  const APP_TRANSLATION_LOOKUP = (() => {
    const lookup = new Map();
    Object.entries(APP_LANGUAGE_TRANSLATIONS.en).forEach(([key, value]) => lookup.set(value, key));
    Object.values(APP_LANGUAGE_TRANSLATIONS).forEach((translations) => {
      Object.entries(translations).forEach(([key, value]) => lookup.set(value, key));
    });
    return lookup;
  })();

  function normalizeAppLanguage(language) {
    const code = getLanguageCodeFromLocale(language);
    return APP_LANGUAGE_TRANSLATIONS[code] ? code : "en";
  }

  function translateInterfaceText(value, language = getActiveAppLanguage()) {
    const text = String(value == null ? "" : value);
    const trimmed = text.trim().replace(/\s+/g, " ");
    if (!trimmed) return text;
    const key = APP_TRANSLATION_LOOKUP.get(trimmed);
    if (!key) return text;
    const translated = APP_LANGUAGE_TRANSLATIONS[normalizeAppLanguage(language)]?.[key] || APP_LANGUAGE_TRANSLATIONS.en[key] || trimmed;
    return text.replace(trimmed, translated);
  }

  function t(key, fallback = "") {
    return APP_LANGUAGE_TRANSLATIONS[getActiveAppLanguage()]?.[key] || APP_LANGUAGE_TRANSLATIONS.en[key] || fallback || key;
  }

  function formatWelcomeBackTitle(name) {
    const displayName = name || "Chef";
    switch (getActiveAppLanguage()) {
      case "fr":
        return `Bon retour, ${displayName}!`;
      case "zh-Hans":
        return `欢迎回来，${displayName}！`;
      case "ar":
        return `مرحباً بعودتك، ${displayName}!`;
      default:
        return `Welcome back, ${displayName}!`;
    }
  }

  function getActiveAppLanguage() {
    const languagePrefs = normalizeAccessibilityPreferences(state.accessibilityPreferences || {}).language;
    return normalizeAppLanguage(languagePrefs.interfaceLanguage || languagePrefs.interfaceLocale || getLocalizationPreferences().locale || "en-CA");
  }

  function getAppLanguageDirection(language = getActiveAppLanguage()) {
    return normalizeAppLanguage(language) === "ar" ? "rtl" : "ltr";
  }

  function updateAppLanguageMetadata(language = getActiveAppLanguage()) {
    const appLanguage = normalizeAppLanguage(language);
    document.documentElement.lang = appLanguage;
    document.documentElement.dir = getAppLanguageDirection(appLanguage);
    document.documentElement.dataset.appLanguage = appLanguage;
  }

  function shouldSkipInterfaceTranslation(node) {
    const element = node.nodeType === 1 ? node : node.parentElement;
    return !element || Boolean(element.closest("script, style, textarea, input, code, pre, [data-no-translate]"));
  }

  function translateInterfaceTextNodes(root = document.body, language = getActiveAppLanguage()) {
    if (!root || typeof document.createTreeWalker !== "function" || typeof NodeFilter === "undefined") return;
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode(node) {
        if (shouldSkipInterfaceTranslation(node)) return NodeFilter.FILTER_REJECT;
        return APP_TRANSLATION_LOOKUP.has(String(node.nodeValue || "").trim().replace(/\s+/g, " ")) ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_SKIP;
      }
    });
    const nodes = [];
    while (walker.nextNode()) nodes.push(walker.currentNode);
    nodes.forEach((node) => { node.nodeValue = translateInterfaceText(node.nodeValue, language); });
  }

  function translateInterfaceAttributes(root = document.body, language = getActiveAppLanguage()) {
    if (!root || typeof root.querySelectorAll !== "function") return;
    ["placeholder", "aria-label", "title"].forEach((attribute) => {
      $$(`[${attribute}]`, root).forEach((element) => {
        if (element.closest("script, style, code, pre, [data-no-translate]")) return;
        const current = element.getAttribute(attribute);
        const translated = translateInterfaceText(current, language);
        if (translated !== current) element.setAttribute(attribute, translated);
      });
    });
  }

  function applyAppLanguage(language = getActiveAppLanguage(), root = document.body) {
    if (appLanguageTranslationActive) return;
    const appLanguage = normalizeAppLanguage(language);
    appLanguageTranslationActive = true;
    try {
      updateAppLanguageMetadata(appLanguage);
      translateInterfaceTextNodes(root, appLanguage);
      translateInterfaceAttributes(root, appLanguage);
    } finally {
      appLanguageTranslationActive = false;
    }
  }

  function scheduleAppLanguageRefresh() {
    if (appLanguageTranslationQueued || appLanguageTranslationActive) return;
    appLanguageTranslationQueued = true;
    const run = () => {
      appLanguageTranslationQueued = false;
      applyAppLanguage();
    };
    if (typeof window.requestAnimationFrame === "function") window.requestAnimationFrame(run);
    else window.setTimeout(run, 0);
  }

  function startAppLanguageObserver() {
    if (appLanguageTranslationObserver || typeof MutationObserver !== "function" || !document.body) return;
    appLanguageTranslationObserver = new MutationObserver((mutations) => {
      if (appLanguageTranslationActive) return;
      if (mutations.some((mutation) => mutation.type === "childList" || mutation.type === "characterData" || mutation.type === "attributes")) scheduleAppLanguageRefresh();
    });
    appLanguageTranslationObserver.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ["placeholder", "aria-label", "title"] });
  }

  function renderLanguageOptions(selectedLocale, excludedLocales = []) {
    const excluded = new Set(excludedLocales.filter(Boolean));
    const selectedLanguage = getLanguageCodeFromLocale(selectedLocale);
    return getSupportedLanguageChoices()
      .filter((language) => !excluded.has(language.code))
      .map((language) => `<option value="${escapeHtml(language.code)}"${selectedLanguage === language.code ? " selected" : ""}>${escapeHtml(language.label)}</option>`)
      .join("");
  }

  function renderRegionOptions(selectedRegionCode, displayLocale) {
    const selected = normalizeRegionCode(selectedRegionCode);
    const deviceOption = `<option value="device"${selected === "device" ? " selected" : ""}>Use device region</option>`;
    return deviceOption + getSupportedRegions()
      .map((region) => `<option value="${escapeHtml(region.code)}"${selected === region.code ? " selected" : ""}>${escapeHtml(getRegionDisplayLabel(region.code, displayLocale))}</option>`)
      .join("");
  }

  function focusLanguageRegionSettings() {
    window.setTimeout(() => {
      const title = $("#languageRegionSettingsTitle");
      title?.focus();
      title?.scrollIntoView({ block: "start", behavior: "smooth" });
    }, 0);
  }

  function focusAccessibilitySettings() {
    window.setTimeout(() => {
      const title = $("#accessibilitySettingsTitle");
      title?.focus();
      title?.scrollIntoView({ block: "start", behavior: "smooth" });
    }, 0);
  }

  function renderLocalizationPreferencesSection() {
    const prefs = getLocalizationPreferences();
    const languagePrefs = normalizeAccessibilityPreferences(state.accessibilityPreferences || {}).language;
    const regionCode = getActiveRegionCode(prefs, languagePrefs);
    const appLanguage = languagePrefs.interfaceLanguage || getLanguageCodeFromLocale(languagePrefs.interfaceLocale || prefs.locale);
    const appLocale = resolveLocale(appLanguage, regionCode, { fallbackLocale: prefs.locale });
    const explanationLanguage = languagePrefs.explanationLanguage || getLanguageCodeFromLocale(languagePrefs.explanationLocale || appLocale);
    const cookingTermLanguage = languagePrefs.cookingTermLanguage || getLanguageCodeFromLocale(languagePrefs.cookingTermLocale || appLocale);
    const voiceLanguage = languagePrefs.selectedVoiceLanguage || getLanguageCodeFromLocale(languagePrefs.selectedVoiceLocale || appLocale);
    const usesDifferentExplanationLanguage = explanationLanguage !== appLanguage;
    const interfaceOptions = renderLanguageOptions(appLanguage);
    const regionOptions = renderRegionOptions(regionCode, appLocale);
    const explanationOptions = renderLanguageOptions(explanationLanguage);
    const cookingTermOptions = `<option value="${escapeHtml(appLanguage)}"${cookingTermLanguage === appLanguage ? " selected" : ""}>Same as App language</option>${renderLanguageOptions(cookingTermLanguage, [appLanguage])}`;
    const voiceOptions = `<option value="${escapeHtml(appLanguage)}"${voiceLanguage === appLanguage ? " selected" : ""}>Same as App language</option>${renderLanguageOptions(voiceLanguage, [appLanguage])}`;
    const deviceRegionStatus = getDeviceRegionStatusText(regionCode, appLocale);
    const measureOptions = [["metric", "Metric"], ["imperial", "Imperial"], ["recipe-original", "Recipe original"]].map(([value, label]) => `<option value="${value}"${prefs.measurementSystem === value ? " selected" : ""}>${label}</option>`).join("");
    const tempOptions = [["both", "Celsius and Fahrenheit"], ["celsius", "Celsius"], ["fahrenheit", "Fahrenheit"]].map(([value, label]) => `<option value="${value}"${prefs.temperatureDisplay === value ? " selected" : ""}>${label}</option>`).join("");
    const hourOptions = [["12", "12-hour"], ["24", "24-hour"]].map(([value, label]) => `<option value="${value}"${prefs.hourCycle === value ? " selected" : ""}>${label}</option>`).join("");
    return `<section class="profile-section localization-settings" id="languageRegionSettings" aria-labelledby="languageRegionSettingsTitle">
      <div class="nutrition-profile-header">
        <span class="eyebrow">LANGUAGE & REGION</span>
        <h2 id="languageRegionSettingsTitle" tabindex="-1">Language & Region</h2>
        <p>Choose app language, local formats, and measurement preferences.</p>
      </div>
      <form id="localizationPreferencesForm" class="localization-preferences-form" novalidate>
        <input type="hidden" name="preservedExplanationLocale" value="${escapeHtml(explanationLanguage)}">
        <fieldset class="localization-settings-panel localization-language-panel">
          <legend>Language</legend>
          <div class="localization-control-grid">
            <label for="localizationInterfaceLanguage">App language <small id="localizationInterfaceLanguageHelp">Changes Chef Nova menus and buttons.</small><select id="localizationInterfaceLanguage" name="interfaceLocale" aria-describedby="localizationInterfaceLanguageHelp">${interfaceOptions}</select></label>
            <div class="localization-toggle-card">
              <label class="checkbox-field" for="localizationUseExplanationOverride"><input id="localizationUseExplanationOverride" name="useExplanationOverride" type="checkbox"${usesDifferentExplanationLanguage ? " checked" : ""}> Use a different language for recipe explanations</label>
              <p class="field-help">Recipe explanation language: <span id="localizationExplanationSummary">${usesDifferentExplanationLanguage ? escapeHtml(getLanguageOptionLabel(explanationLanguage)) : "Same as App language"}</span></p>
            </div>
            <label class="localization-conditional-field${usesDifferentExplanationLanguage ? "" : " hidden"}" id="localizationExplanationLanguageWrap" for="localizationExplanationLanguage"${usesDifferentExplanationLanguage ? "" : " hidden"}>Recipe explanation language <small id="localizationExplanationLanguageHelp">Changes recipe explanations only.</small><select id="localizationExplanationLanguage" name="explanationLocale" aria-describedby="localizationExplanationLanguageHelp">${explanationOptions}</select></label>
          </div>
          <details class="localization-disclosure">
            <summary>Advanced Language Options</summary>
            <div class="localization-control-grid">
              <label for="localizationCookingTermLanguage">Cooking terms language <small id="localizationCookingTermLanguageHelp">Keeps important cooking words in your preferred language.</small><select id="localizationCookingTermLanguage" name="cookingTermLocale" aria-describedby="localizationCookingTermLanguageHelp">${cookingTermOptions}</select></label>
              <label for="localizationVoiceLanguage">Voice input language <small id="localizationVoiceLanguageHelp">Controls the language Chef Nova listens for during voice entry.</small><select id="localizationVoiceLanguage" name="selectedVoiceLocale" aria-describedby="localizationVoiceLanguageHelp">${voiceOptions}</select></label>
            </div>
          </details>
        </fieldset>
        <fieldset class="localization-settings-panel localization-region-panel">
          <legend>Region & Formats</legend>
          <div class="localization-control-grid">
            <label for="localizationRegionLocale">Region <small id="localizationRegionLocaleHelp">Controls local number, date, time, and formatting conventions.</small><select id="localizationRegionLocale" name="regionCode" aria-describedby="localizationRegionLocaleHelp localizationDeviceRegionStatus">${regionOptions}</select><small id="localizationDeviceRegionStatus">${escapeHtml(deviceRegionStatus)}</small></label>
            <label for="localizationMeasurementSystem">Measurement system <small id="localizationMeasurementSystemHelp">Controls recipe quantity display.</small><select id="localizationMeasurementSystem" name="measurementSystem" aria-describedby="localizationMeasurementSystemHelp">${measureOptions}</select></label>
            <label for="localizationTemperatureDisplay">Temperature display <small id="localizationTemperatureDisplayHelp">Controls how cooking temperatures appear.</small><select id="localizationTemperatureDisplay" name="temperatureDisplay" aria-describedby="localizationTemperatureDisplayHelp">${tempOptions}</select></label>
            <label for="localizationHourCycle">Clock format <small id="localizationHourCycleHelp">Controls how meal times and timers appear.</small><select id="localizationHourCycle" name="hourCycle" aria-describedby="localizationHourCycleHelp">${hourOptions}</select></label>
          </div>
          <details class="localization-disclosure localization-timezone-details">
            <summary>Time zone <span>Automatically detected: ${escapeHtml(prefs.timeZone || getCurrentApplicationTimeZone())}</span></summary>
            <label for="localizationTimeZone">Time zone <small id="localizationTimeZoneHelp">Used for meal scheduling, reminders, and saved times.</small><input id="localizationTimeZone" name="timeZone" type="text" value="${escapeHtml(prefs.timeZone)}" placeholder="America/Toronto" aria-describedby="localizationTimeZoneHelp"></label>
          </details>
        </fieldset>
        <details class="localization-settings-panel localization-preview-panel">
          <summary><span class="summary-closed-label">Show Format Preview</span><span class="summary-open-label">Hide Format Preview</span></summary>
          <div class="localization-preview-copy">
            <h3>Format Preview</h3>
            <p>See how recipes, measurements, dates, and times will appear. Examples do not change saved recipe data.</p>
          </div>
          <div class="localization-preview" id="localizationPreview" aria-live="polite">${renderLocalizationPreview(prefs)}</div>
        </details>
        <div class="settings-error hidden" id="localizationPreferencesError" role="alert" hidden></div>
        <p class="language-recovery-inline"><a href="#account" data-page="account" data-focus-language-settings="true">Language / Langue / 语言 / اللغة</a></p>
        <div class="profile-form-actions"><button class="button primary" type="submit">Save Language Settings</button><button class="button secondary" type="button" data-open-accessibility-feedback data-feedback-category="translation-incorrect">Report an Accessibility or Language Problem</button></div>
      </form>
    </section>`;
  }

  function renderLocalizationPreview(preferences = getLocalizationPreferences()) {
    const prefs = typeof LOCALIZATION.normalizePreferences === "function" ? LOCALIZATION.normalizePreferences(preferences) : preferences;
    const ingredient = typeof LOCALIZATION.formatIngredientQuantity === "function" ? LOCALIZATION.formatIngredientQuantity({ value: "200", unit: "g" }, { id: "spinach", name: "spinach" }, prefs).display : "200 g spinach";
    const soup = typeof LOCALIZATION.formatIngredientQuantity === "function" ? LOCALIZATION.formatIngredientQuantity({ value: "1.5", unit: "L" }, { id: "soup", name: "soup" }, prefs).display : "1.5 L soup";
    const temperature = typeof LOCALIZATION.formatSafetyTemperature === "function" ? LOCALIZATION.formatSafetyTemperature("chickenInternal", prefs).display : "Heat to at least 74°C / 165°F.";
    const date = typeof LOCALIZATION.formatDate === "function" ? LOCALIZATION.formatDate("2026-08-18", prefs) : "August 18, 2026";
    const time = typeof LOCALIZATION.formatTime === "function" ? LOCALIZATION.formatTime("2026-08-18T18:30:00-04:00", prefs) : "6:30 p.m.";
    return `<div><span>Ingredient Quantity</span><strong><bdi>${escapeHtml(ingredient)}</bdi></strong></div>
      <div><span>Decimal & Volume</span><strong><bdi>${escapeHtml(soup)}</bdi></strong></div>
      <div><span>Safety Temperature</span><strong>${escapeHtml(temperature)}</strong></div>
      <div><span>Date & Time</span><strong>${escapeHtml(date)} at ${escapeHtml(time)}</strong></div>`;
  }

  function readLocalizationPreferencesForm() {
    const form = $("#localizationPreferencesForm");
    if (!form) return getLocalizationPreferences();
    const accessibilityPrefs = normalizeAccessibilityPreferences(state.accessibilityPreferences || {});
    const useExplanationOverride = Boolean(form.useExplanationOverride?.checked);
    const currentPrefs = getLocalizationPreferences();
    const interfaceLanguage = getLanguageCodeFromLocale(form.interfaceLocale.value);
    const regionCode = normalizeRegionCode(form.regionCode.value, currentPrefs.locale);
    const locale = resolveLocale(interfaceLanguage, regionCode, { fallbackLocale: currentPrefs.locale });
    const explanationLanguage = useExplanationOverride ? getLanguageCodeFromLocale(form.explanationLocale.value) : getLanguageCodeFromLocale(form.preservedExplanationLocale?.value || accessibilityPrefs.language.explanationLocale || interfaceLanguage);
    const cookingTermLanguage = getLanguageCodeFromLocale(form.cookingTermLocale.value);
    const selectedVoiceLanguage = getLanguageCodeFromLocale(form.selectedVoiceLocale.value);
    return {
      interfaceLanguage,
      regionCode,
      interfaceLocale: locale,
      locale,
      explanationLanguage,
      explanationLocale: resolveLocale(explanationLanguage, regionCode, { fallbackLocale: currentPrefs.locale }),
      cookingTermLanguage,
      cookingTermLocale: resolveLocale(cookingTermLanguage, regionCode, { fallbackLocale: currentPrefs.locale }),
      selectedVoiceLanguage,
      selectedVoiceLocale: resolveLocale(selectedVoiceLanguage, regionCode, { fallbackLocale: currentPrefs.locale }),
      measurementSystem: form.measurementSystem.value,
      temperatureDisplay: form.temperatureDisplay.value,
      hourCycle: form.hourCycle.value,
      timeZone: form.timeZone.value.trim() || getCurrentApplicationTimeZone()
    };
  }

  function syncLocalizationSettingsVisibility() {
    const form = $("#localizationPreferencesForm");
    if (!form) return;
    const useExplanationOverride = Boolean(form.useExplanationOverride?.checked);
    const explanationWrap = $("#localizationExplanationLanguageWrap");
    if (explanationWrap) {
      explanationWrap.classList.toggle("hidden", !useExplanationOverride);
      explanationWrap.hidden = !useExplanationOverride;
    }
    const summary = $("#localizationExplanationSummary");
    if (summary) summary.textContent = useExplanationOverride ? getLanguageOptionLabel(form.explanationLocale?.value || form.preservedExplanationLocale?.value || form.interfaceLocale.value) : "Same as App language";
    const regionStatus = $("#localizationDeviceRegionStatus");
    if (regionStatus) {
      const appLanguage = getLanguageCodeFromLocale(form.interfaceLocale?.value);
      const regionCode = normalizeRegionCode(form.regionCode?.value);
      regionStatus.textContent = getDeviceRegionStatusText(regionCode, resolveLocale(appLanguage, regionCode));
    }
  }

  function updateLocalizationPreview() {
    syncLocalizationSettingsVisibility();
    const target = $("#localizationPreview");
    if (target) target.innerHTML = renderLocalizationPreview(readLocalizationPreferencesForm());
  }

  function saveLocalizationPreferencesFromForm(event) {
    event?.preventDefault();
    const error = $("#localizationPreferencesError");
    const draft = readLocalizationPreferencesForm();
    const validTimeZone = (() => {
      try { new Intl.DateTimeFormat("en-CA", { timeZone: draft.timeZone }).format(new Date()); return true; }
      catch (_) { return false; }
    })();
    if (!validTimeZone) {
      if (error) {
        error.hidden = false;
        error.classList.remove("hidden");
        error.innerHTML = `<h3>Language settings could not be saved</h3><p>Your previous settings are still active. Enter a valid time zone, such as America/Toronto.</p>`;
      }
      $("#localizationTimeZone")?.closest("details")?.setAttribute("open", "");
      $("#localizationTimeZone")?.focus();
      return false;
    }
    if (error) {
      error.textContent = "";
      error.hidden = true;
      error.classList.add("hidden");
    }
    const accessibilityPrefs = normalizeAccessibilityPreferences(state.accessibilityPreferences || {});
    const previousInterfaceLocale = accessibilityPrefs.language.interfaceLocale || getLocalizationPreferences().locale;
    saveLocalizationPreferences({ ...getLocalizationPreferences(), ...draft, locale: draft.locale });
    state.accessibilityPreferences = {
      ...accessibilityPrefs,
      language: {
        ...accessibilityPrefs.language,
        interfaceLanguage: draft.interfaceLanguage,
        interfaceLocale: draft.interfaceLocale,
        regionCode: draft.regionCode,
        explanationLanguage: draft.explanationLanguage,
        explanationLocale: draft.explanationLocale,
        cookingTermLanguage: draft.cookingTermLanguage,
        cookingTermLocale: draft.cookingTermLocale,
        measurementLocale: draft.locale,
        selectedVoiceLanguage: draft.selectedVoiceLanguage,
        selectedVoiceLocale: draft.selectedVoiceLocale
      }
    };
    persistAccessibilityPreferences();
    if (draft.interfaceLocale !== previousInterfaceLocale || draft.interfaceLanguage !== getLanguageCodeFromLocale(previousInterfaceLocale)) changeInterfaceLanguage(draft.interfaceLocale);
    else applyAppLanguage(draft.interfaceLanguage);
    displayPantry();
    displayMealPlanner();
    displayShoppingList();
    renderAccountPage();
    showToast(t("languageUpdated", "Language settings updated."), "success");
    return true;
  }

  function normalizeLowBandwidthPreferences(value) {
    return typeof RESILIENCE.normalizeLowBandwidthPreferences === "function"
      ? RESILIENCE.normalizeLowBandwidthPreferences(value)
      : { enabled: false, textFirst: true, autoplayVideo: false, preferTranscript: true, imageQuality: "small", suggestOfflineDownload: true, preloadAudio: false, preloadVideo: false, avoidBackgroundRequests: true, ...(value || {}) };
  }

  function normalizeOfflineCookingPreferences(value) {
    return typeof RESILIENCE.normalizeOfflineCookingPreferences === "function"
      ? RESILIENCE.normalizeOfflineCookingPreferences(value)
      : { autoSaveProgress: true, suggestDownloadBeforeCooking: true, includeTranscriptsByDefault: true, includeSmallImagesByDefault: false, includeAudioByDefault: false, includeVideoByDefault: false, downloadOnlyOnWifi: false, showStorageUsed: true, keepOriginalTextWithTranslations: true, useDeviceTtsWhenAudioFails: true, showKeyboardShortcuts: true, announceConnectivityChanges: true, retrySyncAutomatically: true, ...(value || {}) };
  }

  function getOfflinePreferenceStorageConfig(name) {
    const suffix = name === "offlineCooking" ? "OfflineCookingPreferences" : "LowBandwidthPreferences";
    if (state.guestMode || isGuestMode()) return { storage: sessionStorage, key: `chefNovaGuest${suffix}` };
    const user = getCurrentUser();
    return user ? { storage: localStorage, key: `chefNova${suffix}_${user.id}` } : { storage: localStorage, key: `chefNova${suffix}` };
  }

  function readOfflinePreference(name, fallback) {
    const config = getOfflinePreferenceStorageConfig(name);
    try {
      const value = config.storage.getItem(config.key);
      return value ? JSON.parse(value) : fallback;
    } catch (_) {
      return fallback;
    }
  }

  function writeOfflinePreference(name, value) {
    const config = getOfflinePreferenceStorageConfig(name);
    config.storage.setItem(config.key, JSON.stringify(value));
  }

  function loadOfflineResiliencePreferences() {
    state.lowBandwidthPreferences = normalizeLowBandwidthPreferences(readOfflinePreference("lowBandwidth", {}));
    state.offlineCookingPreferences = normalizeOfflineCookingPreferences(readOfflinePreference("offlineCooking", {}));
    document.body.classList.toggle("low-bandwidth-mode", Boolean(state.lowBandwidthPreferences.enabled));
  }

  async function initializeOfflineResilience() {
    loadOfflineResiliencePreferences();
    if (typeof RESILIENCE.createOfflineRecipeRepository === "function") {
      offlineRecipeRepository = RESILIENCE.createOfflineRecipeRepository();
    }
    if (typeof RESILIENCE.createSyncQueue === "function") offlineSyncQueue = RESILIENCE.createSyncQueue();
    await refreshOfflinePackages();
    registerServiceWorker();
    updateConnectivityStatus();
    window.addEventListener("online", () => updateConnectivityStatus({ announce: true }));
    window.addEventListener("offline", () => updateConnectivityStatus({ announce: true }));
    navigator.connection?.addEventListener?.("change", () => updateConnectivityStatus({ announce: true }));
  }

  function registerServiceWorker() {
    if (location.protocol === "file:" || !navigator.serviceWorker) return;
    navigator.serviceWorker.register("service-worker.js").catch(() => {
      state.featureAvailability.serviceWorker = { state: "failed" };
    });
  }

  async function refreshOfflinePackages() {
    if (!offlineRecipeRepository) {
      state.offlinePackages = [];
      return [];
    }
    try {
      state.offlinePackages = await offlineRecipeRepository.listPackages();
      return state.offlinePackages;
    } catch (_) {
      state.offlinePackages = [];
      return [];
    }
  }

  function ensureConnectivityStatusRegion() {
    let target = $("#offlineStatusBanner");
    if (target) return target;
    target = document.createElement("div");
    target.id = "offlineStatusBanner";
    target.className = "offline-status-banner";
    target.setAttribute("role", "status");
    target.setAttribute("aria-live", "polite");
    $("#chefNovaApp")?.prepend(target);
    return target;
  }

  function updateConnectivityStatus(options = {}) {
    state.networkState = typeof RESILIENCE.getNetworkState === "function" ? RESILIENCE.getNetworkState() : { status: navigator.onLine === false ? "offline" : "online" };
    const status = state.networkState.status || "unknown";
    const target = ensureConnectivityStatusRegion();
    const messages = {
      offline: "Offline mode. Saved recipes, text instructions, pantry, planner, and shopping list stay available on this device.",
      unstable: "Low-bandwidth mode suggested. Chef Nova will prefer text and cached content.",
      online: "Online. Offline cooking backups remain saved on this device.",
      unknown: "Connection status unknown. Core cooking tools remain available."
    };
    target.className = `offline-status-banner ${status === "online" ? "is-online" : "is-visible"} ${status}`;
    target.textContent = messages[status] || messages.unknown;
    if (options.announce && state.offlineCookingPreferences?.announceConnectivityChanges && lastConnectivityAnnouncement !== status) {
      lastConnectivityAnnouncement = status;
      announcePolite(target.textContent);
    }
  }

  function getOfflinePackageForRecipe(recipeId) {
    return (state.offlinePackages || []).find((pack) => pack.recipeId === recipeId) || null;
  }

  async function queueOfflineSyncOperation(entityType, entityId, operation, payload = {}) {
    if (!offlineSyncQueue) return null;
    return offlineSyncQueue.enqueue({ entityType, entityId, operation, payload });
  }

  async function downloadRecipeForOffline(recipeId) {
    if (!offlineRecipeRepository || typeof RESILIENCE.createOfflineRecipePackage !== "function") {
      showToast("Offline recipe storage is not supported in this browser.", "warning");
      return;
    }
    const recipe = state.recipes.map(normalizeRecipe).find((item) => item.id === recipeId);
    if (!recipe) return showToast("Recipe not found", "error");
    const readiness = evaluateRecipePublicationReadiness(recipe, [getLocalizationPreferences().locale || "en-CA"]);
    const legacySnapshot = getRecipePublishedSnapshotStatus(recipe);
    if (!readiness.publishable && !legacySnapshot.legacyPublished) {
      showToast("This recipe cannot be downloaded until its content review is complete.", "warning");
      renderAccountPage();
      return;
    }
    const packageOptions = {
      explanationLocale: getLocalizationPreferences().locale,
      includeSmallImages: state.offlineCookingPreferences?.includeSmallImagesByDefault,
      includeAudio: state.offlineCookingPreferences?.includeAudioByDefault && !state.lowBandwidthPreferences?.enabled,
      includeVideo: state.offlineCookingPreferences?.includeVideoByDefault && !state.lowBandwidthPreferences?.enabled
    };
    const recipePackage = RESILIENCE.createOfflineRecipePackage(recipe, packageOptions);
    const result = await offlineRecipeRepository.savePackage(recipePackage);
    await refreshOfflinePackages();
    displayRecipeDetailsIfOpen(recipe.id);
    displayFavoritesPage();
    searchRecipes();
    await queueOfflineSyncOperation("offline-recipe", recipe.id, "save-package", { recipeVersion: recipePackage.recipeVersion });
    showToast(result.ok ? `${recipe.name} is available offline.` : "Offline package was incomplete. Existing download was kept if available.", result.ok ? "success" : "warning");
  }

  async function removeOfflineRecipe(recipeId) {
    if (!offlineRecipeRepository) return;
    await offlineRecipeRepository.removePackage(recipeId);
    await refreshOfflinePackages();
    renderAccountPage();
    displayRecipeDetailsIfOpen(recipeId);
    searchRecipes();
    showToast("Offline recipe removed.", "success");
  }

  function formatStorageEstimate(bytes = 0) {
    if (!bytes) return "Text only";
    if (bytes < 1000000) return `${Math.max(1, Math.round(bytes / 1000))} KB`;
    return `${(bytes / 1000000).toFixed(1)} MB`;
  }

  function renderOfflineRecipeControls(recipe) {
    const pack = getOfflinePackageForRecipe(recipe.id);
    if (!pack) return `<section class="offline-recipe-panel" aria-label="Offline cooking"><div><h3>Offline Cooking Backup</h3><p>Download a text-first package for cooking without a connection.</p></div><div class="offline-recipe-actions"><button class="button secondary small" type="button" data-offline-download="${escapeHtml(recipe.id)}">Download Offline</button><button class="button secondary small" type="button" data-open-accessibility-feedback data-feedback-category="captions-or-transcript-missing">Report an Accessibility or Language Problem</button></div></section>`;
    return `<section class="offline-recipe-panel available" aria-label="Offline cooking">
      <div><h3>Offline Cooking Backup</h3><p>Available on this device. Includes text steps, ingredients, warnings, transcript, timers, and progress.</p><small>Status: ${escapeHtml(pack.status)} · ${escapeHtml(formatStorageEstimate(pack.storageEstimateBytes))}</small></div>
      <div class="offline-recipe-actions"><button class="button secondary small" type="button" data-offline-download="${escapeHtml(recipe.id)}">Update Download</button><button class="button secondary small remove-shopping-button" type="button" data-offline-remove="${escapeHtml(recipe.id)}">Remove</button></div>
    </section>
    ${renderOfflineCookingProgressPanel(recipe, pack)}`;
  }

  function renderOfflineCookingProgressPanel(recipe, pack = getOfflinePackageForRecipe(recipe.id)) {
    const steps = pack?.recipeSnapshot?.steps || recipe.steps.map((step, index) => ({ stepId: `step-${index + 1}`, sourceText: step, index }));
    const currentIndex = Math.min(Math.max(Number(pack?.progress?.currentStepIndex) || 0, 0), Math.max(steps.length - 1, 0));
    const currentStep = steps[currentIndex] || { sourceText: "No instruction available." };
    const completed = new Set(pack?.progress?.completedStepIds || []);
    const activeTimer = (pack?.progress?.activeTimers || []).find((timer) => timer.stepId === currentStep.stepId);
    const timerText = typeof RESILIENCE.getTimerPresentation === "function" && activeTimer ? RESILIENCE.getTimerPresentation(activeTimer) : "No active timer.";
    return `<section class="offline-step-panel" aria-label="Offline step controls">
      <div class="offline-step-status"><span>Step ${currentIndex + 1} of ${steps.length}</span><strong>${completed.has(currentStep.stepId) ? "Complete" : "In progress"}</strong></div>
      <p id="offlineCurrentStepText">${escapeHtml(currentStep.sourceText)}</p>
      <div class="offline-step-actions">
        <button class="button secondary small" type="button" data-offline-step-prev="${escapeHtml(recipe.id)}">Previous step</button>
        <button class="button primary small" type="button" data-offline-step-complete="${escapeHtml(recipe.id)}">Mark step complete</button>
        <button class="button secondary small" type="button" data-offline-step-next="${escapeHtml(recipe.id)}">Next step</button>
        <button class="button secondary small" type="button" data-offline-timer-start="${escapeHtml(recipe.id)}">Start timer</button>
      </div>
      <div class="offline-timer-panel" role="status">${escapeHtml(timerText)}</div>
    </section>`;
  }

  async function updateOfflineCookingProgress(recipeId, updater) {
    const pack = getOfflinePackageForRecipe(recipeId);
    if (!pack || !offlineRecipeRepository) return showToast("Download this recipe for offline step tracking.", "info");
    const nextProgress = typeof updater === "function" ? updater(pack.progress || {}, pack) : updater;
    await offlineRecipeRepository.updateProgress(recipeId, nextProgress);
    await refreshOfflinePackages();
    await queueOfflineSyncOperation("offline-progress", recipeId, "save-progress", nextProgress);
    displayRecipeDetailsIfOpen(recipeId);
  }

  async function moveOfflineRecipeStep(recipeId, direction) {
    await updateOfflineCookingProgress(recipeId, (progress, pack) => {
      const count = pack.recipeSnapshot?.steps?.length || 1;
      return { ...progress, currentStepIndex: Math.min(Math.max((Number(progress.currentStepIndex) || 0) + direction, 0), count - 1) };
    });
  }

  async function completeOfflineRecipeStep(recipeId) {
    await updateOfflineCookingProgress(recipeId, (progress, pack) => {
      const steps = pack.recipeSnapshot?.steps || [];
      const currentIndex = Math.min(Math.max(Number(progress.currentStepIndex) || 0, 0), Math.max(steps.length - 1, 0));
      const currentStep = steps[currentIndex];
      const completed = Array.from(new Set([...(progress.completedStepIds || []), currentStep?.stepId].filter(Boolean)));
      return { ...progress, completedStepIds: completed };
    });
    showToast("Step saved for offline cooking.", "success");
  }

  async function startOfflineRecipeTimer(recipeId) {
    const pack = getOfflinePackageForRecipe(recipeId);
    if (!pack || typeof RESILIENCE.createOfflineTimer !== "function") return showToast("Download this recipe for offline timers.", "info");
    const steps = pack.recipeSnapshot?.steps || [];
    const step = steps[Number(pack.progress?.currentStepIndex) || 0] || steps[0];
    const definition = (pack.recipeSnapshot?.timerDefinitions || []).find((timer) => timer.stepId === step?.stepId);
    const timer = RESILIENCE.createOfflineTimer({ timerId: definition?.timerId || `${recipeId}::${step?.stepId || "step"}::timer`, recipeId, stepId: step?.stepId || "step-1", label: definition?.label || "Step timer", durationMs: definition?.durationMs || 300000 });
    await updateOfflineCookingProgress(recipeId, (progress) => ({ ...progress, activeTimers: [timer] }));
    showToast("Offline timer started.", "success");
  }

  function showFeatureFallback(regionSelector, feature, failureState, context = {}) {
    const target = $(regionSelector);
    if (!target || typeof RESILIENCE.fallbackCopy !== "function" || typeof RESILIENCE.renderFeatureFallback !== "function") return;
    const model = RESILIENCE.fallbackCopy(feature, failureState, context);
    target.innerHTML = RESILIENCE.renderFeatureFallback(model);
    target.insertAdjacentHTML("beforeend", `<button class="button secondary small" type="button" data-open-accessibility-feedback data-feedback-category="${feature === (RESILIENCE.ENHANCED_FEATURES?.TRANSLATION || "translation") ? "translation-incorrect" : feature === (RESILIENCE.ENHANCED_FEATURES?.SPEECH_RECOGNITION || "speech-recognition") ? "voice-control-misunderstood" : "captions-or-transcript-missing"}">Report an Accessibility or Language Problem</button>`);
  }

  function getVoiceAccountId() {
    const user = getCurrentUser?.();
    if (user?.id) return user.id;
    return state.guestMode || isGuestMode() ? "guest" : "anonymous";
  }

  function getVoiceAuthSessionId() {
    if (state.guestMode || isGuestMode()) return readGuestSession()?.sessionId || "guest-session";
    return readCurrentUserSession()?.id || "anonymous-session";
  }

  function createVoiceCallbackContext(session = state.voiceSession) {
    return {
      sessionId: session?.id || "",
      sessionEpoch: session?.sessionEpoch || 0,
      accountId: getVoiceAccountId(),
      authenticationSessionId: getVoiceAuthSessionId()
    };
  }

  function renderMicrophoneFallback(reason = "not-supported", detail = "") {
    const target = $("#pantryVoiceFallbackRegion");
    if (!target) return;
    const html = typeof VOICE_SAFETY.renderMicrophoneFallback === "function"
      ? VOICE_SAFETY.renderMicrophoneFallback({ detail, showPermissionHelp: reason === "permission-denied" || reason === "permission-revoked" })
      : `<section class="microphone-fallback-panel" role="alert" tabindex="-1"><h3>MICROPHONE ACCESS IS NOT AVAILABLE</h3><p>You can continue with keyboard controls or the labelled form.</p><div class="microphone-fallback-actions"><button class="button primary small" type="button" data-voice-keyboard-controls="pantry-form">Use Keyboard Controls</button><button class="button secondary small" type="button" data-voice-open-form="pantry-form">Open Pantry Form</button></div></section>`;
    target.innerHTML = html;
    target.querySelector("[data-microphone-fallback]")?.focus?.();
    announce("Microphone access is not available. Use keyboard controls or the Pantry form.");
  }

  function renderVoiceListeningPanel() {
    const target = $("#pantryVoiceFallbackRegion");
    if (!target || !state.voiceSession) return;
    target.innerHTML = typeof VOICE_SAFETY.renderListeningIndicator === "function"
      ? VOICE_SAFETY.renderListeningIndicator(state.voiceSession)
      : `<section class="microphone-listening-panel" role="status"><h3>LISTENING FOR PANTRY ENTRY</h3><p>Microphone is active.</p><button class="button secondary small" type="button" data-stop-voice-entry>Stop Listening</button></section>`;
  }

  function stopActiveVoiceSession(reason = "user-cancelled", options = {}) {
    state.voiceSessionEpoch += 1;
    try { activeSpeechRecognizer?.abort?.(); } catch (_) {}
    try { activeSpeechRecognizer?.stop?.(); } catch (_) {}
    activeSpeechRecognizer = null;
    const result = typeof VOICE_SAFETY.stopVoiceSession === "function"
      ? VOICE_SAFETY.stopVoiceSession(state.voiceSession, { reason, stream: activeVoiceMediaStream, preserveEditableText: options.preserveEditableText })
      : { session: null, event: null };
    activeVoiceMediaStream = null;
    state.voiceSession = result.session || null;
    if (result.event) state.voicePrivacyEvents = [...state.voicePrivacyEvents, result.event].slice(-20);
    if (!options.keepDraft) state.voiceInterpretationDraft = null;
    if (!options.keepRegion) $("#pantryVoiceFallbackRegion")?.replaceChildren();
    return result;
  }

  function cancelVoiceForAccountBoundary(reason = VOICE_SAFETY.FAILURE_REASONS?.ACCOUNT_CHANGED || "account-changed") {
    state.pendingSensitiveVoiceAction = null;
    state.voiceInterpretationDraft = null;
    return stopActiveVoiceSession(reason, { keepRegion: true });
  }

  function renderPantryVoiceReview(draft) {
    const target = $("#pantryVoiceFallbackRegion");
    if (!target || !draft) return;
    const needsCanSize = draft.canSizeStatus === "confirmation-required";
    target.innerHTML = `<section class="voice-pantry-review" role="region" aria-labelledby="voicePantryReviewTitle" tabindex="-1" data-voice-pantry-review>
      <div>
        <span class="eyebrow">REVIEW PANTRY ENTRY</span>
        <h3 id="voicePantryReviewTitle">Confirm before saving</h3>
        <p>Voice text is not saved until you review it.</p>
      </div>
      <div class="voice-review-grid">
        <label>Ingredient<input name="voiceIngredientName" value="${escapeAttr(draft.ingredientName || "")}" autocomplete="off"></label>
        <label>Quantity<input name="voiceQuantity" type="number" min="1" step="1" value="${escapeAttr(draft.quantity || "")}"></label>
        <label>Container<input name="voiceContainerType" value="${escapeAttr(draft.containerType || "")}" autocomplete="off"></label>
        <label>Can size ${needsCanSize ? "<small>Required for cans.</small>" : ""}<input name="voiceCanSize" value="${escapeAttr(draft.canSize || "")}" placeholder="398 ml" autocomplete="off"></label>
      </div>
      <p class="form-message" id="voicePantryReviewMessage" aria-live="polite">${needsCanSize ? "Enter can size before saving canned items." : ""}</p>
      <div class="voice-review-actions">
        <button class="button primary small" type="button" data-save-voice-pantry-draft>Save to Pantry Form</button>
        <button class="button secondary small" type="button" data-cancel-voice-pantry-draft>Cancel</button>
      </div>
    </section>`;
    target.querySelector("[data-voice-pantry-review]")?.focus?.();
  }

  function readVoiceDraftReview() {
    const panel = $("[data-voice-pantry-review]");
    const draft = state.voiceInterpretationDraft || {};
    return {
      ...draft,
      ingredientName: panel?.querySelector("[name='voiceIngredientName']")?.value.trim() || "",
      quantity: Number(panel?.querySelector("[name='voiceQuantity']")?.value),
      containerType: panel?.querySelector("[name='voiceContainerType']")?.value.trim() || "",
      canSize: panel?.querySelector("[name='voiceCanSize']")?.value.trim() || ""
    };
  }

  function saveVoicePantryDraft() {
    const draft = readVoiceDraftReview();
    const message = $("#voicePantryReviewMessage");
    if (!draft.ingredientName || !Number.isInteger(draft.quantity) || draft.quantity < 1) {
      if (message) message.textContent = "Enter an ingredient and quantity before saving.";
      return;
    }
    if (draft.containerType === "cans" && !draft.canSize) {
      if (message) message.textContent = "Enter can size before saving canned items.";
      return;
    }
    $("#showPantryForm")?.click();
    const form = $("#pantryForm");
    if (!form) return;
    const finalName = draft.canSize ? `${draft.ingredientName} (${draft.canSize} ${draft.containerType || "can"})` : draft.ingredientName;
    form.elements.name.value = finalName;
    form.elements.quantity.value = String(draft.quantity);
    if (form.elements.unit) form.elements.unit.value = draft.containerType === "cans" ? "can" : "each";
    if (form.elements.category) form.elements.category.value = "Other";
    state.voiceInterpretationDraft = { ...draft, status: "user-confirmed", persisted: false, finalRecognizedText: "" };
    stopActiveVoiceSession("draft-confirmed", { keepRegion: true, keepDraft: true });
    $("#pantryVoiceFallbackRegion").innerHTML = `<p class="feature-inline-status microphone-off-status" role="status">Voice entry reviewed. Finish the Pantry form to save.</p>`;
    form.elements.name.focus();
  }

  function cancelVoicePantryDraft() {
    state.voiceInterpretationDraft = null;
    stopActiveVoiceSession("draft-cancelled");
    announce("Voice Pantry draft cancelled.");
  }

  function startVoicePantryEntry() {
    const speechEvaluation = evaluateRolloutFlag("pantry.speech-entry");
    const privacyEvaluation = evaluateRolloutFlag("privacy.microphone-controls");
    if (!speechEvaluation.enabled || !privacyEvaluation.enabled) {
      stopActiveVoiceSession("rollout-disabled", { keepRegion: true });
      renderMicrophoneFallback(speechEvaluation.reason || privacyEvaluation.reason || "feature-disabled", "Voice Pantry Entry is temporarily unavailable. The labelled Pantry form is still available.");
      recordRolloutHealthEvent({ event: "feature-fallback-used", featureFlagKey: "pantry.speech-entry", rolloutStage: "stage-2-independent-cooking", outcome: "fallback", errorCategory: speechEvaluation.reason || privacyEvaluation.reason || "feature-disabled" });
      return;
    }
    recordRolloutHealthEvent({ event: "feature-exposed", featureFlagKey: "pantry.speech-entry", rolloutStage: "stage-2-independent-cooking", outcome: "success" });
    const feature = RESILIENCE.ENHANCED_FEATURES?.SPEECH_RECOGNITION || "speech-recognition";
    const states = RESILIENCE.FEATURE_AVAILABILITY_STATES || {};
    const availability = typeof RESILIENCE.detectFeatureAvailability === "function" ? RESILIENCE.detectFeatureAvailability(feature) : { state: "unsupported" };
    state.featureAvailability.speechRecognition = availability;
    if (availability.state !== (states.AVAILABLE || "available")) {
      renderMicrophoneFallback(availability.state || "not-supported", "Speech recognition is unavailable in this browser or context.");
      return;
    }
    try {
      window.speechSynthesis?.cancel?.();
      stopActiveVoiceSession("new-session", { keepRegion: true });
      const sessionEpoch = state.voiceSessionEpoch + 1;
      const created = typeof VOICE_SAFETY.createVoiceSession === "function"
        ? VOICE_SAFETY.createVoiceSession({ userActivated: true, purpose: "pantry-entry", accountId: getVoiceAccountId(), authenticationSessionId: getVoiceAuthSessionId(), sessionEpoch, recognitionLanguage: getLocalizationPreferences().locale || "en-CA" })
        : { ok: true, session: { id: `voice-${Date.now()}`, sessionEpoch, accountId: getVoiceAccountId(), authenticationSessionId: getVoiceAuthSessionId(), purpose: "pantry-entry", recognitionLanguage: getLocalizationPreferences().locale || "en-CA", state: "ready" } };
      if (!created.ok) return renderMicrophoneFallback("not-supported", "Start voice entry from the Pantry button.");
      state.voiceSessionEpoch = sessionEpoch;
      state.voiceSession = { ...created.session, state: VOICE_SAFETY.MICROPHONE_STATES?.LISTENING || "listening" };
      state.voiceInterpretationDraft = null;
      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      activeSpeechRecognizer = new SpeechRecognition();
      activeSpeechRecognizer.lang = getLocalizationPreferences().locale || "en-CA";
      activeSpeechRecognizer.interimResults = true;
      activeSpeechRecognizer.onresult = (event) => {
        const transcript = Array.from(event.results).map((result) => result[0]?.transcript || "").join(" ").trim();
        const finalTranscript = Array.from(event.results).filter((result) => result.isFinal).map((result) => result[0]?.transcript || "").join(" ").trim();
        const callbackContext = createVoiceCallbackContext();
        const updated = typeof VOICE_SAFETY.updateSessionTranscript === "function"
          ? VOICE_SAFETY.updateSessionTranscript(state.voiceSession, { ...callbackContext, partialTranscript: transcript, finalTranscript })
          : { ok: true, session: { ...state.voiceSession, partialTranscript: transcript, unconfirmedTranscript: finalTranscript } };
        if (!updated.ok) return;
        state.voiceSession = updated.session;
        if (finalTranscript) {
          const draft = typeof VOICE_SAFETY.parseSpeechPantryEntry === "function" ? VOICE_SAFETY.parseSpeechPantryEntry(finalTranscript) : { ingredientName: finalTranscript, quantity: null, containerType: "", canSize: "", canSizeStatus: "not-applicable" };
          state.voiceInterpretationDraft = { ...draft, accountId: getVoiceAccountId(), voiceSessionId: state.voiceSession?.id || "" };
          renderPantryVoiceReview(state.voiceInterpretationDraft);
        } else {
          renderVoiceListeningPanel();
        }
      };
      activeSpeechRecognizer.onerror = (error) => {
        const normalized = typeof VOICE_SAFETY.normalizeMicrophoneError === "function" ? VOICE_SAFETY.normalizeMicrophoneError(error) : { reason: states.FAILED || "failed" };
        stopActiveVoiceSession(normalized.reason, { keepRegion: true });
        renderMicrophoneFallback(normalized.reason, "Voice entry stopped. Use keyboard controls or the Pantry form.");
      };
      activeSpeechRecognizer.onend = () => {
        if (state.voiceSession?.state === (VOICE_SAFETY.MICROPHONE_STATES?.LISTENING || "listening")) stopActiveVoiceSession("recognition-ended", { keepRegion: true });
      };
      activeSpeechRecognizer.start();
      renderVoiceListeningPanel();
      showToast("Voice entry started.", "info");
    } catch (_) {
      stopActiveVoiceSession("unexpected-error", { keepRegion: true });
      renderMicrophoneFallback("unexpected-error", "Voice entry could not start. Use keyboard controls or the Pantry form.");
    }
  }

  function openPantryFormFromFallback() {
    $("#showPantryForm")?.click();
    const nameInput = $("#pantryForm input[name='name']");
    nameInput?.focus();
  }

  function readRecipeDetailAloud(recipeId) {
    const evaluation = evaluateRolloutFlag("cooking.recipe-tts");
    if (!evaluation.enabled) {
      showFeatureFallback("#recipeTtsFallbackRegion", RESILIENCE.ENHANCED_FEATURES?.TEXT_TO_SPEECH || "text-to-speech", RESILIENCE.FEATURE_AVAILABILITY_STATES?.DISABLED_BY_USER || "disabled-by-user");
      recordRolloutHealthEvent({ event: "feature-fallback-used", featureFlagKey: "cooking.recipe-tts", rolloutStage: "stage-2-independent-cooking", outcome: "fallback", errorCategory: evaluation.reason });
      return;
    }
    recordRolloutHealthEvent({ event: "feature-exposed", featureFlagKey: "cooking.recipe-tts", rolloutStage: "stage-2-independent-cooking", outcome: "success" });
    const feature = RESILIENCE.ENHANCED_FEATURES?.TEXT_TO_SPEECH || "text-to-speech";
    const states = RESILIENCE.FEATURE_AVAILABILITY_STATES || {};
    const availability = typeof RESILIENCE.detectFeatureAvailability === "function" ? RESILIENCE.detectFeatureAvailability(feature) : { state: "unsupported" };
    if (availability.state !== (states.AVAILABLE || "available")) return showFeatureFallback("#recipeTtsFallbackRegion", feature, availability.state || "unsupported");
    const text = $("#recipeDetailInstructions")?.textContent?.trim() || $("#recipeDetailModalTitle")?.textContent || "";
    try {
      window.speechSynthesis.cancel();
      window.speechSynthesis.speak(new SpeechSynthesisUtterance(text));
    } catch (_) {
      showFeatureFallback("#recipeTtsFallbackRegion", feature, states.FAILED || "failed");
    }
  }

  function continueWithRecipeText() {
    $("#recipeDetailInstructions")?.focus();
  }

  function showRecipeTranslationFallback(recipeId) {
    const recipe = state.recipes.map(normalizeRecipe).find((item) => item.id === recipeId);
    if (!recipe) return;
    const result = typeof RESILIENCE.resolveTranslationFallback === "function"
      ? RESILIENCE.resolveTranslationFallback({ sourceText: recipe.steps.join("\n"), translations: [], targetLocale: getLocalizationPreferences().locale, recipeVersion: recipe.recipeVersion || recipe.id, online: navigator.onLine !== false })
      : { text: recipe.steps.join("\n"), warning: "The original instructions remain available." };
    showFeatureFallback("#recipeTranslationFallbackRegion", RESILIENCE.ENHANCED_FEATURES?.TRANSLATION || "translation", navigator.onLine === false ? "offline" : "failed");
    const target = $("#recipeTranslationFallbackRegion");
    if (target) target.insertAdjacentHTML("beforeend", `<div class="feature-fallback-text"><h4>Original or cached text</h4>${result.warning ? `<p>${escapeHtml(result.warning)}</p>` : ""}<pre>${escapeHtml(result.text)}</pre></div>`);
  }

  function showRecipeMediaFallback(recipeId) {
    const recipe = state.recipes.map(normalizeRecipe).find((item) => item.id === recipeId);
    if (!recipe) return;
    const result = typeof RESILIENCE.resolveMediaFallback === "function" ? RESILIENCE.resolveMediaFallback({ type: "video", transcript: recipe.steps.join("\n"), text: recipe.steps.join("\n") }) : { text: recipe.steps.join("\n") };
    showFeatureFallback("#recipeMediaFallbackRegion", RESILIENCE.ENHANCED_FEATURES?.VIDEO || "video", navigator.onLine === false ? "offline" : "failed");
    const target = $("#recipeMediaFallbackRegion");
    if (target) target.insertAdjacentHTML("beforeend", `<div class="feature-fallback-text"><h4>Transcript</h4><pre>${escapeHtml(result.text || recipe.steps.join("\n"))}</pre></div>`);
  }

  function renderOfflineSettingsSection() {
    const low = normalizeLowBandwidthPreferences(state.lowBandwidthPreferences);
    const offline = normalizeOfflineCookingPreferences(state.offlineCookingPreferences);
    const packages = state.offlinePackages || [];
    const packageRows = packages.length ? packages.map((pack) => `<article class="offline-download-card">
      <div><h3>${escapeHtml(pack.title)}</h3><p>${escapeHtml(pack.sourceLocale || "en")} ${pack.explanationLocale ? `→ ${escapeHtml(pack.explanationLocale)}` : ""} · ${escapeHtml(pack.status)} · ${escapeHtml(formatStorageEstimate(pack.storageEstimateBytes))}</p><small>Saved ${escapeHtml(formatDate(pack.downloadedAt || pack.updatedAt))}</small></div>
      <button class="button secondary small remove-shopping-button" type="button" data-offline-remove="${escapeHtml(pack.recipeId)}">Remove</button>
    </article>`).join("") : `<p class="empty-helper">No offline recipes yet. Open a recipe and choose Download Offline.</p>`;
    return `<section class="profile-section offline-settings" aria-labelledby="offlineSettingsTitle">
      <div class="nutrition-profile-header">
        <span class="eyebrow">OFFLINE READY</span>
        <h2 id="offlineSettingsTitle">Offline and Low-Bandwidth</h2>
        <p>Keep core cooking tools usable when connection, audio, video, or translation features fail.</p>
      </div>
      <form id="offlinePreferencesForm" class="offline-preferences-form" novalidate>
        <fieldset><legend>Low-bandwidth mode</legend>
          <label class="checkbox-field"><input name="lowEnabled" type="checkbox" ${low.enabled ? "checked" : ""}> Prefer text and cached content</label>
          <label class="checkbox-field"><input name="textFirst" type="checkbox" ${low.textFirst ? "checked" : ""}> Show text first</label>
          <label class="checkbox-field"><input name="preferTranscript" type="checkbox" ${low.preferTranscript ? "checked" : ""}> Prefer transcripts</label>
          <label>Image quality<select name="imageQuality"><option value="none" ${low.imageQuality === "none" ? "selected" : ""}>None</option><option value="small" ${low.imageQuality === "small" ? "selected" : ""}>Small</option><option value="standard" ${low.imageQuality === "standard" ? "selected" : ""}>Standard</option></select></label>
        </fieldset>
        <fieldset><legend>Offline cooking downloads</legend>
          <label class="checkbox-field"><input name="autoSaveProgress" type="checkbox" ${offline.autoSaveProgress ? "checked" : ""}> Auto-save step progress</label>
          <label class="checkbox-field"><input name="suggestDownload" type="checkbox" ${offline.suggestDownloadBeforeCooking ? "checked" : ""}> Suggest downloads before cooking</label>
          <label class="checkbox-field"><input name="includeSmallImages" type="checkbox" ${offline.includeSmallImagesByDefault ? "checked" : ""}> Include small images</label>
          <label class="checkbox-field"><input name="includeAudio" type="checkbox" ${offline.includeAudioByDefault ? "checked" : ""}> Include audio when available</label>
          <label class="checkbox-field"><input name="includeVideo" type="checkbox" ${offline.includeVideoByDefault ? "checked" : ""}> Include video when available</label>
          <label class="checkbox-field"><input name="showKeyboardShortcuts" type="checkbox" ${offline.showKeyboardShortcuts ? "checked" : ""}> Show keyboard shortcuts</label>
        </fieldset>
        <div class="profile-form-actions"><button class="button primary" type="submit">Save Offline Settings</button></div>
      </form>
      <div class="profile-form-actions"><button class="button secondary" type="button" data-open-accessibility-feedback>Report an Accessibility or Language Problem</button></div>
      <div class="offline-downloads-manager" aria-live="polite">
        <div class="section-heading compact"><div><span class="eyebrow">SAVED LOCALLY</span><h3>Offline Downloads</h3></div></div>
        <div class="offline-download-list">${packageRows}</div>
      </div>
    </section>`;
  }

  function saveOfflinePreferencesFromForm(event) {
    event?.preventDefault();
    const form = $("#offlinePreferencesForm");
    if (!form) return false;
    const low = normalizeLowBandwidthPreferences({
      enabled: form.lowEnabled.checked,
      textFirst: form.textFirst.checked,
      preferTranscript: form.preferTranscript.checked,
      imageQuality: form.imageQuality.value,
      autoplayVideo: false,
      preloadAudio: false,
      preloadVideo: false
    });
    const offline = normalizeOfflineCookingPreferences({
      autoSaveProgress: form.autoSaveProgress.checked,
      suggestDownloadBeforeCooking: form.suggestDownload.checked,
      includeSmallImagesByDefault: form.includeSmallImages.checked,
      includeAudioByDefault: form.includeAudio.checked,
      includeVideoByDefault: form.includeVideo.checked,
      showKeyboardShortcuts: form.showKeyboardShortcuts.checked
    });
    writeOfflinePreference("lowBandwidth", low);
    writeOfflinePreference("offlineCooking", offline);
    loadOfflineResiliencePreferences();
    updateConnectivityStatus();
    renderAccountPage();
    showToast("Offline settings saved.", "success");
    return true;
  }

  function renderAccessibilityRecoverySettingsSection() {
    const prefs = normalizeAccessibilityPreferences(state.accessibilityPreferences || {});
    const display = prefs.display;
    const interaction = prefs.interaction;
    return `<section class="profile-section accessibility-settings" id="profileAccessibilitySettings" aria-labelledby="accessibilitySettingsTitle">
      <div class="nutrition-profile-header">
        <span class="eyebrow">ACCESSIBILITY</span>
        <h2 id="accessibilitySettingsTitle" tabindex="-1">Accessibility Settings</h2>
        <p>Adjust reading, display, keyboard, and recovery options.</p>
      </div>
      <form id="accessibilityDisplayForm" class="accessibility-display-form" novalidate>
        <div class="accessibility-help-grid">
          <label for="displayFontScale">Font size<input id="displayFontScale" name="fontScalePercent" type="number" min="75" max="250" step="5" value="${escapeHtml(display.fontScalePercent)}"><span class="field-help">75 to 250 percent.</span></label>
          <label for="displayLineSpacing">Line spacing<select id="displayLineSpacing" name="lineSpacing"><option value="standard" ${display.lineSpacing === "standard" ? "selected" : ""}>Standard</option><option value="comfortable" ${display.lineSpacing === "comfortable" ? "selected" : ""}>Comfortable</option><option value="extra" ${display.lineSpacing === "extra" ? "selected" : ""}>Extra</option></select><span class="field-help">Adds space between lines.</span></label>
          <label for="displayWordSpacing">Word spacing<select id="displayWordSpacing" name="wordSpacing"><option value="standard" ${display.wordSpacing === "standard" ? "selected" : ""}>Standard</option><option value="increased" ${display.wordSpacing === "increased" ? "selected" : ""}>Increased</option></select></label>
          <label for="displayContentWidth">Content width<select id="displayContentWidth" name="contentWidth"><option value="standard" ${display.contentWidth === "standard" ? "selected" : ""}>Standard</option><option value="wide" ${display.contentWidth === "wide" ? "selected" : ""}>Wide</option><option value="narrow" ${display.contentWidth === "narrow" ? "selected" : ""}>Narrow</option></select></label>
          <label for="displayContrast">High contrast<select id="displayContrast" name="highContrastMode"><option value="system" ${display.highContrastMode === "system" ? "selected" : ""}>Use system setting</option><option value="on" ${display.highContrastMode === "on" ? "selected" : ""}>On</option><option value="off" ${display.highContrastMode === "off" ? "selected" : ""}>Off</option></select></label>
          <label for="displayMotion">Reduced motion<select id="displayMotion" name="reducedMotionMode"><option value="system" ${display.reducedMotionMode === "system" ? "selected" : ""}>Use system setting</option><option value="on" ${display.reducedMotionMode === "on" ? "selected" : ""}>On</option><option value="off" ${display.reducedMotionMode === "off" ? "selected" : ""}>Off</option></select></label>
        </div>
        <div class="accessibility-toggle-grid">
          <label class="checkbox-field"><input name="largeButtons" type="checkbox" ${display.largeButtons ? "checked" : ""}> Large buttons</label>
          <label class="checkbox-field"><input name="dyslexiaFriendlyDisplay" type="checkbox" ${display.dyslexiaFriendlyDisplay ? "checked" : ""}> Dyslexia-friendly display</label>
          <label class="checkbox-field"><input name="readingGuide" type="checkbox" ${display.readingGuide ? "checked" : ""}> Reading guide</label>
          <label class="checkbox-field"><input name="focusHighlight" type="checkbox" ${display.focusHighlight === "enhanced" ? "checked" : ""}> Enhanced focus highlight</label>
          <label class="checkbox-field"><input name="oneInstructionAtATime" type="checkbox" ${interaction.oneInstructionAtATime ? "checked" : ""}> One-instruction mode</label>
          <label class="checkbox-field"><input name="keyboardShortcutsEnabled" type="checkbox" ${interaction.keyboardShortcutsEnabled !== false ? "checked" : ""}> Keyboard shortcuts</label>
        </div>
        <details class="contextual-help"><summary>Will restoring display defaults erase my recipes?</summary><p>Restoring display defaults changes only visual settings. Recipes, pantry, allergies, languages, meal plans, shopping lists, timers, and budget information stay unchanged.</p></details>
        <details class="contextual-help"><summary>What happens to my timer when I change languages?</summary><p>Timers keep their original IDs and end times. Only the displayed label may change.</p></details>
        <details class="contextual-help"><summary>Keyboard help</summary><p>Use Tab to move through controls. Alt + Shift + A opens Accessibility Recovery when you are not typing in a form field.</p></details>
        <p class="form-error" id="accessibilityDisplayError" role="alert"></p>
        <div class="profile-form-actions">
          <button class="button primary" type="submit">Preview Reading Settings</button>
          <button class="button secondary" type="button" data-restore-display-defaults>Restore Display Defaults</button>
          <button class="button secondary" id="openAccessibilityRecoveryFromSettings" type="button" data-open-accessibility-recovery>Accessibility Recovery</button>
          <button class="button secondary" type="button" data-open-accessibility-feedback>Report an Accessibility or Language Problem</button>
        </div>
      </form>
      <div id="displayUndoStatus" class="display-undo-status" role="status" aria-live="polite"></div>
      ${renderAccessibilityHelpSection()}
    </section>`;
  }

  function readDisplayForm() {
    const form = $("#accessibilityDisplayForm");
    const current = normalizeAccessibilityPreferences(state.accessibilityPreferences || {}).display;
    if (!form) return current;
    return {
      fontScalePercent: Number(form.fontScalePercent.value),
      lineSpacing: form.lineSpacing.value,
      wordSpacing: form.wordSpacing.value,
      letterSpacing: "standard",
      contentWidth: form.contentWidth.value,
      largeButtons: form.largeButtons.checked,
      highContrastMode: form.highContrastMode.value,
      reducedMotionMode: form.reducedMotionMode.value,
      dyslexiaFriendlyDisplay: form.dyslexiaFriendlyDisplay.checked,
      readingGuide: form.readingGuide.checked,
      focusHighlight: form.focusHighlight.checked ? "enhanced" : "standard"
    };
  }

  function readAccessibilityInteractionForm() {
    const form = $("#accessibilityDisplayForm");
    const current = normalizeAccessibilityPreferences(state.accessibilityPreferences || {}).interaction;
    if (!form) return current;
    return {
      ...current,
      oneInstructionAtATime: form.oneInstructionAtATime.checked,
      keyboardShortcutsEnabled: form.keyboardShortcutsEnabled.checked
    };
  }

  function openDisplayPreview(event) {
    event?.preventDefault();
    const validation = ACCESSIBILITY_RECOVERY.validateDisplayPreferences?.(readDisplayForm(), getSystemDisplayPreferences()) || { valid: true, preferences: readDisplayForm(), issues: [] };
    const error = $("#accessibilityDisplayError");
    if (!validation.valid) {
      if (error) error.textContent = "Review the display settings. Font size must be 75 to 250 percent.";
      $("#displayFontScale")?.focus();
      return false;
    }
    if (error) error.textContent = "";
    const previous = normalizeAccessibilityPreferences(state.accessibilityPreferences || {}).display;
    state.displayPreviewSession = ACCESSIBILITY_RECOVERY.createDisplayPreviewSession?.(previous, validation.preferences, { originElementId: document.activeElement?.id || "accessibilityDisplayForm", originRoute: location.hash }) || { previousSettings: previous, proposedSettings: validation.preferences, status: "previewing" };
    writeAccessibilityStorage("preview", state.displayPreviewSession);
    showDisplayPreviewModal();
    return true;
  }

  function showDisplayPreviewModal() {
    const session = state.displayPreviewSession;
    if (!session) return;
    let modal = $("#displayPreviewModal");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "displayPreviewModal";
      modal.className = "display-preview-backdrop";
      document.body.appendChild(modal);
    }
    const display = normalizeAccessibilityPreferences({ display: session.proposedSettings }).display;
    modal.className = "display-preview-backdrop";
    modal.setAttribute("aria-hidden", "false");
    modal.innerHTML = `<section class="display-preview-modal" role="dialog" aria-modal="true" aria-labelledby="displayPreviewTitle" aria-describedby="displayPreviewDescription">
      <div class="display-preview-toolbar">
        <div><h2 id="displayPreviewTitle" tabindex="-1">Preview Reading Settings</h2><p id="displayPreviewDescription">Check whether these settings are readable before saving.</p></div>
        <div class="display-preview-actions">
          <button class="button primary" type="button" data-display-preview-apply>Apply Settings</button>
          <button class="button secondary" type="button" data-display-preview-continue>Continue Previewing</button>
          <button class="button secondary" type="button" data-display-preview-cancel>Return to Previous Settings</button>
          <button class="button secondary" type="button" data-restore-display-defaults>Restore Display Defaults</button>
        </div>
      </div>
      <div class="display-preview-region" style="--preview-font-scale:${display.fontScalePercent / 100};--preview-line-height:${display.lineSpacing === "extra" ? "1.85" : display.lineSpacing === "comfortable" ? "1.65" : "1.5"};--preview-word-spacing:${display.wordSpacing === "increased" ? "0.16em" : "normal"};">
        <h3>Spinach Mushroom Bowl</h3>
        <p>Representative Chef Nova text for checking readability and spacing.</p>
        <p><b>Recipe step:</b> Cook the mushrooms for 5 minutes, until soft and lightly browned.</p>
        <p><b>Ingredient:</b> 180 g spinach</p>
        <p class="nutrition-safety-message"><b>Safety warning:</b> Keep hot food out of the danger zone and refrigerate leftovers promptly.</p>
        <p class="allergy-warning"><b>Allergy warning:</b> Check labels before cooking.</p>
        <button class="button ${display.largeButtons ? "large-preview-button" : "secondary"}" type="button">Timer control</button>
        <label class="checkbox-field"><input type="checkbox"> Sample checkbox</label>
        <a href="#account">Sample help link</a>
        <p><b>Translated term:</b> saute / faire sauter</p>
      </div>
    </section>`;
    $("#displayPreviewTitle")?.focus();
  }

  function applyDisplayPreview() {
    if (!state.displayPreviewSession) return;
    const result = ACCESSIBILITY_RECOVERY.applyPreviewSession?.(state.accessibilityPreferences, state.displayPreviewSession, "preview");
    state.accessibilityPreferences = result?.preferences || { ...state.accessibilityPreferences, display: state.displayPreviewSession.proposedSettings };
    state.accessibilityPreferences = { ...state.accessibilityPreferences, interaction: readAccessibilityInteractionForm() };
    if (result?.historyEntry) saveDisplayHistoryEntry(result.historyEntry);
    persistAccessibilityPreferences();
    applyAccessibilityDisplayPreferences();
    removeAccessibilityStorage("preview");
    closeDisplayPreviewModal();
    renderAll();
    showDisplayUndoMessage(result?.changeSummary || ["Display settings updated."]);
    announcePolite("Display settings updated.", { key: "display-settings-updated" });
  }

  function cancelDisplayPreview() {
    if (!state.displayPreviewSession) return;
    const result = ACCESSIBILITY_RECOVERY.cancelPreviewSession?.(state.accessibilityPreferences, state.displayPreviewSession);
    state.accessibilityPreferences = result?.preferences || { ...state.accessibilityPreferences, display: state.displayPreviewSession.previousSettings };
    persistAccessibilityPreferences();
    applyAccessibilityDisplayPreferences();
    removeAccessibilityStorage("preview");
    const origin = state.displayPreviewSession.originElementId;
    closeDisplayPreviewModal();
    renderAccountPage();
    if (origin) setTimeout(() => document.getElementById(origin)?.focus(), 0);
    announcePolite("Previous display settings restored.", { key: "display-preview-cancelled" });
  }

  function closeDisplayPreviewModal() {
    const modal = $("#displayPreviewModal");
    if (modal) {
      modal.classList.add("hidden");
      modal.setAttribute("aria-hidden", "true");
      modal.innerHTML = "";
    }
    state.displayPreviewSession = null;
  }

  function restoreDisplayDefaultsFromUI() {
    const description = "This will reset font size, text spacing, contrast, motion, focus highlighting, and button-size preferences. It will not change your recipes, pantry, allergies, dietary restrictions, languages, meal plans, shopping lists, timers, or budget information.";
    if (!confirm(`Restore Display Defaults?\n\n${description}`)) return false;
    const previous = normalizeAccessibilityPreferences(state.accessibilityPreferences || {}).display;
    state.accessibilityPreferences = ACCESSIBILITY_RECOVERY.restoreDisplayDefaults?.(state.accessibilityPreferences, getSystemDisplayPreferences()) || { ...state.accessibilityPreferences, display: createFallbackAccessibilityPreferences().display };
    const entry = ACCESSIBILITY_RECOVERY.createDisplayHistoryEntry?.(previous, state.accessibilityPreferences.display, "restore-defaults");
    if (entry) saveDisplayHistoryEntry(entry);
    persistAccessibilityPreferences();
    applyAccessibilityDisplayPreferences();
    renderAll();
    showDisplayUndoMessage(ACCESSIBILITY_RECOVERY.summarizeDisplayChanges?.(previous, state.accessibilityPreferences.display) || ["Display settings restored."]);
    announcePolite("Display settings restored. Recipes, pantry, languages, meal plans, shopping lists, timers, and budget information were not changed.", { key: "display-settings-restored" });
    return true;
  }

  function showDisplayUndoMessage(lines = []) {
    const target = $("#displayUndoStatus");
    if (!target) return;
    target.innerHTML = `<div class="display-undo-card"><h3>Display Settings Updated</h3>${lines.map((line) => `<p>${escapeHtml(line)}</p>`).join("")}<div><button class="button secondary small" type="button" data-display-undo>Undo</button><button class="button secondary small" type="button" data-display-keep>Keep Settings</button></div></div>`;
  }

  function undoRecentDisplayChange() {
    const result = ACCESSIBILITY_RECOVERY.undoLastDisplayChange?.(state.accessibilityPreferences, state.displayHistory) || { ok: false };
    if (!result.ok) return showToast("No display change to undo.", "info");
    state.accessibilityPreferences = result.preferences;
    state.displayHistory = result.history;
    writeAccessibilityStorage("history", state.displayHistory);
    persistAccessibilityPreferences();
    applyAccessibilityDisplayPreferences();
    renderAll();
    announcePolite("Display changes undone.", { key: "display-settings-undone" });
    showToast("Display changes undone.", "success");
  }

  function renderAccessibilityHelpSection() {
    return `<section class="accessibility-help-centre" aria-labelledby="accessibilityHelpTitle">
      <div class="section-heading compact"><div><span class="eyebrow">HELP</span><h3 id="accessibilityHelpTitle">Accessibility Help</h3></div></div>
      <div class="accessibility-help-grid">
        <p><b>Font size:</b> Choose a size, then preview before saving.</p>
        <p><b>Text spacing:</b> Use comfortable or extra spacing for easier reading.</p>
        <p><b>Large buttons:</b> Turn on larger controls for touch or motor access.</p>
        <p><b>High contrast:</b> Use stronger colours for readability.</p>
        <p><b>Reduced motion:</b> Reduce animation while keeping the app usable.</p>
        <p><b>Keyboard:</b> Use Tab to move and Enter or Space to activate controls. Alt + Shift + A opens recovery. Alt + Shift + L opens language recovery.</p>
        <p><b>Voice or read-aloud fails:</b> Continue with text fields, transcripts, and visible instructions.</p>
        <p><b>Offline:</b> Download recipes for text-first cooking without a connection.</p>
      </div>
    </section>`;
  }

  function renderAccessibilityRecoveryPage() {
    const target = $("#accessibilityRecoveryContent");
    if (!target) return;
    target.innerHTML = `<section class="accessibility-recovery-shell" aria-labelledby="accessibilityRecoveryTitle">
      <span class="eyebrow">ACCESSIBILITY RECOVERY</span>
      <h1 id="accessibilityRecoveryTitle" tabindex="-1">Accessibility Recovery</h1>
      <p>Use baseline controls to recover display, language, keyboard, voice, or feedback settings.</p>
      <div class="accessibility-recovery-actions">
        <button class="button primary" type="button" data-restore-display-defaults>Restore Display Defaults</button>
        <button class="button secondary" type="button" data-display-undo>Return to Previous Display Settings</button>
        <button class="button secondary" type="button" data-recovery-quick-display="largeButtons">Turn On Large Buttons</button>
        <button class="button secondary" type="button" data-recovery-quick-display="highContrastMode">Turn On High Contrast</button>
        <button class="button secondary" type="button" data-recovery-quick-display="reducedMotionMode">Turn Off Animations</button>
        <a class="language-recovery-link" href="#account" data-page="account" data-focus-language-settings="true" aria-label="Open Profile Settings Language and Region">Change Language</a>
        <button class="button secondary" type="button" data-recovery-text-only>Continue with Text Only</button>
        <button class="button secondary" type="button" data-page="account" data-focus-accessibility-settings="true">Open Keyboard Help</button>
        <button class="button secondary" type="button" data-open-accessibility-feedback>Report an Accessibility or Language Problem</button>
        <button class="button secondary" type="button" data-return-from-accessibility-recovery>Return to Previous Screen</button>
      </div>
      ${renderAccessibilityHelpSection()}
    </section>`;
    $("#accessibilityRecoveryTitle")?.focus();
  }

  function updateRecoveryQuickDisplay(field) {
    const prefs = normalizeAccessibilityPreferences(state.accessibilityPreferences || {});
    const previous = prefs.display;
    const next = { ...previous };
    if (field === "largeButtons") next.largeButtons = true;
    if (field === "highContrastMode") next.highContrastMode = "on";
    if (field === "reducedMotionMode") next.reducedMotionMode = "on";
    const entry = ACCESSIBILITY_RECOVERY.createDisplayHistoryEntry?.(previous, next, "recovery-screen");
    state.accessibilityPreferences = { ...prefs, display: next };
    if (entry) saveDisplayHistoryEntry(entry);
    persistAccessibilityPreferences();
    applyAccessibilityDisplayPreferences();
    renderAccessibilityRecoveryPage();
    showToast("Recovery display setting applied.", "success");
  }

  function openAccessibilityRecovery(trigger = null) {
    const snapshot = captureAccessibilitySessionSnapshot();
    state.accessibilityRecoveryReturnTarget = {
      page: snapshot.route || "home",
      focusElementId: trigger?.id || document.activeElement?.id || "",
      openedFromProfileMenu: trigger?.id === "profileAccessibilitySettingsButton"
    };
    closeAccountMenu();
    navigate("accessibility-recovery");
  }

  function returnFromAccessibilityRecovery() {
    const target = state.accessibilityRecoveryReturnTarget || { page: "account", focusElementId: "openAccessibilityRecoveryFromSettings" };
    navigate(target.page || "account");
    if (target.openedFromProfileMenu) {
      state.profileMenuOpen = true;
      renderAccount();
    }
    window.setTimeout(() => {
      const focusTarget = target.focusElementId ? document.getElementById(target.focusElementId) : null;
      if (focusTarget) focusTarget.focus();
      else if (target.page === "account") focusAccessibilitySettings();
      else $("#main-content")?.focus();
    }, 0);
  }

  function openLanguageRecovery() {
    navigate("account");
    focusLanguageRegionSettings();
  }

  function changeInterfaceLanguage(locale, options = {}) {
    const previousLocalization = getLocalizationPreferences();
    const previousLanguage = normalizeAccessibilityPreferences(state.accessibilityPreferences || {}).language;
    const interfaceLanguage = getLanguageCodeFromLocale(locale);
    const regionCode = normalizeRegionCode(previousLanguage.regionCode || previousLocalization.regionCode || getRegionCodeFromLocale(locale), previousLocalization.locale);
    const interfaceLocale = resolveLocale(interfaceLanguage, regionCode, { fallbackLocale: locale || previousLocalization.locale });
    const proposedLanguage = {
      ...previousLanguage,
      interfaceLanguage,
      interfaceLocale,
      regionCode,
      measurementLocale: interfaceLocale
    };
    const transaction = ACCESSIBILITY_RECOVERY.createLanguageChangeTransaction?.(previousLanguage, proposedLanguage, captureAccessibilitySessionSnapshot());
    state.languageChangeTransaction = transaction;
    const result = ACCESSIBILITY_RECOVERY.applyLanguageChange?.(state.accessibilityPreferences, transaction, options) || { ok: true, preferences: { ...state.accessibilityPreferences, language: proposedLanguage }, direction: getAppLanguageDirection(interfaceLanguage), restoredSnapshot: captureAccessibilitySessionSnapshot() };
    if (!result.ok) {
      state.accessibilityPreferences = result.preferences;
      saveLocalizationPreferences(previousLocalization);
      updateAppLanguageMetadata(previousLanguage.interfaceLanguage || previousLanguage.interfaceLocale || previousLocalization.locale);
      showLanguageFailureMessage(locale);
      announcePolite("Language change was not completed. Previous language restored.", { key: "language-change-failed" });
      return false;
    }
    state.accessibilityPreferences = result.preferences;
    persistAccessibilityPreferences();
    saveLocalizationPreferences({ ...previousLocalization, locale: interfaceLocale, regionCode, timeZone: previousLocalization.timeZone });
    updateAppLanguageMetadata(interfaceLanguage);
    displayPantry();
    displayMealPlanner();
    displayShoppingList();
    displayRecipeDetailsIfOpen(result.restoredSnapshot?.recipeId || "");
    renderAccountPage();
    renderAccessibilityRecoveryPage();
    applyAppLanguage(interfaceLanguage);
    announcePolite(t("languageChanged"), { key: "language-changed" });
    return true;
  }

  function showLanguageFailureMessage(locale) {
    let modal = $("#languageRecoveryFailure");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "languageRecoveryFailure";
      modal.className = "display-preview-backdrop";
      document.body.appendChild(modal);
    }
    modal.innerHTML = `<section class="display-preview-modal small" role="dialog" aria-modal="true" aria-labelledby="languageFailureTitle">
      <h2 id="languageFailureTitle" tabindex="-1">Language Change Was Not Completed</h2>
      <p>Chef Nova returned to your previous language. Your recipe, cooking step, timers, and drafts were preserved.</p>
      <div class="display-preview-actions"><button class="button primary" type="button" data-language-retry="${escapeHtml(locale)}">Try Again</button><button class="button secondary" type="button" data-language-recovery>Choose Another Language</button><button class="button secondary" type="button" data-language-failure-close>Close</button></div>
    </section>`;
    $("#languageFailureTitle")?.focus();
  }

  function closeLanguageFailureMessage() {
    $("#languageRecoveryFailure")?.remove();
  }

  function openAccessibilityFeedback(category = "", reference = null) {
    state.accessibilityFeedbackDraft = ACCESSIBILITY_RECOVERY.createFeedbackDraft?.({ category, contentReference: reference }) || { category, contentReference: reference, description: "" };
    renderAccessibilityFeedbackModal(false);
  }

  function renderAccessibilityFeedbackModal(reviewMode = false) {
    let modal = $("#accessibilityFeedbackModal");
    if (!modal) {
      modal = document.createElement("div");
      modal.id = "accessibilityFeedbackModal";
      modal.className = "accessibility-feedback-backdrop";
      document.body.appendChild(modal);
    }
    const draft = state.accessibilityFeedbackDraft || {};
    if (reviewMode) {
      const record = createAccessibilityFeedbackRecordFromDraft(false);
      modal.innerHTML = `<section class="accessibility-feedback-modal" role="dialog" aria-modal="true" aria-labelledby="feedbackReviewTitle">
        <h2 id="feedbackReviewTitle" tabindex="-1">Review Your Report</h2>
        <p><b>Category:</b> ${escapeHtml(feedbackCategoryLabel(record.category))}</p>
        <p><b>Your description:</b> ${escapeHtml(record.description || "No description entered")}</p>
        <div class="feedback-review-columns"><div><h3>Included</h3><ul>${Object.keys(record.included || {}).map((key) => `<li>${escapeHtml(key.replace(/([A-Z])/g, " $1").toLowerCase())}</li>`).join("") || "<li>Only your category and description</li>"}</ul></div><div><h3>Not included</h3><ul>${record.notIncluded.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}</ul></div></div>
        <div class="profile-form-actions"><button class="button primary" type="button" data-feedback-send>Send Report</button><button class="button secondary" type="button" data-feedback-edit>Edit Report</button><button class="button secondary" type="button" data-feedback-cancel>Cancel</button></div>
      </section>`;
      $("#feedbackReviewTitle")?.focus();
      return;
    }
    const categoryRows = (ACCESSIBILITY_RECOVERY.FEEDBACK_CATEGORIES || []).map((item) => `<label><input type="radio" name="feedbackCategory" value="${escapeHtml(item.id)}" ${draft.category === item.id ? "checked" : ""}> ${escapeHtml(item.label)}</label>`).join("");
    modal.innerHTML = `<section class="accessibility-feedback-modal" role="dialog" aria-modal="true" aria-labelledby="feedbackTitle">
      <h2 id="feedbackTitle" tabindex="-1">Report an Accessibility or Language Problem</h2>
      <form id="accessibilityFeedbackForm" novalidate>
        <fieldset class="feedback-category-group"><legend>Problem category</legend>${categoryRows}</fieldset>
        <label for="feedbackDescription">What happened?<textarea id="feedbackDescription" name="description" rows="5" required>${escapeHtml(draft.description || "")}</textarea></label>
        <label for="feedbackImpact">Impact<select id="feedbackImpact" name="userImpact"><option value="minor">Minor</option><option value="blocked-task">Blocked task</option><option value="safety-concern">This may affect allergy or food-safety information</option></select></label>
        <fieldset class="feedback-consent-group"><legend>Optional information. Off by default.</legend>
          <label class="checkbox-field"><input name="includePageContext" type="checkbox"> Include current page name</label>
          <label class="checkbox-field"><input name="includeDisplaySettings" type="checkbox"> Include current display settings</label>
          <label class="checkbox-field"><input name="includeLanguageSettings" type="checkbox"> Include language settings</label>
          <label class="checkbox-field"><input name="includeRecognizedVoiceText" type="checkbox"> Include text Chef Nova understood from voice input</label>
          <label class="checkbox-field"><input name="includeTechnicalDiagnostics" type="checkbox"> Include safe technical diagnostics</label>
        </fieldset>
        <p class="feedback-privacy-note">Not included by default: pantry contents, allergies, dietary restrictions, meal plans, shopping lists, budget data, waste diary details, screenshots, raw audio, and account tokens.</p>
        <p class="form-error" id="accessibilityFeedbackError" role="alert"></p>
        <div class="profile-form-actions"><button class="button primary" type="submit">Review Report</button><button class="button secondary" type="button" data-feedback-cancel>Cancel</button></div>
      </form>
    </section>`;
    $("#feedbackTitle")?.focus();
  }

  function feedbackCategoryLabel(id) {
    return (ACCESSIBILITY_RECOVERY.FEEDBACK_CATEGORIES || []).find((item) => item.id === id)?.label || "Other";
  }

  function updateFeedbackDraftFromForm() {
    const form = $("#accessibilityFeedbackForm");
    if (!form) return false;
    const category = form.feedbackCategory.value || "";
    const description = form.description.value.trim();
    if (!category || !description) {
      $("#accessibilityFeedbackError").textContent = "Choose a category and describe the problem.";
      return false;
    }
    state.accessibilityFeedbackDraft = ACCESSIBILITY_RECOVERY.createFeedbackDraft?.({
      ...state.accessibilityFeedbackDraft,
      category,
      description,
      userImpact: form.userImpact.value,
      includePageContext: form.includePageContext.checked,
      includeDisplaySettings: form.includeDisplaySettings.checked,
      includeLanguageSettings: form.includeLanguageSettings.checked,
      includeRecognizedVoiceText: form.includeRecognizedVoiceText.checked,
      includeTechnicalDiagnostics: form.includeTechnicalDiagnostics.checked
    });
    return true;
  }

  function createAccessibilityFeedbackRecordFromDraft(commit = true) {
    const prefs = normalizeAccessibilityPreferences(state.accessibilityPreferences || {});
    const record = ACCESSIBILITY_RECOVERY.createFeedbackRecord?.(state.accessibilityFeedbackDraft || {}, {
      offline: navigator.onLine === false,
      route: (location.hash || "#home").replace("#", ""),
      componentId: document.activeElement?.id || "",
      displaySettings: prefs.display,
      languageSettings: prefs.language,
      diagnostics: {
        appVersion: "static-local",
        routeTemplate: (location.hash || "#home").replace("#", "").split("?")[0],
        interfaceLocale: prefs.language.interfaceLocale,
        explanationLocale: prefs.language.explanationLocale,
        textDirection: document.documentElement.dir || "ltr",
        connectivityState: state.networkState?.status || (navigator.onLine === false ? "offline" : "online"),
        viewportCategory: window.innerWidth < 640 ? "small" : window.innerWidth < 1024 ? "medium" : "large",
        featureAvailabilityState: Object.values(state.featureAvailability || {}).map((item) => item.state).join(",").slice(0, 120)
      }
    }) || { ...state.accessibilityFeedbackDraft, status: navigator.onLine === false ? "queued-offline" : "received", included: {}, notIncluded: [] };
    if (commit) {
      const triage = ACCESSIBILITY_RECOVERY.createTranslationFeedbackTriageItem?.(record, CONTENT_REVIEW);
      record.triageItem = triage || null;
      state.accessibilityFeedbackReports = [record, ...(state.accessibilityFeedbackReports || [])].slice(0, 50);
      writeAccessibilityStorage("feedback", state.accessibilityFeedbackReports);
    }
    return record;
  }

  function submitAccessibilityFeedback() {
    const record = createAccessibilityFeedbackRecordFromDraft(true);
    const reference = record.status === "queued-offline" ? "Report saved on this device." : `Reference: ${record.id}`;
    closeAccessibilityFeedbackModal();
    showToast(record.status === "queued-offline" ? "Report saved on this device. Chef Nova will send it when your connection returns." : "Report sent. Thank you.", record.status === "queued-offline" ? "info" : "success");
    announcePolite(`${record.status === "queued-offline" ? "Report saved offline." : "Report sent."} ${reference}`, { key: "accessibility-feedback-submitted" });
  }

  function closeAccessibilityFeedbackModal() {
    $("#accessibilityFeedbackModal")?.remove();
    state.accessibilityFeedbackDraft = null;
  }

  function getRecipeContentVersion(recipe) {
    if (typeof CONTENT_REVIEW.createReviewableVersion !== "function") return null;
    return CONTENT_REVIEW.createReviewableVersion({
      entityId: recipe.id,
      entityType: "recipe",
      version: Number(recipe.recipeVersion || recipe.version) || 1,
      sourceLocale: recipe.sourceLocale || "en-CA",
      requiredReviews: ["content-completeness", "accessibility", "food-safety"],
      createdBy: recipe.createdBy || "legacy-import",
      content: recipe,
      status: CONTENT_REVIEW.CONTENT_REVIEW_STATUSES?.OUTDATED || "outdated"
    });
  }

  function evaluateRecipePublicationReadiness(recipe, locales = ["en-CA"]) {
    if (typeof CONTENT_REVIEW.evaluateRecipe !== "function") return { publishable: true, issues: [], approvedLocales: locales, blockedLocales: [], version: null };
    const version = getRecipeContentVersion(recipe);
    return CONTENT_REVIEW.evaluateRecipe(recipe, {
      version,
      requestedLocales: locales,
      translations: recipe.translations || [],
      approvals: recipe.reviewApprovals || [],
      ingredientTerms: state.ingredientCatalogue?.ingredients || []
    });
  }

  function getRecipePublishedSnapshotStatus(recipe) {
    if (typeof CONTENT_REVIEW.migrateLegacyRecipe !== "function") return { legacyPublished: true, reviewMarker: "legacy-review-required", remediationIssues: [] };
    return CONTENT_REVIEW.migrateLegacyRecipe(recipe);
  }

  function renderContentReviewDashboardSection() {
    if (typeof CONTENT_REVIEW.evaluateRecipe !== "function") return "";
    const recipes = state.recipes.map(normalizeRecipe);
    const readiness = recipes.map((recipe) => ({ recipe, migration: getRecipePublishedSnapshotStatus(recipe), evaluation: evaluateRecipePublicationReadiness(recipe, ["en-CA", "fr-CA", "zh-CN"]) }));
    const blocked = readiness.filter((item) => item.evaluation.issues.length);
    const ready = readiness.filter((item) => item.evaluation.publishable);
    const issueRows = blocked.slice(0, 6).map((item) => {
      const firstIssue = item.evaluation.issues[0];
      return `<article class="content-review-row">
        <div><h3>${escapeHtml(item.recipe.name)}</h3><p>${escapeHtml(firstIssue.messageKey || firstIssue.code)}</p><small>Version ${escapeHtml(String(item.evaluation.version?.version || 1))} · ${escapeHtml(firstIssue.requiredReviewKind || "review required")} · ${escapeHtml(firstIssue.fieldPath || "recipe")}</small></div>
        <button class="button secondary small" type="button" data-recipe-details="${escapeHtml(item.recipe.id)}">Open Recipe</button>
      </article>`;
    }).join("");
    const queueItems = blocked.map((item) => ({ reviewKind: item.evaluation.issues[0]?.requiredReviewKind || "content-completeness", status: "unassigned", entityId: item.recipe.id, assignedToCurrentUser: false }));
    const dashboard = typeof CONTENT_REVIEW.buildReviewDashboardModel === "function" ? CONTENT_REVIEW.buildReviewDashboardModel(queueItems) : {};
    return `<section class="profile-section content-review-dashboard" aria-labelledby="contentReviewDashboardTitle">
      <div class="nutrition-profile-header">
        <span class="eyebrow">CONTENT GOVERNANCE</span>
        <h2 id="contentReviewDashboardTitle">Review Dashboard</h2>
        <p>Drafts can be saved. Publication is blocked until required human reviews match the exact version.</p>
      </div>
      <div class="content-review-summary">
        <div><span>Legacy recipes preserved</span><strong>${recipes.length}</strong></div>
        <div><span>Need remediation</span><strong>${blocked.length}</strong></div>
        <div><span>Ready now</span><strong>${ready.length}</strong></div>
        <div><span>Safety queue</span><strong>${dashboard.safetyReview?.length || 0}</strong></div>
      </div>
      <div class="publication-readiness-panel" role="status" aria-live="polite">
        <h3>Publication Readiness</h3>
        ${issueRows || `<p>No blocking issues found in the current local catalogue.</p>`}
      </div>
      <p class="content-review-note">This static app has no trusted backend. The local gate blocks Chef Nova publication actions inside this app, and the report documents that server enforcement would be required before real production publishing.</p>
    </section>`;
  }

  function handleOfflineCookingKeydown(event) {
    const modal = $("#recipeDetailModal");
    if (!modal || modal.classList.contains("hidden")) return false;
    if (typeof RESILIENCE.shouldHandleKeyboardShortcut === "function" && !RESILIENCE.shouldHandleKeyboardShortcut(event, state.offlineCookingPreferences)) return false;
    const recipeId = $("#recipeDetailModalTitle")?.dataset.recipeId || "";
    if (!recipeId) return false;
    const shortcuts = {
      ArrowRight: () => moveOfflineRecipeStep(recipeId, 1),
      ArrowLeft: () => moveOfflineRecipeStep(recipeId, -1),
      Enter: () => completeOfflineRecipeStep(recipeId),
      t: () => startOfflineRecipeTimer(recipeId),
      T: () => startOfflineRecipeTimer(recipeId),
      r: () => readRecipeDetailAloud(recipeId),
      R: () => readRecipeDetailAloud(recipeId),
      i: () => $("#recipeDetailInstructions")?.focus(),
      I: () => $("#recipeDetailInstructions")?.focus(),
      w: () => $("#recipeTtsFallbackRegion")?.focus(),
      W: () => $("#recipeTtsFallbackRegion")?.focus()
    };
    const action = shortcuts[event.key];
    if (!action) return false;
    event.preventDefault();
    action();
    return true;
  }

  const PROFILE_SECTION_IDS = ["overview", "personal", "language-region", "accessibility", "food-preferences", "privacy", "security", "notifications", "data-account"];

  function normalizeProfileSection(section) {
    const normalized = String(section || "overview").trim().toLowerCase();
    return PROFILE_SECTION_IDS.includes(normalized) ? normalized : "not-found";
  }

  function normalizeProfileRoutePage(page) {
    return String(page || "").trim().toLowerCase() === "profile" ? "account" : page;
  }

  function getProfileAccountState() {
    if (state.guestMode || isGuestMode()) return "guest";
    const activeUserId = getCurrentUserId();
    if (!activeUserId) return isSwitchingAccount ? "loading" : "signed-out";
    if (state.users.some((user) => user.id === activeUserId)) return "authenticated";
    return isSwitchingAccount ? "loading" : "error";
  }

  function getAccessibilityPreferences() {
    return normalizeAccessibilityPreferences(state.accessibilityPreferences || {});
  }

  function buildProfileHash(section = "overview") {
    const normalized = normalizeProfileSection(section);
    return normalized && normalized !== "overview" && normalized !== "not-found" ? `#account/${normalized}` : "#account";
  }

  function getProfileSections(user) {
    const safeUser = user || {};
    const prefs = getLocalizationPreferences();
    const accessibility = getAccessibilityPreferences();
    const progress = getSavedProgressSummary();
    const nutritionProfile = safeUser.id ? getNutritionProfile(safeUser.id) : null;
    const nutritionStatus = getNutritionProfileSetupStatusDisplay(getNutritionProfileSetupStatus(nutritionProfile));
    const allergyCount = normalizeAllergies(safeUser.allergies).length;
    const foodPreferenceCount = allergyCount + (safeUser.dietaryPreference && safeUser.dietaryPreference !== "No preference" ? 1 : 0);
    const displayPrefs = accessibility.display || {};
    return [
      { id: "personal", title: "Personal Profile", description: "Update your photo and account details.", status: safeUser.email || "Email saved" },
      { id: "language-region", title: "Language & Region", description: "Set language, region, and formats.", status: `${getLanguageOptionLabel(accessibility.language?.interfaceLanguage || accessibility.language?.interfaceLocale || prefs.locale)} · ${getRegionDisplayLabel(getActiveRegionCode(prefs, accessibility.language), resolveLocale(accessibility.language?.interfaceLanguage || accessibility.language?.interfaceLocale || prefs.locale, getActiveRegionCode(prefs, accessibility.language)))} · ${prefs.measurementSystem || "metric"}` },
      { id: "accessibility", title: "Accessibility", description: "Adjust reading and recovery settings.", status: displayPrefs.highContrastMode === "on" ? "High contrast on" : "Standard display" },
      { id: "food-preferences", title: "Food Preferences & Safety", description: "Manage diets and allergies.", status: `${foodPreferenceCount} saved preferences` },
      { id: "privacy", title: "Privacy & Voice", description: "Review voice and local privacy options.", status: state.voicePrivacyEvents.length ? `${state.voicePrivacyEvents.length} voice events` : "Voice privacy ready" },
      { id: "security", title: "Account Security", description: "Manage email and password access.", status: "Password protected" },
      { id: "notifications", title: "Notifications", description: "Open reminders and notification controls.", status: `${progress.settingsSaved ? "Settings saved" : "Default settings"}` },
      { id: "data-account", title: "Data & Account", description: "Review saved data and offline tools.", status: `${progress.favorites + progress.pantry} saved items` }
    ];
  }

  function renderProfileSubnav(activeSection) {
    return `<nav class="profile-subnav" aria-label="Profile settings">
      <a href="#account" data-page="account" ${activeSection === "overview" ? `aria-current="page"` : ""}>Overview</a>
      ${getProfileSections(getCurrentUser() || {}).map((section) => `<a href="${buildProfileHash(section.id)}" data-page="account/${section.id}" ${activeSection === section.id ? `aria-current="page"` : ""}>${escapeHtml(section.title)}</a>`).join("")}
    </nav>`;
  }

  function renderProfilePageShell({ section, eyebrow, title, description, body }) {
    return `<div class="profile-page-shell">
      ${renderProfileSubnav(section)}
      <div class="profile-subpage">
        <div class="profile-subpage-heading">
          <span class="eyebrow">${escapeHtml(eyebrow || "PROFILE SETTINGS")}</span>
          <h2 id="profilePageTitle" tabindex="-1">${escapeHtml(title)}</h2>
          <p>${escapeHtml(description)}</p>
        </div>
        ${body}
      </div>
    </div>`;
  }

  function renderProfileStatusCards(user) {
    const progress = getSavedProgressSummary();
    const allergyCount = normalizeAllergies(user.allergies).length;
    const nutritionProfile = getNutritionProfile(user.id);
    const nutritionStatus = getNutritionProfileSetupStatusDisplay(getNutritionProfileSetupStatus(nutritionProfile));
    const rows = [
      ["Favorites", String(progress.favorites)],
      ["Pantry Items", String(progress.pantry)],
      ["Meal Plan", `${progress.mealsPlanned} / ${progress.totalMeals}`],
      ["Diet", user.dietaryPreference || "No preference"],
      ["Allergies", `${allergyCount} saved`],
      ["Nutrition", nutritionStatus.label]
    ];
    return `<div class="profile-status-grid" aria-label="Profile summary">${rows.map(([label, value]) => `<div class="profile-status-card"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join("")}</div>`;
  }

  function renderProfileOverview(user) {
    const safeUser = user || {};
    const sections = getProfileSections(user);
    return `<div class="profile-overview">
      <div class="profile-overview-hero">
        ${renderUserAvatar(safeUser, { size: "large", className: "profile-avatar profile-avatar-large", decorative: false })}
        <div>
          <span class="eyebrow">CURRENT COOK</span>
          <h2 id="profilePageTitle" tabindex="-1">${escapeHtml(safeUser.name || "Chef Nova User")}</h2>
          <p>${escapeHtml(safeUser.email || "Profile saved on this device.")}</p>
        </div>
        <div class="profile-overview-actions">
          <button class="button primary small" type="button" data-page="account/personal">Edit Profile</button>
          <button class="button secondary small profile-logout" type="button" data-auth="logout">Logout</button>
        </div>
      </div>
      ${renderProfileStatusCards(user)}
      <section class="profile-section-navigation" aria-labelledby="profileSectionNavigationTitle">
        <div class="section-heading-line">
          <h3 id="profileSectionNavigationTitle">Profile Settings</h3>
        </div>
        <div class="profile-section-grid">
          ${sections.map((section) => `<a class="profile-section-card" href="${buildProfileHash(section.id)}" data-page="account/${section.id}">
            <span>${escapeHtml(section.status)}</span>
            <h3>${escapeHtml(section.title)}</h3>
            <p>${escapeHtml(section.description)}</p>
            <b>Open ${escapeHtml(section.title)}</b>
          </a>`).join("")}
        </div>
      </section>
    </div>`;
  }

  function renderPersonalProfilePage(user) {
    const details = [["Name", user.name || "Not provided"], ["Email", user.email || "Not provided"], ["Age", user.age || "Not provided"], ["Gender", user.gender || "Not provided"], ["Phone", user.phone || "Not provided"]];
    return renderProfilePageShell({
      section: "personal",
      title: "Personal Profile",
      description: "Update your photo and basic account details.",
      body: `<div class="profile-details">${details.map(([label, value]) => `<div class="profile-detail"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join("")}</div>
      ${renderProfilePictureSection(user)}
      <div class="profile-page-actions"><button class="button primary small" type="button" data-profile-edit>Edit Profile</button></div>
      ${state.isEditingProfile ? renderProfileEditForm(user) : ""}`
    });
  }

  function renderFoodPreferencesProfilePage(user) {
    const details = [["Dietary preference", user.dietaryPreference || "No preference"], ["Allergies", formatAllergies(user.allergies)]];
    return renderProfilePageShell({
      section: "food-preferences",
      title: "Food Preferences & Safety",
      description: "Manage dietary preferences and allergy warnings.",
      body: `<div class="profile-details compact">${details.map(([label, value]) => `<div class="profile-detail"><span>${escapeHtml(label)}</span><strong>${escapeHtml(value)}</strong></div>`).join("")}</div>
      <p class="profile-helper-note">Allergy details are stored locally and used for recipe warnings.</p>
      <div class="profile-page-actions"><button class="button primary small" type="button" data-profile-edit>Edit Food Preferences</button></div>
      ${state.isEditingProfile ? renderProfileEditForm(user) : ""}`
    });
  }

  function renderSecurityProfilePage(user) {
    return renderProfilePageShell({
      section: "security",
      title: "Account Security",
      description: "Manage login details for this device.",
      body: `<div class="profile-details compact">
        <div class="profile-detail"><span>Email</span><strong>${escapeHtml(user.email || "No email saved")}</strong></div>
        <div class="profile-detail"><span>Password</span><strong>Saved locally</strong></div>
      </div>
      <div class="profile-page-actions"><button class="button primary small" type="button" data-password-edit>Change Password</button><button class="button secondary small" type="button" data-profile-edit>Edit Email</button></div>
      ${state.isChangingPassword ? renderPasswordChangeForm() : ""}
      ${state.isEditingProfile ? renderProfileEditForm(user) : ""}`
    });
  }

  function renderPrivacyProfilePage() {
    return renderProfilePageShell({
      section: "privacy",
      title: "Privacy & Voice",
      description: "Review voice activity and privacy controls.",
      body: `<div class="profile-details compact">
        <div class="profile-detail"><span>Voice Activity</span><strong>${escapeHtml(state.voicePrivacyEvents.length ? `${state.voicePrivacyEvents.length} local events` : "No local voice events")}</strong></div>
        <div class="profile-detail"><span>Storage</span><strong>Stored in this browser</strong></div>
      </div>
      <p class="profile-helper-note">Voice and privacy settings stay on this device unless you choose otherwise.</p>
      ${renderOfflineSettingsSection()}`
    });
  }

  function renderNotificationsProfilePage() {
    return renderProfilePageShell({
      section: "notifications",
      title: "Notifications",
      description: "Open notification filters, reminders, and food-rescue settings.",
      body: `<div class="profile-route-card">
        <h3>Notification Center</h3>
        <p>Review unread messages and manage reminder delivery.</p>
        <button class="button primary small" type="button" data-page="notifications">Open Notifications</button>
      </div>`
    });
  }

  function renderDataAccountProfilePage(user) {
    const progress = getSavedProgressSummary();
    return renderProfilePageShell({
      section: "data-account",
      title: "Data & Account",
      description: "Review saved data, content checks, and account tools.",
      body: `<div class="profile-details compact">
        <div class="profile-detail"><span>Favorites</span><strong>${progress.favorites}</strong></div>
        <div class="profile-detail"><span>Pantry</span><strong>${progress.pantry}</strong></div>
        <div class="profile-detail"><span>Meal Plan</span><strong>${progress.mealsPlanned} / ${progress.totalMeals}</strong></div>
      </div>
      ${renderContentReviewDashboardSection()}
      ${renderBodyNutritionProfileSection({ profile: getNutritionProfile(user.id), derivedTarget: loadDailyNutritionTarget(), isGuest: false })}`
    });
  }

  function renderProfileNotFoundPage() {
    return renderProfilePageShell({
      section: "not-found",
      title: "Profile Section Not Found",
      description: "This Profile section could not be found.",
      body: `<div class="profile-route-card"><p>This Profile section could not be found.</p><button class="button primary small" type="button" data-page="account">Open Profile</button></div>`
    });
  }

  function renderProfileLoadingState() {
    return `<section class="profile-state-card" role="status" aria-live="polite">
      <h2 id="profilePageTitle" tabindex="-1">Loading your profile...</h2>
      <p>Chef Nova is opening your saved Profile.</p>
    </section>`;
  }

  function renderProfileErrorState() {
    return `<section class="profile-state-card profile-state-card--error" role="alert">
      <h2 id="profilePageTitle" tabindex="-1">Profile could not be loaded</h2>
      <p>Your Chef Nova data has not been changed.</p>
      <div class="profile-page-actions">
        <button class="button primary small" type="button" data-profile-retry>Try Again</button>
        <button class="button secondary small" type="button" data-return-button>Return</button>
      </div>
    </section>`;
  }

  function renderRegisteredProfileSection(user, section) {
    if (section === "overview") return renderProfileOverview(user);
    if (section === "personal") return renderPersonalProfilePage(user);
    if (section === "language-region") return renderProfilePageShell({ section, title: "Language & Region", description: "Set language, region, measurements, and formats.", body: renderLocalizationPreferencesSection() });
    if (section === "accessibility") return renderProfilePageShell({ section, title: "Accessibility", description: "Adjust reading, keyboard, and recovery settings.", body: renderAccessibilityRecoverySettingsSection() });
    if (section === "food-preferences") return renderFoodPreferencesProfilePage(user);
    if (section === "privacy") return renderPrivacyProfilePage();
    if (section === "security") return renderSecurityProfilePage(user);
    if (section === "notifications") return renderNotificationsProfilePage();
    if (section === "data-account") return renderDataAccountProfilePage(user);
    return renderProfileNotFoundPage();
  }

  function renderAccountPage() {
    const guest = $("#accountGuest"); const profile = $("#accountProfile");
    if (!guest || !profile) {
      console.error("Profile page containers are missing.");
      return;
    }
    try {
      const accountState = getProfileAccountState();
      if (accountState === "loading") {
        guest.classList.add("hidden");
        profile.classList.remove("hidden");
        profile.innerHTML = renderProfileLoadingState();
        return;
      }
      if (accountState === "guest") {
        guest.classList.remove("hidden");
        profile.classList.add("hidden");
        guest.innerHTML = renderGuestAccountPanel();
        return;
      }
      if (accountState === "signed-out") {
        guest.classList.remove("hidden");
        profile.classList.add("hidden");
        return;
      }
      if (accountState === "error") {
        state.currentUser = null;
        clearCurrentUserSession();
        guest.classList.add("hidden");
        profile.classList.remove("hidden");
        profile.innerHTML = renderProfileErrorState();
        return;
      }
      const user = getCurrentUser();
      if (!user) throw new Error("Authenticated session could not be resolved.");
      guest.classList.add("hidden");
      profile.classList.remove("hidden");
      profile.innerHTML = renderRegisteredProfileSection(user, state.profileSection || "overview");
    } catch (error) {
      console.error("Unable to render Profile page:", error);
      guest.classList.add("hidden");
      profile.classList.remove("hidden");
      profile.innerHTML = renderProfileErrorState();
    }
  }

  function renderGuestAccountPanel() {
    const guestProfile = getActiveNutritionProfile();
    const guestSection = renderBodyNutritionProfileSection({
      profile: guestProfile,
      derivedTarget: loadDailyNutritionTarget(),
      isGuest: true
    });
    return `<div class="account-intro-card guest-profile-panel">
      <span class="brand-mark large">✦</span><span class="eyebrow">SESSION SETTINGS</span>
      <h2>Guest settings</h2>
      <p>Review temporary settings for this session.</p>
      <section class="profile-section profile-picture-section guest-avatar-section" aria-labelledby="guestProfilePictureTitle">
        <div class="nutrition-profile-header">
          <span class="eyebrow">PROFILE PICTURE</span>
          <h2 id="guestProfilePictureTitle">Profile Picture</h2>
          <p>Create an account to add a permanent profile picture.</p>
        </div>
        <div class="profile-picture-card">
          <span class="profile-avatar" aria-label="Guest avatar">GN</span>
          <div class="profile-picture-copy">
            <p>Guest avatar changes are not saved permanently.</p>
            <div class="profile-picture-actions"><button class="button primary small" type="button" data-auth-mode="register">Create Account</button><button class="button secondary small" type="button" data-auth-mode="login">Log In</button></div>
          </div>
        </div>
      </section>
      ${guestSection}
      ${renderLocalizationPreferencesSection()}
      ${renderAccessibilityRecoverySettingsSection()}
      ${renderOfflineSettingsSection()}
    </div>`;
  }

  function updateProfileNutritionSection() {
    const section = $("#profileNutritionSection");
    if (!section) return;
    const user = getCurrentUser();
    if (!user || state.guestMode || isGuestMode()) {
      section.hidden = true;
      section.setAttribute("aria-hidden", "true");
      return;
    }
    section.hidden = false;
    section.removeAttribute("aria-hidden");
    const summaryElement = $("#nutritionProfileSummary");
    const profile = getNutritionProfile(user.id);
    if (summaryElement) {
      summaryElement.innerHTML = renderBodyNutritionProfileSummary(profile, loadDailyNutritionTarget(), false);
    }
  }

  function renderBodyNutritionProfileSection({ profile, derivedTarget = null, isGuest = false } = {}) {
    const canonical = normalizeStoredNutritionProfile(profile);
    return `<section id="profileNutritionSection" class="profile-section nutrition-profile-section guest-body-nutrition-section" aria-labelledby="profileNutritionTitle">
      <div class="nutrition-profile-header">
        <span class="eyebrow">OPTIONAL</span>
        <h2 id="profileNutritionTitle">Body and Nutrition Information</h2>
        <p>${isGuest ? "Guest nutrition profile information is temporary." : "Review or update optional nutrition settings."}</p>
        <p class="nutrition-profile-privacy-note">${isGuest ? "Available only during this Guest Mode session." : "Body measurements are hidden by default."}</p>
      </div>
      ${renderBodyNutritionProfileSummary(canonical, derivedTarget, isGuest)}
    </section>`;
  }

  function renderBodyNutritionProfileSummary(profile, derivedTarget, isGuest = false) {
    const canonical = normalizeStoredNutritionProfile(profile);
    const safety = evaluateNutritionSafety(canonical || createEmptyNutritionProfile());
    const summary = buildBodyNutritionProfileSummary(canonical, derivedTarget, safety);
    const status = getNutritionProfileSetupStatusDisplay(summary.setupStatus);
    const privateRows = buildPrivateNutritionInformation(canonical);
    const hasProfile = hasMeaningfulNutritionProfile(canonical);
    const canRecalculate = summary.canRecalculate;
    const summaryRows = [
      ["Setup Status", status.label],
      ["Goal", summary.goalLabel],
      ["Activity Level", summary.activityLabel],
      ["Unit Preference", summary.unitPreference],
      ["Last Updated", summary.lastUpdated]
    ];
    const planningMode = canonical?.goal === "gradual-weight-change" && safety.useMaintenancePlanning ? `<p class="nutrition-profile-safety">Selected goal: ${escapeHtml(summary.goalLabel)}. Planning mode: Maintenance-style planning.</p>` : "";
    const visibleNotice = getNutritionProfileSafetyNotice(safety);
    const privateSectionId = isGuest ? "guestPrivateNutritionInformation" : "privateNutritionInformation";
    const toggleId = isGuest ? "guestTogglePrivateNutritionInfo" : "togglePrivateNutritionInfo";
    const privateToggle = privateRows.length ? `<button class="button secondary small private-info-toggle" type="button" id="${toggleId}" aria-expanded="false" aria-controls="${privateSectionId}" data-private-nutrition-toggle>Show Private Information</button>
      <div id="${privateSectionId}" class="private-nutrition-information" hidden>
        <p class="nutrition-profile-privacy-note">${isGuest ? "Available only during this Guest Mode session." : "Stored locally and hidden by default."}</p>
        ${renderPrivateNutritionRows(privateRows)}
      </div>` : "";
    const deleteButton = hasProfile ? `<button class="button secondary small danger-button" id="deleteNutritionProfileButton" type="button" data-nutrition-profile-delete>Delete Information</button>` : "";
    return `<div class="body-nutrition-summary-card">
      <p class="nutrition-profile-status-text">${escapeHtml(status.description)}</p>
      <dl class="body-nutrition-summary-list">
        ${summaryRows.map(([label, value]) => `<div><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(value)}</dd></div>`).join("")}
      </dl>
      ${planningMode}
      ${visibleNotice ? `<p class="nutrition-profile-safety">${escapeHtml(visibleNotice)}</p>` : ""}
      <div class="nutrition-profile-controls">
        <button class="button primary small" id="editNutritionProfileButton" type="button" data-nutrition-profile-edit>${hasProfile ? "Edit Information" : "Set Up Information"}</button>
        <button class="button secondary small" id="recalculateNutritionEstimatesButton" type="button" data-nutrition-profile-recalculate ${canRecalculate ? "" : "disabled"}>Recalculate Nutrition Estimates</button>
        ${deleteButton}
        ${isGuest && !hasProfile ? `<button class="button secondary small" type="button" data-page="home">Continue Without Setup</button>` : ""}
      </div>
      ${privateToggle}
    </div>`;
  }

  function buildBodyNutritionProfileSummary(profile, derivedTarget, safetyResult) {
    return {
      setupStatus: getNutritionProfileSetupStatus(profile, safetyResult),
      goalLabel: getNutritionGoalDisplayLabel(profile?.goal),
      activityLabel: getActivityLevelDisplayLabel(profile?.activityLevel),
      unitPreference: getUnitPreferenceDisplayLabel(profile?.unitSystem),
      lastUpdated: formatProfileUpdatedDate(profile?.updatedAt),
      hasPrivateInformation: hasPrivateNutritionInformation(profile),
      canRecalculate: canAttemptNutritionRecalculation(profile),
      derivedTargetAvailable: validateDailyNutritionTarget(derivedTarget)
    };
  }

  function getNutritionProfileSetupStatus(profile, safetyResult = evaluateNutritionSafety(profile || createEmptyNutritionProfile())) {
    const canonical = normalizeStoredNutritionProfile(profile);
    if (!hasMeaningfulNutritionProfile(canonical)) return "not-started";
    if (canonical?.preferGeneralNutritionOnly || canonical?.avoidPersonalizedNutrition) return "general-planning-only";
    if (safetyResult?.requiresProfessionalGuidance) return "estimates-unavailable";
    if (safetyResult?.useMaintenancePlanning && canonical?.profileCompleteness === "sufficient-for-estimates") return "general-planning-only";
    if (canonical?.profileCompleteness !== "sufficient-for-estimates") return "partial";
    if (safetyResult && (!safetyResult.canGeneratePersonalizedNutrition || safetyResult.disableEnergyRecommendations || safetyResult.disableMacroRecommendations)) return "estimates-unavailable";
    return "complete";
  }

  function getNutritionProfileSetupStatusDisplay(status) {
    const statuses = {
      "not-started": { label: "Not set up", description: "General meal planning remains available." },
      partial: { label: "Partially set up", description: "Some optional information is missing. General planning remains available." },
      complete: { label: "Set up", description: "Estimated ranges and meal guidance are available." },
      "general-planning-only": { label: "General meal planning only", description: "Personalized nutrition estimates are off." },
      "estimates-unavailable": { label: "Personalized estimates unavailable", description: "General meal planning remains available." }
    };
    return statuses[status] || statuses["not-started"];
  }

  function hasMeaningfulNutritionProfile(profile) {
    return Boolean(
      profile?.setupCompleted ||
      Number.isInteger(profile?.age) ||
      Number.isFinite(profile?.heightCm) ||
      Number.isFinite(profile?.currentWeightKg) ||
      Number.isFinite(profile?.desiredWeightKg) ||
      profile?.activityLevel ||
      profile?.goal ||
      profile?.preferredPace ||
      profile?.workoutProfile ||
      profile?.avoidPersonalizedNutrition ||
      profile?.preferGeneralNutritionOnly
    );
  }

  function getNutritionGoalDisplayLabel(goal) {
    const labels = {
      "maintain-current-weight": "Maintain current weight",
      "support-workouts": "Support workouts",
      "build-muscle": "Support muscle-building goals",
      "gradual-weight-change": "Gradual weight change",
      "improve-eating-habits": "Build balanced eating habits",
      "prefer-not-to-choose": "No specific goal selected"
    };
    return labels[normalizeNutritionGoal(goal)] || "Not selected";
  }

  function getActivityLevelDisplayLabel(activityLevel) {
    const normalized = normalizeActivityLevel(activityLevel);
    const labels = {
      "mostly-inactive": "Mostly inactive",
      "lightly-active": "Lightly active",
      "moderately-active": "Moderately active",
      "very-active": "Very active",
      "athlete-or-intense-training": "Athlete or intense activity"
    };
    return labels[normalized] || "Not selected";
  }

  function getUnitPreferenceDisplayLabel(unitSystem) {
    if (unitSystem === "metric") return "Metric";
    if (unitSystem === "imperial") return "Imperial";
    return "Not selected";
  }

  function formatProfileUpdatedDate(updatedAt) {
    const timestamp = Date.parse(updatedAt || "");
    if (!Number.isFinite(timestamp)) return "Not available";
    return typeof LOCALIZATION.formatDateTime === "function"
      ? LOCALIZATION.formatDateTime(new Date(timestamp), getLocalizationPreferences())
      : new Intl.DateTimeFormat(undefined, { month: "long", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" }).format(new Date(timestamp));
  }

  function hasPrivateNutritionInformation(profile) {
    return buildPrivateNutritionInformation(profile).length > 0;
  }

  function canAttemptNutritionRecalculation(profile) {
    return hasMeaningfulNutritionProfile(profile);
  }

  function buildPrivateNutritionInformation(profile) {
    const canonical = normalizeStoredNutritionProfile(profile);
    if (!canonical) return [];
    const rows = [];
    if (Number.isInteger(canonical.age)) rows.push({ label: "Age", value: String(canonical.age) });
    const height = formatProfileHeight(canonical);
    if (height) rows.push({ label: "Height", value: height });
    const currentWeight = formatProfileWeight(canonical.currentWeightKg, canonical.unitSystem);
    if (currentWeight) rows.push({ label: "Current weight", value: currentWeight });
    const desiredWeight = formatProfileWeight(canonical.desiredWeightKg, canonical.unitSystem);
    if (desiredWeight) {
      rows.push({
        label: "Desired weight",
        value: desiredWeight,
        note: desiredWeightNeedsReview(canonical) ? "This value needs review before Chef Nova can use it for personalized planning." : ""
      });
    }
    if (canonical.goal === "gradual-weight-change") rows.push({ label: "Preferred pace", value: getPreferredPaceDisplayLabel(canonical.preferredPace) });
    const workout = normalizeWorkoutProfile(canonical.workoutProfile);
    if (canonical.goal === "support-workouts" && workout) {
      if (workout.workoutDaysPerWeek !== null) rows.push({ label: "Workout days", value: `${workout.workoutDaysPerWeek} per week` });
      if (workout.typicalWorkoutLength) rows.push({ label: "Workout duration", value: WORKOUT_LENGTH_DISPLAY_LABELS[workout.typicalWorkoutLength] || "Not selected" });
      if (workout.trainingFocus) rows.push({ label: "Workout focus", value: TRAINING_FOCUS_DISPLAY_LABELS[workout.trainingFocus] || "Not selected" });
    }
    return rows;
  }

  function renderPrivateNutritionRows(rows) {
    if (!rows.length) return "";
    return `<dl class="private-nutrition-list">${rows.map((row) => `<div><dt>${escapeHtml(row.label)}</dt><dd>${escapeHtml(row.value)}${row.note ? `<span>${escapeHtml(row.note)}</span>` : ""}</dd></div>`).join("")}</dl>`;
  }

  function formatProfileHeight(profile) {
    if (!Number.isFinite(profile?.heightCm)) return "";
    if (profile.unitSystem === "imperial") {
      const { feet, inches } = centimetresToFeetAndInches(profile.heightCm);
      return Number.isInteger(feet) && Number.isInteger(inches) ? `${feet} ft ${inches} in` : "";
    }
    return `${formatNutritionNumber(profile.heightCm, 0)} cm`;
  }

  function formatProfileWeight(weightKg, unitSystem) {
    if (!Number.isFinite(weightKg)) return "";
    if (unitSystem === "imperial") return `${formatNutritionNumber(kilogramsToPounds(weightKg), 1)} lb`;
    return `${formatNutritionNumber(weightKg, 1)} kg`;
  }

  function getPreferredPaceDisplayLabel(preferredPace) {
    const pace = normalizePreferredPace(preferredPace);
    const labels = {
      "no-specific-pace": "No pace selected",
      "slow-and-gradual": "Gradual",
      "discussed-with-healthcare-professional": "General maintenance planning"
    };
    return labels[pace] || (preferredPace ? "Needs review" : "No pace selected");
  }

  function getNutritionProfileSafetyNotice(safety) {
    if (safety?.requiresProfessionalGuidance) return SPECIALIZED_NUTRITION_NOTICE;
    if (safety?.useMaintenancePlanning) return "Chef Nova is using general meal planning instead of personalized nutrition estimates.";
    return "";
  }

  function toggleBodyMeasurementReference(button) {
    const panelId = button?.getAttribute("aria-controls");
    const panel = panelId ? $("#" + panelId) : null;
    if (!button || !panel) return;
    const expanded = button.getAttribute("aria-expanded") === "true";
    button.setAttribute("aria-expanded", String(!expanded));
    panel.hidden = expanded;
  }

  function nutritionWeightSummaryText(weightKg, unitSystem, hideWeight) {
    if (!Number.isFinite(weightKg)) return "Not provided";
    if (hideWeight) return "Hidden";
    if (unitSystem === "imperial") return `${formatNutritionNumber(kilogramsToPounds(weightKg))} lb`;
    return `${formatNutritionNumber(weightKg)} kg`;
  }

  function nutritionHeightSummaryText(heightCm, unitSystem) {
    if (!Number.isFinite(heightCm)) return "Not provided";
    if (unitSystem === "imperial") {
      const { feet, inches } = centimetresToFeetAndInches(heightCm);
      return Number.isInteger(feet) && Number.isInteger(inches) ? `${feet} ft ${inches} in` : "Not provided";
    }
    return `${formatNutritionNumber(heightCm)} cm`;
  }

  function nutritionCompletenessLabel(completeness) {
    const labels = {
      limited: "Limited information",
      partial: "Partial information",
      "sufficient-for-estimates": "Enough information for estimates"
    };
    return labels[completeness] || "Limited information";
  }

  function togglePrivateNutritionInformation(button) {
    const panelId = button?.getAttribute("aria-controls");
    const panel = panelId ? $("#" + panelId) : null;
    if (!button || !panel) return;
    const expanded = button.getAttribute("aria-expanded") === "true";
    button.setAttribute("aria-expanded", String(!expanded));
    button.textContent = expanded ? "Show Private Information" : "Hide Private Information";
    panel.hidden = expanded;
    if (expanded && panel.contains(document.activeElement) && typeof button.focus === "function") button.focus();
  }

  function recalculateNutritionEstimatesFromProfile(button) {
    const profile = getActiveNutritionProfile();
    if (!profile || !hasMeaningfulNutritionProfile(profile)) {
      showToast("There is not enough information to estimate personalized nutrition ranges. General meal planning remains available.", "info");
      updateProfileNutritionSection();
      return { success: false, safety: evaluateNutritionSafety(createEmptyNutritionProfile()) };
    }
    if (button) {
      button.disabled = true;
      button.textContent = "Recalculating...";
    }
    const safety = evaluateNutritionSafety(profile);
    if (safety.requiresProfessionalGuidance) {
      clearDailyNutritionTarget();
      updateProfileNutritionSection();
      updateWeeklyNutritionSummary();
      showToast(SPECIALIZED_NUTRITION_NOTICE, "warning");
      if (button) {
        button.disabled = false;
        button.textContent = "Recalculate Nutrition Estimates";
      }
      return { success: false, safety };
    }
    if (!safety.canGeneratePersonalizedNutrition || safety.disableEnergyRecommendations || safety.disableMacroRecommendations) {
      clearDailyNutritionTarget();
      updateProfileNutritionSection();
      updateWeeklyNutritionSummary();
      showToast("Personalized nutrition estimates are currently unavailable. General meal planning remains available.", "info");
      if (button) {
        button.disabled = false;
        button.textContent = "Recalculate Nutrition Estimates";
      }
      return { success: false, safety };
    }
    const target = recalculateDailyNutritionTarget(profile);
    updateProfileNutritionSection();
    updateWeeklyNutritionSummary();
    refreshRecipeResults();
    if (button) {
      button.disabled = false;
      button.textContent = "Recalculate Nutrition Estimates";
    }
    if (!target) {
      showToast("There is not enough information to estimate personalized nutrition ranges. General meal planning remains available.", "info");
      return { success: false, safety };
    }
    showToast("Nutrition estimates recalculated.", "success");
    return { success: true, target, safety };
  }

  function deleteNutritionProfile() {
    const message = "This removes your optional body and nutrition profile and personalized nutrition estimates. Your account, recipes, Meal Planner, Nutrition Tracker, Pantry, and optional Weight Progress entries will remain. Optional Weight Progress entries are stored separately and will remain. The user can delete Weight Progress from its own privacy controls.";
    openNutritionConfirm({
      title: "Delete Body and Nutrition Information?",
      message,
      confirmLabel: "Delete Information",
      cancelLabel: "Keep Information",
      danger: true,
      onConfirm: deleteBodyAndNutritionInformation
    });
  }

  function getActiveUserIdentity() {
    if (state.guestMode || isGuestMode()) return { type: "guest", id: "guest" };
    const user = getCurrentUser();
    return user ? { type: "registered", id: user.id } : null;
  }

  function removeNutritionProfile(identity) {
    if (!identity) return;
    if (identity.type === "guest") {
      sessionStorage.removeItem(getGuestNutritionProfileKey());
      return;
    }
    localStorage.removeItem(getNutritionProfileKey(identity.id));
  }

  function removeDerivedNutritionTarget(identity) {
    if (!identity) return;
    if (identity.type === "guest") {
      sessionStorage.removeItem(getGuestNutritionTargetsKey());
      return;
    }
    localStorage.removeItem(getNutritionTargetsKey(identity.id));
  }

  function clearNutritionProfileTemporaryState() {
    state.isEditingProfile = false;
    closeNutritionConfirm();
  }

  function refreshNutritionProfileSummary() {
    if (state.guestMode || isGuestMode()) {
      renderAccountPage();
      return;
    }
    updateProfileNutritionSection();
  }

  function refreshDependentNutritionViews() {
    updateWeeklyNutritionSummary();
    refreshRecipeResults();
    displayMealPlanner();
  }

  function deleteBodyAndNutritionInformation() {
    const activeIdentity = getActiveUserIdentity();
    if (!activeIdentity) return false;
    removeNutritionProfile(activeIdentity);
    removeDerivedNutritionTarget(activeIdentity);
    clearNutritionProfileTemporaryState();
    refreshNutritionProfileSummary();
    refreshDependentNutritionViews();
    showNotification("Body and nutrition information deleted.", "success");
    return true;
  }

  function confirmDeleteNutritionProfile() {
    if (state.guestMode || isGuestMode()) {
      sessionStorage.removeItem(getGuestNutritionProfileKey());
      sessionStorage.removeItem(getGuestNutritionTargetsKey());
      updateProfileNutritionSection();
      renderAccountPage();
      updateWeeklyNutritionSummary();
      showToast("Body and nutrition information deleted.", "success");
      return;
    }
    const user = getCurrentUser();
    if (!user) return;
    localStorage.removeItem(getNutritionProfileKey(user.id));
    localStorage.removeItem(getNutritionTargetsKey(user.id));
    updateProfileNutritionSection();
    updateWeeklyNutritionSummary();
    showToast("Body and nutrition information deleted.", "success");
  }

  function toggleWeightVisibility() {
    const profile = getActiveNutritionProfile() || createEmptyNutritionProfile();
    profile.hideWeightInformation = !profile.hideWeightInformation;
    saveCurrentNutritionProfile(profile);
    updateProfileNutritionSection();
    renderAccountPage();
    showToast(profile.hideWeightInformation ? "Weight information hidden." : "Weight information visible.", "success");
  }

  function resetNutritionGoals() {
    const profile = getActiveNutritionProfile();
    if (!profile) return showToast("No nutrition profile to reset.", "info");
    openNutritionConfirm({
      title: "Reset nutrition goals?",
      message: "This will remove your saved goal, desired weight, preferred pace, reason, and Workout Support information. Other nutrition profile information will stay saved.",
      confirmLabel: "Reset",
      danger: false,
      onConfirm: confirmResetNutritionGoals
    });
  }

  function confirmResetNutritionGoals() {
    const profile = getActiveNutritionProfile();
    if (!profile) return showToast("No nutrition profile to reset.", "info");
    profile.goal = null;
    profile.desiredWeightKg = null;
    profile.weightGoalReason = null;
    profile.preferredPace = null;
    profile.workoutProfile = null;
    profile.profileCompleteness = evaluateNutritionProfileCompleteness(profile);
    profile.updatedAt = getCurrentIsoString();
    saveCurrentNutritionProfile(profile);
    recalculateDailyNutritionTarget(profile);
    updateProfileNutritionSection();
    renderAccountPage();
    updateWeeklyNutritionSummary();
    showToast("Nutrition goals reset.", "success");
  }

  function getCurrentUser() {
    const currentUserId = getCurrentUserId();
    if (!currentUserId) return null;
    const currentUser = state.users.find((candidate) => candidate.id === currentUserId) || null;
    if (!currentUser) {
      clearCurrentUserSession();
      state.currentUser = null;
      return null;
    }
    state.currentUser = currentUser;
    return currentUser;
  }

  function createProfileEditDraftFromUser(user) {
    return {
      userId: user?.id || "",
      name: user?.name || "",
      email: user?.email || "",
      age: user?.age || "",
      gender: user?.gender || "",
      phone: user?.phone || "",
      dietaryPreference: user?.dietaryPreference || "",
      allergies: formatAllergiesForInput(user?.allergies)
    };
  }

  function getProfileEditDraft(user) {
    if (!state.profileEditDraft || state.profileEditDraft.userId !== user.id) {
      state.profileEditDraft = createProfileEditDraftFromUser(user);
    }
    return state.profileEditDraft;
  }

  function captureProfileEditDraft() {
    const form = $("#profileEditForm");
    const user = getCurrentUser();
    if (!form || !user || !state.isEditingProfile) return;
    const data = new FormData(form);
    state.profileEditDraft = {
      userId: user.id,
      name: String(data.get("name") || ""),
      email: String(data.get("email") || ""),
      age: String(data.get("age") || ""),
      gender: String(data.get("gender") || ""),
      phone: String(data.get("phone") || ""),
      dietaryPreference: String(data.get("dietaryPreference") || ""),
      allergies: String(data.get("allergies") || "")
    };
  }

  function renderProfileEditForm(user) {
    const draft = getProfileEditDraft(user);
    return `<form class="profile-edit-form" id="profileEditForm">
      <div class="form-heading"><h2>Edit Profile</h2><p>Update your account information, dietary preference, and allergies.</p></div>
      <div class="form-grid two">
        <label>Name<input name="name" required autocomplete="name" value="${escapeHtml(draft.name)}" placeholder="Your name"></label>
        <label>Email<input name="email" type="email" required autocomplete="email" value="${escapeHtml(draft.email)}" placeholder="you@example.com"></label>
      </div>
      <div class="form-grid two">
        <label>Age<input name="age" type="number" min="1" max="120" step="1" required value="${escapeHtml(draft.age)}" placeholder="Age"></label>
        <label>Gender<select name="gender" required>${profileOptions(["Woman", "Man", "Non-binary", "Prefer not to say", "Self-describe"], draft.gender, "Select")}</select></label>
      </div>
      <div class="form-grid two">
        <label>Phone <small>(optional)</small><input name="phone" type="tel" autocomplete="tel" value="${escapeHtml(draft.phone)}" placeholder="Phone number"></label>
        <label>Dietary preference<select name="dietaryPreference" required>${profileOptions(["No preference", "Vegetarian", "Vegan", "Pescatarian", "Gluten-free", "Halal", "Kosher", "Other"], draft.dietaryPreference, "Select a preference")}</select></label>
      </div>
      <label>Allergies<textarea name="allergies" rows="3" placeholder="List allergies, or write None">${escapeHtml(draft.allergies)}</textarea></label>
      <p class="form-message" id="profileEditMessage" aria-live="polite"></p>
      <div class="profile-form-actions">
        <button class="button primary" type="submit">Save Changes</button>
        <button class="button secondary" type="button" data-profile-cancel>Cancel</button>
      </div>
    </form>`;
  }

  function renderPasswordChangeForm() {
    return `<form class="profile-edit-form password-change-form" id="passwordChangeForm">
      <div class="form-heading"><h2>Change Password</h2><p>Enter your current password, then choose a new password.</p></div>
      <div class="form-grid two">
        <label>Current password<span class="password-field"><input name="currentPassword" type="password" autocomplete="current-password" required placeholder="Current password"><button class="password-toggle" type="button" data-toggle-password aria-pressed="false" aria-label="Show password"><span class="password-toggle-icon" aria-hidden="true"></span></button></span></label>
        <label>New password<span class="password-field"><input name="newPassword" type="password" autocomplete="new-password" required minlength="8" placeholder="At least 8 characters"><button class="password-toggle" type="button" data-toggle-password aria-pressed="false" aria-label="Show password"><span class="password-toggle-icon" aria-hidden="true"></span></button></span></label>
      </div>
      <label>Confirm new password<span class="password-field"><input name="confirmPassword" type="password" autocomplete="new-password" required minlength="8" placeholder="Re-enter new password"><button class="password-toggle" type="button" data-toggle-password aria-pressed="false" aria-label="Show confirm password"><span class="password-toggle-icon" aria-hidden="true"></span></button></span></label>
      <p class="form-message" id="passwordChangeMessage" aria-live="polite"></p>
      <div class="profile-form-actions">
        <button class="button primary" type="submit">Save Password</button>
        <button class="button secondary" type="button" data-password-cancel>Cancel</button>
      </div>
    </form>`;
  }

  function profileOptions(options, selected, placeholder) {
    return [`<option value="">${escapeHtml(placeholder)}</option>`].concat(options.map((option) => `<option value="${escapeHtml(option)}" ${option === selected ? "selected" : ""}>${escapeHtml(option)}</option>`)).join("");
  }

  function showProfileEditor() {
    if (!requireAccount("save your profile information")) return;
    state.profileEditDraft = createProfileEditDraftFromUser(getCurrentUser());
    state.isEditingProfile = true;
    renderAccountPage();
    const input = $("#profileEditForm input[name='name']");
    if (input) input.focus();
  }

  function cancelProfileEdit() {
    state.isEditingProfile = false;
    state.profileEditDraft = null;
    renderAccountPage();
    showToast("Changes cancelled", "info");
  }

  function showPasswordEditor() {
    if (!requireAccount("save your profile information")) return;
    state.isChangingPassword = true;
    renderAccountPage();
    const input = $("#passwordChangeForm input[name='currentPassword']");
    if (input) input.focus();
  }

  function cancelPasswordEdit() {
    state.isChangingPassword = false;
    renderAccountPage();
    showToast("Changes cancelled", "info");
  }

  function saveProfileChanges(event) {
    event.preventDefault();
    if (!requireAccount("save your profile information")) return;
    const user = getCurrentUser();
    if (!user) return showToast("Unable to update profile", "error");
    const data = new FormData(event.currentTarget);
    const updated = {
      name: data.get("name").trim(),
      email: normalizeEmail(data.get("email")),
      age: Number(data.get("age")),
      gender: data.get("gender"),
      phone: data.get("phone").trim(),
      dietaryPreference: data.get("dietaryPreference"),
      allergies: normalizeAllergies(data.get("allergies"))
    };
    const error = validateProfileUpdate(updated, user.id);
    if (error) {
      $("#profileEditMessage").textContent = error;
      showToast(error, "error");
      return;
    }
    const index = state.users.findIndex((candidate) => candidate.id === user.id);
    if (index < 0) return showToast("Unable to update profile", "error");
    state.users[index] = { ...state.users[index], ...updated };
    saveRegisteredUsers(state.users);
    state.currentUser = state.users[index];
    setCurrentUserId(user.id);
    state.isEditingProfile = false;
    state.profileEditDraft = null;
    renderAccount();
    renderAccountPage();
    searchRecipes();
    showToast("Profile updated successfully", "success", { saveToHistory: true, actionName: "View Profile", actionTarget: "account" });
  }

  function savePasswordChange(event) {
    event.preventDefault();
    if (!requireAccount("save your profile information")) return;
    const user = getCurrentUser();
    if (!user) return showToast("Unable to update profile", "error");
    const data = new FormData(event.currentTarget);
    const currentPassword = data.get("currentPassword");
    const newPassword = data.get("newPassword");
    const confirmPassword = data.get("confirmPassword");
    const messageTarget = $("#passwordChangeMessage");
    if (currentPassword !== user.password) return showProfileFormError(messageTarget, "Current password is incorrect");
    if (!newPassword || newPassword.length < MIN_PASSWORD_LENGTH) return showProfileFormError(messageTarget, "New password does not meet the requirements");
    if (newPassword !== confirmPassword) return showProfileFormError(messageTarget, "New passwords do not match");
    const index = state.users.findIndex((candidate) => candidate.id === user.id);
    if (index < 0) return showToast("Unable to update profile", "error");
    state.users[index] = { ...state.users[index], password: newPassword };
    saveRegisteredUsers(state.users);
    event.currentTarget.reset();
    state.isChangingPassword = false;
    renderAccountPage();
    showToast("Password changed successfully", "success");
  }

  function validateProfileUpdate(profile, userId) {
    if (!profile.name) return "Please enter a valid name";
    if (!isValidEmail(profile.email)) return "Please enter a valid email address";
    if (state.users.some((user) => user.id !== userId && normalizeEmail(user.email) === profile.email)) return "This email is already in use";
    if (!Number.isInteger(profile.age) || profile.age < 1 || profile.age > 120) return "Please enter a valid age";
    if (!profile.gender) return "Please enter all required fields";
    if (profile.phone && !isValidPhone(profile.phone)) return "Please enter a valid phone number";
    if (!profile.dietaryPreference) return "Please enter all required fields";
    return "";
  }

  function showProfileFormError(target, message) {
    if (target) target.textContent = message;
    showToast(message, "error");
  }

  /* Search every recipe from the data file, then apply filters and sort by match percentage. */
  function searchRecipes(options = {}) {
    const userIngredients = parseIngredientInput($("#recipeSearch").value);
    if (options.requireIngredients && !userIngredients.length) {
      showToast("Please enter at least one ingredient", "error");
      return;
    }
    const matched = state.recipes.map((recipe) => calculateRecipeMatch(userIngredients, normalizeRecipe(recipe)));
    const context = buildPersonalizedRecipeContext();
    updatePersonalizedRecipeFilterAvailability(context);
    const selectedFilters = getSelectedPersonalizedRecipeFilters();
    state.personalizedRecipeFilters.selected = selectedFilters;
    const baseFiltered = filterRecipes(matched);
    const filteredResults = applyPersonalizedRecipeFilters(baseFiltered, selectedFilters, context);
    const results = state.foodRescueRankingRequest
      ? applyFoodRescueRecipeRanking(filteredResults, state.foodRescueRankingRequest, context)
      : sortRecipesByMatch(filteredResults, context);
    displayRecipeResults(results);
    updateRecipeResultStatus(results.length, selectedFilters, context);
    if (options.notify && !results.length) showToast("No matching recipes found", "warning", { saveToHistory: true, actionName: "View Recipes", actionTarget: "recipes" });
    if (options.notify && results.some(recipeContainsUserAllergy)) showToast("This recipe contains one or more of your allergies", "warning", { saveToHistory: true, actionName: "View Recipes", actionTarget: "recipes" });
  }

  function refreshRecipeResults() {
    searchRecipes();
  }

  function updateRecipeFilters() {
    const maxTimeInput = $("#recipeMaxTimeFilter");
    const maxTimeValue = maxTimeInput.value.trim();
    if (maxTimeValue && (!Number.isInteger(Number(maxTimeValue)) || Number(maxTimeValue) < 1)) {
      maxTimeInput.setCustomValidity("Please enter a valid cooking time in minutes.");
      maxTimeInput.reportValidity();
      showToast("Please enter a valid cooking time in minutes.", "error");
      return;
    }
    maxTimeInput.setCustomValidity("");
    state.recipeFilters = {
      category: $("#recipeCategoryFilter").value || "All",
      cuisine: $("#recipeCuisineFilter").value || "All",
      difficulty: $("#recipeDifficultyFilter").value || "All",
      maxTime: maxTimeValue,
      dietary: $("#recipeDietaryFilter").value || "All",
      hideAllergies: $("#hideAllergyRecipesFilter").checked
    };
    searchRecipes();
  }

  function createEmptyPersonalizedRecipeFilterState() {
    return {
      selected: [],
      enabled: true
    };
  }

  function getSelectedPersonalizedRecipeFilters() {
    return $$("[data-personalized-recipe-filter]:checked")
      .map((element) => element.value)
      .filter((value) => Object.values(PERSONALIZED_RECIPE_FILTERS).includes(value));
  }

  function updatePersonalizedRecipeFilters() {
    state.personalizedRecipeFilters.selected = getSelectedPersonalizedRecipeFilters();
    refreshRecipeResults();
  }

  function clearPersonalizedRecipeFilters() {
    $$("[data-personalized-recipe-filter]").forEach((input) => {
      input.checked = false;
    });
    state.personalizedRecipeFilters = createEmptyPersonalizedRecipeFilterState();
    refreshRecipeResults();
  }

  function parseIngredientInput(value) {
    return String(value || "").split(",").map((item) => item.trim()).filter(Boolean);
  }

  function getIngredientAliases(ingredient) {
    const normalized = normalizeIngredient(ingredient);
    const aliases = ingredientAliases[normalized] || [];
    const reverseMatches = Object.entries(ingredientAliases).filter(([, values]) => values.map(normalizeIngredient).includes(normalized)).map(([key]) => key);
    const canonical = resolveCanonicalIngredientName(ingredient);
    const catalogueAliases = canonical.status === "resolved"
      ? (state.ingredientCatalogue.ingredients.find((entry) => entry.id === canonical.ingredientId)?.aliases || []).map(normalizeIngredient)
      : [];
    return Array.from(new Set([normalized, canonical.ingredientId, ...catalogueAliases, ...aliases.map(normalizeIngredient), ...reverseMatches].filter(Boolean)));
  }

  function ingredientsMatch(userIngredient, recipeIngredient) {
    const userNames = getIngredientAliases(userIngredient);
    const recipeNames = getIngredientAliases(recipeIngredient);
    return userNames.some((userName) => recipeNames.some((recipeName) => userName === recipeName || userName.includes(recipeName) || recipeName.includes(userName)));
  }

  function calculateRecipeMatch(userIngredients, recipe) {
    const required = recipe.ingredients;
    const matchedIngredients = required.filter((ingredient) => userIngredients.some((userIngredient) => ingredientsMatch(userIngredient, ingredient.name)));
    const missingIngredients = required.filter((ingredient) => !matchedIngredients.some((matched) => normalizeIngredient(matched.name) === normalizeIngredient(ingredient.name)));
    const matchPercentage = required.length ? Math.round((matchedIngredients.length / required.length) * 100) : 0;
    return { ...recipe, matchedIngredients, missingIngredients, matchPercentage, matchScore: matchedIngredients.length, matchLevel: getMatchLevel(matchPercentage) };
  }

  function filterRecipes(recipes) {
    const filters = state.recipeFilters;
    const maxTime = Number(filters.maxTime);
    const personalizedActive = getSelectedPersonalizedRecipeFilters().length > 0;
    return recipes.filter((recipe) => {
      if (filters.category !== "All" && recipe.category !== filters.category) return false;
      if (filters.cuisine !== "All" && recipe.cuisine !== filters.cuisine) return false;
      if (filters.difficulty !== "All" && recipe.difficulty !== filters.difficulty) return false;
      if (filters.dietary !== "All" && !recipe.dietaryTags.some((tag) => normalizeIngredient(tag) === normalizeIngredient(filters.dietary))) return false;
      if (filters.maxTime && recipe.cookingTime > maxTime) return false;
      if ((filters.hideAllergies || personalizedActive) && !isRecipeSafeForUser(recipe, state.currentUser)) return false;
      if (personalizedActive && !matchesDietaryPreferences(recipe, state.currentUser)) return false;
      return true;
    });
  }

  function isRecipeSafeForUser(recipe, userProfile = state.currentUser) {
    const result = evaluateRecipeForCurrentRequirements(recipe, { userProfile }, { includeCookingConstraints: false, includeServingConstraints: false, includeIngredientAvailability: false, includeDietaryRequirements: false });
    return result.canUseForAutomaticPlanning;
  }

  function matchesDietaryPreferences(recipe, userProfile = state.currentUser) {
    const preference = String((userProfile && userProfile.dietaryPreference) || getUserDietaryPreference() || "").trim();
    if (!preference || preference === "No preference") return true;
    return recipe.dietaryTags.some((tag) => normalizeIngredient(tag) === normalizeIngredient(preference));
  }

  function normalizeDietaryRequirement(value) {
    const normalized = normalizeIngredient(value);
    const aliases = {
      "no-preference": "",
      halal: "halal-friendly",
      "halal-friendly": "halal-friendly",
      "gluten-free": "gluten-free",
      glutenfree: "gluten-free",
      "dairy-free": "dairy-free",
      dairyfree: "dairy-free"
    };
    return aliases[normalized] ?? normalized;
  }

  function normalizeSavedAllergenIds(allergies = []) {
    const normalizer = RECIPE_ELIGIBILITY.normalizeAllergenId || normalizeIngredient;
    return normalizeAllergies(allergies).map(normalizer).filter(Boolean);
  }

  function resolvePreferenceIngredientIds(values = []) {
    return parsePreferenceText(Array.isArray(values) ? values.join(",") : values).map((item) => {
      const resolved = resolveCanonicalIngredientName(item);
      return resolved.status === "resolved" ? resolved.ingredientId : normalizeIngredient(item);
    }).filter(Boolean);
  }

  function buildRecipeEligibilityContext(sourceContext = {}, options = {}) {
    const userProfile = sourceContext.userProfile || options.userProfile || state.currentUser || getCurrentUser();
    const preferences = sourceContext.mealPlanPreferences || sourceContext.preferredMeals || getMealPlanningPreferences();
    const planningInputs = sourceContext.planningModeInputs || normalizePlanningModeInputs(state.planningModeInputs);
    const budget = planningInputs.budgetRescue || createEmptyBudgetRescueDraft();
    const includeCooking = options.includeCookingConstraints !== false;
    const includeServing = options.includeServingConstraints !== false;
    const requiredServings = Number(options.requiredServings || sourceContext.requiredServings || budget.household?.suggestedServings || 1);
    const availableAppliances = Array.isArray(sourceContext.availableAppliances)
      ? sourceContext.availableAppliances
      : getCurrentPlanningMode() === PLANNING_MODES.BUDGET_RESCUE || sourceContext.planningMode === PLANNING_MODES.BUDGET_RESCUE
        ? budget.availableAppliances || []
        : [];
    return {
      profileRevision: `${userProfile?.id || "guest"}:${normalizeSavedAllergenIds(userProfile?.allergies).join("|")}:${normalizeDietaryRequirement(userProfile?.dietaryPreference || "")}`,
      allergies: { allergenIds: normalizeSavedAllergenIds(userProfile?.allergies), avoidCrossContact: false },
      dietaryRequirements: options.includeDietaryRequirements === false ? [] : [normalizeDietaryRequirement(userProfile?.dietaryPreference || "")].filter(Boolean),
      availableAppliances: includeCooking ? availableAppliances : [],
      maximumCookingTimeMinutes: includeCooking ? preferences.maximumCookingMinutes || null : null,
      requiredServings: includeServing && Number.isFinite(requiredServings) && requiredServings > 0 ? requiredServings : 1,
      ingredientAvailability: options.includeIngredientAvailability === false ? { explicitlyUnavailableIngredientIds: [], explicitlyUnavailableNames: [], purchasePolicy: "allow-grocery-purchases" } : {
        explicitlyUnavailableIngredientIds: Array.from(new Set([...resolvePreferenceIngredientIds(preferences.foodsToAvoid || []), ...getExpiredConfirmedIngredientIds(), ...getFoodSafetyExcludedIngredientIds()])),
        explicitlyUnavailableNames: parsePreferenceText((preferences.foodsToAvoid || []).join ? preferences.foodsToAvoid.join(",") : preferences.foodsToAvoid),
        explicitlyAvailableIngredientIds: getActivePantryItems().map((item) => item.ingredientId).filter(Boolean),
        purchasePolicy: "allow-grocery-purchases"
      },
      foodSafetyGuardrail: {
        schemaVersion: FOOD_SAFETY_GUARDRAIL_VERSION,
        excludedIngredientIds: getFoodSafetyExcludedIngredientIds(),
        policyCoverage: getFoodSafetyPolicyCoverage(),
        hardExclusionsCannotBeOverridden: true
      },
      selectedRescueSources: Array.isArray(options.selectedRescueSources) ? options.selectedRescueSources : Array.isArray(sourceContext.selectedRescueSources) ? sourceContext.selectedRescueSources : [],
      preparedLeftoverSources: (Array.isArray(options.selectedRescueSources) ? options.selectedRescueSources : Array.isArray(sourceContext.selectedRescueSources) ? sourceContext.selectedRescueSources : []).filter((source) => source.sourceType === RESCUE_SOURCE_TYPES.PREPARED_LEFTOVER),
      pantryContext: {
        pantryRevision: PANTRY_FIRST.pantryRevision ? PANTRY_FIRST.pantryRevision(getActivePantryItems()) : "",
        pantryItems: Array.isArray(options.pantryItems) ? options.pantryItems : getActivePantryItems()
      },
      leftoverContext: sourceContext.leftoverContext || options.leftoverContext || { selectedLeftovers: [], leftoverRevision: "" },
      substitutionContext: {
        ruleIds: state.substitutionIndexes?.rules?.map((rule) => rule.ruleId).filter(Boolean) || [],
        rules: state.substitutionIndexes?.rules || []
      },
      requireStructuredQuantities: options.requireStructuredQuantities === true,
      selectedOptionalIngredients: {},
      planningMode: sourceContext.planningMode || getCurrentPlanningMode(),
      planDate: getCurrentDateString()
    };
  }

  function evaluateRecipeForCurrentRequirements(recipe, sourceContext = {}, options = {}) {
    if (typeof RECIPE_ELIGIBILITY.evaluateRecipeEligibility !== "function") {
      const allergySafe = !recipeContainsUserAllergy(recipe, sourceContext.userProfile || state.currentUser);
      const dietarySafe = matchesDietaryPreferences(recipe, sourceContext.userProfile || state.currentUser);
      return { recipeId: recipe?.id || "", status: allergySafe && dietarySafe ? RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE : RECIPE_ELIGIBILITY_STATUSES.INELIGIBLE, canUseForAutomaticPlanning: allergySafe && dietarySafe, exclusionReasons: [] };
    }
    return RECIPE_ELIGIBILITY.evaluateRecipeEligibility({
      recipe: normalizeRecipe(recipe),
      eligibilityContext: buildRecipeEligibilityContext(sourceContext, options),
      ingredientCatalogue: state.ingredientCatalogue
    });
  }

  function isRecipeEligibleForAutomaticPlanning(recipe, context, options = {}) {
    return evaluateRecipeForCurrentRequirements(recipe, context, options).status === RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE;
  }

  function applyPersonalizedRecipeFilters(recipes, selectedFilters = getSelectedPersonalizedRecipeFilters(), context = buildPersonalizedRecipeContext()) {
    const availableFilters = selectedFilters.filter((filter) => getPersonalizedFilterAvailability(filter, context).enabled);
    return recipes.filter((recipe) => availableFilters.every((filter) => {
      switch (filter) {
        case PERSONALIZED_RECIPE_FILTERS.FITS_NUTRITION_RANGE:
          return doesRecipeFitNutritionRange(recipe, context);
        case PERSONALIZED_RECIPE_FILTERS.HIGHER_PROTEIN:
          return isHigherProteinRecipe(recipe);
        case PERSONALIZED_RECIPE_FILTERS.BALANCED_MEAL:
          return isBalancedMealRecipe(recipe);
        case PERSONALIZED_RECIPE_FILTERS.WORKOUT_FRIENDLY:
          return isWorkoutFriendlyRecipe(recipe, context);
        case PERSONALIZED_RECIPE_FILTERS.VEGETABLE_RICH:
          return isVegetableRichRecipe(recipe);
        case PERSONALIZED_RECIPE_FILTERS.HIGHER_FIBRE:
          return isHigherFibreRecipe(recipe);
        case PERSONALIZED_RECIPE_FILTERS.LOWER_ADDED_SUGAR:
          return isLowerAddedSugarRecipe(recipe);
        case PERSONALIZED_RECIPE_FILTERS.QUICK_MEAL:
          return isQuickMealRecipe(recipe);
        default:
          return true;
      }
    }));
  }

  function sortRecipesByMatch(recipes, context = buildPersonalizedRecipeContext()) {
    const timeValue = (recipe) => Number.isFinite(getRecipeTotalMinutes(recipe)) ? getRecipeTotalMinutes(recipe) : Number.MAX_SAFE_INTEGER;
    return [...recipes].sort((a, b) => b.matchPercentage - a.matchPercentage || a.missingIngredients.length - b.missingIngredients.length || calculatePantryMatch(b, context.pantryItems).percentage - calculatePantryMatch(a, context.pantryItems).percentage || timeValue(a) - timeValue(b) || calculatePersonalizedRecipeScore(b, context).total - calculatePersonalizedRecipeScore(a, context).total || getRecipeNutritionTagScore(b) - getRecipeNutritionTagScore(a) || a.name.localeCompare(b.name));
  }

  function createFoodRescueRankingRequest(selectedEntries = [], options = {}) {
    const normalizedEntries = selectedEntries.map((entry) => ({
      rescueSourceId: entry.rescueSourceId,
      sourceType: entry.sourceType,
      pantryItemId: entry.pantryItemId || null,
      preparedLeftoverId: entry.preparedLeftoverId || null,
      ingredientId: entry.ingredientId || null,
      displayName: entry.displayName,
      priorityLevel: entry.priorityLevel || entry.rescueRecipePriority?.priorityLevel || USE_FIRST_PRIORITY_LEVELS.MONITOR,
      rescueRecipePriorityScore: entry.rescueRecipePriority?.score ?? entry.rescueRecipePriorityScore ?? null,
      recommendationGoal: entry.recommendationGoal || null,
      sourceRecipeCandidateId: entry.sourceRecipeCandidateId || null,
      projectedRemainder: entry.projectedRemainder && typeof entry.projectedRemainder === "object" ? structuredCloneSafe(entry.projectedRemainder) : null,
      availableQuantity: entry.availableQuantity,
      currentQuantity: entry.currentQuantity,
      unit: entry.unit || entry.projectedRemainder?.unit || "",
      selectedAt: state.useFirstPanelDraft?.selectedAtBySourceId?.[entry.rescueSourceId] || getCurrentIsoString()
    })).filter((entry) => entry.rescueSourceId);
    return {
      profile: FOOD_RESCUE_RANKING_PROFILE,
      rankingVersion: FOOD_RESCUE_RECIPE_RANKING_VERSION,
      scoreConfigurationVersion: FOOD_RESCUE_RECIPE_SCORE_CONFIGURATION_VERSION,
      createdAt: getCurrentIsoString(),
      userScope: state.guestMode ? "guest" : getActiveUserId() || "none",
      source: options.source || "use-these-first-panel",
      householdContext: { requiredServings: getFoodRescueRequiredServings() },
      selectedRescueSources: normalizedEntries
    };
  }

  function getFoodRescueRequiredServings() {
    const planned = Number(normalizePlanningModeInputs(state.planningModeInputs).budgetRescue?.household?.suggestedServings);
    return Number.isFinite(planned) && planned > 0 ? planned : 1;
  }

  function revalidateFoodRescueSelectedSources(request) {
    const selectedIds = uniqueCleanIds((request?.selectedRescueSources || []).map((source) => source.rescueSourceId));
    const requestedSourceById = new Map((request?.selectedRescueSources || []).map((source) => [source.rescueSourceId, source]));
    const panel = validateUseFirstPanelSelection(selectedIds);
    const validEntries = panel.validEntries.map((entry) => {
      const normalized = normalizeFoodRescueSourceFromPanelEntry(entry);
      const requestedSource = requestedSourceById.get(entry.rescueSourceId);
      if (!normalized || requestedSource?.recommendationGoal !== "use-projected-remainder") return normalized;
      const projectedQuantity = Number(requestedSource.projectedRemainder?.quantity ?? requestedSource.availableQuantity);
      if (!Number.isFinite(projectedQuantity) || projectedQuantity <= 0) return null;
      const cappedQuantity = Math.min(Number(normalized.availableQuantity) || 0, projectedQuantity);
      const comparable = COST_ENGINE.normalizeComparableQuantity?.(cappedQuantity, requestedSource.projectedRemainder?.unit || normalized.unit);
      return {
        ...normalized,
        availableQuantity: cappedQuantity,
        currentQuantity: cappedQuantity,
        comparableQuantity: comparable?.valid ? comparable.quantity : null,
        comparableUnit: comparable?.valid ? comparable.unit : normalized.comparableUnit,
        comparableDimension: comparable?.valid ? comparable.dimension : normalized.comparableDimension,
        recommendationGoal: "use-projected-remainder",
        sourceRecipeCandidateId: requestedSource.sourceRecipeCandidateId || null
      };
    }).filter(Boolean);
    const validIds = new Set(validEntries.map((source) => source.rescueSourceId));
    const rejectedSources = selectedIds.filter((id) => !validIds.has(id)).map((id) => ({ rescueSourceId: id, reason: "Source no longer has safe, measurable quantity for recipe ranking." }));
    return { validSources: validEntries, rejectedSources, panelModel: panel.model, staleIds: panel.staleIds };
  }

  function normalizeFoodRescueSourceFromPanelEntry(entry) {
    if (entry.sourceType === RESCUE_SOURCE_TYPES.PREPARED_LEFTOVER) {
      const leftover = getPreparedLeftoverBatchById(entry.leftoverBatchId || entry.pantryItemId);
      if (!leftover) return null;
      const guardrail = getFoodSafetyGuardrailForPantryItem(leftover);
      const quantity = calculateUseFirstQuantitySummary(leftover);
      if (!guardrail.canUseForAutomaticPlanning || guardrail.hardExclusion || guardrail.requiresUserReview) return null;
      if (quantity.quantityStatus === PANTRY_QUANTITY_STATUSES.UNKNOWN || quantity.availableQuantity === null || Number(quantity.availableQuantity) <= 0) return null;
      const comparable = COST_ENGINE.normalizeComparableQuantity?.(quantity.availableQuantity, quantity.unit);
      return {
        rescueSourceId: getRescueSourceId(RESCUE_SOURCE_TYPES.PREPARED_LEFTOVER, leftover.id),
        sourceType: RESCUE_SOURCE_TYPES.PREPARED_LEFTOVER,
        pantryItemId: leftover.id,
        leftoverBatchId: leftover.id,
        preparedLeftoverId: leftover.id,
        ingredientId: null,
        displayName: leftover.displayName || leftover.name || "Prepared leftover",
        form: PANTRY_ITEM_FORMS.PREPARED,
        priorityLevel: USE_FIRST_PRIORITY_LEVELS.MEDIUM,
        rescueRecipePriorityScore: entry.priority?.rescueRecipeScore || 40,
        foodSafetyDecision: guardrail.decision || null,
        currentQuantity: quantity.currentQuantity,
        reservedQuantity: quantity.reservedQuantity || 0,
        availableQuantity: quantity.availableQuantity,
        availableServings: leftover.leftoverBatch?.servings?.currentServings ?? quantity.availableQuantity,
        unit: quantity.unit || "serving",
        comparableQuantity: comparable?.valid ? comparable.quantity : null,
        comparableUnit: comparable?.valid ? comparable.unit : quantity.unit || "serving",
        comparableDimension: comparable?.valid ? comparable.dimension : null,
        quantityStatus: quantity.quantityStatus,
        requiresTransformationRule: true,
        transformationRuleId: null,
        reusableAfterReheat: false,
        reheated: selectFoodEventsForLeftoverBatch({ leftoverBatchId: leftover.id }).some((event) => event.eventType === FOOD_EVENT_TYPES.REHEATED),
        lineageValid: leftover.leftoverBatch?.lineage?.rootMealIds?.length > 0,
        lineageRequired: true,
        sourceRevision: `${leftover.updatedAt || leftover.createdAt || ""}:${quantity.availableQuantity}:${quantity.unit || ""}`
      };
    }
    const pantryItem = state.pantry.find((item) => item.id === entry.pantryItemId);
    if (!pantryItem) return null;
    const latest = deriveUseFirstPriorityForPantryItem(pantryItem);
    const quantity = latest.quantitySummary || {};
    if (!latest.foodSafety?.canUseForAutomaticPlanning || latest.rescueRecipePriority?.score === null) return null;
    if (quantity.quantityStatus === PANTRY_QUANTITY_STATUSES.UNKNOWN || quantity.availableQuantity === null || Number(quantity.availableQuantity) <= 0) return null;
    const comparable = COST_ENGINE.normalizeComparableQuantity?.(quantity.availableQuantity, quantity.unit);
    return {
      rescueSourceId: getRescueSourceId(RESCUE_SOURCE_TYPES.PANTRY_ITEM, pantryItem.id),
      sourceType: RESCUE_SOURCE_TYPES.PANTRY_ITEM,
      pantryItemId: pantryItem.id,
      ingredientId: pantryItem.ingredientId || resolveCanonicalIngredientName(pantryItem.name).ingredientId || null,
      displayName: pantryItem.displayName || pantryItem.name || "Pantry item",
      form: pantryItem.form || null,
      priorityLevel: latest.rescueRecipePriority.priorityLevel || useFirstPriorityLevel(latest.rescueRecipePriority.score),
      rescueRecipePriorityScore: latest.rescueRecipePriority.score,
      foodSafetyDecision: latest.foodSafety.decision || null,
      dateSummary: latest.dateIntelligence || null,
      currentQuantity: quantity.currentQuantity,
      reservedQuantity: quantity.reservedQuantity || 0,
      availableQuantity: quantity.availableQuantity,
      unit: quantity.unit || pantryItem.unit || "each",
      comparableQuantity: comparable?.valid ? comparable.quantity : null,
      comparableUnit: comparable?.valid ? comparable.unit : quantity.unit || pantryItem.unit || "each",
      comparableDimension: comparable?.valid ? comparable.dimension : null,
      quantityStatus: quantity.quantityStatus,
      sourceRevision: `${pantryItem.updatedAt || pantryItem.createdAt || ""}:${quantity.availableQuantity}:${quantity.unit || ""}`
    };
  }

  function applyFoodRescueRecipeRanking(recipes, request, context = buildPersonalizedRecipeContext()) {
    const validated = revalidateFoodRescueSelectedSources(request);
    if (!validated.validSources.length) {
      state.foodRescueRankingRequest = null;
      state.foodRescueRankingResults = [];
      return sortRecipesByMatch(recipes, context);
    }
    const candidates = request?.excludeRecipeId ? recipes.filter((recipe) => recipe.id !== request.excludeRecipeId) : recipes;
    const ranked = candidates.map((recipe) => rankRecipeForFoodRescue(recipe, validated.validSources, request, context)).filter(Boolean).sort(compareFoodRescueRecipeResults);
    state.foodRescueRankingResults = ranked;
    return ranked.length ? ranked.map((item) => ({ ...item.recipe, foodRescueRanking: item })) : sortRecipesByMatch(recipes, context);
  }

  function rankRecipeForFoodRescue(recipe, sources, request, context) {
    const normalizedRecipe = normalizeRecipe(recipe);
    const selectedServings = Number(request?.householdContext?.requiredServings) || normalizedRecipe.servings || 1;
    const initialEligibility = evaluateRecipeForCurrentRequirements(normalizedRecipe, { userProfile: context.userProfile, selectedRescueSources: sources, planningMode: PLANNING_MODES.COOK_BEFORE_IT_SPOILS }, { includeIngredientAvailability: true, requiredServings: selectedServings, selectedRescueSources: sources, pantryItems: getActivePantryItems(), requireStructuredQuantities: true });
    if (initialEligibility.status !== RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE && initialEligibility.canUseForAutomaticPlanning !== true) return null;
    const scaleResult = createFoodRescuePracticalScalePreview(normalizedRecipe, selectedServings);
    if (!scaleResult || scaleResult.status === "unsupported") return null;
    const practicalRecipe = normalizeRecipe(scaleResult.scaledRecipe || normalizedRecipe);
    const practicalServings = Number(scaleResult.effectiveServings) || selectedServings;
    const eligibility = evaluateRecipeForCurrentRequirements(practicalRecipe, { userProfile: context.userProfile, selectedRescueSources: sources, planningMode: PLANNING_MODES.COOK_BEFORE_IT_SPOILS }, { includeIngredientAvailability: true, requiredServings: practicalServings, selectedRescueSources: sources, pantryItems: getActivePantryItems(), requireStructuredQuantities: true });
    if (eligibility.status !== RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE && eligibility.canUseForAutomaticPlanning !== true) return null;
    const usage = calculateFoodRescueSelectedFoodUsage(practicalRecipe, sources, practicalServings);
    if (!usage.sourceUses.some((sourceUse) => sourceUse.usedQuantity > 0)) return null;
    const pantryAllocation = calculateFoodRescuePantryCoverageWithSharedAllocator(practicalRecipe, practicalServings);
    const purchase = calculateFoodRescuePurchaseMetrics(practicalRecipe, pantryAllocation);
    const portion = calculateFoodRescuePortionSuitability(practicalRecipe, selectedServings);
    const leftovers = calculateFoodRescueLeftoverFit({ ...practicalRecipe, servings: practicalServings }, selectedServings);
    const crossMeal = calculateFoodRescueCrossMealUse(practicalRecipe, sources);
    const practicality = calculateRecipeTimeScore(normalizedRecipe);
    const score = calculateFoodRescueRecipeScore({ usage, pantryAllocation, purchase, portion, leftovers, crossMeal, practicality });
    return { rankingProfile: FOOD_RESCUE_RANKING_PROFILE, rankingVersion: FOOD_RESCUE_RECIPE_RANKING_VERSION, recipe: normalizedRecipe, scaledRecipe: practicalRecipe, scaleResult, recipeId: normalizedRecipe.id, recipeName: normalizedRecipe.name, selectedServings, practicalServings, eligibility, usage, pantryAllocation, purchase, portion, leftovers, crossMeal, practicality, score, primaryReasons: buildFoodRescueRecipeReasons({ usage, pantryAllocation, purchase, portion, leftovers, score, scaleResult }) };
  }

  function createFoodRescuePracticalScalePreview(recipe, selectedServings) {
    if (typeof COST_ENGINE.scaleRecipeWithPracticalRules === "function") {
      return COST_ENGINE.scaleRecipeWithPracticalRules({
        recipe,
        selectedServings,
        pricingContext: getActiveBudgetPriceSettings(),
        calculationDate: getCurrentDateString()
      });
    }
    const baseServings = Number(recipe?.servings) || 1;
    return {
      version: 0,
      recipeId: recipe?.id || null,
      requestedServings: selectedServings,
      effectiveServings: selectedServings,
      baseServings,
      scaleFactor: selectedServings / baseServings,
      status: "supported",
      materialAdjustments: [],
      ingredientResults: [],
      scaledRecipe: recipe
    };
  }

  function compareFoodRescueRecipeResults(a, b) {
    return b.score.total - a.score.total
      || b.usage.weightedCoverageRatio - a.usage.weightedCoverageRatio
      || b.usage.meaningfullyUsedSourceCount - a.usage.meaningfullyUsedSourceCount
      || a.purchase.newPurchaseGroupCount - b.purchase.newPurchaseGroupCount
      || (getRecipeTotalMinutes(a.recipe) || 9999) - (getRecipeTotalMinutes(b.recipe) || 9999)
      || a.recipeName.localeCompare(b.recipeName)
      || a.recipeId.localeCompare(b.recipeId);
  }

  function calculateFoodRescueSelectedFoodUsage(recipe, sources, selectedServings) {
    const remainingBySourceId = new Map(sources.map((source) => [source.rescueSourceId, Number(source.comparableQuantity ?? source.availableQuantity) || 0]));
    const sourceUses = sources.map((source) => ({ ...source, usedQuantity: 0, usedComparableQuantity: 0, useRatio: 0, meaningfulUse: false, matchedRecipeIngredients: [] }));
    getStructuredIngredients(recipe).filter((ingredient) => ingredient.optional !== true).forEach((ingredient) => {
      const required = buildFoodRescueScaledRequirement(recipe, ingredient, selectedServings);
      if (!required.normalized?.valid || !required.ingredientId) return;
      const compatibleSources = sourceUses.filter((source) => source.ingredientId === required.ingredientId && foodRescueFormsCompatible(required.form, source.form) && source.comparableDimension === required.normalized.dimension).sort((a, b) => (b.rescueRecipePriorityScore || 0) - (a.rescueRecipePriorityScore || 0) || a.rescueSourceId.localeCompare(b.rescueSourceId));
      let remainingRequired = required.normalized.quantity;
      compatibleSources.forEach((source) => {
        if (remainingRequired <= 0) return;
        const remainingSource = remainingBySourceId.get(source.rescueSourceId) || 0;
        const used = Math.min(remainingSource, remainingRequired);
        if (used <= 0) return;
        remainingBySourceId.set(source.rescueSourceId, COST_ENGINE.roundQuantity ? COST_ENGINE.roundQuantity(remainingSource - used) : remainingSource - used);
        remainingRequired = COST_ENGINE.roundQuantity ? COST_ENGINE.roundQuantity(remainingRequired - used) : remainingRequired - used;
        source.usedComparableQuantity += used;
        source.usedQuantity += projectFoodRescueQuantityToSourceUnit(used, source);
        source.matchedRecipeIngredients.push({ ingredientId: ingredient.ingredientId, displayName: ingredient.displayName || ingredient.displayText || "Ingredient", requiredQuantity: required.normalized.quantity, requiredUnit: required.normalized.unit });
      });
    });
    const priorityWeights = FOOD_RESCUE_RECIPE_SCORE_CONFIG.priorityWeights;
    let weightedUsed = 0;
    let weightedAvailable = 0;
    sourceUses.forEach((source) => {
      source.usedComparableQuantity = roundFoodRescueNumber(source.usedComparableQuantity);
      source.usedQuantity = roundFoodRescueNumber(source.usedQuantity);
      const available = Number(source.comparableQuantity ?? source.availableQuantity) || 0;
      source.useRatio = available > 0 ? Math.min(1, source.usedComparableQuantity / available) : 0;
      source.meaningfulUse = source.useRatio >= FOOD_RESCUE_RECIPE_SCORE_CONFIG.meaningfulUse.minimumUseRatio || (FOOD_RESCUE_RECIPE_SCORE_CONFIG.meaningfulUse.useAllAvailableQuantityQualifies && available > 0 && available - source.usedComparableQuantity <= 1e-6);
      const weight = priorityWeights[source.priorityLevel] || 0.4;
      weightedUsed += source.usedComparableQuantity * weight;
      weightedAvailable += available * weight;
    });
    return {
      sourceUses,
      selectedSourceCount: sourceUses.length,
      usedSourceCount: sourceUses.filter((source) => source.usedQuantity > 0).length,
      meaningfullyUsedSourceCount: sourceUses.filter((source) => source.meaningfulUse).length,
      weightedCoverageRatio: weightedAvailable > 0 ? Math.min(1, weightedUsed / weightedAvailable) : 0
    };
  }

  function buildFoodRescueScaledRequirement(recipe, ingredient, selectedServings) {
    const baseServings = Number(recipe.servings) || 1;
    const scale = Number(selectedServings) > 0 ? Number(selectedServings) / baseServings : 1;
    const scaled = COST_ENGINE.scaleIngredientQuantity?.(ingredient, scale) || { quantity: Number(ingredient.quantity) * scale, quantityMax: Number(ingredient.quantityMax) * scale };
    const quantity = ingredient.measurementStatus === "range" && Number.isFinite(Number(scaled.quantityMax)) ? Number(scaled.quantityMax) : Number(scaled.quantity);
    return { ingredientId: ingredient.ingredientId || null, form: ingredient.form || null, displayName: ingredient.displayName || ingredient.displayText || "Ingredient", normalized: COST_ENGINE.normalizeComparableQuantity?.(quantity, ingredient.unit) || { valid: false } };
  }

  function foodRescueFormsCompatible(recipeForm, sourceForm) {
    return !recipeForm || !sourceForm || recipeForm === sourceForm;
  }

  function projectFoodRescueQuantityToSourceUnit(usedComparableQuantity, source) {
    const availableComparable = Number(source.comparableQuantity);
    const availableDisplay = Number(source.availableQuantity);
    if (!Number.isFinite(availableComparable) || availableComparable <= 0 || !Number.isFinite(availableDisplay)) return usedComparableQuantity;
    return availableDisplay * Math.min(1, usedComparableQuantity / availableComparable);
  }

  function calculateFoodRescuePantryCoverageWithSharedAllocator(recipe, selectedServings) {
    if (typeof PANTRY_FIRST.createPlanningInventory !== "function" || typeof PANTRY_FIRST.simulateRecipeAgainstInventory !== "function") {
      const match = calculatePantryMatch(recipe, getActivePantryItems());
      return { pantryCoverageRatio: match.percentage / 100, newPurchaseGroupCount: match.missing.length, requirementAllocations: [] };
    }
    const inventory = PANTRY_FIRST.createPlanningInventory({ pantryItems: getActivePantryItems(), ingredientResolver: resolveCanonicalIngredientName, planStartDate: getCurrentDateString(), planEndDate: getCurrentDateString() });
    return PANTRY_FIRST.simulateRecipeAgainstInventory({ recipe: normalizeRecipe(recipe), selectedServings, planningInventory: inventory });
  }

  function calculateFoodRescuePurchaseMetrics(recipe, pantryAllocation) {
    const purchaseGroups = (pantryAllocation?.requirementAllocations || []).filter((item) => Number(item.missingQuantity) > 0);
    let knownFullPackageCostCents = 0;
    let incompletePriceCount = 0;
    purchaseGroups.forEach((group) => {
      const resolution = group.ingredientId ? PRICE_DATA.resolveIngredientPrice?.({ ingredientId: group.ingredientId, ...getActiveBudgetPriceSettings(), calculationDate: getCurrentDateString() }) : null;
      if (!resolution || resolution.status !== "resolved" || !Number.isInteger(resolution.effectivePriceCents)) {
        incompletePriceCount += 1;
        return;
      }
      knownFullPackageCostCents += resolution.effectivePriceCents;
    });
    return { newPurchaseGroupCount: purchaseGroups.length, knownFullPackageCostCents, incompletePriceCount, complete: incompletePriceCount === 0, purchaseGroups };
  }

  function calculateFoodRescuePortionSuitability(recipe, selectedServings) {
    const produced = Number(recipe.servings) || 1;
    const needed = Number(selectedServings) || 1;
    const ratio = Math.min(produced, needed) / Math.max(produced, needed);
    return { producedServings: produced, selectedServings: needed, scoreRatio: Math.max(0, Math.min(1, ratio)) };
  }

  function calculateFoodRescueLeftoverFit(recipe, selectedServings) {
    const produced = Number(recipe.servings) || 1;
    const extraServings = Math.max(0, produced - (Number(selectedServings) || 1));
    const supported = recipe.leftovers?.supported === true || recipe.batchCooking?.supported === true;
    return { supported, extraServings, usefulRatio: supported && extraServings > 0 ? Math.min(1, extraServings / produced) : 0, excessRatio: !supported && extraServings > 0 ? Math.min(1, extraServings / produced) : 0 };
  }

  function calculateFoodRescueCrossMealUse(recipe, sources) {
    const plannedNames = Object.values(getSavedMealPlan()).flatMap((day) => Object.values(day || {})).map((entry) => normalizeMealPlanEntry(entry)?.recipeName || "").filter(Boolean);
    const plannedRecipes = plannedNames.map((name) => state.recipes.map(normalizeRecipe).find((recipe) => normalizeIngredient(recipe.name) === normalizeIngredient(name))).filter(Boolean);
    const sourceIngredientIds = new Set(sources.map((source) => source.ingredientId).filter(Boolean));
    const reuseCount = plannedRecipes.reduce((count, plannedRecipe) => count + (getStructuredIngredients(plannedRecipe).some((ingredient) => sourceIngredientIds.has(ingredient.ingredientId)) ? 1 : 0), 0);
    return { reuseMealCount: reuseCount, scoreRatio: Math.min(1, reuseCount / 3) };
  }

  function calculateFoodRescueRecipeScore(metrics) {
    const positive = FOOD_RESCUE_RECIPE_SCORE_CONFIG.positiveMaximums;
    const penalty = FOOD_RESCUE_RECIPE_SCORE_CONFIG.penaltyMaximums;
    const positiveScore =
      Math.min(positive.priorityFoodBreadth, metrics.usage.meaningfullyUsedSourceCount / Math.max(1, metrics.usage.selectedSourceCount) * positive.priorityFoodBreadth)
      + metrics.usage.weightedCoverageRatio * positive.weightedRescueCoverage
      + (metrics.pantryAllocation?.pantryCoverageRatio || 0) * positive.pantryCoverage
      + metrics.portion.scoreRatio * positive.portionSuitability
      + metrics.crossMeal.scoreRatio * positive.crossMealIngredientUse
      + (metrics.practicality / 100) * positive.cookingPracticality
      + metrics.leftovers.usefulRatio * positive.usefulLeftovers;
    const penaltyScore =
      Math.min(penalty.newPurchase, metrics.purchase.newPurchaseGroupCount * 3)
      + metrics.leftovers.excessRatio * penalty.excessLeftovers
      + Math.min(penalty.futureUnusedFoodRisk, Math.max(0, metrics.purchase.newPurchaseGroupCount - metrics.usage.usedSourceCount) * 2)
      + Math.min(penalty.incompleteData, metrics.purchase.incompletePriceCount * 2);
    const total = clampFoodRescueScore(positiveScore - penaltyScore);
    return { total, positiveScore: Math.round(positiveScore), penaltyScore: Math.round(penaltyScore), rescueValueLevel: getFoodRescueValueLevel(total), configurationVersion: FOOD_RESCUE_RECIPE_SCORE_CONFIGURATION_VERSION };
  }

  function clampFoodRescueScore(value) {
    const range = FOOD_RESCUE_RECIPE_SCORE_CONFIG.scoreRange;
    return Math.max(range.minimum, Math.min(range.maximum, Math.round(Number(value) || 0)));
  }

  function getFoodRescueValueLevel(score) {
    const thresholds = FOOD_RESCUE_RECIPE_SCORE_CONFIG.rescueValueThresholds;
    if (score >= thresholds.veryHigh) return FOOD_RESCUE_RESCUE_VALUE_LEVELS.VERY_HIGH;
    if (score >= thresholds.high) return FOOD_RESCUE_RESCUE_VALUE_LEVELS.HIGH;
    if (score >= thresholds.medium) return FOOD_RESCUE_RESCUE_VALUE_LEVELS.MEDIUM;
    return FOOD_RESCUE_RESCUE_VALUE_LEVELS.LOW;
  }

  function buildFoodRescueRecipeReasons({ usage, pantryAllocation, purchase, portion, leftovers, score, scaleResult }) {
    const reasons = [];
    if (usage.meaningfullyUsedSourceCount) reasons.push(`Uses ${usage.meaningfullyUsedSourceCount} priority ${pluralize(usage.meaningfullyUsedSourceCount, "food")}`);
    if (usage.weightedCoverageRatio > 0) reasons.push(`Projected priority-food use: ${Math.round(usage.weightedCoverageRatio * 100)}%`);
    if ((pantryAllocation?.pantryCoverageRatio || 0) > 0) reasons.push(`Pantry coverage: ${Math.round((pantryAllocation.pantryCoverageRatio || 0) * 100)}%`);
    if (scaleResult?.materialAdjustments?.some((item) => item.adjusted)) reasons.push("Practical ingredient amounts adjusted");
    if (scaleResult?.status === "review-required") reasons.push("Some ingredient amounts need review");
    if (!purchase.newPurchaseGroupCount) reasons.push("No new ingredient groups estimated");
    else reasons.push(`${purchase.newPurchaseGroupCount} new ${pluralize(purchase.newPurchaseGroupCount, "ingredient group")} estimated`);
    if (portion.scoreRatio >= 0.9) reasons.push("Serving size fits the plan");
    if (leftovers.usefulRatio > 0) reasons.push("Leftovers can support another meal");
    return { headline: `${useFirstPriorityLevelLabel(score.rescueValueLevel)} rescue match`, reasons: reasons.slice(0, FOOD_RESCUE_RECIPE_SCORE_CONFIG.maximumPrimaryReasons) };
  }

  function buildFoodRescueCardViewModel(ranking) {
    if (!ranking || ranking.eligibility?.status !== RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE) return null;
    const recipe = normalizeRecipe(ranking.recipe || {});
    const projectedFoodUse = (ranking.usage?.sourceUses || []).map((source) => {
      const available = Number(source.availableQuantity);
      const used = Number(source.usedQuantity);
      const remaining = Number.isFinite(available) && Number.isFinite(used) ? Math.max(0, roundFoodRescueNumber(available - used)) : null;
      const useRatio = Number.isFinite(Number(source.useRatio)) ? Math.max(0, Math.min(1, Number(source.useRatio))) : null;
      const panelEntry = getUseFirstPanelEntryForRescueSource(source.rescueSourceId);
      return {
        rescueSourceId: source.rescueSourceId,
        sourceType: source.sourceType || RESCUE_SOURCE_TYPES.PANTRY_ITEM,
        foodName: source.displayName || source.foodName || "Selected food",
        lotLabel: panelEntry?.lotLabel || source.lotLabel || "",
        projectedUsedQuantity: Number.isFinite(used) ? roundFoodRescueNumber(used) : null,
        availableQuantity: Number.isFinite(available) ? roundFoodRescueNumber(available) : null,
        projectedRemainingQuantity: remaining,
        unit: source.unit || "",
        useRatio,
        meaningfulUse: source.meaningfulUse === true,
        sourcePriorityLevel: source.priorityLevel || USE_FIRST_PRIORITY_LEVELS.MONITOR,
        canFindSecondUse: canShowFoodRescueRemainderAction({ remaining, source, panelEntry }),
        canReviewFreezeOptionsForRemainder: canShowFoodRescueRemainderAction({ remaining, source, panelEntry }) && panelEntry?.actions?.canViewFreezeOptions === true
      };
    });
    const aggregate = buildSelectedFoodCoverageAggregate(ranking.usage?.sourceUses || []);
    const incompletePrices = Number(ranking.purchase?.incompletePriceCount) || 0;
    const newGroceries = Number(ranking.purchase?.newPurchaseGroupCount) || 0;
    const knownCost = Number.isInteger(ranking.purchase?.knownFullPackageCostCents) ? ranking.purchase.knownFullPackageCostCents : null;
    const unallocated = Number(ranking.leftovers?.extraServings) || 0;
    const plannedLeftovers = 0;
    const methodLabel = ranking.eligibility?.preparationMethodId || ranking.eligibility?.selectedPreparationMethodId || "Current method";
    const effectiveTime = ranking.eligibility?.validatedContext?.effectiveCookingTimeMinutes ?? getRecipeTotalMinutes(recipe);
    const portionInput = createSmartPortionInput(recipe.id, {});
    const scalingSummary = buildFoodRescuePracticalScalingSummary(ranking.scaleResult);
    return {
      viewModelVersion: FOOD_RESCUE_CARD_VIEW_MODEL_VERSION,
      candidateId: ranking.eligibility?.candidateId || `recipe::${recipe.id}::food-rescue`,
      recipeId: recipe.id,
      recipeVariantId: ranking.eligibility?.recipeVariantId || null,
      preparationMethodId: ranking.eligibility?.preparationMethodId || null,
      eligibility: { status: ranking.eligibility.status, hardEligible: ranking.eligibility.hardEligible === true },
      recipe: { name: recipe.name, description: recipe.description || null, imageId: recipe.imageId || null },
      rescueValue: { score: ranking.score.total, level: ranking.score.rescueValueLevel, label: useFirstPriorityLevelLabel(ranking.score.rescueValueLevel) },
      projectedFoodUse,
      selectedFoodCoverage: { value: ranking.usage.weightedCoverageRatio, displayPercent: Math.round((ranking.usage.weightedCoverageRatio || 0) * 100), metricType: aggregate ? "selected-food-coverage" : "weighted-rescue-coverage", sameUnitFamilyAggregate: aggregate },
      pantryCoverage: { value: ranking.pantryAllocation?.pantryCoverageRatio || 0, displayPercent: Math.round((ranking.pantryAllocation?.pantryCoverageRatio || 0) * 100) },
      purchaseSummary: {
        newPurchaseGroupCount: newGroceries,
        marginalPurchaseCostCents: incompletePrices ? null : knownCost,
        knownPurchaseSubtotalCents: knownCost,
        costStatus: incompletePrices ? PRICE_CONFIDENCE_STATUSES.INCOMPLETE : newGroceries === 0 && knownCost === 0 ? "complete-zero" : PRICE_CONFIDENCE_STATUSES.ESTIMATED,
        unpricedPurchaseGroupCount: incompletePrices,
        priceConfidenceLabel: incompletePrices ? "Incomplete estimate" : "Estimated"
      },
      cookingSummary: { totalTimeMinutes: Number.isFinite(Number(effectiveTime)) ? Number(effectiveTime) : null, activeTimeMinutes: null, methodLabel },
      servingSummary: { householdSuggestedServings: ranking.selectedServings, effectiveYield: ranking.practicalServings || ranking.portion?.producedServings || recipe.servings, scaleFactor: ranking.scaleResult?.scaleFactor || ranking.eligibility?.scaleFactor || 1, batchCount: ranking.eligibility?.batchCount || 1, validPlannedLeftoverServings: plannedLeftovers, unallocatedLeftoverServings: unallocated },
      practicalScaling: scalingSummary,
      smartPortionSuggestion: null,
      smartPortionStartingPoint: {
        peopleEating: portionInput?.peopleEating?.value || null,
        source: portionInput?.peopleEating?.source || "blank",
        message: portionInput?.peopleEating?.value ? `Based on ${portionInput.peopleEating.value} ${pluralize(portionInput.peopleEating.value, "person")} eating.` : "Enter people eating to get a serving suggestion."
      },
      leftoverFit: {
        householdFitsBatch: ranking.leftovers?.householdFitsBatch === true,
        extraServings: unallocated,
        leftoverPenalty: Number(ranking.leftovers?.leftoverPenalty) || 0
      },
      recommendationExplanation: buildFoodRescueRecommendationExplanation(ranking),
      futureUnusedFoodRisk: buildFoodRescueUnusedFoodRisk(ranking),
      actions: {
        canCookTonight: ranking.eligibility.status === RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE,
        canAdjustPortions: true,
        canSeeOtherRecipes: state.foodRescueRankingResults.length > 1,
        canViewRescueDetails: true
      },
      sourceRevisions: ranking.eligibility?.sourceRevisions || {}
    };
  }

  function buildFoodRescuePracticalScalingSummary(scaleResult) {
    if (!scaleResult) return { status: "not-available", version: null, adjustments: [], warnings: [], summary: "" };
    const material = (scaleResult.materialAdjustments || []).filter((item) => item.status !== "excluded");
    const adjusted = material.filter((item) => item.adjusted);
    const reviewRequired = material.filter((item) => item.status === "review-required");
    const unsupported = material.filter((item) => item.status === "unsupported");
    const summaryParts = [];
    if (adjusted.length) summaryParts.push(`${adjusted.length} practical ${pluralize(adjusted.length, "adjustment")}`);
    if (reviewRequired.length) summaryParts.push(`${reviewRequired.length} ${pluralize(reviewRequired.length, "item")} need review`);
    if (unsupported.length) summaryParts.push(`${unsupported.length} unsupported ${pluralize(unsupported.length, "item")}`);
    return {
      version: scaleResult.version || null,
      policyVersion: scaleResult.policyVersion || null,
      profileVersion: scaleResult.recipeScaleProfileVersion || null,
      status: scaleResult.status || "supported",
      adjustments: material.map((item) => ({
        occurrenceId: item.occurrenceId,
        displayName: item.displayName,
        rawQuantity: item.rawMathematicalQuantity,
        practicalQuantity: item.practicalRecipeQuantity,
        groceryPurchaseQuantity: item.groceryPurchaseQuantity,
        groceryPurchaseUnit: item.groceryPurchaseUnit,
        packageSurplusQuantity: item.packageSurplusQuantity,
        packageSurplusUnit: item.packageSurplusUnit,
        unit: item.unit,
        status: item.status,
        adjusted: item.adjusted === true,
        explanation: item.explanation
      })),
      warnings: scaleResult.warnings || [],
      summary: summaryParts.join("; ")
    };
  }

  function buildSelectedFoodCoverageAggregate(sourceUses = []) {
    const used = sourceUses.filter((source) => Number(source.usedComparableQuantity) > 0 && source.comparableDimension && source.comparableUnit);
    if (!used.length) return null;
    const dimension = used[0].comparableDimension;
    const unit = used[0].comparableUnit;
    if (!used.every((source) => source.comparableDimension === dimension && source.comparableUnit === unit)) return null;
    return {
      quantityUsed: roundFoodRescueNumber(used.reduce((sum, source) => sum + (Number(source.usedComparableQuantity) || 0), 0)),
      quantityAvailable: roundFoodRescueNumber(used.reduce((sum, source) => sum + (Number(source.comparableQuantity ?? source.availableQuantity) || 0), 0)),
      unit
    };
  }

  function buildFoodRescueRecommendationExplanation(ranking) {
    const sentence = ranking.primaryReasons?.reasons?.length
      ? `${ranking.primaryReasons.reasons.slice(0, 2).join(" and ")}.`
      : "Matches selected food that needs attention.";
    return { summary: sentence.length > 220 ? `${sentence.slice(0, 217)}...` : sentence, primaryReasonIds: ranking.primaryReasons?.reasons || [] };
  }

  function buildFoodRescueUnusedFoodRisk(ranking) {
    const newPurchases = Number(ranking.purchase?.newPurchaseGroupCount) || 0;
    const usedSources = Number(ranking.usage?.usedSourceCount) || 0;
    const warnings = [];
    if (newPurchases > usedSources) warnings.push(`This recipe may add ${newPurchases - usedSources} new grocery ${pluralize(newPurchases - usedSources, "group")} not currently used by selected food.`);
    if (Number(ranking.leftovers?.extraServings) > 0 && !ranking.leftovers?.supported) warnings.push(`May produce ${formatQuantityForDisplay(ranking.leftovers.extraServings)} unallocated ${pluralize(ranking.leftovers.extraServings, "serving")}.`);
    return { level: warnings.length ? "medium" : "low", warnings };
  }

  function getUseFirstPanelEntryForRescueSource(rescueSourceId) {
    if (!rescueSourceId) return null;
    try {
      return getCurrentUseFirstPanelModel().entries.find((entry) => entry.rescueSourceId === rescueSourceId) || null;
    } catch {
      return null;
    }
  }

  function canShowFoodRescueRemainderAction({ remaining, source, panelEntry }) {
    if (!Number.isFinite(Number(remaining)) || Number(remaining) <= 0) return false;
    if (Number(source?.useRatio) >= 0.98) return false;
    return panelEntry?.selection?.selectable !== false;
  }

  function renderFoodRescueRecipeSummary(recipe) {
    const viewModel = buildFoodRescueCardViewModel(recipe.foodRescueRanking);
    if (!viewModel) return "";
    const usedRows = viewModel.projectedFoodUse.filter((source) => Number(source.projectedUsedQuantity) > 0);
    const remainingRows = usedRows.filter((source) => Number(source.projectedRemainingQuantity) > 0 && (source.canFindSecondUse || source.canReviewFreezeOptionsForRemainder));
    return `<section class="food-rescue-result-summary" data-food-rescue-card-view-model-version="${FOOD_RESCUE_CARD_VIEW_MODEL_VERSION}" aria-label="Food rescue planning estimate for ${escapeHtml(recipe.name)}">
      <div class="food-rescue-heading">
        <span class="food-rescue-value ${escapeHtml(viewModel.rescueValue.level)}">Food rescue value: <b>${escapeHtml(viewModel.rescueValue.label)}</b></span>
        <p>These quantities are planning estimates. Pantry amounts update only after food use is confirmed.</p>
      </div>
      <div class="food-rescue-use-block">
        <h4>Would Use</h4>
        <ul class="food-rescue-use-list">${usedRows.map((source) => renderFoodRescueProjectedUseRow(source, viewModel.recipe.name)).join("")}</ul>
      </div>
      <dl class="food-rescue-metrics">
        <div><dt>${viewModel.selectedFoodCoverage.metricType === "weighted-rescue-coverage" ? "Weighted selected-food coverage" : "Selected-food coverage"}</dt><dd>Approximately ${escapeHtml(String(viewModel.selectedFoodCoverage.displayPercent))}%</dd></div>
        <div><dt>Pantry coverage</dt><dd>${escapeHtml(String(viewModel.pantryCoverage.displayPercent))}%</dd></div>
        <div><dt>New groceries needed</dt><dd>${escapeHtml(String(viewModel.purchaseSummary.newPurchaseGroupCount))}</dd></div>
        <div><dt>Estimated added cost</dt><dd>${renderFoodRescueCostValue(viewModel.purchaseSummary)}</dd></div>
        <div><dt>Cooking time</dt><dd>${viewModel.cookingSummary.totalTimeMinutes === null ? "Needs review" : `${escapeHtml(String(viewModel.cookingSummary.totalTimeMinutes))} minutes`}</dd></div>
        <div><dt>Suggested servings</dt><dd>${viewModel.smartPortionSuggestion ? escapeHtml(String(viewModel.smartPortionSuggestion.recipeYield.supportedYield)) : escapeHtml(viewModel.smartPortionStartingPoint.message)}</dd></div>
      </dl>
      <p class="food-rescue-help">Coverage reflects the projected percentage of the selected food this recipe would use.</p>
      ${renderFoodRescueScalingSummary(viewModel)}
      <div class="food-rescue-leftover-summary">${renderFoodRescueLeftoverSummary(viewModel)}</div>
      <div class="food-rescue-explanation"><h4>Why Chef Nova recommends this</h4><p>${escapeHtml(viewModel.recommendationExplanation.summary)}</p></div>
      ${viewModel.futureUnusedFoodRisk.warnings.length ? `<div class="food-rescue-risk" role="status">${viewModel.futureUnusedFoodRisk.warnings.map((warning) => `<p>${escapeHtml(warning)}</p>`).join("")}</div>` : ""}
      ${remainingRows.length ? `<div class="food-rescue-remainders"><h4>Projected remaining food</h4>${remainingRows.map((source) => renderFoodRescueRemainderActions(source, viewModel.recipeId)).join("")}</div>` : ""}
      <div class="food-rescue-actions">
        ${viewModel.actions.canCookTonight ? `<button class="button primary small" type="button" data-food-rescue-cook-tonight="${escapeHtml(viewModel.recipeId)}" aria-label="Plan ${escapeHtml(viewModel.recipe.name)} for tonight">Cook This Tonight</button>` : ""}
        ${viewModel.actions.canAdjustPortions ? `<button class="button secondary small" type="button" data-food-rescue-adjust="${escapeHtml(viewModel.recipeId)}" aria-label="Adjust portions for ${escapeHtml(viewModel.recipe.name)}">Adjust Portions</button>` : `<p class="food-rescue-action-note">Adjust Portions unavailable. This recipe supports only one fixed batch size.</p>`}
        <button class="button secondary small" type="button" data-food-rescue-details="${escapeHtml(viewModel.recipeId)}" aria-label="View food-rescue details for ${escapeHtml(viewModel.recipe.name)}">View Rescue Details</button>
        ${viewModel.actions.canSeeOtherRecipes ? `<button class="button secondary small" type="button" data-food-rescue-other="${escapeHtml(viewModel.recipeId)}" aria-label="See other recipes using the selected food">See Other Recipes</button>` : ""}
      </div>
    </section>`;
  }

  function renderFoodRescueScalingSummary(viewModel) {
    const summary = viewModel.practicalScaling;
    if (!summary || (!summary.adjustments.length && summary.status === "supported")) return "";
    const label = summary.summary || (summary.status === "review-required" ? "Some ingredient amounts need review" : "Practical ingredient scaling applied");
    return `<div class="food-rescue-scaling-summary" role="status">
      <p><b>Ingredient scaling:</b> ${escapeHtml(label)}.</p>
      <button class="button secondary small" type="button" data-food-rescue-scaling-details="${escapeHtml(viewModel.recipeId)}" aria-label="Why were ingredient amounts adjusted for ${escapeHtml(viewModel.recipe.name)}?">Why Was This Adjusted?</button>
    </div>`;
  }

  function renderFoodRescueProjectedUseRow(source, recipeName) {
    const useLabel = source.meaningfulUse ? "Would use" : "Would use a small amount";
    const check = source.meaningfulUse ? `<span class="food-rescue-check" aria-hidden="true">✓</span>` : "";
    const amount = `${formatQuantityForDisplay(source.projectedUsedQuantity)} ${source.unit || ""}`.trim();
    const available = `${formatQuantityForDisplay(source.availableQuantity)} ${source.unit || ""}`.trim();
    const remaining = source.projectedRemainingQuantity === null ? "Needs review" : `${formatQuantityForDisplay(source.projectedRemainingQuantity)} ${source.unit || ""}`.trim();
    return `<li>
      ${check}
      <div>
        <b>${escapeHtml(source.foodName)}</b>${source.lotLabel ? `<small>${escapeHtml(source.lotLabel)}</small>` : ""}
        <span>${escapeHtml(useLabel)}: ${escapeHtml(amount)} of ${escapeHtml(available)}</span>
        <span>Approximately ${escapeHtml(String(formatFoodRescuePercent(source.useRatio)))}%</span>
        <span>Would remain: ${escapeHtml(remaining)}</span>
      </div>
    </li>`;
  }

  function renderFoodRescueRemainderActions(source, recipeId) {
    const remaining = `${formatQuantityForDisplay(source.projectedRemainingQuantity)} ${source.unit || ""}`.trim();
    return `<div class="food-rescue-remainder-row">
      <p>This recipe would use ${escapeHtml(formatQuantityForDisplay(source.projectedUsedQuantity))} ${escapeHtml(source.unit || "")} of your ${escapeHtml(formatQuantityForDisplay(source.availableQuantity))} ${escapeHtml(source.unit || "")} ${escapeHtml(source.foodName)}. Approximately ${escapeHtml(remaining)} would remain.</p>
      <div>
        ${source.canFindSecondUse ? `<button class="button secondary small" type="button" data-food-rescue-second-use="${escapeHtml(recipeId)}" data-rescue-source-id="${escapeHtml(source.rescueSourceId)}" aria-label="Find a second use for the projected remaining ${escapeHtml(remaining)} of ${escapeHtml(source.foodName)}">Find a Second Use</button>` : ""}
        ${source.canReviewFreezeOptionsForRemainder ? `<button class="button secondary small" type="button" data-food-rescue-freeze-remainder="${escapeHtml(recipeId)}" data-rescue-source-id="${escapeHtml(source.rescueSourceId)}" aria-label="Review freeze options for the projected remaining ${escapeHtml(remaining)} of ${escapeHtml(source.foodName)}">Review Freeze Options for the Remaining Portion</button>` : ""}
      </div>
    </div>`;
  }

  function renderFoodRescueCostValue(purchaseSummary) {
    if (purchaseSummary.unpricedPurchaseGroupCount > 0) return `<span class="food-rescue-incomplete-cost">Incomplete estimate</span><small>${escapeHtml(numberWord(purchaseSummary.unpricedPurchaseGroupCount))} ${escapeHtml(pluralize(purchaseSummary.unpricedPurchaseGroupCount, "grocery item"))} still ${purchaseSummary.unpricedPurchaseGroupCount === 1 ? "needs" : "need"} a price.</small>`;
    return escapeHtml(formatCostCents(purchaseSummary.marginalPurchaseCostCents ?? 0));
  }

  function renderFoodRescueLeftoverSummary(viewModel) {
    const planned = Number(viewModel.servingSummary.validPlannedLeftoverServings) || 0;
    const unallocated = Number(viewModel.servingSummary.unallocatedLeftoverServings) || 0;
    if (planned > 0) return `<p>Planned leftovers: ${escapeHtml(formatQuantityForDisplay(planned))} ${escapeHtml(pluralize(planned, "serving"))}.</p>`;
    if (unallocated > 0) return `<p>May produce ${escapeHtml(formatQuantityForDisplay(unallocated))} unallocated ${escapeHtml(pluralize(unallocated, "serving"))}.</p>`;
    return `<p>No unallocated leftovers.</p>`;
  }

  function formatFoodRescuePercent(ratio) {
    return Number.isFinite(Number(ratio)) ? Math.round(Number(ratio) * 100) : "review";
  }

  function openFoodRescueRecipeDetails(recipeId) {
    const ranking = getFoodRescueRankingByRecipeId(recipeId);
    const viewModel = buildFoodRescueCardViewModel(ranking);
    if (!viewModel) return showToast("Food rescue details are not available for this recipe.", "info");
    const modal = $("#useFirstPriorityModal");
    const content = $("#useFirstPriorityModalContent");
    if (!modal || !content) return;
    content.innerHTML = `<div class="instruction-modal-heading">
      <span class="rule-badge">Food Rescue Details</span>
      <h2 id="useFirstPriorityModalTitle">${escapeHtml(viewModel.recipe.name)}</h2>
      <p>These quantities are planning estimates. Pantry amounts are updated only after food use is confirmed.</p>
    </div>
    <dl class="use-first-detail-list">
      <div><dt>Food rescue value</dt><dd>${escapeHtml(viewModel.rescueValue.label)} (${escapeHtml(String(viewModel.rescueValue.score))} / 100)</dd></div>
      <div><dt>${viewModel.selectedFoodCoverage.metricType === "weighted-rescue-coverage" ? "Weighted selected-food coverage" : "Selected-food coverage"}</dt><dd>Approximately ${escapeHtml(String(viewModel.selectedFoodCoverage.displayPercent))}%</dd></div>
      <div><dt>Pantry coverage</dt><dd>${escapeHtml(String(viewModel.pantryCoverage.displayPercent))}%</dd></div>
      <div><dt>Additional groceries</dt><dd>${escapeHtml(String(viewModel.purchaseSummary.newPurchaseGroupCount))}</dd></div>
      <div><dt>Additional checkout cost</dt><dd>${viewModel.purchaseSummary.unpricedPurchaseGroupCount ? "Incomplete estimate" : escapeHtml(formatCostCents(viewModel.purchaseSummary.marginalPurchaseCostCents ?? 0))}</dd></div>
      <div><dt>Price status</dt><dd>${escapeHtml(viewModel.purchaseSummary.priceConfidenceLabel)}</dd></div>
      <div><dt>Method and time</dt><dd>${escapeHtml(viewModel.cookingSummary.methodLabel)}${viewModel.cookingSummary.totalTimeMinutes === null ? "" : `, ${escapeHtml(String(viewModel.cookingSummary.totalTimeMinutes))} minutes`}</dd></div>
      <div><dt>Serving profile</dt><dd>${escapeHtml(String(viewModel.servingSummary.householdSuggestedServings))} suggested; ${escapeHtml(String(viewModel.servingSummary.effectiveYield))} effective yield</dd></div>
      <div><dt>Ingredient scaling</dt><dd>${escapeHtml(viewModel.practicalScaling.summary || viewModel.practicalScaling.status || "Supported")}</dd></div>
      <div><dt>Leftovers</dt><dd>${viewModel.servingSummary.unallocatedLeftoverServings > 0 ? `${escapeHtml(String(viewModel.servingSummary.unallocatedLeftoverServings))} unallocated servings` : "No unallocated leftovers"}</dd></div>
    </dl>
    <div class="recipe-detail-section"><h3>Projected food use</h3><ul class="food-rescue-detail-list">${viewModel.projectedFoodUse.map((source) => `<li><b>${escapeHtml(source.foodName)}</b><span>Would use ${escapeHtml(formatQuantityForDisplay(source.projectedUsedQuantity))} ${escapeHtml(source.unit || "")} of ${escapeHtml(formatQuantityForDisplay(source.availableQuantity))} ${escapeHtml(source.unit || "")}. Approximately ${escapeHtml(String(formatFoodRescuePercent(source.useRatio)))}%. ${escapeHtml(formatQuantityForDisplay(source.projectedRemainingQuantity))} ${escapeHtml(source.unit || "")} would remain.</span></li>`).join("")}</ul></div>
    ${renderFoodRescueScalingDetailsSection(viewModel.practicalScaling)}
    <div class="recipe-detail-section"><h3>Recommendation reasons</h3><p>${escapeHtml(viewModel.recommendationExplanation.summary)}</p><ul>${viewModel.recommendationExplanation.primaryReasonIds.map((reason) => `<li>${escapeHtml(reason)}</li>`).join("")}</ul></div>
    ${viewModel.futureUnusedFoodRisk.warnings.length ? `<div class="recipe-detail-section"><h3>Future unused-food risk</h3>${viewModel.futureUnusedFoodRisk.warnings.map((warning) => `<p>${escapeHtml(warning)}</p>`).join("")}</div>` : ""}
    <p class="field-help">Food-safety reminder: Chef Nova provides guidance, not a guarantee. Review storage, dates, temperature, and condition before cooking.</p>
    <button class="button primary" type="button" data-close-use-first-priority>Close</button>`;
    modal.classList.remove("hidden");
    modal.setAttribute("aria-hidden", "false");
    document.body.classList.add("modal-open");
    $("#useFirstPriorityModalClose")?.focus();
  }

  function renderFoodRescueScalingDetailsSection(summary) {
    if (!summary || !summary.adjustments.length) return `<div class="recipe-detail-section"><h3>Ingredient scaling</h3><p>Measured ingredient amounts scale directly for this serving profile.</p></div>`;
    return `<div class="recipe-detail-section"><h3>Ingredient scaling</h3>
      <ul class="food-rescue-detail-list">${summary.adjustments.map((item) => {
        const raw = Number.isFinite(Number(item.rawQuantity)) ? `${formatQuantityForDisplay(item.rawQuantity)} ${item.unit || ""}`.trim() : "Needs review";
        const practical = Number.isFinite(Number(item.practicalQuantity)) ? `${formatQuantityForDisplay(item.practicalQuantity)} ${item.unit || ""}`.trim() : "Needs review";
        const grocery = Number.isFinite(Number(item.groceryPurchaseQuantity)) ? ` Grocery purchase estimate: ${formatQuantityForDisplay(item.groceryPurchaseQuantity)} ${item.groceryPurchaseUnit || ""}.` : "";
        const surplus = Number.isFinite(Number(item.packageSurplusQuantity)) && Number(item.packageSurplusQuantity) > 0 ? ` Estimated package surplus: ${formatQuantityForDisplay(item.packageSurplusQuantity)} ${item.packageSurplusUnit || ""}.` : "";
        return `<li><b>${escapeHtml(item.displayName)}</b><span>Calculated: ${escapeHtml(raw)}. Practical recipe use: ${escapeHtml(practical)}. ${escapeHtml(item.explanation || "")}${escapeHtml(grocery)}${escapeHtml(surplus)}</span></li>`;
      }).join("")}</ul>
      <p class="field-help">Recipe-use amounts, grocery purchases, and package surplus stay separate. Pantry updates only after cooking is confirmed.</p>
    </div>`;
  }

  function openFoodRescueScalingDetails(recipeId) {
    const ranking = getFoodRescueRankingByRecipeId(recipeId);
    const viewModel = buildFoodRescueCardViewModel(ranking);
    if (!viewModel) return showToast("Ingredient scaling details are not available for this recipe.", "info");
    const modal = $("#useFirstPriorityModal");
    const content = $("#useFirstPriorityModalContent");
    if (!modal || !content) return;
    content.innerHTML = `<div class="instruction-modal-heading">
      <span class="rule-badge">Ingredient Scaling</span>
      <h2 id="useFirstPriorityModalTitle">${escapeHtml(viewModel.recipe.name)}</h2>
      <p>Practical quantities are planning estimates. Pantry amounts update only after food use is confirmed.</p>
    </div>
    ${renderFoodRescueScalingDetailsSection(viewModel.practicalScaling)}
    <button class="button primary" type="button" data-close-use-first-priority>Close</button>`;
    modal.classList.remove("hidden");
    modal.setAttribute("aria-hidden", "false");
    document.body.classList.add("modal-open");
    $("#useFirstPriorityModalClose")?.focus();
  }

  function getFoodRescueRankingByRecipeId(recipeId) {
    return state.foodRescueRankingResults.find((result) => result.recipeId === recipeId) || null;
  }

  function getSmartPortionHouseholdContext() {
    const budget = normalizePlanningModeInputs(state.planningModeInputs).budgetRescue;
    const adults = Number.isInteger(Number(budget.household?.adults)) ? Number(budget.household.adults) : 0;
    const children = Number.isInteger(Number(budget.household?.children)) ? Number(budget.household.children) : 0;
    const total = adults + children;
    return {
      savedAdults: adults,
      savedChildren: children,
      savedHouseholdMemberCount: total > 0 ? total : null,
      householdRevision: `${adults}:${children}:${state.guestMode ? "guest" : getActiveUserId() || "none"}`,
      source: total > 0 ? "household-profile" : "not-available",
      explanation: total > 0
        ? `Chef Nova started with your saved household size of ${total} ${pluralize(total, "person")}. You can change this for tonight.`
        : "Enter how many people are eating tonight."
    };
  }

  function getSmartPortionStartingPeople(overrides = {}) {
    const override = Number(overrides.peopleEating);
    if (Number.isInteger(override) && override > 0) return { value: override, source: "user-confirmed", userConfirmed: true };
    const household = getSmartPortionHouseholdContext();
    if (Number.isInteger(household.savedHouseholdMemberCount) && household.savedHouseholdMemberCount > 0) return { value: household.savedHouseholdMemberCount, source: "household-profile", userConfirmed: false };
    const recent = Number(state.currentCookTonightWorkflow?.peopleEating?.count);
    if (Number.isInteger(recent) && recent > 0) return { value: recent, source: "recent-current-draft", userConfirmed: false };
    return { value: null, source: "blank", userConfirmed: false };
  }

  function normalizePortionLeftoverPreference(value) {
    return Object.values(PORTION_LEFTOVER_PREFERENCES).includes(value) ? value : null;
  }

  function createSmartPortionInput(recipeId, overrides = {}) {
    const ranking = getFoodRescueRankingByRecipeId(recipeId);
    if (!ranking) return null;
    const householdContext = getSmartPortionHouseholdContext();
    const people = getSmartPortionStartingPeople(overrides);
    const peopleValue = Number.isInteger(Number(people.value)) && Number(people.value) > 0 ? Number(people.value) : null;
    const explicitCurrentMeal = Number(overrides.currentMealServings ?? overrides.requestedMealServings);
    const selectedCurrentMeal = Number.isInteger(explicitCurrentMeal) && explicitCurrentMeal > 0 ? explicitCurrentMeal : peopleValue;
    return {
      portionSuggestionVersion: SMART_PORTION_SUGGESTION_VERSION,
      recipeCandidateId: ranking.eligibility?.candidateId || `recipe::${recipeId}::food-rescue`,
      recipeId,
      householdContext,
      peopleEating: people,
      currentMealServingOverride: Number.isInteger(explicitCurrentMeal) && explicitCurrentMeal > 0 ? explicitCurrentMeal : null,
      currentMealServings: selectedCurrentMeal,
      leftoverPreference: normalizePortionLeftoverPreference(overrides.leftoverPreference),
      additionalMealServingOverrides: [overrides.firstAdditionalMealServings, overrides.secondAdditionalMealServings].map((value) => Number(value)).filter((value) => Number.isInteger(value) && value >= 0),
      futureMealTargets: Array.isArray(overrides.futureMealTargets) ? overrides.futureMealTargets : [],
      selectedRescueSources: (ranking.usage?.sourceUses || []).map((source) => ({
        rescueSourceId: source.rescueSourceId,
        pantryItemId: source.pantryItemId || null,
        ingredientId: source.ingredientId || null,
        sourceRevision: source.sourceRevision || ""
      })),
      currentPlanContext: {
        planId: state.mealPlans?.id || null,
        targetDate: overrides.date || getCurrentDateString(),
        targetMealSlotId: overrides.mealType || "Dinner"
      },
      constraints: {
        maximumCookingTimeMinutes: getMealPlanningPreferences().maximumCookingMinutes || null,
        availableApplianceIds: normalizePlanningModeInputs(state.planningModeInputs).budgetRescue.availableAppliances || [],
        allergyProfileRevision: `${normalizeAllergies(getCurrentUser()?.allergies).join("|")}`,
        dietaryProfileRevision: getCurrentUser()?.dietaryPreference || ""
      },
      referenceDateTime: getCurrentIsoString(),
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "local",
      userScopeId: state.guestMode ? "guest" : getActiveUserId() || "none"
    };
  }

  function validateSmartPortionPeople(value) {
    const number = Number(value);
    return Number.isInteger(number) && number > 0 && number <= 20;
  }

  function getAdditionalMealCountForPreference(preference) {
    if (preference === PORTION_LEFTOVER_PREFERENCES.ONE_ADDITIONAL_MEAL) return 1;
    if (preference === PORTION_LEFTOVER_PREFERENCES.TWO_ADDITIONAL_MEALS) return 2;
    return 0;
  }

  function getSmartPortionCandidatePreferences(preference) {
    if (preference === PORTION_LEFTOVER_PREFERENCES.CHEF_NOVA_RECOMMEND) {
      return [PORTION_LEFTOVER_PREFERENCES.NONE, PORTION_LEFTOVER_PREFERENCES.ONE_ADDITIONAL_MEAL, PORTION_LEFTOVER_PREFERENCES.TWO_ADDITIONAL_MEALS];
    }
    return [preference].filter(Boolean);
  }

  function findSmartPortionFutureTargets({ recipe, currentDate, currentMealServings, additionalMealCount }) {
    if (!additionalMealCount) return [];
    const metadata = normalizeRecipeBatchMetadata(recipe);
    const leftovers = metadata.leftovers;
    if (leftovers.supported !== true || !Number.isFinite(Number(leftovers.storageWindowDays))) return [];
    const supportedMeals = new Set((leftovers.supportedTargetMealTypes || ["lunch", "dinner"]).map(normalizeIngredient));
    const targets = [];
    for (let dayOffset = 1; dayOffset <= Number(leftovers.storageWindowDays) && targets.length < additionalMealCount; dayOffset += 1) {
      const date = addDaysToDateString(currentDate, dayOffset);
      ["Lunch", "Dinner", "Breakfast", "Snack"].forEach((mealType) => {
        if (targets.length >= additionalMealCount) return;
        if (!supportedMeals.has(normalizeIngredient(mealType))) return;
        if (normalizeMealPlanEntry(getCalendarDayPlan(date)[mealType])) return;
        targets.push({
          targetType: "optional-future-meal",
          targetDate: date,
          mealSlotId: mealType,
          expectedPeople: currentMealServings,
          plannedServings: currentMealServings,
          confirmed: false
        });
      });
    }
    return targets;
  }

  function getSupportedRecipeYieldProfile(recipe, desiredYield) {
    const base = Number(recipe?.servings);
    if (!Number.isFinite(base) || base <= 0 || !Number.isFinite(Number(desiredYield)) || Number(desiredYield) <= 0) {
      return { supported: false, supportedYield: null, scaleFactor: null, batchCount: 0, profileType: "invalid", reason: "Recipe serving data needs review." };
    }
    const desired = Number(desiredYield);
    const scalable = recipe.scalable !== false;
    const minimum = Number.isFinite(Number(recipe.minimumServings)) ? Number(recipe.minimumServings) : base;
    const maximum = Number.isFinite(Number(recipe.maximumServings)) ? Number(recipe.maximumServings) : base;
    const increment = Number.isFinite(Number(recipe.servingIncrement)) && Number(recipe.servingIncrement) > 0 ? Number(recipe.servingIncrement) : 1;
    if (scalable && desired >= minimum && desired <= maximum) {
      const supportedYield = roundUpToServingIncrement(desired, increment);
      if (supportedYield <= maximum) return { supported: true, supportedYield, scaleFactor: supportedYield / base, batchCount: 1, profileType: "continuous", reason: "Recipe supports this serving range." };
    }
    const batchable = recipe.batchable === true || recipe.batchCooking?.supported === true;
    const maxBatches = Number.isInteger(Number(recipe.maximumBatches)) ? Number(recipe.maximumBatches) : Number(recipe.batchCooking?.maximumBatchCount || 1);
    const servingsPerBatch = Number(recipe.batchCooking?.maximumServingsPerBatch || recipe.batchCooking?.baseServings || base) || base;
    if (batchable) {
      const batchCount = Math.ceil(desired / servingsPerBatch);
      if (batchCount > 0 && batchCount <= Math.max(1, maxBatches)) return { supported: true, supportedYield: batchCount * servingsPerBatch, scaleFactor: servingsPerBatch / base, batchCount, profileType: "batch", reason: "Recipe can be prepared in supported batches." };
    }
    if (desired <= base) return { supported: true, supportedYield: base, scaleFactor: 1, batchCount: 1, profileType: "fixed", reason: `This recipe is prepared in a fixed ${base}-serving batch.` };
    return { supported: false, supportedYield: base, scaleFactor: 1, batchCount: 1, profileType: "unsupported", reason: "This recipe cannot produce that supported serving yield." };
  }

  function createSmartPortionProfile({ recipe, input, preference }) {
    const currentMealServings = Number(input.currentMealServings);
    const additionalMealCount = getAdditionalMealCountForPreference(preference);
    const futureTargets = findSmartPortionFutureTargets({ recipe, currentDate: input.currentPlanContext.targetDate, currentMealServings, additionalMealCount });
    const editedTargets = futureTargets.map((target, index) => Number.isInteger(input.additionalMealServingOverrides?.[index]) ? { ...target, plannedServings: input.additionalMealServingOverrides[index] } : target);
    const leftoversSupported = recipe?.leftovers?.supported === true || recipe?.batchCooking?.supported === true;
    const hasValidLeftoverTargets = additionalMealCount === 0 || (leftoversSupported && editedTargets.length >= additionalMealCount);
    const plannedLeftoverServings = hasValidLeftoverTargets ? editedTargets.slice(0, additionalMealCount).reduce((sum, target) => sum + (Number(target.plannedServings) || 0), 0) : 0;
    const desiredYield = currentMealServings + plannedLeftoverServings;
    const yieldProfile = getSupportedRecipeYieldProfile(recipe, desiredYield);
    const ranking = yieldProfile.supported ? recalculateFoodRescueRankingForServings(recipe.id, yieldProfile.supportedYield) : null;
    const viewModel = ranking ? buildFoodRescueCardViewModel(ranking) : null;
    const hardEligible = ranking?.eligibility?.status === RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE || ranking?.eligibility?.canUseForAutomaticPlanning === true;
    const unallocatedServings = Math.max(0, roundFoodRescueNumber((yieldProfile.supportedYield || 0) - currentMealServings - plannedLeftoverServings));
    const warnings = [];
    if (additionalMealCount > 0 && !leftoversSupported) warnings.push("Reviewed leftover guidance is unavailable for this recipe.");
    if (additionalMealCount > 0 && leftoversSupported && futureTargets.length < additionalMealCount) warnings.push("Chef Nova could not find enough open future meal slots inside the leftover window.");
    if (!yieldProfile.supported) warnings.push(yieldProfile.reason);
    if (ranking && !hardEligible) warnings.push(ranking.eligibility?.primaryReason?.message || "This serving option does not meet current hard requirements.");
    const eligible = yieldProfile.supported && hardEligible && currentMealServings > 0 && (additionalMealCount === 0 || hasValidLeftoverTargets);
    const metrics = {
      selectedFoodCoverage: ranking?.usage?.weightedCoverageRatio || 0,
      pantryCoverage: ranking?.pantryAllocation?.pantryCoverageRatio || 0,
      newPurchaseGroupCount: Number(ranking?.purchase?.newPurchaseGroupCount) || 0,
      marginalPurchaseCostCents: Number.isInteger(ranking?.purchase?.knownFullPackageCostCents) && !ranking?.purchase?.incompletePriceCount ? ranking.purchase.knownFullPackageCostCents : null,
      effectiveCookingTimeMinutes: ranking?.eligibility?.validatedContext?.effectiveCookingTimeMinutes ?? getRecipeTotalMinutes(recipe)
    };
    const score = calculateSmartPortionScore({ input, preference, profile: yieldProfile, currentMealServings, plannedLeftoverServings, unallocatedServings, metrics, eligible });
    return {
      profileId: `portion::${recipe.id}::${preference}::current-${currentMealServings}::yield-${yieldProfile.supportedYield || "unsupported"}`,
      preference,
      additionalMealCount,
      currentMealServings,
      plannedLeftoverServings,
      futureTargets: editedTargets.slice(0, additionalMealCount),
      desiredYield,
      yieldProfile,
      ranking,
      viewModel,
      metrics,
      score,
      eligible,
      warnings,
      reasonCodes: buildSmartPortionReasonCodes({ preference, additionalMealCount, unallocatedServings, metrics, eligible, warnings })
    };
  }

  function calculateSmartPortionScore({ input, preference, currentMealServings, plannedLeftoverServings, unallocatedServings, metrics, eligible }) {
    if (!eligible) return 0;
    const max = SMART_PORTION_SUGGESTION_CONFIG.scoreMaximums;
    const penalties = SMART_PORTION_SUGGESTION_CONFIG.penaltyMaximums;
    const currentFit = currentMealServings >= Number(input.currentMealServings) ? max.currentMealFit : 0;
    const preferenceFit = preference === input.leftoverPreference || input.leftoverPreference === PORTION_LEFTOVER_PREFERENCES.CHEF_NOVA_RECOMMEND ? max.leftoverPreferenceFit : 0;
    const positive = currentFit
      + preferenceFit
      + Math.min(max.selectedFoodCoverage, (metrics.selectedFoodCoverage || 0) * max.selectedFoodCoverage)
      + Math.min(max.pantryCoverage, (metrics.pantryCoverage || 0) * max.pantryCoverage)
      + Math.max(0, max.groceryPracticality - Number(metrics.newPurchaseGroupCount || 0))
      + max.cookingPracticality
      + (plannedLeftoverServings > 0 ? max.plannedLeftoverUtility : 0);
    const penalty = Math.min(penalties.unallocatedServings, unallocatedServings * 5)
      + Math.min(penalties.futureUnusedFoodRisk, Math.max(0, Number(metrics.newPurchaseGroupCount || 0) - 1) * 2)
      + (Number.isInteger(metrics.marginalPurchaseCostCents) ? 0 : penalties.incompleteData);
    return Math.max(0, Math.min(100, Math.round(positive - penalty)));
  }

  function buildSmartPortionReasonCodes({ preference, additionalMealCount, unallocatedServings, metrics, eligible, warnings }) {
    const codes = [];
    if (eligible) codes.push("meets-current-meal-servings");
    if (additionalMealCount === 0) codes.push("no-planned-leftovers");
    if (additionalMealCount === 1) codes.push("one-valid-leftover-meal");
    if (additionalMealCount === 2) codes.push("two-valid-leftover-meals");
    if (unallocatedServings === 0) codes.push("no-unallocated-servings");
    if ((metrics.selectedFoodCoverage || 0) > 0) codes.push("uses-selected-priority-food");
    if ((metrics.newPurchaseGroupCount || 0) === 0) codes.push("no-new-grocery-groups");
    if (preference === PORTION_LEFTOVER_PREFERENCES.CHEF_NOVA_RECOMMEND) codes.push("chef-nova-recommendation");
    warnings.forEach((warning) => codes.push(`review:${normalizeIngredient(warning).slice(0, 40)}`));
    return codes;
  }

  function compareSmartPortionProfiles(a, b, requestedPreference) {
    const explicit = requestedPreference !== PORTION_LEFTOVER_PREFERENCES.CHEF_NOVA_RECOMMEND;
    return Number(b.eligible) - Number(a.eligible)
      || (explicit ? Number(b.preference === requestedPreference) - Number(a.preference === requestedPreference) : b.score - a.score)
      || a.yieldProfile.supportedYield - b.yieldProfile.supportedYield
      || a.yieldProfile.batchCount - b.yieldProfile.batchCount
      || a.metrics.newPurchaseGroupCount - b.metrics.newPurchaseGroupCount
      || (a.metrics.marginalPurchaseCostCents ?? 999999) - (b.metrics.marginalPurchaseCostCents ?? 999999)
      || (a.metrics.effectiveCookingTimeMinutes ?? 9999) - (b.metrics.effectiveCookingTimeMinutes ?? 9999)
      || a.profileId.localeCompare(b.profileId);
  }

  function buildSmartPortionSuggestion(recipeId, overrides = {}) {
    const input = createSmartPortionInput(recipeId, overrides);
    const recipe = findRecipeById(recipeId);
    if (!input || !recipe) return null;
    if (!validateSmartPortionPeople(input.peopleEating.value) || !validateSmartPortionPeople(input.currentMealServings)) {
      return {
        portionSuggestionVersion: SMART_PORTION_SUGGESTION_VERSION,
        recommendationStatus: "needs-review",
        recipeCandidateId: input.recipeCandidateId,
        recipeId,
        peopleEating: input.peopleEating.value,
        input,
        warnings: ["Enter a positive whole number for People eating and Servings for tonight."],
        alternatives: []
      };
    }
    if (!input.leftoverPreference) {
      return {
        portionSuggestionVersion: SMART_PORTION_SUGGESTION_VERSION,
        recommendationStatus: "needs-leftover-preference",
        recipeCandidateId: input.recipeCandidateId,
        recipeId,
        peopleEating: input.peopleEating.value,
        input,
        warnings: ["Choose a leftover preference to see a portion suggestion."],
        alternatives: []
      };
    }
    const candidates = getSmartPortionCandidatePreferences(input.leftoverPreference)
      .map((preference) => createSmartPortionProfile({ recipe, input, preference }))
      .sort((a, b) => compareSmartPortionProfiles(a, b, input.leftoverPreference));
    const selected = candidates.find((candidate) => candidate.eligible) || candidates[0];
    if (!selected) return null;
    const level = selected.eligible ? "recommended" : "needs-review";
    return {
      portionSuggestionVersion: SMART_PORTION_SUGGESTION_VERSION,
      recommendationStatus: level,
      recipeCandidateId: input.recipeCandidateId,
      recipeId,
      peopleEating: input.peopleEating.value,
      currentMealServings: {
        suggested: input.peopleEating.value,
        selected: selected.currentMealServings,
        source: input.currentMealServingOverride ? "user-adjusted" : "people-eating-starting-point"
      },
      leftoverPlan: {
        preference: input.leftoverPreference,
        recommendedPreference: selected.preference,
        additionalMealCount: selected.additionalMealCount,
        plannedLeftoverServings: selected.plannedLeftoverServings,
        perMealTargets: selected.futureTargets
      },
      recipeYield: {
        originalBaseServings: Number(recipe.servings) || 1,
        desiredYield: selected.desiredYield,
        supportedYield: selected.yieldProfile.supportedYield,
        scaleFactor: selected.yieldProfile.scaleFactor,
        batchCount: selected.yieldProfile.batchCount,
        unallocatedServings: selected.yieldProfile.supportedYield === null ? 0 : Math.max(0, roundFoodRescueNumber(selected.yieldProfile.supportedYield - selected.currentMealServings - selected.plannedLeftoverServings)),
        profileType: selected.yieldProfile.profileType
      },
      projectedRecipeMetrics: selected.metrics,
      recommendation: {
        level,
        score: selected.score,
        explanation: buildSmartPortionExplanation(recipe, selected, input),
        reasonCodes: selected.reasonCodes
      },
      alternatives: candidates.filter((candidate) => candidate.profileId !== selected.profileId).slice(0, 3).map((candidate) => ({ profileId: candidate.profileId, preference: candidate.preference, supportedYield: candidate.yieldProfile.supportedYield, score: candidate.score, eligible: candidate.eligible, warnings: candidate.warnings })),
      warnings: selected.warnings,
      sourceRevisions: {
        userScopeId: input.userScopeId,
        householdRevision: input.householdContext.householdRevision,
        pantryRevision: createPantryRevisionSignature(),
        recipeRevision: `${recipe.id}:${recipe.updatedAt || recipe.recipeVersion || recipe.servings}`,
        portionSuggestionVersion: SMART_PORTION_SUGGESTION_VERSION,
        configVersion: SMART_PORTION_SUGGESTION_CONFIG.version,
        referenceLocalDate: input.currentPlanContext.targetDate,
        timezone: input.timezone
      },
      input,
      selectedRanking: selected.ranking,
      selectedViewModel: selected.viewModel
    };
  }

  function buildSmartPortionExplanation(recipe, profile, input) {
    if (!profile.eligible) return profile.warnings[0] || "This portion suggestion needs review before planning.";
    const yieldLabel = `${formatServingAmount(profile.yieldProfile.supportedYield)} ${pluralize(profile.yieldProfile.supportedYield, "serving")}`;
    const currentLabel = `${formatServingAmount(profile.currentMealServings)} ${pluralize(profile.currentMealServings, "serving")} for tonight`;
    const leftoverLabel = profile.plannedLeftoverServings > 0
      ? `${formatServingAmount(profile.plannedLeftoverServings)} optional ${pluralize(profile.plannedLeftoverServings, "serving")} for later`
      : "no planned leftovers";
    const unallocated = Math.max(0, Number(profile.yieldProfile.supportedYield || 0) - profile.currentMealServings - profile.plannedLeftoverServings);
    const unallocatedText = unallocated > 0 ? ` Approximately ${formatServingAmount(unallocated)} ${pluralize(unallocated, "serving")} would remain unassigned.` : " No unallocated servings.";
    if (input.leftoverPreference === PORTION_LEFTOVER_PREFERENCES.CHEF_NOVA_RECOMMEND) return `Chef Nova recommends ${yieldLabel}: ${currentLabel} and ${leftoverLabel}.${unallocatedText}`;
    return `${yieldLabel} matches your portion choice: ${currentLabel} and ${leftoverLabel}.${unallocatedText}`;
  }

  function createPantryRevisionSignature() {
    return state.pantry.map((item) => `${item.id}:${item.revision || 0}:${item.updatedAt || ""}:${item.quantityDetails?.currentQuantity ?? item.quantity ?? ""}`).sort().join("|");
  }

  function portionPreferenceLabel(value) {
    return {
      [PORTION_LEFTOVER_PREFERENCES.NONE]: "No leftovers",
      [PORTION_LEFTOVER_PREFERENCES.ONE_ADDITIONAL_MEAL]: "One additional meal",
      [PORTION_LEFTOVER_PREFERENCES.TWO_ADDITIONAL_MEALS]: "Two additional meals",
      [PORTION_LEFTOVER_PREFERENCES.CHEF_NOVA_RECOMMEND]: "Let Chef Nova recommend"
    }[value] || "Choose a leftover preference";
  }

  function renderSmartPortionSuggestionPanel(recipeId, suggestion, options = {}) {
    const recipe = findRecipeById(recipeId);
    const input = suggestion?.input || createSmartPortionInput(recipeId, options);
    const people = input?.peopleEating?.value ?? "";
    const currentServings = options.currentMealServings ?? suggestion?.currentMealServings?.selected ?? input?.currentMealServings ?? people ?? "";
    const preference = normalizePortionLeftoverPreference(options.leftoverPreference ?? input?.leftoverPreference);
    const editVisible = options.editing === true || suggestion?.currentMealServings?.source === "user-adjusted";
    const additionalOne = suggestion?.leftoverPlan?.perMealTargets?.[0]?.plannedServings ?? currentServings;
    const additionalTwo = suggestion?.leftoverPlan?.perMealTargets?.[1]?.plannedServings ?? currentServings;
    return `<section class="smart-portion-panel" aria-labelledby="smartPortionHeading" data-smart-portion-version="${SMART_PORTION_SUGGESTION_VERSION}">
      <div class="smart-portion-heading">
        <div>
          <span class="eyebrow">SMART PORTION SUGGESTION</span>
          <h3 id="smartPortionHeading">Smart Portion Suggestion</h3>
        </div>
        <span class="smart-portion-version">v${SMART_PORTION_SUGGESTION_VERSION}</span>
      </div>
      <p class="field-help">${escapeHtml(input?.householdContext?.explanation || "Chef Nova uses people eating as a starting serving suggestion. You can adjust the amount.")}</p>
      <label class="field-stack" for="smartPortionPeople">People eating tonight
        <input id="smartPortionPeople" type="number" min="1" max="20" step="1" inputmode="numeric" value="${escapeHtml(String(people || ""))}" data-smart-portion-input="${escapeHtml(recipeId)}" data-smart-portion-field="peopleEating" aria-describedby="smartPortionPeopleHelp smartPortionError">
      </label>
      <p class="field-help" id="smartPortionPeopleHelp">Chef Nova uses the number of people eating as a starting serving suggestion. You can adjust the amount.</p>
      <fieldset class="cook-tonight-radio-group smart-portion-leftovers">
        <legend>Would you like leftovers?</legend>
        ${Object.values(PORTION_LEFTOVER_PREFERENCES).map((value) => `<label><input type="radio" name="smartPortionLeftoverPreference" value="${value}" data-smart-portion-choice="${escapeHtml(recipeId)}" ${preference === value ? "checked" : ""}> ${escapeHtml(portionPreferenceLabel(value))}</label>`).join("")}
      </fieldset>
      <div class="smart-portion-editor" ${editVisible ? "" : "hidden"}>
        <label>Servings for tonight<input type="number" min="1" max="20" step="1" value="${escapeHtml(String(currentServings || ""))}" data-smart-portion-input="${escapeHtml(recipeId)}" data-smart-portion-field="currentMealServings"></label>
        <label>First additional meal<input type="number" min="0" max="20" step="1" value="${escapeHtml(String(additionalOne || 0))}" data-smart-portion-input="${escapeHtml(recipeId)}" data-smart-portion-field="firstAdditionalMealServings"></label>
        <label>Second additional meal<input type="number" min="0" max="20" step="1" value="${escapeHtml(String(additionalTwo || 0))}" data-smart-portion-input="${escapeHtml(recipeId)}" data-smart-portion-field="secondAdditionalMealServings"></label>
      </div>
      <div id="smartPortionPreview" aria-live="polite">${renderSmartPortionPreview(recipeId, suggestion)}</div>
      <p class="form-error" id="smartPortionError" role="alert"></p>
      <div class="meal-generation-actions smart-portion-actions">
        <button class="button primary" type="button" data-smart-portion-use="${escapeHtml(recipeId)}" aria-label="Use ${escapeHtml(recipe?.name || "this recipe")} portion suggestion">Use This Suggestion</button>
        <button class="button secondary" type="button" data-smart-portion-edit="${escapeHtml(recipeId)}" aria-label="Edit servings for ${escapeHtml(recipe?.name || "this recipe")}">Edit Servings</button>
        ${suggestion?.currentMealServings?.source === "user-adjusted" ? `<button class="button secondary" type="button" data-smart-portion-return="${escapeHtml(recipeId)}" aria-label="Return to Chef Nova's portion suggestion for ${escapeHtml(recipe?.name || "this recipe")}">Return to Chef Nova Suggestion</button>` : ""}
      </div>
    </section>`;
  }

  function getSmartPortionFormValues(recipeId) {
    const getField = (field) => $(`[data-smart-portion-input="${recipeId}"][data-smart-portion-field="${field}"]`)?.value;
    return {
      peopleEating: getField("peopleEating"),
      currentMealServings: getField("currentMealServings"),
      firstAdditionalMealServings: getField("firstAdditionalMealServings"),
      secondAdditionalMealServings: getField("secondAdditionalMealServings"),
      leftoverPreference: $("input[name='smartPortionLeftoverPreference']:checked")?.value || null
    };
  }

  function buildSmartPortionOverridesFromForm(recipeId, current = {}) {
    const values = getSmartPortionFormValues(recipeId);
    const people = Number(values.peopleEating);
    const currentMeal = Number(values.currentMealServings);
    const preference = normalizePortionLeftoverPreference(values.leftoverPreference);
    return {
      ...current,
      peopleEating: Number.isInteger(people) && people > 0 ? people : values.peopleEating,
      currentMealServings: Number.isInteger(currentMeal) && currentMeal > 0 ? currentMeal : undefined,
      requestedMealServings: Number.isInteger(currentMeal) && currentMeal > 0 ? currentMeal : undefined,
      firstAdditionalMealServings: Number.isInteger(Number(values.firstAdditionalMealServings)) && Number(values.firstAdditionalMealServings) >= 0 ? Number(values.firstAdditionalMealServings) : undefined,
      secondAdditionalMealServings: Number.isInteger(Number(values.secondAdditionalMealServings)) && Number(values.secondAdditionalMealServings) >= 0 ? Number(values.secondAdditionalMealServings) : undefined,
      leftoverPreference: preference
    };
  }

  function renderSmartPortionPreview(recipeId, suggestion) {
    if (!suggestion) return `<div class="food-rescue-stale" role="status"><b>Portion suggestion needs review</b><p>Chef Nova could not verify serving, Pantry, leftover, recipe, or calendar details. No Pantry quantity was changed.</p></div>`;
    if (suggestion.recommendationStatus === "needs-leftover-preference") return `<div class="smart-portion-result needs-review" role="status"><h4>Choose a leftover preference</h4><p>Chef Nova will calculate a supported recipe yield after you choose one option.</p></div>`;
    if (suggestion.recommendationStatus !== "recommended") return `<div class="smart-portion-result needs-review" role="status"><h4>Portion Suggestion Needs Review</h4>${suggestion.warnings.map((warning) => `<p>${escapeHtml(warning)}</p>`).join("")}<p>No Pantry quantity was changed.</p></div>`;
    const recipeYield = suggestion.recipeYield;
    const leftoverTargets = suggestion.leftoverPlan.perMealTargets || [];
    return `<div class="smart-portion-result recommended" role="status">
      <h4>Chef Nova's suggestion</h4>
      <dl class="cook-tonight-summary-list smart-portion-metrics">
        <div><dt>Original recipe</dt><dd>${escapeHtml(formatServingAmount(recipeYield.originalBaseServings))} ${escapeHtml(pluralize(recipeYield.originalBaseServings, "serving"))}</dd></div>
        <div><dt>Recommended recipe yield</dt><dd>${escapeHtml(formatServingAmount(recipeYield.supportedYield))} ${escapeHtml(pluralize(recipeYield.supportedYield, "serving"))}</dd></div>
        <div><dt>Tonight</dt><dd>${escapeHtml(formatServingAmount(suggestion.currentMealServings.selected))} ${escapeHtml(pluralize(suggestion.currentMealServings.selected, "serving"))}</dd></div>
        <div><dt>Optional leftover</dt><dd>${suggestion.leftoverPlan.plannedLeftoverServings ? `${escapeHtml(formatServingAmount(suggestion.leftoverPlan.plannedLeftoverServings))} ${escapeHtml(pluralize(suggestion.leftoverPlan.plannedLeftoverServings, "serving"))}` : "No planned leftovers"}</dd></div>
        <div><dt>Unallocated</dt><dd>${escapeHtml(formatServingAmount(recipeYield.unallocatedServings))} ${escapeHtml(pluralize(recipeYield.unallocatedServings, "serving"))}</dd></div>
        <div><dt>Cooking time</dt><dd>${suggestion.projectedRecipeMetrics.effectiveCookingTimeMinutes ? `${escapeHtml(String(suggestion.projectedRecipeMetrics.effectiveCookingTimeMinutes))} minutes` : "Needs review"}</dd></div>
      </dl>
      <p>${escapeHtml(suggestion.recommendation.explanation)}</p>
      ${leftoverTargets.length ? `<ul class="smart-portion-targets">${leftoverTargets.map((target) => `<li>${escapeHtml(formatServingAmount(target.plannedServings))} optional ${escapeHtml(pluralize(target.plannedServings, "serving"))} for ${escapeHtml(formatEmergencyDate(target.targetDate))} ${escapeHtml(target.mealSlotId)}</li>`).join("")}</ul>` : ""}
      ${suggestion.warnings.length ? `<div class="food-rescue-risk">${suggestion.warnings.map((warning) => `<p>${escapeHtml(warning)}</p>`).join("")}</div>` : ""}
    </div>`;
  }

  function updateSmartPortionPreview(recipeId) {
    const target = $("#smartPortionPreview");
    if (!target) return;
    const overrides = buildSmartPortionOverridesFromForm(recipeId);
    const suggestion = buildSmartPortionSuggestion(recipeId, overrides);
    target.innerHTML = renderSmartPortionPreview(recipeId, suggestion);
    announcePolite("Portion suggestion updated.", { key: `smart-portion-update-${recipeId}` });
  }

  function useSmartPortionSuggestion(recipeId) {
    const overrides = buildSmartPortionOverridesFromForm(recipeId);
    const suggestion = buildSmartPortionSuggestion(recipeId, overrides);
    if (!suggestion || suggestion.recommendationStatus !== "recommended") {
      const error = $("#smartPortionError");
      if (error) error.textContent = suggestion?.warnings?.[0] || "Review serving details before using this suggestion.";
      $("#smartPortionPeople")?.focus();
      return;
    }
    const updated = recalculateFoodRescueRankingForServings(recipeId, suggestion.recipeYield.supportedYield);
    if (!updated) return showToast("Chef Nova could not recheck the selected serving profile.", "warning");
    state.foodRescueRankingRequest = { ...(state.foodRescueRankingRequest || {}), householdContext: { ...(state.foodRescueRankingRequest?.householdContext || {}), requiredServings: suggestion.recipeYield.supportedYield, portionSuggestion: structuredCloneSafe(suggestion) } };
    state.foodRescueRankingResults = state.foodRescueRankingResults.map((result) => result.recipeId === recipeId ? updated : result).sort(compareFoodRescueRecipeResults);
    if (state.currentCookTonightWorkflow?.recipeId === recipeId) {
      const current = state.currentCookTonightWorkflow;
      state.currentCookTonightWorkflow = createCookTonightDraft(recipeId, {
        workflowId: current.workflowId,
        date: current.target.date,
        mealType: current.target.mealSlotId,
        peopleEating: suggestion.peopleEating,
        requestedMealServings: suggestion.currentMealServings.selected,
        plannedLeftoverServings: suggestion.leftoverPlan.plannedLeftoverServings,
        leftoverPreference: suggestion.leftoverPlan.preference,
        portionSuggestion: suggestion
      });
      if (state.currentCookTonightWorkflow) return renderCookTonightDraftStep(state.currentCookTonightWorkflow.workflowId);
    }
    closeMealPlanGenerationModal();
    searchRecipes({ requireIngredients: false, notify: false });
    announcePolite(`Portion suggestion applied. ${suggestion.recommendation.explanation}`, { key: `smart-portion-applied-${recipeId}` });
  }

  function toggleSmartPortionEditor(recipeId) {
    const editor = $(".smart-portion-editor");
    if (editor) {
      editor.hidden = !editor.hidden;
      if (!editor.hidden) editor.querySelector("input")?.focus();
    }
    updateSmartPortionPreview(recipeId);
  }

  function returnToSmartPortionSuggestion(recipeId) {
    const people = $(`[data-smart-portion-input="${recipeId}"][data-smart-portion-field="peopleEating"]`)?.value;
    const current = $(`[data-smart-portion-input="${recipeId}"][data-smart-portion-field="currentMealServings"]`);
    if (current) current.value = people || current.value;
    updateSmartPortionPreview(recipeId);
  }

  function recalculateFoodRescueRankingForServings(recipeId, selectedServings) {
    const current = getFoodRescueRankingByRecipeId(recipeId);
    if (!current || !state.foodRescueRankingRequest) return null;
    const nextRequest = structuredCloneSafe(state.foodRescueRankingRequest);
    nextRequest.householdContext = { ...(nextRequest.householdContext || {}), requiredServings: selectedServings };
    const sources = current.usage?.sourceUses?.map((source) => ({
      ...source,
      availableQuantity: source.availableQuantity,
      comparableQuantity: source.comparableQuantity,
      comparableUnit: source.comparableUnit,
      comparableDimension: source.comparableDimension
    })) || [];
    return rankRecipeForFoodRescue(current.recipe, sources, nextRequest, buildPersonalizedRecipeContext());
  }

  function openFoodRescuePortionAdjuster(recipeId) {
    const ranking = getFoodRescueRankingByRecipeId(recipeId);
    const viewModel = buildFoodRescueCardViewModel(ranking);
    if (!viewModel) return showToast("Portion adjustment is unavailable for this estimate.", "warning");
    const suggestion = buildSmartPortionSuggestion(recipeId, {});
    renderMealPlanGenerationModal(`<section class="food-rescue-portion-dialog" aria-labelledby="foodRescuePortionTitle">
      <div class="meal-generation-heading">
        <span class="eyebrow">FOOD RESCUE PREVIEW</span>
        <h2 id="foodRescuePortionTitle">Adjust portions for ${escapeHtml(viewModel.recipe.name)}</h2>
        <p>Preview changes only. Pantry, reservations, Shopping List, calendar, and Food Event History stay unchanged.</p>
      </div>
      ${renderSmartPortionSuggestionPanel(recipeId, suggestion)}
      <div class="meal-generation-actions">
        <button class="button primary" type="button" data-apply-food-rescue-portions="${escapeHtml(recipeId)}">Apply Preview</button>
        <button class="button secondary" type="button" data-cancel-generated-plan>Close</button>
      </div>
    </section>`);
  }

  function updateFoodRescuePortionPreview(recipeId) {
    const target = $("#foodRescuePortionPreview");
    const input = $(`[data-food-rescue-portion-input="${recipeId}"]`);
    if (!target || !input) return;
    const servings = Math.max(1, Math.floor(Number(input.value) || 1));
    if (String(servings) !== input.value) input.value = String(servings);
    target.innerHTML = renderFoodRescuePortionPreview(recipeId, servings);
  }

  function renderFoodRescuePortionPreview(recipeId, selectedServings) {
    const updated = recalculateFoodRescueRankingForServings(recipeId, selectedServings);
    if (!updated) return `<div class="food-rescue-stale" role="status"><b>Recipe estimate needs review</b><p>Chef Nova could not verify one or more current Pantry, serving, price, storage, or recipe quantities. No Pantry quantity was changed.</p></div>`;
    const viewModel = buildFoodRescueCardViewModel(updated);
    if (!viewModel) return `<div class="food-rescue-stale" role="status"><b>This portion is unavailable</b><p>This recipe cannot produce the selected serving amount using current hard requirements.</p></div>`;
    const original = getFoodRescueRankingByRecipeId(recipeId);
    const originalServings = Number(original?.selectedServings) || selectedServings;
    return `<div class="food-rescue-portion-preview" data-food-rescue-preview-servings="${escapeHtml(String(selectedServings))}">
      ${selectedServings < originalServings ? `<p class="food-rescue-risk">This portion is smaller than the current household serving suggestion.</p>` : ""}
      <dl class="food-rescue-metrics">
        <div><dt>Selected-food coverage</dt><dd>Approximately ${escapeHtml(String(viewModel.selectedFoodCoverage.displayPercent))}%</dd></div>
        <div><dt>Pantry coverage</dt><dd>${escapeHtml(String(viewModel.pantryCoverage.displayPercent))}%</dd></div>
        <div><dt>Additional checkout cost</dt><dd>${renderFoodRescueCostValue(viewModel.purchaseSummary)}</dd></div>
        <div><dt>Cooking time</dt><dd>${viewModel.cookingSummary.totalTimeMinutes === null ? "Needs review" : `${escapeHtml(String(viewModel.cookingSummary.totalTimeMinutes))} minutes`}</dd></div>
      </dl>
      <ul class="food-rescue-detail-list">${viewModel.projectedFoodUse.filter((source) => Number(source.projectedUsedQuantity) > 0).map((source) => `<li><b>${escapeHtml(source.foodName)}</b><span>Would use ${escapeHtml(formatQuantityForDisplay(source.projectedUsedQuantity))} ${escapeHtml(source.unit || "")}; ${escapeHtml(formatQuantityForDisplay(source.projectedRemainingQuantity))} ${escapeHtml(source.unit || "")} would remain.</span></li>`).join("")}</ul>
    </div>`;
  }

  function applyFoodRescuePortionPreview(recipeId) {
    const suggestion = buildSmartPortionSuggestion(recipeId, buildSmartPortionOverridesFromForm(recipeId));
    if (!suggestion || suggestion.recommendationStatus !== "recommended") return showToast(suggestion?.warnings?.[0] || "Review serving details before applying portions.", "warning");
    const selectedServings = suggestion.recipeYield.supportedYield;
    const updated = recalculateFoodRescueRankingForServings(recipeId, selectedServings);
    if (!updated) return showToast("Recipe estimate needs review before applying portions.", "warning");
    state.foodRescueRankingRequest = { ...(state.foodRescueRankingRequest || {}), householdContext: { ...(state.foodRescueRankingRequest?.householdContext || {}), requiredServings: selectedServings, portionSuggestion: structuredCloneSafe(suggestion) } };
    state.foodRescueRankingResults = state.foodRescueRankingResults.map((result) => result.recipeId === recipeId ? updated : result).sort(compareFoodRescueRecipeResults);
    closeMealPlanGenerationModal();
    searchRecipes({ requireIngredients: false, notify: false });
    announcePolite(`Portions updated. ${suggestion.recommendation.explanation}`, { key: "food-rescue-portion-update" });
  }

  function summarizeProjectedFoodUseForAnnouncement(ranking) {
    return (ranking.usage?.sourceUses || [])
      .filter((source) => Number(source.usedQuantity) > 0)
      .map((source) => `${formatQuantityForDisplay(source.usedQuantity)} ${source.unit || ""} of ${source.displayName}`.trim())
      .join(" and ") || "the selected food";
  }

  function openFoodRescueCookTonight(recipeId) {
    const draft = createCookTonightDraft(recipeId);
    if (!draft) return showToast("This recipe estimate has changed. Refresh recipe results before planning.", "warning");
    state.currentCookTonightWorkflow = draft;
    renderCookTonightDraftStep(draft.workflowId);
  }

  function confirmFoodRescueCookTonight(recipeId, mealType = "Dinner") {
    const draft = createCookTonightDraft(recipeId, { mealType });
    if (!draft) return showToast("This recipe estimate has changed. Refresh recipe results before planning.", "warning");
    state.currentCookTonightWorkflow = { ...draft, status: COOK_TONIGHT_WORKFLOW_STATUSES.AWAITING_CONFIRMATION };
    renderCookTonightReview(state.currentCookTonightWorkflow.workflowId);
  }

  function createCookTonightDraft(recipeId, overrides = {}) {
    const ranking = getFoodRescueRankingByRecipeId(recipeId);
    const viewModel = buildFoodRescueCardViewModel(ranking);
    if (!viewModel) return null;
    const recipe = findRecipeById(recipeId);
    if (!recipe) return null;
    const date = overrides.date || getCurrentDateString();
    const mealSlotId = CALENDAR_MEALS.includes(overrides.mealType) ? overrides.mealType : "Dinner";
    const portionSuggestion = overrides.portionSuggestion || buildSmartPortionSuggestion(recipeId, {
      peopleEating: overrides.peopleEating,
      currentMealServings: overrides.requestedMealServings ?? overrides.currentMealServings,
      leftoverPreference: overrides.leftoverPreference,
      firstAdditionalMealServings: overrides.firstAdditionalMealServings,
      secondAdditionalMealServings: overrides.secondAdditionalMealServings,
      date,
      mealType: mealSlotId
    });
    const people = clampWholeNumber(overrides.peopleEating ?? portionSuggestion?.peopleEating ?? viewModel.smartPortionStartingPoint.peopleEating ?? viewModel.servingSummary.householdSuggestedServings ?? 1, 1, 20);
    const mealServings = clampWholeNumber(overrides.requestedMealServings ?? portionSuggestion?.currentMealServings?.selected ?? people, 1, 20);
    const plannedLeftovers = Math.max(0, clampWholeNumber(overrides.plannedLeftoverServings ?? portionSuggestion?.leftoverPlan?.plannedLeftoverServings ?? 0, 0, 20));
    const plannedFrozenServings = Math.max(0, clampWholeNumber(overrides.plannedFrozenServings ?? overrides.servingAllocation?.plannedFrozenServings ?? 0, 0, 20));
    const plannedSharedServings = Math.max(0, clampWholeNumber(overrides.plannedSharedServings ?? overrides.servingAllocation?.plannedSharedServings ?? 0, 0, 20));
    const requiredRecipeYield = mealServings + plannedLeftovers + plannedFrozenServings + plannedSharedServings;
    const refreshed = recalculateFoodRescueRankingForServings(recipeId, requiredRecipeYield);
    const refreshedViewModel = buildFoodRescueCardViewModel(refreshed);
    if (!refreshed || !refreshedViewModel) return null;
    const workflowId = overrides.workflowId || `cook-tonight::${refreshedViewModel.candidateId}::${date}::${normalizeIngredient(mealSlotId)}`;
    const mealId = `cook-tonight-meal::${date}::${normalizeIngredient(mealSlotId)}::${recipeId}`;
    const pantryAllocationPreview = buildCookTonightPantryAllocationPreview(refreshed);
    const servingAllocationDraft = {
      servingsTonight: mealServings,
      plannedRefrigeratedLeftoverServings: plannedLeftovers,
      plannedFrozenServings,
      plannedSharedServings,
      unallocatedServingsAccepted: overrides.unallocatedServingsAccepted === true || overrides.servingAllocation?.unallocatedServingsAccepted === true,
      acknowledgement: overrides.unallocatedAcknowledgement || overrides.servingAllocation?.unallocatedAcknowledgement || null
    };
    const portionPreview = buildCookTonightPortionPreview({
      recipe,
      draftBase: { workflowId, mealId, target: { date, mealSlotId, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "local" }, peopleEating: people, recipeId, candidateId: refreshedViewModel.candidateId, recipeVariantId: refreshedViewModel.recipeVariantId, preparationMethodId: refreshedViewModel.preparationMethodId },
      ranking: refreshed,
      viewModel: refreshedViewModel,
      servingAllocation: servingAllocationDraft,
      portionSuggestion
    });
    return {
      workflowVersion: COOK_TONIGHT_WORKFLOW_VERSION,
      workflowId,
      mealId,
      status: COOK_TONIGHT_WORKFLOW_STATUSES.DRAFT,
      candidateId: refreshedViewModel.candidateId,
      recipeId,
      recipeVariantId: refreshedViewModel.recipeVariantId,
      preparationMethodId: refreshedViewModel.preparationMethodId,
      target: { date, mealSlotId, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "local" },
      peopleEating: { count: people, source: portionSuggestion?.input?.peopleEating?.source || "user-confirmed", userConfirmed: overrides.peopleEating !== undefined },
      servingPlan: {
        requestedMealServings: mealServings,
        plannedLeftoverServings: plannedLeftovers,
        plannedFrozenServings,
        plannedSharedServings,
        leftoverPreference: normalizePortionLeftoverPreference(overrides.leftoverPreference ?? portionSuggestion?.leftoverPlan?.preference),
        requiredRecipeYield,
        effectiveRecipeYield: refreshedViewModel.servingSummary.effectiveYield,
        scaleFactor: refreshedViewModel.servingSummary.scaleFactor,
        batchCount: refreshedViewModel.servingSummary.batchCount,
        practicalScaling: refreshed.scaleResult ? structuredCloneSafe(refreshed.scaleResult) : null,
        servingAllocationVersion: SERVING_ALLOCATION_VERSION,
        servingAllocation: portionPreview.servingAllocation,
        unallocatedServingsAccepted: portionPreview.servingAllocation.unallocatedServingsAccepted === true,
        portionSuggestion: portionSuggestion?.recommendationStatus === "recommended" ? structuredCloneSafe(portionSuggestion) : null
      },
      portionPreview,
      pantryAllocationPreview,
      missingPurchaseGroups: (refreshed.purchase?.purchaseGroups || []).map(normalizeCookTonightPurchaseGroup),
      leftoverPlan: createCookTonightLeftoverPlan(refreshedViewModel, plannedLeftovers),
      eligibilitySnapshot: structuredCloneSafe(refreshed.eligibility),
      costSnapshot: structuredCloneSafe(refreshed.purchase),
      sourceRevisions: refreshedViewModel.sourceRevisions || {},
      rescueRankingVersion: FOOD_RESCUE_RECIPE_RANKING_VERSION,
      cardViewModelVersion: FOOD_RESCUE_CARD_VIEW_MODEL_VERSION,
      userScope: state.guestMode ? "guest" : getActiveUserId() || "none",
      createdAt: getCurrentIsoString(),
      updatedAt: getCurrentIsoString()
    };
  }

  function buildCookTonightPortionPreview({ recipe, draftBase, ranking, viewModel, servingAllocation, portionSuggestion }) {
    const effectiveYield = Number(viewModel?.servingSummary?.effectiveYield ?? ranking?.practicalServings ?? servingAllocation?.servingsTonight ?? 1) || 1;
    const servingsTonight = Number(servingAllocation?.servingsTonight) || 0;
    const refrigerated = Number(servingAllocation?.plannedRefrigeratedLeftoverServings) || 0;
    const frozen = Number(servingAllocation?.plannedFrozenServings) || 0;
    const shared = Number(servingAllocation?.plannedSharedServings) || 0;
    const allocated = roundFoodRescueNumber(servingsTonight + refrigerated + frozen + shared);
    const invalid = allocated > effectiveYield + 1e-6;
    const unallocated = invalid ? Math.max(0, roundFoodRescueNumber(allocated - effectiveYield)) : Math.max(0, roundFoodRescueNumber(effectiveYield - allocated));
    const meaningfulCount = countMeaningfulPriorityFoodGroups(ranking?.usage?.sourceUses || []);
    const minimumReasons = deriveMinimumBatchReasonCodes(recipe, ranking, viewModel, { effectiveYield, servingsTonight, refrigerated, frozen, shared });
    const assessment = buildExcessPreparedFoodAssessment({ effectiveYield, allocated, unallocated, invalid, minimumReasons, accepted: servingAllocation?.unallocatedServingsAccepted === true });
    const basePreview = {
      portionPreviewVersion: PORTION_PREVIEW_VERSION,
      workflowId: draftBase.workflowId,
      candidateId: draftBase.candidateId,
      recipeId: draftBase.recipeId,
      recipeVariantId: draftBase.recipeVariantId || null,
      preparationMethodId: draftBase.preparationMethodId || null,
      target: draftBase.target,
      peopleEating: draftBase.peopleEating,
      servingAllocation: {
        servingAllocationVersion: SERVING_ALLOCATION_VERSION,
        servingsTonight,
        plannedRefrigeratedLeftoverServings: refrigerated,
        plannedFrozenServings: frozen,
        plannedSharedServings: shared,
        effectiveRecipeYield: effectiveYield,
        allocatedServings: allocated,
        unallocatedServings: unallocated,
        unallocatedServingsAccepted: servingAllocation?.unallocatedServingsAccepted === true,
        unallocatedAcknowledgement: servingAllocation?.acknowledgement || null
      },
      recipeYield: {
        requestedYield: servingsTonight + refrigerated + frozen + shared,
        minimumSupportedYield: Math.max(Number(recipe?.minimumServings) || Number(recipe?.servings) || effectiveYield, Number(recipe?.servings) || effectiveYield),
        maximumSupportedYield: Number(recipe?.maximumServings) || Number(recipe?.batchCooking?.maximumServingsPerBatch) || effectiveYield,
        effectiveYield,
        scaleFactor: viewModel?.servingSummary?.scaleFactor || ranking?.scaleResult?.scaleFactor || 1,
        batchCount: viewModel?.servingSummary?.batchCount || ranking?.eligibility?.batchCount || 1,
        servingProfileId: `${ranking?.scaleResult?.status || "supported"}::${viewModel?.servingSummary?.scaleFactor || 1}`
      },
      projectedRescue: {
        meaningfulPriorityFoodGroupCount: meaningfulCount,
        projectedFoodUseBySource: buildProjectedFoodUseGroups(ranking?.usage?.sourceUses || []),
        selectedFoodCoverage: ranking?.usage?.weightedCoverageRatio || 0,
        label: "Priority foods projected to be used"
      },
      groceryImpact: {
        newPurchaseGroupCount: Number(ranking?.purchase?.newPurchaseGroupCount) || 0,
        knownFullPackageCostCents: Number.isInteger(ranking?.purchase?.knownFullPackageCostCents) ? ranking.purchase.knownFullPackageCostCents : null,
        incompletePriceCount: Number(ranking?.purchase?.incompletePriceCount) || 0,
        purchaseGroups: ranking?.purchase?.purchaseGroups || []
      },
      excessPreparedFoodAssessment: assessment,
      sourceRevisions: {
        ...(viewModel?.sourceRevisions || {}),
        pantryRevision: createPantryRevisionSignature(),
        portionSuggestionVersion: SMART_PORTION_SUGGESTION_VERSION,
        practicalScaleResultVersion: ranking?.scaleResult?.version || null,
        portionPreviewVersion: PORTION_PREVIEW_VERSION,
        userScope: state.guestMode ? "guest" : getActiveUserId() || "none",
        referenceLocalDate: draftBase.target?.date || getCurrentDateString(),
        timezone: draftBase.target?.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || "local"
      },
      portionSuggestionVersion: portionSuggestion?.portionSuggestionVersion || SMART_PORTION_SUGGESTION_VERSION
    };
    return { ...basePreview, availableActions: buildPortionPreviewActions({ recipe, preview: basePreview, ranking, servingAllocation }) };
  }

  function countMeaningfulPriorityFoodGroups(sourceUses = []) {
    const ids = new Set();
    sourceUses.forEach((source) => {
      if (source.meaningfulUse !== true || Number(source.usedQuantity) <= 0) return;
      if (!source.ingredientId || source.priorityLevel === USE_FIRST_PRIORITY_LEVELS.MONITOR) return;
      ids.add(`${source.ingredientId}::${source.form || "default"}`);
    });
    return ids.size;
  }

  function buildProjectedFoodUseGroups(sourceUses = []) {
    const groups = new Map();
    sourceUses.forEach((source) => {
      if (Number(source.usedQuantity) <= 0 || !source.ingredientId) return;
      const key = `${source.ingredientId}::${source.form || "default"}`;
      if (!groups.has(key)) groups.set(key, { ingredientId: source.ingredientId, displayName: source.displayName || source.foodName || "Priority food", projectedUsedQuantity: 0, availableQuantity: 0, unit: source.unit || "", sourceCount: 0 });
      const group = groups.get(key);
      group.projectedUsedQuantity = roundFoodRescueNumber(group.projectedUsedQuantity + (Number(source.usedQuantity) || 0));
      group.availableQuantity = roundFoodRescueNumber(group.availableQuantity + (Number(source.availableQuantity) || 0));
      group.sourceCount += 1;
    });
    return Array.from(groups.values()).sort((a, b) => a.displayName.localeCompare(b.displayName) || a.ingredientId.localeCompare(b.ingredientId));
  }

  function deriveMinimumBatchReasonCodes(recipe, ranking, viewModel, allocation) {
    const reasons = [];
    const requested = Number(allocation.servingsTonight) + Number(allocation.refrigerated) + Number(allocation.frozen) + Number(allocation.shared);
    const effective = Number(allocation.effectiveYield);
    if (effective <= requested) return reasons;
    const profileType = ranking?.scaleResult?.scalingClass || ranking?.eligibility?.profileType || "";
    const smartProfile = viewModel?.smartPortionSuggestion?.recipeYield?.profileType || ranking?.servingProfile?.profileType || "";
    if (recipe?.scalable === false || smartProfile === "fixed") reasons.push(MINIMUM_BATCH_REASON_CODES.FIXED_RECIPE_YIELD);
    if (profileType === "baking-sensitive" || recipe?.bakingSensitive) reasons.push(MINIMUM_BATCH_REASON_CODES.BAKING_PROFILE);
    if ((ranking?.scaleResult?.materialAdjustments || []).some((item) => item.policyId?.includes("whole") || item.mode === "whole-item")) reasons.push(MINIMUM_BATCH_REASON_CODES.WHOLE_ITEM_MINIMUM);
    if ((ranking?.scaleResult?.materialAdjustments || []).some((item) => item.policyId?.includes("minimum-cooking-liquid"))) reasons.push(MINIMUM_BATCH_REASON_CODES.MINIMUM_COOKING_LIQUID);
    if (recipe?.batchCooking?.supported || smartProfile === "batch") reasons.push(MINIMUM_BATCH_REASON_CODES.METHOD_BATCH_REQUIREMENT);
    if (!reasons.length) reasons.push(MINIMUM_BATCH_REASON_CODES.MINIMUM_RECIPE_QUANTITY);
    return [...new Set(reasons)].sort();
  }

  function buildExcessPreparedFoodAssessment({ effectiveYield, allocated, unallocated, invalid, minimumReasons, accepted }) {
    if (invalid) return { status: EXCESS_PREPARED_FOOD_STATUSES.INVALID, unallocatedServings: unallocated, unallocatedRatio: 0, effectiveYield, allocatedServings: allocated, reasonCodes: ["allocation-exceeds-yield"], requiresDecision: true, requiresExplicitAcceptance: true };
    if (unallocated <= 0) return { status: EXCESS_PREPARED_FOOD_STATUSES.NONE, unallocatedServings: 0, unallocatedRatio: 0, effectiveYield, allocatedServings: allocated, reasonCodes: [], requiresDecision: false, requiresExplicitAcceptance: false };
    const ratio = effectiveYield > 0 ? unallocated / effectiveYield : 0;
    const status = accepted ? EXCESS_PREPARED_FOOD_STATUSES.LOW : EXCESS_PREPARED_FOOD_STATUSES.DECISION_REQUIRED;
    return { status, unallocatedServings: unallocated, unallocatedRatio: roundFoodRescueNumber(ratio), effectiveYield, allocatedServings: allocated, reasonCodes: minimumReasons, requiresDecision: !accepted, requiresExplicitAcceptance: !accepted };
  }

  function canPlanPreparedFoodFreezing(recipe) {
    const recipeAllowsLeftovers = (recipe?.leftovers?.supported === true && recipe?.leftovers?.freezerStorage?.supported !== false)
      || (recipe?.batchCooking?.supported === true && recipe?.leftovers?.supported === true);
    if (!recipeAllowsLeftovers) return false;
    const guidance = resolveFreezerGuidance({ recipe, freezerProfile: getCurrentFreezerProfile(), foodSafetyGuardrail: createFoodSafetyResult({ decision: FOOD_SAFETY_DECISIONS.ELIGIBLE, canUseForAutomaticPlanning: true, requiresUserReview: false }) });
    return guidance.suitability.canRecommendFreezing === true;
  }

  function buildPortionPreviewActions({ recipe, preview, ranking }) {
    const unallocated = Number(preview.servingAllocation.unallocatedServings) || 0;
    if (unallocated <= 0 || preview.excessPreparedFoodAssessment.status === EXCESS_PREPARED_FOOD_STATUSES.INVALID) return [];
    const actions = [];
    const freezeAllowed = canPlanPreparedFoodFreezing(recipe);
    if (freezeAllowed) actions.push({
      optionId: `plan-freeze-${unallocated}`,
      optionType: EXCESS_SERVING_OPTION_TYPES.PLAN_FREEZE,
      label: `Cook and Freeze ${formatServingAmount(unallocated)} ${pluralize(unallocated, "Serving")}`,
      accessibleLabel: `Cook ${formatServingAmount(preview.servingAllocation.effectiveRecipeYield)} servings and plan to freeze ${formatServingAmount(unallocated)} servings of ${recipe?.name || "this recipe"}`,
      available: true,
      recommended: true,
      affectedServings: unallocated,
      disabledReason: null,
      explanationReasonCodes: ["prepared-food-freezing-supported", "eliminates-unallocated-servings"]
    });
    actions.push({
      optionId: `find-smaller-${preview.servingAllocation.servingsTonight}`,
      optionType: EXCESS_SERVING_OPTION_TYPES.FIND_SMALLER_RECIPE,
      label: "Find a Smaller Recipe",
      accessibleLabel: `Find a smaller recipe for ${formatServingAmount(preview.servingAllocation.servingsTonight)} ${pluralize(preview.servingAllocation.servingsTonight, "person")} using the selected priority food`,
      available: true,
      recommended: !freezeAllowed,
      affectedServings: unallocated,
      disabledReason: null,
      explanationReasonCodes: ["smaller-supported-yield", "reuse-food-rescue-ranking"]
    });
    actions.push({
      optionId: `plan-share-${unallocated}`,
      optionType: EXCESS_SERVING_OPTION_TYPES.PLAN_SHARE,
      label: `Plan to Share ${formatServingAmount(unallocated)} ${pluralize(unallocated, "Serving")}`,
      accessibleLabel: `Cook ${formatServingAmount(preview.servingAllocation.effectiveRecipeYield)} servings and plan to share ${formatServingAmount(unallocated)} servings`,
      available: ranking?.eligibility?.status === RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE,
      recommended: false,
      affectedServings: unallocated,
      disabledReason: ranking?.eligibility?.status === RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE ? null : "Current food-safety or hard-filter data needs review before sharing can be planned.",
      explanationReasonCodes: ["planned-sharing", "post-cooking-confirmation-required"]
    });
    actions.push({
      optionId: `keep-full-yield-${preview.servingAllocation.effectiveRecipeYield}`,
      optionType: EXCESS_SERVING_OPTION_TYPES.KEEP_FULL_YIELD,
      label: `Keep ${formatServingAmount(preview.servingAllocation.effectiveRecipeYield)} ${pluralize(preview.servingAllocation.effectiveRecipeYield, "Serving")}`,
      accessibleLabel: `Keep the full ${formatServingAmount(preview.servingAllocation.effectiveRecipeYield)} serving batch with ${formatServingAmount(unallocated)} servings currently unallocated`,
      available: ranking?.eligibility?.status === RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE,
      recommended: false,
      affectedServings: unallocated,
      disabledReason: null,
      explanationReasonCodes: ["explicit-unallocated-acceptance-required"]
    });
    return actions.filter((action) => action.available || action.disabledReason).sort((a, b) => Number(b.recommended) - Number(a.recommended) || a.optionType.localeCompare(b.optionType));
  }

  function normalizeCookTonightPurchaseGroup(group = {}) {
    return {
      purchaseGroupId: group.purchaseGroupId || `cook-tonight-purchase::${group.ingredientId || normalizeIngredient(group.displayText || "item")}`,
      ingredientId: group.ingredientId || null,
      displayName: getIngredientDisplayNameById(group.ingredientId, group.displayText || group.displayName || "Grocery item"),
      missingQuantity: Number(group.missingQuantity) || 0,
      missingUnit: group.missingUnit || group.totalRequiredUnit || group.unit || "",
      suggestedPurchaseText: typeof getSuggestedPurchaseText === "function" ? getSuggestedPurchaseText(group) : `${formatQuantityForDisplay(group.missingQuantity || 1)} ${group.missingUnit || ""}`.trim(),
      priceStatus: group.status || "needs-review"
    };
  }

  function renderCookTonightPortionPreview(preview, options = {}) {
    if (!preview) return `<section class="portion-preview needs-review" aria-labelledby="portionPreviewTitle"><h3 id="portionPreviewTitle">Portion Preview Needs Review</h3><p>Chef Nova could not verify one or more serving, recipe, Pantry, freezer, sharing, leftover, or grocery details. No Pantry quantity was changed.</p></section>`;
    const allocation = preview.servingAllocation || {};
    const assessment = preview.excessPreparedFoodAssessment || {};
    const unallocated = Number(allocation.unallocatedServings) || 0;
    const projectedRows = preview.projectedRescue?.projectedFoodUseBySource || [];
    const compact = options.compact === true;
    return `<section class="portion-preview ${escapeHtml(assessment.status || "none")}" aria-labelledby="portionPreviewTitle" data-portion-preview-version="${PORTION_PREVIEW_VERSION}">
      <div class="portion-preview-heading">
        <div>
          <span class="eyebrow">PORTION PREVIEW</span>
          <h3 id="portionPreviewTitle">${compact ? "Final Portion Plan" : "Portion Preview"}</h3>
        </div>
        <span class="smart-portion-version">v${PORTION_PREVIEW_VERSION}</span>
      </div>
      ${renderMinimumBatchNotice(preview)}
      <dl class="portion-preview-metrics">
        <div><dt>People eating</dt><dd>${escapeHtml(String(preview.peopleEating || 0))}</dd></div>
        <div><dt>Servings for tonight</dt><dd>${escapeHtml(formatServingAmount(allocation.servingsTonight || 0))}</dd></div>
        <div><dt>Planned refrigerated leftovers</dt><dd>${escapeHtml(formatServingAmount(allocation.plannedRefrigeratedLeftoverServings || 0))}</dd></div>
        <div><dt>Planned frozen servings</dt><dd>${escapeHtml(formatServingAmount(allocation.plannedFrozenServings || 0))}</dd></div>
        <div><dt>Planned shared servings</dt><dd>${escapeHtml(formatServingAmount(allocation.plannedSharedServings || 0))}</dd></div>
        <div><dt>Effective recipe yield</dt><dd>${escapeHtml(formatServingAmount(allocation.effectiveRecipeYield || 0))}</dd></div>
        <div><dt>${escapeHtml(preview.projectedRescue?.label || "Priority foods projected to be used")}</dt><dd>${escapeHtml(String(preview.projectedRescue?.meaningfulPriorityFoodGroupCount || 0))}</dd></div>
        <div><dt>Estimated unallocated prepared food</dt><dd>${escapeHtml(formatServingAmount(unallocated))} ${escapeHtml(pluralize(unallocated, "serving"))}</dd></div>
      </dl>
      <p class="field-help">${unallocated > 0 ? `This recipe would produce ${formatServingAmount(unallocated)} ${pluralize(unallocated, "serving")} without a current planned use. This does not mean the food has been wasted.` : "Every planned serving has a current use."}</p>
      ${projectedRows.length ? `<details class="portion-preview-details"><summary>Priority food use</summary><ul>${projectedRows.map((row) => `<li><b>${escapeHtml(row.displayName)}</b><span>${escapeHtml(formatShoppingQuantity(row.projectedUsedQuantity, row.unit))} of ${escapeHtml(formatShoppingQuantity(row.availableQuantity, row.unit))} projected to be used</span></li>`).join("")}</ul></details>` : ""}
      ${renderPortionPreviewGroceryImpact(preview)}
      ${options.showActions === false ? "" : renderPortionPreviewActions(preview)}
    </section>`;
  }

  function renderMinimumBatchNotice(preview) {
    const allocation = preview?.servingAllocation || {};
    const unallocated = Number(allocation.unallocatedServings) || 0;
    if (unallocated <= 0 || preview.excessPreparedFoodAssessment?.status === EXCESS_PREPARED_FOOD_STATUSES.INVALID) return "";
    const reason = minimumBatchReasonText(preview);
    return `<div class="minimum-batch-notice" role="status">
      <h4>Minimum Batch Notice</h4>
      <p>${escapeHtml(reason)}</p>
      <dl>
        <div><dt>People eating tonight</dt><dd>${escapeHtml(String(preview.peopleEating || 0))}</dd></div>
        <div><dt>Servings required tonight</dt><dd>${escapeHtml(formatServingAmount(allocation.servingsTonight || 0))}</dd></div>
        <div><dt>Minimum supported yield</dt><dd>${escapeHtml(formatServingAmount(preview.recipeYield?.minimumSupportedYield || allocation.effectiveRecipeYield || 0))}</dd></div>
        <div><dt>Servings without a current use</dt><dd>${escapeHtml(formatServingAmount(unallocated))}</dd></div>
      </dl>
    </div>`;
  }

  function minimumBatchReasonText(preview) {
    const reasons = preview?.excessPreparedFoodAssessment?.reasonCodes || [];
    const yieldText = formatServingAmount(preview?.servingAllocation?.effectiveRecipeYield || 0);
    if (reasons.includes(MINIMUM_BATCH_REASON_CODES.SLOW_COOKER_MINIMUM_VOLUME)) return `The selected slow-cooker method requires a minimum ${yieldText}-serving batch.`;
    if (reasons.includes(MINIMUM_BATCH_REASON_CODES.BLENDER_MINIMUM_VOLUME)) return `The selected blender method requires a minimum ${yieldText}-serving batch.`;
    if (reasons.includes(MINIMUM_BATCH_REASON_CODES.BAKING_PROFILE)) return `This baking recipe uses validated serving profiles and cannot be reduced to the requested amount.`;
    if (reasons.includes(MINIMUM_BATCH_REASON_CODES.WHOLE_ITEM_MINIMUM)) return `The smaller amount is not supported because the recipe would require an unsupported partial structural ingredient.`;
    if (reasons.includes(MINIMUM_BATCH_REASON_CODES.FIXED_RECIPE_YIELD)) return `This recipe is prepared in a fixed ${yieldText}-serving batch.`;
    return `This recipe is prepared in a minimum ${yieldText}-serving batch.`;
  }

  function renderPortionPreviewGroceryImpact(preview) {
    const count = Number(preview?.groceryImpact?.newPurchaseGroupCount) || 0;
    if (!count) return "";
    const cost = Number.isInteger(preview.groceryImpact.knownFullPackageCostCents) && !preview.groceryImpact.incompletePriceCount
      ? formatCostCents(preview.groceryImpact.knownFullPackageCostCents)
      : "Incomplete estimate";
    return `<div class="portion-preview-grocery-impact"><p>Projected additional groceries: ${escapeHtml(String(count))}. Estimated additional checkout cost: ${escapeHtml(cost)}.</p></div>`;
  }

  function renderPortionPreviewActions(preview) {
    const actions = preview.availableActions || [];
    if (!actions.length) return "";
    return `<fieldset class="portion-preview-options">
      <legend>Choose a plan for extra servings</legend>
      ${actions.map((action) => `<button class="button ${action.optionType === EXCESS_SERVING_OPTION_TYPES.KEEP_FULL_YIELD ? "secondary" : "primary"} small" type="button" data-portion-preview-option="${escapeHtml(action.optionType)}" data-workflow-id="${escapeHtml(preview.workflowId)}" aria-label="${escapeHtml(action.accessibleLabel)}"${action.available ? "" : " disabled"}>${escapeHtml(action.label)}</button>${action.disabledReason ? `<p class="field-help">${escapeHtml(action.disabledReason)}</p>` : ""}`).join("")}
    </fieldset>`;
  }

  function applyPortionPreviewOption(workflowId, optionType) {
    const current = getCurrentCookTonightWorkflow(workflowId);
    if (!current?.portionPreview) return showToast("Portion preview needs review.", "warning");
    const unallocated = Number(current.portionPreview.servingAllocation?.unallocatedServings) || 0;
    if (optionType === EXCESS_SERVING_OPTION_TYPES.FIND_SMALLER_RECIPE) {
      seeOtherFoodRescueRecipes(current.recipeId);
      announcePolite("Searching for smaller eligible recipes using the selected priority food.", { key: `portion-preview-smaller-${workflowId}` });
      return;
    }
    const base = {
      peopleEating: current.peopleEating.count,
      requestedMealServings: current.servingPlan.requestedMealServings,
      plannedLeftoverServings: current.servingPlan.plannedLeftoverServings,
      plannedFrozenServings: 0,
      plannedSharedServings: 0,
      leftoverPreference: current.servingPlan.leftoverPreference,
      portionSuggestion: current.servingPlan.portionSuggestion,
      date: current.target.date,
      mealType: current.target.mealSlotId,
      workflowId: current.workflowId
    };
    let message = "Portion preview updated.";
    if (optionType === EXCESS_SERVING_OPTION_TYPES.PLAN_FREEZE) {
      base.plannedFrozenServings = unallocated;
      message = `${formatServingAmount(unallocated)} ${pluralize(unallocated, "serving")} planned for freezing after cooking. No food has been marked frozen.`;
    } else if (optionType === EXCESS_SERVING_OPTION_TYPES.PLAN_SHARE) {
      base.plannedSharedServings = unallocated;
      message = `${formatServingAmount(unallocated)} ${pluralize(unallocated, "serving")} planned for sharing after cooking. No food has been recorded as shared.`;
    } else if (optionType === EXCESS_SERVING_OPTION_TYPES.KEEP_FULL_YIELD) {
      base.unallocatedServingsAccepted = true;
      base.unallocatedAcknowledgement = { unallocatedServingsAccepted: true, acceptedUnallocatedServings: unallocated, acceptedAt: getCurrentIsoString(), acknowledgementVersion: 1 };
      message = `${formatServingAmount(unallocated)} ${pluralize(unallocated, "serving")} remain unallocated and will be reviewed after cooking.`;
    }
    const next = createCookTonightDraft(current.recipeId, base);
    if (!next) return showCookTonightNeedsReview("Chef Nova recalculated the portion plan and it needs review.");
    state.currentCookTonightWorkflow = { ...next, status: current.status };
    if (current.status === COOK_TONIGHT_WORKFLOW_STATUSES.AWAITING_CONFIRMATION) renderCookTonightReview(next.workflowId);
    else renderCookTonightDraftStep(next.workflowId);
    announcePolite(message, { key: `portion-preview-option-${workflowId}` });
  }

  function buildCookTonightPantryAllocationPreview(ranking) {
    const byId = new Map((ranking.usage?.sourceUses || []).map((source) => [source.pantryItemId, source]));
    const allocationRows = (ranking.pantryAllocation?.requirementAllocations || []).flatMap((requirement) => requirement.pantryAllocations || []);
    const rows = allocationRows.map((allocation, index) => {
      const item = normalizePantryItem(state.pantry.find((candidate) => candidate.id === allocation.pantryItemId) || {});
      const quantity = item.quantityDetails || {};
      const sourceUse = byId.get(allocation.pantryItemId);
      const unit = allocation.unit || quantity.unit || item.unit || sourceUse?.unit || "";
      const planned = Number(allocation.quantity ?? sourceUse?.usedQuantity) || 0;
      const current = Number(quantity.currentQuantity);
      const reserved = deriveReservedQuantity(item);
      const available = Number.isFinite(current) ? Math.max(0, current - reserved) : null;
      return {
        allocationId: `allocation::${allocation.pantryItemId || "pantry"}::${index}`,
        pantryItemId: allocation.pantryItemId || sourceUse?.pantryItemId || "",
        rescueSourceId: sourceUse?.rescueSourceId || "",
        ingredientId: sourceUse?.ingredientId || item.ingredientId || allocation.ingredientId || null,
        displayName: item.displayName || item.name || sourceUse?.displayName || allocation.originalLabel || "Pantry item",
        lotLabel: getPantryLotLabel(item),
        plannedQuantity: roundFoodRescueNumber(planned),
        unit,
        currentQuantity: Number.isFinite(current) ? current : null,
        alreadyReservedQuantity: reserved,
        availableQuantity: available,
        wouldRemainQuantity: available === null ? null : Math.max(0, roundFoodRescueNumber(available - planned)),
        sourceRevision: `${item.updatedAt || item.createdAt || ""}:${quantity.currentQuantity}:${quantity.unit || ""}`,
        reservationId: ""
      };
    }).filter((row) => row.pantryItemId && row.plannedQuantity > 0);
    return rows.length ? rows : (ranking.usage?.sourceUses || []).filter((source) => Number(source.usedQuantity) > 0).map((source, index) => {
      const item = normalizePantryItem(state.pantry.find((candidate) => candidate.id === source.pantryItemId) || {});
      const current = Number(item.quantityDetails?.currentQuantity);
      const reserved = deriveReservedQuantity(item);
      const available = Number.isFinite(current) ? Math.max(0, current - reserved) : Number(source.availableQuantity) || null;
      return {
        allocationId: `source-allocation::${source.rescueSourceId || index}`,
        pantryItemId: source.pantryItemId || "",
        rescueSourceId: source.rescueSourceId || "",
        ingredientId: source.ingredientId || item.ingredientId || null,
        displayName: item.displayName || item.name || source.displayName || "Pantry item",
        lotLabel: getPantryLotLabel(item),
        plannedQuantity: roundFoodRescueNumber(source.usedQuantity),
        unit: source.unit || item.unit || "",
        currentQuantity: Number.isFinite(current) ? current : null,
        alreadyReservedQuantity: reserved,
        availableQuantity: available,
        wouldRemainQuantity: available === null ? null : Math.max(0, roundFoodRescueNumber(available - Number(source.usedQuantity || 0))),
        sourceRevision: `${item.updatedAt || item.createdAt || ""}:${item.quantityDetails?.currentQuantity}:${item.quantityDetails?.unit || ""}`,
        reservationId: ""
      };
    });
  }

  function getPantryLotLabel(item = {}) {
    const storage = item.storage?.location ? pantryLabelFor(item.storage.location, { pantry: "Pantry", refrigerator: "Refrigerator", freezer: "Freezer", counter: "Counter", "cellar-cool-storage": "Cellar or cool storage", other: item.storage?.locationNote ? `Other: ${item.storage.locationNote}` : "Other", unknown: "" }) : item.location || "";
    const opened = item.lifecycle?.packageState === PANTRY_PACKAGE_STATES.OPENED || item.opened ? "opened package" : "";
    return [opened, storage].filter(Boolean).join(", ");
  }

  function createCookTonightLeftoverPlan(viewModel, plannedLeftovers) {
    const recipe = findRecipeById(viewModel.recipeId);
    if (!plannedLeftovers) return { requested: false, plannedLeftoverServings: 0, storageGuidanceAvailable: false, guidance: "No planned leftovers." };
    const supported = recipe?.leftovers?.supported === true || recipe?.batchCooking?.supported === true;
    return {
      requested: true,
      plannedLeftoverServings: plannedLeftovers,
      expectedLeftoverServings: plannedLeftovers,
      storageGuidanceAvailable: supported,
      guidance: supported ? "Reviewed leftover guidance is available for this recipe. Confirm actual storage after cooking." : "Leftover storage guidance is unavailable. Chef Nova cannot automatically schedule this leftover for reuse."
    };
  }

  function getCurrentCookTonightWorkflow(workflowId) {
    return state.currentCookTonightWorkflow?.workflowId === workflowId ? state.currentCookTonightWorkflow : null;
  }

  function renderCookTonightDraftStep(workflowId) {
    const draft = getCurrentCookTonightWorkflow(workflowId);
    if (!draft) return showToast("Tonight's plan needs review.", "warning");
    const recipe = findRecipeById(draft.recipeId);
    const existing = normalizeMealPlanEntry(getCalendarDayPlan(draft.target.date)[draft.target.mealSlotId]);
    renderMealPlanGenerationModal(`<section class="cook-tonight-workflow" aria-labelledby="cookTonightDraftTitle">
      <div class="meal-generation-heading">
        <span class="eyebrow">TONIGHT'S FOOD-RESCUE PLAN</span>
        <h2 id="cookTonightDraftTitle">Confirm Pantry amounts</h2>
        <p>Review current amounts before Chef Nova reserves food for tonight.</p>
      </div>
      ${renderFoodSafetyNotice()}
      <ol class="cook-tonight-steps" aria-label="Cook This Tonight progress">
        <li aria-current="step">Confirm amounts</li><li>People and servings</li><li>Review plan</li><li>Start cooking</li><li>Confirm outcome</li>
      </ol>
      <section class="cook-tonight-card">
        <h3>${escapeHtml(recipe?.name || "Recipe")}</h3>
        <p>${escapeHtml(formatEmergencyDate(draft.target.date))} - ${escapeHtml(draft.target.mealSlotId)}</p>
        ${existing ? `<div class="food-rescue-risk" role="status"><p>${escapeHtml(formatEmergencyDate(draft.target.date))} ${escapeHtml(draft.target.mealSlotId.toLowerCase())} already has ${escapeHtml(existing.recipeName)} planned. Confirming will replace that meal.</p></div>` : ""}
      </section>
      <section class="cook-tonight-card" aria-labelledby="cookTonightPantryAmountsTitle">
        <h3 id="cookTonightPantryAmountsTitle">Pantry amount check</h3>
        <ul class="cook-tonight-allocation-list">${draft.pantryAllocationPreview.map(renderCookTonightAllocationRow).join("") || "<li>No tracked Pantry quantities would be reserved.</li>"}</ul>
      </section>
      <form class="cook-tonight-form" id="cookTonightDraftForm">
        ${renderSmartPortionSuggestionPanel(recipe?.id || draft.recipeId, draft.servingPlan.portionSuggestion, {
          peopleEating: draft.peopleEating.count,
          currentMealServings: draft.servingPlan.requestedMealServings,
          leftoverPreference: draft.servingPlan.leftoverPreference,
          date: draft.target.date,
          mealType: draft.target.mealSlotId
        })}
        ${renderCookTonightPortionPreview(draft.portionPreview)}
        <p class="form-error" id="cookTonightDraftError" role="alert"></p>
      </form>
      <div class="meal-generation-actions">
        <button class="button primary" type="button" data-cook-tonight-review="${escapeHtml(workflowId)}" aria-label="Review tonight's plan for ${escapeHtml(recipe?.name || "this recipe")}">Amounts Are Correct</button>
        <button class="button secondary" type="button" data-page="pantry">Edit Pantry Amounts</button>
        <button class="button secondary" type="button" data-cancel-generated-plan>Cancel</button>
      </div>
    </section>`);
  }

  function renderCookTonightAllocationRow(row) {
    return `<li>
      <b>${escapeHtml(row.displayName)}</b>
      ${row.lotLabel ? `<span>${escapeHtml(row.lotLabel)}</span>` : ""}
      <dl>
        <div><dt>Recipe plans to use</dt><dd>${escapeHtml(formatShoppingQuantity(row.plannedQuantity, row.unit))}</dd></div>
        <div><dt>Currently recorded</dt><dd>${row.currentQuantity === null ? "Amount unknown" : escapeHtml(formatShoppingQuantity(row.currentQuantity, row.unit))}</dd></div>
        <div><dt>Already reserved</dt><dd>${escapeHtml(formatShoppingQuantity(row.alreadyReservedQuantity || 0, row.unit))}</dd></div>
        <div><dt>Available after reservations</dt><dd>${row.availableQuantity === null ? "Needs review" : escapeHtml(formatShoppingQuantity(row.availableQuantity, row.unit))}</dd></div>
      </dl>
    </li>`;
  }

  function getCookTonightDraftFormValues() {
    const recipeId = state.currentCookTonightWorkflow?.recipeId || "";
    const values = getSmartPortionFormValues(recipeId);
    const suggestion = buildSmartPortionSuggestion(recipeId, buildSmartPortionOverridesFromForm(recipeId, { date: state.currentCookTonightWorkflow?.target?.date, mealType: state.currentCookTonightWorkflow?.target?.mealSlotId }));
    return {
      peopleEating: Number(values.peopleEating),
      requestedMealServings: Number(suggestion?.currentMealServings?.selected ?? values.currentMealServings ?? values.peopleEating),
      plannedLeftoverServings: Number(suggestion?.leftoverPlan?.plannedLeftoverServings ?? 0),
      leftoverPreference: normalizePortionLeftoverPreference(values.leftoverPreference),
      firstAdditionalMealServings: Number(values.firstAdditionalMealServings),
      secondAdditionalMealServings: Number(values.secondAdditionalMealServings),
      portionSuggestion: suggestion
    };
  }

  function validateCookTonightDraftInputs(values) {
    const errors = [];
    ["peopleEating", "requestedMealServings"].forEach((field) => {
      const value = Number(values[field]);
      if (!Number.isInteger(value) || value <= 0) errors.push(field === "peopleEating" ? "Enter how many people are eating." : "Enter servings for tonight.");
    });
    const leftovers = Number(values.plannedLeftoverServings);
    if (!Number.isInteger(leftovers) || leftovers < 0) errors.push("Enter a valid leftover serving count.");
    if (!values.leftoverPreference) errors.push("Choose a leftover preference.");
    if (!values.portionSuggestion || values.portionSuggestion.recommendationStatus !== "recommended") errors.push(values.portionSuggestion?.warnings?.[0] || "Review serving details before continuing.");
    return errors;
  }

  function reviewCookTonightDraft(workflowId) {
    const current = getCurrentCookTonightWorkflow(workflowId);
    if (!current) return showToast("Tonight's plan needs review.", "warning");
    const values = getCookTonightDraftFormValues();
    const errors = validateCookTonightDraftInputs(values);
    if (errors.length) {
      const target = $("#cookTonightDraftError");
      if (target) target.textContent = errors[0];
      $("#smartPortionPeople")?.focus();
      return;
    }
    const recalculated = createCookTonightDraft(current.recipeId, { ...values, date: current.target.date, mealType: current.target.mealSlotId, workflowId: current.workflowId });
    if (!recalculated) return showCookTonightNeedsReview("Chef Nova recalculated the recipe and it no longer meets current hard requirements.");
    if (recalculated.pantryAllocationPreview.some((row) => row.availableQuantity === null || row.plannedQuantity > row.availableQuantity)) return showCookTonightNeedsReview("A selected priority food no longer has enough eligible Pantry quantity. Change servings or choose another recipe.");
    if (recalculated.portionPreview?.excessPreparedFoodAssessment?.requiresDecision) {
      state.currentCookTonightWorkflow = { ...recalculated, status: COOK_TONIGHT_WORKFLOW_STATUSES.DRAFT };
      renderCookTonightDraftStep(recalculated.workflowId);
      showToast("Choose a plan for extra servings before reviewing tonight's plan.", "warning");
      return;
    }
    state.currentCookTonightWorkflow = { ...recalculated, status: COOK_TONIGHT_WORKFLOW_STATUSES.AWAITING_CONFIRMATION };
    renderCookTonightReview(recalculated.workflowId);
  }

  function renderCookTonightReview(workflowId) {
    const draft = getCurrentCookTonightWorkflow(workflowId);
    const recipe = draft ? findRecipeById(draft.recipeId) : null;
    if (!draft || !recipe) return showToast("Tonight's plan needs review.", "warning");
    renderMealPlanGenerationModal(`<section class="cook-tonight-workflow" aria-labelledby="cookTonightReviewTitle">
      <div class="meal-generation-heading">
        <span class="eyebrow">REVIEW TONIGHT'S FOOD-RESCUE PLAN</span>
        <h2 id="cookTonightReviewTitle">${escapeHtml(recipe.name)}</h2>
        <p>This review does not reserve food or change your Pantry yet.</p>
      </div>
      ${renderFoodSafetyNotice()}
      <dl class="cook-tonight-summary-list">
        <div><dt>Date</dt><dd>${escapeHtml(formatEmergencyDate(draft.target.date))}</dd></div>
        <div><dt>Meal</dt><dd>${escapeHtml(draft.target.mealSlotId)}</dd></div>
        <div><dt>People eating</dt><dd>${escapeHtml(String(draft.peopleEating.count))}</dd></div>
        <div><dt>Servings for tonight</dt><dd>${escapeHtml(String(draft.servingPlan.requestedMealServings))}</dd></div>
        <div><dt>Planned leftovers</dt><dd>${escapeHtml(formatServingAmount(draft.servingPlan.plannedLeftoverServings))}</dd></div>
        <div><dt>Total recipe yield</dt><dd>${escapeHtml(formatServingAmount(draft.servingPlan.effectiveRecipeYield))}</dd></div>
        <div><dt>Cooking time</dt><dd>${escapeHtml(String(getRecipeTotalMinutes(recipe) || "Needs review"))}${getRecipeTotalMinutes(recipe) ? " minutes" : ""}</dd></div>
      </dl>
      <section class="cook-tonight-card"><h3>Would reserve from your Pantry</h3><ul>${draft.pantryAllocationPreview.map((row) => `<li>${escapeHtml(formatShoppingQuantity(row.plannedQuantity, row.unit))} ${escapeHtml(row.displayName)}${row.lotLabel ? ` - ${escapeHtml(row.lotLabel)}` : ""}</li>`).join("") || "<li>No tracked Pantry reservations.</li>"}</ul></section>
      ${renderCookTonightPortionPreview(draft.portionPreview, { compact: true })}
      <section class="cook-tonight-card"><h3>Still needed</h3><ul>${draft.missingPurchaseGroups.length ? draft.missingPurchaseGroups.map((group) => `<li>${escapeHtml(group.suggestedPurchaseText || formatShoppingQuantity(group.missingQuantity, group.missingUnit))} ${escapeHtml(group.displayName)}</li>`).join("") : "<li>Nothing else from the Shopping List.</li>"}</ul></section>
      <section class="cook-tonight-card"><h3>Leftover guidance</h3><p>${escapeHtml(draft.leftoverPlan.guidance)}</p></section>
      <div class="meal-generation-actions">
        <button class="button primary" type="button" data-cook-tonight-confirm="${escapeHtml(workflowId)}" aria-label="Confirm tonight's plan for ${escapeHtml(recipe.name)}">Confirm Tonight's Plan</button>
        <button class="button secondary" type="button" data-cook-tonight-change="${escapeHtml(workflowId)}" aria-label="Change servings for tonight's ${escapeHtml(recipe.name)}">Change Servings</button>
        <button class="button secondary" type="button" data-food-rescue-other="${escapeHtml(recipe.id)}">Choose Another Recipe</button>
        <button class="button secondary" type="button" data-cancel-generated-plan>Cancel</button>
      </div>
    </section>`);
  }

  function showCookTonightNeedsReview(message) {
    renderMealPlanGenerationModal(`<section class="cook-tonight-workflow" aria-labelledby="cookTonightNeedsReviewTitle">
      <div class="meal-generation-heading"><span class="eyebrow">TONIGHT'S PLAN NEEDS REVIEW</span><h2 id="cookTonightNeedsReviewTitle">Review Tonight's Plan</h2><p>${escapeHtml(message)}</p></div>
      <p>The previous Pantry quantities and meal status remain unchanged.</p>
      <div class="meal-generation-actions"><button class="button secondary" type="button" data-cancel-generated-plan>Close</button></div>
    </section>`);
  }

  function confirmCookTonightPlan(workflowId) {
    const draft = getCurrentCookTonightWorkflow(workflowId);
    if (!draft) return showToast("Tonight's plan needs review.", "warning");
    if (draft.portionPreview?.excessPreparedFoodAssessment?.requiresDecision) return showCookTonightNeedsReview("Choose how to handle extra prepared servings before confirming tonight's plan.");
    const result = commitCookTonightPlanAtomically(draft);
    if (!result.ok) return showCookTonightNeedsReview(result.message || "Chef Nova could not complete the reservation, calendar, or Shopping List update.");
    state.currentCookTonightWorkflow = { ...result.workflow, status: COOK_TONIGHT_WORKFLOW_STATUSES.PLANNED };
    renderCommittedCookTonightPlan(state.currentCookTonightWorkflow);
    announcePolite(`Tonight's plan confirmed. Pantry quantities were reserved and not deducted.`, { key: `cook-tonight-confirmed-${draft.workflowId}` });
  }

  function commitCookTonightPlanAtomically(draft) {
    const latest = createCookTonightDraft(draft.recipeId, {
      peopleEating: draft.peopleEating.count,
      requestedMealServings: draft.servingPlan.requestedMealServings,
      plannedLeftoverServings: draft.servingPlan.plannedLeftoverServings,
      plannedFrozenServings: draft.servingPlan.plannedFrozenServings,
      plannedSharedServings: draft.servingPlan.plannedSharedServings,
      unallocatedServingsAccepted: draft.servingPlan.unallocatedServingsAccepted,
      unallocatedAcknowledgement: draft.servingPlan.servingAllocation?.unallocatedAcknowledgement,
      leftoverPreference: draft.servingPlan.leftoverPreference,
      portionSuggestion: draft.servingPlan.portionSuggestion,
      date: draft.target.date,
      mealType: draft.target.mealSlotId,
      workflowId: draft.workflowId
    });
    if (!latest) return { ok: false, message: "This recipe no longer meets current hard requirements." };
    if (latest.userScope !== draft.userScope) return { ok: false, message: "Your account changed while this plan was open. Reopen the workflow." };
    if (latest.portionPreview?.excessPreparedFoodAssessment?.requiresDecision) return { ok: false, message: "Choose how to handle extra prepared servings before confirming tonight's plan." };
    const reservationResult = createCookTonightReservations(latest);
    if (!reservationResult.ok) return reservationResult;
    const recipe = findRecipeById(latest.recipeId);
    const mealEntry = createCookTonightMealEntry(recipe, latest, reservationResult.reservations);
    try {
      state.mealPlans.calendar = state.mealPlans.calendar || {};
      const dayPlan = normalizeMealDay(state.mealPlans.calendar[latest.target.date], CALENDAR_MEALS);
      dayPlan[latest.target.mealSlotId] = mealEntry;
      state.mealPlans.calendar[latest.target.date] = normalizeMealDay(dayPlan, CALENDAR_MEALS);
      syncWeeklyFromCalendarDate(latest.target.date);
      saveMealPlan();
      ensureBudgetPurchaseGroupsInShoppingList(derivePriceConfidence({ purchaseGroups: calculateCurrentMealPlanCosts()?.purchaseGroups || [], weeklyCostSummary: calculateCurrentMealPlanCosts()?.weeklySummary || {} }));
      displayMealPlanner();
      displayShoppingList();
      displayWeeklyNutrition();
      return { ok: true, workflow: { ...latest, status: COOK_TONIGHT_WORKFLOW_STATUSES.PLANNED, pantryAllocationPreview: reservationResult.allocations, reservationIds: reservationResult.reservations.map((item) => item.reservationId) } };
    } catch (error) {
      releaseCookTonightReservations(reservationResult.reservations, latest, "calendar-commit-failed");
      return { ok: false, message: "Chef Nova could not save the calendar meal. Pantry reservations were not kept." };
    }
  }

  function createCookTonightReservations(draft) {
    const now = getCurrentIsoString();
    const nextPantry = state.pantry.map((item) => normalizePantryItem(item));
    const events = [];
    const reservations = [];
    const allocations = [];
    for (const row of draft.pantryAllocationPreview) {
      const item = nextPantry.find((candidate) => candidate.id === row.pantryItemId);
      if (!item) return { ok: false, message: `${row.displayName} is no longer in your Pantry.` };
      if (item.quantityDetails?.status === PANTRY_QUANTITY_STATUSES.UNKNOWN) return { ok: false, message: `${row.displayName} needs a current Pantry amount before reserving.` };
      const available = Math.max(0, Number(item.quantityDetails.currentQuantity || 0) - deriveReservedQuantity(item));
      if (available + 1e-6 < Number(row.plannedQuantity)) return { ok: false, message: `${row.displayName} no longer has enough unreserved Pantry quantity.` };
      const reservationId = `reservation::${draft.mealId}::${item.id}::${row.allocationId}`.replace(/[^a-z0-9:-]/gi, "-").toLowerCase();
      const alreadyActive = (item.reservations || []).some((record) => record.reservationId === reservationId && record.status === PANTRY_RESERVATION_STATUSES.ACTIVE);
      if (alreadyActive) {
        reservations.push(item.reservations.find((record) => record.reservationId === reservationId));
        allocations.push({ ...row, reservationId });
        continue;
      }
      const reservation = {
        reservationId,
        pantryItemId: item.id,
        planId: draft.workflowId,
        mealId: draft.mealId,
        quantity: Number(row.plannedQuantity),
        unit: row.unit || item.quantityDetails.unit || item.unit || "each",
        status: PANTRY_RESERVATION_STATUSES.ACTIVE,
        idempotencyKey: `reserve::${draft.mealId}::${item.id}::${row.allocationId}::v1`,
        createdAt: now,
        updatedAt: now
      };
      item.reservations = [...(item.reservations || []), reservation];
      item.updatedAt = now;
      item.revision = Number(item.revision || 0) + 1;
      reservations.push(reservation);
      allocations.push({ ...row, reservationId });
      events.push(buildFoodEventForPantryCommand({
        commandType: FOOD_EVENT_TYPES.RESERVED_FOR_RECIPE,
        pantryItemId: item.id,
        beforeItem: state.pantry.find((candidate) => candidate.id === item.id),
        afterItem: item,
        source: { sourceType: FOOD_EVENT_SOURCE_TYPES.RESERVATION, planId: draft.workflowId, mealId: draft.mealId, reservationId, recipeId: draft.recipeId },
        idempotencyKey: reservation.idempotencyKey,
        payload: {
          occurredAt: now,
          affectsOnHandQuantity: false,
          affectsReservedQuantity: true,
          direction: FOOD_EVENT_QUANTITY_DIRECTIONS.INCREASE,
          amount: reservation.quantity,
          unit: reservation.unit,
          note: "Reserved for tonight's confirmed Food-Rescue plan. On-hand Pantry quantity was not deducted."
        }
      }));
    }
    const result = commitPantrySnapshotAndFoodEvents(nextPantry, events);
    if (!result.ok) return { ok: false, message: "Chef Nova could not reserve Pantry quantities." };
    return { ok: true, reservations, allocations };
  }

  function releaseCookTonightReservations(reservations = [], draft = {}, reason = "cancelled") {
    if (!reservations.length) return { ok: true, released: [] };
    const ids = new Set(reservations.map((reservation) => reservation.reservationId));
    const now = getCurrentIsoString();
    const nextPantry = state.pantry.map((item) => normalizePantryItem(item));
    const events = [];
    nextPantry.forEach((item) => {
      item.reservations = (item.reservations || []).map((reservation) => {
        if (!ids.has(reservation.reservationId) || reservation.status !== PANTRY_RESERVATION_STATUSES.ACTIVE) return reservation;
        const nextReservation = { ...reservation, status: reason === "consumed" ? PANTRY_RESERVATION_STATUSES.CONSUMED : PANTRY_RESERVATION_STATUSES.CANCELLED, updatedAt: now };
        events.push(buildFoodEventForPantryCommand({
          commandType: reason === "consumed" ? FOOD_EVENT_TYPES.RESERVATION_CONSUMED : FOOD_EVENT_TYPES.RESERVATION_CANCELLED,
          pantryItemId: item.id,
          beforeItem: item,
          afterItem: { ...item, reservations: (item.reservations || []).map((record) => record.reservationId === reservation.reservationId ? nextReservation : record) },
          source: { sourceType: FOOD_EVENT_SOURCE_TYPES.RESERVATION, planId: draft.workflowId || reservation.planId, mealId: draft.mealId || reservation.mealId, reservationId: reservation.reservationId, recipeId: draft.recipeId || "" },
          idempotencyKey: `${reason === "consumed" ? "consume" : "cancel"}::${reservation.reservationId}::v1`,
          payload: { occurredAt: now, affectsOnHandQuantity: false, affectsReservedQuantity: true, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.DECREASE, amount: reservation.quantity, unit: reservation.unit }
        }));
        return nextReservation;
      });
    });
    return commitPantrySnapshotAndFoodEvents(nextPantry, events);
  }

  function getActiveReservationHoldStatuses() {
    return [
      PANTRY_RESERVATION_STATUSES.ACTIVE,
      PANTRY_RESERVATION_STATUSES.NEEDS_OUTCOME_REVIEW,
      PANTRY_RESERVATION_STATUSES.NEEDS_QUANTITY_REVIEW,
      PANTRY_RESERVATION_STATUSES.NEEDS_SAFETY_REVIEW,
      PANTRY_RESERVATION_STATUSES.PARTIALLY_FULFILLED
    ];
  }

  function getCalendarMealId(date, mealType, existingEntry = null) {
    return existingEntry?.mealId || `calendar-meal::${date}::${normalizeIngredient(mealType)}`;
  }

  function getCalendarReservationSourceRevisions(pantryItems = state.pantry, plan = state.mealPlans) {
    return {
      userScopeId: getActiveUserScopeId(),
      calendarRevision: createStableSavedPlanId(plan, null, null),
      mealRevision: JSON.stringify(plan?.calendar || {}).length,
      planRevision: plan?.savedPlanMetadata?.revision || plan?.updatedAt || "",
      recipeRevision: state.recipes.length,
      pantryRevision: buildPantrySignature(pantryItems),
      reservationRevision: pantryItems.map((item) => `${item.id}:${(item.reservations || []).map((reservation) => `${reservation.reservationId}:${reservation.status}:${reservation.quantity}:${reservation.unit}`).join("|")}`).join("::"),
      dateIntelligenceRevision: FOOD_DATE_INTELLIGENCE_VERSION,
      foodSafetyGuardrailRevision: FOOD_SAFETY_POLICY_SCHEMA_VERSION,
      allergyProfileRevision: JSON.stringify(getCurrentUser()?.allergies || []),
      dietaryProfileRevision: getCurrentUser()?.dietaryPreference || "",
      shoppingListRevision: JSON.stringify(getShoppingListItems()).length,
      priceRevision: state.priceEstimateCatalogue?.reviewedAt || "",
      leftoverRevision: JSON.stringify(plan?.leftoverRelationships || []).length,
      priorityEngineRevision: USE_FIRST_PRIORITY_ENGINE_VERSION,
      referenceLocalDate: getCurrentDateString(),
      timezone: getCurrentApplicationTimeZone(),
      reservationPolicyVersion: PANTRY_RESERVATION_POLICY_VERSION
    };
  }

  function createMealWindowForReservation(date, mealType) {
    const localDate = isIsoDate(date) ? date : getCurrentDateString();
    const defaultTimes = {
      Breakfast: ["08:00", "09:00"],
      Lunch: ["12:00", "13:00"],
      Dinner: ["18:00", "19:30"],
      Snacks: ["15:00", "15:30"]
    };
    const [start, end] = defaultTimes[mealType] || ["23:00", "23:59"];
    return {
      localDate,
      scheduledStartAt: `${localDate}T${start}:00`,
      scheduledEndAt: `${localDate}T${end}:00`,
      precision: "date-only",
      mealTimePrecision: "date-only",
      timezone: getCurrentApplicationTimeZone()
    };
  }

  function createReservationWindowForMeal(date) {
    const localDate = isIsoDate(date) ? date : getCurrentDateString();
    return {
      reservedAt: getCurrentIsoString(),
      reservedUntil: `${localDate}T23:59:00`,
      expirationBehavior: PANTRY_RESERVATION_STATUSES.NEEDS_OUTCOME_REVIEW
    };
  }

  function createReservationEligibilitySnapshot(item, allocation = {}, sourceRevisions = {}) {
    const dateIntel = deriveFoodDateIntelligence({ pantryItem: item });
    const primary = dateIntel.primaryDateRecord || {};
    return {
      mealDateEligible: true,
      foodForm: item.form || item.identity?.form || PANTRY_ITEM_FORMS.UNKNOWN,
      storageLocation: item.storage?.location || PANTRY_STORAGE_LOCATIONS.UNKNOWN,
      openedStatus: item.storage?.packageState || PANTRY_PACKAGE_STATES.UNKNOWN,
      frozenOrThawedStatus: item.preservation?.state || PANTRY_PRESERVATION_STATES.UNKNOWN,
      dateType: primary.dateType || item.freshnessDateType || "unknown",
      recordedDate: primary.dateValue || item.freshnessDate || item.expirationDate || null,
      priorityDate: dateIntel.priorityDate || primary.dateValue || null,
      priorityConfidence: dateIntel.priorityConfidence || "unknown",
      safetyDecisionId: allocation.safetyDecisionId || `safety-decision::${item.id}::${sourceRevisions.foodSafetyGuardrailRevision}`,
      safetyPolicyVersion: FOOD_SAFETY_POLICY_SCHEMA_VERSION,
      allergyProfileRevision: sourceRevisions.allergyProfileRevision || "",
      dietaryProfileRevision: sourceRevisions.dietaryProfileRevision || "",
      pantryItemRevision: Number(item.revision || 0),
      dateInformationRevision: FOOD_DATE_INTELLIGENCE_VERSION,
      reservationPolicyVersion: PANTRY_RESERVATION_POLICY_VERSION
    };
  }

  function getPantryReservationAvailability({ pantryItemId, excludingMealId = "", asOfMealDate = "", userScopeId = getActiveUserScopeId(), pantryItems = state.pantry } = {}) {
    const item = pantryItems.map(normalizePantryItem).find((candidate) => candidate.id === pantryItemId);
    if (!item) return { ok: false, status: "missing-pantry-item", pantryItemId, physicalQuantity: null, activeReservedQuantity: 0, freelyAvailableQuantity: null, conflicts: [] };
    const quantity = item.quantityDetails || {};
    const holdStatuses = getActiveReservationHoldStatuses();
    const activeReservations = (item.reservations || []).filter((reservation) => holdStatuses.includes(reservation.status) && reservation.mealId !== excludingMealId && (!reservation.userScopeId || reservation.userScopeId === userScopeId));
    const exclusive = activeReservations.some((reservation) => reservation.scope === PANTRY_RESERVATION_SCOPES.ENTIRE_ITEM || reservation.exclusive === true);
    const physicalQuantity = quantity.status === PANTRY_QUANTITY_STATUSES.UNKNOWN ? null : Number(quantity.currentQuantity);
    const activeReservedQuantity = activeReservations.filter((reservation) => reservation.unit === quantity.unit).reduce((sum, reservation) => sum + (Number(reservation.quantity) || 0), 0);
    const freelyAvailableQuantity = exclusive ? 0 : physicalQuantity === null || !Number.isFinite(physicalQuantity) ? null : Math.max(0, roundFoodRescueNumber(physicalQuantity - activeReservedQuantity));
    const conflicts = physicalQuantity !== null && activeReservedQuantity > physicalQuantity + 1e-6 ? [{
      conflictType: "reservation-exceeds-physical-quantity",
      message: `The reservations exceed the recorded Pantry amount by ${formatShoppingQuantity(activeReservedQuantity - physicalQuantity, quantity.unit)}.`,
      affectedMealIds: activeReservations.map((reservation) => reservation.mealId).filter(Boolean).sort()
    }] : [];
    return { ok: true, pantryItemId, userScopeId, asOfMealDate, physicalQuantity, unit: quantity.unit || item.unit || "", activeReservedQuantity, freelyAvailableQuantity, exclusive, activeReservations, conflicts };
  }

  function reservePantryForMeal({ meal, pantryAllocations = [], currentRevisions = {}, userScopeId = getActiveUserScopeId(), pantryItems = state.pantry, origin = PANTRY_RESERVATION_ORIGINS.CALENDAR_ADD } = {}) {
    if (!meal?.mealId) return { ok: false, message: "Meal reservation needs review." };
    const now = getCurrentIsoString();
    const nextPantry = pantryItems.map((item) => normalizePantryItem(item));
    const reservations = [];
    const reservationGroups = [];
    const events = [];
    const rowsByDemand = new Map();
    pantryAllocations.forEach((row) => {
      const key = row.ingredientDemandId || `${meal.mealId}::${row.ingredientId || row.displayName || "ingredient"}`;
      rowsByDemand.set(key, [...(rowsByDemand.get(key) || []), row]);
    });
    for (const [ingredientDemandId, rows] of rowsByDemand.entries()) {
      const requiredQuantity = rows.reduce((sum, row) => sum + (Number(row.reservedQuantity ?? row.quantity ?? row.plannedQuantity) || 0), 0);
      const unit = rows[0]?.unit || rows[0]?.requiredUnit || "";
      const groupId = `reservation-group::${meal.mealId}::${rows[0]?.ingredientId || normalizeIngredient(rows[0]?.displayName || ingredientDemandId)}`.replace(/[^a-z0-9:-]/gi, "-").toLowerCase();
      const groupReservationIds = [];
      let reservedQuantity = 0;
      for (const row of rows) {
        const item = nextPantry.find((candidate) => candidate.id === row.pantryItemId);
        if (!item) return { ok: false, message: `${row.displayName || "Pantry item"} is no longer in your Pantry.` };
        const quantity = Number(row.reservedQuantity ?? row.quantity ?? row.plannedQuantity);
        if (!Number.isFinite(quantity) || quantity <= 0) return { ok: false, message: `${row.displayName || item.displayName} needs a valid reservation quantity.` };
        const availability = getPantryReservationAvailability({ pantryItemId: item.id, excludingMealId: meal.mealId, asOfMealDate: meal.date, userScopeId, pantryItems: nextPantry });
        const eligibility = validateFoodUseActionAllowed({
          source: item,
          actionId: FOOD_USE_ACTION_IDS.RESERVE_FOR_MEAL,
          meal,
          recipe: meal.recipeId ? findRecipeById(meal.recipeId) : null,
          targetMealDate: meal.date,
          reservationAvailability: availability,
          requiredQuantity: quantity,
          requestId: `reserve:${meal.mealId}:${item.id}:${ingredientDemandId}`
        });
        if (!eligibility.ok) return { ok: false, status: "reservation-eligibility-blocked", message: eligibility.message || "THIS ACTION IS NOT AVAILABLE\n\nNo Pantry quantity, reservation, or meal plan was changed.", eligibilityDecision: eligibility.decision };
        if (availability.freelyAvailableQuantity === null) return { ok: false, message: `${row.displayName || item.displayName} amount needs confirmation before reserving.` };
        if (availability.freelyAvailableQuantity + 1e-6 < quantity) return { ok: false, message: `${row.displayName || item.displayName} no longer has enough unreserved Pantry quantity.` };
        const reservationId = `reservation::${meal.mealId}::${item.id}::${ingredientDemandId}`.replace(/[^a-z0-9:-]/gi, "-").toLowerCase();
        const existing = (item.reservations || []).find((record) => record.reservationId === reservationId);
        if (existing && getActiveReservationHoldStatuses().includes(existing.status)) {
          reservations.push(existing);
          groupReservationIds.push(existing.reservationId);
          reservedQuantity += Number(existing.quantity) || 0;
          continue;
        }
        const sourceRevisions = { ...getCalendarReservationSourceRevisions(nextPantry, state.mealPlans), ...currentRevisions };
        const reservation = {
          pantryReservationSchemaVersion: PANTRY_RESERVATION_SCHEMA_VERSION,
          reservationId,
          reservationGroupId: groupId,
          userScopeId,
          origin,
          status: PANTRY_RESERVATION_STATUSES.ACTIVE,
          scope: PANTRY_RESERVATION_SCOPES.QUANTITY,
          pantryItemId: item.id,
          mealId: meal.mealId,
          planId: meal.planId || createStableSavedPlanId(state.mealPlans, null, null),
          recipeId: meal.recipeId || null,
          ingredientDemandId,
          quantity,
          unit: row.unit || item.quantityDetails?.unit || item.unit || "each",
	          quantityDetails: { point: quantity, unit: row.unit || item.quantityDetails?.unit || item.unit || "each", dimension: resolveQuantityDimension(row.unit || item.quantityDetails?.unit || item.unit || "each").dimension, confidence: QUANTITY_CONFIDENCE_LEVELS.MEASURED },
	          mealWindow: createMealWindowForReservation(meal.date, meal.mealType),
	          reservationWindow: createReservationWindowForMeal(meal.date),
	          eligibilitySnapshot: createReservationEligibilitySnapshot(item, row, sourceRevisions),
	          recommendationEligibility: eligibility.decision,
	          reservationEligibilityStatus: eligibility.decision.overallStatus === RECOMMENDATION_ELIGIBILITY_STATUSES.REVIEW_REQUIRED ? RESERVATION_ELIGIBILITY_STATUSES.REVIEW_REQUIRED : RESERVATION_ELIGIBILITY_STATUSES.ELIGIBLE,
	          reconciliation: { fulfilledQuantity: 0, releasedQuantity: 0, unresolvedQuantity: quantity, unit: row.unit || item.quantityDetails?.unit || item.unit || "each" },
          sourceWorkflow: PLANNING_MODES.COOK_BEFORE_IT_SPOILS,
          sourceRevisions,
          idempotencyKey: `reserve-pantry:${meal.mealId}:${item.id}:${ingredientDemandId}:v${PANTRY_RESERVATION_POLICY_VERSION}`,
          createdAt: now,
          updatedAt: now
        };
        item.reservations = [...(item.reservations || []), reservation];
        item.updatedAt = now;
        item.revision = Number(item.revision || 0) + 1;
        reservations.push(reservation);
        groupReservationIds.push(reservation.reservationId);
        reservedQuantity += quantity;
        events.push(buildFoodEventForPantryCommand({
          commandType: FOOD_EVENT_TYPES.RESERVED_FOR_RECIPE,
          pantryItemId: item.id,
          beforeItem: pantryItems.find((candidate) => candidate.id === item.id) || item,
          afterItem: item,
          source: { sourceType: FOOD_EVENT_SOURCE_TYPES.RESERVATION, planId: reservation.planId, mealId: meal.mealId, reservationId, recipeId: meal.recipeId },
          idempotencyKey: reservation.idempotencyKey,
          payload: { occurredAt: now, affectsOnHandQuantity: false, affectsReservedQuantity: true, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.INCREASE, amount: quantity, unit: reservation.unit, note: "Reserved for a confirmed Calendar meal. Physical Pantry quantity was not deducted." }
        }));
      }
      reservationGroups.push({
        reservationGroupSchemaVersion: PANTRY_RESERVATION_GROUP_SCHEMA_VERSION,
        reservationGroupId: groupId,
        userScopeId,
        mealId: meal.mealId,
        ingredientDemandId,
        canonicalIngredientId: rows[0]?.ingredientId || null,
        requiredForm: rows[0]?.requiredForm || rows[0]?.form || "",
        requiredQuantity,
        reservedQuantity,
        missingQuantity: Math.max(0, roundFoodRescueNumber(requiredQuantity - reservedQuantity)),
        unit,
        reservationIds: groupReservationIds,
        status: Math.abs(requiredQuantity - reservedQuantity) < 1e-6 ? PANTRY_RESERVATION_GROUP_STATUSES.FULLY_RESERVED : reservedQuantity > 0 ? PANTRY_RESERVATION_GROUP_STATUSES.PARTIALLY_RESERVED : PANTRY_RESERVATION_GROUP_STATUSES.PURCHASE_REQUIRED,
        sourceRevisions: getCalendarReservationSourceRevisions(nextPantry, state.mealPlans)
      });
    }
    return { ok: true, nextPantry, reservations, reservationGroups, events };
  }

  function createReservationReleaseRecord({ reservation, nextReservation, releaseReason, cancellationId, releasedAt, sourceRevisions = {} } = {}) {
    const quantityRepresentation = reservation.scope === PANTRY_RESERVATION_SCOPES.ENTIRE_ITEM ? PANTRY_QUANTITY_REPRESENTATIONS.UNKNOWN : reservation.quantityDetails?.representation || (Number.isFinite(Number(reservation.quantity)) ? PANTRY_QUANTITY_REPRESENTATIONS.EXACT_NUMERIC : PANTRY_QUANTITY_REPRESENTATIONS.UNKNOWN);
    return {
      reservationReleaseVersion: RESERVATION_RELEASE_VERSION,
      releaseId: `reservation-release:${reservation.reservationId}:${cancellationId || releaseReason}`.replace(/[^a-z0-9:-]/gi, "-").toLowerCase(),
      reservationId: reservation.reservationId,
      userScopeId: reservation.userScopeId || getActiveUserScopeId(),
      mealId: reservation.mealId || "",
      pantryItemId: reservation.pantryItemId || "",
      previousReservationStatus: reservation.status,
      currentReservationStatus: nextReservation.status,
      releasedQuantity: {
        representation: reservation.scope === PANTRY_RESERVATION_SCOPES.ENTIRE_ITEM ? "whole-recorded-item" : quantityRepresentation,
        point: Number.isFinite(Number(reservation.quantity)) ? Number(reservation.quantity) : null,
        unit: reservation.unit || reservation.quantityDetails?.unit || "",
        confidence: reservation.quantityDetails?.confidence || QUANTITY_CONFIDENCE_LEVELS.UNKNOWN
      },
      releaseReason,
      releasedAt,
      cancellationId: cancellationId || null,
      sourceRevisions
    };
  }

  function releaseMealReservations({ mealId, releaseReason = RESERVATION_RELEASE_REASONS.USER_RELEASED, cancellationId = "", currentRevisions = {}, userScopeId = getActiveUserScopeId(), pantryItems = state.pantry, commit = true } = {}) {
    if (!mealId) return { ok: true, nextPantry: pantryItems, reservations: [], releaseRecords: [], events: [] };
    const now = getCurrentIsoString();
    const nextPantry = pantryItems.map((item) => normalizePantryItem(item));
    const events = [];
    const released = [];
    const releaseRecords = [];
    nextPantry.forEach((item) => {
      item.reservations = (item.reservations || []).map((reservation) => {
        if (reservation.mealId !== mealId || !getActiveReservationHoldStatuses().includes(reservation.status) || (reservation.userScopeId && reservation.userScopeId !== userScopeId)) return reservation;
        const status = releaseReason === RESERVATION_RELEASE_REASONS.MEAL_REPLACED || releaseReason === "superseded" ? PANTRY_RESERVATION_STATUSES.SUPERSEDED : PANTRY_RESERVATION_STATUSES.RELEASED;
        const nextReservation = {
          ...reservation,
          status,
          reconciliation: { ...(reservation.reconciliation || {}), releasedQuantity: Number(reservation.quantity) || 0, unresolvedQuantity: 0, unit: reservation.unit },
          releaseReason,
          releaseRecords: [...(reservation.releaseRecords || []), createReservationReleaseRecord({ reservation, nextReservation: { ...reservation, status }, releaseReason, cancellationId, releasedAt: now, sourceRevisions: { ...(reservation.sourceRevisions || {}), ...currentRevisions } })],
          cancellationId: cancellationId || reservation.cancellationId || null,
          sourceRevisions: { ...(reservation.sourceRevisions || {}), ...currentRevisions },
          updatedAt: now
        };
        releaseRecords.push(nextReservation.releaseRecords[nextReservation.releaseRecords.length - 1]);
        released.push(nextReservation);
        events.push(buildFoodEventForPantryCommand({
          commandType: FOOD_EVENT_TYPES.RESERVATION_CANCELLED,
          pantryItemId: item.id,
          beforeItem: item,
          afterItem: { ...item, reservations: (item.reservations || []).map((record) => record.reservationId === reservation.reservationId ? nextReservation : record) },
          source: { sourceType: FOOD_EVENT_SOURCE_TYPES.RESERVATION, planId: reservation.planId, mealId, reservationId: reservation.reservationId, recipeId: reservation.recipeId },
          idempotencyKey: `reservation-release:${reservation.reservationId}:${cancellationId || releaseReason}:v${RESERVATION_RELEASE_VERSION}`,
          payload: { occurredAt: now, affectsOnHandQuantity: false, affectsReservedQuantity: true, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.DECREASE, amount: reservation.quantity, unit: reservation.unit, note: "Calendar reservation released. Physical Pantry quantity was not changed. The amount is available for planning again." }
        }));
        return nextReservation;
      });
      if (released.some((reservation) => reservation.pantryItemId === item.id)) {
        item.updatedAt = now;
        item.revision = Number(item.revision || 0) + 1;
      }
    });
    if (!commit) return { ok: true, nextPantry, reservations: released, releaseRecords, events };
    const result = commitPantrySnapshotAndFoodEvents(nextPantry, events);
    return result.ok ? { ok: true, nextPantry: state.pantry, reservations: released, releaseRecords, events } : { ok: false, message: "Chef Nova could not release the meal reservations." };
  }

  function findCalendarMealById(mealId) {
    if (!mealId) return null;
    const calendar = state.mealPlans.calendar || {};
    for (const [date, dayPlan] of Object.entries(calendar)) {
      const normalizedDay = normalizeMealDay(dayPlan, CALENDAR_MEALS, date);
      for (const slot of getMealSlotsForDay(normalizedDay, CALENDAR_MEALS)) {
        const entry = normalizeMealPlanEntry(slot.entry);
        if (entry?.mealId === mealId) return { date, mealType: getMealSlotLabel(slot), slotId: slot.id, entry };
      }
    }
    return null;
  }

  function getCalendarMealForCancellation(date, mealType) {
    const plan = getCalendarDayPlan(date);
    const slot = findMealSlot(plan, mealType, CALENDAR_MEALS);
    const entry = normalizeMealPlanEntry(slot?.entry);
    return entry ? { date, mealType: getMealSlotLabel(slot), slotId: slot.id, entry, dayPlan: plan } : null;
  }

  function getMealStatusForCancellation(entry = {}) {
    const status = entry.status || (entry.pantryReservationIds?.length ? MEAL_STATUSES.RESERVED : MEAL_STATUSES.SCHEDULED);
    if ([COOK_TONIGHT_WORKFLOW_STATUSES.COOKING, MEAL_STATUSES.STARTED].includes(status)) return MEAL_STATUSES.STARTED;
    if ([COOK_TONIGHT_WORKFLOW_STATUSES.COMPLETED, MEAL_STATUSES.COMPLETED].includes(status)) return MEAL_STATUSES.COMPLETED;
    if (status === MEAL_STATUSES.CANCELLED || status === "cancelled") return MEAL_STATUSES.CANCELLED;
    if (status === MEAL_STATUSES.NEEDS_OUTCOME_REVIEW || status === PANTRY_RESERVATION_STATUSES.NEEDS_OUTCOME_REVIEW) return MEAL_STATUSES.NEEDS_OUTCOME_REVIEW;
    return Object.values(MEAL_STATUSES).includes(status) ? status : MEAL_STATUSES.SCHEDULED;
  }

  function getReservationRowsForMeal(mealId, pantryItems = state.pantry, userScopeId = getActiveUserScopeId()) {
    return pantryItems.map(normalizePantryItem).flatMap((item) => (item.reservations || [])
      .filter((reservation) => reservation.mealId === mealId && (!reservation.userScopeId || reservation.userScopeId === userScopeId))
      .map((reservation) => ({ item, reservation })));
  }

  function getActiveReservationRowsForMeal(mealId, pantryItems = state.pantry, userScopeId = getActiveUserScopeId()) {
    return getReservationRowsForMeal(mealId, pantryItems, userScopeId).filter(({ reservation }) => getActiveReservationHoldStatuses().includes(reservation.status));
  }

  function formatReservationQuantityText(reservation = {}) {
    if (reservation.scope === PANTRY_RESERVATION_SCOPES.ENTIRE_ITEM) return "Whole recorded item";
    const representation = reservation.quantityDetails?.representation || "";
    const prefix = representation === PANTRY_QUANTITY_REPRESENTATIONS.ESTIMATED_POINT || representation === PANTRY_QUANTITY_REPRESENTATIONS.ESTIMATED_RANGE ? "Approximately " : "";
    return `${prefix}${formatShoppingQuantity(reservation.quantity, reservation.unit || reservation.quantityDetails?.unit || "")}`.trim();
  }

  function createMealCancellationId({ mealId, requestId }) {
    return `meal-cancellation:${getActiveUserScopeId()}:${mealId}:${requestId || "default"}:v${MEAL_CANCELLATION_VERSION}`.replace(/[^a-z0-9:-]/gi, "-").toLowerCase();
  }

  function buildReservationReleaseSummary(release = {}, pantrySnapshot = state.pantry) {
    const releasedRows = (release.reservations || []).map((reservation) => {
      const item = pantrySnapshot.map(normalizePantryItem).find((candidate) => candidate.id === reservation.pantryItemId) || {};
      const availability = getPantryReservationAvailability({ pantryItemId: reservation.pantryItemId, excludingMealId: reservation.mealId, pantryItems: pantrySnapshot });
      return {
        reservationId: reservation.reservationId,
        ingredientId: item.ingredientId || reservation.ingredientDemandId || "",
        pantryItemId: reservation.pantryItemId,
        displayName: item.displayName || item.name || "Pantry item",
        packageLabel: getPackageLabel(item, 0),
        releasedQuantity: reservation.scope === PANTRY_RESERVATION_SCOPES.ENTIRE_ITEM ? null : Number(reservation.quantity),
        quantityText: formatReservationQuantityText(reservation),
        unit: reservation.unit || item.quantityDetails?.unit || item.unit || "",
        scope: reservation.scope || PANTRY_RESERVATION_SCOPES.QUANTITY,
        quantityConfidence: reservation.quantityDetails?.confidence || QUANTITY_CONFIDENCE_LEVELS.UNKNOWN,
        physicalQuantity: availability.physicalQuantity,
        activeReservedQuantity: availability.activeReservedQuantity,
        availableQuantity: availability.freelyAvailableQuantity,
        availabilityText: availability.freelyAvailableQuantity === null ? "Available for another planning decision" : `${formatShoppingQuantity(availability.freelyAvailableQuantity, availability.unit)} is available for planning again`
      };
    });
    return {
      activeReservationsFound: releasedRows.length,
      reservationsReleased: releasedRows.length,
      exactQuantityReleased: releasedRows.filter((row) => Number.isFinite(row.releasedQuantity)).map((row) => ({ ingredientId: row.ingredientId, pantryItemId: row.pantryItemId, quantity: row.releasedQuantity, unit: row.unit })),
      qualitativeCapacityReleased: releasedRows.filter((row) => row.unit && row.unit.includes("serving") && !Number.isFinite(row.releasedQuantity)),
      wholeItemReservationsReleased: releasedRows.filter((row) => row.scope === PANTRY_RESERVATION_SCOPES.ENTIRE_ITEM),
      releasedRows
    };
  }

  function markDependentLeftoverMealsForSourceCancellation(sourceMealId, cancellationId, now = getCurrentIsoString()) {
    const affectedMealIds = [];
    Object.entries(state.mealPlans.calendar || {}).forEach(([date, dayPlan]) => {
      const normalizedDay = normalizeMealDay(dayPlan, CALENDAR_MEALS, date);
      let changed = false;
      normalizedDay.mealSlots = getMealSlotsForDay(normalizedDay, CALENDAR_MEALS).map((slot) => {
        const entry = normalizeMealPlanEntry(slot.entry);
        if (!entry || entry.mealId === sourceMealId || entry.status === MEAL_STATUSES.CANCELLED) return slot;
        const dependsOnSource = entry.leftoverFromMealId === sourceMealId
          || entry.sourceMealId === sourceMealId
          || (entry.leftoverTargets || []).some((target) => target.sourceMealId === sourceMealId || target.leftoverFromMealId === sourceMealId)
          || (entry.plannedOutcome?.plannedLeftovers || []).some((target) => target.sourceMealId === sourceMealId || target.leftoverFromMealId === sourceMealId);
        if (!dependsOnSource) return slot;
        const mealType = getMealSlotLabel(slot);
        affectedMealIds.push(entry.mealId || `${date}:${mealType}`);
        changed = true;
        return {
          ...slot,
          entry: {
            ...entry,
            dependentMealStatus: DEPENDENT_MEAL_STATUSES.NEEDS_REPLACEMENT,
            dependencyStatus: DEPENDENT_MEAL_STATUSES.SOURCE_MEAL_CANCELLED,
            status: MEAL_STATUSES.NEEDS_OUTCOME_REVIEW,
            sourceMealCancellationId: cancellationId,
            updatedAt: now
          }
        };
      });
      if (changed) {
        syncLegacyMealFieldsFromSlots(normalizedDay, CALENDAR_MEALS);
        state.mealPlans.calendar[date] = normalizedDay;
      }
    });
    return { affectedMealIds, needsRepair: affectedMealIds.length > 0 };
  }

  function createMealCancellationRecord({ meal, date, mealType, reason, cancellationId, releaseSummary, dependentMealSummary, previousMealStatus, result, requestId, now }) {
    return {
      mealCancellationVersion: MEAL_CANCELLATION_VERSION,
      cancellationId,
      userScopeId: getActiveUserScopeId(),
      mealId: meal.mealId,
      planId: meal.planId || createStableSavedPlanId(state.mealPlans, null, null),
      calendarDate: date,
      mealType,
      previousMealStatus,
      currentMealStatus: MEAL_STATUSES.CANCELLED,
      reason: Object.values(MEAL_CANCELLATION_REASONS).includes(reason) ? reason : MEAL_CANCELLATION_REASONS.NOT_RECORDED,
      cancelledAt: now,
      reservationReleaseSummary: releaseSummary,
      dependentMealSummary,
      result,
      sourceRevisions: getCalendarReservationSourceRevisions(state.pantry, state.mealPlans),
      requestId
    };
  }

  function commitMealCancellation({ date, mealType, reason = MEAL_CANCELLATION_REASONS.NOT_RECORDED, requestId = "" } = {}) {
    const found = getCalendarMealForCancellation(date, mealType);
    if (!found?.entry?.mealId) return { ok: false, result: MEAL_CANCELLATION_RESULTS.FAILED, message: "MEAL CANCELLATION NEEDS REVIEW. Chef Nova could not find the meal. The meal and Pantry reservations remain in their last verified state." };
    const meal = found.entry;
    const previousMealStatus = getMealStatusForCancellation(meal);
    if (previousMealStatus === MEAL_STATUSES.CANCELLED) return { ok: true, result: MEAL_CANCELLATION_RESULTS.ALREADY_CANCELLED, cancellationRecord: meal.cancellationRecord || meal.cancellation || null, releaseSummary: meal.reservationReleaseSummary || { releasedRows: [] } };
    if (previousMealStatus === MEAL_STATUSES.STARTED) return { ok: false, result: MEAL_CANCELLATION_RESULTS.OUTCOME_REVIEW_REQUIRED, message: "Meal outcome review is required before releasing Pantry reservations." };
    if ([MEAL_STATUSES.PREPARED, MEAL_STATUSES.COMPLETED].includes(previousMealStatus)) return { ok: false, result: MEAL_CANCELLATION_RESULTS.OUTCOME_REVIEW_REQUIRED, message: "This meal was prepared or completed. Use meal outcome correction instead of cancellation." };
    const activeRows = getActiveReservationRowsForMeal(meal.mealId);
    const previousCalendar = structuredCloneSafe(state.mealPlans.calendar || {});
    const previousPantry = structuredCloneSafe(state.pantry || []);
    const now = getCurrentIsoString();
    const cancellationId = createMealCancellationId({ mealId: meal.mealId, requestId: requestId || `${date}:${mealType}` });
    const release = releaseMealReservations({
      mealId: meal.mealId,
      releaseReason: RESERVATION_RELEASE_REASONS.MEAL_CANCELLED,
      cancellationId,
      currentRevisions: getCalendarReservationSourceRevisions(state.pantry, state.mealPlans),
      pantryItems: previousPantry,
      commit: false
    });
    if (!release.ok) return { ok: false, result: MEAL_CANCELLATION_RESULTS.FAILED, message: "MEAL CANCELLATION NEEDS REVIEW. Chef Nova could not safely cancel the meal and release all related reservations. The meal and Pantry reservations remain in their last verified state." };
    const releaseSummary = buildReservationReleaseSummary(release, release.nextPantry);
    state.mealPlans.calendar = structuredCloneSafe(previousCalendar);
    const dependentMealSummary = markDependentLeftoverMealsForSourceCancellation(meal.mealId, cancellationId, now);
    const result = dependentMealSummary.needsRepair ? MEAL_CANCELLATION_RESULTS.DEPENDENT_MEALS_NEED_REPAIR : activeRows.length ? MEAL_CANCELLATION_RESULTS.CANCELLED_AND_RELEASED : MEAL_CANCELLATION_RESULTS.CANCELLED_NO_ACTIVE_RESERVATIONS;
    const cancellationRecord = createMealCancellationRecord({ meal, date, mealType, reason, cancellationId, releaseSummary, dependentMealSummary, previousMealStatus, result, requestId, now });
    const cancelledEntry = {
      ...meal,
      status: MEAL_STATUSES.CANCELLED,
      cancellation: { cancellationId, cancelledAt: now, reason: cancellationRecord.reason },
      cancellationRecord,
      reservationReleaseSummary: releaseSummary,
      reservationReleaseRecords: release.releaseRecords,
      pantryReservationIds: meal.pantryReservationIds || [],
      cancelledAt: now,
      updatedAt: now
    };
    state.mealPlans.calendar[date] = setMealSlotEntry(state.mealPlans.calendar[date], found.slotId || mealType, cancelledEntry, CALENDAR_MEALS);
    const commit = commitPantrySnapshotAndFoodEvents(release.nextPantry, release.events);
    if (!commit.ok) {
      state.mealPlans.calendar = previousCalendar;
      state.pantry = previousPantry.map((item) => normalizePantryItem(item));
      return { ok: false, result: MEAL_CANCELLATION_RESULTS.FAILED, message: "MEAL CANCELLATION NEEDS REVIEW. Chef Nova could not safely cancel the meal and release all related reservations. The meal and Pantry reservations remain in their last verified state. No physical Pantry quantity, Shopping List purchase, or Impact Ledger value was changed." };
    }
    state.mealPlans.cancellations = [cancellationRecord, ...(state.mealPlans.cancellations || []).filter((record) => record.cancellationId !== cancellationId)];
    syncWeeklyFromCalendarDate(date);
    saveMealPlan();
    displayMealPlanner();
    displayShoppingList();
    displayPantry();
    updateWeeklyNutritionSummary({ showNotification: false });
    announcePolite(buildMealCancellationAnnouncement(cancellationRecord), { key: cancellationId });
    showToast("Meal cancelled. Pantry reservations were released. Physical Pantry quantities were not changed.", "success", { saveToHistory: true, actionName: "View Meal Planner", actionTarget: "planner" });
    return { ok: true, result, cancellationRecord, releaseSummary, dependentMealSummary };
  }

  function buildMealCancellationAnnouncement(cancellationRecord = {}) {
    const rows = cancellationRecord.reservationReleaseSummary?.releasedRows || [];
    const first = rows[0];
    if (cancellationRecord.dependentMealSummary?.needsRepair) return `Meal cancelled. ${cancellationRecord.dependentMealSummary.affectedMealIds.length} planned leftover ${pluralize(cancellationRecord.dependentMealSummary.affectedMealIds.length, "meal")} now need replacements.`;
    if (first?.availableQuantity !== null && first?.availableQuantity !== undefined) return `Meal cancelled. ${rows.length} Pantry ${pluralize(rows.length, "reservation")} released. ${formatShoppingQuantity(first.availableQuantity, first.unit)} ${first.displayName} is available for planning again. Physical Pantry quantities were not changed.`;
    return `Meal cancelled. ${rows.length} Pantry ${pluralize(rows.length, "reservation")} released. Physical Pantry quantities were not changed.`;
  }

  function renderReservationRowsForCancellation(rows = []) {
    if (!rows.length) return "<li>No active Pantry reservations.</li>";
    return rows.map(({ item, reservation }) => `<li><span><strong>${escapeHtml(item.displayName || item.name || "Pantry item")}</strong><small>${escapeHtml(getPackageLabel(item, 0))}</small></span><span>${escapeHtml(formatReservationQuantityText(reservation))}</span></li>`).join("");
  }

  function openCalendarMealCancellationDialog(date, mealType) {
    const found = getCalendarMealForCancellation(date || state.selectedCalendarDate, mealType);
    if (!found?.entry) return deleteCalendarMeal(mealType);
    mealPlanGenerationLastFocus = document.activeElement;
    const status = getMealStatusForCancellation(found.entry);
    if (status === MEAL_STATUSES.CANCELLED) return renderMealCancellationResult(found.entry.cancellationRecord || { result: MEAL_CANCELLATION_RESULTS.ALREADY_CANCELLED, reservationReleaseSummary: found.entry.reservationReleaseSummary || { releasedRows: [] }, mealId: found.entry.mealId, calendarDate: found.date, mealType }, found.entry.reservationReleaseSummary || { releasedRows: [] });
    if (status === MEAL_STATUSES.STARTED || [MEAL_STATUSES.PREPARED, MEAL_STATUSES.COMPLETED].includes(status)) {
      renderMealPlanGenerationModal(`<section class="meal-cancellation-dialog" aria-labelledby="mealCancellationReviewTitle">
        <div class="meal-generation-heading"><span class="eyebrow">MEAL OUTCOME REVIEW</span><h2 id="mealCancellationReviewTitle">Review ${escapeHtml(found.entry.recipeName)}</h2><p>This meal may have started or been prepared. Chef Nova needs the meal outcome before releasing Pantry reservations.</p></div>
        <div class="meal-generation-actions"><button class="button primary" type="button" data-cook-tonight-finish="${escapeHtml(found.entry.cookTonightWorkflowId || "")}">Review Meal Outcome</button><button class="button secondary" type="button" data-cancel-generated-plan>Return to Calendar</button></div>
      </section>`);
      return;
    }
    const activeRows = getActiveReservationRowsForMeal(found.entry.mealId);
    const dependentCount = Object.values(state.mealPlans.calendar || {}).flatMap((dayPlan) => getMealSlotsForDay(dayPlan, CALENDAR_MEALS).map((slot) => normalizeMealPlanEntry(slot.entry))).filter((entry) => entry && entry.mealId !== found.entry.mealId && (entry.leftoverFromMealId === found.entry.mealId || entry.sourceMealId === found.entry.mealId)).length;
    renderMealPlanGenerationModal(`<section class="meal-cancellation-dialog" aria-labelledby="mealCancellationTitle">
      <div class="meal-generation-heading"><span class="eyebrow">CANCEL MEAL</span><h2 id="mealCancellationTitle">Cancel ${escapeHtml(found.entry.recipeName)}?</h2><p>${escapeHtml(formatDate(found.date))} ${escapeHtml(mealType)}. Cancelling releases this meal's active Pantry reservations only.</p></div>
      <section class="meal-cancellation-summary" aria-label="Current meal reservations">
        <h3>This meal currently reserves</h3>
        <ul class="calendar-reservation-list">${renderReservationRowsForCancellation(activeRows)}</ul>
        <p>Physical Pantry quantities will not change.</p>
        <p>${dependentCount ? `${dependentCount} future leftover ${pluralize(dependentCount, "meal")} may need replacement.` : "Dependent leftover meals: None"}</p>
      </section>
      <label>Cancellation reason, optional<select data-meal-cancellation-reason>
        <option value="${MEAL_CANCELLATION_REASONS.NOT_RECORDED}">Not recorded</option>
        <option value="${MEAL_CANCELLATION_REASONS.PLANS_CHANGED}">Plans changed</option>
        <option value="${MEAL_CANCELLATION_REASONS.CHOSE_DIFFERENT_MEAL}">Chose a different meal</option>
        <option value="${MEAL_CANCELLATION_REASONS.INGREDIENT_UNAVAILABLE}">Ingredient unavailable</option>
        <option value="${MEAL_CANCELLATION_REASONS.STORAGE_OR_SAFETY_REVIEW}">Storage or safety review</option>
        <option value="${MEAL_CANCELLATION_REASONS.OTHER}">Other</option>
      </select></label>
      <p class="form-error" id="mealCancellationError" role="alert"></p>
      <div class="meal-generation-actions">
        <button class="button danger" type="button" data-meal-cancel-confirm="${escapeHtml(found.date)}::${escapeHtml(mealType)}" aria-label="Cancel ${escapeHtml(found.entry.recipeName)} and release its Pantry reservations">Cancel Meal and Release Reservations</button>
        <button class="button secondary" type="button" data-cancel-generated-plan aria-label="Keep ${escapeHtml(found.entry.recipeName)} on the Calendar">Keep Meal</button>
      </div>
    </section>`);
  }

  function getPostCancellationActionsForRow(row = {}) {
    const item = state.pantry.map(normalizePantryItem).find((candidate) => candidate.id === row.pantryItemId);
    if (!item) return [{ label: "Keep in Pantry", action: "keep" }];
    const guardrail = getFoodSafetyGuardrailForPantryItem(item);
    if (guardrail.hardExclusion || guardrail.canUseForAutomaticPlanning === false) {
      if (guardrail.decision === FOOD_SAFETY_DECISIONS.EXCLUDED_RECORDED_EXPIRATION) return [{ label: "Review Item Details", action: "pantry" }, { label: "Record as Discarded", action: "discard" }];
      return [{ label: "Review Storage Information", action: "storage" }, { label: "Keep Excluded from Planning", action: "keep" }, { label: "Record as Discarded", action: "discard" }];
    }
    const freezer = resolveFreezerGuidance({ inventoryItem: item, foodSafetyGuardrail: guardrail });
    return [
      { label: "Find Another Recipe", action: "recipe" },
      ...(freezer.suitability?.canRecommendFreezing ? [{ label: "Review Freezing Options", action: "freeze" }] : []),
      { label: "Keep in Pantry", action: "keep" }
    ];
  }

  function renderMealCancellationResult(cancellationRecord = {}, releaseSummary = cancellationRecord.reservationReleaseSummary || {}) {
    const rows = releaseSummary.releasedRows || [];
    const first = rows[0];
    const heading = cancellationRecord.dependentMealSummary?.needsRepair ? `${cancellationRecord.dependentMealSummary.affectedMealIds.length} MEALS NEED A REPLACEMENT` : rows.length > 1 ? "RESERVATIONS RELEASED" : "RESERVATION RELEASED";
    const releasedRows = rows.map((row) => `<article class="reservation-release-card">
      <h3>${escapeHtml(row.displayName)}</h3>
      <dl>
        <div><dt>Previously reserved</dt><dd>${escapeHtml(row.quantityText)}</dd></div>
        <div><dt>Current physical Pantry quantity</dt><dd>${row.physicalQuantity === null ? "Not recorded" : escapeHtml(formatShoppingQuantity(row.physicalQuantity, row.unit))}</dd></div>
        <div><dt>Current reserved quantity</dt><dd>${escapeHtml(formatShoppingQuantity(row.activeReservedQuantity || 0, row.unit))}</dd></div>
        <div><dt>Current available quantity</dt><dd>${row.availableQuantity === null ? "Available for another planning decision. Chef Nova did not invent a numeric quantity." : escapeHtml(formatShoppingQuantity(row.availableQuantity, row.unit))}</dd></div>
      </dl>
      <p>${row.availableQuantity === null ? "The item is available for another planning decision." : `${escapeHtml(formatShoppingQuantity(row.releasedQuantity, row.unit))} is available for planning again.`}</p>
    </article>`).join("");
    const actions = getPostCancellationActionsForRow(first || {}).map((action) => `<button class="button ${action.action === "discard" ? "danger" : action.action === "recipe" ? "primary" : "secondary"}" type="button" data-post-cancel-action="${escapeHtml(action.action)}" data-post-cancel-item="${escapeHtml(first?.pantryItemId || "")}" data-post-cancel-date="${escapeHtml(cancellationRecord.calendarDate || "")}" data-post-cancel-meal="${escapeHtml(cancellationRecord.mealType || "")}">${escapeHtml(action.label)}</button>`).join("");
    renderMealPlanGenerationModal(`<section class="meal-cancellation-result" aria-labelledby="mealCancellationResultTitle" tabindex="-1">
      <div class="meal-generation-heading"><span class="eyebrow">MEAL CANCELLED</span><h2 id="mealCancellationResultTitle">${escapeHtml(heading)}</h2><p>The reservation was released. Physical Pantry quantities were not changed.</p></div>
      ${first ? `<p><strong>${escapeHtml(first.displayName)}</strong> was reserved for ${escapeHtml(cancellationRecord.mealType || "this meal")}. It is now available for another plan when current safety and date rules allow.</p>` : "<p>No active Pantry reservations were found for this meal.</p>"}
      ${releasedRows}
      ${cancellationRecord.dependentMealSummary?.needsRepair ? `<section class="dependent-meal-repair"><h3>Dependent meals need replacement</h3><p>No leftover batch was created. Review the affected Calendar meals.</p></section>` : ""}
      <div class="meal-generation-actions">${actions || `<button class="button secondary" type="button" data-post-cancel-action="keep">Keep in Pantry</button>`}<button class="button secondary" type="button" data-cancel-generated-plan>Review Calendar</button></div>
    </section>`);
    setTimeout(() => $("#mealCancellationResultTitle")?.focus?.(), 0);
  }

  function confirmCalendarMealCancellation(encoded) {
    const [date, ...mealParts] = String(encoded || "").split("::");
    const mealType = mealParts.join("::");
    const reason = $("[data-meal-cancellation-reason]")?.value || MEAL_CANCELLATION_REASONS.NOT_RECORDED;
    const result = commitMealCancellation({ date, mealType, reason, requestId: `${date}:${mealType}` });
    if (!result.ok) {
      const error = $("#mealCancellationError");
      if (error) error.textContent = result.message || "Meal cancellation needs review.";
      announcePolite("Meal cancellation needs review. The meal and Pantry reservations remain in their last verified state.", { key: `meal-cancel-failed-${date}-${mealType}` });
      return result;
    }
    renderMealCancellationResult(result.cancellationRecord, result.releaseSummary);
    return result;
  }

  function handlePostCancellationAction(action, pantryItemId) {
    const item = state.pantry.map(normalizePantryItem).find((candidate) => candidate.id === pantryItemId);
    if (action === "recipe") {
      closeMealPlanGenerationModal();
      navigate("recipes");
      const search = $("#recipeSearch");
      if (search && item) search.value = item.displayName || item.name || "";
      searchRecipes({ requireIngredients: false, notify: false });
      announcePolite(item ? `Finding recipe ideas using the released ${item.displayName || item.name}. No new reservation was created.` : "Finding recipe ideas. No new reservation was created.", { key: `post-cancel-recipe-${pantryItemId}` });
      return;
    }
    if (action === "freeze" && item) return openFreezerRecordingWorkflow({ inventoryItemId: pantryItemId, sourceWorkflow: FREEZER_RECORDING_SOURCES.MEAL_PLANNER });
    if (action === "storage" && item) {
      closeMealPlanGenerationModal();
      navigate("pantry");
      focusStorageReviewForm(pantryItemId);
      return;
    }
    if (action === "pantry" && item) {
      closeMealPlanGenerationModal();
      navigate("pantry");
      return;
    }
    if (action === "discard" && item) {
      closeMealPlanGenerationModal();
      return openRecordDiscardedFoodWorkflow({ inventoryItemId: pantryItemId, sourceWorkflow: DISCARD_RECORDING_SOURCES.PANTRY_ITEM_ACTION });
    }
    closeMealPlanGenerationModal();
    announcePolite("The released food remains in the Pantry. No quantity, date, storage, safety, or priority value was changed.", { key: `post-cancel-keep-${pantryItemId || "none"}` });
  }

  function reconcileMealReservations({ mealId, actualOutcome = {}, currentRevisions = {}, userScopeId = getActiveUserScopeId() } = {}) {
    void currentRevisions;
    if (!mealId) return { ok: false, message: "Meal outcome needs review." };
    return {
      ok: true,
      status: "outcome-review-required",
      userScopeId,
      mealId,
      actualOutcome,
      message: "Meal completion must use confirmed actual quantities before Pantry deduction."
    };
  }

  function revalidateMealReservations({ mealId, changedSource = "calendar", currentRevisions = {}, userScopeId = getActiveUserScopeId(), pantryItems = state.pantry } = {}) {
    const affected = pantryItems.map(normalizePantryItem).flatMap((item) => (item.reservations || []).filter((reservation) => reservation.mealId === mealId && (!reservation.userScopeId || reservation.userScopeId === userScopeId)).map((reservation) => {
      const availability = getPantryReservationAvailability({ pantryItemId: item.id, excludingMealId: reservation.mealId, userScopeId, pantryItems });
      const quantity = Number(reservation.quantity) || 0;
      const physical = Number(item.quantityDetails?.currentQuantity);
      const needsQuantityReview = Number.isFinite(physical) && quantity > physical + 1e-6;
      return {
        reservationId: reservation.reservationId,
        pantryItemId: item.id,
        mealId,
        changedSource,
        status: needsQuantityReview || availability.conflicts.length ? PANTRY_RESERVATION_STATUSES.NEEDS_QUANTITY_REVIEW : reservation.status,
        reviewRequired: needsQuantityReview || availability.conflicts.length > 0,
        message: needsQuantityReview ? `The reservation exceeds the Pantry amount by ${formatShoppingQuantity(quantity - physical, reservation.unit)}.` : "",
        sourceRevisions: currentRevisions
      };
    }));
    return { ok: true, mealId, changedSource, affectedReservations: affected };
  }

  function normalizeCalendarMealForReservation(entry, date, mealType, previousEntry = null) {
    const meal = normalizeMealPlanEntry(entry);
    if (!meal) return null;
    return {
      ...meal,
      mealId: getCalendarMealId(date, mealType, previousEntry),
      slotMealType: mealType,
      calendarDate: date,
      mealWindow: createMealWindowForReservation(date, mealType),
      calendarReservationPolicyVersion: PANTRY_RESERVATION_POLICY_VERSION
    };
  }

  function isSameCalendarMealForReservation(previousEntry, nextEntry) {
    const previous = normalizeMealPlanEntry(previousEntry);
    const next = normalizeMealPlanEntry(nextEntry);
    if (!previous || !next) return false;
    return previous.recipeId === next.recipeId
      && normalizeIngredient(previous.recipeName) === normalizeIngredient(next.recipeName)
      && Number(previous.servings || 1) === Number(next.servings || 1)
      && Array.isArray(previous.pantryReservationIds)
      && previous.pantryReservationIds.length > 0;
  }

  function buildCalendarReservationAllocationsForMeal(plan, mealId, pantrySnapshot = state.pantry) {
    const allocation = buildPantryAllocationForPlan(plan, pantrySnapshot);
    return (allocation?.summary?.mealPantryAllocations || [])
      .filter((row) => row.mealId === mealId)
      .flatMap((row) => (row.allocations || []).map((allocationRow) => ({
        pantryItemId: allocationRow.pantryItemId,
        ingredientId: row.ingredientId || allocationRow.ingredientId || null,
        displayName: row.displayName || allocationRow.originalLabel || "Pantry item",
        reservedQuantity: Number(allocationRow.quantity) || 0,
        unit: allocationRow.unit || row.requiredUnit || row.missingUnit || "",
        ingredientDemandId: `${mealId}::${row.ingredientId || normalizeIngredient(row.displayName || "ingredient")}`,
        requiredQuantity: row.requiredQuantity,
        requiredUnit: row.requiredUnit,
        missingQuantity: row.missingQuantity,
        missingUnit: row.missingUnit,
        originalLabel: allocationRow.originalLabel || row.displayName || "Pantry item",
        requiredForm: row.requiredForm || "",
        form: allocationRow.form || ""
      }))).filter((row) => row.pantryItemId && row.reservedQuantity > 0);
  }

  function buildCalendarMissingPurchaseRowsForMeal(plan, mealId, pantrySnapshot = state.pantry) {
    const allocation = buildPantryAllocationForPlan(plan, pantrySnapshot);
    return (allocation?.summary?.mealPantryAllocations || [])
      .filter((row) => row.mealId === mealId && Number(row.missingQuantity) > 0)
      .map((row) => ({
        ingredientDemandId: `${mealId}::${row.ingredientId || normalizeIngredient(row.displayName || "ingredient")}`,
        ingredientId: row.ingredientId || null,
        displayName: row.displayName || "Ingredient",
        missingQuantity: row.missingQuantity,
        unit: row.missingUnit || row.requiredUnit || "",
        sourceMealId: mealId
      }));
  }

  function scheduleMealWithReservations({ date, nextDayPlan, previousDayPlan = {}, currentRevisions = {}, userScopeId = getActiveUserScopeId() } = {}) {
    if (!isIsoDate(date)) return { ok: false, message: "Meal date needs review." };
    const previousCalendar = structuredCloneSafe(state.mealPlans.calendar || {});
    const previousPantry = structuredCloneSafe(state.pantry || []);
    const releaseMealIds = [];
    const keptReservationIds = new Map();
    const normalizedDay = normalizeMealDay(nextDayPlan, CALENDAR_MEALS, date);
    const previousDay = normalizeMealDay(previousDayPlan, CALENDAR_MEALS, date);
    getMealSlotsForDay(previousDay, CALENDAR_MEALS).forEach((previousSlot) => {
      const mealType = getMealSlotLabel(previousSlot);
      const previousEntry = normalizeMealPlanEntry(previousSlot.entry);
      const nextSlot = findMealSlot(normalizedDay, previousSlot.id, CALENDAR_MEALS);
      const nextEntry = normalizeMealPlanEntry(nextSlot?.entry);
      if (previousEntry?.mealId && (!nextEntry || !isSameCalendarMealForReservation(previousEntry, nextEntry))) releaseMealIds.push(previousEntry.mealId);
      if (previousEntry && nextEntry && isSameCalendarMealForReservation(previousEntry, nextEntry)) {
        keptReservationIds.set(previousSlot.id, {
          pantryReservationIds: structuredCloneSafe(previousEntry.pantryReservationIds || []),
          calendarReservationGroups: structuredCloneSafe(previousEntry.calendarReservationGroups || []),
          plannedOutcome: structuredCloneSafe(previousEntry.plannedOutcome || null)
        });
      }
    });
    normalizedDay.mealSlots = getMealSlotsForDay(normalizedDay, CALENDAR_MEALS).map((slot) => {
      const previousSlot = findMealSlot(previousDay, slot.id, CALENDAR_MEALS);
      const previousEntry = normalizeMealPlanEntry(previousSlot?.entry);
      const nextEntry = normalizeMealPlanEntry(slot.entry);
      return { ...slot, entry: nextEntry ? normalizeCalendarMealForReservation(nextEntry, date, getMealSlotLabel(slot), previousEntry) : null };
    });
    syncLegacyMealFieldsFromSlots(normalizedDay, CALENDAR_MEALS);
    let workingPantry = previousPantry.map((item) => normalizePantryItem(item));
    let allEvents = [];
    for (const mealId of releaseMealIds) {
      const release = releaseMealReservations({ mealId, releaseReason: "superseded", currentRevisions, userScopeId, pantryItems: workingPantry, commit: false });
      if (!release.ok) return release;
      workingPantry = release.nextPantry;
      allEvents = [...allEvents, ...release.events];
    }
    const candidatePlan = cloneMealPlan(state.mealPlans);
    candidatePlan.calendar = { ...(candidatePlan.calendar || {}), [date]: normalizeMealDay(normalizedDay, CALENDAR_MEALS) };
    normalizedDay.mealSlots = getMealSlotsForDay(normalizedDay, CALENDAR_MEALS).map((slot) => {
      const kept = keptReservationIds.get(slot.id);
      if (!kept || !slot.entry) return slot;
      const entry = {
        ...slot.entry,
        pantryReservationIds: kept.pantryReservationIds,
        calendarReservationGroups: kept.calendarReservationGroups
      };
      if (kept.plannedOutcome) entry.plannedOutcome = kept.plannedOutcome;
      revalidateMealReservations({ mealId: entry.mealId, changedSource: "calendar-save", currentRevisions, userScopeId, pantryItems: workingPantry });
      return { ...slot, entry };
    });
    syncLegacyMealFieldsFromSlots(normalizedDay, CALENDAR_MEALS);
    for (const slot of getMealSlotsForDay(normalizedDay, CALENDAR_MEALS)) {
      const mealType = getMealSlotLabel(slot);
      const meal = normalizeMealPlanEntry(slot.entry);
      if (!meal?.recipeId || keptReservationIds.has(slot.id)) continue;
      const pantryAllocations = buildCalendarReservationAllocationsForMeal(candidatePlan, meal.mealId, workingPantry);
      const reservationResult = reservePantryForMeal({
        meal: { ...meal, date, mealType, planId: createStableSavedPlanId(candidatePlan, null, null) },
        pantryAllocations,
        currentRevisions,
        userScopeId,
        pantryItems: workingPantry,
        origin: meal.source === PLANNING_MODES.COOK_BEFORE_IT_SPOILS ? PANTRY_RESERVATION_ORIGINS.COOK_BEFORE_IT_SPOILS : PANTRY_RESERVATION_ORIGINS.CALENDAR_ADD
      });
      if (!reservationResult.ok) return reservationResult;
      workingPantry = reservationResult.nextPantry;
      allEvents = [...allEvents, ...reservationResult.events];
      const missingRows = buildCalendarMissingPurchaseRowsForMeal(candidatePlan, meal.mealId, workingPantry);
      const reservedMeal = {
        ...meal,
        pantryReservationIds: reservationResult.reservations.map((reservation) => reservation.reservationId),
        calendarReservationGroups: reservationResult.reservationGroups,
        plannedOutcome: {
          ...(meal.plannedOutcome || {}),
          pantryAllocations,
          missingPurchases: missingRows,
          plannedLeftovers: meal.leftoverTargets || [],
          physicalPantryQuantityChanged: false,
          impactCreditCreated: false
        },
        shoppingDemandReferences: missingRows.map((row) => row.ingredientDemandId)
      };
      normalizedDay.mealSlots = normalizedDay.mealSlots.map((candidate) => candidate.id === slot.id ? { ...candidate, entry: reservedMeal } : candidate);
    }
    syncLegacyMealFieldsFromSlots(normalizedDay, CALENDAR_MEALS);
    const commit = commitPantrySnapshotAndFoodEvents(workingPantry, allEvents);
    if (!commit.ok) {
      state.mealPlans.calendar = previousCalendar;
      state.pantry = previousPantry.map((item) => normalizePantryItem(item));
      return { ok: false, message: "Meal reservation needs review. Pantry quantity and Calendar were not changed." };
    }
    state.mealPlans.calendar = state.mealPlans.calendar || {};
    state.mealPlans.calendar[date] = normalizeMealDay(normalizedDay, CALENDAR_MEALS);
    syncWeeklyFromCalendarDate(date);
    saveMealPlan();
    ensureBudgetPurchaseGroupsInShoppingList(derivePriceConfidence({ purchaseGroups: calculateCurrentMealPlanCosts()?.purchaseGroups || [], weeklyCostSummary: calculateCurrentMealPlanCosts()?.weeklySummary || {} }));
    return { ok: true, dayPlan: normalizedDay, reservationsCreated: allEvents.filter((event) => event?.eventType === FOOD_EVENT_TYPES.RESERVED_FOR_RECIPE).length, releasedEventCount: allEvents.filter((event) => event?.eventType === FOOD_EVENT_TYPES.RESERVATION_CANCELLED).length };
  }

  function createCookTonightMealEntry(recipe, draft, reservations) {
    return {
      ...createRecipeMealEntry(recipe, draft.servingPlan.requestedMealServings),
      mealId: draft.mealId,
      source: PLANNING_MODES.COOK_BEFORE_IT_SPOILS,
      status: COOK_TONIGHT_WORKFLOW_STATUSES.PLANNED,
      foodRescueCandidateId: draft.candidateId,
      foodRescueRankingVersion: draft.rescueRankingVersion,
      cookTonightWorkflowId: draft.workflowId,
      cookTonightMetadataVersion: COOK_TONIGHT_PLAN_METADATA_VERSION,
      peopleEating: draft.peopleEating.count,
      plannedRecipeServings: draft.servingPlan.effectiveRecipeYield,
      requestedMealServings: draft.servingPlan.requestedMealServings,
      reservedLeftoverServings: draft.servingPlan.plannedLeftoverServings,
      plannedFrozenServings: draft.servingPlan.plannedFrozenServings,
      plannedSharedServings: draft.servingPlan.plannedSharedServings,
      unallocatedServings: draft.servingPlan.servingAllocation?.unallocatedServings || 0,
      servingAllocation: draft.servingPlan.servingAllocation,
      portionPreview: draft.portionPreview,
      pantryReservationIds: reservations.map((reservation) => reservation.reservationId),
      plannedOutcome: {
        peopleEating: draft.peopleEating,
        mealServings: draft.servingPlan.requestedMealServings,
        leftoverServings: draft.servingPlan.plannedLeftoverServings,
        frozenServings: draft.servingPlan.plannedFrozenServings,
        sharedServings: draft.servingPlan.plannedSharedServings,
        unallocatedServings: draft.servingPlan.servingAllocation?.unallocatedServings || 0,
        servingAllocation: draft.servingPlan.servingAllocation,
        portionPreview: draft.portionPreview,
        pantryAllocations: draft.pantryAllocationPreview.map((row) => ({ ...row }))
      },
      shoppingDemandReferences: draft.missingPurchaseGroups.map((group) => group.purchaseGroupId),
      foodRescuePlan: {
        workflowVersion: draft.workflowVersion,
        workflowId: draft.workflowId,
        candidateId: draft.candidateId,
        target: draft.target,
        servingPlan: draft.servingPlan,
        portionPreview: draft.portionPreview,
        reservations,
        missingPurchaseGroups: draft.missingPurchaseGroups,
        leftoverPlan: draft.leftoverPlan,
        sourceRevisions: draft.sourceRevisions,
        createdAt: draft.createdAt,
        updatedAt: getCurrentIsoString()
      }
    };
  }

  function renderCommittedCookTonightPlan(workflow) {
    const recipe = findRecipeById(workflow.recipeId);
    const allocations = workflow.pantryAllocationPreview || [];
    renderMealPlanGenerationModal(`<section class="cook-tonight-workflow committed" aria-labelledby="cookTonightPlanSummaryTitle">
      <div class="meal-generation-heading">
        <span class="eyebrow">TONIGHT'S FOOD-RESCUE PLAN</span>
        <h2 id="cookTonightPlanSummaryTitle">${escapeHtml(recipe?.name || "Recipe")}</h2>
        <p>${escapeHtml(formatEmergencyDate(workflow.target.date))} - ${escapeHtml(workflow.target.mealSlotId)}</p>
      </div>
      <dl class="cook-tonight-summary-list">
        <div><dt>People eating</dt><dd>${escapeHtml(String(workflow.peopleEating.count))}</dd></div>
        <div><dt>Planned yield</dt><dd>${escapeHtml(formatServingAmount(workflow.servingPlan.effectiveRecipeYield))}</dd></div>
        <div><dt>Expected leftover</dt><dd>${workflow.servingPlan.plannedLeftoverServings ? `Approximately ${escapeHtml(formatServingAmount(workflow.servingPlan.plannedLeftoverServings))}` : "No planned leftover"}</dd></div>
      </dl>
      ${renderCookTonightPortionPreview(workflow.portionPreview, { compact: true, showActions: false })}
      <section class="cook-tonight-card"><h3>Reserved from your Pantry</h3><ul>${allocations.map((row) => `<li>${escapeHtml(formatShoppingQuantity(row.plannedQuantity, row.unit))} ${escapeHtml(row.displayName)}${row.lotLabel ? ` - ${escapeHtml(row.lotLabel)}` : ""}</li>`).join("") || "<li>No tracked Pantry reservations.</li>"}</ul></section>
      <section class="cook-tonight-card"><h3>Still needed</h3><ul>${workflow.missingPurchaseGroups.length ? workflow.missingPurchaseGroups.map((group) => `<li>${escapeHtml(group.suggestedPurchaseText || formatShoppingQuantity(group.missingQuantity, group.missingUnit))} ${escapeHtml(group.displayName)}</li>`).join("") : "<li>Nothing else from the Shopping List.</li>"}</ul></section>
      <section class="cook-tonight-card"><h3>Storage guidance</h3><p>${escapeHtml(workflow.leftoverPlan?.guidance || "Confirm actual leftovers after cooking.")}</p></section>
      <div class="meal-generation-actions">
        <button class="button primary" type="button" data-cook-tonight-start="${escapeHtml(workflow.workflowId)}" aria-label="Start cooking ${escapeHtml(recipe?.name || "this recipe")}">Start Cooking</button>
        <button class="button secondary" type="button" data-cook-tonight-change="${escapeHtml(workflow.workflowId)}" aria-label="Change servings for tonight's ${escapeHtml(recipe?.name || "recipe")}">Change Servings</button>
        <button class="button secondary" type="button" data-page="shopping-list">Review Shopping List</button>
        <button class="button danger" type="button" data-cook-tonight-cancel-reservation="${escapeHtml(workflow.workflowId)}" aria-label="Cancel Pantry reservations for tonight's ${escapeHtml(recipe?.name || "recipe")}">Cancel Reservation</button>
      </div>
    </section>`);
  }

  function findCookTonightMeal(workflowId) {
    const calendar = state.mealPlans.calendar || {};
    for (const [date, dayPlan] of Object.entries(calendar)) {
      for (const mealType of CALENDAR_MEALS) {
        const entry = dayPlan?.[mealType];
        if (entry?.cookTonightWorkflowId === workflowId || entry?.foodRescuePlan?.workflowId === workflowId) return { date, mealType, entry };
      }
    }
    return null;
  }

  function updateCookTonightMealEntry(workflowId, updater) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return null;
    const next = updater(structuredCloneSafe(found.entry), found);
    state.mealPlans.calendar[found.date][found.mealType] = next;
    syncWeeklyFromCalendarDate(found.date);
    saveMealPlan();
    displayMealPlanner();
    return next;
  }

  function startCookTonightMeal(workflowId) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return showToast("Tonight's plan was not found.", "warning");
    const recipe = findRecipeById(found.entry.recipeId);
    const blockedReservation = (found.entry.pantryReservationIds || []).map((reservationId) => findPantryReservationById(reservationId)).filter(Boolean).find(({ item, reservation }) => {
      const decision = validateFoodUseActionAllowed({
        source: item,
        actionId: FOOD_USE_ACTION_IDS.USE_IN_HEATED_RECIPE,
        meal: found.entry,
        recipe,
        targetMealDate: found.date,
        requestId: `start-cooking:${workflowId}:${reservation.reservationId}`
      });
      return !decision.ok;
    });
    if (blockedReservation) {
      const decision = createRecommendationEligibilityDecision({
        source: blockedReservation.item,
        actionIds: [FOOD_USE_ACTION_IDS.USE_IN_HEATED_RECIPE, FOOD_USE_ACTION_IDS.REVIEW_INFORMATION, FOOD_USE_ACTION_IDS.RECORD_DISCARDED, FOOD_USE_ACTION_IDS.KEEP_RECORDED],
        meal: found.entry,
        recipe,
        targetMealDate: found.date,
        requestId: `start-cooking:${workflowId}`
      });
      renderMealPlanGenerationModal(`<section class="cook-tonight-workflow" aria-labelledby="startCookingBlockedTitle">
        <div class="meal-generation-heading"><span class="eyebrow">THIS MEAL CANNOT START WITH THE CURRENT INGREDIENTS</span><h2 id="startCookingBlockedTitle">${escapeHtml(recipe?.name || found.entry.recipeName)}</h2><p>No Pantry quantity, reservation, or meal plan was changed.</p></div>
        ${renderRecommendationEligibilityReasons(decision, { itemName: blockedReservation.item.displayName || blockedReservation.item.name || "this ingredient", heading: "THIS MEAL CANNOT START WITH THE CURRENT INGREDIENTS" })}
        <div class="meal-generation-actions">
          <button class="button secondary" type="button" data-calendar-replace-meal="${escapeHtml(found.mealType)}">Replace Ingredient</button>
          <button class="button secondary" type="button" data-page="planner">Choose Another Meal</button>
        </div>
      </section>`);
      announcePolite("Start cooking blocked. One ingredient needs eligibility review. No Pantry quantity was changed.", { key: `start-cooking-blocked-${workflowId}` });
      return;
    }
    updateCookTonightMealEntry(workflowId, (entry) => ({ ...entry, status: COOK_TONIGHT_WORKFLOW_STATUSES.COOKING, cookingStartedAt: getCurrentIsoString() }));
    renderMealPlanGenerationModal(`<section class="cook-tonight-workflow" aria-labelledby="cookTonightCookingTitle">
      <div class="meal-generation-heading"><span class="eyebrow">COOKING IN PROGRESS</span><h2 id="cookTonightCookingTitle">${escapeHtml(recipe?.name || found.entry.recipeName)}</h2><p>Pantry quantities remain reserved and have not been deducted.</p></div>
      <ol class="recipe-steps">${(recipe?.steps || []).map((step, index) => `<li><b>Step ${index + 1}</b><span>${escapeHtml(step)}</span></li>`).join("")}</ol>
      <div class="meal-generation-actions">
        <button class="button primary" type="button" data-cook-tonight-finish="${escapeHtml(workflowId)}" aria-label="Finish cooking ${escapeHtml(recipe?.name || found.entry.recipeName)}">Finish Cooking</button>
        <button class="button secondary" type="button" data-cancel-generated-plan>Close</button>
      </div>
    </section>`);
    announcePolite("Cooking started. Pantry quantities remain reserved and have not been deducted.", { key: `cook-tonight-start-${workflowId}` });
  }

  function openCookTonightOutcomeReview(workflowId) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return showToast("Tonight's plan was not found.", "warning");
    updateCookTonightMealEntry(workflowId, (entry) => ({ ...entry, status: COOK_TONIGHT_WORKFLOW_STATUSES.COMPLETION_REVIEW }));
    renderMealPlanGenerationModal(`<section class="cook-tonight-workflow" aria-labelledby="cookTonightOutcomeTitle">
      <div class="meal-generation-heading"><span class="eyebrow">MEAL OUTCOME</span><h2 id="cookTonightOutcomeTitle">Did you prepare this meal?</h2><p>No Pantry quantity is deducted until you confirm the outcome.</p></div>
      <fieldset class="cook-tonight-radio-group">
        <legend>Choose what happened</legend>
        <label><input type="radio" name="cookTonightOutcome" value="${COOK_TONIGHT_OUTCOMES.AS_PLANNED}"> Yes, as planned</label>
        <label><input type="radio" name="cookTonightOutcome" value="${COOK_TONIGHT_OUTCOMES.CHANGED_QUANTITIES}"> Yes, but I changed the quantities</label>
        <label><input type="radio" name="cookTonightOutcome" value="${COOK_TONIGHT_OUTCOMES.NOT_YET}"> Not yet</label>
        <label><input type="radio" name="cookTonightOutcome" value="${COOK_TONIGHT_OUTCOMES.CHOSE_SOMETHING_ELSE}"> I chose something else</label>
      </fieldset>
      <p class="form-error" id="cookTonightOutcomeError" role="alert"></p>
      <div class="meal-generation-actions"><button class="button primary" type="button" data-cook-tonight-outcome-next="${escapeHtml(workflowId)}">Continue</button><button class="button secondary" type="button" data-cancel-generated-plan>Close</button></div>
    </section>`);
  }

  function handleCookTonightOutcomeNext(workflowId) {
    const outcome = $("input[name='cookTonightOutcome']:checked")?.value;
    if (!outcome) {
      const target = $("#cookTonightOutcomeError");
      if (target) target.textContent = "Choose what happened before continuing.";
      return;
    }
    if (outcome === COOK_TONIGHT_OUTCOMES.AS_PLANNED) return renderCookTonightAsPlannedConfirm(workflowId);
    if (outcome === COOK_TONIGHT_OUTCOMES.CHANGED_QUANTITIES) return renderCookTonightChangedQuantityForm(workflowId);
    if (outcome === COOK_TONIGHT_OUTCOMES.NOT_YET) {
      updateCookTonightMealEntry(workflowId, (entry) => ({ ...entry, status: COOK_TONIGHT_WORKFLOW_STATUSES.PLANNED }));
      closeMealPlanGenerationModal();
      showToast("The meal remains planned. Pantry quantities have not been deducted.", "info");
      return;
    }
    return openCookTonightCancelReservation(workflowId, { choseSomethingElse: true });
  }

  function renderPreparedFoodOutcomeFields(entry) {
    const plannedFrozen = Number(entry.plannedFrozenServings || entry.plannedOutcome?.frozenServings || 0);
    const plannedShared = Number(entry.plannedSharedServings || entry.plannedOutcome?.sharedServings || 0);
    const unallocated = Number(entry.unallocatedServings || entry.plannedOutcome?.unallocatedServings || 0);
    return `${plannedFrozen > 0 ? `<fieldset class="cook-tonight-radio-group">
        <legend>What happened to planned frozen servings?</legend>
        <label><input type="radio" name="cookTonightFreezeOutcome" value="froze-as-planned"> Froze as planned</label>
        <label><input type="radio" name="cookTonightFreezeOutcome" value="froze-different"> Froze a different amount</label>
        <label><input type="radio" name="cookTonightFreezeOutcome" value="refrigerated"> Saved in the refrigerator instead</label>
        <label><input type="radio" name="cookTonightFreezeOutcome" value="none"> Did not freeze servings</label>
      </fieldset>
      <label>Actual frozen servings<input type="number" min="0" max="30" step="1" value="${escapeHtml(String(plannedFrozen))}" data-cook-tonight-actual-frozen></label>` : ""}
      ${plannedShared > 0 ? `<fieldset class="cook-tonight-radio-group">
        <legend>What happened to planned shared servings?</legend>
        <label><input type="radio" name="cookTonightShareOutcome" value="shared-as-planned"> Shared as planned</label>
        <label><input type="radio" name="cookTonightShareOutcome" value="shared-different"> Shared a different amount</label>
        <label><input type="radio" name="cookTonightShareOutcome" value="kept"> Kept the servings</label>
        <label><input type="radio" name="cookTonightShareOutcome" value="none"> Did not share servings</label>
      </fieldset>
      <label>Actual shared servings<input type="number" min="0" max="30" step="1" value="${escapeHtml(String(plannedShared))}" data-cook-tonight-actual-shared></label>` : ""}
      ${unallocated > 0 ? `<fieldset class="cook-tonight-radio-group">
        <legend>What happened to unallocated servings?</legend>
        <label><input type="radio" name="cookTonightUnallocatedOutcome" value="reviewed-kept"> Reviewed and kept</label>
        <label><input type="radio" name="cookTonightUnallocatedOutcome" value="reassigned"> Reassigned to leftovers, freezing, or sharing</label>
        <label><input type="radio" name="cookTonightUnallocatedOutcome" value="none-remained"> No extra servings remained</label>
        <label><input type="radio" name="cookTonightUnallocatedOutcome" value="unsure"> I am not sure</label>
      </fieldset>` : ""}
      <fieldset class="cook-tonight-radio-group leftover-storage-confirmation">
        <legend>Stored leftover details</legend>
        <label>Storage location<select data-cook-tonight-leftover-storage><option value="${PANTRY_STORAGE_LOCATIONS.REFRIGERATOR}">Refrigerator</option><option value="${PANTRY_STORAGE_LOCATIONS.FREEZER}">Freezer</option><option value="${PANTRY_STORAGE_LOCATIONS.OTHER}">Other reviewed storage</option></select></label>
        <label>Container<select data-cook-tonight-leftover-container><option value="${PANTRY_STORAGE_CONTAINERS.AIRTIGHT_CONTAINER}">Airtight container</option><option value="${PANTRY_STORAGE_CONTAINERS.FREEZER_BAG}">Freezer bag</option><option value="${PANTRY_STORAGE_CONTAINERS.ORIGINAL_PACKAGE}">Original package</option><option value="${PANTRY_STORAGE_CONTAINERS.OTHER}">Other container</option></select></label>
        <label>Storage started<input type="datetime-local" data-cook-tonight-leftover-storage-start></label>
      </fieldset>`;
  }

  function getCookTonightLeftoverStorageConfirmation() {
    const storageLocation = $("[data-cook-tonight-leftover-storage]")?.value || PANTRY_STORAGE_LOCATIONS.REFRIGERATOR;
    const storageContainer = $("[data-cook-tonight-leftover-container]")?.value || PANTRY_STORAGE_CONTAINERS.AIRTIGHT_CONTAINER;
    const startedValue = $("[data-cook-tonight-leftover-storage-start]")?.value || "";
    const leftoverStorageStartedAt = startedValue ? new Date(startedValue).toISOString() : getCurrentIsoString();
    return { storageLocation, storageContainer, leftoverStorageStartedAt };
  }

  function renderCookTonightAsPlannedConfirm(workflowId) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return;
    const entry = found.entry;
    const allocations = entry.plannedOutcome?.pantryAllocations || [];
    renderMealPlanGenerationModal(`<section class="cook-tonight-workflow" aria-labelledby="cookTonightCompleteTitle">
      <div class="meal-generation-heading"><span class="eyebrow">CONFIRM MEAL COMPLETION</span><h2 id="cookTonightCompleteTitle">${escapeHtml(entry.recipeName)}</h2><p>Chef Nova will record these actual Pantry quantities as used.</p></div>
      <ul class="cook-tonight-allocation-list">${allocations.map((row) => `<li><b>${escapeHtml(row.displayName)}</b><span>${escapeHtml(formatShoppingQuantity(row.plannedQuantity, row.unit))} used</span></li>`).join("")}</ul>
      <fieldset class="cook-tonight-radio-group">
        <legend>What happened to the planned leftover?</legend>
        <label><input type="radio" name="cookTonightLeftoverOutcome" value="saved"> Saved as a leftover</label>
        <label><input type="radio" name="cookTonightLeftoverOutcome" value="eaten"> Eaten during the meal</label>
        <label><input type="radio" name="cookTonightLeftoverOutcome" value="none"> No leftover remained</label>
        <label><input type="radio" name="cookTonightLeftoverOutcome" value="unsure"> I am not sure</label>
      </fieldset>
      <label>Actual leftover servings saved<input type="number" min="0" max="20" step="1" value="${escapeHtml(String(entry.reservedLeftoverServings || 0))}" data-cook-tonight-actual-leftovers></label>
      ${renderPreparedFoodOutcomeFields(entry)}
      <div class="meal-generation-actions"><button class="button primary" type="button" data-cook-tonight-complete="${escapeHtml(workflowId)}" aria-label="Confirm ${escapeHtml(entry.recipeName)} was prepared as planned">Confirm as Prepared</button><button class="button secondary" type="button" data-cook-tonight-finish="${escapeHtml(workflowId)}">Go Back</button></div>
    </section>`);
  }

  function renderCookTonightChangedQuantityForm(workflowId) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return;
    const entry = found.entry;
    const allocations = entry.plannedOutcome?.pantryAllocations || [];
    renderMealPlanGenerationModal(`<section class="cook-tonight-workflow" aria-labelledby="cookTonightChangedTitle">
      <div class="meal-generation-heading"><span class="eyebrow">ACTUAL QUANTITIES USED</span><h2 id="cookTonightChangedTitle">Record actual quantities used</h2><p>This records meal use. Pantry record corrections stay separate.</p></div>
      <div class="cook-tonight-actual-grid">${allocations.map((row) => `<label>${escapeHtml(row.displayName)}<span>Planned: ${escapeHtml(formatShoppingQuantity(row.plannedQuantity, row.unit))}</span><input type="number" min="0" step="0.01" value="${escapeHtml(String(row.plannedQuantity))}" data-cook-tonight-actual-use="${escapeHtml(row.pantryItemId)}"><small>${escapeHtml(row.unit || "")}</small></label>`).join("")}</div>
      <label>Actual servings prepared<input type="number" min="1" max="30" step="1" value="${escapeHtml(String(entry.plannedRecipeServings || entry.servings || 1))}" data-cook-tonight-prepared></label>
      <label>Actual servings eaten<input type="number" min="1" max="30" step="1" value="${escapeHtml(String(entry.requestedMealServings || entry.servings || 1))}" data-cook-tonight-eaten></label>
      <label>Actual leftover servings<input type="number" min="0" max="30" step="1" value="${escapeHtml(String(entry.reservedLeftoverServings || 0))}" data-cook-tonight-actual-leftovers></label>
      ${renderPreparedFoodOutcomeFields(entry)}
      <p class="field-help">Was the Pantry amount wrong before cooking? Correct the Pantry record separately so meal use and quantity corrections stay distinct.</p>
      <div class="meal-generation-actions"><button class="button primary" type="button" data-cook-tonight-changed-complete="${escapeHtml(workflowId)}">Confirm Actual Quantities</button><button class="button secondary" type="button" data-cook-tonight-finish="${escapeHtml(workflowId)}">Go Back</button></div>
    </section>`);
  }

  function confirmCookTonightCompletion(workflowId) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return showToast("Tonight's plan was not found.", "warning");
    const allocations = found.entry.plannedOutcome?.pantryAllocations || [];
    const actualUses = allocations.map((row) => ({ ...row, actualQuantity: Number(row.plannedQuantity) || 0 }));
    const leftoverOutcome = $("input[name='cookTonightLeftoverOutcome']:checked")?.value || "unsure";
    const leftoverServings = leftoverOutcome === "saved" ? Math.max(0, clampWholeNumber($("[data-cook-tonight-actual-leftovers]")?.value || 0, 0, 30)) : 0;
    const frozenOutcome = $("input[name='cookTonightFreezeOutcome']:checked")?.value || null;
    const shareOutcome = $("input[name='cookTonightShareOutcome']:checked")?.value || null;
    const unallocatedOutcome = $("input[name='cookTonightUnallocatedOutcome']:checked")?.value || null;
    const storageConfirmation = getCookTonightLeftoverStorageConfirmation();
    const result = commitCookTonightCompletionAtomically(workflowId, {
      outcome: COOK_TONIGHT_OUTCOMES.AS_PLANNED,
      actualUses,
      servingsPrepared: Number(found.entry.plannedRecipeServings || found.entry.servings || 1),
      servingsEaten: Number(found.entry.requestedMealServings || found.entry.servings || 1),
      leftoverOutcome,
      leftoverServingsStored: leftoverServings,
      frozenOutcome,
      frozenServingsStored: clampWholeNumber($("[data-cook-tonight-actual-frozen]")?.value || 0, 0, 30),
      shareOutcome,
      sharedServings: clampWholeNumber($("[data-cook-tonight-actual-shared]")?.value || 0, 0, 30),
      unallocatedOutcome,
      ...storageConfirmation
    });
    if (!result.ok) return showCookTonightNeedsReview(result.message || "Chef Nova could not complete the meal transaction.");
    closeMealPlanGenerationModal();
    showToast("Meal completed. Pantry quantities were updated once.", "success");
    announcePolite("Meal completed. Pantry quantities were recorded as used once.", { key: `cook-tonight-complete-${workflowId}` });
  }

  function confirmCookTonightChangedQuantities(workflowId) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return showToast("Tonight's plan was not found.", "warning");
    const allocations = found.entry.plannedOutcome?.pantryAllocations || [];
    const actualUses = allocations.map((row) => {
      const value = Number($(`[data-cook-tonight-actual-use="${row.pantryItemId}"]`)?.value);
      return { ...row, actualQuantity: Number.isFinite(value) && value >= 0 ? value : null };
    });
    if (actualUses.some((row) => row.actualQuantity === null)) return showToast("Enter valid actual quantities.", "error");
    const result = commitCookTonightCompletionAtomically(workflowId, {
      outcome: COOK_TONIGHT_OUTCOMES.CHANGED_QUANTITIES,
      actualUses,
      servingsPrepared: clampWholeNumber($("[data-cook-tonight-prepared]")?.value || 1, 1, 30),
      servingsEaten: clampWholeNumber($("[data-cook-tonight-eaten]")?.value || 1, 1, 30),
      leftoverOutcome: Number($("[data-cook-tonight-actual-leftovers]")?.value || 0) > 0 ? "saved" : "none",
      leftoverServingsStored: clampWholeNumber($("[data-cook-tonight-actual-leftovers]")?.value || 0, 0, 30),
      frozenOutcome: $("input[name='cookTonightFreezeOutcome']:checked")?.value || null,
      frozenServingsStored: clampWholeNumber($("[data-cook-tonight-actual-frozen]")?.value || 0, 0, 30),
      shareOutcome: $("input[name='cookTonightShareOutcome']:checked")?.value || null,
      sharedServings: clampWholeNumber($("[data-cook-tonight-actual-shared]")?.value || 0, 0, 30),
      unallocatedOutcome: $("input[name='cookTonightUnallocatedOutcome']:checked")?.value || null,
      ...getCookTonightLeftoverStorageConfirmation()
    });
    if (!result.ok) return showCookTonightNeedsReview(result.message || "Chef Nova could not complete the meal transaction.");
    closeMealPlanGenerationModal();
    showToast("Meal completed with actual quantities. Pantry was updated once.", "success");
  }

  function commitCookTonightCompletionAtomically(workflowId, actual = {}) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return { ok: false, message: "The meal is no longer available." };
    if (found.entry.actualOutcome?.completedAt || found.entry.status === COOK_TONIGHT_WORKFLOW_STATUSES.COMPLETED) return { ok: true, idempotent: true };
    const completionKey = `meal-completion:${found.entry.mealId || workflowId}:v${COOK_TONIGHT_COMPLETION_VERSION}`;
    const history = state.foodEventHistory || loadFoodEventHistory();
    if (history.idempotencyIndex?.[completionKey]) return { ok: true, idempotent: true };
    const now = getCurrentIsoString();
    const nextPantry = state.pantry.map((item) => normalizePantryItem(item));
    const events = [];
    for (const use of actual.actualUses || []) {
      const item = nextPantry.find((candidate) => candidate.id === use.pantryItemId);
      if (!item) continue;
      const before = normalizePantryItem(state.pantry.find((candidate) => candidate.id === item.id) || item);
      const quantity = Number(use.actualQuantity);
      if (!Number.isFinite(quantity) || quantity < 0) return { ok: false, message: `Review the actual quantity for ${use.displayName}.` };
      const current = Number(item.quantityDetails?.currentQuantity);
      if (!Number.isFinite(current)) return { ok: false, message: `${use.displayName} needs a known Pantry quantity before completion.` };
      if (quantity > current + 1e-6) return { ok: false, message: `${use.displayName} does not have enough recorded Pantry quantity for the actual amount entered.` };
      item.quantity = Math.max(0, roundFoodRescueNumber(current - quantity));
      item.quantityDetails = { ...item.quantityDetails, currentQuantity: item.quantity, updatedAt: now };
      item.reservations = (item.reservations || []).map((reservation) => (found.entry.pantryReservationIds || []).includes(reservation.reservationId) ? { ...reservation, status: quantity > 0 ? PANTRY_RESERVATION_STATUSES.CONSUMED : PANTRY_RESERVATION_STATUSES.CANCELLED, updatedAt: now } : reservation);
      item.updatedAt = now;
      item.revision = Number(item.revision || 0) + 1;
      if (item.quantity === 0) item.lifecycle = { ...(item.lifecycle || {}), status: PANTRY_LIFECYCLE_STATUSES.USED, closedAt: now, closureReason: "used-in-meal" };
      if (quantity > 0) {
        events.push(buildFoodEventForPantryCommand({
          commandType: FOOD_EVENT_TYPES.QUANTITY_USED,
          pantryItemId: item.id,
          beforeItem: before,
          afterItem: item,
          source: { sourceType: FOOD_EVENT_SOURCE_TYPES.MEAL_COMPLETION, planId: workflowId, mealId: found.entry.mealId, recipeId: found.entry.recipeId, reservationId: use.reservationId || null },
          idempotencyKey: `${completionKey}:${item.id}:quantity-used:v1`,
          payload: { occurredAt: now, affectsOnHandQuantity: true, affectsReservedQuantity: false, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.DECREASE, amount: quantity, unit: item.quantityDetails.unit || item.unit || use.unit || "each", quantityBefore: current, quantityAfter: item.quantity }
        }));
      }
      (item.reservations || []).filter((reservation) => (found.entry.pantryReservationIds || []).includes(reservation.reservationId)).forEach((reservation) => {
        events.push(buildFoodEventForPantryCommand({
          commandType: reservation.status === PANTRY_RESERVATION_STATUSES.CONSUMED ? FOOD_EVENT_TYPES.RESERVATION_CONSUMED : FOOD_EVENT_TYPES.RESERVATION_CANCELLED,
          pantryItemId: item.id,
          beforeItem: before,
          afterItem: item,
          source: { sourceType: FOOD_EVENT_SOURCE_TYPES.RESERVATION, planId: workflowId, mealId: found.entry.mealId, recipeId: found.entry.recipeId, reservationId: reservation.reservationId },
          idempotencyKey: `${completionKey}:${reservation.reservationId}:${reservation.status}:v1`,
          payload: { occurredAt: now, affectsOnHandQuantity: false, affectsReservedQuantity: true, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.DECREASE, amount: reservation.quantity, unit: reservation.unit }
        }));
      });
    }
    const createdLeftoverBatchIds = [];
    const refrigeratedServings = normalizePantryQuantityValue(actual.leftoverServingsStored, { positive: true });
    if (refrigeratedServings) {
      const batch = createPreparedLeftoverInventoryItem({ entry: found.entry, actual, servings: refrigeratedServings, storageLocation: actual.storageLocation || PANTRY_STORAGE_LOCATIONS.REFRIGERATOR, storageContainer: actual.storageContainer || PANTRY_STORAGE_CONTAINERS.AIRTIGHT_CONTAINER, preservationState: PANTRY_PRESERVATION_STATES.NOT_FROZEN, batchIndex: 0, now });
      if (!batch) return { ok: false, message: "Leftover batch could not be created. Pantry completion was not saved." };
      if (!nextPantry.some((item) => item.id === batch.id)) nextPantry.push(batch);
      createdLeftoverBatchIds.push(batch.id);
      // createLeftoverCreationEvents appends FOOD_EVENT_TYPES.ADDED_TO_LEFTOVER_BATCH for Step 12 compatibility.
      events.push(...createLeftoverCreationEvents(batch, { entry: found.entry, now, idempotencyKey: `${completionKey}:leftover-batch:0:v1` }));
    }
    const frozenServings = normalizePantryQuantityValue(actual.frozenServingsStored, { positive: true });
    if (frozenServings) {
      const batchIndex = createdLeftoverBatchIds.length;
      const batch = createPreparedLeftoverInventoryItem({ entry: found.entry, actual, servings: frozenServings, storageLocation: PANTRY_STORAGE_LOCATIONS.FREEZER, storageContainer: actual.storageContainer || PANTRY_STORAGE_CONTAINERS.FREEZER_BAG, preservationState: PANTRY_PRESERVATION_STATES.FROZEN, batchIndex, now });
      if (!batch) return { ok: false, message: "Frozen leftover batch could not be created. Pantry completion was not saved." };
      if (!nextPantry.some((item) => item.id === batch.id)) nextPantry.push(batch);
      createdLeftoverBatchIds.push(batch.id);
      // createLeftoverCreationEvents appends FOOD_EVENT_TYPES.ADDED_TO_LEFTOVER_BATCH for Step 12 compatibility.
      events.push(...createLeftoverCreationEvents(batch, { entry: found.entry, now, idempotencyKey: `${completionKey}:leftover-batch:${batchIndex}:v1` }));
      events.push(buildFoodEventForPantryCommand({
        commandType: FOOD_EVENT_TYPES.MARKED_FROZEN,
        pantryItemId: batch.id,
        beforeItem: null,
        afterItem: batch,
        source: { sourceType: FOOD_EVENT_SOURCE_TYPES.LEFTOVER_WORKFLOW, planId: workflowId, mealId: found.entry.mealId, recipeId: found.entry.recipeId, leftoverBatchId: batch.id },
        idempotencyKey: `${completionKey}:frozen-servings:v1`,
        payload: { occurredAt: now, affectsOnHandQuantity: false, affectsReservedQuantity: false, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.NONE, amount: frozenServings, unit: "serving", note: "Prepared leftover batch marked frozen after meal completion confirmation." }
      }));
    }
    if (actual.sharedServings > 0) {
      events.push(buildFoodEventForPantryCommand({
        commandType: FOOD_EVENT_TYPES.DONATED_SHARED,
        pantryItemId: found.entry.mealId || workflowId,
        beforeItem: null,
        afterItem: null,
        source: { sourceType: FOOD_EVENT_SOURCE_TYPES.LEFTOVER_WORKFLOW, planId: workflowId, mealId: found.entry.mealId, recipeId: found.entry.recipeId },
        idempotencyKey: `${completionKey}:shared-servings:v1`,
        payload: { occurredAt: now, affectsOnHandQuantity: false, affectsReservedQuantity: false, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.NONE, amount: actual.sharedServings, unit: "serving", note: "Prepared servings recorded as shared after meal completion confirmation." }
      }));
    }
    const pantryResult = commitPantrySnapshotAndFoodEvents(nextPantry, events);
    if (!pantryResult.ok) return { ok: false, message: "Pantry completion could not be saved." };
    updateCookTonightMealEntry(workflowId, (entry) => ({
      ...entry,
      status: COOK_TONIGHT_WORKFLOW_STATUSES.COMPLETED,
      actualOutcome: {
        outcome: actual.outcome,
        servingsPrepared: actual.servingsPrepared,
        servingsEaten: actual.servingsEaten,
        leftoverOutcome: actual.leftoverOutcome,
        leftoverServingsStored: actual.leftoverServingsStored,
        plannedServingAllocation: entry.foodRescuePlan?.portionPreview?.servingAllocation || entry.portionPreview?.servingAllocation || entry.servingAllocation || null,
        frozenOutcome: actual.frozenOutcome,
        frozenServingsStored: actual.frozenServingsStored,
        shareOutcome: actual.shareOutcome,
        sharedServings: actual.sharedServings,
        unallocatedOutcome: actual.unallocatedOutcome,
        leftoverStorageLocation: actual.storageLocation || null,
        leftoverStorageContainer: actual.storageContainer || null,
        leftoverStorageStartedAt: actual.leftoverStorageStartedAt || null,
        leftoverBatchIds: createdLeftoverBatchIds,
        pantryQuantitiesUsed: actual.actualUses,
        completedAt: now,
        completionVersion: COOK_TONIGHT_COMPLETION_VERSION
      }
    }));
    displayPantry();
    displayShoppingList();
    displayWeeklyNutrition();
    return { ok: true };
  }

  function openCookTonightCancelReservation(workflowId, options = {}) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return showToast("Tonight's plan was not found.", "warning");
    renderMealPlanGenerationModal(`<section class="cook-tonight-workflow" aria-labelledby="cookTonightCancelTitle">
      <div class="meal-generation-heading"><span class="eyebrow">${options.choseSomethingElse ? "I CHOSE SOMETHING ELSE" : "CANCEL RESERVATION"}</span><h2 id="cookTonightCancelTitle">Cancel Pantry reservation?</h2><p>Chef Nova will release the reserved Pantry quantities. Pantry on-hand quantities will not be deducted.</p></div>
      <fieldset class="cook-tonight-radio-group">
        <legend>What should happen to tonight's meal?</legend>
        <label><input type="radio" name="cookTonightCancelAction" value="remove" checked> Remove the meal from the calendar</label>
        <label><input type="radio" name="cookTonightCancelAction" value="replace"> Choose another recipe</label>
      </fieldset>
      <div class="meal-generation-actions"><button class="button danger" type="button" data-cook-tonight-cancel-confirm="${escapeHtml(workflowId)}">Cancel Pantry Reservations</button><button class="button secondary" type="button" data-cancel-generated-plan>Go Back</button></div>
    </section>`);
  }

  function confirmCookTonightCancelReservation(workflowId) {
    const found = findCookTonightMeal(workflowId);
    if (!found) return showToast("Tonight's plan was not found.", "warning");
    const result = commitMealCancellation({ date: found.date, mealType: found.mealType, reason: MEAL_CANCELLATION_REASONS.USER_REQUESTED, requestId: workflowId });
    if (!result.ok) return showCookTonightNeedsReview(result.message || "Chef Nova could not release the reservations. No Pantry quantity was deducted.");
    renderMealCancellationResult(result.cancellationRecord, result.releaseSummary);
  }

  function seeOtherFoodRescueRecipes(recipeId) {
    const safeId = window.CSS?.escape ? window.CSS.escape(recipeId) : String(recipeId).replace(/"/g, '\\"');
    const card = document.querySelector(`[data-food-rescue-cook-tonight="${safeId}"]`)?.closest(".recipe-card");
    const list = $("#recipeResults");
    list?.scrollIntoView({ behavior: "smooth", block: "start" });
    card?.focus?.();
    announcePolite("Showing the ranked recipe list with the selected food preserved.", { key: "food-rescue-other-recipes" });
  }

  function findFoodRescueSecondUse(recipeId, rescueSourceId) {
    const ranking = getFoodRescueRankingByRecipeId(recipeId);
    const viewModel = buildFoodRescueCardViewModel(ranking);
    const source = viewModel?.projectedFoodUse.find((item) => item.rescueSourceId === rescueSourceId);
    if (!ranking || !source || !source.canFindSecondUse) return showToast("Chef Nova did not find another eligible search path for this projected remainder.", "warning");
    const originalSource = ranking.usage.sourceUses.find((item) => item.rescueSourceId === rescueSourceId);
    state.foodRescueRankingRequest = createFoodRescueRankingRequest([{
      ...originalSource,
      rescueSourceId,
      displayName: source.foodName,
      availableQuantity: source.projectedRemainingQuantity,
      currentQuantity: source.projectedRemainingQuantity,
      recommendationGoal: "use-projected-remainder",
      sourceRecipeCandidateId: viewModel.candidateId,
      projectedRemainder: { quantity: source.projectedRemainingQuantity, unit: source.unit || originalSource?.unit || "" },
      rescueRecipePriority: { score: originalSource?.rescueRecipePriorityScore || 1, priorityLevel: source.sourcePriorityLevel }
    }], { source: "projected-remainder" });
    state.foodRescueRankingRequest.excludeRecipeId = recipeId;
    navigate("recipes");
    const search = $("#recipeSearch");
    if (search) search.value = source.foodName;
    searchRecipes({ requireIngredients: false, notify: false });
    announcePolite(`Second-use ideas for the projected remaining ${formatQuantityForDisplay(source.projectedRemainingQuantity)} ${source.unit || ""} of ${source.foodName}. These options assume the first recipe uses ${formatQuantityForDisplay(source.projectedUsedQuantity)} ${source.unit || ""}.`, { key: "food-rescue-second-use" });
  }

  function openFoodRescueRemainderFreezeOptions(recipeId, rescueSourceId) {
    const ranking = getFoodRescueRankingByRecipeId(recipeId);
    const viewModel = buildFoodRescueCardViewModel(ranking);
    const source = viewModel?.projectedFoodUse.find((item) => item.rescueSourceId === rescueSourceId);
    const entry = getUseFirstPanelEntryForRescueSource(rescueSourceId);
    if (!source || !entry?.actions?.canViewFreezeOptions) return showToast("Reviewed freezing guidance is not available for this projected remainder.", "warning");
    const modal = $("#useFirstPriorityModal");
    const content = $("#useFirstPriorityModalContent");
    if (!modal || !content) return;
    content.innerHTML = `<div class="instruction-modal-heading">
      <span class="rule-badge">Freeze Options</span>
      <h2 id="useFirstPriorityModalTitle">Freeze options for projected remaining ${escapeHtml(source.foodName)}</h2>
      <p>Chef Nova rechecks the current Pantry lot before showing guidance. Opening this review does not freeze food.</p>
    </div>
    <dl class="use-first-detail-list">
      <div><dt>Projected remainder</dt><dd>${escapeHtml(formatQuantityForDisplay(source.projectedRemainingQuantity))} ${escapeHtml(source.unit || "")}</dd></div>
      <div><dt>Original selected food</dt><dd>${escapeHtml(formatQuantityForDisplay(source.availableQuantity))} ${escapeHtml(source.unit || "")}</dd></div>
      <div><dt>First recipe would use</dt><dd>${escapeHtml(formatQuantityForDisplay(source.projectedUsedQuantity))} ${escapeHtml(source.unit || "")}</dd></div>
      <div><dt>Safety status</dt><dd>${escapeHtml(entry.foodSafety?.decision || "eligible")}</dd></div>
      <div><dt>Freezing</dt><dd>Freezing guidance is reviewed for this current source. Use Pantry controls for any confirmed storage change.</dd></div>
    </dl>
    <p class="field-help">No storage, dates, events, or quantities changed. Only an explicit Pantry confirmation can mark food frozen.</p>
    <button class="button primary" type="button" data-close-use-first-priority>Close</button>`;
    modal.classList.remove("hidden");
    modal.setAttribute("aria-hidden", "false");
    document.body.classList.add("modal-open");
    $("#useFirstPriorityModalClose")?.focus();
  }

  function roundFoodRescueNumber(value) {
    return COST_ENGINE.roundQuantity ? COST_ENGINE.roundQuantity(value) : Math.round((Number(value) + 1e-9) * 100) / 100;
  }

  function displayRecipeResults(results) {
    $("#recipeResults").innerHTML = results.length ? results.map(recipeCard).join("") : emptyRecipeState();
    displayFinderFavorites();
  }

  function findConditionalPantryQuantityMatchesForRecipe(recipe = {}) {
    const recipeIngredients = Array.isArray(recipe.structuredIngredients) && recipe.structuredIngredients.length ? recipe.structuredIngredients : (recipe.ingredients || []).map((ingredient) => ({ displayName: ingredient.name, ingredientId: normalizeIngredient(ingredient.name), quantity: ingredient.quantity, unit: ingredient.unit }));
    return recipeIngredients.flatMap((ingredient) => {
      const ingredientName = ingredient.displayName || ingredient.name || ingredient.ingredientId || "";
      const pantryItem = state.pantry.map(normalizePantryItem).find((item) => {
        const names = [item.ingredientId, item.displayName, item.name, item.originalLabel].filter(Boolean).map(normalizeIngredient);
        return names.includes(normalizeIngredient(ingredientName)) || names.includes(normalizeIngredient(ingredient.ingredientId));
      });
      if (!pantryItem) return [];
      const quantityState = resolvePantryQuantityState(pantryItem);
      if (!quantityState.requiresConfirmation) return [];
      return [{ ingredient, pantryItem, quantityState }];
    });
  }

  function getRecipeDemandTextForQuantityWarning(match, recipe = {}) {
    const name = normalizeIngredient(match?.ingredient?.displayName || match?.ingredient?.name || match?.pantryItem?.displayName || "");
    if (name === "spinach") return "This recipe uses approximately 80 g of spinach per serving.";
    const quantity = normalizePantryQuantityValue(match?.ingredient?.quantity, { positive: true });
    const unit = match?.ingredient?.unit || "";
    const servings = Number(recipe?.servings) || 1;
    if (quantity !== null && servings > 0) return `This recipe uses approximately ${formatQuantityForDisplay(roundFoodRescueNumber(quantity / servings))} ${unit} of ${match.ingredient.displayName || match.ingredient.name} per serving.`;
    return `This recipe uses ${match?.ingredient?.displayName || match?.ingredient?.name || "this ingredient"}, but the exact Pantry amount needs confirmation.`;
  }

  function renderRecipeQuantityConfirmationWarning(recipe = {}) {
    const matches = findConditionalPantryQuantityMatchesForRecipe(recipe);
    if (!matches.length) return "";
    const match = matches[0];
    const recorded = match.quantityState.representation === PANTRY_QUANTITY_REPRESENTATIONS.MEAL_SERVING_CAPACITY
      ? `Enough for approximately ${formatQuantityForDisplay(match.quantityState.mealServingCapacity?.point || 1)} meal ${pluralize(match.quantityState.mealServingCapacity?.point || 1, "serving")}`
      : formatPantryQuantityState(match.quantityState);
    const itemName = match.pantryItem.displayName || match.pantryItem.name || match.ingredient.displayName || "this ingredient";
    return `<section class="quantity-condition-warning" aria-label="Quantity confirmation needed for ${escapeHtml(itemName)}">
      <span class="quantity-review-badge">QUANTITY CONFIRMATION NEEDED</span>
      <p>${escapeHtml(getRecipeDemandTextForQuantityWarning(match, recipe))}</p>
      <p>Your Pantry currently records:</p>
      <p><b>${escapeHtml(recorded)}</b></p>
      <p>Before this meal is saved, confirm whether the available amount can cover the selected recipe quantity.</p>
      <div class="quantity-condition-actions">
        <button class="button primary small" type="button" data-demand-confirm-enough="${escapeHtml(match.pantryItem.id)}" data-demand-recipe="${escapeHtml(recipe.id)}">Yes, I Have Enough for This Recipe</button>
        <button class="button secondary small" type="button" data-confirm-pantry-quantity="${escapeHtml(match.pantryItem.id)}">Enter an Approximate Amount</button>
        <button class="button secondary small" type="button" data-add-missing="${escapeHtml(recipe.id)}">Add ${escapeHtml(itemName)} to the Shopping List</button>
        <button class="button secondary small" type="button" data-clear-recipe-search>Choose Another Recipe</button>
      </div>
    </section>`;
  }

  function getRecipeFefoPackageAllocationSummaries(recipe = {}) {
    const ingredients = Array.isArray(recipe.structuredIngredients) && recipe.structuredIngredients.length ? recipe.structuredIngredients : (recipe.ingredients || []).map((ingredient, index) => ({ ingredientId: normalizeIngredient(ingredient.name), displayName: ingredient.name, quantity: ingredient.quantity, unit: ingredient.unit, occurrenceIndex: index }));
    return ingredients.map((ingredient, index) => {
      const requiredQuantity = normalizePantryQuantityValue(ingredient.quantity, { positive: true });
      if (requiredQuantity === null) return null;
      const canonicalIngredientId = ingredient.ingredientId || normalizeIngredient(ingredient.displayName || ingredient.name);
      const matchingPackages = state.pantry.map(normalizePantryItem).filter((item) => {
        const keys = [item.ingredientId, normalizeIngredient(item.displayName), normalizeIngredient(item.name)].filter(Boolean);
        return keys.includes(normalizeIngredient(canonicalIngredientId)) || keys.includes(normalizeIngredient(ingredient.displayName || ingredient.name));
      });
      if (!matchingPackages.length) return null;
      const decision = createFefoAllocationDecision({
        ingredientDemandId: `recipe-preview::${recipe.id}::${canonicalIngredientId || index}`,
        mealId: `recipe-preview::${recipe.id}`,
        targetMealDate: getCurrentDateString(),
        canonicalIngredientId,
        requiredQuantity,
        unit: normalizePantryUnit(ingredient.unit) || ingredient.unit || "",
        requiredForm: ingredient.form || "",
        packageItems: matchingPackages,
        requestId: "recipe-card-preview"
      });
      return decision.packageOrder.length || decision.excludedPackages.length ? { ingredient, decision } : null;
    }).filter(Boolean);
  }

  function renderRecipeFefoPackageAllocationSummary(recipe = {}) {
    const summaries = getRecipeFefoPackageAllocationSummaries(recipe).filter((summary) => summary.decision.packageOrder.length);
    if (!summaries.length) return "";
    return `<section class="recipe-package-allocation-summary" aria-label="Package-level Pantry allocation preview">
      ${summaries.slice(0, 2).map(({ ingredient, decision }) => {
        const name = ingredient.displayName || ingredient.name || getIngredientDisplayNameById(decision.canonicalIngredientId, "Ingredient");
        const firstAllocation = decision.packageOrder[0];
        const coverageStatus = decision.missingQuantity > 0 ? "Partial coverage" : decision.packageOrder.some((row) => row.remainingQuantityRepresentation !== PANTRY_QUANTITY_REPRESENTATIONS.EXACT_NUMERIC) ? "Estimated coverage" : "Exact coverage";
        const purchasePackageQuantity = firstAllocation?.originalPackageQuantity || null;
        const packagesRequired = decision.missingQuantity > 0 && purchasePackageQuantity ? Math.max(1, Math.ceil(decision.missingQuantity / purchasePackageQuantity)) : decision.missingQuantity > 0 ? 1 : 0;
        const plannedUseValue = firstAllocation ? calculatePartialPackageCurrentValue(firstAllocation.item || state.pantry.find((item) => item.id === firstAllocation.pantryItemId), firstAllocation.allocatedQuantity) : null;
        return `<article>
          <h4>${escapeHtml(name.toUpperCase())} ALLOCATION</h4>
          <p><b>Recipe requirement:</b> ${escapeHtml(formatShoppingQuantity(decision.requiredQuantity, decision.unit))}</p>
          ${firstAllocation ? `<p><b>Current package:</b> ${escapeHtml(formatEstimatedAwareQuantity(firstAllocation.currentRemainingQuantity, firstAllocation.unit, firstAllocation.quantityConfidence))} remaining</p>` : ""}
          <p><b>Planned Pantry use:</b></p>
          <ul>
            ${decision.packageOrder.map((row) => `<li>${escapeHtml(row.packageLabel)} — ${escapeHtml(formatEstimatedAwareQuantity(row.allocatedQuantity, row.unit, row.quantityConfidence))} planned<br><span>Original package size: ${escapeHtml(row.originalPackageQuantity ? formatShoppingQuantity(row.originalPackageQuantity, row.originalPackageUnit || row.unit) : "Not recorded")}</span><br><span>Expected package remainder: ${escapeHtml(formatEstimatedAwareQuantity(row.plannedRemainingQuantity, row.unit, row.quantityConfidence))}</span><br><span>${escapeHtml(row.packageState === PACKAGE_PHYSICAL_STATES.OPENED ? "Opened" : row.packageState === PACKAGE_PHYSICAL_STATES.UNOPENED ? "Unopened" : row.packageState.replace(/-/g, " "))}</span><br><span>${escapeHtml(row.dateLabel)}</span></li>`).join("")}
          </ul>
          <p><b>Coverage status:</b> ${escapeHtml(coverageStatus)}</p>
          <p><b>Estimated missing quantity:</b> ${decision.missingQuantity > 0 ? escapeHtml(formatEstimatedAwareQuantity(decision.missingQuantity, decision.unit, firstAllocation?.quantityConfidence || REMAINING_QUANTITY_CONFIDENCE.USER_ESTIMATED)) : "None"}</p>
          <p><b>New ${escapeHtml(name.toLowerCase())} purchase:</b> ${decision.missingQuantity > 0 ? escapeHtml(formatEstimatedAwareQuantity(decision.missingQuantity, decision.unit, firstAllocation?.quantityConfidence || REMAINING_QUANTITY_CONFIDENCE.USER_ESTIMATED)) : "None"}</p>
          <p><b>Suggested purchase:</b> ${packagesRequired > 0 ? `${escapeHtml(String(packagesRequired))} compatible ${pluralize(packagesRequired, "package")}` : "None"}</p>
          ${plannedUseValue?.available ? `<p><b>Ingredient-use value:</b> ${escapeHtml(`${firstAllocation?.quantityConfidence === REMAINING_QUANTITY_CONFIDENCE.MEASURED ? "" : "Approximately "}${formatCurrencyFromCents(plannedUseValue.valueCents)}`)}</p>` : ""}
          <p class="package-use-first-reason">Chef Nova is using the recorded remaining quantity, not the original package size. Preview only. Pantry quantities remain unchanged until cooking is confirmed.</p>
        </article>`;
      }).join("")}
    </section>`;
  }

  function recipeCard(recipe, favoriteView = false, presentationContext = {}) {
    if (presentationContext?.presentationMode === "leftover-transformation") return renderSharedRecipeCardWithTransformation(recipe, presentationContext.transformation);
    const saved = isRecipeFavorite(recipe.id);
    const warnings = getRecipeAllergies(recipe);
    const hasUserAllergy = recipeContainsUserAllergy(recipe);
    const preference = getUserDietaryPreference();
    const preferenceMatch = preference && recipe.dietaryTags.some((tag) => normalizeIngredient(tag) === normalizeIngredient(preference));
    const context = buildPersonalizedRecipeContext();
    const nutritionTags = getRecipeCardNutritionTags(recipe, getSelectedPersonalizedRecipeFilters());
    const match = calculatePersonalizedRecipeScore(recipe, context);
    const reasons = buildRecipeMatchReasons(recipe, context, getSelectedPersonalizedRecipeFilters()).slice(0, 3);
    return `<article class="recipe-card expanded">
      <div class="recipe-image placeholder">
        <span>${escapeHtml(recipe.imagePlaceholder || recipe.name)}</span>
        <button class="favorite-button ${saved ? "saved" : ""}" data-favorite="${recipe.id}" aria-label="${saved ? "Remove from" : "Add to"} favorites">${saved ? "♥" : "♡"}</button>
      </div>
      <div class="recipe-body">
        <div class="recipe-card-topline">
          <span class="match-badge ${matchClass(recipe.matchPercentage)}">${recipe.matchPercentage}%</span>
          <span class="match-level">${escapeHtml(recipe.matchLevel)}</span>
          ${hasUserAllergy ? `<span class="allergy-badge">Allergy warning</span>` : ""}
          ${preferenceMatch ? `<span class="dietary-badge">Matches your preference</span>` : ""}
        </div>
        <h3>${escapeHtml(recipe.name)}</h3>
        <div class="recipe-meta"><span>${escapeHtml(recipe.category)}</span><span>${escapeHtml(recipe.cuisine)}</span><span>◷ ${recipe.cookingTime} min</span><span>${escapeHtml(recipe.difficulty)}</span><span>${formatRecipeNutritionValue(recipe.calories, "calories")}</span><span>${formatRecipeNutritionValue(recipe.protein, "g")} protein</span></div>
        ${renderRecipeCardCostSummary(recipe, { cardContext: RECIPE_CARD_CONTEXTS.STANDALONE_RECIPE, selectedServings: recipe.servings || 1 })}
        ${renderFoodRescueRecipeSummary(recipe)}
        ${renderRecipeQuantityConfirmationWarning(recipe)}
        ${renderRecipeFefoPackageAllocationSummary(recipe)}
        ${nutritionTags.length ? `<div class="recipe-nutrition-tags">${nutritionTags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}</div>` : ""}
        ${reasons.length ? `<div class="recipe-match-reasons"><b>${escapeHtml(getPersonalizedMatchLabel(match.total))}</b><ul>${reasons.map((reason) => `<li>${escapeHtml(reason)}</li>`).join("")}</ul></div>` : ""}
        <div class="ingredient-block"><b>Ingredients you have</b><div class="ingredient-tags matched-tags">${recipe.matchedIngredients.length ? recipe.matchedIngredients.map((i) => `<span>${escapeHtml(i.name)}</span>`).join("") : `<span>Search to match ingredients</span>`}</div></div>
        <div class="ingredient-block"><b>Missing ingredients</b><div class="ingredient-tags missing-tags">${recipe.missingIngredients.length ? recipe.missingIngredients.slice(0, 5).map((i) => `<span>${escapeHtml(i.name)}</span>`).join("") : `<span>None</span>`}</div></div>
        <div class="ingredient-block"><b>Optional ingredients</b><div class="ingredient-tags">${recipe.optionalIngredients.length ? recipe.optionalIngredients.slice(0, 4).map((i) => `<span>${escapeHtml(i.name)}</span>`).join("") : `<span>None</span>`}</div></div>
        <div class="dietary-tags">${recipe.dietaryTags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}</div>
        <div class="allergy-warning"><b>Allergy warnings:</b> ${warnings.map(escapeHtml).join(", ")}. Check ingredient labels and confirm dietary suitability before cooking.</div>
        <div class="recipe-card-actions">
          <button class="button primary small" data-recipe-details="${recipe.id}">View Details</button>
          <button class="button secondary small" type="button" data-offline-download="${recipe.id}">Download Offline</button>
          <button class="button secondary small" type="button" data-cook-before-recipe="${recipe.id}">Use Food That Needs Attention</button>
          <button class="button secondary small" data-add-missing="${recipe.id}">Add Missing Ingredients to Shopping List</button>
          ${favoriteView ? `<button class="button secondary small remove-favorite-button" data-remove-favorite="${recipe.id}">Remove favorite</button>` : ""}
        </div>
      </div>
    </article>`;
  }

  function renderSharedRecipeCardWithTransformation(recipe, transformation) {
    const warnings = getRecipeAllergies(recipe);
    return `<article class="recipe-card expanded leftover-transformation-recipe-card" data-transformation-card-version="${LEFTOVER_TRANSFORMATION_CARD_VERSION}" aria-labelledby="${escapeHtml(transformation.candidateId)}Title">
      <div class="recipe-image placeholder">
        <span>${escapeHtml(recipe.imagePlaceholder || recipe.name)}</span>
      </div>
      <div class="recipe-body">
        <div class="recipe-card-topline">
          <span class="match-badge high">${escapeHtml(String(transformation.score.value))}</span>
          <span class="match-level">${escapeHtml(useFirstPriorityLevelLabel(transformation.score.level))} transformation option</span>
        </div>
        <h3 id="${escapeHtml(transformation.candidateId)}Title">${escapeHtml(recipe.name)}</h3>
        <div class="recipe-meta"><span>${escapeHtml(recipe.category)}</span><span>${escapeHtml(transformation.cookingSummary.methodLabel)}</span><span>${transformation.cookingSummary.totalTimeMinutes === null ? "Time needs review" : `${escapeHtml(String(transformation.cookingSummary.totalTimeMinutes))} min`}</span><span>Serves ${escapeHtml(String(transformation.servingSummary.peopleEating || transformation.servingSummary.effectiveYield || recipe.servings || 1))}</span></div>
        ${renderLeftoverTransformationRecipeSection(transformation)}
        <div class="allergy-warning"><b>Allergy warnings:</b> ${warnings.map(escapeHtml).join(", ")}. Check ingredient labels and confirm dietary suitability before cooking.</div>
      </div>
    </article>`;
  }

  function renderLeftoverTransformationRecipeSection(card) {
    const useAll = Number(card.sourceUse.sourceCoverage) >= 0.98;
    const sourceUse = card.sourceUse.projectedServings !== null
      ? `${formatQuantityForDisplay(card.sourceUse.projectedServings)} ${pluralize(card.sourceUse.projectedServings, "serving")}, approximately ${formatShoppingQuantity(card.sourceUse.projectedQuantity, card.sourceUse.unit)}`
      : `${formatShoppingQuantity(card.sourceUse.projectedQuantity, card.sourceUse.unit)} of ${formatShoppingQuantity(card.sourceUse.availableQuantity, card.sourceUse.unit)}`;
    const remaining = card.sourceUse.projectedRemainingServings !== null
      ? `${formatQuantityForDisplay(card.sourceUse.projectedRemainingServings)} ${pluralize(card.sourceUse.projectedRemainingServings, "serving")}`
      : formatShoppingQuantity(card.sourceUse.projectedRemainingQuantity, card.sourceUse.unit);
    const groceries = formatTransformationGrocerySummary(card.purchaseSummary);
    const cost = card.purchaseSummary.unpricedPurchaseGroupCount > 0 || card.purchaseSummary.costStatus === "incomplete" ? `<span class="food-rescue-incomplete-cost">Incomplete estimate</span><small>${escapeHtml(numberWord(card.purchaseSummary.unpricedPurchaseGroupCount || 1))} required grocery price still needs confirmation.</small>` : escapeHtml(formatCurrencyFromCents(card.purchaseSummary.marginalPurchaseCostCents || 0));
    const meaningfulPriority = card.otherPriorityFoodUse.filter((item) => item.meaningfulUse);
    return `<section class="leftover-transformation-card-section" aria-label="Leftover transformation planning estimate">
      <p class="leftover-timeline-warning">Originally cooked ${card.timelineSummary.originalCookedAt ? escapeHtml(formatTimelineEventRelative(card.timelineSummary.originalCookedAt)) : "at a time that needs review"}. Transforming this leftover will not automatically extend its recorded storage window.</p>
      <dl class="leftover-transformation-metrics">
        <div><dt>Would use</dt><dd>${useAll ? "Uses all currently available leftover quantity" : escapeHtml(sourceUse)}</dd></div>
        <div><dt>Projected source use</dt><dd>Approximately ${escapeHtml(String(formatFoodRescuePercent(card.sourceUse.sourceCoverage)))}%</dd></div>
        <div><dt>Projected quantity remaining</dt><dd>${escapeHtml(remaining)}</dd></div>
        <div><dt>Cooking time</dt><dd>${card.cookingSummary.totalTimeMinutes === null ? "Needs review" : `${escapeHtml(String(card.cookingSummary.totalTimeMinutes))} minutes`}</dd></div>
        <div><dt>Suggested servings</dt><dd>${escapeHtml(String(card.servingSummary.peopleEating || card.servingSummary.effectiveYield))}</dd></div>
        <div><dt>Target unallocated servings</dt><dd>${escapeHtml(String(card.servingSummary.unallocatedServings || 0))}</dd></div>
        <div><dt>Pantry coverage</dt><dd>${escapeHtml(String(formatFoodRescuePercent(card.pantrySummary.pantryCoverage)))}%</dd></div>
        <div><dt>New groceries</dt><dd>${groceries}</dd></div>
        <div><dt>Estimated additional checkout cost</dt><dd>${cost}</dd></div>
      </dl>
      ${meaningfulPriority.length ? `<div class="leftover-other-priority-food"><h4>Also Uses</h4><ul>${meaningfulPriority.map((item) => `<li><b>${escapeHtml(item.displayName)}</b><span>${escapeHtml(formatShoppingQuantity(item.projectedUsedQuantity, item.unit))} of ${escapeHtml(formatShoppingQuantity(item.availableQuantity, item.unit))}</span><small>${escapeHtml(useFirstPriorityLevelLabel(item.priorityLevel))} use-first priority</small></li>`).join("")}</ul><p>Also uses ${escapeHtml(meaningfulPriority.map((item) => item.displayName.toLowerCase()).join(" and "))} that need attention.</p></div>` : `<p class="field-help">Uses the leftover efficiently.</p>`}
      <div class="food-rescue-explanation"><h4>Why Chef Nova recommends this</h4><p>${escapeHtml(card.explanation.summary)}</p></div>
      <div class="food-rescue-actions">
        ${card.actions.canAddToTonight ? `<button class="button primary small" type="button" data-leftover-transform-use="${escapeHtml(`transformation-path::${card.sourceLeftoverBatchId}::${card.recipeId}::1`)}" aria-label="Plan ${escapeHtml(card.recipe.displayName)} for tonight using ${escapeHtml(sourceUse)}">Add to Tonight</button>` : ""}
        ${card.actions.canPlanForAnotherMeal ? `<button class="button primary small" type="button" data-leftover-transform-use="${escapeHtml(`transformation-path::${card.sourceLeftoverBatchId}::${card.recipeId}::1`)}" aria-label="Plan ${escapeHtml(card.recipe.displayName)} for another meal using ${escapeHtml(sourceUse)}">Plan for Another Meal</button>` : ""}
        <button class="button secondary small" type="button" data-leftover-transform-details="${escapeHtml(`transformation-path::${card.sourceLeftoverBatchId}::${card.recipeId}::1`)}" aria-label="View transformation details for ${escapeHtml(card.recipe.displayName)}">View Details</button>
        ${card.actions.canFindAnotherUse ? `<button class="button secondary small" type="button" data-leftover-find-another-use="${escapeHtml(card.candidateId)}" aria-label="Find another use for the projected remaining ${escapeHtml(remaining)}">Find Another Use</button>` : ""}
      </div>
    </section>`;
  }

  function formatTransformationGrocerySummary(purchaseSummary) {
    const names = purchaseSummary.newPurchaseGroupNames || [];
    if (!purchaseSummary.newPurchaseGroupCount) return "None";
    if (names.length === 1) return escapeHtml(names[0]);
    if (names.length === 2) return `${escapeHtml(names[0])} and ${escapeHtml(names[1])}`;
    return `${escapeHtml(String(purchaseSummary.newPurchaseGroupCount))} purchase groups`;
  }

  function buildPersonalizedRecipeContext() {
    const profile = getCurrentNutritionProfile();
    const safety = evaluateNutritionSafety(profile);
    const target = safety.canGeneratePersonalizedNutrition && !safety.disableEnergyRecommendations && !safety.disableMacroRecommendations ? getCurrentDailyNutritionTarget(profile) : null;
    const weeklyRange = target ? buildEstimatedWeeklyNutritionRange(target) : null;
    const weeklyData = getCurrentWeeklyNutritionData();
    const remaining = weeklyRange && weeklyData?.plannedTotals ? calculateRemainingPlannedNutrition(weeklyData.plannedTotals, weeklyRange) : null;
    return {
      profile,
      safety,
      userProfile: state.currentUser,
      target,
      weeklyRange,
      weeklyData,
      coverage: weeklyData?.coverage || null,
      remaining,
      pantryItems: getActivePantryItems(),
      goal: profile?.goal || null,
      workoutProfile: profile?.workoutProfile || null
    };
  }

  function getCurrentWeeklyNutritionData() {
    const summary = getWeeklyNutritionSummary();
    return {
      plannedTotals: {
        calories: summary.totalCalories,
        protein: summary.totalProtein,
        carbohydrates: summary.totalCarbohydrates,
        fat: summary.totalFat
      },
      plannedMeals: summary.plannedMeals,
      mealsWithNutritionData: summary.mealsWithNutrition,
      coverage: calculateNutritionDataCoverage(summary.mealsWithNutrition, summary.plannedMeals)
    };
  }

  function calculateRemainingPlannedNutrition(plannedTotals, weeklyRange) {
    if (!plannedTotals || !weeklyRange) return null;
    const createRemainingItem = (planned, minimum, maximum) => {
      if (!Number.isFinite(planned) || !Number.isFinite(minimum) || !Number.isFinite(maximum)) return null;
      return {
        planned: Math.max(0, planned),
        estimatedMinimum: minimum,
        estimatedMaximum: maximum,
        remainingToMinimum: Math.max(0, minimum - planned),
        remainingToMaximum: Math.max(0, maximum - planned)
      };
    };
    return {
      calories: createRemainingItem(plannedTotals.calories, weeklyRange.calories.minimum, weeklyRange.calories.maximum),
      protein: createRemainingItem(plannedTotals.protein, weeklyRange.protein.minimum, weeklyRange.protein.maximum),
      carbohydrates: createRemainingItem(plannedTotals.carbohydrates, weeklyRange.carbohydrates.minimum, weeklyRange.carbohydrates.maximum),
      fat: createRemainingItem(plannedTotals.fat, weeklyRange.fat.minimum, weeklyRange.fat.maximum)
    };
  }

  function hasUsefulRemainingNutritionContext(context) {
    const coverage = context?.coverage;
    if (!context?.target) return false;
    if (!context?.weeklyData?.plannedMeals) return true;
    return coverage?.percentage >= MINIMUM_WEEKLY_NUTRITION_DATA_COVERAGE && coverage?.mealsWithNutritionData >= MINIMUM_MEALS_WITH_NUTRITION_DATA;
  }

  function calculateRecipeNutritionFitScore(recipe, context = buildPersonalizedRecipeContext()) {
    const nutrition = getRecipeNutritionForServings(recipe, 1);
    if (!hasValidCoreRecipeNutrition(nutrition) || !context?.target) return { available: false, total: 0, reasons: [] };
    const reasons = [];
    let total = 0;
    const dailyRange = {
      calories: { minimum: context.target.calorieMin, maximum: context.target.calorieMax },
      protein: { minimum: context.target.proteinMin, maximum: context.target.proteinMax },
      carbohydrates: { minimum: context.target.carbohydrateMin, maximum: context.target.carbohydrateMax },
      fat: { minimum: context.target.fatMin, maximum: context.target.fatMax }
    };
    const plannedMeals = Number(context.weeklyData?.plannedMeals) || 0;
    const useRemaining = plannedMeals > 0 && hasUsefulRemainingNutritionContext(context);
    const scoreAgainstRange = (amount, range, weight, idealMinimumRatio = 0.12, idealMaximumRatio = 0.35) => {
      if (!Number.isFinite(amount) || !range) return 0;
      const ratio = amount / range.maximum;
      if (ratio < idealMinimumRatio) return Math.round(weight * (ratio / idealMinimumRatio) * 0.75);
      if (ratio <= idealMaximumRatio) return weight;
      return Math.max(0, Math.round(weight * (1 - Math.min(0.75, ratio - idealMaximumRatio))));
    };
    if (useRemaining && context.remaining?.protein?.remainingToMinimum > 0 && nutrition.protein >= 15) {
      total += 25;
      reasons.push("May support your planned protein range");
    } else {
      total += scoreAgainstRange(nutrition.protein, dailyRange.protein, 25, 0.12, 0.4);
    }
    if (useRemaining && context.remaining?.carbohydrates?.remainingToMinimum > 0 && nutrition.carbohydrates >= 25) total += 20;
    else total += scoreAgainstRange(nutrition.carbohydrates, dailyRange.carbohydrates, 20, 0.12, 0.4);
    total += scoreAgainstRange(nutrition.fat, dailyRange.fat, 15, 0.08, 0.38);
    total += scoreAgainstRange(nutrition.calories, dailyRange.calories, 15, 0.12, 0.38);
    if (isVegetableRichRecipe(recipe) || isHigherFibreRecipe(recipe)) {
      total += 15;
      reasons.push("Includes vegetables or fibre");
    } else if (hasMeaningfulProduce(recipe, nutrition)) total += 8;
    const goalScore = calculateRecipeGoalScore(recipe, context);
    total += Math.round(goalScore * 0.1);
    if (goalScore >= 70 && context.goal === "support-workouts") reasons.push("Supports your workout preference");
    return {
      available: true,
      total: Math.min(100, Math.max(0, Math.round(total))),
      reasons: Array.from(new Set(reasons)).slice(0, 3)
    };
  }

  function doesRecipeFitNutritionRange(recipe, context) {
    const score = calculateRecipeNutritionFitScore(recipe, context);
    return score.available && score.total >= MINIMUM_RECIPE_NUTRITION_FIT_SCORE;
  }

  function hasValidCoreRecipeNutrition(nutrition) {
    return ["calories", "protein", "carbohydrates", "fat"].every((field) => Number.isFinite(nutrition?.[field]) && nutrition[field] >= 0);
  }

  function isHigherProteinRecipe(recipe) {
    const nutrition = getRecipeNutritionForServings(recipe, 1);
    return Number.isFinite(nutrition.protein) && nutrition.protein >= RECIPE_NUTRITION_TAG_RULES.higherProteinGrams;
  }

  function isBalancedMealRecipe(recipe) {
    const nutrition = getRecipeNutritionForServings(recipe, 1);
    return Number.isFinite(nutrition.protein) && nutrition.protein >= 15 && Number.isFinite(nutrition.carbohydrates) && nutrition.carbohydrates >= 25 && Number.isFinite(nutrition.fat) && nutrition.fat > 0 && hasMeaningfulProduce(recipe, nutrition);
  }

  function isWorkoutFriendlyRecipe(recipe, context = buildPersonalizedRecipeContext()) {
    const nutrition = getRecipeNutritionForServings(recipe, 1);
    if (!hasValidCoreRecipeNutrition(nutrition)) return false;
    const trainingFocus = context?.workoutProfile?.trainingFocus || null;
    if (trainingFocus === "strength-training") return nutrition.protein >= 25 && nutrition.carbohydrates >= 25;
    if (trainingFocus === "endurance" || trainingFocus === "team-sport") return nutrition.carbohydrates >= 40 && nutrition.protein >= 10;
    if (trainingFocus === "mixed-training") return nutrition.protein >= 15 && nutrition.carbohydrates >= 30;
    return isBalancedMealRecipe(recipe);
  }

  function isVegetableRichRecipe(recipe) {
    const nutrition = getRecipeNutritionForServings(recipe, 1);
    return Number.isFinite(nutrition.vegetableServings) && nutrition.vegetableServings >= RECIPE_NUTRITION_TAG_RULES.vegetableRichServings;
  }

  function isHigherFibreRecipe(recipe) {
    const nutrition = getRecipeNutritionForServings(recipe, 1);
    return Number.isFinite(nutrition.fibre) && nutrition.fibre >= RECIPE_NUTRITION_TAG_RULES.higherFibreGrams;
  }

  function isLowerAddedSugarRecipe(recipe) {
    const nutrition = getRecipeNutritionForServings(recipe, 1);
    return Number.isFinite(nutrition.addedSugar) && nutrition.addedSugar <= RECIPE_NUTRITION_TAG_RULES.lowerAddedSugarGrams;
  }

  function isQuickMealRecipe(recipe) {
    const minutes = getRecipeTotalMinutes(recipe);
    return Number.isFinite(minutes) && minutes <= QUICK_MEAL_MAX_MINUTES;
  }

  function getRecipeTotalMinutes(recipe) {
    if (Number.isFinite(recipe?.totalTime)) return recipe.totalTime;
    const prep = Number.isFinite(recipe?.prepTime) ? recipe.prepTime : Number.isFinite(recipe?.preparationTime) ? recipe.preparationTime : 0;
    const cook = Number.isFinite(recipe?.cookTime) ? recipe.cookTime : Number.isFinite(recipe?.cookingTime) ? recipe.cookingTime : 0;
    const total = prep + cook;
    return total > 0 ? total : null;
  }

  function hasMeaningfulProduce(recipe, nutrition = getRecipeNutritionForServings(recipe, 1)) {
    if (Number.isFinite(nutrition.vegetableServings) && nutrition.vegetableServings >= 1) return true;
    const produceTerms = ["apple", "banana", "berries", "berry", "mango", "tomato", "lettuce", "romaine", "spinach", "cucumber", "carrot", "carrots", "broccoli", "peas", "celery", "onion", "avocado", "cabbage", "bell pepper", "mushrooms", "green beans", "sweet potato"];
    const ingredients = normalizeIngredientList(recipe?.ingredients || []).map((ingredient) => normalizeIngredient(ingredient.name));
    return ingredients.some((ingredient) => produceTerms.some((term) => ingredient === term || ingredient.includes(term)));
  }

  function calculatePantryMatch(recipe, pantryItems = []) {
    const requiredIngredients = normalizeIngredientList(recipe?.ingredients || []).map((ingredient) => ingredient.name).filter(Boolean);
    if (!requiredIngredients.length) return { available: false, matched: 0, total: 0, percentage: 0, missing: [] };
    const pantryNames = pantryItems.map((item) => normalizeIngredient(item?.name || item)).filter(Boolean);
    const matchedIngredients = requiredIngredients.filter((ingredient) => pantryNames.some((pantryName) => ingredientsMatch(pantryName, ingredient)));
    const missingIngredients = requiredIngredients.filter((ingredient) => !matchedIngredients.some((matched) => normalizeIngredient(matched) === normalizeIngredient(ingredient)));
    return {
      available: true,
      matched: matchedIngredients.length,
      total: requiredIngredients.length,
      percentage: Math.round((matchedIngredients.length / requiredIngredients.length) * 100),
      missing: missingIngredients
    };
  }

  function calculateRecipeTimeScore(recipe) {
    const minutes = getRecipeTotalMinutes(recipe);
    if (!Number.isFinite(minutes)) return 0;
    if (minutes <= 15) return 100;
    if (minutes <= QUICK_MEAL_MAX_MINUTES) return 85;
    if (minutes <= 45) return 60;
    if (minutes <= 60) return 35;
    return 15;
  }

  function calculateRecipeGoalScore(recipe, context = buildPersonalizedRecipeContext()) {
    const nutrition = getRecipeNutritionForServings(recipe, 1);
    if (!hasValidCoreRecipeNutrition(nutrition)) return 0;
    if (context?.safety?.disableGoalAdjustments || context?.safety?.useMaintenancePlanning) return isBalancedMealRecipe(recipe) ? 55 : hasMeaningfulProduce(recipe, nutrition) ? 35 : 20;
    const goal = context?.goal || "prefer-not-to-choose";
    if (goal === "build-muscle") return (isHigherProteinRecipe(recipe) ? 55 : 0) + (nutrition.carbohydrates >= 25 ? 35 : 0) + (hasMeaningfulProduce(recipe, nutrition) ? 10 : 0);
    if (goal === "improve-eating-habits") return (isVegetableRichRecipe(recipe) ? 45 : 0) + (isHigherFibreRecipe(recipe) ? 30 : 0) + (isBalancedMealRecipe(recipe) ? 25 : 0);
    if (goal === "support-workouts") return isWorkoutFriendlyRecipe(recipe, context) ? 90 : calculateRecipeTimeScore(recipe) * 0.25;
    if (goal === "maintain-current-weight" || goal === "gradual-weight-change") return isBalancedMealRecipe(recipe) ? 80 : hasMeaningfulProduce(recipe, nutrition) ? 45 : 25;
    return isBalancedMealRecipe(recipe) ? 55 : 25;
  }

  function calculateRecipeVarietyScore(recipe) {
    const plannedRecipes = Object.values(getSavedMealPlan()).flatMap((day) => Object.values(day || {})).map((entry) => normalizeIngredient(normalizeMealPlanEntry(entry)?.recipeName || "")).filter(Boolean);
    const categoryRepeats = state.recipes.filter((candidate) => candidate.category === recipe.category).length;
    let score = 70;
    if (!plannedRecipes.includes(normalizeIngredient(recipe.name))) score += 20;
    if (categoryRepeats <= 5) score += 10;
    return Math.min(100, score);
  }

  function calculatePersonalizedRecipeScore(recipe, context = buildPersonalizedRecipeContext()) {
    let score = 0;
    const reasons = [];
    const nutritionFit = calculateRecipeNutritionFitScore(recipe, context);
    if (nutritionFit.available) {
      score += nutritionFit.total * 0.35;
      reasons.push(...nutritionFit.reasons);
    }
    const pantryMatch = calculatePantryMatch(recipe, context.pantryItems || []);
    if (pantryMatch.available) score += pantryMatch.percentage * 0.25;
    score += calculateRecipeTimeScore(recipe, context) * 0.15;
    score += calculateRecipeGoalScore(recipe, context) * 0.15;
    score += calculateRecipeVarietyScore(recipe, context) * 0.10;
    return {
      total: Math.round(Math.max(0, Math.min(100, score))),
      reasons: Array.from(new Set(reasons)).slice(0, 3)
    };
  }

  function scoreRecipeForUser(recipe, context = buildPersonalizedRecipeContext()) {
    return calculatePersonalizedRecipeScore(recipe, context);
  }

  function getPersonalizedFilterAvailability(filterValue, context = buildPersonalizedRecipeContext()) {
    if (filterValue === PERSONALIZED_RECIPE_FILTERS.FITS_NUTRITION_RANGE) {
      return {
        enabled: Boolean(context?.target) && context?.safety?.canGeneratePersonalizedNutrition !== false,
        reason: context?.target && context?.safety?.canGeneratePersonalizedNutrition !== false ? null : "Personalized nutrition estimates unavailable. Chef Nova will continue providing recipe browsing and balanced meal-planning tools."
      };
    }
    if (filterValue === PERSONALIZED_RECIPE_FILTERS.WORKOUT_FRIENDLY) {
      return {
        enabled: true,
        reason: context?.goal === "support-workouts" ? null : "Workout-friendly suggestions are most personalized when Support my workouts is selected in the Nutrition Profile."
      };
    }
    return { enabled: true, reason: null };
  }

  function updatePersonalizedRecipeFilterAvailability(context = buildPersonalizedRecipeContext()) {
    const messages = [...(context?.safety?.notices || [])];
    $$("[data-personalized-recipe-filter]").forEach((input) => {
      const availability = getPersonalizedFilterAvailability(input.value, context);
      input.disabled = !availability.enabled;
      input.closest("label")?.classList.toggle("disabled", !availability.enabled);
      if (!availability.enabled) input.checked = false;
      if (availability.reason) messages.push(availability.reason);
    });
    const selected = getSelectedPersonalizedRecipeFilters();
    if (selected.includes(PERSONALIZED_RECIPE_FILTERS.FITS_NUTRITION_RANGE)) {
      if (!context.weeklyData?.plannedMeals) messages.push("No planned meals are available for a remaining-nutrition comparison. Recipes are being compared with your general estimated daily range instead.");
      else if (!hasUsefulRemainingNutritionContext(context)) messages.push("Not enough meal data for a personalized nutrition-range filter.");
    }
    if (selected.includes(PERSONALIZED_RECIPE_FILTERS.LOWER_ADDED_SUGAR)) messages.push("Some recipes are not shown because added-sugar information is unavailable.");
    if (selected.includes(PERSONALIZED_RECIPE_FILTERS.HIGHER_FIBRE)) messages.push("Some recipes could not be evaluated because nutrition information was unavailable.");
    const profileAge = Number(context.profile?.age);
    if (Number.isFinite(profileAge) && profileAge > 0 && profileAge < 18) messages.push("For users under 18, personalized filters support regular balanced meals and activity rather than calorie restriction.");
    const target = $("#personalizedFilterAvailability");
    if (target) target.textContent = Array.from(new Set(messages)).join(" ");
  }

  function updateRecipeResultStatus(resultCount, selectedFilters = getSelectedPersonalizedRecipeFilters(), context = buildPersonalizedRecipeContext()) {
    const target = $("#recipeResultStatus");
    if (!target) return;
    if (!resultCount && selectedFilters.length) {
      target.textContent = "No recipes match all selected filters. Try removing one personalized filter, increasing cooking time, adding more pantry ingredients, reviewing dietary preferences, or clearing personalized filters.";
      return;
    }
    target.textContent = selectedFilters.length ? `${resultCount} recipes match your selected filters.` : `${resultCount} recipes available. Personalized recipe filters are optional and must not prevent users from browsing recipes without personalization.`;
  }

  function getRecipeCardNutritionTags(recipe, selectedFilters = []) {
    const tagMap = {
      [PERSONALIZED_RECIPE_FILTERS.HIGHER_PROTEIN]: "Higher protein",
      [PERSONALIZED_RECIPE_FILTERS.BALANCED_MEAL]: LANGUAGE.balancedMealOption || "Balanced meal option",
      [PERSONALIZED_RECIPE_FILTERS.WORKOUT_FRIENDLY]: "Workout-friendly",
      [PERSONALIZED_RECIPE_FILTERS.VEGETABLE_RICH]: "Vegetable-rich",
      [PERSONALIZED_RECIPE_FILTERS.HIGHER_FIBRE]: "Higher fibre",
      [PERSONALIZED_RECIPE_FILTERS.LOWER_ADDED_SUGAR]: "Lower added sugar",
      [PERSONALIZED_RECIPE_FILTERS.QUICK_MEAL]: "Quick meal"
    };
    const selectedTags = selectedFilters.map((filter) => tagMap[filter]).filter(Boolean);
    const recipeTags = buildRecipeNutritionTags(recipe);
    if (isQuickMealRecipe(recipe)) recipeTags.push("Quick meal");
    if (isWorkoutFriendlyRecipe(recipe, buildPersonalizedRecipeContext())) recipeTags.push("Workout-friendly");
    return Array.from(new Set([...selectedTags.filter((tag) => recipeTags.includes(tag) || tag === "Quick meal" && isQuickMealRecipe(recipe)), ...recipeTags])).slice(0, 3);
  }

  function getPersonalizedMatchLabel(score) {
    if (score >= 80) return "Strong planning match";
    if (score >= 60) return "Useful planning match";
    return "Possible planning match";
  }

  function buildRecipeMatchReasons(recipe, context = buildPersonalizedRecipeContext(), selectedFilters = getSelectedPersonalizedRecipeFilters()) {
    const reasons = [];
    selectedFilters.forEach((filter) => {
      const label = {
        [PERSONALIZED_RECIPE_FILTERS.HIGHER_PROTEIN]: "Matches the Higher protein filter",
        [PERSONALIZED_RECIPE_FILTERS.BALANCED_MEAL]: "Matches the Balanced meal filter",
        [PERSONALIZED_RECIPE_FILTERS.WORKOUT_FRIENDLY]: "Matches the Workout-friendly filter",
        [PERSONALIZED_RECIPE_FILTERS.VEGETABLE_RICH]: "Matches the Vegetable-rich filter",
        [PERSONALIZED_RECIPE_FILTERS.HIGHER_FIBRE]: "Matches the Higher fibre filter",
        [PERSONALIZED_RECIPE_FILTERS.LOWER_ADDED_SUGAR]: "Matches the Lower added sugar filter",
        [PERSONALIZED_RECIPE_FILTERS.QUICK_MEAL]: "Ready in 30 minutes or less"
      }[filter];
      if (label) reasons.push(label);
    });
    const pantryMatch = calculatePantryMatch(recipe, context.pantryItems || []);
    if (pantryMatch.matched > 0) reasons.push(`Uses ${pantryMatch.matched} pantry ${pantryMatch.matched === 1 ? "ingredient" : "ingredients"}`);
    if (selectedFilters.includes(PERSONALIZED_RECIPE_FILTERS.FITS_NUTRITION_RANGE)) reasons.push(...calculateRecipeNutritionFitScore(recipe, context).reasons);
    if (isQuickMealRecipe(recipe)) reasons.push(`Ready in ${getRecipeTotalMinutes(recipe)} minutes`);
    return Array.from(new Set(reasons)).slice(0, 3);
  }

  function generateRecipeCategories() {
    const cuisines = uniqueRecipeValues("cuisine");
    fillSelect("#recipeCategoryFilter", ["All", ...MEAL_CATEGORIES], "All meals");
    fillSelect("#recipeCuisineFilter", ["All", ...cuisines], "All cuisines");
    fillSelect("#recipeDifficultyFilter", ["All", ...DIFFICULTIES], "All difficulties");
    fillSelect("#recipeDietaryFilter", ["All", ...DIETARY_PREFERENCES], "All diets");
  }

  function uniqueRecipeValues(key) {
    return Array.from(new Set(state.recipes.map((recipe) => recipe[key]).filter(Boolean))).sort();
  }

  function fillSelect(selector, values, allLabel) {
    const select = $(selector);
    if (!select) return;
    const current = select.value || "All";
    select.innerHTML = values.map((value) => `<option value="${escapeHtml(value)}">${escapeHtml(value === "All" ? allLabel : value)}</option>`).join("");
    select.value = values.includes(current) ? current : "All";
  }

  function normalizeRecipe(recipe) {
    const ingredients = normalizeIngredientList(recipe.ingredients);
    const optionalIngredients = normalizeIngredientList(recipe.optionalIngredients || []);
    const structuredIngredients = normalizeStructuredIngredientList(recipe.structuredIngredients, ingredients, false);
    const structuredOptionalIngredients = normalizeStructuredIngredientList(recipe.structuredOptionalIngredients, optionalIngredients, true);
    const allergies = getRecipeAllergies(recipe);
    return {
      ...recipe,
      ingredientSchemaVersion: recipe.ingredientSchemaVersion || 0,
      imagePlaceholder: recipe.imagePlaceholder || recipe.name,
      category: recipe.category || "Dinner",
      subcategory: recipe.subcategory || "Quick Meals",
      cuisine: recipe.cuisine || "Global",
      dietaryTags: Array.isArray(recipe.dietaryTags) ? recipe.dietaryTags : [],
      ingredients,
      optionalIngredients,
      structuredIngredients,
      structuredOptionalIngredients,
      batchCooking: recipe.batchCooking && typeof recipe.batchCooking === "object" ? structuredCloneSafe(recipe.batchCooking) : { supported: false },
      leftovers: recipe.leftovers && typeof recipe.leftovers === "object" ? structuredCloneSafe(recipe.leftovers) : { supported: false },
      cookingTime: toNumber(recipe.cookingTime),
      preparationTime: toNumber(recipe.preparationTime),
      totalTime: toNumber(recipe.totalTime) || toNumber(recipe.cookingTime) + toNumber(recipe.preparationTime),
      servings: toNumber(recipe.servings) || 1,
      calories: normalizeOptionalNutritionNumber(recipe.calories),
      protein: normalizeOptionalNutritionNumber(recipe.protein),
      carbohydrates: normalizeOptionalNutritionNumber(recipe.carbohydrates),
      fat: normalizeOptionalNutritionNumber(recipe.fat),
      sugar: normalizeOptionalNutritionNumber(recipe.sugar),
      vegetableServings: normalizeOptionalNutritionNumber(recipe.vegetableServings),
      fibre: normalizeOptionalNutritionNumber(recipe.fibre ?? recipe.fiber),
      addedSugar: normalizeOptionalNutritionNumber(recipe.addedSugar),
      allergies,
      steps: Array.isArray(recipe.steps) ? recipe.steps : []
    };
  }

  function normalizeIngredientList(list) {
    return (Array.isArray(list) ? list : []).map((ingredient) => typeof ingredient === "string" ? { name: ingredient, quantity: "", unit: "", displayText: ingredient } : { name: ingredient.name || "", quantity: ingredient.quantity ?? "", unit: ingredient.unit || "", displayText: ingredient.displayText || "" }).filter((ingredient) => ingredient.name);
  }

  function normalizeIngredientCatalogue(catalogue) {
    const source = catalogue && typeof catalogue === "object" ? catalogue : STARTER.ingredients;
    return {
      ingredientSchemaVersion: source.ingredientSchemaVersion || 0,
      categories: Array.isArray(source.categories) ? source.categories : [],
      units: Array.isArray(source.units) ? source.units : [],
      measurementStatuses: Array.isArray(source.measurementStatuses) ? source.measurementStatuses : [],
      ingredients: Array.isArray(source.ingredients) ? source.ingredients : []
    };
  }

  function normalizeSubstitutionCatalogue(catalogue) {
    return typeof SUBSTITUTIONS.normalizeSubstitutionCatalogue === "function"
      ? SUBSTITUTIONS.normalizeSubstitutionCatalogue(catalogue || STARTER.substitutions)
      : { substitutionSchemaVersion: 1, groups: [] };
  }

  function buildSubstitutionRuleIndexes(catalogue = state.substitutionCatalogue) {
    return typeof SUBSTITUTIONS.buildRuleIndexes === "function"
      ? SUBSTITUTIONS.buildRuleIndexes(catalogue)
      : { rules: [], rulesByRuleId: new Map(), rulesByOriginalIngredientId: new Map(), rulesByRecipeId: new Map(), rulesByRecipeType: new Map() };
  }

  function validateCurrentSubstitutionCatalogue() {
    if (typeof SUBSTITUTIONS.validateSubstitutionCatalogue !== "function") return { valid: true, errors: [], activeRuleCount: 0, groupCount: 0 };
    return SUBSTITUTIONS.validateSubstitutionCatalogue(state.substitutionCatalogue, {
      ingredientIds: state.ingredientCatalogue.ingredients.map((ingredient) => ingredient.id),
      recipeIds: state.recipes.map((recipe) => recipe.id)
    });
  }

  function normalizeFreezerGuidanceCatalogue(catalogue) {
    const source = catalogue && typeof catalogue === "object" ? catalogue : STARTER.freezerGuidance;
    const policies = Array.isArray(source.policies) ? source.policies.filter((policy) => policy && typeof policy === "object") : [];
    return {
      freezerGuidanceCatalogueVersion: Number(source.freezerGuidanceCatalogueVersion) || FREEZER_GUIDANCE_CATALOGUE_SCHEMA_VERSION,
      policyResolutionVersion: Number(source.policyResolutionVersion) || FREEZER_GUIDANCE_RESOLUTION_VERSION,
      reviewWorkflowVersion: Number(source.reviewWorkflowVersion) || FREEZER_GUIDANCE_REVIEW_WORKFLOW_VERSION,
      reviewedAt: source.reviewedAt || null,
      sourceHierarchy: Array.isArray(source.sourceHierarchy) ? source.sourceHierarchy : FREEZER_GUIDANCE_SOURCE_PRIORITY,
      policies,
      legacyMigration: source.legacyMigration || null
    };
  }

  function validateFreezerGuidancePolicy(policy) {
    const errors = [];
    if (!policy || typeof policy !== "object") errors.push("Policy record is missing.");
    if (!policy?.policyId) errors.push("Policy ID is required.");
    if (Number(policy?.schemaVersion) !== FREEZER_GUIDANCE_POLICY_SCHEMA_VERSION) errors.push("Unsupported freezer policy schema version.");
    if (!Object.values(FREEZER_GUIDANCE_SUBJECT_TYPES).includes(policy?.subject?.entityType)) errors.push("Subject type is not controlled.");
    if (!Object.values(FREEZER_SUITABILITY_STATUSES).includes(policy?.suitability?.status)) errors.push("Suitability status is not controlled.");
    if (!Object.values(FREEZER_GUIDANCE_REVIEW_STATUSES).includes(policy?.review?.status)) errors.push("Review status is not controlled.");
    if (policy?.review?.generatedBy === "ai" && policy.review.status !== FREEZER_GUIDANCE_REVIEW_STATUSES.DRAFT_AI_GENERATED) errors.push("AI-generated guidance must stay draft-ai-generated.");
    if (policy?.review?.status === FREEZER_GUIDANCE_REVIEW_STATUSES.DRAFT_AI_GENERATED && policy?.suitability?.canFreeze === true) errors.push("Draft AI guidance cannot recommend freezing.");
    if (isFreezerGuidancePolicyApprovedForConsumers(policy) && policy.review?.contentHash !== policy.review?.approvalContentHash) errors.push("Approved policy content hash must match approval hash.");
    if (isFreezerGuidancePolicyApprovedForConsumers(policy) && !(policy.evidence || []).length) errors.push("Approved policy requires evidence.");
    return { valid: errors.length === 0, errors };
  }

  function validateFreezerGuidanceCatalogue(catalogue = state.freezerGuidanceCatalogue) {
    const normalized = normalizeFreezerGuidanceCatalogue(catalogue);
    const ids = new Set();
    const errors = [];
    normalized.policies.forEach((policy) => {
      if (ids.has(policy.policyId)) errors.push(`Duplicate freezer policy ID: ${policy.policyId}`);
      ids.add(policy.policyId);
      validateFreezerGuidancePolicy(policy).errors.forEach((error) => errors.push(`${policy.policyId || "unknown"}: ${error}`));
    });
    return { valid: errors.length === 0, errors, policyCount: normalized.policies.length };
  }

  function buildFreezerGuidancePolicyIndexes(catalogue = state.freezerGuidanceCatalogue) {
    const policies = normalizeFreezerGuidanceCatalogue(catalogue).policies;
    const byPolicyId = new Map();
    const bySubjectKey = new Map();
    policies.forEach((policy) => {
      byPolicyId.set(policy.policyId, policy);
      const key = getFreezerGuidanceSubjectKey(policy.subject);
      if (!bySubjectKey.has(key)) bySubjectKey.set(key, []);
      bySubjectKey.get(key).push(policy);
    });
    bySubjectKey.forEach((list) => list.sort(compareFreezerGuidancePolicySpecificity));
    return { byPolicyId, bySubjectKey };
  }

  function getFreezerGuidanceSubjectKey(subject = {}) {
    return [subject.entityType || "", subject.entityId || subject.categoryId || subject.recipeId || "general", subject.form || "any"].join("::");
  }

  function compareFreezerGuidancePolicySpecificity(a, b) {
    const score = (policy) => ({ "product-label-override": 100, recipe: 90, "prepared-leftover-category": 80, "prepared-food": 70, ingredient: 60, "ingredient-category": 30, "general-fallback": 10 }[policy?.subject?.entityType] || 0) + (policy?.subject?.form && policy.subject.form !== "any" ? 5 : 0);
    return score(b) - score(a) || String(a.policyId).localeCompare(String(b.policyId));
  }

  function isFreezerGuidancePolicyApprovedForConsumers(policy) {
    const status = policy?.review?.status;
    return policy?.lifecycle?.status === FREEZER_GUIDANCE_LIFECYCLE_STATUSES.ACTIVE
      && [FREEZER_GUIDANCE_REVIEW_STATUSES.APPROVED, FREEZER_GUIDANCE_REVIEW_STATUSES.APPROVED_WITH_LIMITATIONS].includes(status)
      && policy.review?.generatedBy !== "ai"
      && policy.review?.contentHash
      && policy.review.contentHash === policy.review.approvalContentHash;
  }

  function buildIngredientAliasIndex(catalogue = state.ingredientCatalogue) {
    return typeof INGREDIENT_DATA.buildIngredientAliasIndex === "function" ? INGREDIENT_DATA.buildIngredientAliasIndex(catalogue) : {};
  }

  function resolveCanonicalIngredientName(input) {
    return typeof INGREDIENT_DATA.resolveIngredientName === "function" ? INGREDIENT_DATA.resolveIngredientName(input, state.ingredientCatalogue, state.ingredientAliasIndex) : { status: "unresolved", normalizedInput: normalizeIngredient(input) };
  }

  function normalizeStructuredIngredientList(structuredList, legacyList = [], optional = false) {
    const structured = Array.isArray(structuredList) ? structuredList : [];
    if (structured.length) return structured.map((ingredient, index) => ({
      ingredientId: ingredient.ingredientId || null,
      displayName: ingredient.displayName || ingredient.name || legacyList[index]?.name || "Unknown ingredient",
      displayText: ingredient.displayText || ingredientTagText(legacyList[index] || ingredient),
      quantity: ingredient.quantity ?? null,
      quantityMax: ingredient.quantityMax ?? null,
      unit: ingredient.unit || null,
      optional: ingredient.optional === true,
      category: ingredient.category || "other",
      substituteGroup: ingredient.substituteGroup || null,
      form: ingredient.form || null,
      preparation: ingredient.preparation || null,
      packageSize: ingredient.packageSize || null,
      amountText: ingredient.amountText || null,
      section: ingredient.section || (optional ? "optional" : "main"),
      notes: ingredient.notes || null,
      measurementStatus: ingredient.measurementStatus || "unresolved",
      resolutionStatus: ingredient.resolutionStatus || (ingredient.ingredientId ? "resolved" : "unresolved")
    }));
    if (typeof INGREDIENT_DATA.convertLegacyIngredientAtRuntime === "function") return legacyList.map((ingredient) => ({ ...INGREDIENT_DATA.convertLegacyIngredientAtRuntime(ingredient), optional }));
    return legacyList.map((ingredient) => ({ ingredientId: null, displayName: ingredient.name || "Unknown ingredient", displayText: ingredientTagText(ingredient), quantity: null, quantityMax: null, unit: null, optional, category: "other", substituteGroup: null, form: null, preparation: null, packageSize: null, amountText: null, measurementStatus: "unresolved", resolutionStatus: "unresolved" }));
  }

  function getStructuredIngredients(recipe) {
    return normalizeRecipe(recipe).structuredIngredients;
  }

  function getStructuredOptionalIngredients(recipe) {
    return normalizeRecipe(recipe).structuredOptionalIngredients;
  }

  function getRecipeAllergies(recipe) {
    const value = recipe.allergies || recipe.allergyWarnings || ["None"];
    return (Array.isArray(value) ? value : [value]).filter(Boolean);
  }

  function getUserAllergies() {
    const user = state.currentUser ? state.users.find((candidate) => candidate.id === state.currentUser.id) || state.currentUser : null;
    return normalizeAllergies(user && user.allergies);
  }

  function recipeContainsUserAllergy(recipe, userProfile = state.currentUser) {
    const userAllergies = normalizeAllergies(userProfile?.allergies ?? getUserAllergies()).map(normalizeIngredient);
    if (!userAllergies.length) return false;
    const recipeAllergies = getRecipeAllergies(recipe).map(normalizeIngredient);
    const ingredientNames = normalizeIngredientList(recipe.ingredients).map((ingredient) => normalizeIngredient(ingredient.name));
    return userAllergies.some((allergy) => recipeAllergies.some((item) => item.includes(allergy) || allergy.includes(item)) || ingredientNames.some((item) => item.includes(allergy) || allergy.includes(item)));
  }

  function getUserDietaryPreference() {
    const user = state.currentUser ? state.users.find((candidate) => candidate.id === state.currentUser.id) || state.currentUser : null;
    const preference = String((user && user.dietaryPreference) || "").trim();
    return preference && preference !== "No preference" ? preference : "";
  }

  function displayRecipeDetails(recipeId) {
    const recipe = state.recipes.map(normalizeRecipe).find((item) => item.id === recipeId);
    if (!recipe) {
      showToast("Recipe not found", "error");
      return;
    }
    const result = calculateRecipeMatch(parseIngredientInput($("#recipeSearch").value), recipe);
    const saved = isRecipeFavorite(recipe.id);
    const nutritionTags = buildRecipeNutritionTags(recipe);
    const personalizedContext = buildPersonalizedRecipeContext();
    const detailReasons = buildRecipeMatchReasons(recipe, personalizedContext, getSelectedPersonalizedRecipeFilters());
    $("#recipeDetailModalContent").innerHTML = `<div class="recipe-detail-heading">
      <div class="recipe-detail-image"><span>${escapeHtml(recipe.imagePlaceholder || recipe.name)}</span></div>
      <div><span class="rule-badge">${escapeHtml(recipe.category)} · ${escapeHtml(recipe.cuisine)}</span><h2 id="recipeDetailModalTitle" data-recipe-id="${escapeHtml(recipe.id)}">${escapeHtml(recipe.name)}</h2><p>Check ingredient labels and confirm dietary suitability before cooking.</p>${nutritionTags.length ? `<div class="recipe-nutrition-tags detail-tags">${nutritionTags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}</div>` : ""}</div>
    </div>
    <div class="recipe-detail-stats">
      <span><b>Servings</b>${recipe.servings}</span><span><b>Prep</b>${recipe.preparationTime} min</span><span><b>Cook</b>${recipe.cookingTime} min</span><span><b>Total</b>${recipe.totalTime} min</span>
      <span><b>Calories</b>${formatRecipeNutritionValue(recipe.calories)}</span><span><b>Protein</b>${formatRecipeNutritionValue(recipe.protein, "g")}</span><span><b>Carbs</b>${formatRecipeNutritionValue(recipe.carbohydrates, "g")}</span><span><b>Fat</b>${formatRecipeNutritionValue(recipe.fat, "g")}</span>
    </div>
    <div class="recipe-detail-section recipe-plan-fit-shell">
      <div class="recipe-fit-control">
        <div>
          <h3>How This Recipe Fits Your Plan</h3>
          <p>Choose how many servings you plan to eat.</p>
        </div>
        <label class="recipe-fit-servings-label">Selected servings
          <input type="number" min="1" step="1" value="1" data-recipe-detail-servings="${escapeHtml(recipe.id)}" aria-label="Selected servings for ${escapeHtml(recipe.name)}">
        </label>
      </div>
      <div id="recipeFitStatus" class="recipe-fit-status" role="status" aria-live="polite"></div>
      <div id="recipePlanFitContent">${renderRecipePlanFit(recipe, 1)}</div>
      <div id="recipeCostContent">${renderRecipeCostSummary(recipe, 1)}</div>
    </div>
    ${detailReasons.length ? `<div class="recipe-detail-section"><h3>Why this recipe appeared</h3><ul class="recipe-detail-reasons">${detailReasons.map((reason) => `<li>${escapeHtml(reason)}</li>`).join("")}</ul></div>` : ""}
    ${renderOfflineRecipeControls(recipe)}
    <div class="recipe-detail-section"><h3>Required ingredients</h3><div class="ingredient-tags">${recipe.ingredients.map(ingredientTag).join("")}</div></div>
    <div class="recipe-detail-section"><h3>Optional ingredients</h3><div class="ingredient-tags">${recipe.optionalIngredients.length ? recipe.optionalIngredients.map(ingredientTag).join("") : "<span>None</span>"}</div></div>
    <div class="recipe-detail-section"><h3>Missing ingredients</h3><div class="ingredient-tags missing-tags">${result.missingIngredients.length ? result.missingIngredients.map(ingredientTag).join("") : "<span>None</span>"}</div></div>
    <div class="recipe-detail-section"><h3>Allergy information</h3><p>${getRecipeAllergies(recipe).map(escapeHtml).join(", ")}</p></div>
    <div class="recipe-detail-section"><h3>Dietary tags</h3><div class="dietary-tags">${recipe.dietaryTags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}</div></div>
    <div class="recipe-detail-section"><h3>Step-by-step instructions</h3><ol class="favorite-steps-list" id="recipeDetailInstructions" tabindex="-1">${recipe.steps.map((step) => `<li>${escapeHtml(step)}</li>`).join("")}</ol></div>
    <div id="recipeTtsFallbackRegion" class="feature-fallback-region" aria-live="polite"></div>
    <div id="recipeTranslationFallbackRegion" class="feature-fallback-region" aria-live="polite"></div>
    <div id="recipeMediaFallbackRegion" class="feature-fallback-region" aria-live="polite"></div>
    <div class="recipe-detail-actions">
      <button class="button primary small" data-favorite="${recipe.id}">${saved ? "Remove Favorite" : "Favorite"}</button>
      <button class="button secondary small" type="button" data-recipe-read-aloud="${recipe.id}">Read Aloud</button>
      <button class="button secondary small" type="button" data-recipe-translation-fallback="${recipe.id}">Translation Fallback</button>
      <button class="button secondary small" type="button" data-recipe-media-fallback="${recipe.id}">Transcript / Media Fallback</button>
      <button class="button secondary small" type="button" data-offline-download="${recipe.id}">Download Offline</button>
      <button class="button secondary small" data-page="planner">Add to Meal Planner</button>
      <button class="button secondary small" type="button" data-cook-before-recipe="${recipe.id}">Use Food That Needs Attention</button>
      <button class="button secondary small" data-add-missing="${recipe.id}">Add Missing Ingredients to Shopping List</button>
    </div>`;
    $("#recipeDetailModal").classList.remove("hidden");
    $("#recipeDetailModal").setAttribute("aria-hidden", "false");
  }

  function closeRecipeDetailModal() {
    const modal = $("#recipeDetailModal");
    if (!modal || modal.classList.contains("hidden")) return;
    modal.classList.add("hidden");
    modal.setAttribute("aria-hidden", "true");
    $("#recipeDetailModalContent").innerHTML = "";
  }

  function displayRecipeDetailsIfOpen(recipeId) {
    const modal = $("#recipeDetailModal");
    if (!modal || modal.classList.contains("hidden")) return;
    if ($("#recipeDetailModalTitle") && state.recipes.some((recipe) => recipe.id === recipeId)) displayRecipeDetails(recipeId);
  }

  function getStructuredIngredientForDisplay(recipe, ingredient) {
    const normalizedName = normalizeIngredient(ingredient?.name);
    return getStructuredIngredients(recipe).find((item) => item.ingredientId && (normalizeIngredient(item.displayName) === normalizedName || normalizeIngredient(item.displayText) === normalizedName || ingredientsMatch(item.displayName, ingredient?.name))) || null;
  }

  function addMissingIngredientsToShoppingList(recipeId) {
    const recipe = state.recipes.map(normalizeRecipe).find((item) => item.id === recipeId);
    if (!recipe) {
      showToast("Recipe not found", "error");
      return;
    }
    const result = calculateRecipeMatch(parseIngredientInput($("#recipeSearch").value), recipe);
    const existing = state.guestMode ? guestSessionData.shoppingList : readUserStorage("chefNovaShoppingList", []);
    const additions = result.missingIngredients.map((ingredient) => {
      const structured = getStructuredIngredientForDisplay(recipe, ingredient);
      return { id: "s" + Date.now() + "-" + normalizeIngredient(ingredient.name), name: ingredient.name, ingredientId: structured?.ingredientId || null, quantity: ingredient.quantity || 1, unit: ingredient.unit || "", recipeId: recipe.id, checked: false };
    });
    const merged = [...existing];
    let addedCount = 0;
    additions.forEach((item) => {
      if (!merged.some((existingItem) => normalizeIngredient(existingItem.name) === normalizeIngredient(item.name))) {
        merged.push(item);
        addedCount += 1;
      }
    });
    if (state.guestMode) {
      guestSessionData.shoppingList = merged;
      persistGuestProgress();
    } else writeUserStorage("chefNovaShoppingList", merged);
    displayShoppingList();
    updateDashboardStats();
    if (!additions.length) showToast("No missing ingredients to add", "info");
    else if (!addedCount) showToast("This item is already in the shopping list", "warning");
    else if (state.guestMode) showToast(`Shopping list updated for this session. ${GUEST_TEMPORARY_MESSAGE}`, "info");
    else showToast("Missing ingredients added to shopping list", "success", { saveToHistory: true, actionName: "View Recipes", actionTarget: "recipes" });
  }

  function getShoppingListItems() {
    return state.guestMode ? (guestSessionData.shoppingList || []) : readUserStorage("chefNovaShoppingList", []);
  }

  function saveShoppingListItems(items) {
    clearBudgetDataCaches();
    const normalizedItems = Array.isArray(items) ? items : [];
    if (state.guestMode) {
      guestSessionData.shoppingList = normalizedItems;
      persistGuestProgress();
      return;
    }
    writeUserStorage("chefNovaShoppingList", normalizedItems);
  }

  function getActiveBudgetPriceSettings() {
    const budget = normalizePlanningModeInputs(state.planningModeInputs).budgetRescue;
    return {
      selectedPriceSource: budget.priceSource,
      selectedProfileId: budget.savedPriceProfileId,
      sessionPriceOverrides: [...normalizePriceEntries(budget.sessionPriceOverrides || []), ...normalizePriceEntries(guestSessionData.priceOverrides || [])],
      userPriceProfiles: getSavedPriceProfiles(),
      chefNovaEstimateCatalogue: state.priceEstimateCatalogue
    };
  }

  function getBudgetContextForCostEngine() {
    const budget = normalizePlanningModeInputs(state.planningModeInputs).budgetRescue;
    return {
      weeklyBudgetCents: budget.weeklyBudgetCents,
      planningTargetCents: budget.weeklyBudgetCents ? getBudgetRescuePlanningTargetCents(budget) : null,
      priceCushionPercent: Number(budget.priceCushionPercent) || 0
    };
  }

  function buildWeeklyCostMeals(plan = state.mealPlans) {
    const normalizedPlan = normalizeMealPlan(plan);
    return DAYS.flatMap((day) => getMealSlotsForDay((normalizedPlan[day] || {}), MEALS).map((slot) => {
      const rawEntry = slot.entry;
      const entry = normalizeMealPlanEntry(rawEntry);
      if (!entry?.recipeId || entry.mealType === "leftover") return null;
      const costServings = Number(rawEntry?.plannedRecipeServings || entry.plannedRecipeServings || entry.servings);
      const variantRecipe = getRecipeForMealEntry(entry);
      const mealType = getMealSlotLabel(slot);
      return { day, mealType, slotId: slot.id, mealId: `${day}::${slot.id}`, recipeId: entry.recipeId, recipe: variantRecipe, servings: Number.isFinite(costServings) && costServings > 0 ? costServings : entry.servings, entry };
    }).filter(Boolean));
  }

  function calculateCurrentMealPlanCosts() {
    return calculateMealPlanCostsForPlan(state.mealPlans, state.pantry);
  }

  function calculateMealPlanCostsWithPantry(plan = state.mealPlans, pantry = state.pantry) {
    if (typeof COST_ENGINE.calculateMealPlanCosts !== "function") return null;
    return COST_ENGINE.calculateMealPlanCosts({
      meals: buildWeeklyCostMeals(plan),
      recipes: state.recipes.map(normalizeRecipe),
      pantry,
      pricingContext: getActiveBudgetPriceSettings(),
      budgetContext: getBudgetContextForCostEngine(),
      ingredientResolver: resolveCanonicalIngredientName,
      calculationDate: getCurrentDateString()
    });
  }

  function calculateMealPlanCostsForPlan(plan = state.mealPlans, pantry = state.pantry) {
    return calculateMealPlanCostsWithPantry(plan, buildBudgetCalculationPantry(plan, pantry));
  }

  function buildPantryAllocationForPlan(plan = state.mealPlans, pantryItems = state.pantry) {
    if (typeof PANTRY_FIRST.rebuildPlanPantryAllocations !== "function") return null;
    return PANTRY_FIRST.rebuildPlanPantryAllocations({
      meals: buildWeeklyCostMeals(plan),
      recipes: state.recipes.map(normalizeRecipe),
      pantryItems,
      ingredientResolver: resolveCanonicalIngredientName,
      planStartDate: getCurrentDateString(),
      planEndDate: getCurrentDateString()
    });
  }

  function calculatePantrySavingsForPlan(plan = state.mealPlans) {
    const withPantry = calculateMealPlanCostsForPlan(plan, state.pantry);
    const withoutPantry = calculateMealPlanCostsForPlan(plan, []);
    if (!withPantry || !withoutPantry) return { estimatedPurchasesAvoidedCents: null, knownPurchasesAvoidedCents: 0, incomplete: true };
    const complete = Number.isInteger(withPantry.weeklySummary.weeklyGroceryCostCents) && Number.isInteger(withoutPantry.weeklySummary.weeklyGroceryCostCents);
    const known = Math.max(0, (withoutPantry.weeklySummary.knownPurchaseSubtotalCents || 0) - (withPantry.weeklySummary.knownPurchaseSubtotalCents || 0));
    return {
      estimatedPurchasesAvoidedCents: complete ? Math.max(0, withoutPantry.weeklySummary.weeklyGroceryCostCents - withPantry.weeklySummary.weeklyGroceryCostCents) : null,
      knownPurchasesAvoidedCents: known,
      incomplete: !complete,
      withPantry,
      withoutPantry
    };
  }

  function formatAllocationQuantity(quantity, unit) {
    return `${formatQuantityForDisplay(quantity)} ${unit || ""}`.trim();
  }

  function renderPantryUseReview(allocation) {
    const rows = allocation.summary.mealPantryAllocations.filter((item) => item.pantryQuantityApplied > 0 || item.missingQuantity > 0);
    if (!rows.length) return "";
    return `<details class="pantry-use-review">
      <summary>Review Pantry Use</summary>
      <p>These Pantry quantities are reserved only for this plan preview. Your Pantry will not be changed until you confirm a meal was cooked or update Pantry manually.</p>
      <div class="pantry-use-list">${rows.slice(0, 12).map((item) => `<article>
        <h5>${escapeHtml(getIngredientDisplayNameById(item.ingredientId, item.displayName))}</h5>
        <dl>
          <div><dt>Required</dt><dd>${escapeHtml(formatAllocationQuantity(item.requiredQuantity, item.requiredUnit))}</dd></div>
          <div><dt>Used from Pantry</dt><dd>${escapeHtml(formatAllocationQuantity(item.pantryQuantityApplied, item.requiredUnit))}</dd></div>
          <div><dt>Need to buy</dt><dd>${escapeHtml(formatAllocationQuantity(item.missingQuantity, item.missingUnit))}</dd></div>
        </dl>
        ${item.allocations.length ? `<p>${item.allocations.map((lot) => `${formatAllocationQuantity(lot.quantity, lot.unit)} from ${lot.originalLabel}${lot.opened ? " (opened)" : ""}`).map(escapeHtml).join("; ")}</p>` : ""}
      </article>`).join("")}</div>
      ${rows.length > 12 ? `<p>${rows.length - 12} more Pantry-use rows are included in this plan.</p>` : ""}
    </details>`;
  }

  function renderPantryFirstSummary(plan = state.mealPlans) {
    if (getCurrentPlanningMode() !== PLANNING_MODES.BUDGET_RESCUE) return "";
    const allocation = buildPantryAllocationForPlan(plan);
    if (!allocation) return "";
    const summary = allocation.summary;
    const savings = calculatePantrySavingsForPlan(plan);
    const savingsText = Number.isInteger(savings.estimatedPurchasesAvoidedCents)
      ? `<div><dt>Estimated purchases avoided</dt><dd>${escapeHtml(formatCostCents(savings.estimatedPurchasesAvoidedCents))}</dd></div>`
      : `<div><dt>Known purchases avoided</dt><dd>${escapeHtml(formatCostCents(savings.knownPurchasesAvoidedCents))}</dd></div>`;
    const incomplete = savings.incomplete ? `<p class="shopping-cost-warning">Some prices are incomplete, so the complete purchases-avoided estimate is not available yet.</p>` : "";
    return `<section class="pantry-first-summary" aria-labelledby="pantryFirstSummaryHeading" aria-live="polite">
      <div class="budget-summary-heading">
        <div><h4 id="pantryFirstSummaryHeading">Pantry-first summary</h4><p>Chef Nova uses compatible Pantry quantities before adding groceries.</p></div>
        <button class="button secondary small" type="button" data-budget-edit-pantry>Edit Pantry</button>
      </div>
      <dl>
        <div><dt>Pantry ingredients used</dt><dd>${escapeHtml(String(summary.ingredientGroupCountUsed))}</dd></div>
        <div><dt>Fully covered needs</dt><dd>${escapeHtml(String(summary.fullyCoveredRequirementCount))}</dd></div>
        <div><dt>Partially covered needs</dt><dd>${escapeHtml(String(summary.partiallyCoveredRequirementCount))}</dd></div>
        <div><dt>Opened items used</dt><dd>${escapeHtml(String(summary.openedLotCountUsed))}</dd></div>
        <div><dt>Use-soon items used</dt><dd>${escapeHtml(String(summary.useSoonLotCountUsed))}</dd></div>
        ${savingsText}
      </dl>
      ${incomplete}
      ${renderPantryUseReview(allocation)}
    </section>`;
  }

  function calculateRecipeCostForDisplay(recipe, selectedServings = recipe?.servings || 1) {
    if (typeof COST_ENGINE.calculateRecipeCostSummary !== "function") return null;
    return COST_ENGINE.calculateRecipeCostSummary({
      recipe: normalizeRecipe(recipe),
      selectedServings,
      pricingContext: getActiveBudgetPriceSettings(),
      calculationDate: getCurrentDateString()
    });
  }

  function formatCostCents(cents) {
    if (Number.isInteger(cents) && cents === 0) return "$0.00 CAD";
    return typeof PRICE_DATA.centsToCurrency === "function" ? PRICE_DATA.centsToCurrency(cents, "CAD") : formatCurrencyFromCents(cents);
  }

  function formatQuantityForDisplay(value) {
    const number = Number(value);
    if (!Number.isFinite(number)) return "unknown";
    return formatLocalizedNumber(Number.isInteger(number) ? number : Math.round(number * 100) / 100, { maximumFractionDigits: 2 });
  }

  function pluralize(count, singular, plural = `${singular}s`) {
    return Number(count) === 1 ? singular : plural;
  }

  function numberWord(count) {
    const words = ["Zero", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten"];
    return Number.isInteger(count) && count >= 0 && count <= 10 ? words[count] : String(count);
  }

  function getCoveragePercentDisplay(usableCount, totalCount) {
    if (!totalCount) return null;
    if (usableCount === totalCount) return 100;
    return Math.min(99, Math.round(usableCount / totalCount * 100));
  }

  function getIngredientDisplayNameById(ingredientId, fallback = "Grocery item") {
    const item = state.ingredientCatalogue?.ingredients?.find((ingredient) => ingredient.id === ingredientId);
    return item?.name || fallback;
  }

  function findResolvedPriceEntryById(priceEntryId) {
    if (!priceEntryId) return null;
    const settings = getActiveBudgetPriceSettings();
    const estimateProfiles = Array.isArray(settings.chefNovaEstimateCatalogue?.profiles) ? settings.chefNovaEstimateCatalogue.profiles : [];
    const entries = [
      ...(settings.sessionPriceOverrides || []),
      ...(settings.userPriceProfiles || []).flatMap((profile) => profile.entries || []),
      ...estimateProfiles.flatMap((profile) => profile.entries || [])
    ];
    return entries.find((entry) => entry.id === priceEntryId) || null;
  }

  function getPriceConfidenceReason(group) {
    const reasons = {
      "missing-price": "No usable price is available for this grocery item.",
      "missing-quantity": "The required quantity is not measurable yet.",
      "incompatible-unit": "The recipe and saved price use units that Chef Nova cannot safely convert.",
      "unknown-package-size": "The saved package price does not include a usable package size.",
      "ambiguous-ingredient": "This grocery item is not linked to one standardized ingredient.",
      "form-mismatch": "The available price applies to a different ingredient form."
    };
    return reasons[group?.status] || "Chef Nova cannot cost this grocery item reliably yet.";
  }

  function classifyPurchaseGroupPriceConfidence(group) {
    const sourceEntry = findResolvedPriceEntryById(group?.priceEntryId);
    const isUsable = Boolean(group && group.missingQuantity > 0 && Number.isInteger(group.purchaseCostCents) && ["resolved", "estimated"].includes(group.status));
    if (!isUsable) {
      return {
        ...group,
        isUsable: false,
        sourceClass: PRICE_CONFIDENCE_SOURCE_TYPES.UNRESOLVED,
        reasonCode: group?.status || "incomplete",
        reason: getPriceConfidenceReason(group),
        canOpenPriceEditor: Boolean(group?.ingredientId)
      };
    }
    let sourceClass = PRICE_CONFIDENCE_SOURCE_TYPES.UNRESOLVED;
    if (group.usedFallback) sourceClass = PRICE_CONFIDENCE_SOURCE_TYPES.ESTIMATE_FALLBACK;
    else if (sourceEntry?.sourceType === PRICE_SOURCE_TYPES.USER_ENTERED) sourceClass = PRICE_CONFIDENCE_SOURCE_TYPES.USER_ENTERED;
    else if (sourceEntry?.sourceType === PRICE_SOURCE_TYPES.STORE_PROFILE) sourceClass = PRICE_CONFIDENCE_SOURCE_TYPES.SAVED_PROFILE;
    else if (sourceEntry?.sourceType === PRICE_SOURCE_TYPES.CHEF_NOVA_ESTIMATE) sourceClass = PRICE_CONFIDENCE_SOURCE_TYPES.CHEF_NOVA_ESTIMATE;
    if (sourceClass === PRICE_CONFIDENCE_SOURCE_TYPES.UNRESOLVED) {
      return {
        ...group,
        isUsable: false,
        sourceClass,
        reasonCode: "unresolved-price-source",
        reason: "Chef Nova could not verify the price source for this grocery item.",
        canOpenPriceEditor: Boolean(group.ingredientId)
      };
    }
    return { ...group, isUsable: true, sourceClass, reasonCode: group.status, reason: "", canOpenPriceEditor: Boolean(group.ingredientId) };
  }

  function derivePriceConfidence({ purchaseGroups = [], weeklyCostSummary = {} } = {}) {
    const requiredGroups = (Array.isArray(purchaseGroups) ? purchaseGroups : []).filter((group) => group.missingQuantity > 0 && group.status !== "excluded");
    const classifiedGroups = requiredGroups.map(classifyPurchaseGroupPriceConfidence);
    const usableGroups = classifiedGroups.filter((group) => group.isUsable);
    const unresolvedGroups = classifiedGroups.filter((group) => !group.isUsable);
    const countBySource = (sourceClass) => classifiedGroups.filter((group) => group.sourceClass === sourceClass).length;
    const total = classifiedGroups.length;
    const usable = usableGroups.length;
    const estimateBased = countBySource(PRICE_CONFIDENCE_SOURCE_TYPES.CHEF_NOVA_ESTIMATE) + countBySource(PRICE_CONFIDENCE_SOURCE_TYPES.ESTIMATE_FALLBACK);
    const completeGroceryTotalAvailable = total === 0 || (weeklyCostSummary.weeklyGroceryCostCents !== null && unresolvedGroups.length === 0);
    const weeklyGroceryCostCents = completeGroceryTotalAvailable ? (weeklyCostSummary.weeklyGroceryCostCents ?? 0) : null;
    const weeklyBudgetCents = weeklyCostSummary.weeklyBudgetCents ?? null;
    const knownSubtotalAboveBudgetCents = Number.isInteger(weeklyBudgetCents) && Number.isInteger(weeklyCostSummary.knownPurchaseSubtotalCents)
      ? Math.max(0, weeklyCostSummary.knownPurchaseSubtotalCents - weeklyBudgetCents)
      : null;
    const status = !completeGroceryTotalAvailable || unresolvedGroups.length
      ? PRICE_CONFIDENCE_STATUSES.INCOMPLETE
      : estimateBased > 0 ? PRICE_CONFIDENCE_STATUSES.ESTIMATED : PRICE_CONFIDENCE_STATUSES.HIGH;
    return {
      status,
      totalRequiredGroceryItemCount: total,
      usablePriceItemCount: usable,
      unresolvedItemCount: unresolvedGroups.length,
      userEnteredPriceItemCount: countBySource(PRICE_CONFIDENCE_SOURCE_TYPES.USER_ENTERED),
      savedProfilePriceItemCount: countBySource(PRICE_CONFIDENCE_SOURCE_TYPES.SAVED_PROFILE),
      chefNovaEstimateItemCount: countBySource(PRICE_CONFIDENCE_SOURCE_TYPES.CHEF_NOVA_ESTIMATE),
      estimateFallbackItemCount: countBySource(PRICE_CONFIDENCE_SOURCE_TYPES.ESTIMATE_FALLBACK),
      userConfirmedPriceItemCount: countBySource(PRICE_CONFIDENCE_SOURCE_TYPES.USER_ENTERED) + countBySource(PRICE_CONFIDENCE_SOURCE_TYPES.SAVED_PROFILE),
      estimateBasedPriceItemCount: estimateBased,
      coverageRatio: total ? usable / total : null,
      coveragePercentExact: total ? (usable / total) * 100 : null,
      coveragePercentDisplay: getCoveragePercentDisplay(usable, total),
      completeGroceryTotalAvailable,
      canShowRemainingBudget: completeGroceryTotalAvailable && Number.isInteger(weeklyBudgetCents),
      canClaimWithinBudget: completeGroceryTotalAvailable && Number.isInteger(weeklyBudgetCents) && Number.isInteger(weeklyGroceryCostCents) && weeklyGroceryCostCents <= weeklyBudgetCents,
      canClaimAboveBudget: completeGroceryTotalAvailable && Number.isInteger(weeklyBudgetCents) && Number.isInteger(weeklyGroceryCostCents) && weeklyGroceryCostCents > weeklyBudgetCents,
      knownPurchaseSubtotalCents: weeklyCostSummary.knownPurchaseSubtotalCents ?? 0,
      weeklyGroceryCostCents,
      weeklyBudgetCents,
      knownSubtotalAboveBudgetCents,
      unresolvedItems: unresolvedGroups.map((group) => ({
        purchaseGroupId: group.purchaseGroupId,
        ingredientId: group.ingredientId,
        displayName: getIngredientDisplayNameById(group.ingredientId, group.recipeContributions?.[0]?.displayText || "Grocery item"),
        missingQuantity: group.missingQuantity,
        missingUnit: group.missingUnit,
        reasonCode: group.reasonCode,
        reason: group.reason,
        canOpenPriceEditor: group.canOpenPriceEditor
      })),
      classifiedGroups,
      warnings: unresolvedGroups.length ? ["The final grocery total may be higher."] : ["Actual store prices may vary."]
    };
  }

  function getPlanCostResultForRecipeCard(plan = state.mealPlans) {
    return calculateMealPlanCostsForPlan(plan, state.pantry);
  }

  function createSingleRecipePlan(recipe, selectedServings = recipe?.servings || 1, mealId = "standalone::recipe") {
    const plan = createEmptyMealPlan();
    plan.Monday.Breakfast = { ...createRecipeMealEntry(recipe, selectedServings), mealId };
    return plan;
  }

  function removeMealFromPlan(plan, day, mealType) {
    const nextPlan = cloneMealPlan(plan);
    if (nextPlan[day]) nextPlan[day][mealType] = null;
    return rebuildLeftoverRelationships(nextPlan, buildMealPlanGenerationContext(), normalizeBudgetPlanningRequest(buildMealPlanGenerationContext(), {})).plan;
  }

  function setMealInPlan(plan, day, mealType, entry) {
    const nextPlan = cloneMealPlan(plan);
    nextPlan[day] = nextPlan[day] || {};
    nextPlan[day][mealType] = entry;
    return rebuildLeftoverRelationships(nextPlan, buildMealPlanGenerationContext(), normalizeBudgetPlanningRequest(buildMealPlanGenerationContext(), {})).plan;
  }

  function getWeeklyPurchaseTotal(costResult) {
    return Number.isInteger(costResult?.weeklySummary?.weeklyGroceryCostCents) ? costResult.weeklySummary.weeklyGroceryCostCents : null;
  }

  function deriveRecipeCardNewGrocerySpending({ contextType, plan, day, mealType, meal, recipe, selectedServings }) {
    if (contextType === RECIPE_CARD_CONTEXTS.PLANNED_LEFTOVER_TARGET) {
      return {
        status: Number.isInteger(meal?.additionalCostCents) ? "estimated" : "unavailable",
        cents: Number.isInteger(meal?.additionalCostCents) ? meal.additionalCostCents : null,
        context: NEW_GROCERY_COST_CONTEXTS.LEFTOVER_ADDITIONAL_ONLY,
        label: "Additional grocery cost"
      };
    }
    if (contextType === RECIPE_CARD_CONTEXTS.STANDALONE_RECIPE || !day || !mealType) {
      const singlePlan = createSingleRecipePlan(recipe, selectedServings);
      const result = getPlanCostResultForRecipeCard(singlePlan);
      const confidence = result ? derivePriceConfidence({ purchaseGroups: result.purchaseGroups, weeklyCostSummary: result.weeklySummary }) : null;
      return {
        status: confidence?.completeGroceryTotalAvailable ? "estimated" : "incomplete",
        cents: confidence?.completeGroceryTotalAvailable ? result.weeklySummary.weeklyGroceryCostCents : null,
        knownSubtotalCents: result?.weeklySummary?.knownPurchaseSubtotalCents || 0,
        context: NEW_GROCERY_COST_CONTEXTS.STANDALONE_WITH_CURRENT_PANTRY,
        label: "Estimated grocery purchase cost"
      };
    }
    const currentPlan = plan || suggestedMealPlanReviewState?.draftPlan || state.mealPlans;
    const currentResult = getPlanCostResultForRecipeCard(currentPlan);
    const currentTotal = getWeeklyPurchaseTotal(currentResult);
    if (contextType === RECIPE_CARD_CONTEXTS.REPLACEMENT_CANDIDATE || contextType === RECIPE_CARD_CONTEXTS.PLANNER_CANDIDATE) {
      const basePlan = removeMealFromPlan(currentPlan, day, mealType);
      const baseTotal = getWeeklyPurchaseTotal(getPlanCostResultForRecipeCard(basePlan));
      const candidateEntry = createRecipeMealEntry(recipe, selectedServings);
      const withCandidate = setMealInPlan(basePlan, day, mealType, candidateEntry);
      const candidateTotal = getWeeklyPurchaseTotal(getPlanCostResultForRecipeCard(withCandidate));
      return {
        status: Number.isInteger(candidateTotal) && Number.isInteger(baseTotal) ? "estimated" : "incomplete",
        cents: Number.isInteger(candidateTotal) && Number.isInteger(baseTotal) ? Math.max(0, candidateTotal - baseTotal) : null,
        context: NEW_GROCERY_COST_CONTEXTS.ADDITION_TO_CURRENT_PLAN,
        label: "Additional groceries if selected"
      };
    }
    if (!Number.isInteger(currentTotal)) {
      return { status: "incomplete", cents: null, knownSubtotalCents: currentResult?.weeklySummary?.knownPurchaseSubtotalCents || 0, context: NEW_GROCERY_COST_CONTEXTS.MARGINAL_CURRENT_PLAN, label: contextType === RECIPE_CARD_CONTEXTS.PLANNED_BATCH_SOURCE ? "New groceries for this batch" : "New groceries for this recipe" };
    }
    const withoutMealTotal = getWeeklyPurchaseTotal(getPlanCostResultForRecipeCard(removeMealFromPlan(currentPlan, day, mealType)));
    return {
      status: Number.isInteger(withoutMealTotal) ? "estimated" : "incomplete",
      cents: Number.isInteger(withoutMealTotal) ? Math.max(0, currentTotal - withoutMealTotal) : null,
      context: contextType === RECIPE_CARD_CONTEXTS.PLANNED_BATCH_SOURCE ? NEW_GROCERY_COST_CONTEXTS.SOURCE_BATCH_PRODUCTION_EVENT : NEW_GROCERY_COST_CONTEXTS.MARGINAL_CURRENT_PLAN,
      label: contextType === RECIPE_CARD_CONTEXTS.PLANNED_BATCH_SOURCE ? "New groceries for this batch" : "New groceries for this recipe"
    };
  }

  function getMealPantryRowsForRecipeCard({ mealId, plan }) {
    const allocation = mealId ? buildPantryAllocationForPlan(plan || suggestedMealPlanReviewState?.draftPlan || state.mealPlans) : null;
    return (allocation?.summary?.mealPantryAllocations || []).filter((row) => row.mealId === mealId);
  }

  function deriveRecipeCardPantrySummary({ contextType, mealId, plan, costResult }) {
    if (contextType === RECIPE_CARD_CONTEXTS.PLANNED_LEFTOVER_TARGET) {
      return { coveragePercent: null, coverageStatus: "source-batch", label: "Included in source batch", fullyCoveredRequirementCount: 0, partiallyCoveredRequirementCount: 0, uncoveredRequirementCount: 0, groceryIngredientGroupCount: 0, newlyIntroducedPurchaseGroupCount: 0, rows: [] };
    }
    const rows = getMealPantryRowsForRecipeCard({ mealId, plan });
    if (rows.length) {
      const fully = rows.filter((row) => row.missingQuantity <= 0 && row.pantryQuantityApplied > 0).length;
      const partial = rows.filter((row) => row.missingQuantity > 0 && row.pantryQuantityApplied > 0).length;
      const uncovered = rows.filter((row) => row.missingQuantity > 0 && !row.pantryQuantityApplied).length;
      const score = rows.reduce((sum, row) => {
        if (row.missingQuantity <= 0 && row.pantryQuantityApplied > 0) return sum + 1;
        if (row.pantryQuantityApplied > 0) {
          const required = Number(row.requiredQuantity) || 0;
          return sum + (required > 0 ? Math.min(1, row.pantryQuantityApplied / required) : 0.5);
        }
        return sum;
      }, 0);
      return {
        coveragePercent: rows.length ? Math.round(score / rows.length * 100) : null,
        coverageStatus: "resolved",
        label: rows.length ? `${Math.round(score / rows.length * 100)}%` : "Not available",
        fullyCoveredRequirementCount: fully,
        partiallyCoveredRequirementCount: partial,
        uncoveredRequirementCount: uncovered,
        groceryIngredientGroupCount: new Set(rows.filter((row) => row.missingQuantity > 0).map((row) => row.ingredientId)).size,
        newlyIntroducedPurchaseGroupCount: countNewlyIntroducedPurchaseGroupsForMeal(mealId, plan, costResult),
        rows
      };
    }
    return { coveragePercent: null, coverageStatus: "unavailable", label: "Not available", fullyCoveredRequirementCount: 0, partiallyCoveredRequirementCount: 0, uncoveredRequirementCount: 0, groceryIngredientGroupCount: null, newlyIntroducedPurchaseGroupCount: null, rows: [] };
  }

  function countNewlyIntroducedPurchaseGroupsForMeal(mealId, plan = state.mealPlans, costResult = null) {
    if (!mealId) return null;
    const source = costResult || getPlanCostResultForRecipeCard(plan);
    const currentGroups = new Set((source?.purchaseGroups || []).filter((group) => group.missingQuantity > 0).map((group) => group.purchaseGroupId));
    const meal = findMealByMealId(plan, mealId);
    if (!meal) return null;
    const without = getPlanCostResultForRecipeCard(removeMealFromPlan(plan, meal.day, meal.mealType));
    const withoutGroups = new Set((without?.purchaseGroups || []).filter((group) => group.missingQuantity > 0).map((group) => group.purchaseGroupId));
    return Array.from(currentGroups).filter((id) => !withoutGroups.has(id)).length;
  }

  function getRecipeCardContextType(entry, cardContext) {
    if (cardContext && Object.values(RECIPE_CARD_CONTEXTS).includes(cardContext)) return cardContext;
    if (entry?.mealType === "leftover") return RECIPE_CARD_CONTEXTS.PLANNED_LEFTOVER_TARGET;
    if (Number(entry?.reservedLeftoverServings) > 0) return RECIPE_CARD_CONTEXTS.PLANNED_BATCH_SOURCE;
    return entry ? RECIPE_CARD_CONTEXTS.PLANNED_NORMAL_MEAL : RECIPE_CARD_CONTEXTS.STANDALONE_RECIPE;
  }

  function getRecipeCardServingSummary({ recipe, meal, selectedServings, contextType, plan }) {
    const effectiveServings = Number(meal?.plannedRecipeServings || selectedServings || meal?.servings || recipe?.servings || 1);
    if (contextType === RECIPE_CARD_CONTEXTS.PLANNED_LEFTOVER_TARGET) {
      const source = findMealByMealId(plan || state.mealPlans, meal?.leftoverFromMealId);
      return {
        effectiveServings: Number(meal?.servings || 1),
        householdServings: Number(meal?.servings || 1),
        reservedLeftoverServings: 0,
        unallocatedSurplusServings: 0,
        label: `Serves ${formatServingAmount(meal?.servings || 1)} leftover ${Number(meal?.servings) === 1 ? "portion" : "portions"}${source ? ` from ${source.day} ${source.mealType.toLowerCase()}` : ""}`
      };
    }
    if (contextType === RECIPE_CARD_CONTEXTS.PLANNED_BATCH_SOURCE) {
      return {
        effectiveServings,
        householdServings: Number(meal?.householdServings || meal?.servings || effectiveServings),
        reservedLeftoverServings: Number(meal?.reservedLeftoverServings || 0),
        unallocatedSurplusServings: Number(meal?.unallocatedSurplusServings || 0),
        label: `Serves ${formatServingAmount(effectiveServings)} total`
      };
    }
    return {
      effectiveServings,
      householdServings: Number(meal?.householdServings || meal?.servings || selectedServings || effectiveServings),
      reservedLeftoverServings: 0,
      unallocatedSurplusServings: 0,
      label: `Serves ${formatServingAmount(effectiveServings)}`
    };
  }

  function getRecipeCardTimeSummary(recipe, meal, contextType) {
    if (contextType === RECIPE_CARD_CONTEXTS.PLANNED_LEFTOVER_TARGET) {
      const method = findLeftoverReheatingMethod(recipe, meal?.reheatingMethodId);
      return { effectiveTimeMinutes: method?.reheatingTimeMinutes || null, label: method ? `Reheating: about ${method.reheatingTimeMinutes} minutes` : "Reheating time unavailable" };
    }
    const minutes = getRecipeTotalMinutes(recipe);
    const extra = (meal?.appliedSubstitutions || []).length ? " with current substitutions" : "";
    const batch = contextType === RECIPE_CARD_CONTEXTS.PLANNED_BATCH_SOURCE ? "Batch cooking: " : "Cooking time: ";
    return { effectiveTimeMinutes: Number.isFinite(minutes) ? minutes : null, label: Number.isFinite(minutes) ? `${batch}${minutes} minutes${extra}` : "Cooking time unavailable" };
  }

  function getRecipeCardIngredientBreakdown(recipeCostSummary, pantryRows = []) {
    const pantryByIngredient = new Map(pantryRows.map((row) => [row.ingredientId, row]));
    return (recipeCostSummary?.ingredientCostResults || []).map((result) => {
      const pantry = pantryByIngredient.get(result.ingredientId) || {};
      const ingredientName = result.displayName || result.ingredient?.displayName || getIngredientDisplayNameById(result.ingredientId, result.displayText || "Ingredient");
      const statusText = Number.isInteger(result.ingredientUseCostCents)
        ? formatCostCents(result.ingredientUseCostCents)
        : result.status === "missing-quantity" ? "Quantity needed" : "Price needed";
      return {
        ingredientOccurrenceId: result.ingredientOccurrenceId || `${result.recipeId || recipeCostSummary.recipeId}::ingredient-${result.ingredientIndex}`,
        ingredientId: result.ingredientId,
        displayName: ingredientName,
        displayText: result.displayText || ingredientName,
        requiredQuantity: pantry.requiredQuantity ?? result.normalizedRequiredQuantity,
        requiredUnit: pantry.requiredUnit || result.normalizedRequiredUnit || "",
        pantryQuantityApplied: pantry.pantryQuantityApplied || 0,
        missingQuantity: pantry.missingQuantity,
        missingUnit: pantry.missingUnit || pantry.requiredUnit || "",
        estimatedIngredientUseCostCents: Number.isInteger(result.ingredientUseCostCents) ? result.ingredientUseCostCents : null,
        costStatus: result.status,
        priceSourceLabel: getRecipeCardPriceSourceLabel(result),
        usingSalePrice: result.usingSalePrice === true,
        warnings: result.warnings || [],
        statusText
      };
    });
  }

  function getRecipeCardPriceSourceLabel(result) {
    if (!result?.priceEntryId) return result?.status === "missing-price" ? "Price needed" : "Price source unavailable";
    const entry = findResolvedPriceEntryById(result.priceEntryId);
    if (!entry) return "Price source unavailable";
    if (entry.sourceType === PRICE_SOURCE_TYPES.USER_ENTERED) return "Your approximate price for this plan";
    if (entry.sourceType === PRICE_SOURCE_TYPES.STORE_PROFILE) return "Saved store price profile";
    if (entry.sourceType === PRICE_SOURCE_TYPES.CHEF_NOVA_ESTIMATE) return "Chef Nova estimate";
    return "Price source unavailable";
  }

  function deriveRecipeCardCostModel({
    recipe,
    recipeVariant = null,
    meal = null,
    cardContext = null,
    selectedServings = null,
    plan = null,
    day = "",
    mealType = "",
    recipeCostResult = null,
    planCostResult = null,
    eligibilityResult = null
  } = {}) {
    const entry = normalizeMealPlanEntry(meal);
    const effectiveRecipe = normalizeRecipe(recipeVariant || getRecipeForMealEntry(meal) || recipe);
    if (!effectiveRecipe?.id) return null;
    const contextType = getRecipeCardContextType(meal, cardContext);
    const currentPlan = plan || suggestedMealPlanReviewState?.draftPlan || state.mealPlans;
    const mealId = meal?.mealId || (day && mealType ? getPlanMealId(day, mealType) : "");
    const servingSummary = getRecipeCardServingSummary({ recipe: effectiveRecipe, meal, selectedServings, contextType, plan: currentPlan });
    const selected = Number(selectedServings || meal?.plannedRecipeServings || meal?.servings || servingSummary.effectiveServings || effectiveRecipe.servings || 1);
    const summary = recipeCostResult || calculateRecipeCostForDisplay(effectiveRecipe, selected);
    const currentPlanCost = planCostResult || (mealId ? getPlanCostResultForRecipeCard(currentPlan) : null);
    const confidence = currentPlanCost ? derivePriceConfidence({ purchaseGroups: currentPlanCost.purchaseGroups, weeklyCostSummary: currentPlanCost.weeklySummary }) : null;
    const pantrySummary = deriveRecipeCardPantrySummary({ contextType, mealId, plan: currentPlan, costResult: currentPlanCost });
    const grocery = deriveRecipeCardNewGrocerySpending({ contextType, plan: currentPlan, day, mealType, meal, recipe: effectiveRecipe, selectedServings: selected });
    const completeRecipeCost = Number.isInteger(summary?.totalRecipeCostCents);
    const compatibility = eligibilityResult || (entry?.recipeId ? evaluateRecipeForCurrentRequirements(effectiveRecipe, buildMealPlanGenerationContext(), { requiredServings: entry.servings || selected }) : null);
    const requiresReview = compatibility && compatibility.status !== RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE && compatibility.canUseForAutomaticPlanning !== true;
    const appliedSubstitutions = Array.isArray(meal?.appliedSubstitutions) ? meal.appliedSubstitutions : effectiveRecipe.appliedSubstitutions || [];
    return {
      cardId: mealId || `recipe-card-${effectiveRecipe.id}`,
      contextType,
      mealId,
      recipeId: effectiveRecipe.id,
      variantId: effectiveRecipe.variantId || meal?.variantId || meal?.recipeVariantId || null,
      title: effectiveRecipe.name,
      servingSummary,
      costSummary: {
        ingredientValueStatus: completeRecipeCost ? summary.status || "estimated" : "incomplete",
        estimatedIngredientValueCents: completeRecipeCost ? summary.totalRecipeCostCents : null,
        knownIngredientValueCents: summary?.knownIngredientCostSubtotalCents || 0,
        costPerServingCents: completeRecipeCost ? summary.costPerServingCents : null,
        newGrocerySpendingStatus: grocery.status,
        newGrocerySpendingCents: grocery.cents,
        newGroceryKnownSubtotalCents: grocery.knownSubtotalCents || 0,
        newGrocerySpendingContext: grocery.context,
        newGrocerySpendingLabel: grocery.label,
        priceConfidenceLabel: confidence ? priceConfidenceStatusLabel(confidence.status) : priceConfidenceStatusLabel(summary?.status === "incomplete" ? PRICE_CONFIDENCE_STATUSES.INCOMPLETE : PRICE_CONFIDENCE_STATUSES.ESTIMATED),
        recipeCostComplete: completeRecipeCost,
        purchaseCostComplete: grocery.status === "estimated"
      },
      pantrySummary,
      timeSummary: getRecipeCardTimeSummary(effectiveRecipe, meal, contextType),
      ingredientBreakdown: getRecipeCardIngredientBreakdown(summary, pantrySummary.rows),
      appliedSubstitutions,
      actions: { canViewCostBreakdown: true, canReplaceMeal: Boolean(day && mealType && entry?.recipeId), canViewPriceDetails: true, canReviewPantryUse: pantrySummary.rows.length > 0 },
      warnings: [
        ...(requiresReview ? [compatibility.exclusionReasons?.[0]?.message || "This meal requires review."] : []),
        ...(!completeRecipeCost && summary?.unresolvedIngredientCount ? [`${summary.unresolvedIngredientCount} ${pluralize(summary.unresolvedIngredientCount, "ingredient")} need a price or measurable quantity.`] : []),
        ...(grocery.status === "incomplete" ? ["New grocery spending is incomplete until purchase prices and quantities are resolved."] : [])
      ]
    };
  }

  function getRecipeCardPrimaryCostLabel(model) {
    if (model.contextType === RECIPE_CARD_CONTEXTS.PLANNED_LEFTOVER_TARGET) return "Estimated portion value";
    if (model.contextType === RECIPE_CARD_CONTEXTS.PLANNED_BATCH_SOURCE) return "Estimated batch ingredient value";
    if (model.contextType === RECIPE_CARD_CONTEXTS.REPLACEMENT_CANDIDATE) return "Estimated ingredient value";
    return "Estimated recipe cost";
  }

  function renderRecipeCardCostSummary(modelOrRecipe, options = {}) {
    const model = modelOrRecipe?.costSummary ? modelOrRecipe : deriveRecipeCardCostModel({ recipe: modelOrRecipe, ...options });
    if (!model) return "";
    const cost = model.costSummary;
    const primaryLabel = getRecipeCardPrimaryCostLabel(model);
    const primaryValue = cost.recipeCostComplete ? formatCostCents(cost.estimatedIngredientValueCents) : `Known: ${formatCostCents(cost.knownIngredientValueCents)}`;
    const groceryValue = cost.purchaseCostComplete ? formatCostCents(cost.newGrocerySpendingCents) : cost.newGroceryKnownSubtotalCents ? `Known: ${formatCostCents(cost.newGroceryKnownSubtotalCents)}` : "Not available";
    const pantryValue = model.pantrySummary.coverageStatus === "source-batch" ? model.pantrySummary.label : Number.isInteger(model.pantrySummary.coveragePercent) ? `${model.pantrySummary.coveragePercent}%` : "Not available";
    const rows = [
      [primaryLabel, primaryValue],
      ["Cost per serving", Number.isInteger(cost.costPerServingCents) ? formatCostCents(cost.costPerServingCents) : "Not available"],
      ["Serves", model.servingSummary.label.replace(/^Serves\s*/i, "")],
      ["Pantry coverage", pantryValue],
      ["New ingredients needed", Number.isInteger(model.pantrySummary.groceryIngredientGroupCount) ? String(model.pantrySummary.groceryIngredientGroupCount) : "Not available"],
      ["Cooking time", model.timeSummary.label.replace(/^Cooking time:\s*/i, "").replace(/^Batch cooking:\s*/i, "")]
    ];
    const warning = model.warnings.length ? `<p class="recipe-card-cost-warning" role="status">${escapeHtml(model.warnings[0])}</p>` : "";
    return `<section class="recipe-card-cost-summary ${cost.recipeCostComplete ? "" : "incomplete"}" aria-label="Recipe card cost summary">
      <dl class="recipe-cost-stats">${rows.map(([term, value]) => `<div class="recipe-stat"><dt class="recipe-stat__label">${escapeHtml(term)}</dt><dd class="recipe-stat__value">${escapeHtml(value)}</dd></div>`).join("")}</dl>
      <p class="recipe-card-cost-confidence">Price confidence: ${escapeHtml(cost.priceConfidenceLabel)}</p>
      ${warning}
      ${renderRecipeCardCostBreakdown(model)}
    </section>`;
  }

  function renderRecipeCardCostBreakdown(model) {
    const cost = model.costSummary;
    const groceryValue = cost.purchaseCostComplete ? formatCostCents(cost.newGrocerySpendingCents) : "Not available";
    const ingredientRows = model.ingredientBreakdown.length ? model.ingredientBreakdown.map((row) => `<li>
      <span><b>${escapeHtml(row.displayName)}</b><small>${escapeHtml(row.displayText || "")}</small></span>
      <strong>${escapeHtml(row.statusText)}</strong>
      <small>Required: ${escapeHtml(formatQuantityForDisplay(row.requiredQuantity))} ${escapeHtml(row.requiredUnit || "")}. Used from Pantry: ${escapeHtml(formatQuantityForDisplay(row.pantryQuantityApplied || 0))} ${escapeHtml(row.requiredUnit || "")}. Need to buy: ${escapeHtml(row.missingQuantity === undefined ? "unknown" : formatQuantityForDisplay(row.missingQuantity))} ${escapeHtml(row.missingUnit || row.requiredUnit || "")}. Price source: ${escapeHtml(row.priceSourceLabel)}${row.usingSalePrice ? ". Using active saved sale price." : ""}${row.warnings.length ? ` ${escapeHtml(row.warnings.join(" "))}` : ""}</small>
    </li>`).join("") : `<li><span><b>No ingredient cost rows available</b></span><strong>Unavailable</strong></li>`;
    const substitutions = model.appliedSubstitutions.length ? `<section><h5>Applied substitution</h5><ul>${model.appliedSubstitutions.map((item) => `<li>${escapeHtml(getIngredientDisplayNameById(item.originalIngredientId, "Original ingredient"))} -> ${escapeHtml(getIngredientDisplayNameById(item.alternativeIngredientId, "replacement ingredient"))}. ${escapeHtml(SUBSTITUTION_CAUTION)}</li>`).join("")}</ul></section>` : "";
    return `<details class="recipe-card-cost-breakdown">
      <summary>View Cost Breakdown</summary>
      <div class="recipe-card-cost-breakdown-body">
        <section>
          <h5>Ingredient costs</h5>
          <ul class="recipe-card-cost-lines">${ingredientRows}</ul>
          <dl class="recipe-card-cost-totals">
            <div><dt>${escapeHtml(getRecipeCardPrimaryCostLabel(model))}</dt><dd>${escapeHtml(cost.recipeCostComplete ? formatCostCents(cost.estimatedIngredientValueCents) : `Known ingredient value: ${formatCostCents(cost.knownIngredientValueCents)}`)}</dd></div>
            <div><dt>Cost per serving</dt><dd>${escapeHtml(Number.isInteger(cost.costPerServingCents) ? formatCostCents(cost.costPerServingCents) : "Not available")}</dd></div>
          </dl>
        </section>
        <section>
          <h5>New grocery spending</h5>
          <p><b>${escapeHtml(cost.newGrocerySpendingLabel)}:</b> ${escapeHtml(groceryValue)}</p>
          <p>Ingredient value includes Pantry food and partial-package value. New grocery spending estimates checkout cost in this card's context.</p>
          <p>Meal-level grocery estimates are context-sensitive and should not be added together. The Budget Status panel contains the weekly grocery total.</p>
        </section>
        <section>
          <h5>Pantry contribution</h5>
          <p>Pantry coverage: ${escapeHtml(Number.isInteger(model.pantrySummary.coveragePercent) ? `${model.pantrySummary.coveragePercent}%` : model.pantrySummary.label)}</p>
          <p>${escapeHtml(`${model.pantrySummary.fullyCoveredRequirementCount} fully covered, ${model.pantrySummary.partiallyCoveredRequirementCount} partially covered, ${model.pantrySummary.uncoveredRequirementCount} need groceries.`)}</p>
          ${Number.isInteger(model.pantrySummary.newlyIntroducedPurchaseGroupCount) ? `<p>New groups introduced to the weekly list: ${escapeHtml(String(model.pantrySummary.newlyIntroducedPurchaseGroupCount))}</p>` : ""}
        </section>
        <section>
          <h5>Price information</h5>
          <p>Price confidence: ${escapeHtml(cost.priceConfidenceLabel)}. Actual store prices may vary.</p>
        </section>
        ${substitutions}
      </div>
    </details>`;
  }

  function renderRecipeCostSummary(recipe, selectedServings = recipe?.servings || 1) {
    return renderRecipeCardCostSummary(recipe, { selectedServings, cardContext: RECIPE_CARD_CONTEXTS.STANDALONE_RECIPE });
  }

  function isIntegratedPlanningMode(mode = getCurrentPlanningMode()) {
    return INTEGRATED_PLANNING_MODES.includes(normalizePlanningMode(mode));
  }

  function createIntegratedPlanningContext({
    planMode = getCurrentPlanningMode(),
    plan = state.mealPlans,
    startLocalDate = getCurrentDateString(),
    endLocalDate = addCalendarDays(startLocalDate, 6)
  } = {}) {
    const normalizedMode = normalizePlanningMode(planMode);
    const budgetInputs = normalizePlanningModeInputs(state.planningModeInputs);
    const priorityModel = getUseFirstPriorityModel(getActivePantryItems());
    const costResult = [PLANNING_MODES.BUDGET_RESCUE, PLANNING_MODES.EMERGENCY].includes(normalizedMode)
      ? calculateMealPlanCostsForPlan(plan, state.pantry)
      : null;
    const priceConfidence = costResult ? derivePriceConfidence({ purchaseGroups: costResult.purchaseGroups, weeklyCostSummary: costResult.weeklySummary }) : null;
    return {
      contextVersion: INTEGRATED_PLANNING_CONTEXT_VERSION,
      planMode: normalizedMode,
      plan: normalizeMealPlan(plan),
      period: { startLocalDate, endLocalDate },
      userScope: getActiveUserScopeId(),
      household: {
        defaultServings: getFoodRescueRequiredServings(),
        budgetServings: budgetInputs.budgetRescue?.household?.suggestedServings || getFoodRescueRequiredServings()
      },
      sourceRevisions: {
        pantrySignature: buildPantrySignature(state.pantry),
        planSignature: buildMealPlanSignature(plan),
        recipeCount: state.recipes.length,
        priceConfidenceStatus: priceConfidence?.status || null,
        priorityEngineVersion: priorityModel.priorityEngineVersion,
        costEngineAvailable: typeof COST_ENGINE.calculateMealPlanCosts === "function",
        pantryFirstAvailable: typeof PANTRY_FIRST.createPlanningInventory === "function"
      },
      budget: {
        enabled: [PLANNING_MODES.BUDGET_RESCUE, PLANNING_MODES.EMERGENCY].includes(normalizedMode),
        weeklyBudgetCents: costResult?.weeklySummary?.weeklyBudgetCents ?? budgetInputs.budgetRescue?.weeklyBudgetCents ?? null,
        weeklyGroceryCostCents: priceConfidence?.completeGroceryTotalAvailable ? costResult.weeklySummary.weeklyGroceryCostCents : null,
        knownPurchaseSubtotalCents: costResult?.weeklySummary?.knownPurchaseSubtotalCents || 0,
        priceConfidence
      },
      rescue: {
        enabled: [PLANNING_MODES.BUDGET_RESCUE, PLANNING_MODES.COOK_BEFORE_IT_SPOILS, PLANNING_MODES.EMERGENCY].includes(normalizedMode),
        priorityModel,
        priorityItems: priorityModel.results.filter((result) => result.attentionPriority?.score > 0 || result.rescueRecipePriority?.score > 0)
      },
      creditPolicy: PRIORITY_USE_CREDIT_POLICY
    };
  }

  function buildTemporaryPlanningInventory(context = createIntegratedPlanningContext()) {
    const pantryItems = getActivePantryItems().map((item) => normalizePantryItem(structuredCloneSafe(item)));
    return {
      inventoryVersion: INTEGRATED_PLANNING_CONTEXT_VERSION,
      contextSignature: context.sourceRevisions?.pantrySignature || "",
      mutatesPantry: false,
      items: pantryItems,
      planningInventory: typeof PANTRY_FIRST.createPlanningInventory === "function"
        ? PANTRY_FIRST.createPlanningInventory({
          pantryItems,
          ingredientResolver: resolveCanonicalIngredientName,
          planStartDate: context.period.startLocalDate,
          planEndDate: context.period.endLocalDate
        })
        : null
    };
  }

  function mapIntegratedHardExclusionCode(reason = {}) {
    const code = String(reason.code || reason.reasonCode || reason.type || "").toLowerCase();
    if (code.includes("allerg")) return INTEGRATED_HARD_EXCLUSION_CODES.ALLERGY;
    if (code.includes("diet")) return INTEGRATED_HARD_EXCLUSION_CODES.DIETARY;
    if (code.includes("safety") || code.includes("raw") || code.includes("expired")) return INTEGRATED_HARD_EXCLUSION_CODES.SAFETY;
    if (code.includes("date") || code.includes("storage") || code.includes("timeline")) return INTEGRATED_HARD_EXCLUSION_CODES.TRUE_EXPIRATION_OR_STORAGE_TIMELINE;
    if (code.includes("appliance") || code.includes("equipment")) return INTEGRATED_HARD_EXCLUSION_CODES.APPLIANCE;
    if (code.includes("time")) return INTEGRATED_HARD_EXCLUSION_CODES.TIME;
    if (code.includes("serving") || code.includes("portion")) return INTEGRATED_HARD_EXCLUSION_CODES.SERVINGS;
    if (code.includes("form")) return INTEGRATED_HARD_EXCLUSION_CODES.FORM;
    if (code.includes("leftover")) return INTEGRATED_HARD_EXCLUSION_CODES.LEFTOVER_ELIGIBILITY;
    if (code.includes("ingredient") || code.includes("substitution")) return INTEGRATED_HARD_EXCLUSION_CODES.MANDATORY_INGREDIENT_OR_SUBSTITUTION;
    if (code.includes("inventory") || code.includes("quantity")) return INTEGRATED_HARD_EXCLUSION_CODES.PHYSICAL_INVENTORY;
    return INTEGRATED_HARD_EXCLUSION_CODES.SAFETY;
  }

  function evaluateIntegratedHardEligibility(recipe, { mealSlot = null, context = createIntegratedPlanningContext() } = {}) {
    const selectedServings = Number(mealSlot?.servings || context.household.defaultServings || recipe?.servings || 1);
    const eligibility = evaluateRecipeForCurrentRequirements(
      normalizeRecipe(recipe),
      { userProfile: getProfile(), planningMode: context.planMode, integratedPlanningContext: context },
      {
        includeIngredientAvailability: true,
        requiredServings: selectedServings,
        pantryItems: getActivePantryItems(),
        requireStructuredQuantities: true
      }
    );
    const eligible = eligibility.status === RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE || eligibility.canUseForAutomaticPlanning === true;
    return {
      hardEligibilityVersion: INTEGRATED_HARD_ELIGIBILITY_VERSION,
      eligible,
      selectable: eligible,
      precedence: Object.values(INTEGRATED_HARD_EXCLUSION_CODES),
      eligibility,
      exclusionCodes: eligible ? [] : (eligibility.exclusionReasons || []).map(mapIntegratedHardExclusionCode),
      message: eligible ? "Eligible before budget and rescue scoring." : eligibility.exclusionReasons?.[0]?.message || "This recipe is not eligible for the current plan."
    };
  }

  function evaluateIntegratedPantryAllocation(recipe, { mealSlot = null, context = createIntegratedPlanningContext(), temporaryInventory = buildTemporaryPlanningInventory(context) } = {}) {
    const selectedServings = Number(mealSlot?.servings || context.household.defaultServings || recipe?.servings || 1);
    if (temporaryInventory.planningInventory && typeof PANTRY_FIRST.simulateRecipeAgainstInventory === "function") {
      return PANTRY_FIRST.simulateRecipeAgainstInventory({
        recipe: normalizeRecipe(recipe),
        selectedServings,
        planningInventory: temporaryInventory.planningInventory
      });
    }
    const match = calculatePantryMatch(recipe, temporaryInventory.items);
    return { pantryCoverageRatio: (match.percentage || 0) / 100, requirementAllocations: [], summary: { ingredientGroupCountUsed: match.matched || 0 } };
  }

  function evaluateIntegratedRescueBenefit(recipe, { mealSlot = null, context = createIntegratedPlanningContext(), pantryAllocation = null } = {}) {
    const selectedServings = Number(mealSlot?.servings || context.household.defaultServings || recipe?.servings || 1);
    const prioritySources = context.rescue.priorityItems.map((result) => normalizeFoodRescueSourceFromPanelEntry({
      sourceType: RESCUE_SOURCE_TYPES.PANTRY_ITEM,
      pantryItemId: result.pantryItemId || result.pantryItem?.id,
      priority: result
    })).filter(Boolean);
    const usage = prioritySources.length ? calculateFoodRescueSelectedFoodUsage(normalizeRecipe(recipe), prioritySources, selectedServings) : { sourceUses: [], weightedCoverageRatio: 0, meaningfullyUsedSourceCount: 0 };
    const priorityItemsUsed = usage.sourceUses.filter((source) => source.usedQuantity > 0).map((source) => ({
      pantryItemId: source.pantryItemId,
      rescueSourceId: source.rescueSourceId,
      name: source.displayName || "Priority ingredient",
      plannedQuantity: source.usedQuantity,
      unit: source.unit || "",
      priorityLevel: source.priorityLevel,
      dateType: source.dateSummary?.primaryDateType || source.dateSummary?.dateType || null,
      rescueWindowStatus: source.dateSummary?.attentionStatus || null,
      priorityDate: source.dateSummary?.relevantDate || null,
      openedPackage: [PANTRY_PACKAGE_STATES.OPENED, PANTRY_PACKAGE_STATES.RESEALED].includes(source.packageState || source.storage?.packageState),
      storage: source.storage?.location || null
    }));
    return {
      rescueEvaluationVersion: INTEGRATED_RESCUE_EVALUATION_VERSION,
      plannedOnly: true,
      impactCreditOnSave: false,
      plannedRescueBenefitStatus: priorityItemsUsed.length ? "planned-priority-use" : "none",
      priorityItemsUsed,
      rescueCoverageRatio: usage.weightedCoverageRatio || pantryAllocation?.pantryCoverageRatio || 0,
      recipeRescueCoveragePercent: Math.round((usage.weightedCoverageRatio || 0) * 100),
      openedPackageCountUsed: priorityItemsUsed.filter((item) => item.openedPackage).length,
      temporaryAllocationOnly: true
    };
  }

  function sumEstimatedPantryValueFromCostModel(costModel) {
    if (!costModel?.ingredientBreakdown?.length) return { cents: null, knownCents: 0, missingPriceCount: 0 };
    let knownCents = 0;
    let missingPriceCount = 0;
    costModel.ingredientBreakdown.forEach((row) => {
      if (!(Number(row.pantryQuantityApplied) > 0)) return;
      if (Number.isInteger(row.estimatedIngredientUseCostCents)) knownCents += row.estimatedIngredientUseCostCents;
      else missingPriceCount += 1;
    });
    return { cents: missingPriceCount ? null : knownCents, knownCents, missingPriceCount };
  }

  function evaluateIntegratedBudgetBenefit(recipe, { mealSlot = null, context = createIntegratedPlanningContext() } = {}) {
    const day = mealSlot?.day || "";
    const mealType = mealSlot?.mealType || "";
    const entry = mealSlot?.entry || (recipe ? createRecipeMealEntry(recipe, mealSlot?.servings || recipe.servings || 1) : null);
    const costModel = deriveRecipeCardCostModel({
      recipe,
      meal: entry,
      plan: context.plan,
      day,
      mealType,
      selectedServings: entry?.servings || recipe?.servings || 1,
      cardContext: getRecipeCardContextType(entry, null)
    });
    const pantryValue = sumEstimatedPantryValueFromCostModel(costModel);
    const newGrocery = costModel?.costSummary?.purchaseCostComplete
      ? { cents: costModel.costSummary.newGrocerySpendingCents, status: "estimated" }
      : { cents: null, knownCents: costModel?.costSummary?.newGroceryKnownSubtotalCents || 0, status: "incomplete" };
    return {
      budgetEvaluationVersion: INTEGRATED_BUDGET_EVALUATION_VERSION,
      pantryValueUsedCents: pantryValue.cents,
      knownPantryValueUsedCents: pantryValue.knownCents,
      missingPantryPriceCount: pantryValue.missingPriceCount,
      marginalNewPurchaseCostCents: newGrocery.cents,
      knownNewPurchaseSubtotalCents: newGrocery.knownCents || 0,
      newPurchaseCostStatus: newGrocery.status,
      priceConfidenceStatus: costModel?.costSummary?.priceConfidenceLabel || context.budget.priceConfidence?.status || "Incomplete estimate",
      budgetFitStatus: context.budget.enabled && Number.isInteger(context.budget.weeklyGroceryCostCents) && Number.isInteger(context.budget.weeklyBudgetCents)
        ? context.budget.weeklyGroceryCostCents <= context.budget.weeklyBudgetCents ? "within-budget" : "above-budget"
        : "not-confirmed",
      sharedPackagesCountedOnceWeekly: true,
      pantryValueIsNotCheckoutCost: true,
      costModel
    };
  }

  function evaluateIntegratedPracticality(recipe, { mealSlot = null } = {}) {
    const minutes = getRecipeTotalMinutes(recipe);
    const servings = Number(mealSlot?.servings || recipe?.servings || 1);
    return {
      practicalityEvaluationVersion: INTEGRATED_PRACTICALITY_EVALUATION_VERSION,
      totalTimeMinutes: Number.isFinite(minutes) ? minutes : null,
      servingFit: servings > 0,
      score: calculateRecipeTimeScore(recipe)
    };
  }

  function calculateIntegratedCandidateScore({ rescue, budget, practicality } = {}) {
    const rescueScore = Math.round((rescue?.rescueCoverageRatio || 0) * 100);
    const knownBudgetScore = budget?.newPurchaseCostStatus === "estimated" && Number.isInteger(budget.marginalNewPurchaseCostCents)
      ? Math.max(0, 100 - Math.min(100, budget.marginalNewPurchaseCostCents / 100))
      : 45;
    const practicalScore = Number(practicality?.score) || 0;
    return Math.round(
      rescueScore * INTEGRATED_BUDGET_RESCUE_SCORE_CONFIG.weights.rescue
      + knownBudgetScore * INTEGRATED_BUDGET_RESCUE_SCORE_CONFIG.weights.budget
      + practicalScore * INTEGRATED_BUDGET_RESCUE_SCORE_CONFIG.weights.practicality
    );
  }

  function evaluateIntegratedRecipeCandidate(recipe, mealSlot = {}, context = createIntegratedPlanningContext()) {
    const temporaryInventory = buildTemporaryPlanningInventory(context);
    const hard = evaluateIntegratedHardEligibility(recipe, { mealSlot, context });
    if (!hard.eligible) {
      return {
        candidateEvaluationVersion: INTEGRATED_CANDIDATE_EVALUATION_VERSION,
        recipeId: recipe?.id || "",
        hardEligibility: hard,
        rescueBenefit: null,
        budgetBenefit: null,
        practicality: null,
        finalScore: null,
        selectable: false,
        exclusionCodes: hard.exclusionCodes
      };
    }
    const pantryAllocation = evaluateIntegratedPantryAllocation(recipe, { mealSlot, context, temporaryInventory });
    const rescue = evaluateIntegratedRescueBenefit(recipe, { mealSlot, context, pantryAllocation });
    const budget = evaluateIntegratedBudgetBenefit(recipe, { mealSlot, context });
    const practicality = evaluateIntegratedPracticality(recipe, { mealSlot });
    return {
      candidateEvaluationVersion: INTEGRATED_CANDIDATE_EVALUATION_VERSION,
      recipeId: recipe?.id || "",
      hardEligibility: hard,
      pantryAllocation,
      rescueBenefit: rescue,
      budgetBenefit: budget,
      practicality,
      finalScore: calculateIntegratedCandidateScore({ rescue, budget, practicality }),
      selectable: true,
      exclusionCodes: []
    };
  }

  function buildRecipeBenefitSummary(evaluation) {
    if (!evaluation || evaluation.selectable === false) return null;
    const rescue = evaluation.rescueBenefit || {};
    const budget = evaluation.budgetBenefit || {};
    const practicality = evaluation.practicality || {};
    const plannedItems = rescue.priorityItemsUsed || [];
    return {
      summaryVersion: RECIPE_BENEFIT_SUMMARY_VERSION,
      plannedFoodRescueBenefit: plannedItems.length
        ? `Planned to use ${plannedItems.length} priority ${pluralize(plannedItems.length, "item")}.`
        : "No priority Pantry item planned for this meal.",
      budgetBenefit: Number.isInteger(budget.marginalNewPurchaseCostCents)
        ? `Estimated new grocery allocation: ${formatCostCents(budget.marginalNewPurchaseCostCents)}.`
        : `Estimated new grocery allocation incomplete. Known subtotal: ${formatCostCents(budget.knownNewPurchaseSubtotalCents || 0)}.`,
      pantryValue: Number.isInteger(budget.pantryValueUsedCents)
        ? `Estimated Pantry value used: ${formatCostCents(budget.pantryValueUsedCents)}.`
        : `Estimated Pantry value used unavailable${budget.knownPantryValueUsedCents ? `; known value: ${formatCostCents(budget.knownPantryValueUsedCents)}` : ""}.`,
      practicalBenefit: Number.isFinite(practicality.totalTimeMinutes) ? `Practical benefit: about ${practicality.totalTimeMinutes} minutes.` : "Practical benefit: time unavailable.",
      whyChosen: plannedItems.length ? "Why chosen: it can use food that needs attention while keeping budget checks separate." : "Why chosen: it fits current recipe, budget, and pantry checks.",
      priorityItems: plannedItems.slice(0, 4),
      priceNote: "Weekly checkout totals use full package prices and count shared packages once.",
      plannedOnlyNote: "Planned food-rescue benefit is not confirmed impact."
    };
  }

  function renderIntegratedRecipeBenefitSummary(summary) {
    if (!isIntegratedPlanningMode()) return "";
    if (!summary) return "";
    const priorityItems = summary.priorityItems.length
      ? `<ul>${summary.priorityItems.map((item) => `<li>${escapeHtml(item.name)}${item.priorityDate ? ` · ${escapeHtml(formatDate(item.priorityDate))}` : ""}${item.unit ? ` · planned to use ${escapeHtml(formatQuantityForDisplay(item.plannedQuantity))} ${escapeHtml(item.unit)}` : ""}</li>`).join("")}</ul>`
      : "";
    return `<section class="integrated-benefit-card" aria-label="Planned budget and food rescue benefit">
      <div class="integrated-benefit-grid">
        <article class="planned-rescue-benefit"><h5>Planned food-rescue benefit</h5><p>${escapeHtml(summary.plannedFoodRescueBenefit)}</p>${priorityItems}</article>
        <article class="budget-benefit"><h5>Budget benefit</h5><p>${escapeHtml(summary.pantryValue)}</p><p>${escapeHtml(summary.budgetBenefit)}</p></article>
        <article class="practical-plan-benefit"><h5>Practical benefit</h5><p>${escapeHtml(summary.practicalBenefit)}</p><p>${escapeHtml(summary.whyChosen)}</p></article>
      </div>
      <p class="integrated-benefit-note">${escapeHtml(summary.priceNote || "Weekly checkout totals use full package prices and count shared packages once.")} ${escapeHtml(summary.plannedOnlyNote || "Planned food-rescue benefit is not confirmed impact.")}</p>
    </section>`;
  }

  function renderIntegratedRecipeBenefitForMeal(day, mealType, rawMeal) {
    if (!isIntegratedPlanningMode()) return "";
    const entry = normalizeMealPlanEntry(rawMeal);
    if (!entry?.recipeId) return "";
    const recipe = getRecipeForMealEntry(rawMeal) || findRecipeById(entry.recipeId);
    if (!recipe) return "";
    const context = createIntegratedPlanningContext({ plan: state.mealPlans });
    const evaluation = evaluateIntegratedRecipeCandidate(recipe, { day, mealType, entry: rawMeal, servings: rawMeal?.plannedRecipeServings || entry.servings }, context);
    return renderIntegratedRecipeBenefitSummary(buildRecipeBenefitSummary(evaluation));
  }

  function buildIntegratedPlanSummaries(plan = state.mealPlans, context = createIntegratedPlanningContext({ plan })) {
    const normalizedPlan = normalizeMealPlan(plan);
    const evaluations = getAllMealSlotsFromPlan(normalizedPlan).map(({ day, mealType, entry }) => {
      const recipe = entry?.recipeId ? getRecipeForMealEntry(entry) || findRecipeById(entry.recipeId) : null;
      return recipe ? evaluateIntegratedRecipeCandidate(recipe, { day, mealType, entry, servings: entry.servings || 1 }, context) : null;
    }).filter(Boolean);
    const plannedPriorityItems = evaluations.flatMap((item) => item.rescueBenefit?.priorityItemsUsed || []);
    const knownPantryValue = evaluations.reduce((sum, item) => sum + (item.budgetBenefit?.knownPantryValueUsedCents || 0), 0);
    const costResult = context.budget.enabled ? calculateMealPlanCostsForPlan(normalizedPlan, state.pantry) : null;
    const confidence = costResult ? derivePriceConfidence({ purchaseGroups: costResult.purchaseGroups, weeklyCostSummary: costResult.weeklySummary }) : null;
    return {
      metadataVersion: INTEGRATED_PLANNING_METADATA_VERSION,
      planMode: context.planMode,
      sourceRevisions: context.sourceRevisions,
      creditPolicy: context.creditPolicy,
      plannedFoodRescueSummary: {
        plannedPriorityUseCount: plannedPriorityItems.length,
        uniquePriorityItemCount: new Set(plannedPriorityItems.map((item) => item.pantryItemId || item.rescueSourceId)).size,
        languageStatus: "planned-only",
        impactCreditOnSave: false
      },
      budgetSummary: {
        knownPantryValueUsedCents: knownPantryValue,
        weeklyGroceryCostCents: confidence?.completeGroceryTotalAvailable ? costResult.weeklySummary.weeklyGroceryCostCents : null,
        knownPurchaseSubtotalCents: costResult?.weeklySummary?.knownPurchaseSubtotalCents || 0,
        priceConfidenceStatus: confidence?.status || null,
        sharedPackagesCountedOnceWeekly: true
      }
    };
  }

  function renderIntegratedPlanningSummary(plan = state.mealPlans) {
    if (!isIntegratedPlanningMode()) return "";
    const context = createIntegratedPlanningContext({ plan });
    const summary = buildIntegratedPlanSummaries(plan, context);
    state.currentIntegratedPlanningContext = context;
    state.currentIntegratedPlanEvaluation = summary;
    const rescue = summary.plannedFoodRescueSummary;
    const budget = summary.budgetSummary;
    const groceryText = Number.isInteger(budget.weeklyGroceryCostCents)
      ? formatCostCents(budget.weeklyGroceryCostCents)
      : `Known priced subtotal: ${formatCostCents(budget.knownPurchaseSubtotalCents || 0)}`;
    return `<section class="integrated-planning-summary" aria-labelledby="integratedPlanningHeading">
      <div class="integrated-planning-heading">
        <div>
          <span class="eyebrow">BUDGET + FOOD RESCUE</span>
          <h3 id="integratedPlanningHeading">Shared planning summary</h3>
          <p>Preview only. Pantry, Food Events, and Impact Ledger stay unchanged until you confirm cooking outcomes.</p>
        </div>
        <strong>${escapeHtml(PLANNING_MODE_LABELS[context.planMode] || "Meal Planner")}</strong>
      </div>
      <dl class="integrated-summary-grid">
        <div><dt>Planned priority use</dt><dd>${escapeHtml(String(rescue.uniquePriorityItemCount))} ${escapeHtml(pluralize(rescue.uniquePriorityItemCount, "item"))}</dd></div>
        <div><dt>Known Pantry value used</dt><dd>${escapeHtml(formatCostCents(budget.knownPantryValueUsedCents || 0))}</dd></div>
        <div><dt>Estimated new grocery total</dt><dd>${escapeHtml(groceryText)}</dd></div>
        <div><dt>Price confidence</dt><dd>${escapeHtml(priceConfidenceStatusLabel(budget.priceConfidenceStatus))}</dd></div>
      </dl>
      <p class="integrated-benefit-note">Planned food-rescue benefit does not create impact credit. Weekly checkout totals use full package prices and count shared packages once.</p>
    </section>`;
  }

  function createIntegratedPlanMetadataSnapshot(plan = state.mealPlans) {
    if (!isIntegratedPlanningMode(plan?.planningMode || getCurrentPlanningMode())) return null;
    return buildIntegratedPlanSummaries(plan, createIntegratedPlanningContext({ plan, planMode: plan?.planningMode || getCurrentPlanningMode() }));
  }

  function priceConfidenceStatusLabel(status) {
    return {
      [PRICE_CONFIDENCE_STATUSES.HIGH]: "High confidence",
      [PRICE_CONFIDENCE_STATUSES.ESTIMATED]: "Estimated",
      [PRICE_CONFIDENCE_STATUSES.INCOMPLETE]: "Incomplete estimate"
    }[status] || "Incomplete estimate";
  }

  function renderPriceConfidenceProgress(confidence) {
    if (!confidence || confidence.totalRequiredGroceryItemCount === 0 || confidence.coveragePercentDisplay === null) return "";
    const text = `${confidence.usablePriceItemCount} of ${confidence.totalRequiredGroceryItemCount} grocery ${pluralize(confidence.totalRequiredGroceryItemCount, "item")} ${confidence.usablePriceItemCount === 1 ? "has" : "have"} usable prices`;
    return `<div class="price-confidence-progress" role="progressbar" aria-label="Pricing coverage" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${escapeHtml(String(confidence.coveragePercentDisplay))}" aria-valuetext="${escapeHtml(text)}">
      <span style="width: ${escapeHtml(String(confidence.coveragePercentDisplay))}%"></span>
    </div>`;
  }

  function renderBudgetSafetyMessage(confidence) {
    if (!confidence) return `<p>Chef Nova could not verify the current price coverage. Review grocery prices before relying on the budget total.</p>`;
    if (confidence.status === PRICE_CONFIDENCE_STATUSES.INCOMPLETE) {
      const unresolved = confidence.unresolvedItemCount;
      const above = Number.isInteger(confidence.knownSubtotalAboveBudgetCents) && confidence.knownSubtotalAboveBudgetCents > 0
        ? `<p>The currently priced items alone are approximately ${escapeHtml(formatCostCents(confidence.knownSubtotalAboveBudgetCents))} above the selected weekly budget.</p>`
        : "";
      return `${above}<p>Chef Nova cannot yet determine whether the complete plan is within the selected budget.</p>
        <p>${numberWord(unresolved)} grocery ${pluralize(unresolved, "item")} ${unresolved === 1 ? "does" : "do"} not yet have usable ${pluralize(unresolved, "price", "prices")}, so the final grocery total may be higher.</p>`;
    }
    if (confidence.canClaimWithinBudget) {
      return `<p>${confidence.status === PRICE_CONFIDENCE_STATUSES.HIGH ? "Based on your entered and saved prices" : "Using current Chef Nova estimates and saved prices"}, the estimated grocery cost is within the selected weekly budget.</p><p>Actual store prices may vary.</p>`;
    }
    if (confidence.canClaimAboveBudget) {
      const amount = confidence.weeklyGroceryCostCents - confidence.weeklyBudgetCents;
      return `<p>The estimated grocery cost is approximately ${escapeHtml(formatCostCents(amount))} above the selected weekly budget.</p><p>Actual store prices may vary.</p>`;
    }
    return `<p>Actual store prices may vary.</p>`;
  }

  function renderPriceSourceBreakdown(confidence) {
    const rows = [
      ["User-entered prices", confidence.userEnteredPriceItemCount],
      ["Saved profile prices", confidence.savedProfilePriceItemCount],
      ["Chef Nova estimates", confidence.chefNovaEstimateItemCount],
      ["Estimate fallbacks", confidence.estimateFallbackItemCount],
      ["Missing or unusable", confidence.unresolvedItemCount]
    ];
    return `<details class="price-confidence-details">
      <summary>View price source details</summary>
      <dl>${rows.map(([label, value]) => `<div><dt>${escapeHtml(label)}</dt><dd>${escapeHtml(String(value))}</dd></div>`).join("")}</dl>
    </details>`;
  }

  function renderUnresolvedPriceItems(confidence) {
    if (!confidence.unresolvedItems.length) return "";
    return `<div class="price-confidence-unresolved">
      <h5>Items to review</h5>
      <ul>${confidence.unresolvedItems.slice(0, 5).map((item) => `<li><b>${escapeHtml(item.displayName)}</b><span>${escapeHtml(item.reason)}</span></li>`).join("")}</ul>
      ${confidence.unresolvedItems.length > 5 ? `<p>${confidence.unresolvedItems.length - 5} more ${pluralize(confidence.unresolvedItems.length - 5, "item")} need review.</p>` : ""}
    </div>`;
  }

  function renderPriceConfidencePanel(confidence) {
    if (!confidence) {
      return `<section class="price-confidence incomplete" aria-labelledby="priceConfidenceHeading" aria-live="polite">
        <h4 id="priceConfidenceHeading">Price confidence</h4>
        <p class="price-confidence-status">${priceConfidenceStatusLabel(PRICE_CONFIDENCE_STATUSES.INCOMPLETE)}</p>
        ${renderBudgetSafetyMessage(null)}
      </section>`;
    }
    const statusClass = confidence.status;
    const coverage = confidence.totalRequiredGroceryItemCount
      ? `<p>Pricing coverage: <strong>${escapeHtml(String(confidence.coveragePercentDisplay))}%</strong></p>
        ${renderPriceConfidenceProgress(confidence)}
        <p>${confidence.usablePriceItemCount} of ${confidence.totalRequiredGroceryItemCount} grocery ${pluralize(confidence.totalRequiredGroceryItemCount, "item")} ${confidence.usablePriceItemCount === 1 ? "has" : "have"} usable prices.</p>`
      : `<p>No grocery purchases are currently required.</p><p>The selected plan is fully covered by Pantry quantities in Chef Nova.</p>`;
    const missingPriceCount = confidence.unresolvedItems.filter((item) => item.reasonCode === "missing-price").length;
    const nonPriceIssueCount = confidence.unresolvedItemCount - missingPriceCount;
    const action = confidence.unresolvedItemCount
      ? `<div class="price-confidence-actions">
          ${missingPriceCount ? `<button class="button primary small" type="button" data-add-missing-prices>Add Missing Prices</button>` : ""}
          ${nonPriceIssueCount ? `<button class="button secondary small" type="button" data-review-cost-issues>Review Cost Issues</button>` : ""}
        </div>`
      : "";
    const fallbackNote = confidence.estimateFallbackItemCount
      ? `<p>${numberWord(confidence.estimateFallbackItemCount)} ${pluralize(confidence.estimateFallbackItemCount, "item")} use Chef Nova estimates because the selected source does not contain a usable price.</p>`
      : "";
    return `<section class="price-confidence ${escapeHtml(statusClass)}" aria-labelledby="priceConfidenceHeading" aria-live="polite">
      <div class="price-confidence-heading">
        <div><h4 id="priceConfidenceHeading">Price confidence</h4><p class="price-confidence-status">${escapeHtml(priceConfidenceStatusLabel(confidence.status))}</p></div>
        ${confidence.totalRequiredGroceryItemCount ? `<strong>${escapeHtml(String(confidence.coveragePercentDisplay))}%</strong>` : ""}
      </div>
      ${coverage}
      ${fallbackNote}
      ${renderBudgetSafetyMessage(confidence)}
      ${renderPriceSourceBreakdown(confidence)}
      ${renderUnresolvedPriceItems(confidence)}
      ${action}
    </section>`;
  }

  function renderBudgetCostSummary() {
    if (getCurrentPlanningMode() !== PLANNING_MODES.BUDGET_RESCUE) return "";
    const result = calculateCurrentMealPlanCosts();
    if (!result) return renderPriceConfidencePanel(null);
    const summary = result.weeklySummary;
    const confidence = derivePriceConfidence({ purchaseGroups: result.purchaseGroups, weeklyCostSummary: summary });
    if (!summary.totalPurchaseGroupCount && summary.status === "no-purchases-required") {
      return `<section class="budget-cost-summary" aria-live="polite"><h4>Budget Rescue Cost Preview</h4><p>No grocery purchases are currently required from planned recipe quantities. Recipe-use costs may still need prices.</p></section>${renderPriceConfidencePanel(confidence)}`;
    }
    if (confidence.completeGroceryTotalAvailable && summary.weeklyGroceryCostCents !== null) {
      return `<section class="budget-cost-summary" aria-live="polite"><h4>Budget Rescue Cost Preview</h4>
        <dl>
          <div><dt>Weekly budget</dt><dd>${escapeHtml(formatCostCents(summary.weeklyBudgetCents))}</dd></div>
          <div><dt>Estimated grocery cost</dt><dd>${escapeHtml(formatCostCents(summary.weeklyGroceryCostCents))}</dd></div>
          ${confidence.canShowRemainingBudget ? `<div><dt>Remaining budget</dt><dd>${escapeHtml(formatCostCents(summary.remainingBudgetCents))}</dd></div>` : ""}
          ${confidence.canShowRemainingBudget ? `<div><dt>Remaining planning target</dt><dd>${escapeHtml(formatCostCents(summary.remainingPlanningTargetCents))}</dd></div>` : ""}
          <div><dt>Resolved prices</dt><dd>${escapeHtml(String(summary.resolvedPriceCoveragePercent ?? 0))}%</dd></div>
          <div><dt>User-confirmed prices</dt><dd>${escapeHtml(String(summary.confirmedPriceCoveragePercent ?? 0))}%</dd></div>
        </dl>
      </section>${renderPriceConfidencePanel(confidence)}`;
    }
    return `<section class="budget-cost-summary incomplete" aria-live="polite"><h4>Budget Rescue Cost Preview</h4>
      <p>Currently priced grocery items: ${escapeHtml(formatCostCents(summary.knownPurchaseSubtotalCents))}</p>
      <p>${summary.unresolvedPurchaseGroupCount} ${summary.unresolvedPurchaseGroupCount === 1 ? "grocery item still needs" : "grocery items still need"} prices or measurable quantities. The final total may be higher.</p>
    </section>${renderPriceConfidencePanel(confidence)}`;
  }

  function getBudgetStatusRequestedMealCount(planningRequest = null) {
    const budget = planningRequest?.budget || normalizeBudgetRescueDraft(normalizePlanningModeInputs(state.planningModeInputs).budgetRescue);
    const days = Math.max(1, Math.min(DAYS.length, Number(budget?.household?.numberOfDays) || DAYS.length));
    const mealsToPlan = budget?.household?.mealsToPlan || {};
    const selectedMeals = MEALS.filter((mealType) => mealsToPlan[mealType] !== false);
    return days * (selectedMeals.length || MEALS.length);
  }

  function summarizeBudgetStatusPlanMetrics(plan = state.mealPlans, costResult = null, pantryAllocation = null) {
    const normalizedPlan = normalizeMealPlan(plan);
    const plannedMeals = getAllMealSlotsFromPlan(normalizedPlan);
    const recipeMeals = buildWeeklyCostMeals(normalizedPlan);
    const summariesByMealId = new Map((costResult?.recipeCostSummaries || []).map((summary) => [summary.mealId, summary]));
    let ingredientUseCostCents = 0;
    let deliveredServings = 0;
    let completeIngredientUseCosts = true;
    plannedMeals.forEach(({ day, mealType, entry }) => {
      const servings = Number(entry.householdServings || entry.servings || 1);
      if (Number.isFinite(servings) && servings > 0) deliveredServings += servings;
      if (!entry.recipeId) return;
      if (entry.mealType === "leftover") {
        if (Number.isInteger(entry.additionalCostCents) && entry.additionalCostCents > 0) ingredientUseCostCents += entry.additionalCostCents;
        return;
      }
      const summary = summariesByMealId.get(entry.mealId || `${day}::${mealType}`) || summariesByMealId.get(getPlanMealId(day, mealType));
      if (summary && Number.isInteger(summary.totalRecipeCostCents)) ingredientUseCostCents += summary.totalRecipeCostCents;
      else if (recipeMeals.some((meal) => meal.day === day && meal.mealType === mealType)) completeIngredientUseCosts = false;
    });
    const pantryUsed = Number.isInteger(pantryAllocation?.summary?.ingredientGroupCountUsed)
      ? pantryAllocation.summary.ingredientGroupCountUsed
      : Number.isInteger(costResult?.weeklySummary?.pantryIngredientGroupCountUsed)
        ? costResult.weeklySummary.pantryIngredientGroupCountUsed
        : null;
    return {
      mealsPlannedCount: plannedMeals.length,
      pantryIngredientGroupCountUsed: pantryUsed,
      ingredientUseCostCents: completeIngredientUseCosts ? ingredientUseCostCents : null,
      deliveredServings,
      averageIngredientCostPerServingCents: completeIngredientUseCosts && deliveredServings > 0 ? Math.round(ingredientUseCostCents / deliveredServings) : null
    };
  }

  function validateBudgetStatusPlanCompatibility(plan = state.mealPlans, context = buildMealPlanGenerationContext()) {
    const conflicts = [];
    getAllMealSlotsFromPlan(plan).forEach(({ day, mealType, entry }) => {
        if (!entry?.recipeId) return;
        const recipe = getRecipeForMealEntry(entry);
        if (!recipe) {
          conflicts.push({ day, mealType, message: "Recipe no longer available." });
          return;
        }
        const result = evaluateRecipeForCurrentRequirements(recipe, context, { requiredServings: entry.servings || context.requiredServings || 1 });
        if (result.status !== RECIPE_ELIGIBILITY_STATUSES.ELIGIBLE && result.canUseForAutomaticPlanning !== true) {
          conflicts.push({ day, mealType, message: result.exclusionReasons?.[0]?.message || "Meal needs review." });
        }
    });
    return { safe: conflicts.length === 0, conflictCount: conflicts.length, conflicts };
  }

  function countAvailableLowerCostSubstitutionsForPlan(plan = state.mealPlans) {
    if (!state.substitutionIndexes?.rulesByRuleId) return 0;
    let count = 0;
    getAllMealSlotsFromPlan(plan).forEach(({ day, mealType, entry }) => {
        if (!entry?.recipeId || entry.mealType === "leftover") return;
        const recipe = getRecipeForMealEntry(entry);
        getSubstitutionRulesForRecipe(recipe).forEach((rule) => {
          const evaluation = evaluateSubstitutionForMeal({ rule, day, mealType, entry, plan });
          if (evaluation.canApply && evaluation.savingsResult?.complete && Number(evaluation.savingsResult.estimatedWeeklySavingsCents) > 0) count += 1;
        });
    });
    return count;
  }

  function formatRespectfulBudgetMessage(template, values = {}) {
    return String(template || "").replace(/\{(\w+)\}/g, (_, key) => values[key] ?? "");
  }

  function formatPlanLengthLabel(dayCount) {
    const days = Math.max(1, Number(dayCount) || 1);
    const word = days <= 10 ? numberWord(days).toLowerCase() : String(days);
    return `${word}-day plan`;
  }

  function getRespectfulPlanLengthDays(planningRequest = null, planningResult = null) {
    if (Number.isInteger(planningRequest?.emergencyRequest?.numberOfDays)) return planningRequest.emergencyRequest.numberOfDays;
    if (Number.isInteger(planningRequest?.numberOfDays)) return planningRequest.numberOfDays;
    if (Number.isInteger(planningRequest?.budget?.household?.numberOfDays)) return planningRequest.budget.household.numberOfDays;
    if (Array.isArray(planningResult?.slots) && planningResult.slots.length) {
      return Math.max(1, new Set(planningResult.slots.map((slot) => slot.day)).size);
    }
    return DAYS.length;
  }

  function getRespectfulSafetyMessage(context = {}) {
    if (context.allergenDataIncomplete) {
      return "Chef Nova could not verify every recipe against the current allergy information, so those recipes were not included.";
    }
    const hasAllergies = getUserAllergies().length > 0;
    return hasAllergies ? "No allergy or required dietary restriction was changed." : "No required dietary restriction was changed.";
  }

  function hasProhibitedBudgetLanguage(text) {
    return PROHIBITED_USER_FACING_BUDGET_PATTERNS.some((pattern) => pattern.test(String(text || "")));
  }

  function sanitizeRespectfulBudgetMessage(model) {
    const values = [
      model.heading,
      model.primaryMessage,
      model.secondaryMessage,
      model.safetyMessage,
      model.liveRegionText,
      ...(model.detailLines || []),
      ...(model.warnings || []),
      ...(model.actions || []).flatMap((action) => [action.label, action.description, action.disabledReason])
    ];
    if (!values.some(hasProhibitedBudgetLanguage)) return model;
    return {
      ...model,
      messageType: RESPECTFUL_BUDGET_MESSAGE_TYPES.PLAN_REQUIRES_REVIEW,
      severity: "advisory",
      heading: "Review the current plan",
      primaryMessage: "Chef Nova found a plan message that needs safer wording.",
      secondaryMessage: "Review the available plan and grocery options.",
      safetyMessage: getRespectfulSafetyMessage(),
      detailLines: [],
      actions: [],
      liveRegionText: "Budget status requires review.",
      warnings: ["A budget message was replaced by the respectful-language safeguard."]
    };
  }

  function createRespectfulBudgetAction({
    actionId,
    actionType,
    label,
    description,
    attr,
    available = true,
    enabled = true,
    sourceSystem = "budget-status-panel",
    expectedResult = {},
    currentPlanSignature = "",
    requiresConfirmation = true,
    disabledReason = null
  }) {
    return {
      actionId,
      actionType,
      label,
      description,
      attr,
      available: available === true,
      enabled: enabled === true && available === true && Boolean(attr),
      disabledReason: available === true && attr ? disabledReason : disabledReason || "This action is not available for the current plan.",
      sourceSystem,
      affectedMealIds: [],
      expectedResult,
      currentPlanSignature,
      requiresConfirmation
    };
  }

  function normalizeRespectfulBudgetActions(actions = []) {
    const seen = new Set();
    return actions.filter((action) => action?.available && action.enabled && action.attr && !hasProhibitedBudgetLanguage(action.label)).filter((action) => {
      const key = `${action.actionId}::${action.currentPlanSignature || ""}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  function getActionCountSentence(count) {
    if (count === 1) return "Chef Nova found one possible change.";
    if (count > 1) return `Chef Nova found ${count} possible changes.`;
    return "Chef Nova did not find another automatic safe change using the current settings.";
  }

  function deriveRespectfulBudgetActions({
    messageType,
    confidence,
    shoppingCoverage,
    compatibility,
    substitutionCount = 0,
    pantrySummary = null,
    planningRequest = null,
    plan = state.mealPlans
  } = {}) {
    const currentPlanSignature = buildMealPlanSignature(plan);
    const actions = [];
    const missingPrices = confidence?.unresolvedItems?.filter((item) => item.reasonCode === "missing-price").length || 0;
    if (missingPrices > 0) {
      actions.push(createRespectfulBudgetAction({
        actionId: RESPECTFUL_BUDGET_ACTION_IDS.ADD_MISSING_PRICES,
        actionType: "missing-price-review",
        label: "Add Missing Prices",
        description: "Open the Shopping List price review for grocery items that need usable prices.",
        attr: "data-add-missing-prices",
        sourceSystem: "price-confidence",
        currentPlanSignature
      }));
    }
    if (confidence?.unresolvedItemCount > missingPrices) {
      actions.push(createRespectfulBudgetAction({
        actionId: RESPECTFUL_BUDGET_ACTION_IDS.REVIEW_COST_ISSUES,
        actionType: "cost-issue-review",
        label: "Review Cost Issues",
        description: "Open grocery items with quantities or package details that need review.",
        attr: "data-review-cost-issues",
        sourceSystem: "price-confidence",
        currentPlanSignature
      }));
    }
    if (shoppingCoverage && shoppingCoverage.shoppingCoverageComplete === false) {
      actions.push(createRespectfulBudgetAction({
        actionId: RESPECTFUL_BUDGET_ACTION_IDS.REVIEW_SHOPPING_LIST,
        actionType: "shopping-coverage-review",
        label: "Review Shopping List",
        description: "Review required grocery quantities before relying on the final budget total.",
        attr: "data-page=\"shopping-list\"",
        sourceSystem: "shopping-list",
        currentPlanSignature
      }));
    }
    if (compatibility?.conflictCount > 0) {
      actions.push(createRespectfulBudgetAction({
        actionId: RESPECTFUL_BUDGET_ACTION_IDS.REVIEW_MEAL_PLAN,
        actionType: "hard-requirement-review",
        label: "Review Meal Plan",
        description: "Review meals that no longer match the current hard requirements.",
        attr: "data-review-budget-status-actions",
        sourceSystem: "recipe-eligibility-engine",
        currentPlanSignature
      }));
    }
    if (substitutionCount > 0 && [
      RESPECTFUL_BUDGET_MESSAGE_TYPES.COMPLETE_PLAN_ABOVE_BUDGET,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.FULL_PLAN_NOT_FOUND_WITHIN_BUDGET
    ].includes(messageType)) {
      actions.push(createRespectfulBudgetAction({
        actionId: RESPECTFUL_BUDGET_ACTION_IDS.APPLY_LOWER_COST_SUBSTITUTIONS,
        actionType: "lower-cost-substitution-review",
        label: "Apply Lower-Cost Substitutions",
        description: "Open reviewed lower-cost substitutions that preserve safety requirements.",
        attr: "data-review-budget-status-actions",
        sourceSystem: "substitution-system",
        expectedResult: { availableRecommendationCount: substitutionCount },
        currentPlanSignature
      }));
    }
    const duration = getRespectfulPlanLengthDays(planningRequest);
    if (duration > 4 && [
      RESPECTFUL_BUDGET_MESSAGE_TYPES.COMPLETE_PLAN_ABOVE_BUDGET,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.FULL_PLAN_NOT_FOUND_WITHIN_BUDGET,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.PARTIAL_SAFE_PLAN,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.NO_SAFE_PLAN
    ].includes(messageType)) {
      actions.push(createRespectfulBudgetAction({
        actionId: RESPECTFUL_BUDGET_ACTION_IDS.CREATE_FOUR_DAY_PLAN,
        actionType: "shorter-plan-preview",
        label: "Create a Four-Day Plan",
        description: "Create a four-day preview while keeping the current longer plan unchanged until confirmation.",
        attr: "data-create-four-day-plan",
        sourceSystem: "meal-plan-review",
        expectedResult: { requestedDayCount: 4 },
        currentPlanSignature
      }));
    }
    const pantryHasCurrentBenefit = Number.isInteger(pantrySummary?.ingredientGroupCountUsed) && pantrySummary.ingredientGroupCountUsed > 0;
    if (state.pantry.length && pantryHasCurrentBenefit && [
      RESPECTFUL_BUDGET_MESSAGE_TYPES.COMPLETE_PLAN_ABOVE_BUDGET,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.FULL_PLAN_NOT_FOUND_WITHIN_BUDGET,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.PARTIAL_SAFE_PLAN
    ].includes(messageType)) {
      actions.push(createRespectfulBudgetAction({
        actionId: RESPECTFUL_BUDGET_ACTION_IDS.USE_MORE_PANTRY,
        actionType: "pantry-plan-review",
        label: "Use More Pantry Ingredients",
        description: "Review Pantry information used by the existing pantry-first planner.",
        attr: "data-budget-edit-pantry",
        sourceSystem: "pantry-first-planning",
        currentPlanSignature
      }));
    }
    if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.NO_SAFE_PLAN || messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.PARTIAL_SAFE_PLAN) {
      actions.push(createRespectfulBudgetAction({
        actionId: RESPECTFUL_BUDGET_ACTION_IDS.REVIEW_CLOSEST_SAFE_OPTIONS,
        actionType: "closest-safe-options-review",
        label: "Review Closest Safe Options",
        description: "Review the available safe options without changing allergy or required dietary settings.",
        attr: "data-review-budget-status-actions",
        sourceSystem: "budget-planning-algorithm",
        currentPlanSignature
      }));
    }
    return normalizeRespectfulBudgetActions(actions);
  }

  function deriveRespectfulBudgetMessage({
    planningMode = getCurrentPlanningMode(),
    planningRequest = null,
    planningResult = null,
    compatibilitySummary = null,
    weeklyCostSummary = null,
    priceConfidence = null,
    shoppingCoverage = null,
    pantryOpportunities = null,
    substitutionRecommendations = null,
    repairActions = null,
    shorterPlanOptions = null,
    availableActions = null,
    plan = state.mealPlans
  } = {}) {
    const requestedMeals = planningResult?.slots?.length || getBudgetStatusRequestedMealCount(planningRequest);
    const filledMeals = planningResult?.selectedMeals?.length || summarizeBudgetStatusPlanMetrics(plan).mealsPlannedCount;
    const completePlan = requestedMeals > 0 && filledMeals >= requestedMeals;
    const completePricing = Boolean(priceConfidence?.completeGroceryTotalAvailable && Number.isInteger(weeklyCostSummary?.weeklyGroceryCostCents) && !weeklyCostSummary?.unresolvedPurchaseGroupCount);
    const weeklyBudgetCents = planningMode === PLANNING_MODES.EMERGENCY
      ? planningRequest?.emergencyRequest?.availableBudgetCents || planningRequest?.budget?.weeklyBudgetCents
      : planningRequest?.budget?.weeklyBudgetCents;
    const planningTargetCents = planningRequest?.budget?.planningTargetCents;
    const costCents = completePricing ? weeklyCostSummary.weeklyGroceryCostCents : null;
    const amountAboveBudgetCents = completePricing && Number.isInteger(weeklyBudgetCents) ? Math.max(0, costCents - weeklyBudgetCents) : null;
    const planLengthDays = getRespectfulPlanLengthDays(planningRequest, planningResult);
    const planLengthLabel = formatPlanLengthLabel(planLengthDays);
    const budgetText = Number.isInteger(weeklyBudgetCents) ? formatCostCents(weeklyBudgetCents) : "the selected budget";
    const allergenDataIncomplete = Boolean(compatibilitySummary?.conflicts?.some((conflict) => String(conflict.message || "").toLowerCase().includes("allergen") && String(conflict.message || "").toLowerCase().includes("incomplete")));
    let messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.STATUS_UNAVAILABLE;
    if (compatibilitySummary && compatibilitySummary.safe === false) messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.PLAN_REQUIRES_REVIEW;
    else if (planningResult?.status === BUDGET_PLAN_STATUSES.NO_SAFE_PLAN || (requestedMeals > 0 && filledMeals === 0)) messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.NO_SAFE_PLAN;
    else if (requestedMeals > 0 && filledMeals > 0 && !completePlan) messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.PARTIAL_SAFE_PLAN;
    else if (shoppingCoverage && shoppingCoverage.shoppingCoverageComplete === false) messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.INCOMPLETE_SHOPPING_COVERAGE;
    else if (!completePricing) messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.INCOMPLETE_PRICE_ESTIMATE;
    else if (Number.isInteger(amountAboveBudgetCents) && amountAboveBudgetCents > 0 && planningResult?.status === BUDGET_PLAN_STATUSES.ABOVE_WEEKLY_BUDGET) messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.FULL_PLAN_NOT_FOUND_WITHIN_BUDGET;
    else if (Number.isInteger(amountAboveBudgetCents) && amountAboveBudgetCents > 0) messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.COMPLETE_PLAN_ABOVE_BUDGET;
    else if (Number.isInteger(planningTargetCents) && Number.isInteger(costCents) && costCents > planningTargetCents) messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.WITHIN_BUDGET_USING_CUSHION;
    else if (completePricing) messageType = RESPECTFUL_BUDGET_MESSAGE_TYPES.WITHIN_BUDGET;
    const actions = normalizeRespectfulBudgetActions(availableActions || deriveRespectfulBudgetActions({
      messageType,
      confidence: priceConfidence,
      shoppingCoverage,
      compatibility: compatibilitySummary,
      substitutionCount: substitutionRecommendations?.availableLowerCostActionCount || 0,
      pantrySummary: pantryOpportunities,
      planningRequest,
      plan
    }));
    const actionSentence = getActionCountSentence(actions.length);
    const safetyMessage = [
      RESPECTFUL_BUDGET_MESSAGE_TYPES.COMPLETE_PLAN_ABOVE_BUDGET,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.FULL_PLAN_NOT_FOUND_WITHIN_BUDGET,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.PARTIAL_SAFE_PLAN,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.NO_SAFE_PLAN,
      RESPECTFUL_BUDGET_MESSAGE_TYPES.PLAN_REQUIRES_REVIEW
    ].includes(messageType) ? getRespectfulSafetyMessage({ allergenDataIncomplete }) : "";
    const common = {
      messageType,
      severity: "advisory",
      safetyMessage,
      detailLines: [],
      actions,
      warnings: [],
      policy: RESPECTFUL_BUDGET_MESSAGE_POLICY,
      planSignature: buildMealPlanSignature(plan)
    };
    let model;
    if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.PLAN_REQUIRES_REVIEW) {
      const count = compatibilitySummary?.conflictCount || 0;
      model = { ...common, heading: "Review current meal requirements", primaryMessage: `${numberWord(count)} planned meal ${pluralize(count, "slot")} ${count === 1 ? "needs" : "need"} review before Chef Nova can confirm the budget status.`, secondaryMessage: "Hard safety and dietary requirements remain active.", liveRegionText: `Budget status updated. ${count} meal ${pluralize(count, "slot")} need review.` };
    } else if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.NO_SAFE_PLAN) {
      model = { ...common, heading: planningMode === PLANNING_MODES.EMERGENCY ? "Emergency Plan needs review" : "No safe plan is available yet", primaryMessage: "Chef Nova could not create a safe plan using the current requirements.", secondaryMessage: actions.length ? "Review the available non-safety options below." : "Chef Nova did not find another automatic safe change using the current settings.", liveRegionText: "Budget status updated. Chef Nova could not create a safe plan using the current requirements." };
    } else if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.PARTIAL_SAFE_PLAN) {
      const remaining = Math.max(0, requestedMeals - filledMeals);
      const emergencyWithin = planningMode === PLANNING_MODES.EMERGENCY && completePricing && Number.isInteger(weeklyBudgetCents) && costCents <= weeklyBudgetCents ? " within the available budget" : "";
      model = { ...common, heading: "Partial safe plan", primaryMessage: `Chef Nova safely planned ${filledMeals} of ${requestedMeals} requested meals${emergencyWithin}.`, secondaryMessage: `${numberWord(remaining)} meal ${pluralize(remaining, "slot")} still ${remaining === 1 ? "requires" : "require"} a safe option.`, liveRegionText: `Budget status updated. Chef Nova safely planned ${filledMeals} of ${requestedMeals} requested meals.` };
    } else if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.INCOMPLETE_SHOPPING_COVERAGE) {
      const shortfallCount = (shoppingCoverage?.removedRequiredItemCount || 0) + (shoppingCoverage?.shortfallItemCount || 0) + (shoppingCoverage?.unresolvedQuantityItemCount || 0);
      model = { ...common, heading: "Shopping List coverage needs review", primaryMessage: "The current Shopping List does not yet cover every required grocery quantity.", secondaryMessage: `${numberWord(shortfallCount)} ${pluralize(shortfallCount, "item")} ${shortfallCount === 1 ? "has" : "have"} a purchase or quantity issue. Review before relying on the final budget total.`, liveRegionText: `Budget status updated. ${shortfallCount} Shopping List ${pluralize(shortfallCount, "item")} need review.` };
    } else if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.INCOMPLETE_PRICE_ESTIMATE) {
      const unresolved = priceConfidence?.unresolvedItemCount || weeklyCostSummary?.unresolvedPurchaseGroupCount || 0;
      const knownSubtotal = formatCostCents(weeklyCostSummary?.knownPurchaseSubtotalCents || 0);
      model = { ...common, heading: "Some grocery prices are missing", primaryMessage: "Some grocery prices are missing.", secondaryMessage: `The currently priced items total approximately ${knownSubtotal}. Add the missing prices before relying on the final grocery total.`, detailLines: unresolved ? [`${numberWord(unresolved)} grocery ${pluralize(unresolved, "item")} still ${unresolved === 1 ? "requires" : "require"} usable ${pluralize(unresolved, "price", "prices")}.`] : [], liveRegionText: `Price information updated. ${unresolved} grocery ${pluralize(unresolved, "item")} require prices before the final total can be confirmed.` };
    } else if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.FULL_PLAN_NOT_FOUND_WITHIN_BUDGET) {
      model = { ...common, heading: "Full plan not found within the selected budget", primaryMessage: formatRespectfulBudgetMessage("We could not create the full {planLengthLabel} within {budget} using the selected preferences.", { planLengthLabel, budget: budgetText }), secondaryMessage: actionSentence, liveRegionText: `Budget status updated. A full ${planLengthLabel} was not found within ${budgetText}. ${actions.length} possible ${pluralize(actions.length, "change")} available.` };
    } else if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.COMPLETE_PLAN_ABOVE_BUDGET) {
      const above = formatCostCents(amountAboveBudgetCents || 0);
      const primary = planningMode === PLANNING_MODES.EMERGENCY
        ? `The estimated grocery cost is approximately ${above} above the available budget.`
        : `The current plan is approximately ${above} above the selected budget.`;
      model = { ...common, heading: "The current plan is above the selected budget", primaryMessage: primary, secondaryMessage: actionSentence, liveRegionText: `Budget status updated. The current plan is approximately ${above} above budget. ${actions.length} possible ${pluralize(actions.length, "change")} available.` };
    } else if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.WITHIN_BUDGET_USING_CUSHION) {
      model = { ...common, heading: "The current plan is within the full selected budget", primaryMessage: "The current plan is within the full selected budget.", secondaryMessage: "Part of the selected price cushion may be used. Actual store prices may vary.", liveRegionText: "Budget status updated. The current plan is within the full selected budget." };
    } else if (messageType === RESPECTFUL_BUDGET_MESSAGE_TYPES.WITHIN_BUDGET) {
      const primary = planningMode === PLANNING_MODES.EMERGENCY && Number.isInteger(weeklyBudgetCents)
        ? `Chef Nova created a safe Emergency Plan within the available ${formatCostCents(weeklyBudgetCents)} budget.`
        : "Your current plan is within the selected budget.";
      model = { ...common, heading: "The current plan is within budget", primaryMessage: primary, secondaryMessage: "Actual store prices may vary.", liveRegionText: "Budget status updated. The current plan is within the selected budget." };
    } else {
      model = { ...common, heading: "Budget status unavailable", primaryMessage: "Create a Budget Rescue plan to see budget status.", secondaryMessage: "Review the available plan and grocery options.", liveRegionText: "Budget status unavailable." };
    }
    return sanitizeRespectfulBudgetMessage(model);
  }

  function createPlanSavingsReason({ reasonId, reasonType, message, priority = 50, impactType = "cost-control", estimatedImpactCents = null, impactStatus = "qualitative-evidence", evidence = {}, warnings = [], overlapGroup = "" }) {
    return {
      reasonId,
      reasonType,
      message,
      priority,
      impactType,
      estimatedImpactCents: Number.isInteger(estimatedImpactCents) ? estimatedImpactCents : null,
      impactStatus,
      evidence,
      warnings,
      overlapGroup: overlapGroup || reasonId
    };
  }

  function getPlanSavingsComparisonPriceContext() {
    const settings = getActiveBudgetPriceSettings();
    return {
      comparisonPriceContextId: `${settings.priceSource || "unknown"}::${settings.savedPriceProfileId || "none"}::${getCurrentDateString()}`,
      selectedPriceSource: settings.priceSource || "",
      selectedProfileId: settings.savedPriceProfileId || "",
      currency: BUDGET_RESCUE_CURRENCY,
      calculationDate: getCurrentDateString()
    };
  }

  function createBudgetInitialPlanSnapshot(planState, request) {
    if (!planState?.plan) return null;
    return {
      explanationVersion: PLAN_SAVINGS_EXPLANATION_VERSION,
      baselineType: "initial-safe-plan-before-budget-repairs",
      baselineLabel: "Original estimated plan",
      baselineDescription: "The first complete safe plan before budget-reduction repairs were applied.",
      baselinePlanSignature: buildMealPlanSignature(planState.plan),
      requestedMealSlotCount: planState.slots?.length || 0,
      filledMealSlotCount: planState.selectedMeals?.length || 0,
      requestSignature: JSON.stringify({
        planningMode: request?.planningMode || PLANNING_MODES.BUDGET_RESCUE,
        numberOfDays: request?.budget?.household?.numberOfDays || null,
        mealsToPlan: request?.budget?.household?.mealsToPlan || null,
        suggestedServings: request?.household?.suggestedServings || null
      }),
      groceryCostSummary: structuredCloneSafe(planState.groceryCostSummary || {}),
      priceConfidence: planState.priceConfidence ? {
        status: planState.priceConfidence.status,
        completeGroceryTotalAvailable: planState.priceConfidence.completeGroceryTotalAvailable === true,
        coveragePercentDisplay: planState.priceConfidence.coveragePercentDisplay,
        unresolvedItemCount: planState.priceConfidence.unresolvedItemCount
      } : null,
      shoppingCoverage: { shoppingCoverageComplete: true, status: SHOPPING_COVERAGE_STATUSES.COMPLETE },
      purchaseGroups: (planState.purchaseGroups || []).map((group) => ({
        purchaseGroupId: group.purchaseGroupId,
        ingredientId: group.ingredientId,
        form: group.form || "",
        missingQuantity: group.missingQuantity,
        packagesRequired: group.packagesRequired,
        priceBasis: group.priceBasis,
        pricedQuantity: group.pricedQuantity,
        pricedUnit: group.pricedUnit,
        purchasedUnit: group.purchasedUnit,
        purchaseCostCents: group.purchaseCostCents,
        estimatedSurplusQuantity: group.estimatedSurplusQuantity,
        usingSalePrice: group.usingSalePrice === true,
        recipeContributions: structuredCloneSafe(group.recipeContributions || [])
      })),
      pantrySummary: structuredCloneSafe(planState.pantryAllocationSummary || {}),
      priceContext: getPlanSavingsComparisonPriceContext(),
      capturedAt: getCurrentIsoString()
    };
  }

  function getCurrentPlanSavingsBaseline(plan = state.mealPlans, planningResult = null) {
    return planningResult?.initialPlanSnapshot || plan?.planSavingsBaselineSnapshot || plan?.planExplanationSnapshot?.baselineSnapshot || null;
  }

  function getPlanSavingsMealCounts(plan = state.mealPlans, planningResult = null) {
    const requestedMealCount = planningResult?.slots?.length || getBudgetStatusRequestedMealCount(planningResult?.request || null);
    const plannedMealCount = planningResult?.selectedMeals?.length || countPlannedMeals(plan);
    return { requestedMealCount, plannedMealCount, completePlan: requestedMealCount > 0 && plannedMealCount >= requestedMealCount };
  }

  function comparePlanSavingsPurchaseGroups(baselineGroups = [], finalGroups = []) {
    const finalIds = new Set(finalGroups.map((group) => `${group.ingredientId || group.purchaseGroupId || ""}::${group.form || ""}`));
    const baselineRequired = baselineGroups.filter((group) => group.missingQuantity > 0);
    const finalRequired = finalGroups.filter((group) => group.missingQuantity > 0);
    const singleUseAvoided = baselineRequired.filter((group) => {
      const mealIds = new Set((group.recipeContributions || []).map((contribution) => contribution.mealId).filter(Boolean));
      const key = `${group.ingredientId || group.purchaseGroupId || ""}::${group.form || ""}`;
      return mealIds.size === 1 && !finalIds.has(key);
    });
    const optionalOnlyAvoided = baselineRequired.filter((group) => {
      const contributions = group.recipeContributions || [];
      const optionalOnly = contributions.length > 0 && contributions.every((contribution) => contribution.optional === true);
      const key = `${group.ingredientId || group.purchaseGroupId || ""}::${group.form || ""}`;
      return optionalOnly && !finalIds.has(key);
    });
    const baselineSurplusGroupCount = baselineRequired.filter((group) => Number(group.estimatedSurplusQuantity) > 0).length;
    const finalSurplusGroupCount = finalRequired.filter((group) => Number(group.estimatedSurplusQuantity) > 0).length;
    return {
      baselineUniquePurchaseGroupCount: baselineRequired.length,
      finalUniquePurchaseGroupCount: finalRequired.length,
      uniqueGroupDifference: Math.max(0, baselineRequired.length - finalRequired.length),
      singleUsePurchaseGroupsAvoided: singleUseAvoided,
      optionalOnlyPurchaseGroupsAvoided: optionalOnlyAvoided,
      lowerPackageSurplusGroupDifference: Math.max(0, baselineSurplusGroupCount - finalSurplusGroupCount)
    };
  }

  function buildPlanSavingsPantryReasons({ pantrySummary, purchaseGroups }) {
    const reasons = [];
    const pantryCount = Number.isInteger(pantrySummary?.ingredientGroupCountUsed) ? pantrySummary.ingredientGroupCountUsed : Number.isInteger(pantrySummary?.pantryIngredientGroupCountUsed) ? pantrySummary.pantryIngredientGroupCountUsed : 0;
    if (pantryCount > 0) {
      reasons.push(createPlanSavingsReason({
        reasonId: "pantry-groups-used",
        reasonType: PLAN_SAVINGS_REASON_TYPES.PANTRY_USE,
        message: `Uses ${pantryCount} ${pluralize(pantryCount, "ingredient")} already in your Pantry`,
        priority: 10,
        evidence: { pantryIngredientGroupCount: pantryCount, sourceSystems: ["pantry-first-planning"] }
      }));
    }
    const savings = Number.isInteger(pantrySummary?.savingsCents) ? pantrySummary.savingsCents : Number.isInteger(pantrySummary?.estimatedSavingsCents) ? pantrySummary.estimatedSavingsCents : null;
    if (Number.isInteger(savings) && savings > 0) {
      reasons.push(createPlanSavingsReason({
        reasonId: "pantry-purchases-avoided",
        reasonType: PLAN_SAVINGS_REASON_TYPES.PURCHASES_AVOIDED_BY_PANTRY,
        message: `Avoids approximately ${formatCostCents(savings)} in new grocery purchases by using ingredients already in your Pantry`,
        priority: 5,
        estimatedImpactCents: savings,
        impactStatus: "counterfactual-complete",
        evidence: { estimatedPurchasesAvoidedCents: savings, sourceSystems: ["pantry-first-planning", "cost-engine"] },
        overlapGroup: "pantry-checkout-impact"
      }));
    }
    const saleGroups = (purchaseGroups || []).filter((group) => group.missingQuantity > 0 && group.usingSalePrice === true);
    if (saleGroups.length) {
      reasons.push(createPlanSavingsReason({
        reasonId: "active-sale-use",
        reasonType: PLAN_SAVINGS_REASON_TYPES.ACTIVE_SALE_USE,
        message: `Uses ${saleGroups.length} ${pluralize(saleGroups.length, "ingredient")} with active saved sale prices`,
        priority: 70,
        evidence: { purchaseGroupIds: saleGroups.map((group) => group.purchaseGroupId), sourceSystems: ["price-catalogue", "cost-engine"] }
      }));
    }
    return reasons;
  }

  function buildPlanSavingsSharedReasons(purchaseGroups = []) {
    return (purchaseGroups || []).filter((group) => group.missingQuantity > 0).flatMap((group) => {
      const mealIds = Array.from(new Set((group.recipeContributions || []).map((contribution) => contribution.mealId).filter(Boolean)));
      if (mealIds.length < 2) return [];
      const ingredientName = getIngredientDisplayNameById(group.ingredientId, group.recipeContributions?.[0]?.displayText || "ingredient").toLowerCase();
      if (group.priceBasis === PRICE_BASIS_TYPES.PACKAGE && Number.isInteger(group.packagesRequired) && group.packagesRequired > 0) {
        const packageNoun = PRICE_DATA.unitLabel?.(group.pricedUnit || group.purchasedUnit || "package", group.packagesRequired) || pluralize(group.packagesRequired, "package");
        const packageSize = Number.isFinite(Number(group.pricedQuantity)) ? `${formatQuantityForDisplay(group.pricedQuantity)} ${group.pricedUnit || ""}`.trim() : "";
        return [createPlanSavingsReason({
          reasonId: `shared-package-${group.purchaseGroupId || group.ingredientId}`,
          reasonType: PLAN_SAVINGS_REASON_TYPES.SHARED_PACKAGE_USE,
          message: `Uses ${numberWord(group.packagesRequired).toLowerCase()} ${packageSize ? `${packageSize} ` : ""}${packageNoun} of ${ingredientName} across ${mealIds.length} ${pluralize(mealIds.length, "meal")}`,
          priority: 20,
          evidence: { ingredientId: group.ingredientId, purchaseGroupId: group.purchaseGroupId, selectedPackageCount: group.packagesRequired, mealIds, sourceSystems: ["cost-engine", "shopping-list"] },
          overlapGroup: `${group.ingredientId || group.purchaseGroupId}-cross-meal-reuse`
        })];
      }
      return [createPlanSavingsReason({
        reasonId: `shared-ingredient-${group.purchaseGroupId || group.ingredientId}`,
        reasonType: PLAN_SAVINGS_REASON_TYPES.SHARED_INGREDIENT_USE,
        message: `Uses ${ingredientName} across ${mealIds.length} ${pluralize(mealIds.length, "meal")}`,
        priority: 25,
        evidence: { ingredientId: group.ingredientId, purchaseGroupId: group.purchaseGroupId, mealIds, sourceSystems: ["cost-engine", "shopping-list"] },
        overlapGroup: `${group.ingredientId || group.purchaseGroupId}-cross-meal-reuse`
      })];
    });
  }

  function buildPlanSavingsLeftoverReasons(plan = state.mealPlans, leftoverSummary = null) {
    const reasons = [];
    const leftoverMeals = getAllMealsFromPlan(plan).filter((meal) => meal.entry?.mealType === "leftover");
    const leftoverLunches = leftoverMeals.filter((meal) => normalizeIngredient(meal.mealType) === "lunch").length;
    if (leftoverLunches > 0) {
      reasons.push(createPlanSavingsReason({
        reasonId: "planned-leftover-lunches",
        reasonType: PLAN_SAVINGS_REASON_TYPES.PLANNED_LEFTOVERS,
        message: `Includes ${numberWord(leftoverLunches).toLowerCase()} planned leftover ${pluralize(leftoverLunches, "lunch", "lunches")}`,
        priority: 30,
        evidence: { mealIds: leftoverMeals.map((meal) => getPlanMealId(meal.day, meal.mealType)), sourceSystems: ["leftover-planning"] }
      }));
    } else if (leftoverMeals.length > 0) {
      reasons.push(createPlanSavingsReason({
        reasonId: "planned-leftover-meals",
        reasonType: PLAN_SAVINGS_REASON_TYPES.PLANNED_LEFTOVERS,
        message: `Includes ${numberWord(leftoverMeals.length).toLowerCase()} planned leftover ${pluralize(leftoverMeals.length, "meal")}`,
        priority: 31,
        evidence: { mealIds: leftoverMeals.map((meal) => getPlanMealId(meal.day, meal.mealType)), sourceSystems: ["leftover-planning"] }
      }));
    }
    if (Number.isInteger(leftoverSummary?.estimatedSavingsCents) && leftoverSummary.estimatedSavingsCents > 0) {
      reasons.push(createPlanSavingsReason({
        reasonId: "planned-leftover-cost-impact",
        reasonType: PLAN_SAVINGS_REASON_TYPES.PLANNED_LEFTOVERS,
        message: `Planned leftovers reduce the estimated grocery cost by ${formatCostCents(leftoverSummary.estimatedSavingsCents)}`,
        priority: 28,
        estimatedImpactCents: leftoverSummary.estimatedSavingsCents,
        impactStatus: "counterfactual-complete",
        evidence: { estimatedSavingsCents: leftoverSummary.estimatedSavingsCents, sourceSystems: ["leftover-planning", "cost-engine"] },
        overlapGroup: "leftover-cost-impact"
      }));
    }
    if (Number.isInteger(leftoverSummary?.estimatedCookingSessionsAvoided) && leftoverSummary.estimatedCookingSessionsAvoided > 0) {
      const count = leftoverSummary.estimatedCookingSessionsAvoided;
      reasons.push(createPlanSavingsReason({
        reasonId: "leftover-cooking-sessions",
        reasonType: PLAN_SAVINGS_REASON_TYPES.BATCH_COOKING,
        message: `Avoids ${numberWord(count).toLowerCase()} full cooking ${pluralize(count, "session")} through planned leftovers`,
        priority: 80,
        impactType: "practical-benefit",
        evidence: { estimatedCookingSessionsAvoided: count, sourceSystems: ["leftover-planning"] }
      }));
    }
    return reasons;
  }

  function buildPlanSavingsSubstitutionReasons(plan = state.mealPlans) {
    const applied = getAllMealsFromPlan(plan).flatMap((meal) => (normalizeMealPlanEntry(meal.entry)?.appliedSubstitutions || []).map((substitution) => ({ ...substitution, mealId: getPlanMealId(meal.day, meal.mealType) })));
    const positive = applied.filter((substitution) => {
      const snapshot = substitution.substitutionCostSnapshot || {};
      const savings = snapshot.savingsResult || snapshot;
      return Number.isInteger(savings.estimatedWeeklySavingsCents) ? savings.estimatedWeeklySavingsCents > 0 && savings.complete !== false : true;
    });
    if (!positive.length) return [];
    return [createPlanSavingsReason({
      reasonId: "lower-cost-substitutions",
      reasonType: PLAN_SAVINGS_REASON_TYPES.LOWER_COST_SUBSTITUTIONS,
      message: `Uses ${numberWord(positive.length).toLowerCase()} lower-cost ingredient ${pluralize(positive.length, "substitution")}`,
      priority: 40,
      evidence: { substitutionIds: positive.map((item) => `${item.ruleId}:${item.originalIngredientOccurrenceId}`), mealIds: positive.map((item) => item.mealId), sourceSystems: ["substitution-system"] }
    })];
  }

  function buildPlanSavingsUseSoonReasons(pantrySummary = null) {
    const reasons = [];
    const useSoonCount = Number.isInteger(pantrySummary?.useSoonLotCountUsed) ? pantrySummary.useSoonLotCountUsed : 0;
    const openedCount = Number.isInteger(pantrySummary?.openedLotCountUsed) ? pantrySummary.openedLotCountUsed : 0;
    if (useSoonCount > 0) {
      reasons.push(createPlanSavingsReason({
        reasonId: "use-soon-pantry-items",
        reasonType: PLAN_SAVINGS_REASON_TYPES.USE_SOON_INGREDIENTS,
        message: `Uses ${numberWord(useSoonCount).toLowerCase()} Pantry ${pluralize(useSoonCount, "item")} marked for earlier use`,
        priority: 55,
        evidence: { useSoonLotCountUsed: useSoonCount, sourceSystems: ["pantry-first-planning"] }
      }));
    }
    if (openedCount > 0) {
      reasons.push(createPlanSavingsReason({
        reasonId: "opened-pantry-items",
        reasonType: PLAN_SAVINGS_REASON_TYPES.OPENED_PANTRY_ITEMS,
        message: `Uses ${numberWord(openedCount).toLowerCase()} already opened Pantry ${pluralize(openedCount, "item")}`,
        priority: 56,
        evidence: { openedLotCountUsed: openedCount, sourceSystems: ["pantry-first-planning"] }
      }));
    }
    return reasons;
  }

  function buildPlanSavingsComparison({ baseline, finalCostResult, finalConfidence, shoppingCoverage, planningResult, plan }) {
    if (!baseline) return { available: false, status: "no-baseline", estimatedDifferenceCents: null, warnings: ["A comparable original-plan cost is not available for this plan."] };
    const counts = getPlanSavingsMealCounts(plan, planningResult);
    if (!counts.completePlan) return { available: false, status: "partial-plan", estimatedDifferenceCents: null, warnings: ["The cost of a partial plan is not directly comparable with a complete plan."] };
    const baselineCost = baseline.groceryCostSummary?.weeklyGroceryCostCents;
    const finalCost = finalCostResult?.weeklySummary?.weeklyGroceryCostCents;
    const baselineComplete = baseline.priceConfidence?.completeGroceryTotalAvailable === true && Number.isInteger(baselineCost);
    const finalComplete = finalConfidence?.completeGroceryTotalAvailable === true && Number.isInteger(finalCost) && !finalCostResult?.weeklySummary?.unresolvedPurchaseGroupCount;
    const shoppingComplete = !shoppingCoverage || shoppingCoverage.shoppingCoverageComplete === true;
    if (!baselineComplete || !finalComplete || !shoppingComplete) {
      return {
        available: true,
        status: "incomplete",
        baselineType: baseline.baselineType,
        baselineLabel: baseline.baselineLabel || "Original estimated plan",
        finalLabel: "Budget Rescue plan",
        baselineGroceryCostCents: baselineComplete ? baselineCost : null,
        finalGroceryCostCents: finalComplete && shoppingComplete ? finalCost : null,
        estimatedDifferenceCents: null,
        currency: BUDGET_RESCUE_CURRENCY,
        baselinePriceConfidenceStatus: baseline.priceConfidence?.status || PRICE_CONFIDENCE_STATUSES.INCOMPLETE,
        finalPriceConfidenceStatus: finalConfidence?.status || PRICE_CONFIDENCE_STATUSES.INCOMPLETE,
        warnings: ["One or more grocery items need usable prices or purchase quantities before Chef Nova can compare the original and current plans accurately."]
      };
    }
    return {
      available: true,
      status: "complete",
      baselineType: baseline.baselineType,
      baselineLabel: baseline.baselineLabel || "Original estimated plan",
      baselineDescription: baseline.baselineDescription || "The first complete safe plan before budget-reduction repairs were applied.",
      finalLabel: plan?.planningMode === PLANNING_MODES.EMERGENCY ? "Emergency Plan" : "Budget Rescue plan",
      baselinePlanSignature: baseline.baselinePlanSignature,
      finalPlanSignature: buildMealPlanSignature(plan),
      baselineGroceryCostCents: baselineCost,
      finalGroceryCostCents: finalCost,
      estimatedDifferenceCents: baselineCost - finalCost,
      currency: BUDGET_RESCUE_CURRENCY,
      baselinePriceConfidenceStatus: baseline.priceConfidence?.status || PRICE_CONFIDENCE_STATUSES.ESTIMATED,
      finalPriceConfidenceStatus: finalConfidence?.status || PRICE_CONFIDENCE_STATUSES.ESTIMATED,
      comparisonPriceContextId: getPlanSavingsComparisonPriceContext().comparisonPriceContextId,
      warnings: []
    };
  }

  function getPlanSavingsStatus({ compatibilitySummary, counts, comparison }) {
    if (compatibilitySummary && compatibilitySummary.safe === false) return PLAN_SAVINGS_EXPLANATION_STATUSES.PLAN_REQUIRES_REVIEW;
    if (counts.requestedMealCount > 0 && counts.plannedMealCount > 0 && !counts.completePlan) return PLAN_SAVINGS_EXPLANATION_STATUSES.PARTIAL_PLAN;
    if (comparison?.status === "incomplete") return PLAN_SAVINGS_EXPLANATION_STATUSES.COMPARISON_INCOMPLETE;
    if (comparison?.status === "complete") {
      if (comparison.estimatedDifferenceCents > 0) return comparison.finalPriceConfidenceStatus === PRICE_CONFIDENCE_STATUSES.HIGH && comparison.baselinePriceConfidenceStatus === PRICE_CONFIDENCE_STATUSES.HIGH ? PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_HIGH_CONFIDENCE_REDUCTION : PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_ESTIMATED_REDUCTION;
      if (comparison.estimatedDifferenceCents === 0) return PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_NO_DIFFERENCE;
      return PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_HIGHER_COST;
    }
    if (comparison?.status === "no-baseline") return PLAN_SAVINGS_EXPLANATION_STATUSES.NO_COMPARABLE_BASELINE;
    return PLAN_SAVINGS_EXPLANATION_STATUSES.EXPLANATION_UNAVAILABLE;
  }

  function getPlanSavingsHeading(status, planningMode) {
    if (planningMode === PLANNING_MODES.EMERGENCY && [PLAN_SAVINGS_EXPLANATION_STATUSES.NO_COMPARABLE_BASELINE, PLAN_SAVINGS_EXPLANATION_STATUSES.COMPARISON_INCOMPLETE].includes(status)) return "How This Emergency Plan Uses Available Food";
    return {
      [PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_HIGH_CONFIDENCE_REDUCTION]: "How This Plan Reduces Cost",
      [PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_ESTIMATED_REDUCTION]: "How This Plan Reduces Cost",
      [PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_NO_DIFFERENCE]: "Why Chef Nova Selected This Plan",
      [PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_HIGHER_COST]: "Plan Cost and Practical Trade-Offs",
      [PLAN_SAVINGS_EXPLANATION_STATUSES.COMPARISON_INCOMPLETE]: "How This Plan Uses Your Pantry and Grocery Budget",
      [PLAN_SAVINGS_EXPLANATION_STATUSES.NO_COMPARABLE_BASELINE]: "Why Chef Nova Selected This Plan",
      [PLAN_SAVINGS_EXPLANATION_STATUSES.PARTIAL_PLAN]: "Why Chef Nova Selected These Meals",
      [PLAN_SAVINGS_EXPLANATION_STATUSES.PLAN_REQUIRES_REVIEW]: "Plan Explanation Requires Review",
      [PLAN_SAVINGS_EXPLANATION_STATUSES.EXPLANATION_UNAVAILABLE]: "Plan Explanation Unavailable"
    }[status] || "Plan Explanation Unavailable";
  }

  function getPlanSavingsSummary(status, comparison, counts) {
    if (status === PLAN_SAVINGS_EXPLANATION_STATUSES.PLAN_REQUIRES_REVIEW) return "Review meals that no longer match current requirements before relying on the cost comparison.";
    if (status === PLAN_SAVINGS_EXPLANATION_STATUSES.PARTIAL_PLAN) return `Chef Nova safely planned ${counts.plannedMealCount} of ${counts.requestedMealCount} requested meals. The cost of this partial plan is not directly comparable with a complete plan.`;
    if (status === PLAN_SAVINGS_EXPLANATION_STATUSES.COMPARISON_INCOMPLETE) return "Chef Nova can explain the plan decisions, but the complete cost difference is not available until missing prices or quantities are resolved.";
    if (status === PLAN_SAVINGS_EXPLANATION_STATUSES.NO_COMPARABLE_BASELINE) return "Chef Nova used Pantry, package, price, and meal-planning information to reduce unnecessary purchases. A comparable original-plan cost is not available for this plan.";
    if (status === PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_NO_DIFFERENCE) return "No estimated grocery-cost difference. The selected package and price data produce the same estimated grocery total as the comparison plan.";
    if (status === PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_HIGHER_COST) return `The current plan is estimated to cost ${formatCostCents(Math.abs(comparison.estimatedDifferenceCents))} more than the initial safe plan.`;
    if ([PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_HIGH_CONFIDENCE_REDUCTION, PLAN_SAVINGS_EXPLANATION_STATUSES.COMPLETE_ESTIMATED_REDUCTION].includes(status)) return `The Budget Rescue plan is estimated to cost ${formatCostCents(comparison.estimatedDifferenceCents)} less than the initial safe plan.`;
    return "Chef Nova could not verify the current comparison data. Review the meal plan, Pantry, Shopping List, and grocery prices before relying on a savings estimate.";
  }

  function sortPlanSavingsReasons(reasons = []) {
    const bestByOverlap = new Map();
    reasons.filter((reason) => reason?.message).forEach((reason) => {
      const key = reason.overlapGroup || reason.reasonId;
      const existing = bestByOverlap.get(key);
      if (!existing || comparePlanSavingsReasons(reason, existing) < 0) bestByOverlap.set(key, reason);
    });
    return Array.from(bestByOverlap.values()).sort(comparePlanSavingsReasons);
  }

  function comparePlanSavingsReasons(a, b) {
    if ((a.priority || 99) !== (b.priority || 99)) return (a.priority || 99) - (b.priority || 99);
    const impactA = Number.isInteger(a.estimatedImpactCents) ? a.estimatedImpactCents : -1;
    const impactB = Number.isInteger(b.estimatedImpactCents) ? b.estimatedImpactCents : -1;
    if (impactA !== impactB) return impactB - impactA;
    const mealsA = a.evidence?.mealIds?.length || 0;
    const mealsB = b.evidence?.mealIds?.length || 0;
    if (mealsA !== mealsB) return mealsB - mealsA;
    const groupsA = a.evidence?.purchaseGroupIds?.length || (a.evidence?.purchaseGroupId ? 1 : 0);
    const groupsB = b.evidence?.purchaseGroupIds?.length || (b.evidence?.purchaseGroupId ? 1 : 0);
    if (groupsA !== groupsB) return groupsB - groupsA;
    return String(a.reasonId).localeCompare(String(b.reasonId));
  }

  function derivePlanSavingsExplanation({
    planningMode = getCurrentPlanningMode(),
    planningRequest = null,
    planningResult = null,
    initialPlanResult = null,
    repairHistory = null,
    weeklyCostSummary = null,
    priceConfidence = null,
    shoppingCoverage = null,
    pantrySummary = null,
    purchaseGroups = null,
    leftoverSummary = null,
    substitutionSummary = null,
    eligibilitySummary = null,
    comparisonPriceContext = null,
    plan = state.mealPlans
  } = {}) {
    const costResult = purchaseGroups && weeklyCostSummary ? { purchaseGroups, weeklySummary: weeklyCostSummary } : calculateMealPlanCostsForPlan(plan, state.pantry);
    const finalSummary = weeklyCostSummary || costResult?.weeklySummary || {};
    const finalConfidence = priceConfidence || (costResult ? derivePriceConfidence({ purchaseGroups: costResult.purchaseGroups, weeklyCostSummary: finalSummary }) : null);
    const currentShoppingCoverage = shoppingCoverage || (() => {
      try {
        return deriveShoppingCoverage(deriveShoppingListViewModel({ activeFilter: SHOPPING_LIST_FILTERS.ALL }).items.filter((item) => item.purchaseGroupId));
      } catch {
        return null;
      }
    })();
    const compatibility = eligibilitySummary || validateBudgetStatusPlanCompatibility(plan, buildMealPlanGenerationContext());
    const baseline = initialPlanResult || getCurrentPlanSavingsBaseline(plan, planningResult);
    const counts = getPlanSavingsMealCounts(plan, planningResult);
    const comparison = buildPlanSavingsComparison({ baseline, finalCostResult: costResult, finalConfidence, shoppingCoverage: currentShoppingCoverage, planningResult, plan });
    const baselineGroupComparison = baseline?.purchaseGroups ? comparePlanSavingsPurchaseGroups(baseline.purchaseGroups, costResult?.purchaseGroups || []) : null;
    const pantry = pantrySummary || buildPantryAllocationForPlan(plan)?.summary || {};
    const leftover = leftoverSummary || plan?.leftoverBenefitSnapshot || {};
    const reasons = sortPlanSavingsReasons([
      ...buildPlanSavingsPantryReasons({ pantrySummary: pantry, purchaseGroups: costResult?.purchaseGroups || [] }),
      ...buildPlanSavingsSharedReasons(costResult?.purchaseGroups || []),
      ...buildPlanSavingsLeftoverReasons(plan, leftover),
      ...buildPlanSavingsSubstitutionReasons(plan),
      ...buildPlanSavingsUseSoonReasons(pantry),
      ...(baselineGroupComparison?.singleUsePurchaseGroupsAvoided?.length ? [createPlanSavingsReason({
        reasonId: "single-use-purchases-avoided",
        reasonType: PLAN_SAVINGS_REASON_TYPES.SINGLE_USE_PURCHASES_AVOIDED,
        message: `Avoids purchasing ${numberWord(baselineGroupComparison.singleUsePurchaseGroupsAvoided.length).toLowerCase()} single-use ${pluralize(baselineGroupComparison.singleUsePurchaseGroupsAvoided.length, "ingredient")}`,
        priority: 45,
        evidence: { purchaseGroupIds: baselineGroupComparison.singleUsePurchaseGroupsAvoided.map((group) => group.purchaseGroupId), sourceSystems: ["budget-planning-algorithm", "cost-engine"] }
      })] : []),
      ...(baselineGroupComparison?.uniqueGroupDifference > 0 ? [createPlanSavingsReason({
        reasonId: "fewer-unique-grocery-groups",
        reasonType: PLAN_SAVINGS_REASON_TYPES.FEWER_UNIQUE_GROCERY_GROUPS,
        message: `Uses ${numberWord(baselineGroupComparison.uniqueGroupDifference).toLowerCase()} fewer unique grocery ${pluralize(baselineGroupComparison.uniqueGroupDifference, "item")} than the original plan`,
        priority: 60,
        evidence: { baselineUniquePurchaseGroupCount: baselineGroupComparison.baselineUniquePurchaseGroupCount, finalUniquePurchaseGroupCount: baselineGroupComparison.finalUniquePurchaseGroupCount, sourceSystems: ["cost-engine"] }
      })] : []),
      ...(baselineGroupComparison?.optionalOnlyPurchaseGroupsAvoided?.length ? [createPlanSavingsReason({
        reasonId: "optional-purchases-removed",
        reasonType: PLAN_SAVINGS_REASON_TYPES.OPTIONAL_PURCHASES_REMOVED,
        message: `Removes ${numberWord(baselineGroupComparison.optionalOnlyPurchaseGroupsAvoided.length).toLowerCase()} optional grocery ${pluralize(baselineGroupComparison.optionalOnlyPurchaseGroupsAvoided.length, "purchase", "purchases")}`,
        priority: 65,
        evidence: { purchaseGroupIds: baselineGroupComparison.optionalOnlyPurchaseGroupsAvoided.map((group) => group.purchaseGroupId), sourceSystems: ["budget-planning-algorithm", "shopping-list"] }
      })] : []),
      ...(baselineGroupComparison?.lowerPackageSurplusGroupDifference > 0 ? [createPlanSavingsReason({
        reasonId: "lower-package-surplus",
        reasonType: PLAN_SAVINGS_REASON_TYPES.LOWER_PACKAGE_SURPLUS,
        message: "Uses package sizes more fully and leaves less estimated unused package quantity",
        priority: 75,
        evidence: { lowerPackageSurplusGroupDifference: baselineGroupComparison.lowerPackageSurplusGroupDifference, sourceSystems: ["cost-engine"] }
      })] : [])
    ]);
    const status = getPlanSavingsStatus({ compatibilitySummary: compatibility, counts, comparison });
    const primaryReasons = reasons.slice(0, PLAN_SAVINGS_EXPLANATION_MAX_PRIMARY_REASONS);
    return {
      explanationVersion: PLAN_SAVINGS_EXPLANATION_VERSION,
      status,
      heading: getPlanSavingsHeading(status, planningMode),
      summary: getPlanSavingsSummary(status, comparison, counts),
      reasons: primaryReasons,
      additionalReasons: reasons.slice(PLAN_SAVINGS_EXPLANATION_MAX_PRIMARY_REASONS),
      comparison,
      practicalBenefits: reasons.filter((reason) => reason.impactType === "practical-benefit"),
      warnings: Array.from(new Set([...(comparison?.warnings || []), "Individual plan features can overlap, so the reasons below should not be added together as separate savings amounts."])),
      actions: deriveRespectfulBudgetActions({ messageType: comparison?.status === "incomplete" ? RESPECTFUL_BUDGET_MESSAGE_TYPES.INCOMPLETE_PRICE_ESTIMATE : RESPECTFUL_BUDGET_MESSAGE_TYPES.STATUS_UNAVAILABLE, confidence: finalConfidence, shoppingCoverage: currentShoppingCoverage, compatibility, substitutionCount: substitutionSummary?.availableLowerCostActionCount || 0, pantrySummary: pantry, planningRequest, plan }),
      planSignature: buildMealPlanSignature(plan),
      baselinePlanSignature: baseline?.baselinePlanSignature || null,
      priceContext: comparisonPriceContext || getPlanSavingsComparisonPriceContext(),
      calculatedAt: getCurrentIsoString()
    };
  }

  function buildBudgetStatusPanelActions({ status, confidence, plan, compatibility, substitutionCount }) {
    const actions = [];
    if (confidence?.unresolvedItemCount > 0) {
      const missingPrices = confidence.unresolvedItems.filter((item) => item.reasonCode === "missing-price").length;
      if (missingPrices) actions.push({ label: "Add Missing Prices", type: "primary", attr: "data-add-missing-prices" });
      if (confidence.unresolvedItemCount - missingPrices > 0) actions.push({ label: "Review Cost Issues", type: "secondary", attr: "data-review-cost-issues" });
    }
    if (compatibility?.conflictCount > 0) actions.push({ label: "Review Meal Plan", type: "secondary", attr: "data-review-budget-status-actions" });
    if (substitutionCount > 0 && status === BUDGET_STATUS_PANEL_STATUSES.ABOVE_WEEKLY_BUDGET) actions.push({ label: "Review Lower-Cost Changes", type: "secondary", attr: "data-review-budget-status-actions" });
    if (state.pantry.length) actions.push({ label: "Edit Pantry", type: "secondary", attr: "data-budget-edit-pantry" });
    if (DAYS.some((day) => MEALS.some((mealType) => normalizeMealPlanEntry((plan?.[day] || {})[mealType])))) actions.push({ label: "Review Shopping List", type: "secondary", attr: "data-page=\"shopping-list\"" });
    return actions;
  }

  function deriveBudgetStatusPanelModel({
    planningRequest = null,
    planningResult = null,
    weeklyCostSummary = null,
    priceConfidence = null,
    pantrySummary = null,
    leftoverSummary = null,
    substitutionSummary = null,
    compatibilitySummary = null,
    plan = state.mealPlans,
    costResult = null
  } = {}) {
    if (![PLANNING_MODES.BUDGET_RESCUE, PLANNING_MODES.EMERGENCY].includes(getCurrentPlanningMode())) {
      return { status: BUDGET_STATUS_PANEL_STATUSES.UNAVAILABLE, hidden: true };
    }
    const context = buildMealPlanGenerationContext();
    const request = planningRequest || normalizeBudgetPlanningRequest(context, {});
    const budgetDraft = normalizeBudgetRescueDraft(normalizePlanningModeInputs(state.planningModeInputs).budgetRescue);
    const emergencyDraft = normalizeEmergencyPlanDraft(normalizePlanningModeInputs(state.planningModeInputs).emergency);
    const isEmergency = getCurrentPlanningMode() === PLANNING_MODES.EMERGENCY || request?.planningMode === PLANNING_MODES.EMERGENCY;
    const weeklyBudgetCents = Number.isInteger(request?.budget?.weeklyBudgetCents) ? request.budget.weeklyBudgetCents : isEmergency ? emergencyDraft.availableBudgetCents : budgetDraft.weeklyBudgetCents || null;
    const planningTargetCents = Number.isInteger(request?.budget?.planningTargetCents) ? request.budget.planningTargetCents : weeklyBudgetCents ? getBudgetRescuePlanningTargetCents(budgetDraft) : null;
    const priceCushionCents = Number.isInteger(weeklyBudgetCents) && Number.isInteger(planningTargetCents) ? Math.max(0, weeklyBudgetCents - planningTargetCents) : null;
    const currentCostResult = costResult || calculateMealPlanCostsForPlan(plan, state.pantry);
    const summary = weeklyCostSummary || currentCostResult?.weeklySummary || {};
    const confidence = priceConfidence || (currentCostResult ? derivePriceConfidence({ purchaseGroups: currentCostResult.purchaseGroups, weeklyCostSummary: summary }) : null);
    const pantryAllocation = pantrySummary || buildPantryAllocationForPlan(plan);
    const metrics = summarizeBudgetStatusPlanMetrics(plan, currentCostResult, pantryAllocation);
    const requestedMeals = planningResult?.slots?.length || getBudgetStatusRequestedMealCount(request);
    const filledMeals = planningResult?.selectedMeals?.length || metrics.mealsPlannedCount;
    const completePlan = requestedMeals > 0 && filledMeals >= requestedMeals;
    const compatibility = compatibilitySummary || validateBudgetStatusPlanCompatibility(plan, context);
    const substitutionCount = Number.isInteger(substitutionSummary?.availableLowerCostActionCount)
      ? substitutionSummary.availableLowerCostActionCount
      : countAvailableLowerCostSubstitutionsForPlan(plan);
    const shoppingCoverage = (() => {
      try {
        return deriveShoppingCoverage(deriveShoppingListViewModel({ activeFilter: SHOPPING_LIST_FILTERS.ALL }).items.filter((item) => item.purchaseGroupId));
      } catch (error) {
        console.warn("Budget Status shopping coverage unavailable", error);
        return null;
      }
    })();
    const completeGroceryTotalAvailable = Boolean(confidence?.completeGroceryTotalAvailable && Number.isInteger(summary.weeklyGroceryCostCents) && !summary.unresolvedPurchaseGroupCount);
    const cost = completeGroceryTotalAvailable ? summary.weeklyGroceryCostCents : null;
    let status = BUDGET_STATUS_PANEL_STATUSES.UNAVAILABLE;
    if (planningResult?.status === BUDGET_PLAN_STATUSES.NO_SAFE_PLAN) status = BUDGET_STATUS_PANEL_STATUSES.NO_SAFE_PLAN;
    else if (!compatibility.safe) status = BUDGET_STATUS_PANEL_STATUSES.PLAN_REQUIRES_REVIEW;
    else if (requestedMeals > 0 && filledMeals > 0 && !completePlan) status = BUDGET_STATUS_PANEL_STATUSES.PARTIAL_PLAN;
    else if (!completeGroceryTotalAvailable) status = BUDGET_STATUS_PANEL_STATUSES.INCOMPLETE_ESTIMATE;
    else if (cost === 0) status = BUDGET_STATUS_PANEL_STATUSES.NO_PURCHASES_REQUIRED;
    else if (Number.isInteger(planningTargetCents) && cost <= planningTargetCents) status = BUDGET_STATUS_PANEL_STATUSES.WITHIN_PLANNING_TARGET;
    else if (Number.isInteger(weeklyBudgetCents) && cost <= weeklyBudgetCents) status = BUDGET_STATUS_PANEL_STATUSES.WITHIN_WEEKLY_BUDGET;
    else if (Number.isInteger(weeklyBudgetCents) && cost > weeklyBudgetCents) status = BUDGET_STATUS_PANEL_STATUSES.ABOVE_WEEKLY_BUDGET;
    const remainingBudgetCents = completeGroceryTotalAvailable && Number.isInteger(weeklyBudgetCents) ? Math.max(0, weeklyBudgetCents - cost) : null;
    const amountAboveBudgetCents = completeGroceryTotalAvailable && Number.isInteger(weeklyBudgetCents) ? Math.max(0, cost - weeklyBudgetCents) : null;
    const remainingPlanningTargetCents = completeGroceryTotalAvailable && Number.isInteger(planningTargetCents) ? Math.max(0, planningTargetCents - cost) : null;
    const amountAbovePlanningTargetCents = completeGroceryTotalAvailable && Number.isInteger(planningTargetCents) ? Math.max(0, cost - planningTargetCents) : null;
    const budgetUsedPercentExact = completeGroceryTotalAvailable && Number.isInteger(weeklyBudgetCents) && weeklyBudgetCents > 0 ? (cost / weeklyBudgetCents) * 100 : null;
    const model = {
      version: BUDGET_STATUS_PANEL_VERSION,
      status,
      statusLabel: getBudgetStatusPanelLabel(status),
      headline: "",
      supportingMessage: "",
      budget: {
        label: isEmergency ? "Available Emergency budget" : "Weekly budget",
        weeklyBudgetCents,
        planningTargetCents,
        priceCushionCents,
        weeklyGroceryCostCents: cost,
        remainingBudgetCents,
        amountAboveBudgetCents,
        remainingPlanningTargetCents,
        amountAbovePlanningTargetCents,
        knownPurchaseSubtotalCents: Number.isInteger(summary["knownPurchaseSubtotalCents"]) ? summary["knownPurchaseSubtotalCents"] : 0,
        budgetUsedPercentExact,
        budgetUsedPercentDisplay: budgetUsedPercentExact === null ? null : Math.round(budgetUsedPercentExact * 10) / 10,
        completeGroceryTotalAvailable,
        showFinalBudgetProgress: completeGroceryTotalAvailable && completePlan && compatibility.safe && Number.isInteger(weeklyBudgetCents) && weeklyBudgetCents > 0
      },
      priceConfidence: confidence ? {
        status: confidence.status,
        label: priceConfidenceStatusLabel(confidence.status),
        coveragePercentDisplay: confidence.coveragePercentDisplay,
        unresolvedItemCount: confidence.unresolvedItemCount,
        totalRequiredGroceryItemCount: confidence.totalRequiredGroceryItemCount
      } : null,
      pantry: {
        ingredientGroupCountUsed: metrics.pantryIngredientGroupCountUsed,
        savingsCents: Number.isInteger(pantryAllocation?.summary?.estimatedSavingsCents) ? pantryAllocation.summary.estimatedSavingsCents : null
      },
      plan: {
        mealsPlannedCount: filledMeals,
        requestedMealCount: requestedMeals,
        completePlan,
        compatibility,
        planningMode: isEmergency ? PLANNING_MODES.EMERGENCY : PLANNING_MODES.BUDGET_RESCUE
      },
      leftoverSummary,
      substitutionSummary: { availableLowerCostActionCount: substitutionCount },
      shoppingCoverage,
      metrics,
      actions: []
    };
    model.respectfulMessage = deriveRespectfulBudgetMessage({
      planningMode: model.plan.planningMode,
      planningRequest: request,
      planningResult,
      compatibilitySummary: compatibility,
      weeklyCostSummary: summary,
      priceConfidence: confidence,
      shoppingCoverage,
      pantryOpportunities: model.pantry,
      substitutionRecommendations: model.substitutionSummary,
      repairActions: planningResult?.repairHistory || [],
      plan
    });
    model.headline = model.respectfulMessage.primaryMessage;
    model.supportingMessage = model.respectfulMessage.secondaryMessage;
    model.actions = model.respectfulMessage.actions;
    model.actionCount = model.actions.length;
    return model;
  }

  function getBudgetStatusPanelLabel(status) {
    return {
      [BUDGET_STATUS_PANEL_STATUSES.WITHIN_PLANNING_TARGET]: "Within planning target",
      [BUDGET_STATUS_PANEL_STATUSES.WITHIN_WEEKLY_BUDGET]: "Within weekly budget",
      [BUDGET_STATUS_PANEL_STATUSES.ABOVE_WEEKLY_BUDGET]: "Above budget",
      [BUDGET_STATUS_PANEL_STATUSES.INCOMPLETE_ESTIMATE]: "Incomplete estimate",
      [BUDGET_STATUS_PANEL_STATUSES.PARTIAL_PLAN]: "Partial plan",
      [BUDGET_STATUS_PANEL_STATUSES.PLAN_REQUIRES_REVIEW]: "Needs review",
      [BUDGET_STATUS_PANEL_STATUSES.NO_SAFE_PLAN]: "No safe plan",
      [BUDGET_STATUS_PANEL_STATUSES.NO_PURCHASES_REQUIRED]: "No purchases required",
      [BUDGET_STATUS_PANEL_STATUSES.UNAVAILABLE]: "Budget status unavailable"
    }[status] || "Budget status unavailable";
  }

  function getBudgetStatusPanelHeadline(status, details = {}) {
    if (status === BUDGET_STATUS_PANEL_STATUSES.ABOVE_WEEKLY_BUDGET) {
      const amount = Number.isInteger(details.amountAboveBudgetCents) ? `approximately ${formatCostCents(details.amountAboveBudgetCents)} ` : "";
      const actionText = details.substitutionCount ? ` Chef Nova found ${details.substitutionCount} possible lower-cost ${pluralize(details.substitutionCount, "change")}.` : "";
      return `The plan is ${amount}above the selected budget.${actionText}`;
    }
    return {
      [BUDGET_STATUS_PANEL_STATUSES.WITHIN_PLANNING_TARGET]: "Your current plan is within the selected budget.",
      [BUDGET_STATUS_PANEL_STATUSES.WITHIN_WEEKLY_BUDGET]: "Your current plan fits the weekly budget and uses part of the cushion.",
      [BUDGET_STATUS_PANEL_STATUSES.INCOMPLETE_ESTIMATE]: "Chef Nova needs more price details before confirming the full budget status.",
      [BUDGET_STATUS_PANEL_STATUSES.PARTIAL_PLAN]: "This is a partial plan, so Chef Nova cannot confirm the full weekly budget yet.",
      [BUDGET_STATUS_PANEL_STATUSES.PLAN_REQUIRES_REVIEW]: "One or more planned meals need review before budget status can be confirmed.",
      [BUDGET_STATUS_PANEL_STATUSES.NO_SAFE_PLAN]: "Chef Nova could not find a safe Budget Rescue plan with the current settings.",
      [BUDGET_STATUS_PANEL_STATUSES.NO_PURCHASES_REQUIRED]: "Your planned recipe groceries are currently covered by Pantry items.",
      [BUDGET_STATUS_PANEL_STATUSES.UNAVAILABLE]: "Create a Budget Rescue plan to see budget status."
    }[status] || "Create a Budget Rescue plan to see budget status.";
  }

  function getBudgetStatusPanelSupportingMessage(status, details = {}) {
    if (status === BUDGET_STATUS_PANEL_STATUSES.INCOMPLETE_ESTIMATE) {
      const unresolved = details.confidence?.unresolvedItemCount || 0;
      return unresolved ? `${unresolved} grocery ${pluralize(unresolved, "item")} need prices or measurable quantities.` : "Review grocery prices before relying on the total.";
    }
    if (status === BUDGET_STATUS_PANEL_STATUSES.PARTIAL_PLAN) return `${details.filledMeals} of ${details.requestedMeals} requested meals are planned.`;
    if (status === BUDGET_STATUS_PANEL_STATUSES.PLAN_REQUIRES_REVIEW) return `${details.compatibility?.conflictCount || 0} meal ${pluralize(details.compatibility?.conflictCount || 0, "slot")} conflicts with current requirements.`;
    if (status === BUDGET_STATUS_PANEL_STATUSES.WITHIN_PLANNING_TARGET && Number.isInteger(details.priceCushionCents) && details.priceCushionCents > 0) return "The selected price cushion remains available.";
    if (status === BUDGET_STATUS_PANEL_STATUSES.WITHIN_WEEKLY_BUDGET) return "The estimate is above the planning target but still within the weekly budget.";
    if (status === BUDGET_STATUS_PANEL_STATUSES.NO_PURCHASES_REQUIRED) return "Pantry coverage can change if meals, servings, or Pantry items change.";
    return "Actual store prices may vary.";
  }

  function renderBudgetStatusProgress(model) {
    if (!model?.budget?.showFinalBudgetProgress) return "";
    const actual = model.budget.budgetUsedPercentExact;
    const capped = Math.min(100, Math.max(0, Math.round(actual)));
    const display = model.budget.budgetUsedPercentDisplay;
    const variance = model.budget.amountAboveBudgetCents > 0
      ? `${formatCostCents(model.budget.amountAboveBudgetCents)} above budget`
      : `${formatCostCents(model.budget.remainingBudgetCents || 0)} remaining`;
    return `<div class="budget-status-progress-wrap">
      <div class="budget-status-progress-label"><span>Budget used</span><strong>${escapeHtml(String(display))}%</strong></div>
      <div class="budget-status-progress" role="progressbar" aria-label="Weekly grocery budget used" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${escapeHtml(String(capped))}" aria-valuetext="${escapeHtml(`${display}% used, ${variance}`)}">
        <span style="width: ${escapeHtml(String(Math.min(100, actual)))}%"></span>
      </div>
    </div>`;
  }

  function renderBudgetStatusPanel(model = deriveBudgetStatusPanelModel()) {
    if (!model || model.hidden) return "";
    const message = model.respectfulMessage || deriveRespectfulBudgetMessage({ planningMode: model.plan?.planningMode, plan: state.mealPlans });
    const budget = model.budget || {};
    const complete = budget.completeGroceryTotalAvailable;
    const metricRows = [
      [budget.label || "Weekly budget", Number.isInteger(budget.weeklyBudgetCents) ? formatCostCents(budget.weeklyBudgetCents) : "Not set"],
      ...(model.plan.planningMode === PLANNING_MODES.EMERGENCY ? [] : [["Planning target", Number.isInteger(budget.planningTargetCents) ? formatCostCents(budget.planningTargetCents) : "Not set"], ["Price cushion", Number.isInteger(budget.priceCushionCents) ? formatCostCents(budget.priceCushionCents) : "Not set"]]),
      [complete ? "Estimated grocery cost" : "Known priced subtotal", formatCostCents(complete ? budget.weeklyGroceryCostCents : budget.knownPurchaseSubtotalCents || 0)],
      ...(complete ? [[budget.amountAboveBudgetCents > 0 ? "Above budget" : "Remaining budget", formatCostCents(budget.amountAboveBudgetCents > 0 ? budget.amountAboveBudgetCents : budget.remainingBudgetCents || 0)]] : []),
      ["Price confidence", model.priceConfidence ? `${model.priceConfidence.label}${model.priceConfidence.coveragePercentDisplay !== null && model.priceConfidence.coveragePercentDisplay !== undefined ? ` (${model.priceConfidence.coveragePercentDisplay}%)` : ""}` : "Unavailable"],
      ["Pantry items used", Number.isInteger(model.pantry.ingredientGroupCountUsed) ? String(model.pantry.ingredientGroupCountUsed) : "Unavailable"],
      ["Meals planned", `${model.plan.mealsPlannedCount} / ${model.plan.requestedMealCount}`],
      ["Avg. ingredient cost per serving", Number.isInteger(model.metrics.averageIngredientCostPerServingCents) ? formatCostCents(model.metrics.averageIngredientCostPerServingCents) : "Unavailable"]
    ];
    const actionList = message.actions.length > 1 ? `<ol class="respectful-budget-options">${message.actions.map((action) => `<li>${escapeHtml(action.label)}</li>`).join("")}</ol>` : "";
    const actions = message.actions.length ? `<div class="budget-status-actions" aria-label="Budget status actions">${message.actions.map((action) => `<button class="button ${action.actionId === RESPECTFUL_BUDGET_ACTION_IDS.ADD_MISSING_PRICES ? "primary" : "secondary"} small" type="button" ${action.attr} aria-describedby="budgetActionDescription-${escapeHtml(action.actionId)}">${escapeHtml(action.label)}</button><span class="sr-only" id="budgetActionDescription-${escapeHtml(action.actionId)}">${escapeHtml(action.description || action.label)}</span>`).join("")}</div>` : "";
    const details = message.detailLines?.length ? `<ul class="respectful-budget-details">${message.detailLines.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul>` : "";
    const safety = message.safetyMessage ? `<p class="budget-status-safety-note">${escapeHtml(message.safetyMessage)}</p>` : "";
    return `<section class="budget-status-panel status-${escapeHtml(model.status)}" aria-labelledby="budgetStatusHeading">
      <div class="budget-status-header">
        <div>
          <span class="eyebrow">BUDGET STATUS</span>
          <h3 id="budgetStatusHeading">${escapeHtml(message.heading)}</h3>
          <p>${escapeHtml(message.primaryMessage)}</p>
          <p class="budget-status-support">${escapeHtml(message.secondaryMessage)}</p>
          ${safety}
        </div>
        <strong class="budget-status-badge">${escapeHtml(model.statusLabel)}</strong>
      </div>
      ${details}
      <dl class="budget-status-grid">${metricRows.map(([term, value]) => `<div><dt>${escapeHtml(term)}</dt><dd>${escapeHtml(value)}</dd></div>`).join("")}</dl>
      ${renderBudgetStatusProgress(model)}
      <p class="budget-status-action-count">${escapeHtml(getActionCountSentence(message.actions.length))}</p>
      ${actionList}
      ${actions}
      <div class="sr-only" aria-live="polite" aria-atomic="true">${escapeHtml(message.liveRegionText)}</div>
    </section>`;
  }

  function renderPlanSavingsExplanation(explanation = derivePlanSavingsExplanation()) {
    if (![PLANNING_MODES.BUDGET_RESCUE, PLANNING_MODES.EMERGENCY].includes(getCurrentPlanningMode())) return "";
    if (!explanation || explanation.status === PLAN_SAVINGS_EXPLANATION_STATUSES.EXPLANATION_UNAVAILABLE) return "";
    const reasons = explanation.reasons?.length
      ? `<ul class="plan-savings-reasons">${explanation.reasons.map((reason) => `<li>${escapeHtml(reason.message)}</li>`).join("")}</ul>`
      : `<p>Chef Nova can explain the plan after meals, Pantry, prices, and Shopping List coverage are available.</p>`;
    const more = explanation.additionalReasons?.length
      ? `<details class="plan-savings-more"><summary>View More Details</summary><ul>${explanation.additionalReasons.map((reason) => `<li>${escapeHtml(reason.message)}</li>`).join("")}</ul></details>`
      : "";
    const comparison = [
      PLAN_SAVINGS_EXPLANATION_STATUSES.PLAN_REQUIRES_REVIEW,
      PLAN_SAVINGS_EXPLANATION_STATUSES.PARTIAL_PLAN
    ].includes(explanation.status) ? "" : renderPlanSavingsComparison(explanation);
    const warnings = explanation.warnings?.length ? `<ul class="plan-savings-warnings">${explanation.warnings.map((warning) => `<li>${escapeHtml(warning)}</li>`).join("")}</ul>` : "";
    const actions = explanation.actions?.length ? `<div class="budget-status-actions">${explanation.actions.map((action) => `<button class="button ${action.actionId === RESPECTFUL_BUDGET_ACTION_IDS.ADD_MISSING_PRICES ? "primary" : "secondary"} small" type="button" ${action.attr}>${escapeHtml(action.label)}</button>`).join("")}</div>` : "";
    return `<section class="plan-savings-explanation status-${escapeHtml(explanation.status)}" aria-labelledby="planSavingsHeading">
      <div class="plan-savings-header">
        <div>
          <span class="eyebrow">PLAN EXPLANATION</span>
          <h3 id="planSavingsHeading">${escapeHtml(explanation.heading)}</h3>
          <p>${escapeHtml(explanation.summary)}</p>
        </div>
      </div>
      ${reasons}
      ${more}
      ${comparison}
      ${warnings}
      ${actions}
      <div class="sr-only" aria-live="polite" aria-atomic="true">Plan explanation updated. ${escapeHtml(explanation.summary)}</div>
    </section>`;
  }

  function renderPlanSavingsComparison(explanation) {
    const comparison = explanation?.comparison || {};
    if (!comparison.available && comparison.status === "no-baseline") {
      return `<details class="plan-savings-comparison"><summary>View Cost Comparison</summary><div class="plan-savings-comparison-body"><h4>Cost comparison unavailable</h4><p>A comparable original-plan cost is not available for this plan.</p></div></details>`;
    }
    if (comparison.status === "incomplete") {
      const knownRows = [
        ["Original estimated plan", Number.isInteger(comparison.baselineGroceryCostCents) ? formatCostCents(comparison.baselineGroceryCostCents) : "Needs price review"],
        [comparison.finalLabel || "Budget Rescue plan", Number.isInteger(comparison.finalGroceryCostCents) ? formatCostCents(comparison.finalGroceryCostCents) : "Needs price review"]
      ];
      return `<details class="plan-savings-comparison"><summary>View Cost Comparison</summary><div class="plan-savings-comparison-body"><h4>Cost comparison unavailable</h4><p>One or more grocery items need usable prices or purchase quantities before Chef Nova can compare the original and current plans accurately.</p>${renderPlanSavingsComparisonRows(knownRows)}<p>Actual store prices may vary.</p></div></details>`;
    }
    if (comparison.status !== "complete") return "";
    const differenceLabel = comparison.estimatedDifferenceCents > 0 ? "Estimated difference" : comparison.estimatedDifferenceCents < 0 ? "Estimated additional cost" : "Estimated difference";
    const differenceValue = comparison.estimatedDifferenceCents < 0 ? formatCostCents(Math.abs(comparison.estimatedDifferenceCents)) : formatCostCents(comparison.estimatedDifferenceCents);
    const rows = [
      [comparison.baselineLabel || "Original estimated plan", formatCostCents(comparison.baselineGroceryCostCents)],
      [comparison.finalLabel || "Budget Rescue plan", formatCostCents(comparison.finalGroceryCostCents)],
      [differenceLabel, differenceValue],
      ["Original plan price confidence", priceConfidenceStatusLabel(comparison.baselinePriceConfidenceStatus)],
      [`${comparison.finalLabel || "Budget Rescue"} price confidence`, priceConfidenceStatusLabel(comparison.finalPriceConfidenceStatus)]
    ];
    return `<details class="plan-savings-comparison"><summary>View Cost Comparison</summary><div class="plan-savings-comparison-body"><h4>Cost Comparison</h4>${renderPlanSavingsComparisonRows(rows)}<p>${escapeHtml(comparison.baselineDescription || "The original estimate represents the first complete safe plan before budget-reduction repairs were applied.")}</p><p>Both plans were recalculated using the same Pantry and price context.</p><p>Compared using prices available on ${escapeHtml(formatEmergencyDate(explanation.priceContext?.calculationDate || getCurrentDateString()))}. Actual store prices may vary.</p></div></details>`;
  }

  function renderPlanSavingsComparisonRows(rows = []) {
    return `<dl class="plan-savings-comparison-grid">${rows.map(([term, value]) => `<div><dt>${escapeHtml(term)}</dt><dd>${escapeHtml(value)}</dd></div>`).join("")}</dl>`;
  }

  function openBudgetStatusPossibleChanges() {
    const firstSubstitution = $(".substitution-options");
    if (firstSubstitution) {
      firstSubstitution.scrollIntoView({ behavior: "smooth", block: "center" });
      const button = $("button", firstSubstitution);
      if (button) button.focus();
      showNotification("Review lower-cost changes in the plan preview.", "info");
      return;
    }
    showNotification("Review meals, Pantry, prices, or the Shopping List to adjust this Budget Rescue plan.", "info");
  }

  function createFourDayBudgetPreview() {
    const previousInputs = normalizePlanningModeInputs(state.planningModeInputs);
    const mode = getCurrentPlanningMode();
    const nextInputs = normalizePlanningModeInputs(previousInputs);
    if (mode === PLANNING_MODES.EMERGENCY) {
      const emergency = normalizeEmergencyPlanDraft(nextInputs.emergency);
      const startDate = emergency.startDate || getEmergencyDefaultStartDate({ rawText: emergency.naturalLanguageRequest || "" });
      const endDate = addCalendarDays(startDate, 3);
      nextInputs.emergency = normalizeEmergencyPlanDraft({
        ...emergency,
        startDate,
        endDate,
        numberOfDays: 4,
        interpretationConfirmed: true,
        interpretedAt: getCurrentIsoString(),
        referenceLocalDate: getEmergencyLocalDateString(),
        parseResult: {
          ...emergency.parseResult,
          status: EMERGENCY_PARSE_STATUSES.PARSED,
          endDate,
          numberOfDays: 4,
          warnings: []
        }
      });
    } else {
      nextInputs.budgetRescue = normalizeBudgetRescueDraft({
        ...nextInputs.budgetRescue,
        household: { ...nextInputs.budgetRescue.household, numberOfDays: 4 }
      });
    }
    state.planningModeInputs = nextInputs;
    syncPlanningModeMetadataToPlan();
    const result = generatePersonalizedMealPlan(buildMealPlanGenerationContext(), { mode: MEAL_PLAN_GENERATION_MODES.REPLACE_ALL });
    state.planningModeInputs = previousInputs;
    syncPlanningModeMetadataToPlan();
    if (!result.success) {
      showNotification("Chef Nova could not create a four-day preview with the current requirements.", "info");
      return false;
    }
    pendingGeneratedMealPlan = { ...result, mode: MEAL_PLAN_GENERATION_MODES.REPLACE_ALL };
    openSuggestedMealPlanReview(pendingGeneratedMealPlan, { mode: MEAL_PLAN_GENERATION_MODES.REPLACE_ALL });
    const start = mode === PLANNING_MODES.EMERGENCY ? nextInputs.emergency.startDate : getCurrentDateString();
    const end = addCalendarDays(start, 3);
    showNotification(`Four-day preview created for ${formatEmergencyDateRange(start, end)}. Review before saving.`, "success");
    return true;
  }

  function createBudgetStatusSnapshot(plan = state.mealPlans) {
    const model = deriveBudgetStatusPanelModel({ plan });
    if (!model || model.hidden) return null;
    return {
      version: BUDGET_STATUS_PANEL_VERSION,
      status: model.status,
      statusLabel: model.statusLabel,
      weeklyBudgetCents: model.budget.weeklyBudgetCents,
      planningTargetCents: model.budget.planningTargetCents,
      weeklyGroceryCostCents: model.budget.weeklyGroceryCostCents,
      completeGroceryTotalAvailable: model.budget.completeGroceryTotalAvailable,
      mealsPlannedCount: model.plan.mealsPlannedCount,
      requestedMealCount: model.plan.requestedMealCount,
      priceConfidenceStatus: model.priceConfidence?.status || null,
      actionCount: model.actionCount,
      capturedAt: new Date().toISOString()
    };
  }

  function createPlanSavingsExplanationSnapshot(plan = state.mealPlans) {
    const explanation = derivePlanSavingsExplanation({ plan, planningMode: plan?.planningMode || getCurrentPlanningMode() });
    if (!explanation || explanation.status === PLAN_SAVINGS_EXPLANATION_STATUSES.EXPLANATION_UNAVAILABLE) return null;
    return {
      explanationVersion: PLAN_SAVINGS_EXPLANATION_VERSION,
      status: explanation.status,
      baselineType: explanation.comparison?.baselineType || null,
      baselinePlanSignature: explanation.baselinePlanSignature || null,
      finalPlanSignature: explanation.planSignature || null,
      baselineGroceryCostCents: explanation.comparison?.baselineGroceryCostCents ?? null,
      finalGroceryCostCents: explanation.comparison?.finalGroceryCostCents ?? null,
      estimatedDifferenceCents: explanation.comparison?.estimatedDifferenceCents ?? null,
      reasonEvidence: explanation.reasons.map((reason) => ({
        reasonId: reason.reasonId,
        reasonType: reason.reasonType,
        evidence: structuredCloneSafe(reason.evidence || {})
      })),
      priceContext: structuredCloneSafe(explanation.priceContext || {}),
      calculatedAt: explanation.calculatedAt
    };
  }

  function renderBudgetPlanningResultSummary(result) {
    if (!result || ![PLANNING_MODES.BUDGET_RESCUE, PLANNING_MODES.EMERGENCY].includes(getCurrentPlanningMode())) return "";
    if (getCurrentPlanningMode() === PLANNING_MODES.EMERGENCY || result.emergencyPlanningResult) return renderEmergencyPlanningResultSummary(result.emergencyPlanningResult || result.budgetPlanningResult?.emergencyPlanningResult);
    const summary = result.groceryCostSummary || {};
    const filled = result.selectedMeals?.length || 0;
    const total = result.slots?.length || 0;
    const appliedRepairs = (result.repairHistory || []).filter((repair) => repair.status === "applied").length;
    const costText = Number.isInteger(summary.weeklyGroceryCostCents)
      ? formatCostCents(summary.weeklyGroceryCostCents)
      : formatCostCents(summary.knownPurchaseSubtotalCents || 0);
    const coverage = result.priceConfidence?.coveragePercentDisplay !== null && result.priceConfidence?.coveragePercentDisplay !== undefined
      ? `${result.priceConfidence.coveragePercentDisplay}% price coverage`
      : "Price coverage unavailable";
    return `<section class="budget-planning-result ${escapeHtml(result.status || "")}" aria-live="polite">
      <span class="eyebrow">BUDGET RESCUE RESULT</span>
      <h3>${escapeHtml(getBudgetPlanningStatusMessage(result.status))}</h3>
      <p>${escapeHtml(String(filled))} of ${escapeHtml(String(total))} requested meals filled. Estimated grocery cost: ${escapeHtml(costText)}. ${escapeHtml(coverage)}.</p>
      ${renderLeftoverBenefitSummary(result)}
      ${renderPlanSavingsExplanation(derivePlanSavingsExplanation({ planningMode: PLANNING_MODES.BUDGET_RESCUE, planningResult: result, initialPlanResult: result.initialPlanSnapshot, repairHistory: result.repairHistory || [], weeklyCostSummary: result.groceryCostSummary, priceConfidence: result.priceConfidence, pantrySummary: result.pantryAllocationSummary, purchaseGroups: result.purchaseGroups || [], leftoverSummary: result.leftoverBenefitSnapshot, plan: pendingGeneratedMealPlan?.plan || result.plan || state.mealPlans }))}
      ${appliedRepairs ? `<p>${escapeHtml(String(appliedRepairs))} repair ${escapeHtml(pluralize(appliedRepairs, "change"))} applied.</p>` : ""}
    </section>`;
  }

  function renderEmergencyPlanningResultSummary(result) {
    if (!result) return "";
    const summary = result.weeklyCostSummary || {};
    const completeCost = Number.isInteger(summary.weeklyGroceryCostCents) && result.priceConfidence?.completeGroceryTotalAvailable !== false;
    const knownSubtotalCents = summary["knownPurchaseSubtotalCents"] || 0;
    const costText = completeCost ? formatCostCents(summary.weeklyGroceryCostCents) : formatCostCents(knownSubtotalCents);
    const planningResult = { slots: new Array(result.emergencyMetrics?.requestedMealSlotCount || 0).fill(null), selectedMeals: new Array(result.emergencyMetrics?.filledMealSlotCount || 0).fill(null), status: result.status === EMERGENCY_PLAN_STATUSES.NO_SAFE_PLAN ? BUDGET_PLAN_STATUSES.NO_SAFE_PLAN : result.status === EMERGENCY_PLAN_STATUSES.ABOVE_BUDGET ? BUDGET_PLAN_STATUSES.ABOVE_WEEKLY_BUDGET : result.status?.startsWith("partial") ? BUDGET_PLAN_STATUSES.PARTIAL_SAFE_PLAN : null };
    const message = deriveRespectfulBudgetMessage({
      planningMode: PLANNING_MODES.EMERGENCY,
      planningRequest: { emergencyRequest: result.request, budget: { weeklyBudgetCents: result.request?.availableBudgetCents, planningTargetCents: result.request?.availableBudgetCents } },
      planningResult,
      compatibilitySummary: { safe: result.status !== EMERGENCY_PLAN_STATUSES.PLAN_REQUIRES_REVIEW, conflictCount: 0, conflicts: [] },
      weeklyCostSummary: summary,
      priceConfidence: result.priceConfidence,
      shoppingCoverage: result.shoppingCoverage,
      pantryOpportunities: { ingredientGroupCountUsed: result.emergencyMetrics?.pantryIngredientGroupCountUsed || 0 },
      substitutionRecommendations: { availableLowerCostActionCount: countAvailableLowerCostSubstitutionsForPlan(pendingGeneratedMealPlan?.plan || state.mealPlans) },
      plan: pendingGeneratedMealPlan?.plan || state.mealPlans
    });
    const details = message.detailLines?.length ? `<ul class="respectful-budget-details">${message.detailLines.map((line) => `<li>${escapeHtml(line)}</li>`).join("")}</ul>` : "";
    const safety = message.safetyMessage ? `<p class="budget-status-safety-note">${escapeHtml(message.safetyMessage)}</p>` : "";
    const actions = message.actions.length ? `<div class="budget-status-actions">${message.actions.map((action) => `<button class="button ${action.actionId === RESPECTFUL_BUDGET_ACTION_IDS.ADD_MISSING_PRICES ? "primary" : "secondary"} small" type="button" ${action.attr}>${escapeHtml(action.label)}</button>`).join("")}</div>` : "";
    const safeFood = renderEmergencySafeFoodAvailable(result.safeFoodSummary);
    return `<section class="budget-planning-result emergency-result ${escapeHtml(result.status || "")}" aria-live="polite">
      <span class="eyebrow">EMERGENCY PLAN RESULT</span>
      <h3>${escapeHtml(message.heading)}</h3>
      <p>${escapeHtml(message.primaryMessage)}</p>
      <p>${escapeHtml(message.secondaryMessage)}</p>
      ${safety}
      <p>${escapeHtml(formatEmergencyCurrency(result.request?.availableBudgetCents))} plan for ${escapeHtml(formatEmergencyDateRange(result.request?.startDate, result.request?.endDate))}.</p>
      <p>Meals planned: ${escapeHtml(String(result.emergencyMetrics?.filledMealSlotCount || 0))} of ${escapeHtml(String(result.emergencyMetrics?.requestedMealSlotCount || 0))}. ${completeCost ? `Estimated grocery cost: ${escapeHtml(costText)}.` : `Currently priced grocery items: ${escapeHtml(costText)}.`}</p>
      ${safeFood}
      ${details}
      ${renderPlanSavingsExplanation(derivePlanSavingsExplanation({ planningMode: PLANNING_MODES.EMERGENCY, planningRequest: { emergencyRequest: result.request, budget: { weeklyBudgetCents: result.request?.availableBudgetCents, planningTargetCents: result.request?.availableBudgetCents } }, planningResult, weeklyCostSummary: summary, priceConfidence: result.priceConfidence, shoppingCoverage: result.shoppingCoverage, pantrySummary: result.pantrySummary, purchaseGroups: result.purchaseGroups, leftoverSummary: result.leftoverSummary, plan: pendingGeneratedMealPlan?.plan || state.mealPlans }))}
      <p>Price confidence: ${escapeHtml(result.priceConfidence ? priceConfidenceStatusLabel(result.priceConfidence.status) : "Unavailable")}. Actual store prices may vary.</p>
      <ul>${(result.priorityExplanation || []).map((reason) => `<li>${escapeHtml(reason)}</li>`).join("")}</ul>
      ${actions}
      <div class="sr-only" aria-live="polite" aria-atomic="true">${escapeHtml(message.liveRegionText)}</div>
    </section>`;
  }

  function renderEmergencySafeFoodAvailable(summary = null) {
    if (!summary) return "";
    const eligibleRows = (summary.eligibleItems || []).slice(0, 4).map((item) => `<li>
      <span><b>${escapeHtml(item.displayName)}</b><small>${escapeHtml(item.dateInformation?.displayLabel || "Date details available")}</small></span>
      <strong>${escapeHtml(item.quantity?.point === null ? "Amount needs review" : `${formatQuantityForDisplay(item.quantity?.point)} ${item.quantity?.unit || ""}`.trim())}</strong>
    </li>`).join("");
    const reviewRows = (summary.reviewRequiredItems || []).slice(0, 3).map((item) => `<li><span><b>${escapeHtml(item.displayName)}</b><small>${escapeHtml(item.reason || "Review food details before planning.")}</small></span></li>`).join("");
    const excludedRows = (summary.excludedItems || []).slice(0, 3).map((item) => `<li><span><b>${escapeHtml(item.displayName)}</b><small>${escapeHtml(item.reason || "Not used in this Emergency Plan.")}</small></span></li>`).join("");
    return `<section class="emergency-safe-food-summary" aria-labelledby="emergencySafeFoodHeading">
      <h4 id="emergencySafeFoodHeading">Safe Food Available for the Emergency Plan</h4>
      <p>Chef Nova uses only food that passes current safety, allergy, dietary, storage, appliance, reservation, and meal-date checks.</p>
      <div class="emergency-safe-food-grid">
        <article><h5>Included candidates</h5><ul>${eligibleRows || "<li>No qualifying Pantry food was found in Chef Nova's current records.</li>"}</ul></article>
        <article><h5>Review required</h5><ul>${reviewRows || "<li>No review-required Pantry food in this preview.</li>"}</ul></article>
        <article><h5>Not used</h5><ul>${excludedRows || "<li>No Pantry food was excluded by safety checks in this preview.</li>"}</ul></article>
      </div>
      <p>This is a planning estimate. Food is not marked used until the actual meal outcome is confirmed.</p>
    </section>`;
  }

  function renderLeftoverBenefitSummary(result) {
    const benefits = result?.leftoverBenefitSnapshot;
    if (!benefits) return "";
    if (!benefits.leftoverMealCount) return `<div class="leftover-benefit-summary"><p>No planned leftovers were used in this plan.</p></div>`;
    const lunchCount = benefits.leftoverMealCountBySlotType?.lunch || 0;
    const dinnerCount = benefits.leftoverMealCountBySlotType?.dinner || 0;
    const leftoverPieces = [
      lunchCount ? `${lunchCount} leftover ${pluralize(lunchCount, "lunch", "lunches")}` : "",
      dinnerCount ? `${dinnerCount} leftover ${pluralize(dinnerCount, "dinner")}` : ""
    ].filter(Boolean);
    const savings = benefits.estimatedSavingsCents === null
      ? "Savings estimate unavailable"
      : benefits.estimatedSavingsCents > 0
        ? `Estimated grocery savings: ${formatCostCents(benefits.estimatedSavingsCents)}`
        : benefits.estimatedSavingsCents < 0
          ? `Estimated additional grocery cost: ${formatCostCents(Math.abs(benefits.estimatedSavingsCents))}`
          : "No estimated grocery-cost difference";
    return `<div class="leftover-benefit-summary">
      <h4>This plan includes</h4>
      <ul>
        <li>${escapeHtml(leftoverPieces.join(", ") || `${benefits.leftoverMealCount} leftover ${pluralize(benefits.leftoverMealCount, "meal")}`)}</li>
        <li>${escapeHtml(`${benefits.batchCookedSourceMealCount} batch-cooked ${pluralize(benefits.batchCookedSourceMealCount, "meal")}`)}</li>
        <li>${escapeHtml(savings)}</li>
        <li>${escapeHtml(`${benefits.estimatedCookingSessionsAvoided} full cooking ${pluralize(benefits.estimatedCookingSessionsAvoided, "session")} avoided`)}</li>
        <li>${escapeHtml(`${benefits.reheatingSessionCount} reheating ${pluralize(benefits.reheatingSessionCount, "session")}`)}</li>
      </ul>
      <button class="button secondary small" type="button" data-review-leftover-plan>Review Leftover Plan</button>
    </div>`;
  }

  function findPurchaseGroupForShoppingItem(item) {
    const result = calculateCurrentMealPlanCosts();
    if (!result) return null;
    const ingredientId = item.ingredientId || resolveCanonicalIngredientName(item.name).ingredientId || null;
    return result.purchaseGroups.find((group) => group.purchaseGroupId === item.purchaseGroupId || group.ingredientId === ingredientId) || null;
  }

  function getShoppingItemForAction(itemId) {
    return getShoppingListItems().find((candidate) => candidate.id === itemId)
      || deriveShoppingListViewModel({ activeFilter: SHOPPING_LIST_FILTERS.ALL }).items.find((candidate) => candidate.shoppingItemId === itemId)
      || null;
  }

  function renderShoppingCostDetails(item) {
    const group = findPurchaseGroupForShoppingItem(item);
    if (!group || !group.totalRequiredQuantity) return "";
    const details = [
      ["Needed this week", `${formatQuantityForDisplay(group.totalRequiredQuantity)} ${group.totalRequiredUnit || ""}`.trim()],
      ["Available in Pantry", `${formatQuantityForDisplay(group.pantryQuantityApplied)} ${group.pantryUnit || ""}`.trim()],
      ["Need to buy", `${formatQuantityForDisplay(group.missingQuantity)} ${group.missingUnit || ""}`.trim()]
    ];
    if (group.packagesRequired !== null) details.push(["Suggested purchase", `${group.packagesRequired} package${group.packagesRequired === 1 ? "" : "s"}`]);
    if (Number.isInteger(group.purchaseCostCents)) details.push(["Estimated purchase cost", formatCostCents(group.purchaseCostCents)]);
    else details.push(["Estimated purchase cost", "Incomplete"]);
    if (group.estimatedSurplusQuantity !== null) details.push(["Estimated amount remaining", `${formatQuantityForDisplay(group.estimatedSurplusQuantity)} ${group.estimatedSurplusUnit || ""}`.trim()]);
    const confidence = classifyPurchaseGroupPriceConfidence(group);
    const warning = !confidence.isUsable && group.missingQuantity > 0 ? confidence.reason : group.warnings?.[0] || "";
    return `<dl class="shopping-cost-details">${details.map(([term, value]) => `<div><dt>${escapeHtml(term)}</dt><dd>${escapeHtml(value)}</dd></div>`).join("")}</dl>${warning ? `<p class="shopping-cost-warning" id="shoppingCostWarning-${escapeHtml(item.id)}">${escapeHtml(warning)}</p>` : ""}`;
  }

  function resolveShoppingItemPrice(item) {
    const ingredientId = item.ingredientId || resolveCanonicalIngredientName(item.name).ingredientId || null;
    if (!ingredientId) return { status: "missing", entry: null, ingredientId: null };
    return { ...PRICE_DATA.resolveIngredientPrice?.({ ingredientId, ...getActiveBudgetPriceSettings() }), ingredientId };
  }

  function getPriceSourceLabel(resolution) {
    if (!resolution || resolution.status !== "resolved") return "Price not available";
    const source = resolution.entry.sourceType;
    const profileName = resolution.sourceProfile?.name || "";
    if (resolution.usedFallback) return `Fallback estimate from ${profileName || "Chef Nova Budget Store"}`;
    if (source === PRICE_SOURCE_TYPES.CHEF_NOVA_ESTIMATE) return "Estimated using Chef Nova's Budget Store profile";
    if (source === PRICE_SOURCE_TYPES.USER_ENTERED) return "Approximate price entered by you";
    return `Saved profile: ${profileName || "Local store profile"}`;
  }

  function renderShoppingPriceSummary(item) {
    const resolution = resolveShoppingItemPrice(item);
    if (resolution.status !== "resolved") return `<div class="shopping-price-summary missing"><b>Price not available</b><small>Add an approximate price when needed.</small></div>`;
    const entry = resolution.entry;
    const saleNote = entry.salePriceCents && !PRICE_DATA.isSaleActive?.(entry) ? `<small>Saved sale price expired${entry.saleEndsOn ? ` on ${escapeHtml(entry.saleEndsOn)}` : ""}. Regular price is selected.</small>` : "";
    const fallback = resolution.usedFallback ? `<small>Actual store prices may vary.</small>` : "";
    return `<div class="shopping-price-summary"><b>${escapeHtml(resolution.formattedPrice || PRICE_DATA.formatPriceEntry(entry))}</b><small>${escapeHtml(getPriceSourceLabel(resolution))}</small><small>Prices last updated: ${escapeHtml(entry.updatedAt || "unknown")}</small>${saleNote}${fallback}</div>`;
  }

  function getShoppingItemCostStatus(item) {
    const group = findPurchaseGroupForShoppingItem(item);
    if (!group || group.missingQuantity <= 0) return "complete";
    return classifyPurchaseGroupPriceConfidence(group).isUsable ? "complete" : "needs-review";
  }

  function purchaseGroupToShoppingItem(group) {
    const name = getIngredientDisplayNameById(group.ingredientId, group.recipeContributions?.[0]?.displayText || "Grocery item");
    return {
      id: `budget-${group.purchaseGroupId.replace(/[^a-z0-9-]/gi, "-")}`,
      name,
      ingredientId: group.ingredientId || null,
      quantity: group.missingQuantity || 1,
      unit: group.missingUnit || "",
      recipeId: group.recipeContributions?.[0]?.recipeId || "",
      checked: false,
      source: "budget-rescue",
      origin: SHOPPING_LIST_LINE_ORIGINS.PLAN_REQUIRED
    };
  }

  function getShoppingListOverrideMap() {
    return new Map(getShoppingListItems().filter((item) => item.purchaseGroupId).map((item) => [item.purchaseGroupId, item]));
  }

  function saveShoppingListOverride(purchaseGroupId, patch) {
    if (!purchaseGroupId) return false;
    const items = getShoppingListItems();
    const index = items.findIndex((item) => item.purchaseGroupId === purchaseGroupId);
    const matchingGroup = calculateCurrentMealPlanCosts()?.purchaseGroups?.find((group) => group.purchaseGroupId === purchaseGroupId);
    const existing = index >= 0 ? items[index] : purchaseGroupToShoppingItem(matchingGroup || { purchaseGroupId, recipeContributions: [], missingQuantity: 1, missingUnit: "" });
    const nextItem = { ...existing, ...patch, purchaseGroupId, schemaVersion: SHOPPING_LIST_SCHEMA_VERSION, source: existing.source || "budget-rescue", updatedAt: getCurrentIsoString() };
    const nextItems = index >= 0 ? items.map((item, itemIndex) => itemIndex === index ? nextItem : item) : [...items, nextItem];
    saveShoppingListItems(nextItems);
    return true;
  }

  function getShoppingCategoryForPurchaseGroup(group) {
    const record = getIngredientCatalogueRecord(group.ingredientId);
    const category = record?.shoppingListCategory || record?.category || "";
    const form = String(group.form || record?.form || "").toLowerCase();
    if (form.includes("frozen") || category === "frozen") return "frozen-food";
    if (form.includes("canned") || category === "canned-goods") return "canned-goods";
    if (["produce"].includes(category)) return "produce";
    if (["grains", "bakery"].includes(category)) return "grains";
    if (["meat", "seafood", "eggs", "legumes"].includes(category)) return "protein";
    if (["dairy", "dairy-alternatives"].includes(category)) return "dairy-alternatives";
    if (["oils-fats", "herbs-spices", "condiments-sauces", "sweeteners"].includes(category) || record?.pantryStaple) return "pantry-staples";
    return "other";
  }

  function getShoppingCategoryLabel(categoryId) {
    return SHOPPING_LIST_CATEGORIES.find((category) => category.id === categoryId)?.label || "Other";
  }

  function formatShoppingQuantity(quantity, unit) {
    if (!Number.isFinite(Number(quantity))) return "Not available";
    if (!unit) return formatQuantityForDisplay(quantity);
    if (typeof LOCALIZATION.formatQuantity === "function") {
      const result = LOCALIZATION.formatQuantity({ value: String(quantity), unit: unit || "count" }, getLocalizationPreferences());
      if (result.ok) return result.display;
    }
    return `${formatQuantityForDisplay(quantity)} ${unit || ""}`.trim();
  }

  function getShoppingListSourceRevisions(plan = state.mealPlans) {
    return {
      userScope: getActiveUserScopeId(),
      shoppingListRevision: JSON.stringify(getShoppingListItems().map((item) => ({ id: item.id, purchaseGroupId: item.purchaseGroupId || "", ingredientId: item.ingredientId || "", quantity: item.quantity ?? item.selectedPurchaseQuantity ?? "", origin: item.origin || item.source || "", checked: item.checked === true, removed: item.removedFromPurchaseList === true, updatedAt: item.updatedAt || "" })).sort((a, b) => String(a.id || a.purchaseGroupId).localeCompare(String(b.id || b.purchaseGroupId)))),
      pantryRevision: buildPantrySignature(state.pantry),
      reservationRevision: JSON.stringify(state.pantry.map((item) => ({ id: item.id, reservations: item.reservations || [] })).sort((a, b) => String(a.id).localeCompare(String(b.id)))),
      mealPlanRevision: buildMealPlanSignature(plan),
      mealDateRevision: JSON.stringify({ calendar: plan?.calendar || {}, activeMealDay: state.activeMealDay }),
      dateIntelligenceRevision: String(FOOD_DATE_INTELLIGENCE_VERSION),
      foodSafetyGuardrailRevision: String(FOOD_SAFETY_POLICY_SCHEMA_VERSION),
      allergyProfileRevision: normalizeAllergies(getProfile()?.allergies).join("|"),
      dietaryProfileRevision: getProfile()?.dietaryPreference || "",
      recipeRevision: String(state.recipes.length),
      substitutionRevision: String(state.substitutionCatalogue?.version || state.substitutionCatalogue?.rules?.length || 0),
      priceCatalogueRevision: state.priceEstimateCatalogue?.reviewedAt || String(state.priceEstimateCatalogue?.profiles?.length || 0),
      storeProfileRevision: JSON.stringify(getSavedPriceProfiles().map((profile) => ({ id: profile.id, updatedAt: profile.updatedAt || "", entries: profile.entries?.length || 0 }))),
      packageDataRevision: String(state.priceEstimateCatalogue?.version || state.priceEstimateCatalogue?.reviewedAt || ""),
      costEngineVersion: String(typeof COST_ENGINE.calculateMealPlanCosts === "function"),
      referenceLocalDate: getCurrentDateString(),
      timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "local"
    };
  }

  function getShoppingAllocationRowsByIngredient() {
    const allocation = buildPantryAllocationForPlan(state.mealPlans);
    const rows = allocation?.summary?.mealPantryAllocations || [];
    return rows.reduce((map, row) => {
      const key = row.ingredientId || normalizeIngredient(row.displayName);
      if (!key) return map;
      if (!map.has(key)) map.set(key, []);
      map.get(key).push(row);
      return map;
    }, new Map());
  }

  function sumShoppingRows(rows = [], field) {
    return rows.reduce((sum, row) => sum + (Number(row?.[field]) || 0), 0);
  }

  function getShoppingDateLabelFromAllocation(allocation = {}) {
    const pantryItem = state.pantry.find((item) => item.id === allocation.pantryItemId);
    if (pantryItem) {
      const priority = deriveUseFirstPriorityForPantryItem(pantryItem);
      return formatUseFirstDateSummary(priority);
    }
    if (allocation.useSoonStatus === "during-plan") return allocation.freshnessDate ? `Use soon — ${formatDate(allocation.freshnessDate)}` : "Use soon";
    if (allocation.useSoonStatus === "explicit-use-first") return "Use this first";
    if (allocation.useSoonStatus === "review-required") return "Date needs confirmation";
    if (allocation.freshnessDate) return `Date: ${formatDate(allocation.freshnessDate)}`;
    return "No relevant date recorded";
  }

  function getShoppingPlanMealLabels(rows = []) {
    return Array.from(new Set(rows.map((row) => String(row.mealId || "").replace("::", " ").trim()).filter(Boolean))).sort();
  }

  function aggregateShoppingPantrySupply(ingredientId, rows = [], group = null) {
    const allocations = rows.flatMap((row) => row.allocations || []);
    const allocated = sumShoppingRows(rows, "pantryQuantityApplied");
    const demand = group?.totalRequiredQuantity ?? sumShoppingRows(rows, "requiredQuantity");
    const missing = group?.missingQuantity ?? sumShoppingRows(rows, "missingQuantity");
    const unit = group?.totalRequiredUnit || group?.missingUnit || rows[0]?.requiredUnit || allocations[0]?.unit || "";
    const remaining = Math.max(0, allocated - (demand - missing));
    const quantityUnknown = rows.some((row) => row.allocationStatus === "quantity-unknown") || group?.status === "unknown-pantry-quantity";
    const formIssue = rows.some((row) => row.allocationStatus === "form-incompatible") || group?.status === "form-mismatch";
    const lotAllocations = allocations.map((allocation) => ({
      pantryItemId: allocation.pantryItemId,
      displayName: allocation.originalLabel || getIngredientDisplayNameById(ingredientId, "Pantry item"),
      allocatedQuantity: allocation.quantity,
      unit: allocation.unit || unit,
      estimatedRemainingQuantity: allocation.estimatedRemainingQuantity,
      dateLabel: getShoppingDateLabelFromAllocation(allocation),
      opened: allocation.opened === true,
      useSoonStatus: allocation.useSoonStatus || null
    })).sort((a, b) => String(a.dateLabel).localeCompare(String(b.dateLabel)) || String(a.pantryItemId).localeCompare(String(b.pantryItemId)));
    return {
      eligibleQuantity: allocated,
      reservedForThisPlan: 0,
      unreservedEligibleQuantity: allocated,
      reservedForOtherCommitments: 0,
      allocatedQuantity: allocated,
      estimatedRemainingQuantity: rows.reduce((sum, row) => sum + Math.max(0, (Number(row.pantryQuantityApplied) || 0) - (Number(row.requiredQuantity) || 0)), 0) || Math.max(0, allocated - demand),
      unit,
      quantityConfidence: quantityUnknown ? "unknown" : "measured",
      lotAllocations,
      sourceMealIds: getShoppingPlanMealLabels(rows),
      dateLabel: lotAllocations[0]?.dateLabel || (quantityUnknown ? "Quantity needs review" : "No relevant date recorded"),
      quantityUnknown,
      formIssue
    };
  }

  function getShoppingSupplyStatus({ group = null, pantrySupply = {}, origin = SHOPPING_LIST_LINE_ORIGINS.PLAN_REQUIRED, item = null } = {}) {
    if (origin === SHOPPING_LIST_LINE_ORIGINS.USER_KEPT_EXTRA || item?.userKeptExtra === true) return SHOPPING_LIST_SUPPLY_STATUSES.USER_EXTRA_PURCHASE;
    if (pantrySupply.quantityUnknown) return SHOPPING_LIST_SUPPLY_STATUSES.QUANTITY_REVIEW_REQUIRED;
    if (pantrySupply.formIssue) return SHOPPING_LIST_SUPPLY_STATUSES.INCOMPATIBLE_AT_HOME;
    if (group?.missingQuantity > 0 && pantrySupply.allocatedQuantity > 0) return SHOPPING_LIST_SUPPLY_STATUSES.PARTIALLY_COVERED_AT_HOME;
    if ((group?.missingQuantity || 0) <= 0 && pantrySupply.allocatedQuantity > 0) return SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME;
    if (origin === SHOPPING_LIST_LINE_ORIGINS.OPTIONAL_RECIPE_ITEM) return SHOPPING_LIST_SUPPLY_STATUSES.OPTIONAL_PURCHASE;
    return SHOPPING_LIST_SUPPLY_STATUSES.PURCHASE_REQUIRED;
  }

  function createShoppingListNeedResolution(group, allocationRows = [], override = {}) {
    const ingredientId = group?.ingredientId || null;
    const pantrySupply = aggregateShoppingPantrySupply(ingredientId, allocationRows, group);
    const supplyStatus = getShoppingSupplyStatus({ group, pantrySupply, origin: override.origin || SHOPPING_LIST_LINE_ORIGINS.PLAN_REQUIRED });
    const selectedPurchase = getShoppingSelectedPurchase(group, override);
    return {
      shoppingListNeedResolutionVersion: SHOPPING_LIST_NEED_RESOLUTION_VERSION,
      ingredientDemandId: group?.purchaseGroupId || `demand::${ingredientId || "unknown"}`,
      canonicalIngredientId: ingredientId,
      requiredForm: group?.form || "",
      demand: {
        pointQuantity: group?.totalRequiredQuantity ?? sumShoppingRows(allocationRows, "requiredQuantity"),
        unit: group?.totalRequiredUnit || pantrySupply.unit,
        sourceMealIds: Array.from(new Set((group?.recipeContributions || []).map((contribution) => contribution.mealId).filter(Boolean)))
      },
      pantrySupply,
      missingDemand: { quantity: group?.missingQuantity || 0, unit: group?.missingUnit || pantrySupply.unit },
      purchaseResolution: {
        purchaseRequired: Number(group?.missingQuantity) > 0,
        packageQuantity: group?.pricedQuantity ?? null,
        packageUnit: group?.pricedUnit || group?.purchasedUnit || group?.missingUnit || "",
        packageCount: group?.packagesRequired ?? null,
        checkoutCostMinorUnits: Number.isInteger(selectedPurchase.costCents) ? selectedPurchase.costCents : group?.purchaseCostCents ?? null,
        currency: BUDGET_RESCUE_CURRENCY,
        priceConfidence: classifyPurchaseGroupPriceConfidence(group).sourceClass || PRICE_CONFIDENCE_STATUSES.INCOMPLETE
      },
      shoppingListSupplyStatusVersion: SHOPPING_LIST_SUPPLY_STATUS_VERSION,
      supplyStatus,
      sourceRevisions: getShoppingListSourceRevisions()
    };
  }

  function createShoppingDuplicatePurchaseAdvisory(item, matchingResolution) {
    if (!item || !matchingResolution) return null;
    const decision = item.duplicatePurchaseDecision || {};
    const advisoryId = `duplicate-purchase::${item.id || item.shoppingItemId}::${matchingResolution.sourceRevisions.pantryRevision}::${matchingResolution.sourceRevisions.mealPlanRevision}`;
    if (decision.advisoryId === advisoryId && decision.userDecision === "keep-new-package") return null;
    const pantry = matchingResolution.pantrySupply || {};
    if (matchingResolution.supplyStatus !== SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME || !pantry.eligibleQuantity || pantry.quantityUnknown) return null;
    const name = item.name || item.displayName || getIngredientDisplayNameById(matchingResolution.canonicalIngredientId, "Grocery item");
    return {
      duplicatePurchaseAdvisoryVersion: DUPLICATE_PURCHASE_ADVISORY_VERSION,
      advisoryId,
      shoppingListLineId: item.id || item.shoppingItemId,
      canonicalIngredientId: matchingResolution.canonicalIngredientId,
      status: "active",
      matchedPantryItemIds: pantry.lotAllocations.map((allocation) => allocation.pantryItemId).filter(Boolean),
      evidence: {
        eligibleQuantity: pantry.eligibleQuantity,
        plannedQuantity: matchingResolution.demand.pointQuantity,
        estimatedRemainingQuantity: Math.max(0, pantry.eligibleQuantity - matchingResolution.demand.pointQuantity),
        unit: pantry.unit,
        priorityItemCount: pantry.lotAllocations.filter((allocation) => /use|best before|expiration|leftover/i.test(allocation.dateLabel || "")).length,
        dateLabel: pantry.dateLabel
      },
      actions: ["keep-new-package", "remove-from-shopping-list", "review-pantry-item"],
      userDecision: null,
      sourceRevisions: matchingResolution.sourceRevisions,
      message: `You already have ${name.toLowerCase()} that needs attention. Adding another package may increase the chance of food remaining unused.`
    };
  }

  function getShoppingPriceMeta(group) {
    const entry = findResolvedPriceEntryById(group.priceEntryId);
    if (!entry) return { entry: null, sourceLabel: "Price not available", profileLabel: "Store not selected", updatedAt: "", usingSalePrice: false };
    const resolution = resolveShoppingItemPrice({ ingredientId: group.ingredientId, name: getIngredientDisplayNameById(group.ingredientId) });
    return {
      entry,
      sourceLabel: getPriceSourceLabel(resolution),
      profileLabel: resolution?.sourceProfile?.name || (entry.sourceType === PRICE_SOURCE_TYPES.CHEF_NOVA_ESTIMATE ? "Chef Nova Budget Store" : entry.sourceType === PRICE_SOURCE_TYPES.USER_ENTERED ? "Your approximate price" : "Local store profile"),
      updatedAt: entry.updatedAt || "",
      usingSalePrice: group.usingSalePrice === true,
      usedFallback: group.usedFallback === true
    };
  }

  function getShoppingPromotionEvaluation(group) {
    const entry = findResolvedPriceEntryById(group?.priceEntryId);
    if (!entry?.promotion || group?.priceBasis !== PRICE_BASIS_TYPES.PACKAGE) return null;
    return evaluateMultiPackagePromotion({
      requiredPackageCount: group.packagesRequired,
      regularPackagePriceCents: entry.regularPriceCents,
      promotion: entry.promotion,
      currentPlanCostContext: { currentPlanCostCents: calculateCurrentMealPlanCosts()?.weeklySummary?.weeklyGroceryCostCents },
      weeklyBudgetCents: normalizePlanningModeInputs(state.planningModeInputs).budgetRescue.weeklyBudgetCents,
      entry
    });
  }

  function getSuggestedPurchaseText(group) {
    if (group.missingQuantity <= 0) return "None required";
    if (group.status === "unknown-package-size") return "Package information required";
    if (group.priceBasis === PRICE_BASIS_TYPES.UNIT_RATE) return `approximately ${formatShoppingQuantity(group.missingQuantity, group.missingUnit)}`;
    if (Number.isInteger(group.packagesRequired) && group.packagesRequired > 0 && Number.isFinite(Number(group.pricedQuantity))) {
      const label = PRICE_DATA.unitLabel?.(group.pricedUnit || group.purchasedUnit, group.packagesRequired) || group.pricedUnit || "package";
      return `${group.packagesRequired} x ${formatShoppingQuantity(group.pricedQuantity, group.pricedUnit)} ${label}`;
    }
    if (Number.isInteger(group.packagesRequired)) return `${group.packagesRequired} ${pluralize(group.packagesRequired, "package")}`;
    return group.missingQuantity > 0 ? "Purchase details need review" : "None required";
  }

  function getShoppingSelectedPurchase(group, override = {}) {
    if (override.removedFromPurchaseList) return { quantity: 0, unit: group.purchasedUnit || group.missingUnit, costCents: 0, shortfallQuantity: group.missingQuantity || 0, overridden: true };
    if (Number.isFinite(Number(override.selectedPurchaseQuantity))) {
      const selected = Number(override.selectedPurchaseQuantity);
      let costCents = null;
      if (group.priceBasis === PRICE_BASIS_TYPES.UNIT_RATE && Number.isFinite(Number(group.effectivePriceCents)) && Number.isFinite(Number(group.pricedQuantity)) && group.pricedQuantity > 0) {
        costCents = Math.round(group.effectivePriceCents * selected / group.pricedQuantity);
      } else if (Number.isInteger(group.effectivePriceCents)) {
        costCents = Math.round(group.effectivePriceCents * selected);
      }
      const coverageQuantity = group.priceBasis === PRICE_BASIS_TYPES.UNIT_RATE ? selected : selected * (Number(group.pricedQuantity) || 1);
      return { quantity: selected, unit: override.selectedPurchaseUnit || group.purchasedUnit || group.missingUnit, costCents, shortfallQuantity: Math.max(0, (group.missingQuantity || 0) - coverageQuantity), overridden: true };
    }
    return { quantity: group.priceBasis === PRICE_BASIS_TYPES.UNIT_RATE ? group.missingQuantity : group.packagesRequired, unit: group.priceBasis === PRICE_BASIS_TYPES.UNIT_RATE ? group.missingUnit : "package", costCents: group.purchaseCostCents, shortfallQuantity: 0, overridden: false };
  }

  function createShoppingListItemModel(group, override = {}, allocationRowsByIngredient = new Map()) {
    const confidence = classifyPurchaseGroupPriceConfidence(group);
    const categoryId = getShoppingCategoryForPurchaseGroup(group);
    const selectedPurchase = getShoppingSelectedPurchase(group, override);
    const price = getShoppingPriceMeta(group);
    const promotionEvaluation = getShoppingPromotionEvaluation(group);
    const unknownPantryIssue = createUnknownPantryQuantityIssue(group);
    const missingPriceIssue = createMissingPriceIssue(group);
    const packageRemainder = createPackageRemainderRecord(group, state.mealPlans, `shopping-item::${group.purchaseGroupId}`);
    const hasOptionalContribution = (group.recipeContributions || []).some((contribution) => contribution.optional === true);
    const uniqueMealIds = Array.from(new Set((group.recipeContributions || []).map((contribution) => contribution.mealId).filter(Boolean)));
    const needsPurchase = group.missingQuantity > 0;
    const alreadyAtHome = group.pantryQuantityApplied > 0;
    const priceMissing = needsPurchase && !confidence.isUsable;
    const hasPurchaseShortfall = selectedPurchase.shortfallQuantity > 0;
    const origin = override.origin || (hasOptionalContribution ? SHOPPING_LIST_LINE_ORIGINS.OPTIONAL_RECIPE_ITEM : group.recipeContributions?.some((contribution) => contribution.source === PLANNING_MODES.EMERGENCY) ? SHOPPING_LIST_LINE_ORIGINS.EMERGENCY_PLAN : SHOPPING_LIST_LINE_ORIGINS.PLAN_REQUIRED);
    const needResolution = createShoppingListNeedResolution(group, allocationRowsByIngredient.get(group.ingredientId) || [], override);
    const supplyStatus = override.userKeptExtra === true ? SHOPPING_LIST_SUPPLY_STATUSES.USER_EXTRA_PURCHASE : needResolution.supplyStatus;
    return {
      lineProvenanceVersion: SHOPPING_LIST_LINE_PROVENANCE_VERSION,
      shoppingListSupplyStatusVersion: SHOPPING_LIST_SUPPLY_STATUS_VERSION,
      shoppingItemId: `shopping-item::${group.purchaseGroupId}`,
      purchaseGroupId: group.purchaseGroupId,
      ingredientId: group.ingredientId,
      form: group.form || "",
      origin,
      supplyStatus,
      needResolution,
      displayName: getIngredientDisplayNameById(group.ingredientId, group.recipeContributions?.[0]?.displayText || "Grocery item"),
      originalLabels: Array.from(new Set((group.recipeContributions || []).map((contribution) => contribution.displayText).filter(Boolean))),
      categoryId,
      categoryLabel: getShoppingCategoryLabel(categoryId),
      sourceMealIds: uniqueMealIds,
      sourceRecipeIds: Array.from(new Set((group.recipeContributions || []).map((contribution) => contribution.recipeId).filter(Boolean))),
      requirement: {
        totalRequiredQuantity: group.totalRequiredQuantity,
        unit: group.totalRequiredUnit,
        pantryQuantityApplied: group.pantryQuantityApplied || 0,
        missingQuantity: group.missingQuantity || 0,
        quantityStatus: group.status,
        planRequiredPurchaseQuantity: group.missingQuantity || 0,
        userRequestedExtraQuantity: Number(override.userRequestedExtraQuantity) || 0
      },
      purchase: {
        priceBasis: group.priceBasis,
        suggestedPackageCount: group.packagesRequired,
        suggestedPurchaseText: getSuggestedPurchaseText(group),
        selectedPurchaseQuantity: selectedPurchase.quantity,
        selectedPurchaseUnit: selectedPurchase.unit,
        selectedPurchaseCostCents: selectedPurchase.costCents,
        estimatedSurplusQuantity: group.estimatedSurplusQuantity,
        estimatedSurplusUnit: group.estimatedSurplusUnit,
        purchaseCostCents: group.purchaseCostCents,
        purchaseStatus: confidence.isUsable ? "ready" : group.status || "needs-review"
      },
      price: {
        priceEntryId: group.priceEntryId,
        status: confidence.isUsable ? confidence.sourceClass : PRICE_CONFIDENCE_SOURCE_TYPES.UNRESOLVED,
        sourceLabel: price.sourceLabel,
        profileLabel: price.profileLabel,
        updatedAt: price.updatedAt,
        usedFallback: group.usedFallback === true,
        usingSalePrice: group.usingSalePrice === true
      },
      pantry: { hasAnyAtHome: alreadyAtHome, fullyCoveredAtHome: supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME, partiallyCoveredAtHome: supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.PARTIALLY_COVERED_AT_HOME, supplyStatus, lotAllocations: needResolution.pantrySupply.lotAllocations },
      optional: { isOptionalOnly: hasOptionalContribution && !(group.recipeContributions || []).some((contribution) => contribution.optional !== true), hasOptionalContribution, included: true },
      overrides: { purchaseQuantityOverridden: selectedPurchase.overridden, removedFromPurchaseList: override.removedFromPurchaseList === true, userKeptExtra: override.userKeptExtra === true },
      states: { needsPurchase, alreadyAtHome, priceMissing, hasPurchaseShortfall, requiresReview: priceMissing || hasPurchaseShortfall || override.removedFromPurchaseList === true || [SHOPPING_LIST_SUPPLY_STATUSES.QUANTITY_REVIEW_REQUIRED, SHOPPING_LIST_SUPPLY_STATUSES.DATE_REVIEW_REQUIRED, SHOPPING_LIST_SUPPLY_STATUSES.SAFETY_REVIEW_REQUIRED].includes(supplyStatus), purchased: override.checked === true, doNotBuy: supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME, buyMissingAmount: supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.PARTIALLY_COVERED_AT_HOME, checkBeforeBuying: supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.QUANTITY_REVIEW_REQUIRED, userExtra: supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.USER_EXTRA_PURCHASE },
      warnings: [
        ...(unknownPantryIssue ? [unknownPantryIssue.message] : []),
        ...(priceMissing ? [confidence.reason || "Price not available"] : []),
        ...(override.removedFromPurchaseList ? ["This required item is not currently included in the purchase quantity. Restore it or confirm a sufficient Pantry quantity before relying on the final budget total."] : []),
        ...(hasPurchaseShortfall ? [`This required item has a purchase shortfall of ${formatShoppingQuantity(selectedPurchase.shortfallQuantity, group.missingUnit)}. Review it before relying on the final budget total.`] : []),
        ...(group.warnings || [])
      ],
      edgeCases: { issues: sortEdgeCaseIssues([unknownPantryIssue, missingPriceIssue].filter(Boolean)), unknownPantryIssue, packageRemainder, promotionEvaluation },
      actions: { canEditPurchaseQuantity: true, canUpdatePrice: Boolean(group.ingredientId), canMarkAtHome: true, canRemove: true, canRestore: override.removedFromPurchaseList === true, canChangeStore: true, canReviewPantryItem: needResolution.pantrySupply.lotAllocations.length > 0 }
    };
  }

  function deriveShoppingCoverage(items = []) {
    const required = items.filter((item) => item.states.needsPurchase);
    const removed = required.filter((item) => item.overrides.removedFromPurchaseList).length;
    const shortfalls = required.filter((item) => item.states.hasPurchaseShortfall).length;
    const unresolvedQuantity = required.filter((item) => ["missing-quantity", "ambiguous-ingredient", "unknown-package-size", "incompatible-unit"].includes(item.purchase.purchaseStatus)).length;
    const issueCount = removed + shortfalls + unresolvedQuantity;
    const status = issueCount > 1 ? SHOPPING_COVERAGE_STATUSES.MULTIPLE_ISSUES
      : removed ? SHOPPING_COVERAGE_STATUSES.REQUIRED_ITEM_REMOVED
        : shortfalls ? SHOPPING_COVERAGE_STATUSES.PURCHASE_SHORTFALL
          : unresolvedQuantity ? SHOPPING_COVERAGE_STATUSES.QUANTITY_UNRESOLVED
            : SHOPPING_COVERAGE_STATUSES.COMPLETE;
    return { status, requiredItemCount: required.length, fullyCoveredItemCount: required.length - issueCount, removedRequiredItemCount: removed, shortfallItemCount: shortfalls, unresolvedQuantityItemCount: unresolvedQuantity, shoppingCoverageComplete: issueCount === 0, issues: required.flatMap((item) => item.warnings.map((warning) => ({ itemId: item.shoppingItemId, warning }))) };
  }

  function createCustomShoppingItemModel(item, coveredResolutionMap = new Map()) {
    const ingredientId = item.ingredientId || resolveCanonicalIngredientName(item.name).ingredientId || null;
    const matchingResolution = ingredientId ? coveredResolutionMap.get(ingredientId) : null;
    const origin = item.origin || (item.userKeptExtra ? SHOPPING_LIST_LINE_ORIGINS.USER_KEPT_EXTRA : SHOPPING_LIST_LINE_ORIGINS.USER_MANUAL);
    const duplicatePurchaseAdvisory = createShoppingDuplicatePurchaseAdvisory(item, matchingResolution);
    const supplyStatus = item.userKeptExtra ? SHOPPING_LIST_SUPPLY_STATUSES.USER_EXTRA_PURCHASE : duplicatePurchaseAdvisory ? SHOPPING_LIST_SUPPLY_STATUSES.OPTIONAL_PURCHASE : SHOPPING_LIST_SUPPLY_STATUSES.PURCHASE_REQUIRED;
    return {
      lineProvenanceVersion: SHOPPING_LIST_LINE_PROVENANCE_VERSION,
      shoppingListSupplyStatusVersion: SHOPPING_LIST_SUPPLY_STATUS_VERSION,
      shoppingItemId: item.id,
      purchaseGroupId: null,
      displayName: item.name || "Shopping item",
      originalLabels: [],
      ingredientId,
      origin,
      supplyStatus,
      duplicatePurchaseAdvisory,
      categoryId: "other",
      categoryLabel: "Other",
      sourceMealIds: [],
      requirement: { totalRequiredQuantity: Number(item.quantity) || 1, unit: item.unit || "", pantryQuantityApplied: matchingResolution?.pantrySupply?.eligibleQuantity || 0, missingQuantity: Number(item.quantity) || 1, quantityStatus: "custom", planRequiredPurchaseQuantity: 0, userRequestedExtraQuantity: Number(item.quantity) || 1 },
      purchase: { suggestedPurchaseText: "Custom item", selectedPurchaseQuantity: Number(item.quantity) || 1, selectedPurchaseUnit: item.unit || "", selectedPurchaseCostCents: null, purchaseCostCents: null, purchaseStatus: "custom" },
      price: { sourceLabel: "Custom item", profileLabel: "Not linked to plan", updatedAt: "" },
      pantry: { hasAnyAtHome: Boolean(matchingResolution), fullyCoveredAtHome: false, partiallyCoveredAtHome: false, supplyStatus, lotAllocations: matchingResolution?.pantrySupply?.lotAllocations || [] },
      optional: { isOptionalOnly: false, hasOptionalContribution: false, included: true },
      overrides: { purchaseQuantityOverridden: false, removedFromPurchaseList: false, userKeptExtra: item.userKeptExtra === true },
      states: { needsPurchase: true, alreadyAtHome: Boolean(matchingResolution), priceMissing: false, hasPurchaseShortfall: false, requiresReview: Boolean(duplicatePurchaseAdvisory), purchased: item.checked === true, custom: true, userExtra: supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.USER_EXTRA_PURCHASE },
      warnings: duplicatePurchaseAdvisory ? [duplicatePurchaseAdvisory.message] : [],
      actions: { canEditPurchaseQuantity: false, canUpdatePrice: false, canMarkAtHome: false, canRemove: true, canRestore: false, canChangeStore: false, canReviewPantryItem: Boolean(matchingResolution?.pantrySupply?.lotAllocations?.length) },
      rawItem: item
    };
  }

  function deriveShoppingListViewModel({ activeFilter = state.shoppingCostFilter || SHOPPING_LIST_FILTERS.ALL } = {}) {
    const costResult = calculateCurrentMealPlanCosts();
    const confidence = costResult ? derivePriceConfidence({ purchaseGroups: costResult.purchaseGroups, weeklyCostSummary: costResult.weeklySummary }) : null;
    const overrideMap = getShoppingListOverrideMap();
    const allocationRowsByIngredient = getShoppingAllocationRowsByIngredient();
    const purchaseItems = (costResult?.purchaseGroups || []).map((group) => createShoppingListItemModel(group, overrideMap.get(group.purchaseGroupId) || {}, allocationRowsByIngredient));
    const purchaseGroupIds = new Set(purchaseItems.map((item) => item.purchaseGroupId));
    const coveredResolutionMap = deriveCoveredShoppingNeedResolutions(purchaseItems, allocationRowsByIngredient);
    const customItems = getShoppingListItems().filter((item) => !item.purchaseGroupId && item.source !== "budget-rescue" && !(item.ingredientId && purchaseItems.some((planItem) => planItem.ingredientId === item.ingredientId && item.userKeptExtra !== true))).map((item) => createCustomShoppingItemModel(item, coveredResolutionMap));
    const items = [...purchaseItems, ...customItems];
    const supplySections = deriveShoppingSupplySections(items, allocationRowsByIngredient);
    const coverage = deriveShoppingCoverage(purchaseItems);
    const counts = {
      all: items.length,
      "need-to-buy": items.filter((item) => item.states.needsPurchase).length,
      "already-at-home": items.filter((item) => item.states.alreadyAtHome).length,
      "do-not-buy": supplySections.doNotBuy.length,
      "buy-missing": supplySections.buyMissing.length,
      reserved: supplySections.reserved.length,
      "check-before-buying": supplySections.checkBeforeBuying.length,
      "user-extras": items.filter((item) => item.states.userExtra || item.origin === SHOPPING_LIST_LINE_ORIGINS.USER_KEPT_EXTRA).length,
      "price-missing": items.filter((item) => item.states.priceMissing).length,
      optional: items.filter((item) => item.optional.hasOptionalContribution).length
    };
    const filter = Object.values(SHOPPING_LIST_FILTERS).includes(activeFilter) ? activeFilter : SHOPPING_LIST_FILTERS.ALL;
    const filteredItems = items.filter((item) => filter === SHOPPING_LIST_FILTERS.ALL
      || (filter === SHOPPING_LIST_FILTERS.NEED_TO_BUY && item.states.needsPurchase)
      || (filter === SHOPPING_LIST_FILTERS.ALREADY_AT_HOME && item.states.alreadyAtHome)
      || (filter === SHOPPING_LIST_FILTERS.DO_NOT_BUY && item.states.doNotBuy)
      || (filter === SHOPPING_LIST_FILTERS.BUY_MISSING && item.states.buyMissingAmount)
      || (filter === SHOPPING_LIST_FILTERS.RESERVED && [SHOPPING_LIST_SUPPLY_STATUSES.RESERVED_FOR_THIS_PLAN, SHOPPING_LIST_SUPPLY_STATUSES.RESERVED_FOR_OTHER_COMMITMENT].includes(item.supplyStatus))
      || (filter === SHOPPING_LIST_FILTERS.CHECK_BEFORE_BUYING && item.states.checkBeforeBuying)
      || (filter === SHOPPING_LIST_FILTERS.USER_EXTRAS && (item.states.userExtra || item.origin === SHOPPING_LIST_LINE_ORIGINS.USER_KEPT_EXTRA))
      || (filter === SHOPPING_LIST_FILTERS.PRICE_MISSING && item.states.priceMissing)
      || (filter === SHOPPING_LIST_FILTERS.OPTIONAL && item.optional.hasOptionalContribution));
    const categories = SHOPPING_LIST_CATEGORIES.map((category) => ({
      ...category,
      items: filteredItems.filter((item) => item.categoryId === category.id).sort(compareShoppingListItems)
    })).filter((category) => category.items.length);
    return {
      listId: "shopping-list-current-plan",
      planId: "current-meal-plan",
      planSignature: buildMealPlanSignature(state.mealPlans),
      summary: {
        status: confidence?.completeGroceryTotalAvailable && coverage.shoppingCoverageComplete ? "complete" : "incomplete",
        estimatedGroceryTotalCents: confidence?.completeGroceryTotalAvailable && coverage.shoppingCoverageComplete ? costResult?.weeklySummary?.weeklyGroceryCostCents : null,
        knownPricedSubtotalCents: costResult?.weeklySummary?.knownPurchaseSubtotalCents || 0,
        alreadyAtHomeItemCount: counts["already-at-home"],
        doNotBuyItemCount: counts["do-not-buy"],
        buyMissingItemCount: counts["buy-missing"],
        checkBeforeBuyingItemCount: counts["check-before-buying"],
        userExtraItemCount: counts["user-extras"],
        itemsToPurchaseCount: counts["need-to-buy"],
        unpricedItemCount: counts["price-missing"],
        optionalItemCount: counts.optional,
        removedRequiredItemCount: coverage.removedRequiredItemCount,
        purchaseShortfallItemCount: coverage.shortfallItemCount,
        otherCostIssueCount: coverage.unresolvedQuantityItemCount,
        shoppingCoverageComplete: coverage.shoppingCoverageComplete,
        pricingComplete: confidence?.completeGroceryTotalAvailable === true
      },
      filters: { activeFilter: filter, counts },
      categories,
      items,
      purchaseGroupIds,
      supplySections,
      duplicatePurchaseAdvisories: customItems.map((item) => item.duplicatePurchaseAdvisory).filter(Boolean),
      priceConfidence: confidence,
      shoppingCoverage: coverage,
      warnings: [...(confidence?.warnings || []), ...coverage.issues.map((issue) => issue.warning)]
    };
  }

  function deriveCoveredShoppingNeedResolutions(purchaseItems = [], allocationRowsByIngredient = new Map()) {
    const map = new Map();
    purchaseItems.forEach((item) => {
      if (item.supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME && item.ingredientId) {
        map.set(item.ingredientId, item.needResolution);
      }
    });
    allocationRowsByIngredient.forEach((rows, ingredientId) => {
      if (map.has(ingredientId)) return;
      const required = sumShoppingRows(rows, "requiredQuantity");
      const missing = sumShoppingRows(rows, "missingQuantity");
      const allocated = sumShoppingRows(rows, "pantryQuantityApplied");
      if (required > 0 && allocated > 0 && missing <= 0) {
        map.set(ingredientId, {
          shoppingListNeedResolutionVersion: SHOPPING_LIST_NEED_RESOLUTION_VERSION,
          ingredientDemandId: `covered::${ingredientId}`,
          canonicalIngredientId: ingredientId,
          requiredForm: "",
          demand: { pointQuantity: required, unit: rows[0]?.requiredUnit || "", sourceMealIds: getShoppingPlanMealLabels(rows) },
          pantrySupply: aggregateShoppingPantrySupply(ingredientId, rows, null),
          missingDemand: { quantity: 0, unit: rows[0]?.missingUnit || rows[0]?.requiredUnit || "" },
          purchaseResolution: { purchaseRequired: false, packageQuantity: null, packageUnit: "", packageCount: 0, checkoutCostMinorUnits: null, currency: BUDGET_RESCUE_CURRENCY, priceConfidence: "not-needed" },
          shoppingListSupplyStatusVersion: SHOPPING_LIST_SUPPLY_STATUS_VERSION,
          supplyStatus: SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME,
          sourceRevisions: getShoppingListSourceRevisions()
        });
      }
    });
    return map;
  }

  function deriveShoppingSupplySections(items = [], allocationRowsByIngredient = new Map()) {
    const fromItems = {
      doNotBuy: items.filter((item) => item.supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME),
      buyMissing: items.filter((item) => item.supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.PARTIALLY_COVERED_AT_HOME),
      checkBeforeBuying: items.filter((item) => item.supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.QUANTITY_REVIEW_REQUIRED),
      reserved: items.filter((item) => [SHOPPING_LIST_SUPPLY_STATUSES.RESERVED_FOR_THIS_PLAN, SHOPPING_LIST_SUPPLY_STATUSES.RESERVED_FOR_OTHER_COMMITMENT].includes(item.supplyStatus))
    };
    const existingCoveredIds = new Set(fromItems.doNotBuy.map((item) => item.ingredientId).filter(Boolean));
    allocationRowsByIngredient.forEach((rows, ingredientId) => {
      if (existingCoveredIds.has(ingredientId)) return;
      const required = sumShoppingRows(rows, "requiredQuantity");
      const missing = sumShoppingRows(rows, "missingQuantity");
      const allocated = sumShoppingRows(rows, "pantryQuantityApplied");
      if (required <= 0 || allocated <= 0 || missing > 0) return;
      const resolution = {
        shoppingListNeedResolutionVersion: SHOPPING_LIST_NEED_RESOLUTION_VERSION,
        ingredientDemandId: `covered::${ingredientId}`,
        canonicalIngredientId: ingredientId,
        demand: { pointQuantity: required, unit: rows[0]?.requiredUnit || "", sourceMealIds: getShoppingPlanMealLabels(rows) },
        pantrySupply: aggregateShoppingPantrySupply(ingredientId, rows, null),
        missingDemand: { quantity: 0, unit: rows[0]?.missingUnit || rows[0]?.requiredUnit || "" },
        shoppingListSupplyStatusVersion: SHOPPING_LIST_SUPPLY_STATUS_VERSION,
        supplyStatus: SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME,
        sourceRevisions: getShoppingListSourceRevisions()
      };
      fromItems.doNotBuy.push({
        shoppingItemId: `do-not-buy::${ingredientId}`,
        shoppingListSupplyStatusVersion: SHOPPING_LIST_SUPPLY_STATUS_VERSION,
        ingredientId,
        displayName: getIngredientDisplayNameById(ingredientId, rows[0]?.displayName || "Pantry item"),
        sourceMealIds: getShoppingPlanMealLabels(rows),
        requirement: { totalRequiredQuantity: required, unit: rows[0]?.requiredUnit || "", pantryQuantityApplied: allocated, missingQuantity: 0, quantityStatus: "covered" },
        supplyStatus: SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME,
        needResolution: resolution,
        pantry: { lotAllocations: resolution.pantrySupply.lotAllocations },
        states: { doNotBuy: true, needsPurchase: false, alreadyAtHome: true },
        actions: { canReviewPantryItem: resolution.pantrySupply.lotAllocations.length > 0 }
      });
    });
    return fromItems;
  }

  function compareShoppingListItems(a, b) {
    const score = (item) => item.states.needsPurchase ? 1 : item.states.priceMissing ? 2 : item.pantry.partiallyCoveredAtHome ? 3 : item.pantry.fullyCoveredAtHome ? 4 : item.optional.hasOptionalContribution ? 5 : 6;
    return score(a) - score(b) || a.displayName.localeCompare(b.displayName) || String(a.purchaseGroupId || a.shoppingItemId).localeCompare(String(b.purchaseGroupId || b.shoppingItemId));
  }

  function setShoppingListFilter(filter) {
    state.shoppingCostFilter = Object.values(SHOPPING_LIST_FILTERS).includes(filter) ? filter : SHOPPING_LIST_FILTERS.ALL;
    const model = deriveShoppingListViewModel();
    displayShoppingList();
    const active = model.filters.activeFilter;
    const label = SHOPPING_LIST_FILTER_LABELS[active] || "All items";
    const count = model.filters.counts[active] || 0;
    announcePolite(`${label} filter selected. ${count} ${pluralize(count, "item")} shown.`, { key: `shopping-filter-${active}-${count}` });
  }

  function ensureBudgetPurchaseGroupsInShoppingList(confidence) {
    const groups = confidence?.classifiedGroups || [];
    if (!groups.length) return;
    const existing = getShoppingListItems();
    const merged = [...existing];
    groups.filter((group) => group.missingQuantity > 0).forEach((group) => {
      if (!group.ingredientId) return;
      const alreadyExists = merged.some((item) => (item.ingredientId && item.ingredientId === group.ingredientId) || normalizeIngredient(item.name) === normalizeIngredient(getIngredientDisplayNameById(group.ingredientId)));
      if (!alreadyExists) merged.push(purchaseGroupToShoppingItem(group));
    });
    if (merged.length !== existing.length) saveShoppingListItems(merged);
  }

  function openBudgetPriceReview(filter = SHOPPING_LIST_FILTERS.PRICE_MISSING) {
    const result = calculateCurrentMealPlanCosts();
    const confidence = result ? derivePriceConfidence({ purchaseGroups: result.purchaseGroups, weeklyCostSummary: result.weeklySummary }) : null;
    ensureBudgetPurchaseGroupsInShoppingList(confidence);
    state.shoppingCostFilter = filter;
    navigate("shopping-list");
    displayShoppingList();
    setTimeout(() => {
      const first = $("[data-cost-status='needs-review'] [data-update-price]");
      first?.focus?.();
    }, 0);
    showToast(filter === SHOPPING_LIST_FILTERS.PRICE_MISSING ? "Showing grocery items that need price review." : "Review grocery cost issues.", "info");
  }

  function displayShoppingList() {
    const target = $("#shoppingListContent");
    if (!target) return;
    if (state.shoppingCostFilter === "needs-review") state.shoppingCostFilter = SHOPPING_LIST_FILTERS.PRICE_MISSING;
    const model = deriveShoppingListViewModel();
    const notice = state.guestMode ? guestNotice("Guest Shopping List", GUEST_TEMPORARY_MESSAGE) : "";
    const summary = renderShoppingListSummary(model);
    const filters = renderShoppingListFilters(model);
    const supplySections = renderShoppingSupplySections(model);
    if (!model.categories.length && !supplySections) {
      target.innerHTML = `${notice}${summary}${filters}${supplySections}${getShoppingListEmptyState(model)}`;
      return;
    }
    target.innerHTML = `${notice}${summary}${filters}${supplySections}${model.categories.length ? `<div class="shopping-category-list">${model.categories.map(renderShoppingCategorySection).join("")}</div>` : ""}<div class="sr-only" aria-live="polite" aria-atomic="true">Shopping List updated. ${model.summary.status === "complete" ? "Estimated grocery total is available." : "Shopping List requires review."}</div>`;
  }

  function renderShoppingListSummary(model) {
    const complete = model.summary.pricingComplete && model.summary.shoppingCoverageComplete;
    const rows = [
      [complete ? "Estimated grocery total" : "Currently priced subtotal", formatCostCents(complete ? model.summary.estimatedGroceryTotalCents : model.summary.knownPricedSubtotalCents)],
      ["Do Not Buy items", String(model.summary.doNotBuyItemCount)],
      ["Buy missing amount", String(model.summary.buyMissingItemCount)],
      ["Check before buying", String(model.summary.checkBeforeBuyingItemCount)],
      ["Items already at home", String(model.summary.alreadyAtHomeItemCount)],
      ["Items to purchase", String(model.summary.itemsToPurchaseCount)],
      ["Unpriced items", String(model.summary.unpricedItemCount)]
    ];
    const review = !complete ? `<p class="shopping-cost-warning">${model.summary.unpricedItemCount ? `${numberWord(model.summary.unpricedItemCount)} grocery ${pluralize(model.summary.unpricedItemCount, "item")} still ${model.summary.unpricedItemCount === 1 ? "requires" : "require"} usable ${pluralize(model.summary.unpricedItemCount, "price", "prices")}.` : "Shopping List requires review before Chef Nova can confirm full grocery coverage."}</p>` : "";
    const coverage = model.summary.removedRequiredItemCount || model.summary.purchaseShortfallItemCount
      ? `<p class="shopping-cost-warning">The current Shopping List does not yet cover every required grocery quantity. ${numberWord(model.summary.removedRequiredItemCount + model.summary.purchaseShortfallItemCount)} ${pluralize(model.summary.removedRequiredItemCount + model.summary.purchaseShortfallItemCount, "item")} ${model.summary.removedRequiredItemCount + model.summary.purchaseShortfallItemCount === 1 ? "needs" : "need"} review before relying on the final budget total.</p>` : "";
    return `<section class="shopping-list-summary" aria-labelledby="shoppingListSummaryHeading">
      <div><span class="eyebrow">SHOPPING LIST SUMMARY</span><h2 id="shoppingListSummaryHeading">${complete ? "Estimated grocery total" : "Shopping List requires review"}</h2></div>
      <dl>${rows.map(([term, value]) => `<div><dt>${escapeHtml(term)}</dt><dd>${escapeHtml(value)}</dd></div>`).join("")}</dl>
      ${review}${coverage}
      ${model.summary.unpricedItemCount ? `<button class="button secondary small" type="button" data-shopping-filter="${SHOPPING_LIST_FILTERS.PRICE_MISSING}">Add Missing Prices</button>` : ""}
    </section>`;
  }

  function renderShoppingListFilters(model) {
    return `<div class="shopping-list-filters" role="group" aria-label="Shopping List filters">${Object.values(SHOPPING_LIST_FILTERS).map((filter) => {
      const active = model.filters.activeFilter === filter;
      const count = model.filters.counts[filter] || 0;
      const label = SHOPPING_LIST_FILTER_LABELS[filter];
      return `<button class="shopping-filter-button ${active ? "active" : ""}" type="button" data-shopping-filter="${escapeHtml(filter)}" aria-pressed="${active}" aria-label="${escapeHtml(`${label}, ${count} ${pluralize(count, "item")}`)}">${escapeHtml(label)}<span aria-hidden="true">${escapeHtml(String(count))}</span></button>`;
    }).join("")}</div>`;
  }

  function renderShoppingSupplySections(model) {
    const sections = [
      renderShoppingDoNotBuySection(model.supplySections.doNotBuy),
      renderShoppingBuyMissingSection(model.supplySections.buyMissing),
      renderShoppingCheckBeforeBuyingSection(model.supplySections.checkBeforeBuying),
      renderShoppingReservedSection(model.supplySections.reserved),
      renderDuplicatePurchaseAdvisories(model.duplicatePurchaseAdvisories)
    ].filter(Boolean);
    return sections.length ? `<div class="shopping-supply-sections">${sections.join("")}</div>` : "";
  }

  function renderShoppingSupplyCard(item, mode) {
    const resolution = item.needResolution || {};
    const pantry = resolution.pantrySupply || {};
    const name = item.displayName || getIngredientDisplayNameById(item.ingredientId, "Pantry item");
    const mealText = (item.sourceMealIds || resolution.demand?.sourceMealIds || []).length ? (item.sourceMealIds || resolution.demand.sourceMealIds).join(", ").replace(/::/g, " ") : "Current plan";
    const lots = (pantry.lotAllocations || []).length ? `<details><summary>Relevant Pantry lots</summary><ul>${pantry.lotAllocations.map((lot) => `<li>${escapeHtml(lot.displayName)}: ${escapeHtml(formatShoppingQuantity(lot.allocatedQuantity, lot.unit))}. ${escapeHtml(lot.dateLabel || "Date not recorded")}. Estimated remaining: ${escapeHtml(formatShoppingQuantity(lot.estimatedRemainingQuantity, lot.unit))}.</li>`).join("")}</ul></details>` : "";
    const actionLotId = pantry.lotAllocations?.[0]?.pantryItemId || "";
    const purchaseText = item.purchase?.suggestedPurchaseText || "No purchase currently planned";
    return `<article class="shopping-supply-card ${escapeHtml(mode)}">
      <h3>${escapeHtml(name)}</h3>
      <dl>
        <div><dt>Eligible available quantity</dt><dd>${escapeHtml(formatShoppingQuantity(pantry.eligibleQuantity ?? item.requirement?.pantryQuantityApplied, pantry.unit || item.requirement?.unit))}</dd></div>
        <div><dt>Planned quantity</dt><dd>${escapeHtml(formatShoppingQuantity(resolution.demand?.pointQuantity ?? item.requirement?.totalRequiredQuantity, resolution.demand?.unit || item.requirement?.unit))}</dd></div>
        <div><dt>Estimated remaining</dt><dd>${escapeHtml(formatShoppingQuantity(pantry.estimatedRemainingQuantity ?? Math.max(0, (pantry.eligibleQuantity || 0) - (resolution.demand?.pointQuantity || 0)), pantry.unit || item.requirement?.unit))}</dd></div>
        <div><dt>Missing quantity</dt><dd>${escapeHtml(formatShoppingQuantity(resolution.missingDemand?.quantity ?? item.requirement?.missingQuantity, resolution.missingDemand?.unit || item.requirement?.unit))}</dd></div>
        <div><dt>Suggested purchase package</dt><dd>${escapeHtml(purchaseText)}</dd></div>
        <div><dt>Needs attention</dt><dd>${escapeHtml(pantry.dateLabel || "No relevant date recorded")}</dd></div>
        <div><dt>Used in</dt><dd>${escapeHtml(mealText)}</dd></div>
        <div><dt>Reservation status</dt><dd>${escapeHtml(item.supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.RESERVED_FOR_THIS_PLAN ? "Already reserved for this plan" : item.supplyStatus === SHOPPING_LIST_SUPPLY_STATUSES.RESERVED_FOR_OTHER_COMMITMENT ? "Reserved for another commitment" : "No conflicting reservation found")}</dd></div>
        <div><dt>Quantity confidence</dt><dd>${escapeHtml(quantityConfidenceLabel(pantry.quantityConfidence || "unknown"))}</dd></div>
      </dl>
      ${lots}
      <div class="shopping-supply-actions">
        ${actionLotId ? `<button class="button secondary small" type="button" data-review-shopping-pantry="${escapeHtml(actionLotId)}" aria-label="Review the ${escapeHtml(name)} already recorded in the Pantry">Review Pantry Item</button>` : ""}
        <button class="button secondary small" type="button" data-page="planner" aria-label="View planned use for ${escapeHtml(name)}">View Planned Use</button>
      </div>
    </article>`;
  }

  function renderShoppingDoNotBuySection(items = []) {
    if (!items.length) return "";
    return `<section class="shopping-derived-section do-not-buy-section" aria-labelledby="shoppingDoNotBuyHeading">
      <h2 id="shoppingDoNotBuyHeading">Do Not Buy — Already Available</h2>
      <p>Advisory only. Chef Nova found enough compatible, eligible food at home for the current plan.</p>
      <div class="shopping-derived-grid">${items.map((item) => renderShoppingSupplyCard(item, "do-not-buy")).join("")}</div>
    </section>`;
  }

  function renderShoppingBuyMissingSection(items = []) {
    if (!items.length) return "";
    return `<section class="shopping-derived-section buy-missing-section" aria-labelledby="shoppingBuyMissingHeading">
      <h2 id="shoppingBuyMissingHeading">Use What You Have — Buy Only the Missing Amount</h2>
      <p>Pantry covers part of the demand. Checkout cost still uses full compatible package prices.</p>
      <div class="shopping-derived-grid">${items.map((item) => renderShoppingSupplyCard(item, "buy-missing")).join("")}</div>
    </section>`;
  }

  function renderShoppingCheckBeforeBuyingSection(items = []) {
    if (!items.length) return "";
    return `<section class="shopping-derived-section check-before-buying-section" aria-labelledby="shoppingCheckBeforeBuyingHeading">
      <h2 id="shoppingCheckBeforeBuyingHeading">Check Before Buying</h2>
      <p>Some Pantry amounts need review. Chef Nova does not treat unknown quantities as zero or sufficient.</p>
      <div class="shopping-derived-grid">${items.map((item) => renderShoppingSupplyCard(item, "check-before-buying")).join("")}</div>
    </section>`;
  }

  function renderShoppingReservedSection(items = []) {
    if (!items.length) return "";
    return `<section class="shopping-derived-section reserved-shopping-section" aria-labelledby="shoppingReservedHeading">
      <h2 id="shoppingReservedHeading">Reserved Pantry Quantities</h2>
      <p>Reserved food stays assigned to its plan unless you review and change the reservation.</p>
      <div class="shopping-derived-grid">${items.map((item) => renderShoppingSupplyCard(item, "reserved")).join("")}</div>
    </section>`;
  }

  function renderDuplicatePurchaseAdvisories(advisories = []) {
    if (!advisories.length) return "";
    return `<section class="shopping-derived-section duplicate-purchase-section" aria-labelledby="duplicatePurchaseHeading">
      <h2 id="duplicatePurchaseHeading">Duplicate-Purchase Warnings</h2>
      <div class="shopping-derived-grid">${advisories.map((advisory) => {
        const name = getIngredientDisplayNameById(advisory.canonicalIngredientId, "This item");
        return `<article class="shopping-duplicate-advisory" role="status">
          <h3>You already have ${escapeHtml(name.toLowerCase())} that needs attention</h3>
          <dl>
            <div><dt>Current eligible quantity</dt><dd>${escapeHtml(formatShoppingQuantity(advisory.evidence.eligibleQuantity, advisory.evidence.unit))}</dd></div>
            <div><dt>Planned use</dt><dd>${escapeHtml(formatShoppingQuantity(advisory.evidence.plannedQuantity, advisory.evidence.unit))}</dd></div>
            <div><dt>Estimated amount remaining</dt><dd>${escapeHtml(formatShoppingQuantity(advisory.evidence.estimatedRemainingQuantity, advisory.evidence.unit))}</dd></div>
            <div><dt>Needs attention</dt><dd>${escapeHtml(advisory.evidence.dateLabel || "Review Pantry date")}</dd></div>
          </dl>
          <p>Adding another package may increase the chance of food remaining unused.</p>
          <div class="shopping-supply-actions">
            <button class="button secondary small" type="button" data-keep-extra-package="${escapeHtml(advisory.shoppingListLineId)}" aria-label="Keep the new ${escapeHtml(name)} package on the Shopping List">Keep New Package</button>
            <button class="button secondary small remove-shopping-button" type="button" data-remove-duplicate-shopping="${escapeHtml(advisory.shoppingListLineId)}" aria-label="Remove the optional ${escapeHtml(name)} package from the Shopping List">Remove from Shopping List</button>
            ${advisory.matchedPantryItemIds[0] ? `<button class="button secondary small" type="button" data-review-shopping-pantry="${escapeHtml(advisory.matchedPantryItemIds[0])}" aria-label="Review the ${escapeHtml(name)} already recorded in the Pantry">Review Pantry Item</button>` : ""}
          </div>
        </article>`;
      }).join("")}</div>
    </section>`;
  }

  function getShoppingListEmptyState(model) {
    const messages = {
      [SHOPPING_LIST_FILTERS.NEED_TO_BUY]: ["No grocery items currently need to be purchased.", "Pantry may cover the visible plan requirements."],
      [SHOPPING_LIST_FILTERS.ALREADY_AT_HOME]: ["No items are confirmed at home.", "Update Pantry quantities to reduce grocery needs."],
      [SHOPPING_LIST_FILTERS.PRICE_MISSING]: ["All required grocery items currently have usable prices.", "No price issues are visible."],
      [SHOPPING_LIST_FILTERS.OPTIONAL]: ["No optional grocery items are included in this plan.", "Optional ingredients only appear when currently included."]
    };
    const [title, body] = messages[model.filters.activeFilter] || ["Your shopping list is empty.", "Add missing ingredients from a recipe or create a meal plan."];
    return emptyState(title, body, "Find Recipes", "recipes");
  }

  function renderShoppingCategorySection(category) {
    return `<section class="shopping-category-section" aria-labelledby="shoppingCategory-${escapeHtml(category.id)}">
      <h2 id="shoppingCategory-${escapeHtml(category.id)}">${escapeHtml(category.label)}</h2>
      <div class="shopping-list-grid">${category.items.map(renderShoppingListItemCard).join("")}</div>
    </section>`;
  }

  function renderShoppingListItemCard(item) {
    const costStatus = item.states.priceMissing ? "needs-review" : item.states.requiresReview ? "coverage-review" : "complete";
    const safeName = escapeHtml(item.displayName);
    const purchaseQuantityId = `shoppingQuantity-${escapeHtml(String(item.purchaseGroupId || item.shoppingItemId).replace(/[^a-z0-9_-]/gi, "-"))}`;
    const warningId = item.warnings.length ? `shoppingWarning-${escapeHtml(String(item.shoppingItemId).replace(/[^a-z0-9_-]/gi, "-"))}` : "";
    const selectedInput = item.purchase.priceBasis === PRICE_BASIS_TYPES.PACKAGE
      ? `<label class="shopping-quantity-control" for="${purchaseQuantityId}">Purchase packages for ${safeName}<input id="${purchaseQuantityId}" type="number" min="0" step="1" value="${escapeHtml(item.purchase.selectedPurchaseQuantity ?? "")}" data-shopping-purchase-quantity="${escapeHtml(item.purchaseGroupId || item.shoppingItemId)}" ${warningId ? `aria-describedby="${warningId}"` : ""}></label>`
      : item.purchase.priceBasis === PRICE_BASIS_TYPES.UNIT_RATE
        ? `<label class="shopping-quantity-control" for="${purchaseQuantityId}">Purchase quantity for ${safeName}<input id="${purchaseQuantityId}" type="number" min="0" step="0.01" value="${escapeHtml(item.purchase.selectedPurchaseQuantity ?? "")}" data-shopping-purchase-quantity="${escapeHtml(item.purchaseGroupId || item.shoppingItemId)}" ${warningId ? `aria-describedby="${warningId}"` : ""}><small>${escapeHtml(item.purchase.selectedPurchaseUnit || item.requirement.unit || "")}</small></label>`
        : "";
    return `<article class="shopping-item-card ${item.states.purchased ? "checked" : ""} ${costStatus === "needs-review" ? "needs-price-review" : ""} ${item.overrides.removedFromPurchaseList ? "removed-required" : ""}" data-cost-status="${escapeHtml(costStatus)}">
      <div>
        <span class="eyebrow">${item.states.custom ? "CUSTOM ITEM" : item.categoryLabel.toUpperCase()}</span>
        <h2>${escapeHtml(item.displayName)}</h2>
        ${item.originalLabels.length ? `<p class="shopping-original-labels">Saved label: ${escapeHtml(item.originalLabels.slice(0, 2).join(", "))}</p>` : ""}
        <dl class="shopping-cost-details">
          <div><dt>Needed</dt><dd>${escapeHtml(formatShoppingQuantity(item.requirement.totalRequiredQuantity, item.requirement.unit))}</dd></div>
          <div><dt>At home</dt><dd>${escapeHtml(formatShoppingQuantity(item.requirement.pantryQuantityApplied, item.requirement.unit))}</dd></div>
          <div><dt>Need to buy</dt><dd>${escapeHtml(formatShoppingQuantity(item.requirement.missingQuantity, item.requirement.unit))}</dd></div>
          <div><dt>Suggested purchase</dt><dd>${escapeHtml(item.purchase.suggestedPurchaseText || "Review needed")}</dd></div>
          <div><dt>Estimated price</dt><dd>${Number.isInteger(item.purchase.selectedPurchaseCostCents) ? escapeHtml(formatCostCents(item.purchase.selectedPurchaseCostCents)) : "Price needed"}</dd></div>
          <div><dt>Preferred store</dt><dd>${escapeHtml(item.price.profileLabel || "Not selected")}</dd></div>
          <div><dt>Supply status</dt><dd>${escapeHtml(formatShoppingSupplyStatus(item.supplyStatus))}</dd></div>
          <div><dt>Line origin</dt><dd>${escapeHtml(formatShoppingLineOrigin(item.origin))}</dd></div>
          <div><dt>Required by plan</dt><dd>${escapeHtml(formatShoppingQuantity(item.requirement.planRequiredPurchaseQuantity || 0, item.requirement.unit))}</dd></div>
          <div><dt>User-requested extra</dt><dd>${escapeHtml(formatShoppingQuantity(item.requirement.userRequestedExtraQuantity || 0, item.requirement.unit || item.purchase.selectedPurchaseUnit))}</dd></div>
        </dl>
        <div class="shopping-price-summary ${item.states.priceMissing ? "missing" : ""}"><b>${escapeHtml(item.price.sourceLabel || "Price not available")}</b><small>${item.price.updatedAt ? `Prices last updated: ${escapeHtml(item.price.updatedAt)}` : "No live store inventory is used."}</small>${item.price.usedFallback ? "<small>Using a Chef Nova estimate fallback.</small>" : ""}${item.price.usingSalePrice ? "<small>Using active saved sale price.</small>" : ""}</div>
        ${selectedInput}
        ${renderShoppingEdgeCaseControls(item)}
        ${renderShoppingDuplicateAdvisoryForItem(item)}
        ${renderShoppingItemDetails(item)}
        ${item.warnings.length ? `<p class="shopping-cost-warning" id="${warningId}" role="status">${escapeHtml(item.warnings[0])}</p>` : ""}
      </div>
      <div class="shopping-item-actions">
        ${item.actions.canUpdatePrice ? `<button class="button secondary small" type="button" data-update-price="${escapeHtml(item.shoppingItemId)}">Update price for ${safeName}</button>` : ""}
        ${item.actions.canMarkAtHome ? `<button class="button secondary small" type="button" data-shopping-at-home="${escapeHtml(item.shoppingItemId)}">Mark ${safeName} as at home</button>` : ""}
        ${item.overrides.purchaseQuantityOverridden ? `<button class="button secondary small" type="button" data-use-suggested-shopping="${escapeHtml(item.purchaseGroupId || item.shoppingItemId)}">Use suggested quantity for ${safeName}</button>` : ""}
        ${item.actions.canRestore ? `<button class="button secondary small" type="button" data-restore-shopping="${escapeHtml(item.purchaseGroupId)}">Restore ${safeName}</button>` : `<button class="button secondary small remove-shopping-button" type="button" data-remove-shopping="${escapeHtml(item.shoppingItemId)}">Remove ${safeName}</button>`}
        <button class="button secondary small" type="button" data-toggle-shopping="${escapeHtml(item.shoppingItemId)}">${item.states.purchased ? `Mark ${safeName} as needed` : `Mark ${safeName} as bought`}</button>
      </div>
    </article>`;
  }

  function formatShoppingSupplyStatus(status) {
    return {
      [SHOPPING_LIST_SUPPLY_STATUSES.FULLY_COVERED_AT_HOME]: "Fully covered at home",
      [SHOPPING_LIST_SUPPLY_STATUSES.PARTIALLY_COVERED_AT_HOME]: "Partially covered at home",
      [SHOPPING_LIST_SUPPLY_STATUSES.RESERVED_FOR_THIS_PLAN]: "Reserved for this plan",
      [SHOPPING_LIST_SUPPLY_STATUSES.RESERVED_FOR_OTHER_COMMITMENT]: "Reserved for another commitment",
      [SHOPPING_LIST_SUPPLY_STATUSES.PURCHASE_REQUIRED]: "Purchase required",
      [SHOPPING_LIST_SUPPLY_STATUSES.OPTIONAL_PURCHASE]: "Optional purchase",
      [SHOPPING_LIST_SUPPLY_STATUSES.USER_EXTRA_PURCHASE]: "User-requested extra",
      [SHOPPING_LIST_SUPPLY_STATUSES.QUANTITY_REVIEW_REQUIRED]: "Check quantity before buying",
      [SHOPPING_LIST_SUPPLY_STATUSES.DATE_REVIEW_REQUIRED]: "Check date before buying",
      [SHOPPING_LIST_SUPPLY_STATUSES.SAFETY_REVIEW_REQUIRED]: "Safety review required",
      [SHOPPING_LIST_SUPPLY_STATUSES.INCOMPATIBLE_AT_HOME]: "Incompatible at-home item"
    }[status] || "Purchase required";
  }

  function formatShoppingLineOrigin(origin) {
    return {
      [SHOPPING_LIST_LINE_ORIGINS.PLAN_REQUIRED]: "Plan required",
      [SHOPPING_LIST_LINE_ORIGINS.USER_MANUAL]: "User manual",
      [SHOPPING_LIST_LINE_ORIGINS.USER_KEPT_EXTRA]: "User-kept extra",
      [SHOPPING_LIST_LINE_ORIGINS.OPTIONAL_RECIPE_ITEM]: "Optional recipe item",
      [SHOPPING_LIST_LINE_ORIGINS.SUBSTITUTION]: "Substitution",
      [SHOPPING_LIST_LINE_ORIGINS.EMERGENCY_PLAN]: "Emergency plan",
      [SHOPPING_LIST_LINE_ORIGINS.IMPORTED]: "Imported"
    }[origin] || "User manual";
  }

  function renderShoppingDuplicateAdvisoryForItem(item) {
    const advisory = item.duplicatePurchaseAdvisory;
    if (!advisory) return "";
    const name = item.displayName || "this item";
    return `<div class="shopping-duplicate-inline" role="status">
      <h3>You already have ${escapeHtml(name.toLowerCase())} that needs attention</h3>
      <p>Adding another package may increase the chance of food remaining unused.</p>
      <div class="shopping-supply-actions">
        <button class="button secondary small" type="button" data-keep-extra-package="${escapeHtml(item.shoppingItemId)}" aria-label="Keep the new ${escapeHtml(name)} package on the Shopping List">Keep New Package</button>
        <button class="button secondary small remove-shopping-button" type="button" data-remove-duplicate-shopping="${escapeHtml(item.shoppingItemId)}" aria-label="Remove the optional ${escapeHtml(name)} package from the Shopping List">Remove from Shopping List</button>
        ${advisory.matchedPantryItemIds[0] ? `<button class="button secondary small" type="button" data-review-shopping-pantry="${escapeHtml(advisory.matchedPantryItemIds[0])}" aria-label="Review the ${escapeHtml(name)} already recorded in the Pantry">Review Pantry Item</button>` : ""}
      </div>
    </div>`;
  }

  function renderShoppingEdgeCaseControls(item) {
    const pieces = [];
    if (item.edgeCases?.unknownPantryIssue) {
      const groupId = item.purchaseGroupId || item.shoppingItemId;
      const safeGroupId = groupId.replace(/[^a-z0-9_-]/gi, "-");
      const helpId = `edgePantryHelp-${escapeHtml(safeGroupId)}`;
      const quantityId = `edgePantryQuantity-${escapeHtml(safeGroupId)}`;
      const unitId = `edgePantryUnit-${escapeHtml(safeGroupId)}`;
      pieces.push(`<fieldset class="edge-case-control unknown-pantry-control" data-edge-pantry-controls aria-describedby="${helpId}">
        <legend>${escapeHtml(item.edgeCases.unknownPantryIssue.message)}</legend>
        <label><input type="radio" name="edge-pantry-${escapeHtml(safeGroupId)}" value="${UNKNOWN_PANTRY_RESOLUTIONS.ENOUGH_FOR_CURRENT_PLAN}"> I have enough for this plan</label>
        <label><input type="radio" name="edge-pantry-${escapeHtml(safeGroupId)}" value="${UNKNOWN_PANTRY_RESOLUTIONS.SOME}" aria-controls="edgePantrySomeFields-${escapeHtml(safeGroupId)}"> I have some</label>
        <div class="edge-case-quantity-row" id="edgePantrySomeFields-${escapeHtml(safeGroupId)}" data-edge-pantry-some-fields hidden>
          <label for="${quantityId}">Quantity for ${escapeHtml(item.displayName)} <input id="${quantityId}" type="number" min="0.01" step="0.01" data-edge-pantry-quantity></label>
          <label for="${unitId}">Unit for ${escapeHtml(item.displayName)} <select id="${unitId}" data-edge-pantry-unit>${getKnownPriceUnits().map((unit) => `<option value="${escapeHtml(unit)}" ${unit === item.requirement.unit ? "selected" : ""}>${escapeHtml(unit)}</option>`).join("")}</select></label>
        </div>
        <label><input type="radio" name="edge-pantry-${escapeHtml(safeGroupId)}" value="${UNKNOWN_PANTRY_RESOLUTIONS.ADD_TO_GROCERY_LIST}"> Add ${escapeHtml(item.displayName)} to the grocery list</label>
        <p class="edge-case-help" id="${helpId}">No Pantry amount is assumed until you choose one. ${escapeHtml(item.displayName)} will remain on the grocery list because the Pantry quantity has not been confirmed.</p>
        <button class="button secondary small" type="button" data-edge-pantry-resolve="${escapeHtml(groupId)}">Apply Pantry Choice</button>
      </fieldset>`);
    }
    if (item.states.priceMissing) {
      pieces.push(`<div class="edge-case-control missing-price-control">
        <b>Price required</b>
        <p>Missing prices stay visible and are never counted as $0.00.</p>
        ${item.actions.canUpdatePrice ? `<button class="button secondary small" type="button" data-update-price="${escapeHtml(item.shoppingItemId)}">Add Approximate Price</button>` : ""}
      </div>`);
    }
    const promotion = item.edgeCases?.promotionEvaluation;
    if (promotion && promotion.status !== PROMOTION_EVALUATION_STATUSES.APPLIED) {
      const message = promotion.status === PROMOTION_EVALUATION_STATUSES.EXTRA_QUANTITY_REQUIRED
        ? `Promotion not applied. The current plan requires ${promotion.requiredPackageCount} ${pluralize(promotion.requiredPackageCount, "package")}, so Chef Nova will not buy extra packages automatically.`
        : promotion.status === PROMOTION_EVALUATION_STATUSES.NOT_BENEFICIAL
          ? "Promotion not applied. Buying the promotional bundle would cost more at checkout than buying the packages required by the current plan."
          : promotion.status === PROMOTION_EVALUATION_STATUSES.MOVES_PLAN_ABOVE_BUDGET
            ? "Promotion not applied. It would move the current plan above the selected budget."
            : "Promotion not applied. The promotion terms need review.";
      pieces.push(`<div class="edge-case-control promotion-control">
        <b>Promotion not applied</b>
        <p>${escapeHtml(message)}</p>
        ${Number.isInteger(promotion.regularOnlyCostCents) && Number.isInteger(promotion.promotionCostCents) ? `<dl><div><dt>Regular checkout</dt><dd>${escapeHtml(formatCostCents(promotion.regularOnlyCostCents))}</dd></div><div><dt>Promotion checkout</dt><dd>${escapeHtml(formatCostCents(promotion.promotionCostCents))}</dd></div></dl>` : ""}
      </div>`);
    }
    const remainder = item.edgeCases?.packageRemainder;
    if (remainder && remainder.estimatedRemainingQuantity > 0) {
      const packageText = item.purchase.priceBasis === PRICE_BASIS_TYPES.PACKAGE && Number.isFinite(Number(item.purchase.suggestedPackageCount)) && Number(item.purchase.suggestedPackageCount) > 1
        ? `${item.purchase.suggestedPackageCount} x ${formatShoppingQuantity(item.purchase.suggestedPackageCount ? remainder.purchasedQuantity / item.purchase.suggestedPackageCount : remainder.purchasedQuantity, remainder.purchasedUnit)} packages`
        : formatShoppingQuantity(remainder.purchasedQuantity, remainder.purchasedUnit);
      pieces.push(`<div class="edge-case-control package-remainder-control" aria-label="Potential future Pantry amount for ${escapeHtml(item.displayName)}">
        <dl>
          <div><dt>Purchase</dt><dd>${escapeHtml(packageText)}</dd></div>
          <div><dt>Used this week</dt><dd>${escapeHtml(formatShoppingQuantity(remainder.quantityUsedByPlan, remainder.remainingUnit))}</dd></div>
          <div><dt>Estimated remaining amount</dt><dd>${escapeHtml(formatShoppingQuantity(remainder.estimatedRemainingQuantity, remainder.remainingUnit))}</dd></div>
        </dl>
        <p>This is potential future Pantry inventory. It is not added automatically.</p>
        <button class="button secondary small" type="button" data-add-remainder-to-pantry="${escapeHtml(remainder.remainderId)}">Add ${escapeHtml(formatShoppingQuantity(remainder.estimatedRemainingQuantity, remainder.remainingUnit))} to Pantry</button>
      </div>`);
    }
    return pieces.length ? `<div class="shopping-edge-case-stack">${pieces.join("")}</div>` : "";
  }

  function renderShoppingItemDetails(item) {
    const sources = item.sourceMealIds.length ? item.sourceMealIds.map((mealId) => mealId.replace("::", " ")).join(", ") : "Custom item or source unavailable";
    return `<details class="shopping-item-details">
      <summary>Item details</summary>
      <p>Used by: ${escapeHtml(sources)}.</p>
      <p>Estimated surplus: ${escapeHtml(item.purchase.estimatedSurplusQuantity === null || item.purchase.estimatedSurplusQuantity === undefined ? "Not available" : formatShoppingQuantity(item.purchase.estimatedSurplusQuantity, item.purchase.estimatedSurplusUnit))}.</p>
      <p>Grocery item counts are shared across meals. Filters change the view only; they do not change totals.</p>
    </details>`;
  }

  function updateUnknownPantryConditionalFields(container) {
    if (!container) return;
    const selected = container.querySelector("input[type='radio']:checked")?.value || "";
    const someFields = container.querySelector("[data-edge-pantry-some-fields]");
    if (!someFields) return;
    const shouldShow = selected === UNKNOWN_PANTRY_RESOLUTIONS.SOME;
    someFields.hidden = !shouldShow;
    $$("input, select", someFields).forEach((field) => {
      field.disabled = !shouldShow;
      if (!shouldShow) field.removeAttribute("aria-invalid");
    });
    if (shouldShow) someFields.querySelector("input, select")?.focus();
  }

  function toggleShoppingItem(itemId) {
    const item = getShoppingItemForAction(itemId);
    if (!item) return;
    if (item.purchaseGroupId) {
      saveShoppingListOverride(item.purchaseGroupId, { checked: !item.states.purchased });
    } else {
      const items = getShoppingListItems().map((storedItem) => storedItem.id === itemId ? { ...storedItem, checked: !storedItem.checked } : storedItem);
      saveShoppingListItems(items);
    }
    displayShoppingList();
  }

  function removeShoppingItem(itemId) {
    const item = getShoppingItemForAction(itemId);
    if (!item) return;
    if (item.purchaseGroupId) {
      saveShoppingListOverride(item.purchaseGroupId, { removedFromPurchaseList: true, selectedPurchaseQuantity: 0, checked: false });
    } else {
      const items = getShoppingListItems().filter((storedItem) => storedItem.id !== itemId);
      saveShoppingListItems(items);
    }
    displayShoppingList();
    showToast(state.guestMode ? `Shopping item removed for this session. ${GUEST_TEMPORARY_MESSAGE}` : "Shopping item removed", state.guestMode ? "info" : "success", state.guestMode ? {} : { saveToHistory: true, actionName: "View Shopping List", actionTarget: "shopping-list" });
  }

  function keepDuplicateShoppingPackage(itemId) {
    const item = getShoppingItemForAction(itemId);
    if (!item) return showToast("Shopping item needs review.", "warning");
    const advisory = item.duplicatePurchaseAdvisory;
    const patch = {
      origin: SHOPPING_LIST_LINE_ORIGINS.USER_KEPT_EXTRA,
      userKeptExtra: true,
      duplicatePurchaseDecision: {
        advisoryId: advisory?.advisoryId || `duplicate-purchase::${itemId}`,
        userDecision: "keep-new-package",
        decidedAt: getCurrentIsoString(),
        sourceRevisions: advisory?.sourceRevisions || getShoppingListSourceRevisions()
      },
      updatedAt: getCurrentIsoString()
    };
    if (item.purchaseGroupId) saveShoppingListOverride(item.purchaseGroupId, patch);
    else {
      saveShoppingListItems(getShoppingListItems().map((storedItem) => storedItem.id === itemId ? { ...storedItem, ...patch } : storedItem));
    }
    refreshShoppingListDependentViews();
    showToast("Package kept. The Shopping List was recalculated and Pantry was not changed.", "info");
  }

  function removeDuplicateShoppingPackage(itemId) {
    const item = getShoppingItemForAction(itemId);
    if (!item) return showToast("Shopping item needs review.", "warning");
    if (item.purchaseGroupId && item.requirement?.missingQuantity > 0) {
      showToast("This package is still needed. Buy the missing amount or choose another recipe.", "warning");
      return;
    }
    removeShoppingItem(itemId);
    announcePolite("Package removed. The Pantry quantity was not changed.", { key: `duplicate-remove-${itemId}` });
  }

  function reviewShoppingPantryItem(pantryItemId) {
    if (!pantryItemId || !state.pantry.some((item) => item.id === pantryItemId)) {
      showToast("Pantry item needs review.", "warning");
      return;
    }
    navigate("pantry");
    displayPantry();
    setTimeout(() => {
      const safePantryItemId = String(pantryItemId).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
      const target = $(`[data-pantry-item-id="${safePantryItemId}"]`) || $("#pantryList");
      target?.scrollIntoView?.({ behavior: "smooth", block: "center" });
      target?.focus?.();
    }, 0);
    showToast("Review the Pantry item before changing the Shopping List.", "info");
  }

  function restoreShoppingItem(purchaseGroupId) {
    const item = deriveShoppingListViewModel({ activeFilter: SHOPPING_LIST_FILTERS.ALL }).items.find((candidate) => candidate.purchaseGroupId === purchaseGroupId);
    if (!item) return;
    saveShoppingListOverride(purchaseGroupId, { removedFromPurchaseList: false, selectedPurchaseQuantity: undefined, checked: false });
    displayShoppingList();
    showToast("Shopping item restored.", "success");
  }

  function resetShoppingPurchaseQuantity(purchaseGroupId) {
    const item = deriveShoppingListViewModel({ activeFilter: SHOPPING_LIST_FILTERS.ALL }).items.find((candidate) => candidate.purchaseGroupId === purchaseGroupId);
    if (!item) return;
    saveShoppingListOverride(purchaseGroupId, { selectedPurchaseQuantity: undefined, selectedPurchaseUnit: undefined, removedFromPurchaseList: false });
    refreshShoppingListDependentViews();
    showToast("Suggested quantity restored.", "success");
  }

  function updateShoppingPurchaseQuantity(purchaseGroupId, value) {
    const item = deriveShoppingListViewModel({ activeFilter: SHOPPING_LIST_FILTERS.ALL }).items.find((candidate) => candidate.purchaseGroupId === purchaseGroupId);
    if (!item) return;
    const parsed = Number(value);
    if (!Number.isFinite(parsed) || parsed < 0) {
      showToast("Enter a valid purchase quantity.", "error");
      displayShoppingList();
      return;
    }
    const stepValue = item.purchase.priceBasis === PRICE_BASIS_TYPES.PACKAGE ? Math.floor(parsed) : parsed;
    saveShoppingListOverride(purchaseGroupId, {
      selectedPurchaseQuantity: stepValue,
      selectedPurchaseUnit: item.purchase.priceBasis === PRICE_BASIS_TYPES.PACKAGE ? "package" : item.purchase.selectedPurchaseUnit,
      removedFromPurchaseList: stepValue === 0
    });
    refreshShoppingListDependentViews();
  }

  function mapShoppingCategoryToPantryCategory(categoryId) {
    return {
      produce: "Vegetables",
      grains: "Grains",
      protein: "Meat",
      "dairy-alternatives": "Dairy",
      "frozen-food": "Frozen",
      "canned-goods": "Other",
      "pantry-staples": "Spices",
      other: "Other"
    }[categoryId] || "Other";
  }

  function markShoppingItemAlreadyAtHome(itemId) {
    const item = getShoppingItemForAction(itemId);
    if (!item) return;
    const now = getCurrentIsoString();
    const patch = {
      userConfirmedAtHome: true,
      removedFromPurchaseList: item.purchaseGroupId ? true : item.overrides?.removedFromPurchaseList === true,
      checked: false,
      updatedAt: now,
      sourceRevisions: getShoppingListSourceRevisions()
    };
    if (item.purchaseGroupId) saveShoppingListOverride(item.purchaseGroupId, patch);
    else saveShoppingListItems(getShoppingListItems().map((storedItem) => storedItem.id === itemId ? { ...storedItem, ...patch } : storedItem));
    refreshShoppingListDependentViews();
    showToast(state.guestMode ? `Marked at home for this session. ${GUEST_TEMPORARY_MESSAGE}` : "Marked at home for planning. Pantry was not changed.", state.guestMode ? "info" : "success");
  }

  function refreshShoppingListDependentViews() {
    displayShoppingList();
    displayMealPlanner();
    displayWeeklyNutrition();
    displayNutritionTracker();
    refreshRecipeResults();
    updateDashboardStats();
  }

  function openGroceryPriceEditor(itemId, trigger) {
    const item = getShoppingItemForAction(itemId);
    const modal = $("#priceEditorModal");
    const content = $("#priceEditorContent");
    if (!item || !modal || !content) return;
    const itemName = item.name || item.displayName || "Shopping item";
    const ingredientId = item.ingredientId || resolveCanonicalIngredientName(itemName).ingredientId || "";
    activePriceEditorItemId = itemId;
    priceEditorLastFocus = trigger || document.activeElement;
    const resolution = ingredientId ? resolveShoppingItemPrice({ ...item, ingredientId }) : { status: "missing" };
    const entry = resolution.entry || {};
    const profiles = getSavedPriceProfiles();
    const profileOptions = profiles.map((profile) => `<option value="${escapeHtml(profile.id)}">${escapeHtml(profile.name)}</option>`).join("");
    const unitOptions = getKnownPriceUnits().filter((unit) => PRICE_UNIT_OPTIONS.includes(unit)).map((unit) => `<option value="${escapeHtml(unit)}" ${entry.pricedUnit === unit ? "selected" : ""}>${escapeHtml(PRICE_DATA.unitLabel?.(unit, 2) || unit)}</option>`).join("");
    content.innerHTML = `<div class="price-editor-heading"><h2 id="priceEditorTitle">Update price for ${escapeHtml(itemName)}</h2><p>Enter the grocery price used for this plan.</p></div>
      ${ingredientId ? "" : `<p class="price-editor-warning">This item is not connected to a canonical ingredient. You can use a temporary price, but it cannot be saved to a profile.</p>`}
      <form id="priceEditorForm" class="price-editor-form" novalidate>
        <p class="price-editor-current">${escapeHtml(getPriceSourceLabel(resolution))}${resolution.status === "resolved" ? ` · ${escapeHtml(resolution.formattedPrice || PRICE_DATA.formatPriceEntry(entry))}` : ""}</p>
        <fieldset class="price-basis-fieldset">
          <legend>Price basis</legend>
          <label><input type="radio" name="priceBasis" value="${PRICE_BASIS_TYPES.PACKAGE}" ${entry.priceBasis !== PRICE_BASIS_TYPES.UNIT_RATE ? "checked" : ""}> Package price</label>
          <label><input type="radio" name="priceBasis" value="${PRICE_BASIS_TYPES.UNIT_RATE}" ${entry.priceBasis === PRICE_BASIS_TYPES.UNIT_RATE ? "checked" : ""}> Unit rate</label>
        </fieldset>
        <div class="budget-rescue-grid">
          <label for="priceEditorRegular">Regular price <span class="optional-label">CAD</span><input id="priceEditorRegular" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="3.49" value="${escapeHtml(formatCentsForInput(entry.regularPriceCents))}" aria-describedby="priceEditorError"></label>
          <label for="priceEditorSale">Sale price <span class="optional-label">Optional</span><input id="priceEditorSale" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="2.99" value="${escapeHtml(formatCentsForInput(entry.salePriceCents))}"></label>
          <label for="priceEditorQuantity">Priced quantity<input id="priceEditorQuantity" type="number" min="0.01" step="0.01" inputmode="decimal" placeholder="900" value="${escapeHtml(entry.pricedQuantity || 1)}"></label>
          <label for="priceEditorUnit">Unit<select id="priceEditorUnit">${unitOptions}</select></label>
          <label for="priceEditorSaleEnds">Sale ends <span class="optional-label">Optional</span><input id="priceEditorSaleEnds" type="date" value="${escapeHtml(entry.saleEndsOn || "")}"></label>
          <label for="priceEditorProfile">Store profile<select id="priceEditorProfile" ${profiles.length ? "" : "disabled"}><option value="">Choose profile</option>${profileOptions}</select></label>
        </div>
        <p class="form-error" id="priceEditorError" hidden></p>
        <p class="field-help">${state.guestMode ? "Guest prices are temporary and will be cleared when this session ends." : "Price profiles are saved in this browser for this account."}</p>
        <div class="price-editor-actions">
          <button class="button secondary" type="button" data-close-price-editor>Cancel</button>
          <button class="button secondary" type="button" data-use-plan-price>Use for This Plan</button>
          <button class="button primary" type="button" data-save-profile-price ${(!profiles.length || !ingredientId || state.guestMode) ? "disabled" : ""}>Save to Store Profile</button>
        </div>
      </form>`;
    modal.classList.remove("hidden");
    modal.setAttribute("aria-hidden", "false");
    document.body.classList.add("modal-open");
    $("#priceEditorRegular")?.focus();
  }

  function closeGroceryPriceEditor() {
    const modal = $("#priceEditorModal");
    if (!modal || modal.classList.contains("hidden")) return;
    modal.classList.add("hidden");
    modal.setAttribute("aria-hidden", "true");
    $("#priceEditorContent").innerHTML = "";
    document.body.classList.remove("modal-open");
    priceEditorLastFocus?.focus?.();
    activePriceEditorItemId = "";
  }

  function readPriceEditorEntry(sourceType, profileId = "") {
    const item = getShoppingItemForAction(activePriceEditorItemId);
    const ingredientId = item?.ingredientId || resolveCanonicalIngredientName(item?.name || item?.displayName).ingredientId || "";
    const regular = PRICE_DATA.dollarsToCents?.($("#priceEditorRegular")?.value);
    const saleValue = $("#priceEditorSale")?.value;
    const sale = saleValue ? PRICE_DATA.dollarsToCents?.(saleValue) : { valid: true, cents: null };
    const error = $("#priceEditorError");
    if (!ingredientId) return { valid: false, message: "This item is not connected to the ingredient catalogue." };
    if (!regular?.valid || !sale?.valid) return { valid: false, message: "Enter valid prices in CAD." };
    if (sale.cents && sale.cents > regular.cents) return { valid: false, message: "Sale price cannot be higher than regular price." };
    const quantity = Number($("#priceEditorQuantity")?.value);
    if (!Number.isFinite(quantity) || quantity <= 0) return { valid: false, message: "Enter a positive priced quantity." };
    if (error) error.hidden = true;
    return { valid: true, entry: normalizePriceEntry({
      id: `price-${ingredientId}-${Date.now()}`,
      ingredientId,
      storeProfileId: profileId,
      sourceType,
      priceBasis: $("[name='priceBasis']:checked", $("#priceEditorForm"))?.value || PRICE_BASIS_TYPES.PACKAGE,
      pricedQuantity: quantity,
      pricedUnit: $("#priceEditorUnit")?.value || "each",
      regularPriceCents: regular.cents,
      salePriceCents: sale.cents,
      saleEndsOn: $("#priceEditorSaleEnds")?.value || null,
      currency: "CAD",
      updatedAt: getCurrentIsoString(),
      createdAt: getCurrentIsoString(),
      updatedBy: "user",
      isPreferred: true
    }) };
  }

  function showPriceEditorError(message) {
    const error = $("#priceEditorError");
    if (error) {
      error.textContent = message;
      error.hidden = false;
    }
    $("#priceEditorRegular")?.setAttribute("aria-invalid", "true");
    focusFirstInvalidField($("#priceEditorForm"));
    announceAssertive(message, { key: `price-editor:${message}` });
  }

  function savePriceEditor(destination) {
    const profileId = $("#priceEditorProfile")?.value || "";
    if (destination === "profile" && state.guestMode) return showGuestSaveRestriction();
    if (destination === "profile" && !profileId) return showPriceEditorError("Choose a store profile.");
    const result = readPriceEditorEntry(destination === "profile" ? PRICE_SOURCE_TYPES.STORE_PROFILE : PRICE_SOURCE_TYPES.USER_ENTERED, profileId);
    if (!result.valid || !result.entry) return showPriceEditorError(result.message || "Enter a valid price.");
    if (destination === "profile") {
      if (!savePriceEntryToProfile(profileId, result.entry)) return showPriceEditorError("Unable to save this price.");
      updatePlanningModeInput("priceSource", BUDGET_RESCUE_PRICE_SOURCES.SAVED_PROFILE);
      updatePlanningModeInput("savedPriceProfileId", profileId);
      showToast("Price saved to store profile.", "success");
    } else {
      const budget = normalizePlanningModeInputs(state.planningModeInputs).budgetRescue;
      budget.sessionPriceOverrides = normalizePriceEntries([...(budget.sessionPriceOverrides || []).filter((entry) => entry.ingredientId !== result.entry.ingredientId), result.entry]);
      state.planningModeInputs.budgetRescue = budget;
      if (state.guestMode) guestSessionData.priceOverrides = budget.sessionPriceOverrides;
      syncPlanningModeMetadataToPlan();
      if (state.guestMode) persistGuestProgress();
      updatePlanningModeInput("priceSource", BUDGET_RESCUE_PRICE_SOURCES.USER_ENTERED);
      showToast(state.guestMode ? `Temporary price saved. ${GUEST_TEMPORARY_MESSAGE}` : "Price saved for this plan.", state.guestMode ? "info" : "success");
    }
    closeGroceryPriceEditor();
    displayMealPlanner();
    displayShoppingList();
  }

  function ingredientTag(ingredient) {
    return `<span>${escapeHtml(ingredientTagText(ingredient))}</span>`;
  }

  function ingredientTagText(ingredient) {
    if (ingredient?.displayText) return ingredient.displayText;
    const amount = ingredient?.quantity ? `${ingredient.quantity} ${ingredient.unit || ""}`.trim() + " " : "";
    return `${amount}${ingredient?.name || ""}`.trim();
  }

  function getMatchLevel(percent) {
    if (percent >= 80) return "Excellent Match";
    if (percent >= 60) return "Good Match";
    if (percent >= 30) return "Partial Match";
    return "Low Match";
  }

  function matchClass(percent) {
    if (percent >= 80) return "excellent";
    if (percent >= 60) return "good";
    if (percent >= 30) return "partial";
    return "low";
  }

  function emptyRecipeState() {
    return `<div class="empty-state"><span>✦</span><h3>No matching recipes were found.</h3><p>Adjust filters, check spelling, or try fewer ingredients.</p></div>`;
  }

  function toNumber(value) {
    return Number(String(value || "0").replace(/[^\d.]/g, "")) || 0;
  }

  function normalizeNutritionNumber(value) {
    const number = Number(value);
    return Number.isFinite(number) && number >= 0 ? number : 0;
  }

  function normalizeOptionalNutritionNumber(value) {
    if (value === null || value === undefined || value === "") return null;
    const number = Number(value);
    return Number.isFinite(number) && number >= 0 ? number : null;
  }

  function getRecipeNutritionForServings(recipe, servings = 1) {
    const safeServings = Number.isFinite(servings) && servings > 0 ? servings : 1;
    const nutrition = recipe?.nutrition || recipe || {};
    const calories = normalizeOptionalNutritionNumber(nutrition.calories);
    const protein = normalizeOptionalNutritionNumber(nutrition.protein);
    const carbohydrates = normalizeOptionalNutritionNumber(nutrition.carbohydrates);
    const fat = normalizeOptionalNutritionNumber(nutrition.fat);
    const fibre = normalizeOptionalNutritionNumber(nutrition.fibre ?? nutrition.fiber);
    const sugar = normalizeOptionalNutritionNumber(nutrition.sugar);
    const addedSugar = normalizeOptionalNutritionNumber(nutrition.addedSugar);
    const vegetableServings = normalizeOptionalNutritionNumber(nutrition.vegetableServings);
    return {
      calories: calories !== null ? calories * safeServings : null,
      protein: protein !== null ? protein * safeServings : null,
      carbohydrates: carbohydrates !== null ? carbohydrates * safeServings : null,
      fat: fat !== null ? fat * safeServings : null,
      fibre: fibre !== null ? fibre * safeServings : null,
      sugar: sugar !== null ? sugar * safeServings : null,
      addedSugar: addedSugar !== null ? addedSugar * safeServings : null,
      vegetableServings: vegetableServings !== null ? vegetableServings * safeServings : null
    };
  }

  function calculateRecipeRangeContribution(nutrientAmount, dailyMinimum, dailyMaximum) {
    if (
      !Number.isFinite(nutrientAmount) ||
      nutrientAmount < 0 ||
      !Number.isFinite(dailyMinimum) ||
      !Number.isFinite(dailyMaximum) ||
      dailyMinimum <= 0 ||
      dailyMaximum < dailyMinimum
    ) {
      return null;
    }
    const minimumPercentage = (nutrientAmount / dailyMaximum) * 100;
    const maximumPercentage = (nutrientAmount / dailyMinimum) * 100;
    if (!Number.isFinite(minimumPercentage) || !Number.isFinite(maximumPercentage)) return null;
    return {
      minimum: Math.max(0, Math.round(minimumPercentage)),
      maximum: Math.max(0, Math.round(maximumPercentage))
    };
  }

  function clampRecipeContributionValue(value) {
    if (!Number.isFinite(value)) return null;
    return Math.min(Math.max(0, Math.round(value)), MAX_DISPLAYED_RECIPE_CONTRIBUTION);
  }

  function formatApproximatePercentageRange(range) {
    if (!range || !Number.isFinite(range.minimum) || !Number.isFinite(range.maximum)) return null;
    const minimum = clampRecipeContributionValue(range.minimum);
    const maximum = clampRecipeContributionValue(range.maximum);
    if (minimum === null || maximum === null) return null;
    if (range.minimum > MAX_DISPLAYED_RECIPE_CONTRIBUTION || range.maximum > MAX_DISPLAYED_RECIPE_CONTRIBUTION) return `More than ${MAX_DISPLAYED_RECIPE_CONTRIBUTION}%`;
    if (minimum === maximum) return `approximately ${minimum}%`;
    return `approximately ${minimum}\u2013${maximum}%`;
  }

  function formatRecipeNutritionValue(value, unit = "") {
    if (!Number.isFinite(value)) return "Not available";
    const rounded = Math.round(value);
    return unit ? `${rounded.toLocaleString()} ${unit}` : rounded.toLocaleString();
  }

  function buildRecipeNutritionTags(recipe, selectedNutrition = null) {
    const perServingNutrition = getRecipeNutritionForServings(recipe, 1);
    const tags = [];
    const addTag = (tag) => {
      if (!tags.includes(tag)) tags.push(tag);
    };
    if (perServingNutrition.protein >= RECIPE_NUTRITION_TAG_RULES.higherProteinGrams) addTag("Higher protein");
    if (perServingNutrition.vegetableServings !== null && perServingNutrition.vegetableServings >= RECIPE_NUTRITION_TAG_RULES.vegetableRichServings) addTag("Vegetable-rich");
    if (perServingNutrition.fibre !== null && perServingNutrition.fibre >= RECIPE_NUTRITION_TAG_RULES.higherFibreGrams) addTag("Higher fibre");
    if (perServingNutrition.carbohydrates >= RECIPE_NUTRITION_TAG_RULES.carbohydrateRichGrams) addTag("Carbohydrate-rich");
    if (perServingNutrition.addedSugar !== null && perServingNutrition.addedSugar <= RECIPE_NUTRITION_TAG_RULES.lowerAddedSugarGrams) addTag("Lower added sugar");
    const ingredientNames = normalizeIngredientList(recipe?.ingredients || []).map((ingredient) => normalizeIngredient(ingredient.name));
    const unsaturatedSources = ["nuts", "walnuts", "almonds", "seeds", "chia seeds", "sesame seeds", "avocado", "olive oil", "canola oil"];
    if (ingredientNames.some((ingredient) => unsaturatedSources.some((source) => ingredient.includes(source)))) addTag("Contains unsaturated fat");
    if (perServingNutrition.protein >= 10 && perServingNutrition.carbohydrates >= 20 && perServingNutrition.fat >= 5 && (perServingNutrition.vegetableServings || 0) >= 0.5) addTag("Balanced meal option");
    const profile = getCurrentNutritionProfile();
    if (profile?.goal === "support-workouts" && perServingNutrition.protein >= 15 && perServingNutrition.carbohydrates >= 30 && perServingNutrition.calories >= 250) addTag("Workout-supporting");
    return tags.slice(0, 4);
  }

  function buildRecipePlanFit(recipe, selectedServings, dailyTarget) {
    const nutrition = getRecipeNutritionForServings(recipe, selectedServings);
    const baseResult = {
      available: false,
      nutrition,
      contributions: null,
      tags: buildRecipeNutritionTags(recipe, nutrition),
      message: "Personalized comparison unavailable."
    };
    const hasCoreNutrition = ["calories", "protein", "carbohydrates", "fat"].every((field) => Number.isFinite(nutrition[field]));
    if (!hasCoreNutrition) {
      return {
        ...baseResult,
        message: "Nutrition information unavailable for this recipe."
      };
    }
    if (!validateDailyNutritionTarget(dailyTarget)) {
      return {
        ...baseResult,
        message: "Complete your optional Nutrition Profile to see how this recipe compares with your estimated daily range."
      };
    }
    const contributions = {
      calories: calculateRecipeRangeContribution(nutrition.calories, dailyTarget.calorieMin, dailyTarget.calorieMax),
      protein: calculateRecipeRangeContribution(nutrition.protein, dailyTarget.proteinMin, dailyTarget.proteinMax),
      carbohydrates: calculateRecipeRangeContribution(nutrition.carbohydrates, dailyTarget.carbohydrateMin, dailyTarget.carbohydrateMax),
      fat: calculateRecipeRangeContribution(nutrition.fat, dailyTarget.fatMin, dailyTarget.fatMax)
    };
    if (!contributions.protein || !contributions.carbohydrates || !contributions.fat || !contributions.calories) {
      return {
        ...baseResult,
        message: "Chef Nova could not create a reliable recipe comparison from the available nutrition data."
      };
    }
    return {
      available: true,
      nutrition,
      contributions,
      tags: buildRecipeNutritionTags(recipe, nutrition),
      message: "These percentages are approximate planning references based on the selected serving amount."
    };
  }

  function buildRecipeContributionStatements(recipePlanFit) {
    if (!recipePlanFit?.available) return [];
    const { calories, protein, carbohydrates, fat } = recipePlanFit.contributions;
    return [
      `${formatApproximatePercentageRange(calories)} of your estimated daily calorie range`,
      `${formatApproximatePercentageRange(protein)} of your daily protein range`,
      `${formatApproximatePercentageRange(carbohydrates)} of your daily carbohydrate range`,
      `${formatApproximatePercentageRange(fat)} of your daily fat range`
    ].filter((statement) => statement && !statement.startsWith("null"));
  }

  function getRecipeNutritionTagScore(recipe) {
    const priority = ["Higher protein", "Vegetable-rich", "Higher fibre", "Carbohydrate-rich", "Lower added sugar", "Contains unsaturated fat", "Balanced meal option", "Workout-supporting"];
    const tags = buildRecipeNutritionTags(recipe);
    return tags.reduce((score, tag) => {
      const index = priority.indexOf(tag);
      return score + (index >= 0 ? priority.length - index : 0);
    }, 0);
  }

  function renderRecipePlanFit(recipe, selectedServings = 1) {
    const nutritionProfile = getCurrentNutritionProfile();
    const dailyTarget = getCurrentDailyNutritionTarget(nutritionProfile);
    const recipePlanFit = buildRecipePlanFit(recipe, selectedServings, dailyTarget);
    const nutrition = recipePlanFit.nutrition;
    const contributionStatements = buildRecipeContributionStatements(recipePlanFit);
    const isMinor = Number(nutritionProfile?.age) > 0 && Number(nutritionProfile.age) < 18;
    const servingLabel = selectedServings === 1 ? "serving" : "servings";
    return `<div class="recipe-fit-grid">
      <div class="recipe-fit-panel">
        <h4>Selected serving nutrition</h4>
        <p class="recipe-fit-serving-note">${escapeHtml(String(selectedServings))} ${servingLabel}</p>
        <dl class="recipe-fit-nutrition">
          <div><dt>Calories</dt><dd>${formatRecipeNutritionValue(nutrition.calories, "calories")}</dd></div>
          <div><dt>Protein</dt><dd>${formatRecipeNutritionValue(nutrition.protein, "g")}</dd></div>
          <div><dt>Carbohydrates</dt><dd>${formatRecipeNutritionValue(nutrition.carbohydrates, "g")}</dd></div>
          <div><dt>Fat</dt><dd>${formatRecipeNutritionValue(nutrition.fat, "g")}</dd></div>
          <div><dt>Fibre</dt><dd>${formatRecipeNutritionValue(nutrition.fibre, "g")}</dd></div>
          <div><dt>Sugar</dt><dd>${formatRecipeNutritionValue(nutrition.sugar, "g")}</dd></div>
          <div><dt>Vegetable servings</dt><dd>${formatRecipeNutritionValue(nutrition.vegetableServings)}</dd></div>
        </dl>
      </div>
      <div class="recipe-fit-panel">
        <h4>Daily range contribution</h4>
        ${recipePlanFit.available ? `<p class="recipe-fit-message">This meal provides:</p><ul class="recipe-fit-contributions">${contributionStatements.map((statement) => `<li>${escapeHtml(statement)}</li>`).join("")}</ul>` : `<div class="recipe-fit-message unavailable"><strong>Personalized comparison unavailable</strong><p>${escapeHtml(recipePlanFit.message)}</p></div>`}
      </div>
    </div>
    ${isMinor ? `<p class="recipe-fit-minor-note">For users under 18, these comparisons are intended to support regular balanced meals and activity, not calorie restriction.</p>` : ""}
    <div class="recipe-fit-disclaimers">
      <p>These percentages are approximate planning references based on the selected serving amount. Your actual needs and portions may differ.</p>
      <p>Chef Nova records planned recipe information and may not reflect everything eaten during the day.</p>
      <p>Ingredient substitutions, added toppings, sauces, oils, or portion changes may change the nutrition values.</p>
    </div>`;
  }

  function updateRecipePlanFitSection(recipeId) {
    const recipe = state.recipes.map(normalizeRecipe).find((item) => item.id === recipeId);
    const content = $("#recipePlanFitContent");
    if (!recipe || !content) return;
    const input = Array.from(document.querySelectorAll("[data-recipe-detail-servings]")).find((candidate) => candidate.dataset.recipeDetailServings === recipeId);
    const selectedServings = Math.max(1, Math.floor(Number(input?.value) || 1));
    if (input && String(selectedServings) !== input.value) input.value = selectedServings;
    content.innerHTML = renderRecipePlanFit(recipe, selectedServings);
    const costContent = $("#recipeCostContent");
    if (costContent) costContent.innerHTML = renderRecipeCostSummary(recipe, selectedServings);
    const status = $("#recipeFitStatus");
    if (status) status.textContent = `Recipe nutrition updated for ${selectedServings} ${selectedServings === 1 ? "serving" : "servings"}.`;
  }

  function toggleFavorite(id) {
    if (isRecipeFavorite(id)) removeFavorite(id); else saveFavorite(id);
  }

  /* Save one recipe id to the active mode's favorites storage. */
  function saveFavorite(id) {
    if (!requireAccount("save your favorites")) return;
    if (!state.recipes.some((recipe) => recipe.id === id)) {
      showToast("Recipe not found", "error");
      return;
    }
    if (isRecipeFavorite(id)) return;
    state.favorites = Array.from(new Set([...state.favorites, id]));
    writeUserStorage(KEYS.favorites, state.favorites);
    searchRecipes(); displayFavoritesPage(); renderAccountPage(); displayRecipeDetailsIfOpen(id);
    showToast("Recipe added to Favorites", "success", { saveToHistory: true, actionName: "View Favorites", actionTarget: "favorites" });
  }

  /* Remove one recipe id from the active mode's favorites storage. */
  function removeFavorite(id) {
    if (!requireAccount("save your favorites")) return;
    if (!isRecipeFavorite(id)) {
      showToast("Recipe not found", "error");
      return;
    }
    state.favorites = state.favorites.filter((item) => item !== id);
    writeUserStorage(KEYS.favorites, state.favorites);
    searchRecipes(); displayFavoritesPage(); renderAccountPage(); displayRecipeDetailsIfOpen(id);
    showToast("Recipe removed from Favorites", "success", { saveToHistory: true, actionName: "View Favorites", actionTarget: "favorites" });
  }

  /* Read only the current registered user's saved favorites. */
  function loadFavorites() {
    const saved = readUserStorage(KEYS.favorites, []);
    return Array.isArray(saved) ? Array.from(new Set(saved)) : [];
  }

  function isRecipeFavorite(recipeId) {
    return state.favorites.includes(recipeId);
  }

  /* Clear the ingredient search input and restore the full recipe list. */
  function clearRecipeSearch() {
    $("#recipeSearch").value = "";
    $("#recipeMaxTimeFilter").setCustomValidity("");
    state.foodRescueRankingRequest = null;
    state.foodRescueRankingResults = [];
    searchRecipes();
    showToast("Filters reset", "info");
  }

  function renderFavorites() {
    displayFavoritesPage();
  }

  function displayFavoritesPage() {
    const recipes = state.recipes.map(normalizeRecipe).filter((recipe) => isRecipeFavorite(recipe.id));
    const notice = state.guestMode ? guestNotice("Guest Favorites", "Create an account or log in to save favorite recipes permanently.") : "";
    $("#favoriteResults").innerHTML = notice + (recipes.length ? recipes.map(favoriteRecipeCard).join("") : emptyState("No favorite recipes yet.", "Save recipes from AI Recipe Finder.", "AI Recipe Finder", "recipes"));
    displayFinderFavorites();
  }

  function favoriteRecipeCard(recipe) {
    const warnings = getRecipeAllergies(recipe);
    const nutritionTags = buildRecipeNutritionTags(recipe);
    return `<article class="favorite-recipe-card">
      <div class="favorite-recipe-image"><span>${escapeHtml(recipe.imagePlaceholder || recipe.name)}</span></div>
      <div class="favorite-recipe-body">
        <div class="recipe-meta"><span>${escapeHtml(recipe.category)}</span><span>${escapeHtml(recipe.cuisine)}</span><span>◷ ${escapeHtml(recipe.cookingTime)} min</span><span>${escapeHtml(recipe.difficulty)}</span><span>${formatRecipeNutritionValue(recipe.calories, "calories")}</span><span>${formatRecipeNutritionValue(recipe.protein, "g")} protein</span></div>
        <h3>${escapeHtml(recipe.name)}</h3>
        ${renderRecipeCardCostSummary(recipe, { cardContext: RECIPE_CARD_CONTEXTS.STANDALONE_RECIPE, selectedServings: recipe.servings || 1 })}
        ${nutritionTags.length ? `<div class="recipe-nutrition-tags">${nutritionTags.map((tag) => `<span>${escapeHtml(tag)}</span>`).join("")}</div>` : ""}
        <div class="ingredient-block"><b>Ingredients</b><div class="ingredient-tags">${recipe.ingredients.map(ingredientTag).join("")}</div></div>
        <div class="allergy-warning"><b>Allergy warnings:</b> ${warnings.map(escapeHtml).join(", ")}</div>
        <div class="favorite-card-actions">
          <button class="button primary small" data-recipe-details="${recipe.id}">View Cooking Steps</button>
          <button class="button secondary small" type="button" data-offline-download="${recipe.id}">Download Offline</button>
          <button class="button secondary small remove-favorite-card-button" data-remove-favorite="${recipe.id}">Remove Favorite</button>
        </div>
      </div>
    </article>`;
  }

  function openFavoriteRecipeModal(recipeId) {
    const recipe = state.recipes.map(normalizeRecipe).find((item) => item.id === recipeId);
    if (!recipe) {
      showToast("Recipe not found", "error");
      return;
    }
    $("#favoriteRecipeModalContent").innerHTML = `<div class="favorite-modal-heading"><span class="rule-badge">Cooking steps</span><h2 id="favoriteRecipeModalTitle">${escapeHtml(recipe.name)}</h2></div><ol class="favorite-steps-list">${recipe.steps.map((step) => `<li>${escapeHtml(step)}</li>`).join("")}</ol>`;
    $("#favoriteRecipeModal").classList.remove("hidden");
    $("#favoriteRecipeModal").setAttribute("aria-hidden", "false");
  }

  function closeFavoriteRecipeModal() {
    const modal = $("#favoriteRecipeModal");
    if (!modal || modal.classList.contains("hidden")) return;
    modal.classList.add("hidden");
    modal.setAttribute("aria-hidden", "true");
    $("#favoriteRecipeModalContent").innerHTML = "";
  }

  function displayFinderFavorites() {
    const target = $("#recipeFinderFavorites");
    if (!target) return;
    const recipes = state.recipes.map(normalizeRecipe).filter((recipe) => state.favorites.includes(recipe.id)).map((recipe) => calculateRecipeMatch(parseIngredientInput($("#recipeSearch").value), recipe));
    target.innerHTML = recipes.length ? recipes.map((recipe) => recipeCard(recipe, true)).join("") : emptyState("No favorites saved yet", "Select the heart on a recipe to save it.");
  }

  function getPreparedLeftoverBatches(pantryItems = state.pantry) {
    return (Array.isArray(pantryItems) ? pantryItems : []).map(normalizePantryItem).filter(isPreparedLeftoverItem);
  }

  function getPreparedLeftoverBatchById(leftoverBatchId) {
    return getPreparedLeftoverBatches().find((item) => item.id === leftoverBatchId || item.leftoverBatch?.id === leftoverBatchId) || null;
  }

  function createLeftoverBatchId(mealId, batchIndex = 0) {
    return `leftover::${String(mealId || "meal").replace(/[^a-z0-9:-]/gi, "-").toLowerCase()}::v${COOK_TONIGHT_COMPLETION_VERSION}::${batchIndex}`;
  }

  function createPreparedLeftoverInventoryItem({ entry, actual, servings, storageLocation, storageContainer, preservationState, batchIndex, now }) {
    const recipe = findRecipeById(entry.recipeId);
    const sourceMealId = entry.mealId || entry.cookTonightWorkflowId || `meal-${batchIndex}`;
    const id = createLeftoverBatchId(sourceMealId, batchIndex);
    const quantity = normalizePantryQuantityValue(servings, { positive: true });
    if (!quantity) return null;
    const cookedAt = entry.cookingStartedAt || actual.completedAt || now;
    const storageStartedAt = actual.leftoverStorageStartedAt || now;
    const displayName = `Cooked ${entry.recipeName || recipe?.name || "leftover"}`;
    const storage = {
      location: storageLocation || PANTRY_STORAGE_LOCATIONS.REFRIGERATOR,
      locationNote: null,
      container: storageContainer || PANTRY_STORAGE_CONTAINERS.AIRTIGHT_CONTAINER,
      packageState: PANTRY_PACKAGE_STATES.NOT_APPLICABLE,
      storedAt: storageStartedAt,
      currentStorageStartedAt: storageStartedAt,
      continuousStorageStatus: CONTINUOUS_STORAGE_STATUSES.CONFIRMED,
      temperatureCondition: STORAGE_TEMPERATURE_STATUSES.UNKNOWN
    };
    const preservation = {
      state: preservationState || PANTRY_PRESERVATION_STATES.NOT_FROZEN,
      frozenAt: preservationState === PANTRY_PRESERVATION_STATES.FROZEN ? storageStartedAt : null,
      thawedAt: null,
      freezeThawCycleCount: preservationState === PANTRY_PRESERVATION_STATES.FROZEN ? 1 : 0
    };
    const item = {
      schemaVersion: PANTRY_ITEM_SCHEMA_VERSION,
      itemKind: FOOD_INVENTORY_ITEM_KINDS.PREPARED_LEFTOVER,
      id,
      ingredientId: null,
      displayName,
      name: displayName,
      originalLabel: displayName,
      identityStatus: "prepared-leftover",
      identity: {
        preparedFoodId: `prepared-food::${normalizeIngredient(entry.recipeName || recipe?.name || "leftover")}`,
        displayName,
        form: PANTRY_ITEM_FORMS.PREPARED,
        category: "leftover-cooked-dish",
        identityStatus: "prepared-leftover",
        originalUserLabel: entry.recipeName || recipe?.name || "leftover"
      },
      form: PANTRY_ITEM_FORMS.PREPARED,
      category: "leftover-cooked-dish",
      quantity,
      unit: "serving",
      quantityDetails: {
        status: PANTRY_QUANTITY_STATUSES.KNOWN,
        currentQuantity: quantity,
        originalQuantity: quantity,
        unit: "serving",
        quantitySource: "confirmed-at-meal-completion",
        updatedAt: now
      },
      servings: {
        status: PANTRY_QUANTITY_STATUSES.KNOWN,
        currentServings: quantity,
        originalServings: quantity,
        servingSizeQuantity: 1,
        servingSizeUnit: "serving",
        conversionStatus: LEFTOVER_CONVERSION_STATUSES.CONFIRMED,
        derivation: "confirmed-at-meal-completion"
      },
      source: {
        sourceMealId,
        sourcePlanId: entry.foodRescuePlan?.workflowId || entry.cookTonightWorkflowId || null,
        originalRecipeId: entry.recipeId || null,
        originalRecipeVariantId: entry.foodRescuePlan?.portionPreview?.recipeVariantId || null,
        preparationMethodId: entry.foodRescuePlan?.portionPreview?.preparationMethodId || null,
        completionVersion: COOK_TONIGHT_COMPLETION_VERSION,
        completedAt: actual.completedAt || now
      },
      preparation: {
        originalCookedAt: cookedAt,
        transformedAt: null,
        lastReheatedAt: null
      },
      storage,
      preservation,
      lifecycle: { status: PANTRY_LIFECYCLE_STATUSES.AVAILABLE, closedAt: null, closureReason: null },
      lineage: { rootMealIds: [sourceMealId], parentLeftoverBatchIds: [], transformationDepth: 0 },
      safetyPolicySnapshot: { policyId: "health-canada::leftover-cooked-dish::refrigerator", policyVersion: FOOD_SAFETY_POLICY_SCHEMA_VERSION },
      reservations: [],
      dateIntelligenceVersion: FOOD_DATE_INTELLIGENCE_VERSION,
      dateRecords: [createFoodDateRecord({ pantryItemId: id, dateValue: toIsoDate(new Date(cookedAt)), dateType: FOOD_DATE_TYPES.COOKED_ON, source: FOOD_DATE_SOURCES.USER_RECORDED_EVENT, confirmationStatus: FOOD_DATE_CONFIRMATION_STATUSES.CONFIRMED })],
      metadata: { source: "meal-completion", createdAt: now, updatedAt: now },
      createdAt: now,
      updatedAt: now,
      revision: 1
    };
    return normalizePantryItem({ ...item, leftoverBatch: normalizePreparedLeftoverBatch(item, item) });
  }

  function createLeftoverCreationEvents(batch, { entry, now, idempotencyKey }) {
    return [
      buildFoodEventForPantryCommand({
        commandType: FOOD_EVENT_TYPES.LEFTOVER_BATCH_CREATED,
        pantryItemId: batch.id,
        beforeItem: null,
        afterItem: batch,
        source: { sourceType: FOOD_EVENT_SOURCE_TYPES.LEFTOVER_WORKFLOW, planId: entry.cookTonightWorkflowId || entry.foodRescuePlan?.workflowId || null, mealId: entry.mealId, recipeId: entry.recipeId, leftoverBatchId: batch.id },
        idempotencyKey,
        payload: { occurredAt: now, affectsOnHandQuantity: true, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.INCREASE, amount: batch.quantityDetails.currentQuantity, unit: batch.quantityDetails.unit, quantityBefore: 0, quantityAfter: batch.quantityDetails.currentQuantity, note: "Actual prepared leftover batch created after meal completion confirmation." }
      }),
      buildFoodEventForPantryCommand({
        commandType: FOOD_EVENT_TYPES.ADDED_TO_LEFTOVER_BATCH,
        pantryItemId: batch.id,
        beforeItem: null,
        afterItem: batch,
        source: { sourceType: FOOD_EVENT_SOURCE_TYPES.LEFTOVER_WORKFLOW, planId: entry.cookTonightWorkflowId || entry.foodRescuePlan?.workflowId || null, mealId: entry.mealId, recipeId: entry.recipeId, leftoverBatchId: batch.id },
        idempotencyKey: `${idempotencyKey}:legacy-added`,
        payload: { occurredAt: now, affectsOnHandQuantity: false, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.NONE, amount: batch.quantityDetails.currentQuantity, unit: batch.quantityDetails.unit, note: "Compatibility event for leftover-batch history. Quantity source is the Pantry batch snapshot." }
      })
    ];
  }

  function formatLeftoverServings(item) {
    const batch = normalizePantryItem(item).leftoverBatch;
    if (!batch || batch.servings.status === PANTRY_QUANTITY_STATUSES.UNKNOWN) return "Servings need confirmation";
    return `Approximately ${formatQuantityForDisplay(batch.servings.currentServings)} ${pluralize(batch.servings.currentServings, "serving")}`;
  }

  function renderLeftoverBatchDetails(item, guardrail) {
    if (!isPreparedLeftoverItem(item)) return "";
    const batch = item.leftoverBatch || normalizePreparedLeftoverBatch(item.leftoverBatch || item, item);
    const recipe = findRecipeById(batch.source.originalRecipeId);
    const sourceMeal = batch.source.sourceMealId ? `Meal ${batch.source.sourceMealId}` : "Source meal needs review";
    const timeline = guardrail?.leftoverTimeline || deriveLeftoverTimeline({ leftoverBatch: item, foodSafetyPolicy: getFoodSafetyCatalogueRecordByPolicyId(guardrail?.policyId) || findFoodSafetyPolicyForPantryItem(item) });
    const reheatCount = timeline.reheatCount;
    const freezeButton = timeline.canRecommendFreezing && guardrail?.canRecommendFreezing ? `<button class="button secondary small" type="button" data-leftover-freeze="${escapeHtml(item.id)}" aria-label="Review freeze options for ${escapeHtml(item.displayName)}">Freeze Options</button>` : "";
    return `<section class="leftover-batch-details" aria-label="Prepared leftover details">
      <div class="leftover-batch-label"><span>Prepared leftover</span><strong>${escapeHtml(formatLeftoverServings(item))}</strong></div>
      <div class="pantry-details pantry-schema-details">
        <span><b>Source meal</b>${escapeHtml(sourceMeal)}</span>
        <span><b>Original recipe</b>${escapeHtml(recipe?.name || item.source?.originalRecipeId || "Recipe needs review")}</span>
        <span><b>Cooked</b>${batch.preparation.originalCookedAt ? escapeHtml(formatFoodEventTime(batch.preparation.originalCookedAt)) : "Needs review"}</span>
        <span><b>Current dish prepared</b>${timeline.currentPreparedAt ? escapeHtml(formatFoodEventTime(timeline.currentPreparedAt)) : "Needs review"}</span>
        <span><b>Storage started</b>${batch.storage.currentStorageStartedAt ? escapeHtml(formatFoodEventTime(batch.storage.currentStorageStartedAt)) : "Needs review"}</span>
        <span><b>Preservation</b>${escapeHtml(pantryLabelFor(batch.preservation.state, { "not-frozen": "Not frozen", frozen: "Frozen", thawed: "Thawed", unknown: "Needs review" }))}</span>
        <span><b>Reheated</b>${escapeHtml(String(reheatCount))} ${escapeHtml(pluralize(reheatCount, "time"))}</span>
        <span><b>Lineage</b>${escapeHtml(batch.lineage.rootMealIds.length ? `Root meal ${batch.lineage.rootMealIds.join(", ")}` : "Lineage needs review")}</span>
        <span><b>Safety</b>${escapeHtml(guardrail?.decisionLabel || "Review storage")}</span>
      </div>
      <div class="leftover-batch-actions">
        <button class="button primary small" type="button" data-leftover-transform="${escapeHtml(item.id)}" aria-label="Transform ${escapeHtml(item.displayName)} into another recipe">Transform This Leftover</button>
        <button class="button secondary small" type="button" data-use-first-panel-search="${escapeHtml(getRescueSourceId(RESCUE_SOURCE_TYPES.PREPARED_LEFTOVER, item.id))}" aria-label="Find recipes using ${escapeHtml(item.displayName)}">Find Recipes</button>
        <button class="button secondary small" type="button" data-leftover-consume="${escapeHtml(item.id)}" aria-label="Record consumption from ${escapeHtml(item.displayName)}">Record Consumption</button>
        ${freezeButton}
        ${item.preservation?.state === PANTRY_PRESERVATION_STATES.FROZEN ? `<button class="button secondary small" type="button" data-leftover-thaw="${escapeHtml(item.id)}" aria-label="Record thawing for ${escapeHtml(item.displayName)}">Record Thaw</button>` : ""}
        <button class="button secondary small" type="button" data-leftover-share="${escapeHtml(item.id)}" aria-label="Record sharing from ${escapeHtml(item.displayName)}">Share</button>
        <button class="button danger small" type="button" data-leftover-discard="${escapeHtml(item.id)}" aria-label="Record discard from ${escapeHtml(item.displayName)}">Discard</button>
        <button class="button secondary small" type="button" data-leftover-correct="${escapeHtml(item.id)}" aria-label="Correct quantity or timeline record for ${escapeHtml(item.displayName)}">Correct Timeline Record</button>
      </div>
      ${renderOriginalLeftoverTimelineSummary(item, guardrail)}
      ${item.quantityDetails.status === PANTRY_QUANTITY_STATUSES.UNKNOWN ? `<p class="pantry-date-warning">Leftover amount needs confirmation. Record an amount before reserving or using this batch in recipes.</p>` : ""}
    </section>`;
  }

  function setPantryFilter(filter) {
    state.pantryFilter = ["all", "ingredients", "leftovers"].includes(filter) ? filter : "all";
    if (state.pantrySection === "items") {
      const nextHash = buildPantryHash("items", state.pantryFilter === "all" ? "" : `type=${encodeURIComponent(state.pantryFilter)}`);
      if (location.hash !== nextHash) {
        history.replaceState(null, "", nextHash);
        recordInternalNavigation(nextHash, "replace");
      }
    }
    displayPantry();
    announcePolite(`${state.pantryFilter === "leftovers" ? "Leftovers" : state.pantryFilter === "ingredients" ? "Ingredients" : "All Pantry"} filter selected.`);
  }

  function getLeftoverActionConfig(action) {
    return {
      consume: { title: "Record Leftover Consumption", button: "Record Consumption", eventType: FOOD_EVENT_TYPES.LEFTOVER_QUANTITY_CONSUMED, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.DECREASE, closureReason: "consumed" },
      share: { title: "Record Shared Leftover", button: "Record Sharing", eventType: FOOD_EVENT_TYPES.DONATED_SHARED, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.DECREASE, closureReason: "shared" },
      discard: { title: "Record Discarded Leftover", button: "Record Discard", eventType: FOOD_EVENT_TYPES.DISCARDED, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.DECREASE, closureReason: "discarded" },
      freeze: { title: "Freeze Leftover", button: "Record Freeze", eventType: FOOD_EVENT_TYPES.LEFTOVER_BATCH_SPLIT, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.DECREASE, closureReason: "split-frozen" },
      correct: { title: "Correct Leftover Amount", button: "Correct Amount", eventType: FOOD_EVENT_TYPES.LEFTOVER_QUANTITY_CORRECTED, direction: FOOD_EVENT_QUANTITY_DIRECTIONS.CORRECT, closureReason: null }
    }[action] || null;
  }

  function openLeftoverQuantityAction(leftoverBatchId, action) {
    const item = getPreparedLeftoverBatchById(leftoverBatchId);
    const config = getLeftoverActionConfig(action);
    if (!item || !config) return showToast("Leftover batch needs review.", "warning");
    const available = deriveAvailableQuantity(item);
    const max = available === null ? "" : available;
    renderMealPlanGenerationModal(`<section class="leftover-action-modal" aria-labelledby="leftoverActionTitle">
      <div class="meal-generation-heading"><span class="eyebrow">LEFTOVER INVENTORY</span><h2 id="leftoverActionTitle">${escapeHtml(config.title)}</h2><p>${escapeHtml(item.displayName)}</p></div>
      <p>${escapeHtml(formatPantryQuantityDetails(item))}. ${escapeHtml(formatLeftoverServings(item))}.</p>
      <label>Amount<input type="number" min="0" ${max !== "" ? `max="${escapeHtml(String(max))}"` : ""} step="0.001" value="${escapeHtml(String(action === "correct" ? item.quantityDetails.currentQuantity || "" : max || ""))}" data-leftover-action-amount></label>
      <label>Unit<input type="text" value="${escapeHtml(item.quantityDetails.unit || "serving")}" data-leftover-action-unit readonly></label>
      ${action === "freeze" ? `<label>Frozen storage container<select data-leftover-freeze-container><option value="${PANTRY_STORAGE_CONTAINERS.FREEZER_BAG}">Freezer bag</option><option value="${PANTRY_STORAGE_CONTAINERS.AIRTIGHT_CONTAINER}">Airtight container</option></select></label>` : ""}
      <p class="form-error" id="leftoverActionError" role="alert"></p>
      <div class="meal-generation-actions"><button class="button primary" type="button" data-leftover-action-submit="${escapeHtml(item.id)}" data-leftover-action="${escapeHtml(action)}">${escapeHtml(config.button)}</button><button class="button secondary" type="button" data-cancel-generated-plan>Cancel</button></div>
    </section>`);
  }

  function submitLeftoverQuantityAction(leftoverBatchId) {
    const action = $("[data-leftover-action-submit]")?.dataset.leftoverAction;
    const amount = normalizePantryQuantityValue($("[data-leftover-action-amount]")?.value, { positive: true });
    if (!amount) {
      const error = $("#leftoverActionError");
      if (error) error.textContent = "Enter a positive leftover amount.";
      return;
    }
    const config = getLeftoverActionConfig(action);
    const item = getPreparedLeftoverBatchById(leftoverBatchId);
    if (!item || !config) return showToast("Leftover batch needs review.", "warning");
    if (action === "freeze") return openFreezerRecordingWorkflow({ inventoryItemId: leftoverBatchId, inventoryItemKind: RESCUE_SOURCE_TYPES.PREPARED_LEFTOVER, sourceWorkflow: FREEZER_RECORDING_SOURCES.PANTRY_ACTION, proposedFrozenQuantity: { quantity: amount, unit: item.quantityDetails?.unit || "serving" } });
    return updateLeftoverBatchQuantity({ leftoverBatchId, action, amount, eventType: config.eventType, direction: config.direction, closureReason: config.closureReason });
  }

  function discardFoodTypeLabel(value) {
    return pantryLabelFor(value, { ingredient: "Ingredient", "leftover-meal": "Leftover meal", "prepared-food": "Prepared food", "packaged-food": "Packaged food" });
  }

  function discardReasonLabel(value) {
    return pantryLabelFor(value, { "spoiled-before-use": "Spoiled before use", "forgot-it-was-available": "Forgot it was available", "bought-too-much": "Bought too much", "cooked-too-much": "Cooked too much", "did-not-like-it": "Did not like it", "plans-changed": "Plans changed", "stored-incorrectly": "Stored incorrectly", "date-was-unclear": "Date was unclear", "unsafe-temperature-or-storage": "Unsafe temperature or storage", "recipe-did-not-work": "Recipe did not work", other: "Other", unknown: "I am not sure", "prefer-not-to-say": "Prefer not to say", "not-recorded": "Not recorded" });
  }

  function discardAmountModeLabel(value) {
    return pantryLabelFor(value, { numeric: "Entered amount", "small-amount": "A small amount", "about-one-quarter": "About one-quarter", "about-half": "About half", most: "Most of it", all: "All of it", unknown: "I am not sure" });
  }

  function discardEstimateBasisLabel(value) {
    return pantryLabelFor(value, { "current-recorded-quantity": "Current recorded quantity", "original-package-quantity": "Original package quantity", "user-entered-package-quantity": "User-entered package quantity", "confirmed-serving-conversion": "Confirmed serving conversion", "whole-item-count": "Whole item count", "no-numeric-basis": "No numeric basis" });
  }

  function quantityConfidenceLabel(value) {
    return pantryLabelFor(value, { measured: "Measured", "user-estimated": "Estimated", "qualitative-derived": "Estimated", "serving-derived": "Derived from serving count", unknown: "Amount unknown" });
  }

  function getDiscardFoodTypeForItem(item) {
    if (!item) return DISCARDED_FOOD_TYPES.INGREDIENT;
    if (isPreparedLeftoverItem(item)) return DISCARDED_FOOD_TYPES.LEFTOVER_MEAL;
    if ([PANTRY_ITEM_FORMS.COOKED, PANTRY_ITEM_FORMS.PREPARED].includes(item.form)) return DISCARDED_FOOD_TYPES.PREPARED_FOOD;
    if ([PANTRY_PACKAGE_STATES.UNOPENED, PANTRY_PACKAGE_STATES.OPENED, PANTRY_PACKAGE_STATES.RESEALED].includes(item.storage?.packageState)) return DISCARDED_FOOD_TYPES.PACKAGED_FOOD;
    return DISCARDED_FOOD_TYPES.INGREDIENT;
  }

  function formatPackageStateLabel(item) {
    return pantryLabelFor(item?.storage?.packageState, { unopened: "Unopened package", opened: "Opened package", resealed: "Resealed package", "not-applicable": "No package state", unknown: "Package state not recorded" });
  }

  function formatStorageLocationLabel(item) {
    return pantryLabelFor(item?.storage?.location, { pantry: "Pantry", refrigerator: "Refrigerator", freezer: "Freezer", counter: "Counter", "cellar-cool-storage": "Cool storage", other: item?.storage?.locationNote || "Other storage", unknown: "Storage not recorded" });
  }

  function getPrimaryDateLabelForItem(item) {
    const date = deriveFoodDateIntelligence({ pantryItem: item });
    return date.primaryDate ? `${foodDateTypeLabel(date.primaryDateType)} ${formatDate(date.primaryDate)}` : "Date not recorded";
  }

  function formatOriginalPackageLabel(snapshot = null) {
    const original = snapshot?.originalPackage;
    if (original?.quantity && original.unit && original.status === "confirmed") return `${formatQuantityForDisplay(original.quantity)} ${original.unit}`;
    if (original?.status === "estimated") return "Estimated";
    return "Not recorded";
  }

  function buildPantryLinkedDiscardContext(item, source = {}) {
    if (!item) return null;
    return {
      pantryLinkedDiscardContextVersion: PANTRY_LINKED_DISCARD_CONTEXT_VERSION,
      sourceWorkflow: "waste-diary-pantry-link",
      inventoryItemId: item.id,
      inventoryItemKind: item.itemKind,
      canonicalIngredientId: item.ingredientId || null,
      sourceMealId: source.sourceMealId || item.leftoverBatch?.source?.sourceMealId || null,
      sourcePlanId: source.sourcePlanId || null,
      reservationIds: (item.reservations || []).filter((reservation) => reservation.status === PANTRY_RESERVATION_STATUSES.ACTIVE).map((reservation) => reservation.reservationId),
      userScopeId: getActiveUserScopeId()
    };
  }

  function buildDiscardInventorySnapshot(item) {
    const q = item?.quantityDetails || {};
    const currentQuantity = q.status === PANTRY_QUANTITY_STATUSES.UNKNOWN ? null : Number(q.currentQuantity);
    const activeReservedQuantity = item ? deriveReservedQuantity(item) : 0;
    const unreservedQuantity = currentQuantity === null ? null : Math.max(0, roundFoodRescueNumber(currentQuantity - activeReservedQuantity));
    const packageQuantity = normalizePantryQuantityValue(item?.purchase?.packageQuantity || q.originalQuantity);
    const packageUnit = item?.purchase?.packageUnit || q.unit || item?.unit || "";
    return {
      inventorySnapshotVersion: DISCARD_INVENTORY_SNAPSHOT_VERSION,
      inventoryItemId: item?.id || null,
      inventoryRevision: Number(item?.revision || 0),
      canonicalQuantityBasis: item ? getFreezerRecordingQuantityBasis(item) : "unknown",
      currentQuantity,
      unit: q.unit || item?.unit || "",
      activeReservedQuantity,
      unreservedQuantity,
      availableQuantity: unreservedQuantity,
      originalPackage: { quantity: packageQuantity, unit: packageUnit, status: packageQuantity && packageUnit ? "confirmed" : "not-recorded" },
      purchasePrice: { amountCents: item?.purchase?.pricePaidCents || null, currency: BUDGET_RESCUE_CURRENCY, source: item?.purchase?.pricePaidCents ? "user-recorded-price" : "not-recorded" },
      storage: { location: item?.storage?.location || PANTRY_STORAGE_LOCATIONS.UNKNOWN, packageState: item?.storage?.packageState || PANTRY_PACKAGE_STATES.UNKNOWN, containerLabel: item?.storage?.containerLabel || null },
      lifecycle: { status: item?.lifecycle?.status || PANTRY_LIFECYCLE_STATUSES.UNKNOWN },
      reservationRevision: (item?.reservations || []).map((reservation) => `${reservation.reservationId}:${reservation.status}:${reservation.quantity}:${reservation.unit}:${reservation.updatedAt || ""}`).join("|")
    };
  }

  function buildDiscardQuickSuggestionModel(draft) {
    const snapshot = draft?.linkedInventorySnapshot || draft?.inventorySnapshot;
    const current = snapshot?.currentQuantity;
    const reserved = Number(snapshot?.activeReservedQuantity || 0);
    const basisQuantity = Number.isFinite(Number(snapshot?.unreservedQuantity ?? snapshot?.availableQuantity)) ? Number(snapshot.unreservedQuantity ?? snapshot.availableQuantity) : current;
    const unit = snapshot?.unit || "";
    const suggestions = [];
    const seen = new Set();
    const addSuggestion = (suggestionId, amountMode, quantity, label, confidence = QUANTITY_CONFIDENCE_LEVELS.QUALITATIVE_DERIVED) => {
      const normalizedQuantity = normalizePantryQuantityValue(quantity, { positive: true });
      if (!normalizedQuantity || !unit) return;
      const key = `${normalizedQuantity}:${unit}`;
      if (seen.has(key)) return;
      seen.add(key);
      suggestions.push({ suggestionId, amountMode, quantity: normalizedQuantity, unit, label, confidence, estimateBasis: DISCARD_ESTIMATE_BASES.CURRENT_RECORDED_QUANTITY, basisQuantity, ratio: amountMode === DISCARD_AMOUNT_MODES.ALL ? 1 : QUALITATIVE_DISCARD_ESTIMATE_CONFIG[amountMode]?.pointEstimateRatio || null, quantityConfidence: confidence, estimationConfigVersion: QUALITATIVE_DISCARD_ESTIMATE_CONFIG.version });
    };
    if (snapshot?.currentQuantity === null || !Number.isFinite(Number(basisQuantity)) || basisQuantity <= 0) {
      return { suggestionModelVersion: DISCARD_QUICK_SUGGESTION_MODEL_VERSION, inventoryItemId: snapshot?.inventoryItemId || null, canonicalBasis: snapshot?.canonicalQuantityBasis || "unknown", basis: DISCARD_ESTIMATE_BASES.NO_NUMERIC_BASIS, basisQuantity: null, unit, activeReservedQuantity: reserved, suggestions: [] };
    }
    if (isWholeCountUnit(unit)) {
      const wholeChoices = [
        { suggestionId: "whole-quarter", amountMode: DISCARD_AMOUNT_MODES.ABOUT_ONE_QUARTER, quantity: Math.max(1, Math.floor(basisQuantity * 0.25)) },
        { suggestionId: "whole-half-low", amountMode: DISCARD_AMOUNT_MODES.ABOUT_HALF, quantity: Math.max(1, Math.floor(basisQuantity * 0.5)) },
        { suggestionId: "whole-half-high", amountMode: DISCARD_AMOUNT_MODES.ABOUT_HALF, quantity: Math.min(Math.ceil(basisQuantity * 0.5), Math.max(1, Math.floor(basisQuantity))) }
      ];
      wholeChoices.filter((choice) => choice.quantity > 0 && choice.quantity < basisQuantity).forEach((choice) => addSuggestion(choice.suggestionId, choice.amountMode, choice.quantity, `${formatQuantityForDisplay(choice.quantity)} ${pluralize(choice.quantity, unit)}`));
      addSuggestion("all", DISCARD_AMOUNT_MODES.ALL, basisQuantity, `All ${formatQuantityForDisplay(basisQuantity)} ${unit}`, QUANTITY_CONFIDENCE_LEVELS.USER_ESTIMATED);
    } else {
      addSuggestion("quarter", DISCARD_AMOUNT_MODES.ABOUT_ONE_QUARTER, basisQuantity * QUALITATIVE_DISCARD_ESTIMATE_CONFIG[DISCARD_AMOUNT_MODES.ABOUT_ONE_QUARTER].pointEstimateRatio, `Approximately ${formatQuantityForDisplay(basisQuantity * 0.25)} ${unit}`);
      addSuggestion("half", DISCARD_AMOUNT_MODES.ABOUT_HALF, basisQuantity * QUALITATIVE_DISCARD_ESTIMATE_CONFIG[DISCARD_AMOUNT_MODES.ABOUT_HALF].pointEstimateRatio, `Approximately ${formatQuantityForDisplay(basisQuantity * 0.5)} ${unit}`);
      addSuggestion("all", DISCARD_AMOUNT_MODES.ALL, basisQuantity, `All ${formatQuantityForDisplay(basisQuantity)} ${unit}`, QUANTITY_CONFIDENCE_LEVELS.USER_ESTIMATED);
    }
    return { suggestionModelVersion: DISCARD_QUICK_SUGGESTION_MODEL_VERSION, inventoryItemId: snapshot?.inventoryItemId || null, canonicalBasis: snapshot?.canonicalQuantityBasis || "unknown", basis: DISCARD_ESTIMATE_BASES.CURRENT_RECORDED_QUANTITY, basisQuantity, unit, activeReservedQuantity: reserved, suggestions };
  }

  function getDiscardSuggestionById(draft, suggestionId) {
    return buildDiscardQuickSuggestionModel(draft).suggestions.find((suggestion) => suggestion.suggestionId === suggestionId) || null;
  }

  function resolveQuantityDimension(unit) {
    const normalized = normalizePantryUnit(unit) || String(unit || "").trim().toLowerCase();
    if (normalized === "serving" || normalized === "servings") return { dimension: QUANTITY_DIMENSIONS.SERVINGS, unit: "serving", baseUnit: "serving", factor: 1, source: "serving-unit" };
    const comparable = typeof COST_ENGINE.normalizeComparableQuantity === "function" ? COST_ENGINE.normalizeComparableQuantity(1, normalized) : null;
    if (comparable?.valid) {
      if (comparable.dimension === "mass") return { dimension: QUANTITY_DIMENSIONS.MASS, unit: normalized, baseUnit: "g", factor: comparable.quantity, source: "existing-unit-registry" };
      if (comparable.dimension === "volume") return { dimension: QUANTITY_DIMENSIONS.VOLUME, unit: normalized, baseUnit: "ml", factor: comparable.quantity, source: "existing-unit-registry" };
      if (String(comparable.dimension || "").startsWith("count")) return { dimension: QUANTITY_DIMENSIONS.COUNT, unit: normalized, baseUnit: comparable.unit || normalized, factor: comparable.quantity || 1, source: "existing-unit-registry" };
    }
    return { dimension: null, unit: normalized, baseUnit: null, factor: null, source: "unsupported-unit" };
  }

  function weightConfidenceLabel(value) {
    return pantryLabelFor(value, { measured: "Measured weight", "exact-unit-conversion": "Exact unit conversion", "validated-package-estimate": "Validated package estimate", "validated-serving-estimate": "Validated serving estimate", "validated-average-weight-estimate": "Validated average-weight estimate", "validated-density-estimate": "Validated density estimate", "user-estimate": "User estimate", "low-confidence": "Low-confidence estimate", unavailable: "Weight unavailable" });
  }

  function stableDiscardWeightSnapshotHash(value) {
    const text = JSON.stringify(value || {});
    let hash = 0;
    for (let index = 0; index < text.length; index += 1) hash = ((hash << 5) - hash + text.charCodeAt(index)) | 0;
    return `discard-weight-${Math.abs(hash).toString(36)}`;
  }

  function formatWeightGrams(grams, approximate = true) {
    const value = Number(grams);
    if (!Number.isFinite(value) || value <= 0) return "Unavailable";
    const rounded = roundFoodRescueNumber(value);
    const display = rounded >= 1000 ? `${formatQuantityForDisplay(roundFoodRescueNumber(rounded / 1000))} kg` : `${formatQuantityForDisplay(rounded)} g`;
    return `${approximate ? "Approximately " : ""}${display}`.trim();
  }

  function buildDiscardedWeightRequest(estimate, context = {}) {
    const point = normalizePantryQuantityValue(estimate?.canonicalQuantity, { positive: true });
    const unit = String(estimate?.unit || "").trim();
    const dimension = resolveQuantityDimension(unit);
    return {
      discardedWeightRequestVersion: DISCARDED_WEIGHT_REQUEST_VERSION,
      discardEventId: context.discardEventId || null,
      inventoryItemId: context.inventoryItemId || context.draft?.source?.inventoryItemId || null,
      inventoryItemKind: context.inventoryItemKind || context.draft?.pantryLinkedContext?.inventoryItemKind || null,
      subject: {
        entityType: context.entityType || (context.draft?.food?.preparedFoodId ? "prepared-food" : "ingredient"),
        entityId: context.entityId || context.draft?.food?.canonicalIngredientId || context.record?.food?.canonicalIngredientId || null,
        form: context.form || context.item?.form || context.record?.inventorySnapshot?.form || null,
        sizeClass: context.sizeClass || context.item?.identity?.sizeClass || context.record?.inventorySnapshot?.sizeClass || null
      },
      discardedQuantity: { point, minimum: normalizePantryQuantityValue(estimate?.estimateMinimum, { positive: true }) ?? point, maximum: normalizePantryQuantityValue(estimate?.estimateMaximum, { positive: true }) ?? point, unit, dimension: dimension.dimension, confidence: estimate?.quantityConfidence || QUANTITY_CONFIDENCE_LEVELS.UNKNOWN },
      packageInformation: structuredCloneSafe(context.record?.inventorySnapshot?.originalPackage || context.draft?.linkedInventorySnapshot?.originalPackage || {}),
      servingInformation: structuredCloneSafe(context.item?.leftoverBatch?.servingConversion || context.item?.servingConversion || {}),
      preparedBatchInformation: structuredCloneSafe(context.item?.leftoverBatch || {}),
      userScopeId: getActiveUserScopeId(),
      sourceRevisions: structuredCloneSafe(context.record?.sourceRevisions || context.draft?.sourceRevisions || {}),
      unitRegistryVersion: COST_ENGINE.COST_CALCULATION_VERSION || 1
    };
  }

  function buildUnavailableDiscardedWeightEstimate(request, reasonCodes = ["validated-conversion-unavailable"]) {
    return {
      discardedWeightEstimateVersion: DISCARDED_WEIGHT_ESTIMATE_VERSION,
      schemaVersion: DISCARDED_WEIGHT_ESTIMATE_VERSION,
      status: DISCARDED_WEIGHT_STATUSES.UNAVAILABLE,
      discardEventId: request?.discardEventId || null,
      pointWeightGrams: null,
      minimumWeightGrams: null,
      maximumWeightGrams: null,
      quantity: null,
      unit: "g",
      minimumEstimate: null,
      maximumEstimate: null,
      confidence: WEIGHT_ESTIMATE_CONFIDENCE.UNAVAILABLE,
      weightConfidenceModelVersion: WEIGHT_CONFIDENCE_MODEL_VERSION,
      basis: "weight-estimate-unavailable",
      reasonCodes,
      sourceQuantity: request?.discardedQuantity?.point ?? null,
      sourceUnit: request?.discardedQuantity?.unit || null,
      sourceDimension: request?.discardedQuantity?.dimension || null,
      display: { point: "WEIGHT ESTIMATE UNAVAILABLE", range: "", message: "Chef Nova recorded the discarded food but did not treat the unknown weight as 0 g." },
      source: { conversionType: null, conversionId: null, conversionVersion: null, sourceQuantity: request?.discardedQuantity?.point ?? null, sourceUnit: request?.discardedQuantity?.unit || null },
      calculation: { formula: null, unitRegistryVersion: request?.unitRegistryVersion || COST_ENGINE.COST_CALCULATION_VERSION || 1, calculationVersion: DISCARDED_WEIGHT_CALCULATION_VERSION, calculatedAt: getCurrentIsoString() },
      sourceRevisions: structuredCloneSafe(request?.sourceRevisions || {}),
      conversionSnapshotHash: stableDiscardWeightSnapshotHash({ request, reasonCodes })
    };
  }

  function findApprovedMeasurementConversionPolicy(request, type) {
    const policies = [...SHARED_MEASUREMENT_CONVERSION_POLICIES, ...((state.ingredientCatalogue?.measurementConversionPolicies || []))];
    const applicable = policies.filter((policy) => policy?.conversionType === type && [CONVERSION_REVIEW_STATUSES.APPROVED, CONVERSION_REVIEW_STATUSES.APPROVED_WITH_LIMITATIONS].includes(policy?.review?.status) && policy?.targetQuantity?.dimension === QUANTITY_DIMENSIONS.MASS && policy?.targetQuantity?.unit === "g" && policy?.subject?.entityId === request?.subject?.entityId && (!policy.subject.form || policy.subject.form === request?.subject?.form) && (!policy.subject.sizeClass || policy.subject.sizeClass === request?.subject?.sizeClass));
    if (applicable.length === 1) return applicable[0];
    if (applicable.length > 1) return { conflict: true, policies: applicable };
    return null;
  }

  function resolveValidatedMeasurementConversion(request) {
    const dimension = request?.discardedQuantity?.dimension;
    if (!dimension) return { status: DISCARDED_WEIGHT_STATUSES.UNAVAILABLE, reasonCodes: ["unsupported-unit"] };
    if (dimension === QUANTITY_DIMENSIONS.MASS) return { status: DISCARDED_WEIGHT_STATUSES.AVAILABLE, conversionType: MEASUREMENT_CONVERSION_TYPES.EXACT_UNIT, confidence: request.discardedQuantity.confidence === QUANTITY_CONFIDENCE_LEVELS.MEASURED ? WEIGHT_ESTIMATE_CONFIDENCE.MEASURED : WEIGHT_ESTIMATE_CONFIDENCE.EXACT_UNIT_CONVERSION, formula: "exact-mass-unit-conversion" };
    const packageQuantity = normalizePantryQuantityValue(request?.packageInformation?.quantity, { positive: true });
    const packageUnit = request?.packageInformation?.unit || "";
    const packageMass = packageQuantity && packageUnit ? COST_ENGINE.normalizeComparableQuantity?.(packageQuantity, packageUnit) : null;
    if (dimension === QUANTITY_DIMENSIONS.COUNT && request.discardedQuantity.unit === "package" && packageMass?.valid && packageMass.dimension === "mass") {
      return { status: DISCARDED_WEIGHT_STATUSES.AVAILABLE, conversionType: MEASUREMENT_CONVERSION_TYPES.PACKAGE_NET_WEIGHT, confidence: WEIGHT_ESTIMATE_CONFIDENCE.VALIDATED_PACKAGE_ESTIMATE, formula: "package-count-times-net-food-weight", policy: { conversionId: "inventory-package-net-weight", conversionVersion: 1, conversionType: MEASUREMENT_CONVERSION_TYPES.PACKAGE_NET_WEIGHT, estimate: { pointFactor: packageMass.quantity, minimumFactor: packageMass.quantity, maximumFactor: packageMass.quantity }, subject: request.subject, review: { status: CONVERSION_REVIEW_STATUSES.APPROVED_WITH_LIMITATIONS } } };
    }
    const servingQuantity = normalizePantryQuantityValue(request?.servingInformation?.servingSizeQuantity || request?.preparedBatchInformation?.servings?.servingSizeQuantity, { positive: true });
    const servingUnit = request?.servingInformation?.unit || request?.servingInformation?.servingSizeUnit || request?.preparedBatchInformation?.servings?.servingSizeUnit || "";
    const servingMass = servingQuantity && servingUnit ? COST_ENGINE.normalizeComparableQuantity?.(servingQuantity, servingUnit) : null;
    if (dimension === QUANTITY_DIMENSIONS.SERVINGS && servingMass?.valid && servingMass.dimension === "mass") {
      return { status: DISCARDED_WEIGHT_STATUSES.AVAILABLE, conversionType: MEASUREMENT_CONVERSION_TYPES.SERVING_WEIGHT, confidence: WEIGHT_ESTIMATE_CONFIDENCE.VALIDATED_SERVING_ESTIMATE, formula: "serving-count-times-confirmed-serving-weight", policy: { conversionId: "inventory-serving-weight", conversionVersion: 1, conversionType: MEASUREMENT_CONVERSION_TYPES.SERVING_WEIGHT, estimate: { pointFactor: servingMass.quantity, minimumFactor: servingMass.quantity, maximumFactor: servingMass.quantity }, subject: request.subject, review: { status: CONVERSION_REVIEW_STATUSES.APPROVED_WITH_LIMITATIONS } } };
    }
    const type = dimension === QUANTITY_DIMENSIONS.VOLUME ? MEASUREMENT_CONVERSION_TYPES.DENSITY : dimension === QUANTITY_DIMENSIONS.COUNT ? MEASUREMENT_CONVERSION_TYPES.AVERAGE_UNIT_WEIGHT : dimension === QUANTITY_DIMENSIONS.SERVINGS ? MEASUREMENT_CONVERSION_TYPES.SERVING_WEIGHT : null;
    const policy = type ? findApprovedMeasurementConversionPolicy(request, type) : null;
    if (policy?.conflict) return { status: DISCARDED_WEIGHT_STATUSES.NEEDS_REVIEW, reasonCodes: ["conflicting-approved-conversions"], policies: policy.policies };
    if (!policy) return { status: DISCARDED_WEIGHT_STATUSES.UNAVAILABLE, reasonCodes: [dimension === QUANTITY_DIMENSIONS.VOLUME ? "food-specific-density-unavailable" : dimension === QUANTITY_DIMENSIONS.COUNT ? "approved-average-weight-unavailable" : "confirmed-serving-weight-unavailable"] };
    return { status: DISCARDED_WEIGHT_STATUSES.AVAILABLE, conversionType: policy.conversionType, confidence: policy.conversionType === MEASUREMENT_CONVERSION_TYPES.DENSITY ? WEIGHT_ESTIMATE_CONFIDENCE.VALIDATED_DENSITY_ESTIMATE : policy.conversionType === MEASUREMENT_CONVERSION_TYPES.AVERAGE_UNIT_WEIGHT ? WEIGHT_ESTIMATE_CONFIDENCE.VALIDATED_AVERAGE_WEIGHT_ESTIMATE : WEIGHT_ESTIMATE_CONFIDENCE.VALIDATED_SERVING_ESTIMATE, formula: `${policy.conversionType}-times-source-quantity`, policy };
  }

  function buildDiscardedWeightEstimate(estimate, context = {}) {
    const request = buildDiscardedWeightRequest(estimate, context);
    const quantity = request.discardedQuantity;
    if (!quantity.point || !quantity.unit || !quantity.dimension) return buildUnavailableDiscardedWeightEstimate(request, ["quantity-or-unit-unavailable"]);
    const resolution = resolveValidatedMeasurementConversion(request);
    if (resolution.status !== DISCARDED_WEIGHT_STATUSES.AVAILABLE) return buildUnavailableDiscardedWeightEstimate(request, resolution.reasonCodes || ["validated-conversion-unavailable"]);
    const sourceNormalized = COST_ENGINE.normalizeComparableQuantity?.(quantity.point, quantity.unit);
    const minNormalized = COST_ENGINE.normalizeComparableQuantity?.(quantity.minimum ?? quantity.point, quantity.unit);
    const maxNormalized = COST_ENGINE.normalizeComparableQuantity?.(quantity.maximum ?? quantity.point, quantity.unit);
    let point = null;
    let minimum = null;
    let maximum = null;
    let factors = { pointFactor: null, minimumFactor: null, maximumFactor: null };
    if (quantity.dimension === QUANTITY_DIMENSIONS.MASS) {
      if (!sourceNormalized?.valid || sourceNormalized.dimension !== "mass") return buildUnavailableDiscardedWeightEstimate(request, ["exact-mass-conversion-unavailable"]);
      point = sourceNormalized.quantity;
      minimum = minNormalized?.valid ? minNormalized.quantity : point;
      maximum = maxNormalized?.valid ? maxNormalized.quantity : point;
    } else {
      const policy = resolution.policy;
      factors = { pointFactor: Number(policy?.estimate?.pointFactor), minimumFactor: Number(policy?.estimate?.minimumFactor ?? policy?.estimate?.pointFactor), maximumFactor: Number(policy?.estimate?.maximumFactor ?? policy?.estimate?.pointFactor) };
      if (!Number.isFinite(factors.pointFactor) || factors.pointFactor <= 0 || !Number.isFinite(factors.minimumFactor) || !Number.isFinite(factors.maximumFactor)) return buildUnavailableDiscardedWeightEstimate(request, ["validated-conversion-invalid"]);
      point = quantity.point * factors.pointFactor;
      minimum = (quantity.minimum ?? quantity.point) * factors.minimumFactor;
      maximum = (quantity.maximum ?? quantity.point) * factors.maximumFactor;
    }
    const exactMeasured = resolution.confidence === WEIGHT_ESTIMATE_CONFIDENCE.MEASURED && quantity.confidence === QUANTITY_CONFIDENCE_LEVELS.MEASURED;
    const pointRounded = roundFoodRescueNumber(point);
    const minRounded = roundFoodRescueNumber(Math.min(minimum, maximum));
    const maxRounded = roundFoodRescueNumber(Math.max(minimum, maximum));
    return {
      discardedWeightEstimateVersion: DISCARDED_WEIGHT_ESTIMATE_VERSION,
      schemaVersion: DISCARDED_WEIGHT_ESTIMATE_VERSION,
      status: DISCARDED_WEIGHT_STATUSES.AVAILABLE,
      discardEventId: request.discardEventId,
      pointWeightGrams: pointRounded,
      minimumWeightGrams: minRounded,
      maximumWeightGrams: maxRounded,
      quantity: pointRounded,
      unit: "g",
      minimumEstimate: minRounded,
      maximumEstimate: maxRounded,
      confidence: resolution.confidence,
      sourceQuantityConfidence: quantity.confidence,
      weightConfidenceModelVersion: WEIGHT_CONFIDENCE_MODEL_VERSION,
      basis: resolution.conversionType === MEASUREMENT_CONVERSION_TYPES.EXACT_UNIT ? "exact-compatible-unit-conversion" : resolution.conversionType,
      reasonCodes: [],
      sourceQuantity: quantity.point,
      sourceUnit: quantity.unit,
      sourceDimension: quantity.dimension,
      display: { point: formatWeightGrams(pointRounded, !exactMeasured), range: minRounded !== maxRounded ? `${formatWeightGrams(minRounded, true)}-${formatWeightGrams(maxRounded, false)}` : "", message: "" },
      source: { conversionType: resolution.conversionType, conversionId: resolution.policy?.conversionId || null, conversionVersion: resolution.policy?.conversionVersion || null, sourceQuantity: quantity.point, sourceUnit: quantity.unit, sourceDimension: quantity.dimension },
      calculation: { formula: resolution.formula, pointFactor: factors.pointFactor, minimumFactor: factors.minimumFactor, maximumFactor: factors.maximumFactor, unitRegistryVersion: request.unitRegistryVersion, calculationVersion: DISCARDED_WEIGHT_CALCULATION_VERSION, calculatedAt: getCurrentIsoString(), conversionResolutionVersion: MEASUREMENT_CONVERSION_RESOLUTION_VERSION },
      sourceRevisions: structuredCloneSafe(request.sourceRevisions || {}),
      conversionSnapshotHash: stableDiscardWeightSnapshotHash({ request, resolution, pointRounded, minRounded, maxRounded })
    };
  }

  function formatDiscardedWeightEstimate(weight) {
    if (!weight || weight.status !== DISCARDED_WEIGHT_STATUSES.AVAILABLE || !Number.isFinite(Number(weight.pointWeightGrams ?? weight.quantity))) return "WEIGHT ESTIMATE UNAVAILABLE";
    return weight.display?.point || formatWeightGrams(weight.pointWeightGrams ?? weight.quantity, weight.confidence !== WEIGHT_ESTIMATE_CONFIDENCE.MEASURED);
  }

  function buildDiscardRecordingContext(context = {}) {
    const item = context.inventoryItemId ? state.pantry.map(normalizePantryItem).find((candidate) => candidate.id === context.inventoryItemId) : null;
    const sourceWorkflow = Object.values(DISCARD_RECORDING_SOURCES).includes(context.sourceWorkflow) ? context.sourceWorkflow : item ? DISCARD_RECORDING_SOURCES.PANTRY_ITEM_ACTION : DISCARD_RECORDING_SOURCES.MANUAL_ENTRY;
    return {
      discardRecordingContextVersion: DISCARD_RECORDING_CONTEXT_VERSION,
      sourceWorkflow,
      inventoryItemId: item?.id || null,
      inventoryItemKind: item?.itemKind || null,
      sourceMealId: context.sourceMealId || item?.leftoverBatch?.source?.sourceMealId || null,
      sourcePlanId: context.sourcePlanId || null,
      sourceReservationIds: item ? (item.reservations || []).filter((reservation) => reservation.status === PANTRY_RESERVATION_STATUSES.ACTIVE).map((reservation) => reservation.reservationId) : [],
      userScopeId: getActiveUserScopeId()
    };
  }

  function buildDiscardRecordingDraft(context = {}) {
    const source = buildDiscardRecordingContext(context);
    const item = source.inventoryItemId ? state.pantry.map(normalizePantryItem).find((candidate) => candidate.id === source.inventoryItemId) : null;
    const q = item?.quantityDetails || {};
    const nowParts = getLocalTimeParts();
    return {
      discardRecordingDraftVersion: DISCARD_RECORDING_DRAFT_VERSION,
      draftId: `discard-recording::${source.inventoryItemId || "manual"}::${Date.now()}`,
      status: "editing",
      source,
      pantryLinkedContext: item ? buildPantryLinkedDiscardContext(item, source) : null,
      food: {
        displayName: item?.displayName || item?.name || "",
        foodType: item ? getDiscardFoodTypeForItem(item) : DISCARDED_FOOD_TYPES.INGREDIENT,
        canonicalIngredientId: item?.ingredientId || null,
        preparedFoodId: item?.identity?.preparedFoodId || item?.leftoverBatch?.id || null,
        manualEntry: !item
      },
      inventorySnapshot: item ? {
        canonicalQuantityBasis: getFreezerRecordingQuantityBasis(item),
        currentQuantity: q.status === PANTRY_QUANTITY_STATUSES.UNKNOWN ? null : Number(q.currentQuantity),
        activeReservedQuantity: deriveReservedQuantity(item),
        availableQuantity: deriveAvailableQuantity(item),
        unit: q.unit || item.unit || "",
        originalPackageQuantity: normalizePantryQuantityValue(item.purchase?.packageQuantity || q.originalQuantity),
        originalPackageUnit: item.purchase?.packageUnit || q.unit || item.unit || "",
        revision: Number(item.revision || 0),
        reservationRevision: (item.reservations || []).map((reservation) => `${reservation.reservationId}:${reservation.status}:${reservation.quantity}:${reservation.unit}:${reservation.updatedAt || ""}`).join("|")
      } : null,
      linkedInventorySnapshot: item ? buildDiscardInventorySnapshot(item) : null,
      amount: { mode: DISCARD_AMOUNT_MODES.UNKNOWN, numericQuantity: null, numericUnit: null, derivedEstimate: null, quantityConfidence: QUANTITY_CONFIDENCE_LEVELS.UNKNOWN, userConfirmedDerivedEstimate: false },
      reason: { primaryReasonCode: DISCARD_REASON_CODES.UNKNOWN, reasonSource: "user-selected", userProvidedOtherReason: null, confidence: "user-reported" },
      price: { originalPurchasePriceCents: item?.purchase?.pricePaidCents || null, currency: BUDGET_RESCUE_CURRENCY, source: item?.purchase?.pricePaidCents ? DISCARD_PRICE_SOURCES.LINKED_INVENTORY_PURCHASE_PRICE : DISCARD_PRICE_SOURCES.NONE, estimatedDiscardedValueCents: null, valueConfidence: item?.purchase?.pricePaidCents ? "estimated" : "unavailable" },
      note: null,
      discardedTime: { date: nowParts.date, time: nowParts.time, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "local", precision: DISCARD_TIMESTAMP_PRECISION.EXACT_DATE_TIME, resolvedTimestamp: resolveDiscardTimestamp(nowParts.date, nowParts.time, DISCARD_TIMESTAMP_PRECISION.EXACT_DATE_TIME) },
      sourceRevisions: { userScopeId: getActiveUserScopeId(), inventoryRevision: item?.revision || 0, quantityRevision: item?.quantityDetails?.updatedAt || item?.updatedAt || "", reservationRevision: item ? buildDiscardInventorySnapshot(item).reservationRevision : "", packageDataRevision: item?.purchase?.updatedAt || item?.updatedAt || "", priceRevision: item?.purchase?.updatedAt || item?.updatedAt || "", foodEventHistoryRevision: (state.foodEventHistory || loadFoodEventHistory()).revision || 0, planRevision: state.mealPlans?.updatedAt || "", transformationPathRevision: state.mealPlans?.leftoverPlanningVersion || "", wasteDashboardProjectionVersion: WASTE_DASHBOARD_PROJECTION_VERSION, wastePatternConfigurationVersion: WASTE_PATTERN_CONFIG.version, referenceLocalDate: getCurrentDateString(), timezone: Intl.DateTimeFormat().resolvedOptions().timeZone || "local", estimationConfigurationVersion: QUALITATIVE_DISCARD_ESTIMATE_CONFIG.version }
    };
  }

  function resolveDiscardTimestamp(date, time, precision) {
    if (!isIsoDate(date)) return null;
    if (precision === DISCARD_TIMESTAMP_PRECISION.DATE_ONLY) return `${date}T00:00:00`;
    if (!/^\d{2}:\d{2}$/.test(String(time || ""))) return null;
    const [year, month, day] = date.split("-").map(Number);
    const [hour, minute] = time.split(":").map(Number);
    const local = new Date(year, month - 1, day, hour, minute, 0, 0);
    return Number.isNaN(local.getTime()) ? null : local.toISOString();
  }

  function isWholeCountUnit(unit) {
    return ["each", "piece", "slice", "fillet", "sheet", "head", "stalk", "bunch", "can", "jar", "bottle", "package", "bag", "box", "carton"].includes(String(unit || "").toLowerCase());
  }

  function deriveDiscardEstimate(draft, values = {}) {
    const mode = values.amountMode || DISCARD_AMOUNT_MODES.UNKNOWN;
    const linked = Boolean(draft.source.inventoryItemId);
    const unit = linked ? draft.inventorySnapshot?.unit : values.unit;
    const current = linked ? draft.inventorySnapshot?.currentQuantity : null;
    const available = linked ? draft.inventorySnapshot?.availableQuantity : null;
    const numeric = normalizePantryQuantityValue(values.numericQuantity, { positive: true });
    if (mode === DISCARD_AMOUNT_MODES.NUMERIC) return { mode, canonicalQuantity: numeric, unit: normalizePantryUnit(unit) || unit || "", quantityConfidence: QUANTITY_CONFIDENCE_LEVELS.MEASURED, estimateBasis: linked ? DISCARD_ESTIMATE_BASES.CURRENT_RECORDED_QUANTITY : DISCARD_ESTIMATE_BASES.NO_NUMERIC_BASIS, estimateMinimum: numeric, estimateMaximum: numeric, ratio: current && numeric ? numeric / current : null, configurationVersion: QUALITATIVE_DISCARD_ESTIMATE_CONFIG.version };
    if (mode === DISCARD_AMOUNT_MODES.UNKNOWN) return { mode, canonicalQuantity: null, unit: unit || "", quantityConfidence: QUANTITY_CONFIDENCE_LEVELS.UNKNOWN, estimateBasis: DISCARD_ESTIMATE_BASES.NO_NUMERIC_BASIS, estimateMinimum: null, estimateMaximum: null, ratio: null, configurationVersion: QUALITATIVE_DISCARD_ESTIMATE_CONFIG.version };
    const config = QUALITATIVE_DISCARD_ESTIMATE_CONFIG[mode];
    const manualPackageQuantity = normalizePantryQuantityValue(values.packageQuantity, { positive: true });
    const linkedBasis = draft.linkedInventorySnapshot?.unreservedQuantity ?? current;
    const basisQuantity = linked && Number.isFinite(linkedBasis) && linkedBasis > 0 ? linkedBasis : manualPackageQuantity || null;
    const basis = linked && Number.isFinite(linkedBasis) && linkedBasis > 0 ? DISCARD_ESTIMATE_BASES.CURRENT_RECORDED_QUANTITY : manualPackageQuantity ? DISCARD_ESTIMATE_BASES.USER_ENTERED_PACKAGE_QUANTITY : DISCARD_ESTIMATE_BASES.NO_NUMERIC_BASIS;
    const estimateUnit = linked ? unit : values.packageUnit || unit || "";
    if (!config || !basisQuantity || !estimateUnit) return { mode, canonicalQuantity: null, unit: estimateUnit || "", quantityConfidence: QUANTITY_CONFIDENCE_LEVELS.UNKNOWN, estimateBasis: DISCARD_ESTIMATE_BASES.NO_NUMERIC_BASIS, estimateMinimum: null, estimateMaximum: null, ratio: null, configurationVersion: QUALITATIVE_DISCARD_ESTIMATE_CONFIG.version };
    if (isWholeCountUnit(estimateUnit)) {
      const point = basisQuantity * config.pointEstimateRatio;
      if (!Number.isInteger(point) && mode !== DISCARD_AMOUNT_MODES.ALL) return { mode, canonicalQuantity: null, unit: estimateUnit, quantityConfidence: QUANTITY_CONFIDENCE_LEVELS.UNKNOWN, estimateBasis: DISCARD_ESTIMATE_BASES.WHOLE_ITEM_COUNT, estimateMinimum: Math.max(1, Math.floor(point)), estimateMaximum: Math.min(Math.ceil(point), basisQuantity), ratio: config.pointEstimateRatio, configurationVersion: QUALITATIVE_DISCARD_ESTIMATE_CONFIG.version, wholeItemReviewRequired: true };
    }
    const pointEstimate = roundFoodRescueNumber(basisQuantity * config.pointEstimateRatio);
    return { mode, canonicalQuantity: pointEstimate, unit: estimateUnit, quantityConfidence: QUANTITY_CONFIDENCE_LEVELS.QUALITATIVE_DERIVED, estimateBasis: basis, estimateMinimum: roundFoodRescueNumber(basisQuantity * config.minimumRatio), estimateMaximum: roundFoodRescueNumber(basisQuantity * config.maximumRatio), ratio: config.pointEstimateRatio, configurationVersion: QUALITATIVE_DISCARD_ESTIMATE_CONFIG.version, basisQuantity, availableQuantity: available };
  }

  function formatDiscardEstimateLine(estimate) {
    if (!estimate || estimate.canonicalQuantity === null) return "Amount unknown";
    return `Approximately ${formatQuantityForDisplay(estimate.canonicalQuantity)} ${estimate.unit || ""}`.trim();
  }

  function readDiscardRecordingForm(draft) {
    const form = $("#discardRecordingForm");
    const data = form ? new FormData(form) : new FormData();
    const selectedItemId = String(data.get("discardInventoryItemId") || draft.source.inventoryItemId || "");
    const linkedItem = selectedItemId ? state.pantry.map(normalizePantryItem).find((item) => item.id === selectedItemId) : null;
    const nextDraft = selectedItemId !== (draft.source.inventoryItemId || "") ? buildDiscardRecordingDraft({ inventoryItemId: selectedItemId, sourceWorkflow: DISCARD_RECORDING_SOURCES.PANTRY_GLOBAL_ACTION }) : draft;
    const foodName = linkedItem ? linkedItem.displayName || linkedItem.name : normalizeWhitespace(data.get("discardFoodName"));
    const foodType = linkedItem ? getDiscardFoodTypeForItem(linkedItem) : normalizePantryEnum(data.get("discardFoodType"), DISCARDED_FOOD_TYPES, "");
    const values = {
      selectedItemId,
      foodName,
      foodType,
      quickSuggestionId: String(data.get("discardQuickSuggestion") || ""),
      amountMode: normalizePantryEnum(data.get("discardAmountMode"), DISCARD_AMOUNT_MODES, DISCARD_AMOUNT_MODES.UNKNOWN),
      numericQuantity: data.get("discardAmount"),
      unit: data.get("discardUnit") || nextDraft?.inventorySnapshot?.unit || "",
      packageQuantity: data.get("discardPackageQuantity"),
      packageUnit: data.get("discardPackageUnit") || data.get("discardUnit") || "",
      reasonCode: normalizePantryEnum(data.get("discardReason"), DISCARD_REASON_CODES, DISCARD_REASON_CODES.UNKNOWN),
      otherReason: normalizeWhitespace(data.get("discardOtherReason")),
      priceMode: data.get("discardPriceMode") || "none",
      priceAmount: data.get("discardPriceAmount"),
      note: normalizeWhitespace(data.get("discardNote")).slice(0, 500),
      date: String(data.get("discardDate") || "").trim(),
      time: String(data.get("discardTime") || "").trim(),
      timeUnknown: data.get("discardTimeUnknown") === "on",
      remainingKnown: data.get("discardRemainingKnown") || ""
    };
    const quick = values.quickSuggestionId ? getDiscardSuggestionById(nextDraft || draft, values.quickSuggestionId) : null;
    if (quick) {
      values.amountMode = quick.amountMode;
      values.numericQuantity = quick.quantity;
      values.unit = quick.unit;
    } else if (values.quickSuggestionId === "custom") {
      values.amountMode = DISCARD_AMOUNT_MODES.NUMERIC;
    } else if (values.quickSuggestionId === "unknown") {
      values.amountMode = DISCARD_AMOUNT_MODES.UNKNOWN;
    }
    const estimate = deriveDiscardEstimate(nextDraft || draft, values);
    if (quick) {
      estimate.suggestionId = quick.suggestionId;
      estimate.quantityConfidence = quick.quantityConfidence;
      estimate.estimateBasis = quick.estimateBasis;
      estimate.basisQuantity = quick.basisQuantity;
      estimate.ratio = quick.ratio;
    }
    return { draft: nextDraft || draft, values, estimate };
  }

  function validateDiscardRecording(draft, values, estimate) {
    const errors = [];
    if (draft.source.userScopeId !== getActiveUserScopeId()) errors.push({ selector: "[name='discardFoodName']", message: "Your account changed. Reopen the discard form." });
    if (!values.foodName) errors.push({ selector: "[name='discardFoodName']", message: "Enter or select the food that was discarded." });
    if (!Object.values(DISCARDED_FOOD_TYPES).includes(values.foodType)) errors.push({ selector: "[name='discardFoodType']", message: "Choose a food type." });
    if (!Object.values(DISCARD_REASON_CODES).includes(values.reasonCode)) errors.push({ selector: "[name='discardReason']", message: "Choose a reason or select I am not sure." });
    const timestamp = resolveDiscardTimestamp(values.date, values.timeUnknown ? "" : values.time, values.timeUnknown ? DISCARD_TIMESTAMP_PRECISION.DATE_ONLY : DISCARD_TIMESTAMP_PRECISION.EXACT_DATE_TIME);
    if (!timestamp) errors.push({ selector: "[name='discardDate']", message: "Enter a valid discard date." });
    else if (Date.parse(timestamp) > Date.now() + 60000) errors.push({ selector: "[name='discardDate']", message: "Discard time cannot be in the future." });
    const linkedItem = draft.source.inventoryItemId ? state.pantry.map(normalizePantryItem).find((item) => item.id === draft.source.inventoryItemId) : null;
    if (linkedItem && Number(linkedItem.revision || 0) !== Number(draft.sourceRevisions.inventoryRevision || 0)) errors.push({ selector: "[name='discardInventoryItemId']", message: "The Pantry amount changed. Reopen the discard form." });
    if (values.amountMode === DISCARD_AMOUNT_MODES.NUMERIC && estimate.canonicalQuantity === null) errors.push({ selector: "[name='discardAmount']", message: "Enter a positive amount." });
    if (values.amountMode === DISCARD_AMOUNT_MODES.NUMERIC && !normalizePantryUnit(values.unit)) errors.push({ selector: "[name='discardUnit']", message: "Enter a supported unit." });
    if (linkedItem && estimate.canonicalQuantity !== null) {
      const current = Number(draft.inventorySnapshot?.currentQuantity);
      const available = Number(draft.inventorySnapshot?.availableQuantity);
      if (Number.isFinite(current) && estimate.canonicalQuantity > current + 1e-6) errors.push({ selector: "[name='discardAmount']", message: "Discard amount cannot be greater than the recorded Pantry amount." });
      if (Number.isFinite(available) && estimate.canonicalQuantity > available + 1e-6) errors.push({ selector: "[name='discardAmount']", message: "This includes reserved food. Review the meal or discard only the unreserved amount." });
      if (isWholeCountUnit(draft.inventorySnapshot?.unit) && !Number.isInteger(estimate.canonicalQuantity)) errors.push({ selector: "[name='discardAmount']", message: "Whole-item amounts must be whole numbers." });
    }
    if (estimate.wholeItemReviewRequired) errors.push({ selector: "[name='discardAmountMode']", message: "Enter a whole-item amount or choose Amount unknown." });
    const price = parseMoneyToCents(values.priceAmount, { requirePositive: true });
    if (values.priceMode !== "none" && values.priceAmount && !price.valid) errors.push({ selector: "[name='discardPriceAmount']", message: "Enter a valid price or leave it blank." });
    return { valid: errors.length === 0, errors, timestamp };
  }

  function renderDiscardEstimatePreview(draft, values, estimate) {
    const linked = Boolean(draft.source.inventoryItemId);
    const currentLine = linked ? `<p><b>Current recorded amount:</b> ${draft.inventorySnapshot?.currentQuantity === null ? "Needs review" : `${formatQuantityForDisplay(draft.inventorySnapshot.currentQuantity)} ${draft.inventorySnapshot.unit || ""}`}</p>` : "";
    const basisLine = `<p><b>Estimate basis:</b> ${escapeHtml(discardEstimateBasisLabel(estimate.estimateBasis))}</p>`;
    const range = estimate.estimateMinimum !== null && estimate.estimateMaximum !== null && estimate.estimateMinimum !== estimate.estimateMaximum ? `<p><b>Estimate range:</b> Approximately ${formatQuantityForDisplay(estimate.estimateMinimum)}-${formatQuantityForDisplay(estimate.estimateMaximum)} ${escapeHtml(estimate.unit || "")}</p>` : "";
    const remaining = linked && estimate.canonicalQuantity !== null && draft.inventorySnapshot?.currentQuantity !== null ? `<p><b>Estimated amount remaining:</b> Approximately ${formatQuantityForDisplay(Math.max(0, roundFoodRescueNumber(draft.inventorySnapshot.currentQuantity - estimate.canonicalQuantity)))} ${escapeHtml(draft.inventorySnapshot.unit || "")}</p>` : linked && values.amountMode === DISCARD_AMOUNT_MODES.UNKNOWN ? `<p><b>Remaining amount:</b> Needs confirmation before automatic meal planning.</p>` : "";
    return `<div class="discard-estimate-preview" aria-live="polite">
      <p><b>You selected:</b> ${escapeHtml(discardAmountModeLabel(values.amountMode || DISCARD_AMOUNT_MODES.UNKNOWN))}</p>
      ${currentLine}
      <p><b>Chef Nova estimate:</b> ${escapeHtml(formatDiscardEstimateLine(estimate))}</p>
      ${basisLine}
      ${range}
      <p><b>Quantity confidence:</b> ${escapeHtml(quantityConfidenceLabel(estimate.quantityConfidence))}</p>
      ${remaining}
    </div>`;
  }

  function openRecordDiscardedFoodWorkflow(context = {}) {
    const draft = buildDiscardRecordingDraft(context);
    state.currentDiscardRecordingDraft = draft;
    renderDiscardRecordingForm(draft);
  }

  function renderDiscardRecordingForm(draft) {
    const pantryOptions = state.pantry.map(normalizePantryItem).filter((item) => item.lifecycle?.status !== PANTRY_LIFECYCLE_STATUSES.DISCARDED).map((item) => {
      const details = [formatPantryQuantityDetails(item), formatPackageStateLabel(item), formatStorageLocationLabel(item), getPrimaryDateLabelForItem(item), item.storage?.containerLabel ? `Container: ${item.storage.containerLabel}` : "", isPreparedLeftoverItem(item) && item.leftoverBatch?.source?.sourceMealId ? `Source meal: ${item.leftoverBatch.source.sourceMealId}` : "", item.preservation?.state === PANTRY_PRESERVATION_STATES.FROZEN ? "Frozen" : item.preservation?.state === PANTRY_PRESERVATION_STATES.THAWED ? "Thawed" : ""].filter(Boolean).join(" | ");
      return `<option value="${escapeHtml(item.id)}"${draft.source.inventoryItemId === item.id ? " selected" : ""}>${escapeHtml(item.displayName || item.name)} - ${escapeHtml(details)}</option>`;
    }).join("");
    const current = draft.inventorySnapshot;
    const snapshot = draft.linkedInventorySnapshot;
    const quickModel = buildDiscardQuickSuggestionModel(draft);
    const quickChoices = snapshot ? quickModel.suggestions.map((suggestion) => `<label><input type="radio" name="discardQuickSuggestion" value="${escapeHtml(suggestion.suggestionId)}"> ${escapeHtml(suggestion.label)} <span>(${escapeHtml(discardAmountModeLabel(suggestion.amountMode))} of current available amount)</span></label>`).join("") : "";
    const item = draft.source.inventoryItemId ? state.pantry.map(normalizePantryItem).find((candidate) => candidate.id === draft.source.inventoryItemId) : null;
    const currentSummary = snapshot ? `<div class="discard-linked-summary" aria-label="Selected Pantry item details">
      <h3>${escapeHtml(draft.food.displayName || "Selected Pantry item")}</h3>
      <p><b>Original package:</b> ${escapeHtml(formatOriginalPackageLabel(snapshot))}</p>
      <p><b>Recorded remaining amount:</b> ${snapshot.currentQuantity === null ? "Unknown" : `${formatQuantityForDisplay(snapshot.currentQuantity)} ${escapeHtml(snapshot.unit || "")}`}</p>
      <p><b>Reserved:</b> ${formatQuantityForDisplay(snapshot.activeReservedQuantity || 0)} ${escapeHtml(snapshot.unit || "")}</p>
      <p><b>Available without changing another plan:</b> ${snapshot.unreservedQuantity === null ? "Needs review" : `${formatQuantityForDisplay(snapshot.unreservedQuantity)} ${escapeHtml(snapshot.unit || "")}`}</p>
      <p><b>Current storage:</b> ${escapeHtml(item ? formatStorageLocationLabel(item) : pantryLabelFor(snapshot.storage?.location))}</p>
      <p><b>Package state:</b> ${escapeHtml(item ? formatPackageStateLabel(item) : pantryLabelFor(snapshot.storage?.packageState))}</p>
      <p><b>Date:</b> ${escapeHtml(item ? getPrimaryDateLabelForItem(item) : "Date not recorded")}</p>
      <p><b>Price basis:</b> ${snapshot.purchasePrice?.amountCents ? `Price paid for this package (${escapeHtml(formatCurrencyFromCents(snapshot.purchasePrice.amountCents))})` : "Price not recorded"}</p>
      ${snapshot.activeReservedQuantity > 0 ? `<p class="discard-neutral-note">Quick choices use only the unreserved amount. Use Enter another amount if the physical discard affected reserved food, then review the meal.</p>` : ""}
    </div>` : "";
    renderMealPlanGenerationModal(`<section class="discard-recording-modal" aria-labelledby="discardRecordingTitle">
      <div class="meal-generation-heading"><span class="eyebrow">RECORD DISCARDED FOOD</span><h2 id="discardRecordingTitle">Record Discarded Food</h2><p>Approximate information is okay.</p></div>
      <form id="discardRecordingForm" novalidate>
        <label>What was discarded?
          <select name="discardInventoryItemId" data-discard-selected-item>
            <option value="">This food was not recorded in Pantry</option>
            ${pantryOptions}
          </select>
        </label>
        <label>Food name<input type="text" name="discardFoodName" value="${escapeHtml(draft.food.displayName || "")}" placeholder="Search Pantry or enter a food name"></label>
        ${currentSummary}
        <fieldset><legend>Type</legend>
          ${Object.values(DISCARDED_FOOD_TYPES).map((type) => `<label><input type="radio" name="discardFoodType" value="${type}"${draft.food.foodType === type ? " checked" : ""}> ${escapeHtml(discardFoodTypeLabel(type))}</label>`).join("")}
        </fieldset>
        ${snapshot ? `<fieldset><legend>How much was discarded?</legend>
          ${quickChoices || `<p>Recorded remaining amount is unknown. Numeric quick suggestions are unavailable.</p>`}
          <label><input type="radio" name="discardQuickSuggestion" value="custom"> Enter another amount</label>
          <label><input type="radio" name="discardQuickSuggestion" value="unknown" checked> Amount unknown</label>
        </fieldset>` : `<fieldset><legend>How much was discarded?</legend>
          ${Object.values(DISCARD_AMOUNT_MODES).map((mode, index) => `<label><input type="radio" name="discardAmountMode" value="${mode}"${index === 6 ? " checked" : ""}> ${escapeHtml(discardAmountModeLabel(mode))}</label>`).join("")}
        </fieldset>`}
        <div class="discard-quantity-row"><label>Amount<input type="number" min="0" step="0.001" name="discardAmount" placeholder="100"></label><label>Unit<input type="text" name="discardUnit" value="${escapeHtml(current?.unit || "")}" placeholder="g"></label></div>
        <div class="discard-quantity-row"><label>Package size, optional<input type="number" min="0" step="0.001" name="discardPackageQuantity" placeholder="500"></label><label>Package unit<input type="text" name="discardPackageUnit" value="${escapeHtml(current?.originalPackageUnit || current?.unit || "")}" placeholder="g"></label></div>
        <fieldset><legend>Reason</legend>
          ${Object.values(DISCARD_REASON_CODES).map((reason) => `<label><input type="radio" name="discardReason" value="${reason}"${reason === DISCARD_REASON_CODES.UNKNOWN ? " checked" : ""}> ${escapeHtml(discardReasonLabel(reason))}</label>`).join("")}
        </fieldset>
        <label>Other reason, optional<input type="text" name="discardOtherReason" maxlength="120" placeholder="Optional"></label>
        <fieldset><legend>Optional price information</legend>
          <label><input type="radio" name="discardPriceMode" value="none" checked> No price recorded</label>
          <label><input type="radio" name="discardPriceMode" value="purchase"> Price paid for the full item or package</label>
          <label><input type="radio" name="discardPriceMode" value="discarded-value"> Estimated value of the discarded portion</label>
          <label>Amount<input type="text" name="discardPriceAmount" inputmode="decimal" placeholder="$4.49"></label>
        </fieldset>
        <label>Optional note<textarea name="discardNote" maxlength="500" placeholder="Optional note"></textarea></label>
        <div class="discard-quantity-row"><label>Discarded on<input type="date" name="discardDate" value="${escapeHtml(draft.discardedTime.date)}"></label><label>Time<input type="time" name="discardTime" value="${escapeHtml(draft.discardedTime.time)}"></label></div>
        <label class="checkbox-line"><input type="checkbox" name="discardTimeUnknown"> Time unknown</label>
        <fieldset><legend>If amount is unknown for a linked item, does any food remain?</legend>
          <label><input type="radio" name="discardRemainingKnown" value="yes"> Yes</label>
          <label><input type="radio" name="discardRemainingKnown" value="no"> No, all of it was discarded</label>
          <label><input type="radio" name="discardRemainingKnown" value="unknown" checked> I am not sure</label>
        </fieldset>
        <div id="discardEstimatePreview">${renderDiscardEstimatePreview(draft, { amountMode: DISCARD_AMOUNT_MODES.UNKNOWN }, deriveDiscardEstimate(draft, { amountMode: DISCARD_AMOUNT_MODES.UNKNOWN }))}</div>
        <p class="form-error" id="discardRecordingError" role="alert"></p>
        <div class="meal-generation-actions"><button class="button primary" type="button" data-discard-review-record>Review Discard Record</button><button class="button secondary" type="button" data-cancel-generated-plan>Cancel</button></div>
      </form>
    </section>`);
  }

  function updateDiscardEstimatePreview() {
    if (!state.currentDiscardRecordingDraft || !$("#discardRecordingForm")) return;
    const { draft, values, estimate } = readDiscardRecordingForm(state.currentDiscardRecordingDraft);
    state.currentDiscardRecordingDraft = draft;
    const target = $("#discardEstimatePreview");
    if (target) target.innerHTML = renderDiscardEstimatePreview(draft, values, estimate);
  }

  function reviewDiscardRecording() {
    const read = readDiscardRecordingForm(state.currentDiscardRecordingDraft);
    state.currentDiscardRecordingDraft = read.draft;
    const validation = validateDiscardRecording(read.draft, read.values, read.estimate);
    const error = $("#discardRecordingError");
    if (!validation.valid) {
      const first = validation.errors[0];
      if (error) error.textContent = first.message;
      $("#discardRecordingForm")?.querySelector(first.selector)?.focus();
      return false;
    }
    renderDiscardReview(read.draft, read.values, read.estimate, validation.timestamp);
    return true;
  }

  function discardPriceConfidenceLabel(value) {
    return pantryLabelFor(value, { "confirmed-price": "Confirmed price", "user-entered-estimate": "User-entered estimate", "saved-store-estimate": "Saved store estimate", "chef-nova-estimate": "Chef Nova estimate", "price-unavailable": "Price unavailable" });
  }

  function discardCostConfidenceLabel(value) {
    return pantryLabelFor(value, { high: "High", moderate: "Moderate", low: "Low", unavailable: "Unavailable" });
  }

  function discardPriceSourceLabel(value) {
    return pantryLabelFor(value, { "exact-lot-purchase-price": "Exact lot purchase price", "user-confirmed-package-price": "Price paid for full package", "user-entered-approximate-price": "Approximate package price", "exact-product-store-price": "Exact product store price", "saved-store-profile-price": "Saved store estimate", "chef-nova-estimate": "Chef Nova estimate", "prepared-batch-cost": "Prepared batch cost", "recipe-cost-snapshot": "Recipe cost snapshot", "transformed-batch-cost": "Transformed batch cost", "user-entered-discarded-value": "Estimated discarded portion value", "price-unavailable": "Price unavailable" });
  }

