        return createFoodSafetyResult({ decision: FOOD_SAFETY_DECISIONS.EXCLUDED_REHEATED_LEFTOVER, hardExclusion: true, canUseForAutomaticPlanning: false, canUseForDateDrivenRescueRanking: false, canRecommendFreezing: false, canRecommendTransformation: false, primaryReasonCode: FOOD_SAFETY_REASON_CODES.REHEATED_LEFTOVER_REUSE, policyId: policy.policyId, policyVersion: policy.policyVersion, leftoverTimeline, userMessage: "Reheating does not restart the original storage timeline. Uneaten reheated leftovers are not returned to reusable inventory." });
