      if (!locationMatches) {
        return createFoodSafetyResult({ decision: FOOD_SAFETY_DECISIONS.REVIEW_REQUIRED, canUseForAutomaticPlanning: false, primaryReasonCode: FOOD_SAFETY_REASON_CODES.STORAGE_LOCATION_MISMATCH, policyId: policy.policyId, policyVersion: policy.policyVersion, userMessage: "The current storage location does not match the available food-specific guidance." });
      }
      const appliance = item.storage?.location === PANTRY_STORAGE_LOCATIONS.FREEZER ? environment.freezer : environment.refrigerator;
      const threshold = item.storage?.location === PANTRY_STORAGE_LOCATIONS.FREEZER ? FOOD_STORAGE_TEMPERATURES_C.FREEZER_MAX : FOOD_STORAGE_TEMPERATURES_C.REFRIGERATOR_MAX;
      if (appliance?.temperatureC !== null && appliance.temperatureC > threshold) {
        return createFoodSafetyResult({ decision: FOOD_SAFETY_DECISIONS.EXCLUDED_TEMPERATURE, hardExclusion: true, primaryReasonCode: FOOD_SAFETY_REASON_CODES.TEMPERATURE_OUTSIDE_GUIDANCE, policyId: policy.policyId, policyVersion: policy.policyVersion, storageAssessment: { applianceTemperatureC: appliance.temperatureC, thresholdC: threshold }, userMessage: "The recorded appliance temperature is outside the reviewed guidance for this storage location." });
      }
      const reviewReasons = [];
      if (appliance?.temperatureC === null && review.temperatureCondition === STORAGE_TEMPERATURE_STATUSES.UNKNOWN) reviewReasons.push(FOOD_SAFETY_REASON_CODES.STORAGE_CONDITIONS_UNKNOWN);
      if (review.continuousStorageStatus !== CONTINUOUS_STORAGE_STATUSES.CONFIRMED) reviewReasons.push(FOOD_SAFETY_REASON_CODES.STORAGE_CONDITIONS_UNKNOWN);
      if (policy.roomTemperatureExposure?.behaviorWhenUnknown === "review-required" && review.exposureStatus === STORAGE_EXPOSURE_STATUSES.UNKNOWN) reviewReasons.push(FOOD_SAFETY_REASON_CODES.ROOM_TEMPERATURE_EXPOSURE_UNKNOWN);
      const anchorType = policy.refrigeratorWindow?.anchorEvent;
      const anchorRecord = anchorType ? getPantryDateRecord(item, anchorType) : null;
      if (anchorType && !anchorRecord) reviewReasons.push(anchorType === FOOD_SAFETY_WINDOW_ANCHORS.OPENED_ON ? FOOD_SAFETY_REASON_CODES.OPENING_DATE_NEEDED : anchorType === FOOD_SAFETY_WINDOW_ANCHORS.COOKED_ON ? FOOD_SAFETY_REASON_CODES.COOKED_DATE_NEEDED : FOOD_SAFETY_REASON_CODES.STORAGE_CONDITIONS_UNKNOWN);
      if (item.preservation?.state === PANTRY_PRESERVATION_STATES.THAWED && !item.preservation?.thawedAt) reviewReasons.push(FOOD_SAFETY_REASON_CODES.THAW_HISTORY_NEEDED);
      if (reviewReasons.length) {
        return createFoodSafetyResult({ decision: FOOD_SAFETY_DECISIONS.REVIEW_REQUIRED, canUseForAutomaticPlanning: false, primaryReasonCode: reviewReasons[0], reasonCodes: Array.from(new Set(reviewReasons)), policyId: policy.policyId, policyVersion: policy.policyVersion, userMessage: "Chef Nova does not have enough information to use this item in an automatic food-rescue plan." });
      }
      const safetyWindow = anchorRecord && policy.refrigeratorWindow ? {
        anchorType,
        anchorAt: anchorRecord.dateValue,
        earliestReviewAt: addCalendarDays(anchorRecord.dateValue, Math.floor(policy.refrigeratorWindow.minimumDays || 0)),
        latestEligibleUseAt: addCalendarDays(anchorRecord.dateValue, Math.floor(policy.refrigeratorWindow.maximumDays || 0)),
        basis: "safety"
      } : leftoverTimeline?.effectiveSafetyDeadline ? {
        anchorType: FOOD_SAFETY_WINDOW_ANCHORS.COOKED_ON,
        anchorAt: leftoverTimeline.originalCookedAt,
        earliestReviewAt: null,
        latestEligibleUseAt: leftoverTimeline.effectiveSafetyDeadline,
        basis: "original-leftover-timeline"
      } : null;
      if (safetyWindow) {
        const elapsedDays = calendarDayDifference(anchorRecord.dateValue, referenceDate);
        if (elapsedDays > Number(policy.refrigeratorWindow.maximumDays)) {
          return createFoodSafetyResult({ decision: FOOD_SAFETY_DECISIONS.EXCLUDED_STORAGE_TIME, hardExclusion: true, primaryReasonCode: FOOD_SAFETY_REASON_CODES.REFRIGERATION_MAXIMUM_PASSED, policyId: policy.policyId, policyVersion: policy.policyVersion, safetyWindow, leftoverTimeline, userMessage: "The recorded storage history is outside the reviewed safety window." });
        }
        if (elapsedDays >= Number(policy.refrigeratorWindow.minimumDays) && Number(policy.refrigeratorWindow.maximumDays) > Number(policy.refrigeratorWindow.minimumDays)) {
          return createFoodSafetyResult({ decision: FOOD_SAFETY_DECISIONS.ELIGIBLE_WITH_CONDITIONS, canUseForAutomaticPlanning: true, requiresUserReview: true, primaryReasonCode: FOOD_SAFETY_REASON_CODES.ELIGIBLE_WITH_STORAGE_CONFIRMATION, policyId: policy.policyId, policyVersion: policy.policyVersion, safetyWindow, leftoverTimeline, canRecommendFreezing: leftoverTimeline ? leftoverTimeline.canRecommendFreezing : policy.freezerWindow?.freezeSupport === "supported" && item.preservation?.state !== PANTRY_PRESERVATION_STATES.FROZEN, userMessage: "The item is within the later part of the reviewed storage range. Review before planning." });
        }
      }
      const qualityReason = dateResult.status === FOOD_DATE_ATTENTION_STATUSES.BEST_BEFORE_PASSED ? FOOD_SAFETY_REASON_CODES.BEST_BEFORE_QUALITY_REVIEW : item.storage?.location === PANTRY_STORAGE_LOCATIONS.FREEZER ? FOOD_SAFETY_REASON_CODES.FREEZER_QUALITY_REVIEW : null;
      return createFoodSafetyResult({ decision: qualityReason ? FOOD_SAFETY_DECISIONS.ELIGIBLE_WITH_CONDITIONS : FOOD_SAFETY_DECISIONS.ELIGIBLE, canUseForAutomaticPlanning: true, requiresUserReview: Boolean(qualityReason), primaryReasonCode: qualityReason || FOOD_SAFETY_REASON_CODES.ELIGIBLE_FOR_PLANNING, policyId: policy.policyId, policyVersion: policy.policyVersion, safetyWindow, leftoverTimeline, qualityWindow: policy.freezerWindow || null, canRecommendFreezing: leftoverTimeline ? leftoverTimeline.canRecommendFreezing : policy.freezerWindow?.freezeSupport === "supported" && item.preservation?.state !== PANTRY_PRESERVATION_STATES.FROZEN, canRecommendTransformation: [PANTRY_ITEM_FORMS.COOKED, PANTRY_ITEM_FORMS.PREPARED].includes(item.form) && !foodLineage?.invalid, userMessage: qualityReason ? "A quality-related date changed. Chef Nova still keeps safety checks separate from quality guidance." : "The recorded storage and date information matches the reviewed policy used by Chef Nova. This is not a guarantee of food safety." });
